  "src/api/adminCancelBarter.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Admin membatalkan transaksi barter',
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    await zite.barterHistory.update({
      id: input.barterId,
      record: { status: 'Dibatalkan' },
    });
    return { success: true };
  },
});
