  "src/api/banUser.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Ban atau unban pengguna',
  inputSchema: z.object({
    userId: z.string(),
    action: z.enum(['ban', 'unban']),
    reason: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    // Find user profile by user id
    const { records } = await zite.userProfiles.findAll({
      filters: { user: input.userId },
      limit: 1,
    });

    if (records.length === 0) {
      // Create profile if not exists
      await zite.userProfiles.create({
        record: {
          user: input.userId,
          displayName: null,
          banned: input.action === 'ban',
          bannedReason: input.action === 'ban' ? (input.reason ?? 'Pelanggaran berulang') : null,
        },
      });
    } else {
      await zite.userProfiles.update({
        id: records[0].id,
        record: {
          banned: input.action === 'ban',
          bannedReason: input.action === 'ban' ? (input.reason ?? 'Pelanggaran berulang') : null,
        },
      });
    }

    return { success: true };
  },
});
