  "src/api/getAdminReviews.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil daftar review barter untuk admin',
  inputSchema: z.object({
    ratingFilter: z.number().optional(),
    search: z.string().optional(),
    offset: z.number().default(0),
    limit: z.number().default(20),
  }),
  outputSchema: z.object({
    reviews: z.array(z.any()),
    total: z.number(),
    hasMore: z.boolean(),
    stats: z.object({
      totalReviews: z.number(),
      averageRating: z.number(),
      ratingDistribution: z.array(z.object({ rating: z.number(), count: z.number() })),
    }),
  }),
  execute: async ({ input }) => {
    const { ratingFilter, search, offset, limit } = input;
    const params: unknown[] = [];
    const conditions: string[] = [];

    if (ratingFilter) {
      params.push(ratingFilter);
      conditions.push(`r."rating" = $${params.length}`);
    }
    if (search) {
      params.push(`%${search}%`);
      conditions.push(`(r."comment" ILIKE $${params.length} OR reviewer."name" ILIKE $${params.length} OR reviewee."name" ILIKE $${params.length})`);
    }

    const baseFrom = `
      FROM "BarterReviews" r
      LEFT JOIN "ziteUsers" reviewer ON reviewer.id = r."reviewer"->>0
      LEFT JOIN "ziteUsers" reviewee ON reviewee.id = r."reviewee"->>0
      LEFT JOIN "BarterHistoryBarterReviews" br ON br."barterReviewsId" = r.id
      LEFT JOIN "BarterHistory" bh ON bh.id = br."barterHistoryId"
    `;
    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

    const countRes = await zite.sql({
      query: `SELECT COUNT(*) AS cnt ${baseFrom} ${where}`,
      params,
    });

    // Stats query (always unfiltered)
    const statsRes = await zite.sql({
      query: `
        SELECT 
          COUNT(*) AS "totalReviews",
          COALESCE(AVG(r."rating"), 0) AS "averageRating"
        FROM "BarterReviews" r
      `,
    });

    const distRes = await zite.sql({
      query: `
        SELECT r."rating" AS rating, COUNT(*) AS cnt
        FROM "BarterReviews" r
        WHERE r."rating" IS NOT NULL
        GROUP BY r."rating"
        ORDER BY r."rating" DESC
      `,
    });

    params.push(limit, offset);
    const res = await zite.sql({
      query: `
        SELECT r.id, r."rating", r."comment", r."aspect", r.created_at AS "createdAt",
          reviewer."name" AS "reviewerName", reviewer."email" AS "reviewerEmail",
          reviewee."name" AS "revieweeName",
          bh."title" AS "barterTitle"
        ${baseFrom} ${where}
        ORDER BY r.created_at DESC
        LIMIT $${params.length - 1} OFFSET $${params.length}
      `,
      params,
    });

    const total = Number(countRes.rows[0]?.cnt ?? 0);
    return {
      reviews: res.rows.map(r => ({
        id: String(r.id),
        rating: Number(r.rating ?? 0),
        comment: r.comment ? String(r.comment) : null,
        aspect: r.aspect ? String(r.aspect) : null,
        createdAt: r.createdAt ? String(r.createdAt) : null,
        reviewerName: String(r.reviewerName ?? 'Unknown'),
        reviewerEmail: String(r.reviewerEmail ?? ''),
        revieweeName: String(r.revieweeName ?? 'Unknown'),
        barterTitle: r.barterTitle ? String(r.barterTitle) : null,
      })),
      total,
      hasMore: offset + limit < total,
      stats: {
        totalReviews: Number(statsRes.rows[0]?.totalReviews ?? 0),
        averageRating: Math.round(Number(statsRes.rows[0]?.averageRating ?? 0) * 10) / 10,
        ratingDistribution: [1, 2, 3, 4, 5].map(rating => ({
          rating,
          count: Number(distRes.rows.find(r => Number(r.rating) === rating)?.cnt ?? 0),
        })),
      },
    };
  },
});
