  "src/api/getLeaderboard.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil leaderboard poin user untuk admin',
  inputSchema: z.object({
    offset: z.number().default(0),
    limit: z.number().default(30),
  }),
  outputSchema: z.object({
    leaderboard: z.array(z.object({
      rank: z.number(),
      userId: z.string(),
      userName: z.string(),
      userEmail: z.string(),
      userImage: z.string().nullable(),
      totalPoints: z.number(),
      itemsUploaded: z.number(),
      bartersCompleted: z.number(),
      likesReceived: z.number(),
      currentBadge: z.string(),
    })),
    total: z.number(),
    hasMore: z.boolean(),
    badgeDistribution: z.array(z.object({ badge: z.string(), count: z.number() })),
    topStats: z.object({
      totalPoints: z.number(),
      avgPoints: z.number(),
      totalBarters: z.number(),
    }),
  }),
  execute: async ({ input }) => {
    const { offset, limit } = input;

    const countRes = await zite.sql({
      query: 'SELECT COUNT(*) AS cnt FROM "UserPoints"',
    });
    const total = Number(countRes.rows[0]?.cnt ?? 0);

    const res = await zite.sql({
      query: `
        SELECT p.id, p."totalPoints", p."itemsUploaded", p."bartersCompleted",
          p."likesReceived", p."currentBadge",
          u.id AS "userId", u."name" AS "userName", u."email" AS "userEmail", u."image" AS "userImage"
        FROM "UserPoints" p
        LEFT JOIN "ziteUsers" u ON u.id = p."user"->>0
        ORDER BY p."totalPoints" DESC NULLS LAST
        LIMIT $1 OFFSET $2
      `,
      params: [limit, offset],
    });

    const badgeRes = await zite.sql({
      query: `
        SELECT COALESCE("currentBadge", 'Tanpa Badge') AS badge, COUNT(*) AS cnt
        FROM "UserPoints"
        GROUP BY 1 ORDER BY cnt DESC
      `,
    });

    const statsRes = await zite.sql({
      query: `
        SELECT COALESCE(SUM("totalPoints"), 0) AS "totalPts",
          COALESCE(AVG("totalPoints"), 0) AS "avgPts",
          COALESCE(SUM("bartersCompleted"), 0) AS "totalBarters"
        FROM "UserPoints"
      `,
    });

    return {
      leaderboard: res.rows.map((r, i) => ({
        rank: offset + i + 1,
        userId: String(r.userId ?? ''),
        userName: String(r.userName ?? 'Unknown'),
        userEmail: String(r.userEmail ?? ''),
        userImage: r.userImage ? String(r.userImage) : null,
        totalPoints: Number(r.totalPoints ?? 0),
        itemsUploaded: Number(r.itemsUploaded ?? 0),
        bartersCompleted: Number(r.bartersCompleted ?? 0),
        likesReceived: Number(r.likesReceived ?? 0),
        currentBadge: String(r.currentBadge ?? ''),
      })),
      total,
      hasMore: offset + limit < total,
      badgeDistribution: badgeRes.rows.map(r => ({
        badge: String(r.badge),
        count: Number(r.cnt),
      })),
      topStats: {
        totalPoints: Number(statsRes.rows[0]?.totalPts ?? 0),
        avgPoints: Math.round(Number(statsRes.rows[0]?.avgPts ?? 0)),
        totalBarters: Number(statsRes.rows[0]?.totalBarters ?? 0),
      },
    };
  },
});
",
  "src/api/getUserDetail.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil detail lengkap seorang user untuk admin',
  inputSchema: z.object({ userId: z.string() }),
  outputSchema: z.object({
    user: z.any(),
    profile: z.any().nullable(),
    points: z.any().nullable(),
    items: z.array(z.any()),
    barters: z.array(z.any()),
    violations: z.array(z.any()),
    reviews: z.array(z.any()),
    violationCount: z.number(),
  }),
  execute: async ({ input }) => {
    const { userId } = input;

    // Get auth user
    const usersRes = await zite.auth.findAllUsers({
      filters: { id: userId },
      limit: 1,
    });
    const user = usersRes.records[0] ?? null;

    // Profile
    const profileRes = await zite.userProfiles.findAll({ filters: { user: userId }, limit: 1 });
    const profile = profileRes.records[0] ?? null;

    // Points
    const pointsRes = await zite.userPoints.findAll({ filters: { user: userId }, limit: 1 });
    const points = pointsRes.records[0] ?? null;

    // Items
    const itemsRes = await zite.sql({
      query: `
        SELECT id, "title", "status", "condition", "location", "viewsCount", "likesCount",
          created_at AS "createdAt"
        FROM "Items"
        WHERE "owner"->>0 = $1
        ORDER BY created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Barters (as initiator or partner)
    const bartersRes = await zite.sql({
      query: `
        SELECT b.id, b."title", b."status", b.created_at AS "createdAt", b."completedAt",
          u1."name" AS "initiatorName", u2."name" AS "partnerName"
        FROM "BarterHistory" b
        LEFT JOIN "ziteUsers" u1 ON u1.id = b."initiator"->>0
        LEFT JOIN "ziteUsers" u2 ON u2.id = b."partner"->>0
        WHERE b."initiator"->>0 = $1 OR b."partner"->>0 = $1
        ORDER BY b.created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Violations
    const violationsRes = await zite.sql({
      query: `
        SELECT id, "violationType", "severity", "minusPoints", "status", "notes",
          created_at AS "createdAt"
        FROM "Violations"
        WHERE "user"->>0 = $1
        ORDER BY created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Active violation count
    const countRes = await zite.sql({
      query: `SELECT COUNT(*) AS cnt FROM "Violations" WHERE "user"->>0 = $1 AND "status" = 'Aktif'`,
      params: [userId],
    });

    // Reviews received
    const reviewsRes = await zite.sql({
      query: `
        SELECT r."rating", r."comment", r."aspect", r.created_at AS "createdAt",
          u."name" AS "reviewerName"
        FROM "BarterReviews" r
        LEFT JOIN "ziteUsers" u ON u.id = r."reviewer"->>0
        WHERE r."reviewee"->>0 = $1
        ORDER BY r.created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    return {
      user: user ? {
        id: user.id,
        name: user.name,
        email: user.email,
        image: user.image,
      } : null,
      profile: profile ? {
        displayName: profile.displayName,
        phone: profile.phone,
        bio: profile.bio,
        city: profile.city,
        province: profile.province,
        address: profile.address,
        phoneVerified: profile.phoneVerified,
        banned: (profile as any).banned ?? false,
        bannedReason: (profile as any).bannedReason ?? null,
      } : null,
      points: points ? {
        totalPoints: points.totalPoints,
        itemsUploaded: points.itemsUploaded,
        bartersCompleted: points.bartersCompleted,
        likesReceived: points.likesReceived,
        currentBadge: points.currentBadge,
      } : null,
      items: itemsRes.rows.map(r => ({
        id: String(r.id), title: String(r.title ?? ''), status: String(r.status ?? ''),
        condition: String(r.condition ?? ''), location: String(r.location ?? ''),
        viewsCount: Number(r.viewsCount ?? 0), likesCount: Number(r.likesCount ?? 0),
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
      barters: bartersRes.rows.map(r => ({
        id: String(r.id), title: String(r.title ?? ''), status: String(r.status ?? ''),
        createdAt: r.createdAt ? String(r.createdAt) : null,
        completedAt: r.completedAt ? String(r.completedAt) : null,
        initiatorName: String(r.initiatorName ?? ''), partnerName: String(r.partnerName ?? ''),
      })),
      violations: violationsRes.rows.map(r => ({
        id: String(r.id), violationType: String(r.violationType ?? ''),
        severity: String(r.severity ?? ''), minusPoints: Number(r.minusPoints ?? 0),
        status: String(r.status ?? ''), notes: r.notes ? String(r.notes) : null,
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
      reviews: reviewsRes.rows.map(r => ({
        rating: Number(r.rating ?? 0), comment: r.comment ? String(r.comment) : null,
        aspect: r.aspect ? String(r.aspect) : null, createdAt: r.createdAt ? String(r.createdAt) : null,
        reviewerName: String(r.reviewerName ?? ''),
      })),
      violationCount: Number(countRes.rows[0]?.cnt ?? 0),
    };
  },
});
",
  "src/api/getViolationDetail.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil detail lengkap satu pelanggaran untuk admin',
  inputSchema: z.object({
    violationId: z.string(),
  }),
  outputSchema: z.object({
    violation: z.any(),
  }),
  execute: async ({ input }) => {
    const v = await zite.violations.findOne({ id: input.violationId });
    if (!v) throw new Error('Pelanggaran tidak ditemukan');

    // Get user info
    const userId = Array.isArray(v.user) ? v.user[0] : v.user;
    const reporterId = Array.isArray(v.reportedBy) ? v.reportedBy[0] : v.reportedBy;

    let userName = 'Unknown', userEmail = '', userImage: string | null = null;
    let reporterName = '', reporterEmail = '', reporterImage: string | null = null;

    if (userId) {
      const uRes = await zite.sql({
        query: 'SELECT "name", "email", "image" FROM "ziteUsers" WHERE id = $1',
        params: [userId],
      });
      if (uRes.rows[0]) {
        userName = String(uRes.rows[0].name ?? 'Unknown');
        userEmail = String(uRes.rows[0].email ?? '');
        userImage = uRes.rows[0].image ? String(uRes.rows[0].image) : null;
      }
    }

    if (reporterId) {
      const rRes = await zite.sql({
        query: 'SELECT "name", "email", "image" FROM "ziteUsers" WHERE id = $1',
        params: [reporterId],
      });
      if (rRes.rows[0]) {
        reporterName = String(rRes.rows[0].name ?? '');
        reporterEmail = String(rRes.rows[0].email ?? '');
        reporterImage = rRes.rows[0].image ? String(rRes.rows[0].image) : null;
      }
    }

    // Get linked barter info
    let barterTitle: string | null = null;
    let barterStatus: string | null = null;
    const barterId = Array.isArray(v.barter) ? v.barter[0] : v.barter;
    if (barterId) {
      const b = await zite.barterHistory.findOne({ id: barterId });
      if (b) {
        barterTitle = b.title ?? null;
        barterStatus = b.status ?? null;
      }
    }

    return {
      violation: {
        id: v.id,
        label: v.label ?? '',
        violationType: v.violationType ?? '',
        severity: v.severity ?? '',
        minusPoints: v.minusPoints ?? 0,
        status: v.status ?? '',
        notes: v.notes ?? null,
        createdAt: v.createdAt ?? null,
        evidence: (v.evidence ?? []).map((e: any) => ({
          url: e.url,
          filename: e.originalName || e.filename,
          mimeType: e.mimeType,
        })),
        userName,
        userEmail,
        userId: userId ?? null,
        userImage,
        reporterName,
        reporterEmail,
        reporterImage,
        barterTitle,
        barterStatus,
      },
    };
  },
});
",
