  "src/api/updateListingStatus.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengubah status listing (approve/reject/hapus)',
  inputSchema: z.object({
    itemId: z.string(),
    action: z.enum(['approve', 'reject', 'delete']),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    if (input.action === 'delete') {
      await zite.items.delete({ id: input.itemId });
    } else {
      const statusMap = { approve: 'Tersedia', reject: 'Dibatalkan' } as const;
      await zite.items.update({
        id: input.itemId,
        record: { status: statusMap[input.action] as string },
      });
    }
    return { success: true };
  },
});
