  "src/pages/AnalyticsPage.tsx": "import { useEffect, useState } from 'react';
import { getAnalytics } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Skeleton } from '@project/components/ui/skeleton';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer,
  LineChart, Line, PieChart, Pie, Cell,
} from 'recharts';

const COLORS = [
  'hsl(152 55% 36%)', 'hsl(199 70% 48%)', 'hsl(38 92% 50%)',
  'hsl(280 55% 55%)', 'hsl(350 70% 55%)', 'hsl(160 60% 45%)',
  'hsl(220 60% 55%)', 'hsl(30 80% 55%)',
];

type AnalyticsData = {
  bartersPerWeek: { week: string; count: number }[];
  listingsPerWeek: { week: string; count: number }[];
  listingsPerCategory: { category: string; count: number }[];
  barterCompletionRate: { status: string; count: number }[];
  topLocations: { location: string; count: number }[];
  userGrowth: { week: string; count: number }[];
};

export default function AnalyticsPage() {
  const [data, setData] = useState<AnalyticsData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getAnalytics({}).then(setData).finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="space-y-5">
        <h1 className="text-2xl font-bold">Analytics</h1>
        <div className="grid gap-4 lg:grid-cols-2">
          {[1, 2, 3, 4].map(i => <Skeleton key={i} className="h-72 rounded-xl" />)}
        </div>
      </div>
    );
  }

  if (!data) return null;

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-bold">Analytics</h1>

      <div className="grid gap-4 lg:grid-cols-2">
        {/* Barter per Minggu */}
        <ChartCard title="Tren Barter per Minggu">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data.bartersPerWeek}>
              <XAxis dataKey="week" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
              <Tooltip />
              <Bar dataKey="count" fill="hsl(152 55% 36%)" radius={[4, 4, 0, 0]} name="Barter" />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Listing per Minggu */}
        <ChartCard title="Tren Listing per Minggu">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={data.listingsPerWeek}>
              <XAxis dataKey="week" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
              <Tooltip />
              <Line type="monotone" dataKey="count" stroke="hsl(199 70% 48%)" strokeWidth={2} dot={{ r: 3 }} name="Listing" />
            </LineChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Listing per Kategori */}
        <ChartCard title="Listing per Kategori">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data.listingsPerCategory} layout="vertical">
              <XAxis type="number" tick={{ fontSize: 11 }} allowDecimals={false} />
              <YAxis type="category" dataKey="category" tick={{ fontSize: 11 }} width={100} />
              <Tooltip />
              <Bar dataKey="count" fill="hsl(280 55% 55%)" radius={[0, 4, 4, 0]} name="Listing" />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Status Barter */}
        <ChartCard title="Status Barter">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={data.barterCompletionRate}
                dataKey="count"
                nameKey="status"
                cx="50%"
                cy="50%"
                outerRadius={85}
                label={({ status, count }) => `${status} (${count})`}
              >
                {data.barterCompletionRate.map((_, i) => (
                  <Cell key={i} fill={COLORS[i % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>

        {/* Top Lokasi */}
        <ChartCard title="Top Lokasi Listing">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data.topLocations} layout="vertical">
              <XAxis type="number" tick={{ fontSize: 11 }} allowDecimals={false} />
              <YAxis type="category" dataKey="location" tick={{ fontSize: 11 }} width={120} />
              <Tooltip />
              <Bar dataKey="count" fill="hsl(38 92% 50%)" radius={[0, 4, 4, 0]} name="Listing" />
            </BarChart>
