    setLoading(true);
    try {
      const res = await getAdminBarters({ search: s || undefined, status: st || undefined, offset: p * limit, limit });
      setBarters(res.barters as Barter[]);
      setTotal(res.total);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(search, statusFilter, page); }, [page, statusFilter]);

  const debouncedSearch = useDebouncedCallback((val: string) => { setPage(0); fetchData(val, statusFilter, 0); }, 400);

  const handleCancel = async (id: string) => {
    try {
      await adminCancelBarter({ barterId: id });
      toast.success('Barter dibatalkan');
      fetchData(search, statusFilter, page);
