  "src/pages/BroadcastPage.tsx": "import { useState } from 'react';
import { broadcastNotification } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Textarea } from '@project/components/ui/textarea';
import { Label } from '@project/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@project/components/ui/radio-group';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { Send, Megaphone } from 'lucide-react';
import { toast } from 'sonner';

const SPLIT_RE = /[,\n]+/;

function parseEmails(raw: string) {
  return raw.split(SPLIT_RE).map(e => e.trim()).filter(Boolean);
}

export default function BroadcastPage() {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [targetType, setTargetType] = useState<'all' | 'specific'>('all');
  const [emails, setEmails] = useState('');
  const [sending, setSending] = useState(false);
  const [lastResult, setLastResult] = useState<{ sent: number } | null>(null);

  const emailList = parseEmails(emails);
  const canSend = title.trim().length > 0 && body.trim().length > 0 &&
    (targetType === 'all' || emailList.length > 0);

  const handleSend = async () => {
    setSending(true);
    try {
      const targetEmails = targetType === 'specific' ? emailList : undefined;
      const res = await broadcastNotification({ title, body, targetType, targetEmails });
      setLastResult({ sent: res.sent });
      toast.success('Notifikasi berhasil dikirim ke ' + res.sent + ' user');
      setTitle('');
      setBody('');
      setEmails('');
    } catch {
      toast.error('Gagal mengirim notifikasi');
    } finally {
      setSending(false);
    }
  };

  const targetLabel = targetType === 'all' ? 'semua user' : emailList.length + ' email';

  return (
    <div className="space-y-5 max-w-2xl">
      <h1 className="text-2xl font-bold">Broadcast Notifikasi</h1>

      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Megaphone size={18} /> Kirim Notifikasi Sistem
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="bc-title">Judul Notifikasi</Label>
            <Input
              id="bc-title"
              placeholder="Contoh: Update Fitur Baru!"
              value={title}
              onChange={e => setTitle(e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="bc-body">Isi Pesan</Label>
            <Textarea
              id="bc-body"
              placeholder="Tulis pesan notifikasi di sini..."
              rows={4}
              value={body}
              onChange={e => setBody(e.target.value)}
            />
          </div>

          <div className="space-y-3">
            <Label>Target Penerima</Label>
            <RadioGroup value={targetType} onValueChange={v => setTargetType(v as 'all' | 'specific')}>
              <div className="flex items-center gap-2">
                <RadioGroupItem value="all" id="target-all" />
                <Label htmlFor="target-all" className="font-normal cursor-pointer">Semua User</Label>
              </div>
              <div className="flex items-center gap-2">
                <RadioGroupItem value="specific" id="target-specific" />
                <Label htmlFor="target-specific" className="font-normal cursor-pointer">User Tertentu (berdasarkan email)</Label>
              </div>
            </RadioGroup>
          </div>

          {targetType === 'specific' && (
            <div className="space-y-2">
              <Label htmlFor="bc-emails">Email Penerima</Label>
              <Textarea
                id="bc-emails"
                placeholder={'Masukkan email, pisahkan dengan koma atau enter\ncontoh: user1@email.com, user2@email.com'}
                rows={3}
                value={emails}
                onChange={e => setEmails(e.target.value)}
              />
              <p className="text-xs text-muted-foreground">
                {emailList.length} email terdeteksi
              </p>
            </div>
          )}

          {/* Preview */}
          {title && (
            <Card className="bg-muted/50">
              <CardContent className="p-4">
                <p className="text-xs text-muted-foreground mb-1">Preview:</p>
                <p className="font-semibold text-sm">{title}</p>
                <p className="text-sm text-muted-foreground mt-0.5">{body}</p>
                <p className="text-xs text-muted-foreground mt-2">
                  Target: {targetLabel}
                </p>
              </CardContent>
            </Card>
          )}

          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button disabled={!canSend || sending} className="w-full">
                <Send size={16} className="mr-1.5" />
                {sending ? 'Mengirim...' : 'Kirim Notifikasi'}
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>Kirim Notifikasi?</AlertDialogTitle>
                <AlertDialogDescription>
                  {'Notifikasi "' + title + '" akan dikirim ke ' + targetLabel + '. Tindakan ini tidak bisa dibatalkan.'}
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Batal</AlertDialogCancel>
                <AlertDialogAction onClick={handleSend}>Ya, Kirim</AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>

          {lastResult && (
            <div className="rounded-lg bg-emerald-50 border border-emerald-200 p-3 text-center">
              <p className="text-sm text-emerald-700 font-medium">
                {'✅ Terkirim ke ' + lastResult.sent + ' user'}
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
