  "src/pages/CommentsPage.tsx": "import { useEffect, useState, useCallback } from 'react';
import { getAdminComments, deleteComment } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Skeleton } from '@project/components/ui/skeleton';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { ChevronLeft, ChevronRight, MessageCircle, Trash2, Search } from 'lucide-react';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { toast } from 'sonner';
import { useDebouncedCallback } from 'use-debounce';

type Comment = {
  id: string;
  content: string;
  createdAt: string | null;
  authorName: string;
  authorEmail: string;
  itemTitle: string;
  itemId: string | null;
};

export default function CommentsPage() {
  const [comments, setComments] = useState<Comment[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const limit = 20;

  const fetchData = useCallback(async (s: string, p: number) => {
    setLoading(true);
    try {
      const res = await getAdminComments({ search: s || undefined, offset: p * limit, limit });
      setComments(res.comments as Comment[]);
      setTotal(res.total);
    } finally {
      setLoading(false);
    }
  }, []);

  const debouncedSearch = useDebouncedCallback((val: string) => {
    setPage(0);
    fetchData(val, 0);
  }, 400);

  useEffect(() => { fetchData(search, page); }, [page]);

  const handleDelete = async (id: string) => {
    try {
      await deleteComment({ commentId: id });
      toast.success('Komentar berhasil dihapus');
      fetchData(search, page);
    } catch {
      toast.error('Gagal menghapus komentar');
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / limit));

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <h1 className="text-2xl font-bold">Moderasi Komentar</h1>
        <p className="text-sm text-muted-foreground">{total} komentar total</p>
      </div>

      <div className="relative max-w-sm">
        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Cari komentar, user, atau listing..."
          className="pl-9"
          value={search}
          onChange={(e) => { setSearch(e.target.value); debouncedSearch(e.target.value); }}
        />
      </div>

      {loading ? (
        <div className="space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-20 rounded-xl" />)}</div>
      ) : comments.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Tidak ada komentar ditemukan</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {comments.map((c) => (
            <Card key={c.id}>
              <CardContent className="flex items-start gap-3 p-4">
                <div className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-blue-100 text-blue-600">
                  <MessageCircle size={18} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="text-sm font-semibold">{c.authorName}</p>
                    <span className="text-xs text-muted-foreground">{c.authorEmail}</span>
                  </div>
                  {c.itemTitle && (
                    <p className="text-xs text-muted-foreground mt-0.5">
                      pada listing: <span className="font-medium text-foreground">{c.itemTitle}</span>
                    </p>
                  )}
                  <p className="mt-1.5 text-sm text-foreground leading-relaxed">{c.content}</p>
                  {c.createdAt && (
                    <p className="text-xs text-muted-foreground mt-1.5">
                      {format(new Date(c.createdAt), 'dd MMM yyyy, HH:mm', { locale: idLocale })}
                    </p>
                  )}
                </div>
                <AlertDialog>
                  <AlertDialogTrigger asChild>
                    <Button variant="ghost" size="icon" className="shrink-0 text-muted-foreground hover:text-destructive">
                      <Trash2 size={16} />
                    </Button>
                  </AlertDialogTrigger>
                  <AlertDialogContent>
                    <AlertDialogHeader>
                      <AlertDialogTitle>Hapus komentar?</AlertDialogTitle>
                      <AlertDialogDescription>
                        Komentar dari {c.authorName} akan dihapus permanen. Tindakan ini tidak bisa dibatalkan.
                      </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                      <AlertDialogCancel>Batal</AlertDialogCancel>
                      <AlertDialogAction onClick={() => handleDelete(c.id)} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                        Hapus
                      </AlertDialogAction>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}
