  "src/pages/Dashboard.tsx": "import { useEffect, useState } from 'react';
import { getDashboardStats, GetDashboardStatsOutputType, getAdminAlerts } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Skeleton } from '@project/components/ui/skeleton';
import { Button } from '@project/components/ui/button';
import { Users, Package, ArrowLeftRight, ShieldAlert, AlertTriangle, ArrowRight } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { useNavigate } from 'react-router-dom';

type Stats = GetDashboardStatsOutputType;

const COLORS = [
  'hsl(152 55% 36%)',
  'hsl(199 70% 48%)',
  'hsl(38 92% 50%)',
  'hsl(280 55% 55%)',
  'hsl(350 70% 55%)',
];

function StatCard({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: typeof Users;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <Card>
      <CardContent className="flex items-center gap-4 p-5">
        <div
          className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl"
          style={{ backgroundColor: `${color}18`, color }}
        >
          <Icon size={22} />
        </div>
        <div>
          <p className="text-sm text-muted-foreground">{label}</p>
          <p className="text-2xl font-bold tracking-tight">{value.toLocaleString('id-ID')}</p>
        </div>
      </CardContent>
    </Card>
  );
}

export default function Dashboard() {
  const [stats, setStats] = useState<Stats | null>(null);
  const [alerts, setAlerts] = useState<{ totalActive: number; totalBerat: number; recentAlerts: any[] } | null>(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    Promise.all([
      getDashboardStats({}),
      getAdminAlerts({}),
    ]).then(([s, a]) => { setStats(s); setAlerts(a); }).finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold">Dashboard</h1>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {[1, 2, 3, 4].map((i) => (
            <Skeleton key={i} className="h-24 rounded-xl" />
          ))}
        </div>
        <div className="grid gap-4 lg:grid-cols-2">
          <Skeleton className="h-72 rounded-xl" />
          <Skeleton className="h-72 rounded-xl" />
        </div>
      </div>
    );
  }

  if (!stats) return null;

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold">Dashboard</h1>

      {/* Urgent Violation Alert */}
      {alerts && alerts.totalBerat > 0 && (
        <div className="rounded-xl border-2 border-red-300 bg-red-50 p-4 flex flex-col gap-3 sm:flex-row sm:items-center animate-in fade-in slide-in-from-top-2 duration-500">
          <div className="flex items-center gap-3 flex-1">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-red-500 animate-pulse">
              <AlertTriangle size={20} className="text-white" />
            </div>
            <div>
              <p className="font-bold text-red-800">
                {alerts.totalBerat} Pelanggaran Berat Perlu Ditangani!
              </p>
