        <StatCard icon={Package} label="Total Listing" value={stats.totalItems} color="hsl(152,55%,36%)" />
        <StatCard icon={ArrowLeftRight} label="Total Barter" value={stats.totalBarters} color="hsl(280,55%,55%)" />
