                  <XAxis dataKey="week" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} allowDecimals={false} />
                  <Tooltip />
                  <Bar dataKey="count" fill="hsl(152,55%,36%)" radius={[6, 6, 0, 0]} name="Barter" />
                </BarChart>
              </ResponsiveContainer>
