        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-base">Status Listing</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={stats.itemsByStatus}
                    dataKey="count"
                    nameKey="status"
                    cx="50%"
                    cy="50%"
                    outerRadius={90}
                    label={({ status, count }) => `${status} (${count})`}
                  >
                    {stats.itemsByStatus.map((_, i) => (
                      <Cell key={i} fill={COLORS[i % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Recent items & Barter status */}
      <div className="grid gap-4 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Listing Terbaru</CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="divide-y">
              {stats.recentItems.map((item) => (
                <div key={item.id} className="flex items-center justify-between px-5 py-3">
                  <div className="min-w-0">
                    <p className="truncate text-sm font-medium">{item.title || 'Tanpa Judul'}</p>
                    <p className="text-xs text-muted-foreground">
                      {item.createdAt
                        ? format(new Date(item.createdAt), 'dd MMM yyyy', { locale: idLocale })
                        : '-'}
                    </p>
                  </div>
                  <StatusBadge status={item.status} />
                </div>
              ))}
              {stats.recentItems.length === 0 && (
                <p className="p-5 text-center text-sm text-muted-foreground">Belum ada listing</p>
              )}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-base">Status Barter</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {stats.bartersByStatus.map((s) => (
                <div key={s.status} className="flex items-center justify-between">
                  <StatusBadge status={s.status} />
                  <span className="text-sm font-semibold">{s.count}</span>
                </div>
              ))}
              {stats.bartersByStatus.length === 0 && (
                <p className="text-center text-sm text-muted-foreground">Belum ada data</p>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const colorMap: Record<string, string> = {
    Tersedia: 'bg-emerald-100 text-emerald-700',
    Negosiasi: 'bg-amber-100 text-amber-700',
    'Sudah Ditukar': 'bg-blue-100 text-blue-700',
    Menunggu: 'bg-amber-100 text-amber-700',
    Diterima: 'bg-sky-100 text-sky-700',
    Selesai: 'bg-emerald-100 text-emerald-700',
    Dibatalkan: 'bg-red-100 text-red-700',
  };
  return (
    <span
      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${
        colorMap[status] ?? 'bg-muted text-muted-foreground'
      }`}
    >
      {status || 'Unknown'}
    </span>
  );
}
