        {/* Violations */}
        <Card id="violations">
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><AlertTriangle size={16} /> Pelanggaran ({violations.length})</CardTitle></CardHeader>
          <CardContent className="p-0">
            <div className="divide-y max-h-80 overflow-y-auto">
              {violations.length === 0 ? (
                <p className="p-4 text-center text-sm text-muted-foreground">Tidak ada pelanggaran</p>
              ) : violations.map((v: any) => (
                <div key={v.id} className="flex items-center justify-between px-4 py-2.5">
                  <div className="min-w-0">
                    <p className="truncate text-sm font-medium">{v.violationType}</p>
                    <p className="text-xs text-muted-foreground">
                      <SeverityBadge severity={v.severity} /> · -{v.minusPoints} poin · {fmtDate(v.createdAt)}
                    </p>
                  </div>
                  <StatusBadge status={v.status} />
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Reviews */}
        <Card>
          <CardHeader><CardTitle className="text-base flex items-center gap-2"><Star size={16} /> Review ({reviews.length})</CardTitle></CardHeader>
          <CardContent className="p-0">
            <div className="divide-y max-h-80 overflow-y-auto">
              {reviews.length === 0 ? (
                <p className="p-4 text-center text-sm text-muted-foreground">Tidak ada review</p>
              ) : reviews.map((r: any, i: number) => (
                <div key={i} className="px-4 py-2.5">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium">{r.reviewerName}</span>
                    <span className="text-xs text-amber-500">{'★'.repeat(r.rating)}{'☆'.repeat(5 - r.rating)}</span>
                  </div>
                  {r.aspect && <p className="text-xs text-primary">{r.aspect}</p>}
                  {r.comment && <p className="text-xs text-muted-foreground mt-0.5">{r.comment}</p>}
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

function StatMini({ icon: Icon, label, value, color }: { icon: any; label: string; value: string | number; color?: string }) {
  return (
    <Card>
      <CardContent className="flex items-center gap-3 p-3">
        <Icon size={18} className="text-muted-foreground shrink-0" />
        <div>
          <p className="text-xs text-muted-foreground">{label}</p>
          <p className={`text-lg font-bold ${color ?? ''}`}>{typeof value === 'number' ? value.toLocaleString('id-ID') : value}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function fmtDate(d: string | null) {
  if (!d) return '-';
  try { return format(new Date(d), 'dd MMM yyyy', { locale: idLocale }); } catch { return '-'; }
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Tersedia: 'bg-emerald-100 text-emerald-700', Negosiasi: 'bg-amber-100 text-amber-700',
    'Sudah Ditukar': 'bg-blue-100 text-blue-700', Menunggu: 'bg-amber-100 text-amber-700',
    Diterima: 'bg-sky-100 text-sky-700', Selesai: 'bg-emerald-100 text-emerald-700',
    Dibatalkan: 'bg-red-100 text-red-700', Aktif: 'bg-red-100 text-red-700',
    'Sudah Diperingatkan': 'bg-amber-100 text-amber-700', Dicabut: 'bg-emerald-100 text-emerald-700',
  };
  return <span className={`shrink-0 rounded-full px-2 py-0.5 text-xs font-medium ${c[status] ?? 'bg-muted text-muted-foreground'}`}>{status}</span>;
}

function SeverityBadge({ severity }: { severity: string }) {
  const c: Record<string, string> = { Berat: 'text-red-600', Sedang: 'text-amber-600', Ringan: 'text-blue-600' };
  return <span className={`font-medium ${c[severity] ?? ''}`}>{severity}</span>;
}
