  "src/pages/ViolationDetailPage.tsx": "import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getViolationDetail, updateViolationStatus } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Skeleton } from '@project/components/ui/skeleton';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import {
  Dialog, DialogContent, DialogTrigger,
} from '@project/components/ui/dialog';
import {
  ArrowLeft, AlertTriangle, User, UserCheck, ImageIcon,
  FileText, ArrowLeftRight, Calendar, ShieldAlert, MinusCircle,
} from 'lucide-react';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { toast } from 'sonner';

const V_STATUSES = ['Aktif', 'Sudah Diperingatkan', 'Banding', 'Kedaluwarsa', 'Dicabut'];

type Evidence = { url: string; filename: string; mimeType: string };

type ViolationDetail = {
  id: string;
  label: string;
  violationType: string;
  severity: string;
  minusPoints: number;
  status: string;
  notes: string | null;
  createdAt: string | null;
  evidence: Evidence[];
  userName: string;
  userEmail: string;
  userId: string | null;
  userImage: string | null;
  reporterName: string;
  reporterEmail: string;
  reporterImage: string | null;
  barterTitle: string | null;
  barterStatus: string | null;
};

export default function ViolationDetailPage() {
  const { violationId } = useParams<{ violationId: string }>();
  const navigate = useNavigate();
  const [data, setData] = useState<ViolationDetail | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    if (!violationId) return;
    setLoading(true);
    try {
      const res = await getViolationDetail({ violationId });
      setData(res.violation as ViolationDetail);
    } catch {
      toast.error('Gagal memuat detail pelanggaran');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [violationId]);

  const handleUpdateStatus = async (newStatus: string) => {
    if (!violationId) return;
    try {
      await updateViolationStatus({ violationId, status: newStatus as any });
      toast.success('Status diubah ke "' + newStatus + '"');
      fetchData();
    } catch {
      toast.error('Gagal mengubah status');
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-48 rounded-xl" />
        <div className="grid gap-4 lg:grid-cols-2">
          <Skeleton className="h-40 rounded-xl" />
          <Skeleton className="h-40 rounded-xl" />
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="space-y-4">
        <Button variant="ghost" onClick={() => navigate('/violations')}>
          <ArrowLeft size={16} className="mr-1" /> Kembali
        </Button>
        <p className="text-center text-muted-foreground py-12">Pelanggaran tidak ditemukan</p>
      </div>
    );
  }

  const severityColor = data.severity === 'Berat' ? 'border-red-300 bg-red-50' :
    data.severity === 'Sedang' ? 'border-amber-300 bg-amber-50' : 'border-blue-200 bg-blue-50';
  const severityIcon = data.severity === 'Berat' ? 'bg-red-500' :
    data.severity === 'Sedang' ? 'bg-amber-500' : 'bg-blue-500';

  return (
    <div className="space-y-6 max-w-4xl">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate('/violations')}>
          <ArrowLeft size={18} />
        </Button>
        <h1 className="text-2xl font-bold">Detail Pengaduan</h1>
      </div>

      {/* Main report card */}
      <Card className={'border-2 ' + severityColor}>
        <CardContent className="p-5 space-y-4">
          {/* Type & severity header */}
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-3">
              <div className={'flex h-11 w-11 shrink-0 items-center justify-center rounded-xl ' + severityIcon}>
                <AlertTriangle size={22} className="text-white" />
              </div>
              <div>
                <h2 className="text-lg font-bold">{data.violationType}</h2>
                <div className="flex items-center gap-2 mt-0.5">
                  <SeverityBadge severity={data.severity} />
                  <StatusBadge status={data.status} />
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-muted-foreground">Ubah status:</span>
              <Select value={data.status} onValueChange={handleUpdateStatus}>
                <SelectTrigger className="w-44 h-9 text-sm"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {V_STATUSES.map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Meta info */}
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
            <InfoItem icon={MinusCircle} label="Poin Dikurangi" value={'-' + data.minusPoints} className="text-destructive font-bold" />
            <InfoItem icon={Calendar} label="Tanggal Laporan" value={data.createdAt ? format(new Date(data.createdAt), 'dd MMMM yyyy, HH:mm', { locale: idLocale }) : '-'} />
            {data.barterTitle && (
              <InfoItem icon={ArrowLeftRight} label="Barter Terkait" value={data.barterTitle + (data.barterStatus ? ' (' + data.barterStatus + ')' : '')} />
            )}
          </div>
        </CardContent>
      </Card>

      {/* People */}
      <div className="grid gap-4 sm:grid-cols-2">
        <PersonCard
          title="Pelanggar"
          icon={<ShieldAlert size={16} className="text-destructive" />}
          name={data.userName}
          email={data.userEmail}
          image={data.userImage}
          onClick={data.userId ? () => navigate('/users/' + data.userId) : undefined}
          accent="destructive"
        />
        <PersonCard
          title="Pelapor"
          icon={<UserCheck size={16} className="text-emerald-600" />}
          name={data.reporterName || 'Sistem'}
          email={data.reporterEmail}
          image={data.reporterImage}
          accent="emerald"
        />
      </div>

      {/* Alasan / Notes */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <FileText size={16} /> Alasan & Detail Masalah
          </CardTitle>
        </CardHeader>
        <CardContent>
          {data.notes ? (
            <div className="rounded-lg bg-muted/50 p-4">
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{data.notes}</p>
            </div>
          ) : (
            <p className="text-sm text-muted-foreground italic">Tidak ada catatan/alasan yang diberikan.</p>
          )}
        </CardContent>
      </Card>

      {/* Evidence */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <ImageIcon size={16} /> Bukti Pengaduan ({data.evidence.length} file)
          </CardTitle>
        </CardHeader>
        <CardContent>
          {data.evidence.length === 0 ? (
            <div className="rounded-lg border-2 border-dashed border-muted-foreground/20 py-10 text-center">
              <ImageIcon size={32} className="mx-auto text-muted-foreground/30 mb-2" />
              <p className="text-sm text-muted-foreground">Tidak ada bukti yang dilampirkan</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
              {data.evidence.map((e, i) => (
                <EvidenceThumb key={i} evidence={e} />
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function EvidenceThumb({ evidence }: { evidence: Evidence }) {
  const isImage = evidence.mimeType?.startsWith('image/');

  if (isImage) {
    return (
      <Dialog>
        <DialogTrigger asChild>
          <button className="group relative aspect-square overflow-hidden rounded-lg border bg-muted cursor-pointer hover:ring-2 hover:ring-primary transition-all">
            <img src={evidence.url} alt={evidence.filename} className="h-full w-full object-cover" />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
              <span className="opacity-0 group-hover:opacity-100 text-white text-xs font-medium bg-black/50 rounded px-2 py-1 transition-opacity">
                Perbesar
              </span>
            </div>
          </button>
        </DialogTrigger>
        <DialogContent className="max-w-3xl p-2">
          <img src={evidence.url} alt={evidence.filename} className="w-full rounded-lg" />
          <p className="text-xs text-muted-foreground text-center mt-1">{evidence.filename}</p>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <a
      href={evidence.url}
      target="_blank"
      rel="noopener noreferrer"
      className="flex flex-col items-center justify-center gap-2 aspect-square rounded-lg border bg-muted hover:bg-muted/80 transition-colors p-3"
    >
      <FileText size={28} className="text-muted-foreground" />
      <p className="text-xs text-muted-foreground text-center truncate w-full">{evidence.filename}</p>
    </a>
  );
}

function PersonCard({ title, icon, name, email, image, onClick, accent }: {
  title: string; icon: React.ReactNode; name: string; email: string;
  image: string | null; onClick?: () => void; accent: string;
}) {
  return (
    <Card className={onClick ? 'cursor-pointer hover:shadow-md transition-shadow' : ''} onClick={onClick}>
      <CardContent className="flex items-center gap-3 p-4">
        {image ? (
          <img src={image} alt="" className="h-10 w-10 rounded-full object-cover" />
        ) : (
          <div className={'flex h-10 w-10 items-center justify-center rounded-full text-sm font-bold ' +
            (accent === 'destructive' ? 'bg-red-100 text-red-700' : 'bg-emerald-100 text-emerald-700')}>
            {name[0]?.toUpperCase() ?? '?'}
          </div>
        )}
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5">
            {icon}
            <span className="text-xs text-muted-foreground">{title}</span>
          </div>
          <p className="font-semibold text-sm truncate">{name}</p>
          {email && <p className="text-xs text-muted-foreground truncate">{email}</p>}
        </div>
        {onClick && <ArrowLeft size={14} className="rotate-180 text-muted-foreground" />}
      </CardContent>
    </Card>
  );
}

function InfoItem({ icon: Icon, label, value, className }: { icon: any; label: string; value: string; className?: string }) {
  return (
    <div className="flex items-center gap-2">
      <Icon size={16} className="text-muted-foreground shrink-0" />
      <div>
        <p className="text-xs text-muted-foreground">{label}</p>
        <p className={'text-sm font-medium ' + (className ?? '')}>{value}</p>
      </div>
    </div>
  );
}

function SeverityBadge({ severity }: { severity: string }) {
  const c: Record<string, string> = {
    Berat: 'bg-red-100 text-red-700', Sedang: 'bg-amber-100 text-amber-700', Ringan: 'bg-blue-100 text-blue-700',
  };
  return <span className={'rounded-full px-2 py-0.5 text-xs font-bold ' + (c[severity] ?? 'bg-muted text-muted-foreground')}>{severity.toUpperCase()}</span>;
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Aktif: 'bg-red-100 text-red-700', 'Sudah Diperingatkan': 'bg-amber-100 text-amber-700',
    Banding: 'bg-purple-100 text-purple-700', Kedaluwarsa: 'bg-gray-100 text-gray-600',
    Dicabut: 'bg-emerald-100 text-emerald-700',
  };
  return <span className={'rounded-full px-2 py-0.5 text-xs font-medium ' + (c[status] ?? 'bg-muted text-muted-foreground')}>{status}</span>;
}
