  "src/pages/ViolationsPage.tsx": "import { useEffect, useState, useCallback } from 'react';
import { getAdminViolations, updateViolationStatus } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Skeleton } from '@project/components/ui/skeleton';
import { ChevronLeft, ChevronRight, AlertTriangle, Eye } from 'lucide-react';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { toast } from 'sonner';
import { useNavigate } from 'react-router-dom';

type Violation = {
  id: string;
  label: string;
  violationType: string;
  severity: string;
  minusPoints: number;
  status: string;
  notes: string | null;
  createdAt: string | null;
  userName: string;
  userEmail: string;
  reporterName: string;
};

const V_STATUSES = ['Aktif', 'Sudah Diperingatkan', 'Banding', 'Kedaluwarsa', 'Dicabut'];
const SEVERITIES = ['Berat', 'Sedang', 'Ringan'];

export default function ViolationsPage() {
  const [violations, setViolations] = useState<Violation[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [statusFilter, setStatusFilter] = useState('');
  const [severityFilter, setSeverityFilter] = useState('');
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const limit = 20;

  const fetchData = useCallback(async (st: string, sv: string, p: number) => {
    setLoading(true);
    try {
      const res = await getAdminViolations({ status: st || undefined, severity: sv || undefined, offset: p * limit, limit });
      setViolations(res.violations as Violation[]);
      setTotal(res.total);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(statusFilter, severityFilter, page); }, [page, statusFilter, severityFilter]);

  const handleUpdateStatus = async (id: string, newStatus: string) => {
    try {
      await updateViolationStatus({ violationId: id, status: newStatus as any });
      toast.success(`Status diubah ke "${newStatus}"`);
      fetchData(statusFilter, severityFilter, page);
    } catch {
      toast.error('Gagal mengubah status');
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / limit));

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-bold">Pelanggaran</h1>

      <div className="flex flex-col gap-3 sm:flex-row">
        <Select value={statusFilter} onValueChange={(v) => { setStatusFilter(v === 'all' ? '' : v); setPage(0); }}>
          <SelectTrigger className="w-44"><SelectValue placeholder="Semua Status" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Status</SelectItem>
            {V_STATUSES.map((s) => <SelectItem key={s} value={s}>{s}</SelectItem>)}
          </SelectContent>
        </Select>
        <Select value={severityFilter} onValueChange={(v) => { setSeverityFilter(v === 'all' ? '' : v); setPage(0); }}>
          <SelectTrigger className="w-36"><SelectValue placeholder="Semua Level" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Level</SelectItem>
            {SEVERITIES.map((s) => <SelectItem key={s} value={s}>{s}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <div className="space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-24 rounded-xl" />)}</div>
      ) : violations.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Tidak ada pelanggaran ditemukan</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {violations.map((v) => (
            <Card key={v.id}>
              <CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-start">
                <div className="flex items-start gap-3 min-w-0 flex-1">
                  <div className={`mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${
                    v.severity === 'Berat' ? 'bg-red-100 text-red-600' :
                    v.severity === 'Sedang' ? 'bg-amber-100 text-amber-600' :
                    'bg-blue-100 text-blue-600'
                  }`}>
                    <AlertTriangle size={18} />
                  </div>
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="font-semibold text-sm">{v.violationType}</p>
                      <SeverityBadge severity={v.severity} />
                      <StatusBadge status={v.status} />
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Pelanggar: <span className="font-medium text-foreground">{v.userName}</span> ({v.userEmail})
                    </p>
                    {v.reporterName && <p className="text-xs text-muted-foreground">Dilaporkan oleh: {v.reporterName}</p>}
                    {v.notes && <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{v.notes}</p>}
                    <p className="text-xs text-muted-foreground mt-1">
                      Poin dikurangi: <span className="font-medium text-destructive">-{v.minusPoints}</span>
                      {v.createdAt && ` · ${format(new Date(v.createdAt), 'dd MMM yyyy', { locale: idLocale })}`}
                    </p>
                  </div>
                </div>

                <div className="shrink-0 flex flex-col gap-2">
                  <Select value={v.status} onValueChange={(s) => handleUpdateStatus(v.id, s)}>
                    <SelectTrigger className="w-44 text-xs h-8"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {V_STATUSES.map((s) => <SelectItem key={s} value={s}>{s}</SelectItem>)}
                    </SelectContent>
                  </Select>
                  <Button variant="outline" size="sm" className="text-xs h-8" onClick={() => navigate('/violations/' + v.id)}>
                    <Eye size={14} className="mr-1" /> Lihat Detail
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}

function SeverityBadge({ severity }: { severity: string }) {
  const c: Record<string, string> = {
    Berat: 'bg-red-100 text-red-700',
    Sedang: 'bg-amber-100 text-amber-700',
    Ringan: 'bg-blue-100 text-blue-700',
  };
  return <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${c[severity] ?? 'bg-muted text-muted-foreground'}`}>{severity}</span>;
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Aktif: 'bg-red-100 text-red-700',
    'Sudah Diperingatkan': 'bg-amber-100 text-amber-700',
    Banding: 'bg-purple-100 text-purple-700',
    Kedaluwarsa: 'bg-gray-100 text-gray-600',
    Dicabut: 'bg-emerald-100 text-emerald-700',
  };
  return <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${c[status] ?? 'bg-muted text-muted-foreground'}`}>{status}</span>;
}
