import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Add fake followers to a user to boost their profile',
  inputSchema: z.object({
    userId: z.string(),
    count: z.number().min(1),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    followersAdded: z.number(),
    totalFollowers: z.number(),
  }),
  execute: async ({ input }) => {
    // Get current follower count
    const { records: existing } = await zite.follows.findAll({
      filters: { followingUserId: input.userId },
      limit: 1,
    });

    // Count total existing
    const countResult = await zite.sql({
      query: `SELECT COUNT(*) as cnt FROM "Follows" WHERE "followingUserId" = $1`,
      params: [input.userId],
    });
    const currentCount = Number(countResult.rows[0]?.cnt) || 0;

    // Create follow records in batches of 100
    const totalToAdd = input.count;
    let added = 0;
    while (added < totalToAdd) {
      const batchSize = Math.min(100, totalToAdd - added);
      const records: { follower: string | string[] | null; followingUserId: string | null }[] = [];
      for (let i = 0; i < batchSize; i++) {
        records.push({ follower: null, followingUserId: input.userId });
      }
      await zite.follows.bulkCreate({ records });
      added += batchSize;
    }

    return {
      success: true,
      followersAdded: input.count,
      totalFollowers: currentCount + input.count,
    };
  },
});

