import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Add points to a user from admin boost generator',
  inputSchema: z.object({
    userId: z.string(),
    points: z.number().min(1).max(10000),
    reason: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    newTotalPoints: z.number(),
    pointsAdded: z.number(),
  }),
  execute: async ({ input }) => {
    // Find existing user points record
    const { records } = await zite.userPoints.findAll({
      filters: { user: input.userId },
      limit: 1,
    });

    let newTotal: number;

    if (records.length > 0) {
      const current = Number(records[0].totalPoints) || 0;
      newTotal = current + input.points;
      await zite.userPoints.update({
        id: records[0].id,
        record: { totalPoints: newTotal },
      });
    } else {
      // Create new user points record
      newTotal = input.points;
      await zite.userPoints.create({
        record: {
          label: `Points - ${input.userId}`,
          user: input.userId,
          totalPoints: newTotal,
        },
      });
    }

    // Log in point history
    await zite.pointHistory.create({
      record: {
        activity: input.reason || 'Admin Boost',
        user: input.userId,
        points: input.points,
        activityType: 'admin_boost',
      },
    });

    return {
      success: true,
      newTotalPoints: newTotal,
      pointsAdded: input.points,
    };
  },
});

