import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Admin membatalkan transaksi barter',
  inputSchema: z.object({
    barterId: z.string(),
    reason: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const reason = input.reason || 'Dibatalkan oleh admin';

    // Get barter details first for notifications
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new Error('Barter tidak ditemukan');

    await zite.barterHistory.update({
      id: input.barterId,
      record: { status: 'Dibatalkan' },
    });

    // Notify both parties
    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    const notifRecords: Array<{ title: string; body: string; type: string; recipient: string; read: boolean; linkPath: string | null }> = [];
    if (initiatorId) {
      notifRecords.push({
        title: '⚠️ Barter Dibatalkan Admin',
        body: `Barter "${barter.title || 'Transaksi'}" dibatalkan: ${reason}`,
        type: 'System' as const,
        recipient: initiatorId,
        read: false,
        linkPath: '/barter-history',
      });
    }
    if (partnerId) {
      notifRecords.push({
        title: '⚠️ Barter Dibatalkan Admin',
        body: `Barter "${barter.title || 'Transaksi'}" dibatalkan: ${reason}`,
        type: 'System' as const,
        recipient: partnerId,
        read: false,
        linkPath: '/barter-history',
      });
    }
    if (notifRecords.length > 0) {
      await zite.notifications.bulkCreate({ records: notifRecords });
    }

    // Audit log
    const adminName = context.user.firstName ? `${context.user.firstName} ${context.user.lastName || ''}`.trim() : context.user.email;
    await zite.adminAuditLog.create({
      record: {
        action: 'Batalkan Barter',
        adminEmail: context.user.email,
        adminName,
        targetType: 'barter',
        targetId: input.barterId,
        targetName: barter.title || null,
        details: `Alasan: ${reason}`,
      },
    });

    return { success: true };
  },
});

