import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Admin mengirim peringatan langsung ke pengguna dengan pesan kustom',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
    title: z.string().min(1),
    message: z.string().min(1),
    severity: z.enum(['Ringan', 'Sedang', 'Berat', 'Paling Berat']).optional(),
    deductPoints: z.number().optional(),
    autoSuspend: z.boolean().optional(),
    autoBan: z.boolean().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    notificationId: z.string(),
    pointsDeducted: z.number(),
    actionTaken: z.string(),
  }),
  execute: async ({ input, context }) => {
    const adminName = context.user.firstName
      ? `${context.user.firstName} ${context.user.lastName || ''}`.trim()
      : context.user.email;

    const pointsToDeduct = input.deductPoints ?? 0;

    // Create notification to user
    const notification = await zite.notifications.create({
      record: {
        title: `⚠️ ${input.title}`,
        body: `${input.message}${pointsToDeduct > 0 ? ` (-${pointsToDeduct} poin)` : ''}`,
        type: 'System',
        recipient: input.userId,
        read: false,
        linkPath: '/wallet',
      },
    });

    // Deduct points if specified
    if (pointsToDeduct > 0) {
      const pointsRes = await zite.userPoints.findAll({
        filters: { user: input.userId },
        limit: 1,
      });
      if (pointsRes.records.length > 0) {
        const current = pointsRes.records[0];
        await zite.userPoints.update({
          id: current.id,
          record: {
            totalPoints: Math.max(0, (current.totalPoints ?? 0) - pointsToDeduct),
          },
        });
      }

      await zite.pointHistory.create({
        record: {
          activity: `Peringatan Admin: ${input.title}`,
          user: input.userId,
          points: -pointsToDeduct,
          activityType: 'admin_warning',
        },
      });
    }

    // Create violation record if severity is set
    if (input.severity) {
      await zite.violations.create({
        record: {
          label: `Admin: ${input.title}`,
          user: input.userId,
          violationType: input.title as any,
          severity: input.severity,
          minusPoints: pointsToDeduct > 0 ? -pointsToDeduct : 0,
          barter: null,
          reportedBy: context.user.id,
          notes: `[Admin Peringatan Langsung] ${input.message}`,
          status: 'Sudah Diperingatkan',
          evidence: null,
        },
      });
    }

    let actionTaken = 'Peringatan terkirim';

    // Auto-suspend
    if (input.autoSuspend || input.autoBan) {
      const profileRes = await zite.userProfiles.findAll({
        filters: { user: input.userId },
        limit: 1,
      });
      if (profileRes.records.length > 0) {
        if (input.autoBan) {
          await zite.userProfiles.update({
            id: profileRes.records[0].id,
            record: {
              banned: true,
              bannedReason: `Diblokir oleh admin: ${input.title}. ${input.message}`,
            },
          });
          actionTaken = 'Peringatan terkirim + Akun diblokir';

          await zite.notifications.create({
            record: {
              title: '🚫 Akun Diblokir oleh Admin',
              body: `Akun kamu telah diblokir. Alasan: ${input.title}. ${input.message}`,
              type: 'System',
              recipient: input.userId,
              read: false,
              linkPath: '/wallet',
            },
          });
        } else if (input.autoSuspend) {
          actionTaken = 'Peringatan terkirim + Akun ditangguhkan';

          await zite.notifications.create({
            record: {
              title: '⛔ Akun Ditangguhkan oleh Admin',
              body: `Akun kamu ditangguhkan sementara. Alasan: ${input.title}. ${input.message}`,
              type: 'System',
              recipient: input.userId,
              read: false,
              linkPath: '/wallet',
            },
          });
        }
      }
    }

    // Audit log
    await zite.adminAuditLog.create({
      record: {
        action: 'Send Direct Warning',
        adminEmail: context.user.email,
        adminName,
        targetType: 'user',
        targetId: input.userId,
        targetName: null,
        details: `Peringatan: "${input.title}" — ${input.message}. Poin dikurangi: ${pointsToDeduct}. Aksi: ${actionTaken}`,
      },
    });

    return {
      success: true,
      notificationId: notification.id,
      pointsDeducted: pointsToDeduct,
      actionTaken,
    };
  },
});

