import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const VIOLATION_TYPES = [
  'Tidak Hadir COD', 'Barang Tidak Sesuai', 'Fake Listing',
  'Batal Setelah COD Di-set', 'Batal Sepihak Setelah Deal',
  'Ghosting Negosiasi', 'Barter Expired Berulang',
  'Respons Lambat Berulang', 'Listing Tidak Lengkap',
  'Ubah Syarat di Menit Terakhir', 'Multi-Negosiasi Ghost', 'COD Egois',
] as const;

const SEVERITY_MAP: Record<string, string> = {
  'Tidak Hadir COD': 'Berat',
  'Barang Tidak Sesuai': 'Sedang',
  'Fake Listing': 'Paling Berat',
  'Batal Setelah COD Di-set': 'Berat',
  'Batal Sepihak Setelah Deal': 'Sedang',
  'Ghosting Negosiasi': 'Sedang',
  'Barter Expired Berulang': 'Ringan',
  'Respons Lambat Berulang': 'Ringan',
  'Listing Tidak Lengkap': 'Ringan',
  'Ubah Syarat di Menit Terakhir': 'Sedang',
  'Multi-Negosiasi Ghost': 'Sedang',
  'COD Egois': 'Sedang',
};

const POINTS_MAP: Record<string, number> = {
  'Ringan': -5,
  'Sedang': -10,
  'Berat': -20,
  'Paling Berat': -25,
};

export default createEndpoint({
  description: 'Admin memberikan peringatan pelanggaran kepada pengguna',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
    violationType: z.string(),
    notes: z.string().optional(),
    severityOverride: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    violationId: z.string(),
    severity: z.string(),
    minusPoints: z.number(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const severity = input.severityOverride || SEVERITY_MAP[input.violationType] || 'Sedang';
    const minusPoints = Math.abs(POINTS_MAP[severity] || 10);

    // Create violation record
    const violation = await zite.violations.create({
      record: {
        label: `Peringatan: ${input.violationType}`,
        user: input.userId,
        violationType: input.violationType,
        severity,
        minusPoints,
        barter: null,
        reportedBy: context.user.id,
        notes: input.notes
          ? `[Admin] ${input.notes}`
          : `[Admin] Peringatan dari admin`,
        status: 'Aktif',
        evidence: null,
      },
    });

    // Deduct points from user
    const pointsRes = await zite.userPoints.findAll({
      filters: { user: input.userId },
      limit: 1,
    });

    if (pointsRes.records.length > 0) {
      const current = pointsRes.records[0];
      await zite.userPoints.update({
        id: current.id,
        record: {
          totalPoints: Math.max(0, (current.totalPoints ?? 0) - minusPoints),
        },
      });
    }

    // Record point deduction in history
    await zite.pointHistory.create({
      record: {
        activity: `Peringatan Admin: ${input.violationType}`,
        user: input.userId,
        points: -minusPoints,
        activityType: 'violation_warning',
      },
    });

    // Send notification to user
    await zite.notifications.create({
      record: {
        title: '⚠️ Peringatan Pelanggaran',
        body: `Kamu mendapat peringatan "${input.violationType}". -${minusPoints} poin. ${input.notes ? `Catatan: ${input.notes}` : ''}`,
        type: 'System',
        recipient: input.userId,
        read: false,
        linkPath: null,
      },
    });

    // Audit log
    const adminName = context.user.firstName
      ? `${context.user.firstName} ${context.user.lastName || ''}`.trim()
      : context.user.email;

    await zite.adminAuditLog.create({
      record: {
        action: 'Warn User',
        adminEmail: context.user.email,
        adminName,
        targetType: 'user',
        targetId: input.userId,
        targetName: null,
        details: `Peringatan: ${input.violationType} (${severity}) -${minusPoints} poin. ${input.notes || ''}`,
      },
    });

    // Check if user should be auto-banned (5+ active violations)
    const countRes = await zite.sql({
      query: `SELECT COUNT(*) AS cnt FROM "Violations" WHERE "user"->>0 = $1 AND "status" = 'Aktif'`,
      params: [input.userId],
    });
    const activeCount = Number(countRes.rows[0]?.cnt ?? 0);

    let message = `Peringatan "${input.violationType}" berhasil diberikan. -${minusPoints} poin.`;

    if (activeCount >= 5) {
      // Auto-ban
      const profileRes = await zite.userProfiles.findAll({
        filters: { user: input.userId },
        limit: 1,
      });
      if (profileRes.records.length > 0) {
        await zite.userProfiles.update({
          id: profileRes.records[0].id,
          record: {
            banned: true,
            bannedReason: `Auto-ban: ${activeCount} pelanggaran aktif`,
          },
        });
      }
      message += ` ⚠️ User otomatis di-ban karena memiliki ${activeCount} pelanggaran aktif!`;
    }

    return {
      success: true,
      violationId: violation.id,
      severity,
      minusPoints,
      message,
    };
  },
});

