      });
    } else {
      await zite.userProfiles.update({
        id: records[0].id,
        record: {
          banned: input.action === 'ban',
          bannedReason: input.action === 'ban' ? (input.reason ?? 'Pelanggaran berulang') : null,
        },
      });
