import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const fakeComments = [
  'Bagus banget barangnya!', 'Masih available kah?', 'Tertarik nih, boleh barter?',
  'Kondisinya mantap 👍', 'Harga wajar sih ini', 'Lokasi dimana ya?',
