  'Barter sama apa ya enaknya?', 'Wah murah banget kalau segini',
  'Ada garansi gak kak?', 'Recommended seller 👌', 'Serius minat kak',
];

const indonesianNames = [
  'Andi Pratama', 'Siti Nurhaliza', 'Budi Santoso', 'Dewi Lestari', 'Rizky Aditya',
  'Putri Handayani', 'Fajar Nugroho', 'Nadia Safitri', 'Dimas Arya', 'Rina Wulandari',
  'Taufik Hidayat', 'Maya Sari', 'Agus Setiawan', 'Lina Marlina', 'Reza Firmansyah',
  'Ayu Permata', 'Hendra Gunawan', 'Sari Indah', 'Bayu Prakoso', 'Fitri Amalia',
  'Yoga Prabowo', 'Winda Kusuma', 'Arif Rahman', 'Dian Puspita', 'Ilham Maulana',
  'Ratna Dewi', 'Febri Kurniawan', 'Anisa Rahma', 'Galih Satria', 'Mega Putri',
  'Wahyu Saputra', 'Citra Kirana', 'Eko Prasetyo', 'Laras Arum', 'Irfan Hakim',
  'Nurul Aini', 'Bagus Wicaksono', 'Tika Salsabila', 'Denny Caknan', 'Bella Safira',
];

function pickUniqueNames(count: number): string[] {
  const shuffled = [...indonesianNames].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

export default createEndpoint({
  description: 'Boost views, likes, and comments for an item',
  inputSchema: z.object({
    itemId: z.string(),
    addViews: z.number().min(0).default(0),
    addLikes: z.number().min(0).default(0),
    addComments: z.number().min(0).max(20).default(0),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    newViewsCount: z.number(),
    newLikesCount: z.number(),
    commentsAdded: z.number(),
  }),
  execute: async ({ input }) => {
    const item = await zite.items.findOne({ id: input.itemId });
    if (!item) throw new Error('Item not found');

    const currentViews = Number(item.viewsCount) || 0;
    const currentLikes = Number(item.likesCount) || 0;
    const newViews = currentViews + input.addViews;
    const newLikes = currentLikes + input.addLikes;

    await zite.items.update({
      id: input.itemId,
      record: { viewsCount: newViews, likesCount: newLikes },
    });

    // Add fake comments
    let commentsAdded = 0;
    if (input.addComments > 0) {
      const names = pickUniqueNames(input.addComments);
      const commentRecords: any[] = [];
      const usedTexts = new Set<string>();
      for (let i = 0; i < input.addComments; i++) {
        let text = fakeComments[Math.floor(Math.random() * fakeComments.length)];
        // Avoid duplicate comments if possible
        let attempts = 0;
        while (usedTexts.has(text) && attempts < 10) {
          text = fakeComments[Math.floor(Math.random() * fakeComments.length)];
          attempts++;
        }
        usedTexts.add(text);
        const name = names[i] || `User${Math.floor(Math.random() * 9000) + 1000}`;
        commentRecords.push({
          label: text.slice(0, 30),
          item: input.itemId,
          content: text,
          author: null,
          authorName: name,
        });
      }
      // bulkCreate max 100
      await zite.comments.bulkCreate({ records: commentRecords });
      commentsAdded = input.addComments;
    }

    return { success: true, newViewsCount: newViews, newLikesCount: newLikes, commentsAdded };
  },
});

