import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Export users, listings, or barters data as CSV',
  authenticated: true,
  inputSchema: z.object({
    type: z.enum(['users', 'listings', 'barters']),
  }),
  outputSchema: z.object({ csv: z.string(), filename: z.string(), count: z.number() }),
  execute: async ({ input, context }) => {
    const { type } = input;

    // Log audit
    await zite.adminAuditLog.create({
      record: {
        action: `Export ${type}`,
        adminEmail: context.user.email,
        adminName: context.user.firstName ? `${context.user.firstName} ${context.user.lastName || ''}`.trim() : context.user.email,
        targetType: type,
        targetId: null,
        targetName: null,
        details: `Export seluruh data ${type}`,
      },
    });

    if (type === 'users') {
      const rows = await zite.sql({
        query: `
          SELECT
            u.id, u."name", u."email", u."image",
            p."displayName", p."phone", p."city", p."province", p."address", p."postalCode",
            p."phoneVerified", p."addressVerified", p."banned",
            pt."totalPoints", pt."currentBadge", pt."itemsUploaded", pt."bartersCompleted", pt."likesReceived"
          FROM "ziteUsers" u
          LEFT JOIN "UserProfiles" p ON p."user"->>0 = u.id
          LEFT JOIN "UserPoints" pt ON pt."user"->>0 = u.id
          ORDER BY u."name"
          LIMIT 2000
        `,
      });

      const headers = ['ID', 'Nama', 'Email', 'Display Name', 'HP', 'Kota', 'Provinsi', 'Alamat', 'Kode Pos', 'HP Verified', 'Alamat Verified', 'Banned', 'Poin', 'Badge', 'Upload', 'Barter', 'Likes'];
      const csv = [
        headers.join(','),
        ...rows.rows.map(r => [
          q(r.id), q(r.name), q(r.email), q(r.displayName), q(r.phone),
          q(r.city), q(r.province), q(r.address), q(r.postalCode),
          r.phoneVerified ?? false, r.addressVerified ?? false, r.banned ?? false,
          r.totalPoints ?? 0, q(r.currentBadge), r.itemsUploaded ?? 0,
          r.bartersCompleted ?? 0, r.likesReceived ?? 0,
        ].join(',')),
      ].join('\n');

      return { csv, filename: `users-${dateStr()}.csv`, count: rows.rows.length };
    }

    if (type === 'listings') {
      const rows = await zite.sql({
        query: `
          SELECT i.id, i."title", i."condition", i."status", i."location",
            i."viewsCount", i."likesCount", i."estimatedValueMin", i."estimatedValueMax",
            i.created_at AS "createdAt",
            u."name" AS "ownerName", u."email" AS "ownerEmail"
          FROM "Items" i
          LEFT JOIN "ziteUsers" u ON u.id = i."owner"->>0
          ORDER BY i.created_at DESC
          LIMIT 2000
        `,
      });

      const headers = ['ID', 'Judul', 'Kondisi', 'Status', 'Lokasi', 'Views', 'Likes', 'Nilai Min', 'Nilai Max', 'Tanggal', 'Pemilik', 'Email Pemilik'];
      const csv = [
        headers.join(','),
        ...rows.rows.map(r => [
          q(r.id), q(r.title), q(r.condition), q(r.status), q(r.location),
          r.viewsCount ?? 0, r.likesCount ?? 0, r.estimatedValueMin ?? '', r.estimatedValueMax ?? '',
          q(r.createdAt), q(r.ownerName), q(r.ownerEmail),
        ].join(',')),
      ].join('\n');

      return { csv, filename: `listings-${dateStr()}.csv`, count: rows.rows.length };
    }

    // barters
    const rows = await zite.sql({
      query: `
        SELECT b.id, b."title", b."status", b.created_at AS "createdAt", b."completedAt",
          b."codAddress",
          u1."name" AS "initiatorName", u1."email" AS "initiatorEmail",
          u2."name" AS "partnerName", u2."email" AS "partnerEmail"
        FROM "BarterHistory" b
        LEFT JOIN "ziteUsers" u1 ON u1.id = b."initiator"->>0
        LEFT JOIN "ziteUsers" u2 ON u2.id = b."partner"->>0
        ORDER BY b.created_at DESC
        LIMIT 2000
      `,
    });

    const headers = ['ID', 'Judul', 'Status', 'Tanggal', 'Selesai', 'COD', 'Initiator', 'Email Initiator', 'Partner', 'Email Partner'];
    const csv = [
      headers.join(','),
      ...rows.rows.map(r => [
        q(r.id), q(r.title), q(r.status), q(r.createdAt), q(r.completedAt),
        q(r.codAddress), q(r.initiatorName), q(r.initiatorEmail),
        q(r.partnerName), q(r.partnerEmail),
      ].join(',')),
    ].join('\n');

    return { csv, filename: `barters-${dateStr()}.csv`, count: rows.rows.length };
  },
});

function q(v: unknown): string {
  if (v === null || v === undefined) return '';
  const s = String(v).replace(/"/g, '""');
  return `"${s}"`;
}

function dateStr() {
  return new Date().toISOString().slice(0, 10);
}

