import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil alert pelanggaran terbaru untuk notifikasi admin',
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalActive: z.number(),
    totalBerat: z.number(),
    recentAlerts: z.array(z.object({
      id: z.string(),
      violationType: z.string(),
      severity: z.string(),
      status: z.string(),
      userName: z.string(),
      reporterName: z.string(),
      createdAt: z.string().nullable(),
      notes: z.string().nullable(),
    })),
  }),
  execute: async () => {
    const [countRes, beratRes, recentRes] = await Promise.all([
      zite.sql({
        query: `SELECT COUNT(*) AS cnt FROM "Violations" WHERE "status" = 'Menunggu Review' OR "status" = 'Aktif'`,
      }),
      zite.sql({
        query: `SELECT COUNT(*) AS cnt FROM "Violations" WHERE "status" = 'Aktif' AND "severity" = 'Berat'`,
      }),
      zite.sql({
        query: `
          SELECT v.id, v."violationType", v."severity", v."status", v."notes",
            v.created_at AS "createdAt",
            u."name" AS "userName",
            reporter."name" AS "reporterName"
          FROM "Violations" v
          LEFT JOIN "ziteUsers" u ON u.id = v."user"->>0
          LEFT JOIN "ziteUsers" reporter ON reporter.id = v."reportedBy"->>0
          WHERE v."status" = 'Aktif'
          ORDER BY
            CASE WHEN v."severity" = 'Berat' THEN 0
                 WHEN v."severity" = 'Sedang' THEN 1
                 ELSE 2 END,
            v.created_at DESC
          LIMIT 10
        `,
      }),
    ]);

    return {
      totalActive: Number(countRes.rows[0]?.cnt ?? 0),
      totalBerat: Number(beratRes.rows[0]?.cnt ?? 0),
      recentAlerts: recentRes.rows.map(r => ({
        id: String(r.id),
        violationType: String(r.violationType ?? ''),
        severity: String(r.severity ?? ''),
        status: String(r.status ?? ''),
        userName: String(r.userName ?? 'Unknown'),
        reporterName: String(r.reporterName ?? ''),
        createdAt: r.createdAt ? String(r.createdAt) : null,
        notes: r.notes ? String(r.notes) : null,
      })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil daftar semua transaksi (barter barang + jasa) untuk admin',
  inputSchema: z.object({
    status: z.string().optional(),
    search: z.string().optional(),
    type: z.enum(['all', 'barang', 'jasa']).default('all'),
    offset: z.number().default(0),
    limit: z.number().default(20),
  }),
  outputSchema: z.object({
    barters: z.array(z.any()),
    total: z.number(),
    hasMore: z.boolean(),
  }),
  execute: async ({ input }) => {
    const { status, search, type, offset, limit } = input;
    const results: any[] = [];
    let totalBarang = 0;
    let totalJasa = 0;

    // === BARTER BARANG ===
    if (type === 'all' || type === 'barang') {
      const params: unknown[] = [];
      const conditions: string[] = [];

      if (status) {
        params.push(status);
        conditions.push(`b."status" = $${params.length}`);
      }
      if (search) {
        params.push(`%${search}%`);
        conditions.push(`(b."title" ILIKE $${params.length} OR u1."name" ILIKE $${params.length} OR u2."name" ILIKE $${params.length})`);
      }

      const baseFrom = `
        FROM "BarterHistory" b
        LEFT JOIN "ziteUsers" u1 ON u1.id = b."initiator"->>0
        LEFT JOIN "ziteUsers" u2 ON u2.id = b."partner"->>0
      `;
      const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

      const countRes = await zite.sql({
        query: `SELECT COUNT(*) AS cnt ${baseFrom} ${where}`,
        params,
      });
      totalBarang = Number(countRes.rows[0]?.cnt ?? 0);

      if (type === 'barang' || type === 'all') {
        const pList = [...params, limit, offset];
        const res = await zite.sql({
          query: `
            SELECT b.id, b."title", b."status", b."codAddress",
              b.created_at AS "createdAt", b."completedAt",
              b."initiatorConfirmed", b."partnerConfirmed",
              u1."name" AS "initiatorName", u1."email" AS "initiatorEmail",
              u2."name" AS "partnerName", u2."email" AS "partnerEmail"
            ${baseFrom} ${where}
            ORDER BY b.created_at DESC
            LIMIT $${pList.length - 1} OFFSET $${pList.length}
          `,
          params: pList,
        });

        for (const r of res.rows) {
          results.push({
            id: String(r.id),
            title: String(r.title ?? ''),
            type: 'barang',
            status: String(r.status ?? ''),
            codAddress: r.codAddress ? String(r.codAddress) : null,
            createdAt: r.createdAt ? String(r.createdAt) : null,
            completedAt: r.completedAt ? String(r.completedAt) : null,
            initiatorConfirmed: Boolean(r.initiatorConfirmed),
            partnerConfirmed: Boolean(r.partnerConfirmed),
            initiatorName: String(r.initiatorName ?? ''),
            initiatorEmail: String(r.initiatorEmail ?? ''),
            partnerName: String(r.partnerName ?? ''),
            partnerEmail: String(r.partnerEmail ?? ''),
            itemTitle: null,
            serviceTitle: null,
          });
        }
      }
    }

    // === BARTER JASA ===
    if (type === 'all' || type === 'jasa') {
      const params: unknown[] = [];
      const conditions: string[] = [];

      if (status) {
        params.push(status);
        conditions.push(`sb."status" = $${params.length}`);
      }
      if (search) {
        params.push(`%${search}%`);
        conditions.push(`(sb."title" ILIKE $${params.length} OR u1."name" ILIKE $${params.length} OR u2."name" ILIKE $${params.length} OR s."title" ILIKE $${params.length})`);
      }

      const baseFrom = `
        FROM "ServiceBarters" sb
        LEFT JOIN "ziteUsers" u1 ON u1.id = sb."itemOwner"->>0
        LEFT JOIN "ziteUsers" u2 ON u2.id = sb."serviceProvider"->>0
        LEFT JOIN "Items" i ON i.id = sb."offeredItem"->>0
        LEFT JOIN "Services" s ON s.id = sb."requestedService"->>0
      `;
      const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

      const countRes = await zite.sql({
        query: `SELECT COUNT(*) AS cnt ${baseFrom} ${where}`,
        params,
      });
      totalJasa = Number(countRes.rows[0]?.cnt ?? 0);

      if (type === 'jasa' || type === 'all') {
        const pList = [...params, limit, offset];
        const res = await zite.sql({
          query: `
            SELECT sb.id, sb."title", sb."status",
              sb.created_at AS "createdAt", sb."completedAt",
              sb."itemOwnerConfirmed", sb."providerConfirmed",
              u1."name" AS "initiatorName", u1."email" AS "initiatorEmail",
              u2."name" AS "partnerName", u2."email" AS "partnerEmail",
              i."title" AS "itemTitle", s."title" AS "serviceTitle"
            ${baseFrom} ${where}
            ORDER BY sb.created_at DESC
            LIMIT $${pList.length - 1} OFFSET $${pList.length}
          `,
          params: pList,
        });

        for (const r of res.rows) {
          results.push({
            id: String(r.id),
            title: String(r.title ?? ''),
            type: 'jasa',
            status: String(r.status ?? ''),
            codAddress: null,
            createdAt: r.createdAt ? String(r.createdAt) : null,
            completedAt: r.completedAt ? String(r.completedAt) : null,
            initiatorConfirmed: Boolean(r.itemOwnerConfirmed),
            partnerConfirmed: Boolean(r.providerConfirmed),
            initiatorName: String(r.initiatorName ?? ''),
            initiatorEmail: String(r.initiatorEmail ?? ''),
            partnerName: String(r.partnerName ?? ''),
            partnerEmail: String(r.partnerEmail ?? ''),
            itemTitle: r.itemTitle ? String(r.itemTitle) : null,
            serviceTitle: r.serviceTitle ? String(r.serviceTitle) : null,
          });
        }
      }
    }

    // Sort combined by createdAt desc
    results.sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());

    const total = type === 'barang' ? totalBarang : type === 'jasa' ? totalJasa : totalBarang + totalJasa;

    return {
      barters: results.slice(0, limit),
      total,
      hasMore: offset + limit < total,
    };
  },
});

