        ${where}
        ORDER BY i.created_at DESC
        LIMIT $${params.length - 1} OFFSET $${params.length}
      `,
      params,
    });

    return {
      items: res.rows.map(r => ({
        id: String(r.id),
        title: String(r.title ?? ''),
        status: String(r.status ?? ''),
        condition: String(r.condition ?? ''),
        location: String(r.location ?? ''),
        estimatedValueMin: Number(r.estimatedValueMin ?? 0),
        estimatedValueMax: Number(r.estimatedValueMax ?? 0),
        viewsCount: Number(r.viewsCount ?? 0),
        likesCount: Number(r.likesCount ?? 0),
        createdAt: r.createdAt ? String(r.createdAt) : null,
        ownerName: String(r.ownerName ?? ''),
        ownerEmail: String(r.ownerEmail ?? ''),
      })),
      total: Number(countRes.rows[0]?.cnt ?? 0),
      hasMore: offset + limit < Number(countRes.rows[0]?.cnt ?? 0),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil daftar review barter untuk admin',
  inputSchema: z.object({
    ratingFilter: z.number().optional(),
    search: z.string().optional(),
    offset: z.number().default(0),
    limit: z.number().default(20),
  }),
  outputSchema: z.object({
    reviews: z.array(z.any()),
    total: z.number(),
    hasMore: z.boolean(),
    stats: z.object({
      totalReviews: z.number(),
      averageRating: z.number(),
      ratingDistribution: z.array(z.object({ rating: z.number(), count: z.number() })),
    }),
  }),
  execute: async ({ input }) => {
    const { ratingFilter, search, offset, limit } = input;
    const params: unknown[] = [];
    const conditions: string[] = [];

    if (ratingFilter) {
      params.push(ratingFilter);
      conditions.push(`r."rating" = $${params.length}`);
    }
    if (search) {
      params.push(`%${search}%`);
      conditions.push(`(r."comment" ILIKE $${params.length} OR reviewer."name" ILIKE $${params.length} OR reviewee."name" ILIKE $${params.length})`);
    }

    const baseFrom = `
      FROM "BarterReviews" r
      LEFT JOIN "ziteUsers" reviewer ON reviewer.id = r."reviewer"->>0
      LEFT JOIN "ziteUsers" reviewee ON reviewee.id = r."reviewee"->>0
      LEFT JOIN "BarterHistoryBarterReviews" br ON br."barterReviewsId" = r.id
      LEFT JOIN "BarterHistory" bh ON bh.id = br."barterHistoryId"
    `;
    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';

    const countRes = await zite.sql({
      query: `SELECT COUNT(*) AS cnt ${baseFrom} ${where}`,
      params,
    });

    // Stats query (always unfiltered)
    const statsRes = await zite.sql({
      query: `
        SELECT 
          COUNT(*) AS "totalReviews",
          COALESCE(AVG(r."rating"), 0) AS "averageRating"
        FROM "BarterReviews" r
      `,
    });

    const distRes = await zite.sql({
      query: `
        SELECT r."rating" AS rating, COUNT(*) AS cnt
        FROM "BarterReviews" r
        WHERE r."rating" IS NOT NULL
        GROUP BY r."rating"
        ORDER BY r."rating" DESC
      `,
    });

    params.push(limit, offset);
    const res = await zite.sql({
      query: `
        SELECT r.id, r."rating", r."comment", r."aspect", r.created_at AS "createdAt",
          reviewer."name" AS "reviewerName", reviewer."email" AS "reviewerEmail",
          reviewee."name" AS "revieweeName",
          bh."title" AS "barterTitle"
        ${baseFrom} ${where}
        ORDER BY r.created_at DESC
        LIMIT $${params.length - 1} OFFSET $${params.length}
      `,
      params,
    });

    const total = Number(countRes.rows[0]?.cnt ?? 0);
    return {
      reviews: res.rows.map(r => ({
        id: String(r.id),
        rating: Number(r.rating ?? 0),
        comment: r.comment ? String(r.comment) : null,
        aspect: r.aspect ? String(r.aspect) : null,
        createdAt: r.createdAt ? String(r.createdAt) : null,
        reviewerName: String(r.reviewerName ?? 'Unknown'),
        reviewerEmail: String(r.reviewerEmail ?? ''),
        revieweeName: String(r.revieweeName ?? 'Unknown'),
        barterTitle: r.barterTitle ? String(r.barterTitle) : null,
      })),
      total,
      hasMore: offset + limit < total,
      stats: {
        totalReviews: Number(statsRes.rows[0]?.totalReviews ?? 0),
        averageRating: Math.round(Number(statsRes.rows[0]?.averageRating ?? 0) * 10) / 10,
        ratingDistribution: [1, 2, 3, 4, 5].map(rating => ({
          rating,
          count: Number(distRes.rows.find(r => Number(r.rating) === rating)?.cnt ?? 0),
        })),
      },
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil daftar user untuk admin dengan flag pelanggaran',
  inputSchema: z.object({
    search: z.string().optional(),
    offset: z.number().default(0),
    limit: z.number().default(20),
    flagged: z.boolean().optional(),
  }),
  outputSchema: z.object({
    users: z.array(z.any()),
    total: z.number(),
    hasMore: z.boolean(),
  }),
  execute: async ({ input }) => {
    const { search, offset, limit, flagged } = input;

    let query = `
      SELECT u.id, u."name", u."email", u."image", u.created_at AS "createdAt",
        p."displayName", p."phone", p."city", p."phoneVerified",
        p."banned", p."bannedReason",
        COALESCE(pt."totalPoints", 0) AS "totalPoints",
        COALESCE(pt."bartersCompleted", 0) AS "bartersCompleted",
        COALESCE(pt."itemsUploaded", 0) AS "itemsUploaded",
        pt."currentBadge",
        COALESCE(vc.cnt, 0) AS "activeViolations"
      FROM "ziteUsers" u
      LEFT JOIN "UserProfiles" p ON p."user"->>0 = u.id
      LEFT JOIN "UserPoints" pt ON pt."user"->>0 = u.id
      LEFT JOIN (
        SELECT "user"->>0 AS uid, COUNT(*) AS cnt
        FROM "Violations" WHERE "status" = 'Aktif'
        GROUP BY "user"->>0
      ) vc ON vc.uid = u.id
    `;
    const params: unknown[] = [];
    const conditions: string[] = [];

    if (search) {
      params.push(`%${search}%`);
      conditions.push(`(u."name" ILIKE $${params.length} OR u."email" ILIKE $${params.length} OR p."displayName" ILIKE $${params.length})`);
    }
    if (flagged) {
      conditions.push(`(COALESCE(vc.cnt, 0) >= 3 OR p."banned" = true)`);
    }

    if (conditions.length) {
      query += ` WHERE ${conditions.join(' AND ')}`;
    }

    const countQuery = `SELECT COUNT(*) AS cnt FROM (${query}) sub`;
    const countRes = await zite.sql({ query: countQuery, params });

    params.push(limit, offset);
    query += ` ORDER BY COALESCE(vc.cnt, 0) DESC, u.created_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`;

    const res = await zite.sql({ query, params });
    const total = Number(countRes.rows[0]?.cnt ?? 0);

    return {
      users: res.rows.map(r => ({
        id: String(r.id),
        name: String(r.name ?? ''),
        email: String(r.email ?? ''),
        image: r.image ? String(r.image) : null,
        createdAt: r.createdAt ? String(r.createdAt) : null,
        displayName: r.displayName ? String(r.displayName) : null,
        phone: r.phone ? String(r.phone) : null,
        city: r.city ? String(r.city) : null,
        phoneVerified: Boolean(r.phoneVerified),
        banned: Boolean(r.banned),
        bannedReason: r.bannedReason ? String(r.bannedReason) : null,
        totalPoints: Number(r.totalPoints ?? 0),
        bartersCompleted: Number(r.bartersCompleted ?? 0),
        itemsUploaded: Number(r.itemsUploaded ?? 0),
        currentBadge: r.currentBadge ? String(r.currentBadge) : null,
        activeViolations: Number(r.activeViolations ?? 0),
      })),
      total,
      hasMore: offset + limit < total,
    };
  },
});

