    violations: z.array(z.any()),
    total: z.number(),
    hasMore: z.boolean(),
  }),
  execute: async ({ input }) => {
    const { status, severity, offset, limit } = input;
    const params: unknown[] = [];
    const conditions: string[] = [];

    if (status) {
      params.push(status);
      conditions.push(`v."status" = $${params.length}`);
    }
    if (severity) {
      params.push(severity);
