import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil data analytics tren untuk admin',
  inputSchema: z.object({}),
  outputSchema: z.object({
    bartersPerWeek: z.array(z.object({ week: z.string(), count: z.number() })),
    listingsPerWeek: z.array(z.object({ week: z.string(), count: z.number() })),
    listingsPerCategory: z.array(z.object({ category: z.string(), count: z.number() })),
    barterCompletionRate: z.array(z.object({ status: z.string(), count: z.number() })),
    topLocations: z.array(z.object({ location: z.string(), count: z.number() })),
    userGrowth: z.array(z.object({ week: z.string(), count: z.number() })),
  }),
  execute: async () => {
    const [bartersWeek, listingsWeek, listingsCat, barterStatus, topLoc, userGrowth] = await Promise.all([
      zite.sql({
        query: `
          SELECT to_char(created_at, 'IYYY-IW') AS week, COUNT(*) AS cnt
          FROM "BarterHistory"
          WHERE created_at >= now() - interval '12 weeks'
          GROUP BY 1 ORDER BY 1 ASC
        `,
      }),
      zite.sql({
        query: `
          SELECT to_char(created_at, 'IYYY-IW') AS week, COUNT(*) AS cnt
          FROM "Items"
          WHERE created_at >= now() - interval '12 weeks'
          GROUP BY 1 ORDER BY 1 ASC
        `,
      }),
      zite.sql({
        query: `
          SELECT c."name" AS category, COUNT(ci."itemsId") AS cnt
          FROM "Categories" c
          LEFT JOIN "CategoriesItems" ci ON ci."categoriesId" = c.id
          GROUP BY c.id, c."name"
          ORDER BY cnt DESC
          LIMIT 10
        `,
      }),
      zite.sql({
        query: `
          SELECT "status", COUNT(*) AS cnt
          FROM "BarterHistory"
          GROUP BY "status"
          ORDER BY cnt DESC
        `,
      }),
      zite.sql({
        query: `
          SELECT COALESCE("location", 'Tidak diketahui') AS location, COUNT(*) AS cnt
          FROM "Items"
          WHERE "location" IS NOT NULL AND "location" != ''
          GROUP BY "location"
          ORDER BY cnt DESC
          LIMIT 8
        `,
      }),
      zite.sql({
        query: `
          SELECT to_char(created_at, 'IYYY-IW') AS week, COUNT(*) AS cnt
          FROM "UserProfiles"
          WHERE created_at >= now() - interval '12 weeks'
          GROUP BY 1 ORDER BY 1 ASC
        `,
      }),
    ]);

    return {
      bartersPerWeek: bartersWeek.rows.map(r => ({ week: String(r.week), count: Number(r.cnt) })),
      listingsPerWeek: listingsWeek.rows.map(r => ({ week: String(r.week), count: Number(r.cnt) })),
      listingsPerCategory: listingsCat.rows.map(r => ({ category: String(r.category ?? 'Lainnya'), count: Number(r.cnt) })),
      barterCompletionRate: barterStatus.rows.map(r => ({ status: String(r.status ?? 'Unknown'), count: Number(r.cnt) })),
      topLocations: topLoc.rows.map(r => ({ location: String(r.location), count: Number(r.cnt) })),
      userGrowth: userGrowth.rows.map(r => ({ week: String(r.week), count: Number(r.cnt) })),
    };
  },
});

