import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil detail barter + jejak negosiasi (pesan chat) untuk admin review',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
  }),
  outputSchema: z.object({
    barter: z.object({
      id: z.string(),
      title: z.string(),
      status: z.string(),
      deliveryMethod: z.string().nullable(),
      codAddress: z.string().nullable(),
      codDetail: z.string().nullable(),
      shippingService: z.string().nullable(),
      premiumInsuranceStatus: z.string().nullable(),
      premiumInsuranceAmount: z.number().nullable(),
      initiatorConfirmed: z.boolean(),
      partnerConfirmed: z.boolean(),
      createdAt: z.string().nullable(),
      completedAt: z.string().nullable(),
      expiresAt: z.string().nullable(),
      notes: z.string().nullable(),
    }),
    initiator: z.object({
      id: z.string(),
      name: z.string(),
      email: z.string(),
      image: z.string().nullable(),
      itemTitle: z.string(),
      itemPhoto: z.string().nullable(),
    }),
    partner: z.object({
      id: z.string(),
      name: z.string(),
      email: z.string(),
      image: z.string().nullable(),
      itemTitle: z.string(),
      itemPhoto: z.string().nullable(),
    }),
    messages: z.array(z.object({
      id: z.string(),
      senderId: z.string(),
      senderName: z.string(),
      content: z.string(),
      type: z.string(),
      sentAt: z.string().nullable(),
    })),
    reviews: z.array(z.object({
      reviewerName: z.string(),
      rating: z.number(),
      comment: z.string(),
      createdAt: z.string().nullable(),
    })),
  }),
  execute: async ({ input }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    // Fetch users
    const getUserInfo = async (uid: string | undefined) => {
      if (!uid) return { id: '', name: 'Unknown', email: '', image: null as string | null };
      const res = await zite.sql({
        query: 'SELECT "id", "name", "email", "image" FROM "ziteUsers" WHERE "id" = $1',
        params: [uid],
      });
      const r = res.rows[0];
      return {
        id: uid,
        name: r ? String(r.name ?? 'Unknown') : 'Unknown',
        email: r ? String(r.email ?? '') : '',
        image: r?.image ? String(r.image) : null,
      };
    };

    const [initiatorUser, partnerUser] = await Promise.all([
      getUserInfo(initiatorId),
      getUserInfo(partnerId),
    ]);

    // Fetch items
    const getItemInfo = async (itemIds: string | string[] | undefined) => {
      const id = Array.isArray(itemIds) ? itemIds[0] : itemIds;
      if (!id) return { title: '-', photo: null as string | null };
      const item = await zite.items.findOne({ id });
      return {
        title: item?.title ?? '-',
        photo: (item?.photos && item.photos.length > 0) ? item.photos[0].url : null,
      };
    };

    const [offeredItem, requestedItem] = await Promise.all([
      getItemInfo(barter.offeredItem),
      getItemInfo(barter.requestedItem),
    ]);

    // Messages
    const { rows: msgRows } = await zite.sql({
      query: `SELECT bm."id", bm."sender", bm."content", bm."type", bm."sentAt"
              FROM "BarterMessages" bm
              JOIN "BarterHistoryBarterMessages" link ON link."barterMessagesId" = bm."id"
              WHERE link."barterHistoryId" = $1
              ORDER BY bm."sentAt" ASC
              LIMIT 500`,
      params: [input.barterId],
    });

    // Build user name map
    const userIds = new Set<string>();
    if (initiatorId) userIds.add(initiatorId);
    if (partnerId) userIds.add(partnerId);
    msgRows.forEach((r: any) => {
      const sIds = Array.isArray(r.sender) ? r.sender : r.sender ? [r.sender] : [];
      sIds.forEach((s: string) => userIds.add(s));
    });

    const nameMap = new Map<string, string>();
    nameMap.set(initiatorUser.id, initiatorUser.name);
    nameMap.set(partnerUser.id, partnerUser.name);

    const messages = msgRows.map((r: any) => {
      const sIds = Array.isArray(r.sender) ? r.sender : r.sender ? [r.sender] : [];
      const senderId = sIds[0] || '';
      return {
        id: r.id as string,
        senderId,
        senderName: nameMap.get(senderId) || 'Pengguna',
        content: (r.content as string) || '',
        type: (r.type as string) || 'Text',
        sentAt: (r.sentAt as string) ?? null,
      };
    });

    // Reviews
    const { rows: reviewRows } = await zite.sql({
      query: `SELECT br."reviewer", br."rating", br."comment", br."createdAt"
              FROM "BarterReviews" br
              JOIN "BarterHistoryBarterReviews" link ON link."barterReviewsId" = br."id"
              WHERE link."barterHistoryId" = $1
              ORDER BY br."createdAt" ASC`,
      params: [input.barterId],
    });

    const reviews = reviewRows.map((r: any) => {
      const revIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      return {
        reviewerName: nameMap.get(revIds[0] || '') || 'Pengguna',
        rating: Number(r.rating ?? 0),
        comment: String(r.comment ?? ''),
        createdAt: (r.createdAt as string) ?? null,
      };
    });

    return {
      barter: {
        id: barter.id,
        title: barter.title ?? '',
        status: barter.status ?? '',
        deliveryMethod: barter.deliveryMethod ?? null,
        codAddress: barter.codAddress ?? null,
        codDetail: barter.codDetail ?? null,
        shippingService: barter.shippingService ?? null,
        premiumInsuranceStatus: barter.premiumInsuranceStatus ?? null,
        premiumInsuranceAmount: barter.premiumInsuranceAmount ?? null,
        initiatorConfirmed: barter.initiatorConfirmed ?? false,
        partnerConfirmed: barter.partnerConfirmed ?? false,
        createdAt: barter.createdAt ?? null,
        completedAt: barter.completedAt ?? null,
        expiresAt: barter.expiresAt ?? null,
        notes: barter.notes ?? null,
      },
      initiator: {
        ...initiatorUser,
        itemTitle: offeredItem.title,
        itemPhoto: offeredItem.photo,
      },
      partner: {
        ...partnerUser,
        itemTitle: requestedItem.title,
        itemPhoto: requestedItem.photo,
      },
      messages,
      reviews,
    };
  },
});

