import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Lists all challenges for admin management',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({ challenges: z.array(z.any()) }),
  async execute() {
    const { records } = await zite.challenges.findAll({
      limit: 200,
    });

    // Get participant counts per challenge via SQL
    const { rows } = await zite.sql({
      query: `SELECT "challenge"[1] as "challengeId", COUNT(*) as "count"
              FROM "ChallengeParticipants"
              GROUP BY "challenge"[1]`,
    });
    const countMap: Record<string, number> = {};
    for (const r of rows) {
      if (r.challengeId) countMap[r.challengeId as string] = Number(r.count);
    }

    const challenges = records.map((c) => ({
      ...c,
      participantCount: countMap[c.id] ?? 0,
    }));

    // Sort: active first, then upcoming, then draft, then ended
    const order: Record<string, number> = { Aktif: 0, 'Akan Datang': 1, Draft: 2, Selesai: 3, Dibatalkan: 4 };
    challenges.sort((a, b) => (order[a.status ?? ''] ?? 5) - (order[b.status ?? ''] ?? 5));

    return { challenges };
  },
});

