import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil statistik dashboard admin dengan tren harian',
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalUsers: z.number(),
    totalItems: z.number(),
    totalBarters: z.number(),
    pendingViolations: z.number(),
    // Deltas (vs 7 days ago)
    newUsersToday: z.number(),
    newUsers7d: z.number(),
    newItems7d: z.number(),
    newBarters7d: z.number(),
    // Charts
    itemsByStatus: z.array(z.object({ status: z.string(), count: z.number() })),
    bartersByStatus: z.array(z.object({ status: z.string(), count: z.number() })),
    recentItems: z.array(z.object({
      id: z.string(), title: z.string(), status: z.string(),
      photo: z.string(), ownerName: z.string(),
      createdAt: z.string().nullable(),
    })),
    bartersPerWeek: z.array(z.object({ week: z.string(), count: z.number() })),
    // Daily trends (last 14 days)
    dailyUsers: z.array(z.object({ day: z.string(), count: z.number() })),
    dailyItems: z.array(z.object({ day: z.string(), count: z.number() })),
    dailyBarters: z.array(z.object({ day: z.string(), count: z.number() })),
    // Action items
    unmoderationCount: z.number(),
    recentViolations: z.array(z.object({
      id: z.string(), violationType: z.string(), severity: z.string(),
      userName: z.string(), createdAt: z.string().nullable(),
    })),
  }),
  execute: async () => {
    const results = await Promise.all([
      // 0: total users
      zite.sql({ query: 'SELECT COUNT(DISTINCT id) AS cnt FROM "ziteUsers"' }),
      // 1: total items
      zite.sql({ query: 'SELECT COUNT(*) AS cnt FROM "Items"' }),
      // 2: total barters
      zite.sql({ query: 'SELECT COUNT(*) AS cnt FROM "BarterHistory"' }),
      // 3: pending violations (now counts "Menunggu Review")
      zite.sql({ query: `SELECT COUNT(*) AS cnt FROM "Violations" WHERE "status" = 'Menunggu Review'` }),
      // 4: items by status
      zite.sql({ query: 'SELECT "status", COUNT(*) AS cnt FROM "Items" GROUP BY "status"' }),
      // 5: barters by status
      zite.sql({ query: 'SELECT "status", COUNT(*) AS cnt FROM "BarterHistory" GROUP BY "status"' }),
      // 6: recent items with photo & owner
      zite.sql({
        query: `SELECT i.id, i."title", i."status", i."photos", i.created_at AS "createdAt",
                  u."name" AS "ownerName"
                FROM "Items" i
                LEFT JOIN "ziteUsers" u ON u.id = i."owner"->>0
                ORDER BY i.created_at DESC LIMIT 8`,
      }),
      // 7: barters per week
      zite.sql({
        query: `SELECT to_char(created_at, 'IYYY-IW') AS week, COUNT(*) AS cnt
                FROM "BarterHistory"
                WHERE created_at >= now() - interval '12 weeks'
                GROUP BY 1 ORDER BY 1 ASC`,
      }),
      // 8: new users today
      zite.sql({ query: `SELECT COUNT(*) AS cnt FROM "ziteUsers" WHERE created_at >= CURRENT_DATE` }),
      // 9: new users 7d
      zite.sql({ query: `SELECT COUNT(*) AS cnt FROM "ziteUsers" WHERE created_at >= now() - interval '7 days'` }),
      // 10: new items 7d
      zite.sql({ query: `SELECT COUNT(*) AS cnt FROM "Items" WHERE created_at >= now() - interval '7 days'` }),
      // 11: new barters 7d
      zite.sql({ query: `SELECT COUNT(*) AS cnt FROM "BarterHistory" WHERE created_at >= now() - interval '7 days'` }),
      // 12: daily new users (14 days)
      zite.sql({
        query: `SELECT to_char(d, 'DD/MM') AS day, COALESCE(c.cnt, 0) AS cnt
                FROM generate_series(CURRENT_DATE - interval '13 days', CURRENT_DATE, '1 day') d
                LEFT JOIN (
                  SELECT DATE(created_at) AS dt, COUNT(*) AS cnt
                  FROM "ziteUsers"
                  WHERE created_at >= CURRENT_DATE - interval '13 days'
                  GROUP BY 1
                ) c ON c.dt = d
                ORDER BY d ASC`,
      }),
      // 13: daily new items (14 days)
      zite.sql({
        query: `SELECT to_char(d, 'DD/MM') AS day, COALESCE(c.cnt, 0) AS cnt
                FROM generate_series(CURRENT_DATE - interval '13 days', CURRENT_DATE, '1 day') d
                LEFT JOIN (
                  SELECT DATE(created_at) AS dt, COUNT(*) AS cnt
                  FROM "Items"
                  WHERE created_at >= CURRENT_DATE - interval '13 days'
                  GROUP BY 1
                ) c ON c.dt = d
                ORDER BY d ASC`,
      }),
      // 14: daily barters (14 days)
      zite.sql({
        query: `SELECT to_char(d, 'DD/MM') AS day, COALESCE(c.cnt, 0) AS cnt
                FROM generate_series(CURRENT_DATE - interval '13 days', CURRENT_DATE, '1 day') d
                LEFT JOIN (
                  SELECT DATE(created_at) AS dt, COUNT(*) AS cnt
                  FROM "BarterHistory"
                  WHERE created_at >= CURRENT_DATE - interval '13 days'
                  GROUP BY 1
                ) c ON c.dt = d
                ORDER BY d ASC`,
      }),
      // 15: recent active violations
      zite.sql({
        query: `SELECT v.id, v."violationType", v."severity", v.created_at AS "createdAt",
                  u."name" AS "userName"
                FROM "Violations" v
                LEFT JOIN "ziteUsers" u ON u.id = v."user"->>0
                WHERE v."status" = 'Aktif'
                ORDER BY CASE WHEN v."severity" = 'Berat' THEN 0 WHEN v."severity" = 'Sedang' THEN 1 ELSE 2 END,
                  v.created_at DESC
                LIMIT 5`,
      }),
    ]);

    // Parse photo URL from JSON
    const parsePhoto = (photos: unknown): string => {
      try {
        if (!photos) return '';
        const arr = typeof photos === 'string' ? JSON.parse(photos) : photos;
        if (Array.isArray(arr) && arr.length > 0) return arr[0]?.url || '';
        return '';
      } catch { return ''; }
    };

    return {
      totalUsers: Number(results[0].rows[0]?.cnt ?? 0),
      totalItems: Number(results[1].rows[0]?.cnt ?? 0),
      totalBarters: Number(results[2].rows[0]?.cnt ?? 0),
      pendingViolations: Number(results[3].rows[0]?.cnt ?? 0),
      newUsersToday: Number(results[8].rows[0]?.cnt ?? 0),
      newUsers7d: Number(results[9].rows[0]?.cnt ?? 0),
      newItems7d: Number(results[10].rows[0]?.cnt ?? 0),
      newBarters7d: Number(results[11].rows[0]?.cnt ?? 0),
      itemsByStatus: results[4].rows.map(r => ({ status: String(r.status ?? 'Unknown'), count: Number(r.cnt) })),
      bartersByStatus: results[5].rows.map(r => ({ status: String(r.status ?? 'Unknown'), count: Number(r.cnt) })),
      recentItems: results[6].rows.map(r => ({
        id: String(r.id), title: String(r.title ?? ''), status: String(r.status ?? ''),
        photo: parsePhoto(r.photos), ownerName: String(r.ownerName ?? ''),
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
      bartersPerWeek: results[7].rows.map(r => ({ week: String(r.week), count: Number(r.cnt) })),
      dailyUsers: results[12].rows.map(r => ({ day: String(r.day), count: Number(r.cnt) })),
      dailyItems: results[13].rows.map(r => ({ day: String(r.day), count: Number(r.cnt) })),
      dailyBarters: results[14].rows.map(r => ({ day: String(r.day), count: Number(r.cnt) })),
      unmoderationCount: 0, // placeholder
      recentViolations: results[15].rows.map(r => ({
        id: String(r.id), violationType: String(r.violationType ?? ''),
        severity: String(r.severity ?? ''), userName: String(r.userName ?? ''),
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
    };
  },
});

