import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getAffiliateTier } from '../lib/affiliate';

export default createEndpoint({
  description: 'Gets referral data with stats, top affiliates leaderboard for the admin panel',
  inputSchema: z.object({
    search: z.string().optional(),
    status: z.string().optional(),
    limit: z.number().optional(),
    offset: z.number().optional(),
  }),
  outputSchema: z.object({
    stats: z.object({
      totalCodes: z.number(),
      totalCompleted: z.number(),
      totalPending: z.number(),
      totalExpired: z.number(),
      totalBonusAwarded: z.number(),
    }),
    topAffiliates: z.array(z.object({
      userId: z.string(),
      name: z.string(),
      email: z.string(),
      image: z.string().nullable(),
      completedReferrals: z.number(),
      totalBonus: z.number(),
      tierId: z.string(),
      tierName: z.string(),
      tierEmoji: z.string(),
      pointsPerReferral: z.number(),
      boostSlots: z.number(),
    })),
    referrals: z.array(z.object({
      id: z.string(),
      referralCode: z.string(),
      referrerName: z.string(),
      referrerEmail: z.string(),
      referredName: z.string().nullable(),
      referredEmail: z.string().nullable(),
      status: z.string(),
      bonusPoints: z.number(),
      createdAt: z.string().nullable(),
    })),
    total: z.number(),
  }),
  execute: async ({ input }) => {
    // Stats
    const statsResult = await zite.sql({
      query: `
        SELECT
          COUNT(*) AS "totalCodes",
          COUNT(*) FILTER (WHERE "status" = 'Completed') AS "totalCompleted",
          COUNT(*) FILTER (WHERE "status" = 'Pending') AS "totalPending",
          COUNT(*) FILTER (WHERE "status" = 'Expired') AS "totalExpired",
          COALESCE(SUM("bonusPoints") FILTER (WHERE "status" = 'Completed'), 0) AS "totalBonusAwarded"
        FROM "Referrals"
      `,
    });

    const stats = {
      totalCodes: Number(statsResult.rows[0]?.totalCodes ?? 0),
      totalCompleted: Number(statsResult.rows[0]?.totalCompleted ?? 0),
      totalPending: Number(statsResult.rows[0]?.totalPending ?? 0),
      totalExpired: Number(statsResult.rows[0]?.totalExpired ?? 0),
      totalBonusAwarded: Number(statsResult.rows[0]?.totalBonusAwarded ?? 0),
    };

    // Top affiliates — users with most completed referrals
    const topResult = await zite.sql({
      query: `
        SELECT
          r."referrer"->>0 AS "userId",
          u."name",
          u."email",
          u."image",
          COUNT(*) FILTER (WHERE r."status" = 'Completed') AS "completedReferrals",
          COALESCE(SUM(r."bonusPoints") FILTER (WHERE r."status" = 'Completed'), 0) AS "totalBonus"
        FROM "Referrals" r
        LEFT JOIN "ziteUsers" u ON u.id = r."referrer"->>0
        GROUP BY r."referrer"->>0, u."name", u."email", u."image"
        HAVING COUNT(*) FILTER (WHERE r."status" = 'Completed') > 0
        ORDER BY "completedReferrals" DESC, "totalBonus" DESC
        LIMIT 20
      `,
    });

    const topAffiliates = topResult.rows.map(r => {
      const completed = Number(r.completedReferrals ?? 0);
      const tier = getAffiliateTier(completed);
      return {
        userId: String(r.userId ?? ''),
        name: String(r.name ?? 'Unknown'),
        email: String(r.email ?? ''),
        image: r.image ? String(r.image) : null,
        completedReferrals: completed,
        totalBonus: Number(r.totalBonus ?? 0),
        tierId: tier.id,
        tierName: tier.name,
        tierEmoji: tier.emoji,
        pointsPerReferral: tier.pointsPerReferral,
        boostSlots: tier.boostSlots,
      };
    });

    // Build conditions for referrals list
    const conditions: string[] = [];
    const params: unknown[] = [];
    let paramIdx = 1;

    if (input.status) {
      conditions.push(`r."status" = $${paramIdx++}`);
      params.push(input.status);
    }
    if (input.search) {
      conditions.push(`(r."referralCode" ILIKE $${paramIdx} OR referrer."name" ILIKE $${paramIdx} OR referrer."email" ILIKE $${paramIdx})`);
      params.push(`%${input.search}%`);
      paramIdx++;
    }

    const whereClause = conditions.length > 0 ? `WHERE ${conditions.join(' AND ')}` : '';
    const limit = input.limit ?? 20;
    const offset = input.offset ?? 0;

    // Count
    const countResult = await zite.sql({
      query: `
        SELECT COUNT(*) AS total
        FROM "Referrals" r
        LEFT JOIN "ziteUsers" referrer ON referrer.id = r."referrer"->>0
        ${whereClause}
      `,
      params,
    });

    // Referrals list
    const listResult = await zite.sql({
      query: `
        SELECT
          r.id,
          r."referralCode",
          COALESCE(referrer."name", 'Unknown') AS "referrerName",
          COALESCE(referrer."email", '') AS "referrerEmail",
          referred."name" AS "referredName",
          referred."email" AS "referredEmail",
          r."status",
          COALESCE(r."bonusPoints", 0) AS "bonusPoints",
          r.created_at AS "createdAt"
        FROM "Referrals" r
        LEFT JOIN "ziteUsers" referrer ON referrer.id = r."referrer"->>0
        LEFT JOIN "ziteUsers" referred ON referred.id = r."referredUser"->>0
        ${whereClause}
        ORDER BY r.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `,
      params,
    });

    return {
      stats,
      topAffiliates,
      referrals: listResult.rows.map((r) => ({
        id: String(r.id),
        referralCode: String(r.referralCode ?? ''),
        referrerName: String(r.referrerName ?? 'Unknown'),
        referrerEmail: String(r.referrerEmail ?? ''),
        referredName: r.referredName ? String(r.referredName) : null,
        referredEmail: r.referredEmail ? String(r.referredEmail) : null,
        status: String(r.status ?? 'Pending'),
        bonusPoints: Number(r.bonusPoints ?? 0),
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
      total: Number(countResult.rows[0]?.total ?? 0),
    };
  },
});

