import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil pesan support chat untuk user tertentu (admin view)',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
  }),
  outputSchema: z.object({
    messages: z.array(z.object({
      id: z.string(),
      content: z.string(),
      senderRole: z.string(),
      read: z.boolean(),
      createdAt: z.string(),
    })),
    userName: z.string(),
    userEmail: z.string(),
  }),
  execute: async ({ input }) => {
    const { records } = await zite.supportMessages.findAll({
      filters: { user: input.userId },
      limit: 500,
    });

    // Mark user messages as read
    const unread = records.filter(m => m.senderRole === 'user' && !m.read);
    for (const m of unread) {
      await zite.supportMessages.update({ id: m.id, record: { read: true } });
    }

    const sorted = records.sort(
      (a, b) => new Date(a.sentAt || '').getTime() - new Date(b.sentAt || '').getTime()
    );

    // Get user info
    let userName = '';
    let userEmail = '';
    try {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: input.userId },
        limit: 1,
      });
      if (users[0]) {
        userName = users[0].name || '';
        userEmail = users[0].email || '';
      }
    } catch { /* ignore */ }

    return {
      messages: sorted.map(m => ({
        id: m.id,
        content: m.content || '',
        senderRole: m.senderRole || 'user',
        read: m.read ?? false,
        createdAt: m.sentAt || '',
      })),
      userName,
      userEmail,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil semua chat support untuk admin',
  authenticated: true,
  inputSchema: z.object({
    status: z.string().optional(),
  }),
  outputSchema: z.object({
    conversations: z.array(z.object({
      userId: z.string(),
      userName: z.string(),
      userEmail: z.string(),
      lastMessage: z.string(),
      lastMessageAt: z.string(),
      unreadCount: z.number(),
      status: z.string(),
      totalMessages: z.number(),
    })),
  }),
  execute: async ({ input }) => {
    const { records } = await zite.supportMessages.findAll({
      limit: 2000,
    });

    // Group by user
    const byUser = new Map<string, typeof records>();
    for (const r of records) {
      const uid = Array.isArray(r.user) ? r.user[0] : r.user;
      if (!uid) continue;
      if (!byUser.has(uid)) byUser.set(uid, []);
      byUser.get(uid)!.push(r);
    }

    // Get user info
    const userIds = [...byUser.keys()];
    const userMap = new Map<string, { name: string; email: string }>();
    if (userIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({ limit: 200 });
      for (const u of users) {
        userMap.set(u.id, { name: u.name || u.email, email: u.email });
      }
    }

    const conversations = userIds.map(uid => {
      const msgs = byUser.get(uid)!;
      const sorted = msgs.sort((a, b) => new Date(b.sentAt || '').getTime() - new Date(a.sentAt || '').getTime());
      const lastMsg = sorted[0];
      const unread = msgs.filter(m => m.senderRole === 'user' && !m.read).length;
      const userInfo = userMap.get(uid) || { name: uid, email: '' };

      return {
        userId: uid,
        userName: userInfo.name,
        userEmail: userInfo.email,
        lastMessage: lastMsg?.content || '',
        lastMessageAt: lastMsg?.sentAt || '',
        unreadCount: unread,
        status: lastMsg?.status || 'open',
        totalMessages: msgs.length,
      };
    });

    // Sort: unread first, then by last message time
    conversations.sort((a, b) => {
      if (a.unreadCount > 0 && b.unreadCount === 0) return -1;
      if (b.unreadCount > 0 && a.unreadCount === 0) return 1;
      return new Date(b.lastMessageAt).getTime() - new Date(a.lastMessageAt).getTime();
    });

    const filtered = input.status
      ? conversations.filter(c => c.status === input.status)
      : conversations;

    return { conversations: filtered };
  },
});

