import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getAffiliateTier } from '../lib/affiliate';

export default createEndpoint({
  description: 'Mengambil detail lengkap seorang user untuk admin',
  inputSchema: z.object({ userId: z.string() }),
  outputSchema: z.object({
    user: z.any(),
    profile: z.any().nullable(),
    points: z.any().nullable(),
    items: z.array(z.any()),
    barters: z.array(z.any()),
    serviceBarters: z.array(z.any()),
    violations: z.array(z.any()),
    reviews: z.array(z.any()),
    violationCount: z.number(),
    affiliate: z.object({
      totalReferred: z.number(),
      completedReferrals: z.number(),
      totalBonus: z.number(),
      tierId: z.string(),
      tierName: z.string(),
      tierEmoji: z.string(),
      pointsPerReferral: z.number(),
      boostSlots: z.number(),
      referralCode: z.string(),
      recentReferrals: z.array(z.object({
        referredName: z.string(),
        referredEmail: z.string(),
        status: z.string(),
        bonusPoints: z.number(),
        createdAt: z.string().nullable(),
      })),
    }),
  }),
  execute: async ({ input }) => {
    const { userId } = input;

    // Get auth user
    const usersRes = await zite.auth.findAllUsers({
      filters: { id: userId },
      limit: 1,
    });
    const user = usersRes.records[0] ?? null;

    // Profile
    const profileRes = await zite.userProfiles.findAll({ filters: { user: userId }, limit: 1 });
    const profile = profileRes.records[0] ?? null;

    // Points
    const pointsRes = await zite.userPoints.findAll({ filters: { user: userId }, limit: 1 });
    const points = pointsRes.records[0] ?? null;

    // Items
    const itemsRes = await zite.sql({
      query: `
        SELECT id, "title", "status", "condition", "location", "viewsCount", "likesCount",
          created_at AS "createdAt"
        FROM "Items"
        WHERE "owner"->>0 = $1
        ORDER BY created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Barters (as initiator or partner)
    const bartersRes = await zite.sql({
      query: `
        SELECT b.id, b."title", b."status", b.created_at AS "createdAt", b."completedAt",
          u1."name" AS "initiatorName", u2."name" AS "partnerName"
        FROM "BarterHistory" b
        LEFT JOIN "ziteUsers" u1 ON u1.id = b."initiator"->>0
        LEFT JOIN "ziteUsers" u2 ON u2.id = b."partner"->>0
        WHERE b."initiator"->>0 = $1 OR b."partner"->>0 = $1
        ORDER BY b.created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Service Barters
    const serviceBartersRes = await zite.sql({
      query: `
        SELECT sb.id, sb."title", sb."status", sb.created_at AS "createdAt", sb."completedAt",
          sb."notes", sb."deadlineDays",
          u1."name" AS "itemOwnerName", u1."email" AS "itemOwnerEmail",
          u2."name" AS "providerName", u2."email" AS "providerEmail",
          i."title" AS "itemTitle",
          s."title" AS "serviceTitle"
        FROM "ServiceBarters" sb
        LEFT JOIN "ziteUsers" u1 ON u1.id = sb."itemOwner"->>0
        LEFT JOIN "ziteUsers" u2 ON u2.id = sb."serviceProvider"->>0
        LEFT JOIN "Items" i ON i.id = sb."offeredItem"->>0
        LEFT JOIN "Services" s ON s.id = sb."requestedService"->>0
        WHERE sb."itemOwner"->>0 = $1 OR sb."serviceProvider"->>0 = $1
        ORDER BY sb.created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Violations
    const violationsRes = await zite.sql({
      query: `
        SELECT id, "violationType", "severity", "minusPoints", "status", "notes",
          created_at AS "createdAt"
        FROM "Violations"
        WHERE "user"->>0 = $1
        ORDER BY created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Active violation count
    const countRes = await zite.sql({
      query: `SELECT COUNT(*) AS cnt FROM "Violations" WHERE "user"->>0 = $1 AND "status" = 'Aktif'`,
      params: [userId],
    });

    // Reviews received
    const reviewsRes = await zite.sql({
      query: `
        SELECT r."rating", r."comment", r."aspect", r.created_at AS "createdAt",
          u."name" AS "reviewerName"
        FROM "BarterReviews" r
        LEFT JOIN "ziteUsers" u ON u.id = r."reviewer"->>0
        WHERE r."reviewee"->>0 = $1
        ORDER BY r.created_at DESC LIMIT 20
      `,
      params: [userId],
    });

    // Affiliate stats
    const affResult = await zite.sql({
      query: `
        SELECT
          COUNT(*) AS "totalReferred",
          COUNT(*) FILTER (WHERE r."status" = 'Completed') AS "completedReferrals",
          COALESCE(SUM(r."bonusPoints") FILTER (WHERE r."status" = 'Completed'), 0) AS "totalBonus"
        FROM "Referrals" r
        WHERE r."referrer"->>0 = $1
      `,
      params: [userId],
    });
    const completedRefs = Number(affResult.rows[0]?.completedReferrals ?? 0);
    const tier = getAffiliateTier(completedRefs);
    const codeBase = userId.replace(/-/g, '').slice(0, 8).toUpperCase();

    // Recent referrals
    const recentRefsResult = await zite.sql({
      query: `
        SELECT
          COALESCE(referred."name", referred."email", 'Pengguna') AS "referredName",
          COALESCE(referred."email", '') AS "referredEmail",
          r."status",
          COALESCE(r."bonusPoints", 0) AS "bonusPoints",
          r.created_at AS "createdAt"
        FROM "Referrals" r
        LEFT JOIN "ziteUsers" referred ON referred.id = r."referredUser"->>0
        WHERE r."referrer"->>0 = $1
        ORDER BY r.created_at DESC
        LIMIT 10
      `,
      params: [userId],
    });

    return {
      user: user ? {
        id: user.id,
        name: user.name,
        email: user.email,
        image: user.image,
      } : null,
      profile: profile ? {
        displayName: profile.displayName,
        phone: profile.phone,
        bio: profile.bio,
        city: profile.city,
        province: profile.province,
        address: profile.address,
        postalCode: profile.postalCode,
        phoneVerified: profile.phoneVerified,
        addressVerified: profile.addressVerified,
        banned: (profile as any).banned ?? false,
        bannedReason: (profile as any).bannedReason ?? null,
        instagram: profile.instagram || '',
        twitter: profile.twitter || '',
        whatsApp: profile.whatsApp || '',
        mutariPassword: profile.mutariPassword || '',
      } : null,
      points: points ? {
        totalPoints: points.totalPoints,
        itemsUploaded: points.itemsUploaded,
        bartersCompleted: points.bartersCompleted,
        likesReceived: points.likesReceived,
        currentBadge: points.currentBadge,
      } : null,
      items: itemsRes.rows.map(r => ({
        id: String(r.id), title: String(r.title ?? ''), status: String(r.status ?? ''),
        condition: String(r.condition ?? ''), location: String(r.location ?? ''),
        viewsCount: Number(r.viewsCount ?? 0), likesCount: Number(r.likesCount ?? 0),
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
      barters: bartersRes.rows.map(r => ({
        id: String(r.id), title: String(r.title ?? ''), status: String(r.status ?? ''),
        createdAt: r.createdAt ? String(r.createdAt) : null,
        completedAt: r.completedAt ? String(r.completedAt) : null,
        initiatorName: String(r.initiatorName ?? ''), partnerName: String(r.partnerName ?? ''),
      })),
      serviceBarters: serviceBartersRes.rows.map(r => ({
        id: String(r.id), title: String(r.title ?? ''), status: String(r.status ?? ''),
        createdAt: r.createdAt ? String(r.createdAt) : null,
        completedAt: r.completedAt ? String(r.completedAt) : null,
        notes: r.notes ? String(r.notes) : null,
        deadlineDays: r.deadlineDays ? Number(r.deadlineDays) : null,
        itemOwnerName: String(r.itemOwnerName ?? ''), itemOwnerEmail: String(r.itemOwnerEmail ?? ''),
        providerName: String(r.providerName ?? ''), providerEmail: String(r.providerEmail ?? ''),
        itemTitle: String(r.itemTitle ?? ''), serviceTitle: String(r.serviceTitle ?? ''),
      })),
      violations: violationsRes.rows.map(r => ({
        id: String(r.id), violationType: String(r.violationType ?? ''),
        severity: String(r.severity ?? ''), minusPoints: Number(r.minusPoints ?? 0),
        status: String(r.status ?? ''), notes: r.notes ? String(r.notes) : null,
        createdAt: r.createdAt ? String(r.createdAt) : null,
      })),
      reviews: reviewsRes.rows.map(r => ({
        rating: Number(r.rating ?? 0), comment: r.comment ? String(r.comment) : null,
        aspect: r.aspect ? String(r.aspect) : null, createdAt: r.createdAt ? String(r.createdAt) : null,
        reviewerName: String(r.reviewerName ?? ''),
      })),
      violationCount: Number(countRes.rows[0]?.cnt ?? 0),
      affiliate: {
        totalReferred: Number(affResult.rows[0]?.totalReferred ?? 0),
        completedReferrals: completedRefs,
        totalBonus: Number(affResult.rows[0]?.totalBonus ?? 0),
        tierId: tier.id,
        tierName: tier.name,
        tierEmoji: tier.emoji,
        pointsPerReferral: tier.pointsPerReferral,
        boostSlots: tier.boostSlots,
        referralCode: `MUTARI-${codeBase}`,
        recentReferrals: recentRefsResult.rows.map(r => ({
          referredName: String(r.referredName ?? 'Pengguna'),
          referredEmail: String(r.referredEmail ?? ''),
          status: String(r.status ?? 'Pending'),
          bonusPoints: Number(r.bonusPoints ?? 0),
          createdAt: r.createdAt ? String(r.createdAt) : null,
        })),
      },
    };
  },
});

