      badgeParticipant: input.badgeParticipant ?? null,
      inviteBonusPoints: input.inviteBonusPoints ?? null,
      maxInvites: input.maxInvites ?? null,
      visibility: input.visibility ?? 'Publik',
      icon: input.icon ?? null,
    };

    if (input.id) {
      await zite.challenges.update({ id: input.id, record });
