        record: {
          action: 'Create Challenge',
          adminEmail: context.user.email,
          adminName: context.user.firstName ?? context.user.email,
          targetType: 'Challenge',
          targetId: created.id,
          targetName: input.title,
          details: `Type: ${input.type}, Status: ${input.status ?? 'Draft'}`,
        },
      });
      return { success: true, id: created.id };
    }
  },
});

