        details: `Action: ${input.action}`,
      },
    });
    return { success: true };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const statusLabels: Record<string, string> = {
  'Menunggu Review': 'Menunggu Review',
  'Aktif': 'Aktif',
  'Sudah Diperingatkan': 'Sudah Diperingatkan',
  'Banding': 'Banding',
  'Kedaluwarsa': 'Kedaluwarsa',
  'Dicabut': 'Dicabut',
  'Ditolak': 'Ditolak',
};

const THRESHOLDS = { WARNING: -20, SUSPENSION: -50, BAN: -75 };

export default createEndpoint({
  description: 'Mengubah status pelanggaran — jika disetujui (Aktif) maka poin dikurangi dan sanksi diterapkan; jika ditolak maka pelapor bisa kena sanksi',
  inputSchema: z.object({
    violationId: z.string(),
    status: z.enum(['Aktif', 'Sudah Diperingatkan', 'Banding', 'Kedaluwarsa', 'Dicabut', 'Ditolak', 'Menunggu Review']),
    adminNotes: z.string().optional(),
    sanctionReporter: z.boolean().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), action: z.string().optional() }),
  execute: async ({ input, context }) => {
    const violation = await zite.violations.findOne({ id: input.violationId });
    if (!violation) throw new Error('Pelanggaran tidak ditemukan');

    const oldStatus = violation.status || 'Menunggu Review';
    const reportedUserId = Array.isArray(violation.user) ? violation.user[0] : violation.user;
    const reporterId = Array.isArray(violation.reportedBy) ? violation.reportedBy[0] : violation.reportedBy;
    const adminName = context.user.firstName ? `${context.user.firstName} ${context.user.lastName || ''}`.trim() : context.user.email;

    // Update violation status + admin notes
    await zite.violations.update({
      id: input.violationId,
      record: {
        status: input.status,
        ...(input.adminNotes ? { adminNotes: input.adminNotes } : {}),
      },
    });

    let actionTaken = `Status: ${oldStatus} → ${input.status}`;

    // ─── APPROVED: "Menunggu Review" → "Aktif" ───
    // Now apply the actual punishment (deduct points, enforce thresholds)
    if (input.status === 'Aktif' && oldStatus === 'Menunggu Review' && reportedUserId) {
      const minusPoints = violation.minusPoints ?? -1;
      const label = violation.violationType || 'Pelanggaran';

      // Deduct points from reported user
      await zite.pointHistory.create({
        record: {
          activity: `Pelanggaran Disetujui: ${label}`,
          user: reportedUserId,
          points: minusPoints,
          activityType: 'violation',
        },
      });

      const userPoints = await zite.userPoints.findOne({
        filters: { user: reportedUserId },
      });
      if (userPoints) {
        const newTotal = Math.max(0, (userPoints.totalPoints ?? 0) + minusPoints);
        await zite.userPoints.update({
          id: userPoints.id,
          record: { totalPoints: newTotal },
        });
      }

      // Calculate total minus for threshold enforcement
      const { records: allViolations } = await zite.violations.findAll({
        filters: { user: reportedUserId, status: 'Aktif' },
        limit: 500,
      });
      const totalMinus = allViolations.reduce((sum, v) => sum + (v.minusPoints ?? 0), 0);

      // Auto-enforce thresholds
      if (totalMinus <= THRESHOLDS.BAN) {
        const profileRes = await zite.userProfiles.findAll({
          filters: { user: reportedUserId },
          limit: 1,
        });
        if (profileRes.records.length > 0) {
          await zite.userProfiles.update({
            id: profileRes.records[0].id,
            record: {
              banned: true,
              bannedReason: `Diblokir oleh admin: total ${totalMinus} minus poin (batas: ${THRESHOLDS.BAN}). Pelanggaran: ${label}.`,
            },
          });
        }
        await zite.notifications.create({
          record: {
            title: '🚫 Akun Diblokir',
            body: `Akun kamu diblokir karena total minus poin mencapai ${totalMinus}. Pelanggaran terakhir: ${label}. Hubungi admin jika merasa ini kesalahan.`,
            type: 'System',
            recipient: reportedUserId,
            read: false,
            linkPath: '/wallet',
          },
        });
        actionTaken += ' → Auto-ban diterapkan';
      } else if (totalMinus <= THRESHOLDS.SUSPENSION) {
        await zite.notifications.create({
          record: {
            title: '⛔ Akun Ditangguhkan Sementara',
            body: `Akun kamu ditangguhkan sementara. Total minus poin: ${totalMinus}. Pelanggaran: ${label}.`,
            type: 'System',
            recipient: reportedUserId,
            read: false,
            linkPath: '/wallet',
          },
        });
        actionTaken += ' → Suspensi diterapkan';
      } else if (totalMinus <= THRESHOLDS.WARNING) {
        await zite.notifications.create({
          record: {
            title: '⚠️ Peringatan Resmi',
            body: `Kamu mendapat peringatan resmi! Total minus poin: ${totalMinus}. Pelanggaran: ${label}.`,
            type: 'System',
            recipient: reportedUserId,
            read: false,
            linkPath: '/wallet',
          },
        });
        actionTaken += ' → Peringatan diterapkan';
      } else {
        await zite.notifications.create({
          record: {
            title: `⚠️ Pelanggaran Dikonfirmasi: ${label}`,
            body: `Admin telah mengonfirmasi pelanggaran "${label}". Kamu dikenakan ${minusPoints} MP.${input.adminNotes ? ` Catatan admin: ${input.adminNotes}` : ''}`,
            type: 'System',
            recipient: reportedUserId,
            read: false,
            linkPath: '/wallet',
          },
        });
      }

      // Notify reporter that their report was approved
      if (reporterId) {
        await zite.notifications.create({
          record: {
            title: '✅ Laporan Disetujui',
            body: `Laporan kamu terhadap "${label}" telah disetujui oleh admin. Sanksi telah diterapkan kepada pihak terlapor.`,
            type: 'System',
            recipient: reporterId,
            read: false,
            linkPath: '/wallet',
          },
        });
      }
    }

    // ─── REJECTED: "Menunggu Review" → "Ditolak" ───
    // Notify reporter; optionally sanction reporter for false report
    if (input.status === 'Ditolak' && oldStatus === 'Menunggu Review') {
      // Notify reported user — cleared
      if (reportedUserId) {
        await zite.notifications.create({
          record: {
            title: '✅ Laporan Ditolak — Kamu Bersih',
            body: `Laporan "${violation.violationType || 'Pelanggaran'}" terhadap kamu telah ditolak oleh admin. Tidak ada sanksi yang diterapkan.${input.adminNotes ? ` Catatan: ${input.adminNotes}` : ''}`,
            type: 'System',
            recipient: reportedUserId,
            read: false,
            linkPath: '/wallet',
          },
        });
      }

      // Notify reporter — rejected
      if (reporterId) {
        await zite.notifications.create({
          record: {
            title: '❌ Laporan Ditolak & Sanksi -10 MP',
            body: `Laporan kamu telah ditolak oleh admin. Kamu dikenakan sanksi -10 MP karena laporan tidak valid.${input.adminNotes ? ` Alasan: ${input.adminNotes}` : ''}`,
            type: 'System',
            recipient: reporterId,
            read: false,
            linkPath: '/wallet',
          },
        });
      }

      // Always sanction the reporter when report is rejected (-10 MP)
      if (reporterId) {
        const falseReportPoints = -10;

        await zite.violations.create({
          record: {
            label: 'Laporan Palsu',
            user: reporterId,
            violationType: 'Pelanggaran',
            severity: 'Sedang',
            minusPoints: falseReportPoints,
            barter: violation.barter || null,
            reportedBy: null,
            notes: `Sanksi otomatis: laporan palsu terhadap pelanggaran "${violation.violationType}". Ditolak oleh admin ${adminName}.${input.adminNotes ? ` Catatan: ${input.adminNotes}` : ''}`,
            status: 'Aktif',
            evidence: null,
          } as any,
        });

        await zite.pointHistory.create({
          record: {
            activity: 'Sanksi: Laporan Palsu',
            user: reporterId,
            points: falseReportPoints,
            activityType: 'violation',
          },
        });

        const reporterPoints = await zite.userPoints.findOne({
          filters: { user: reporterId },
        });
        if (reporterPoints) {
          const newTotal = Math.max(0, (reporterPoints.totalPoints ?? 0) + falseReportPoints);
          await zite.userPoints.update({
            id: reporterPoints.id,
            record: { totalPoints: newTotal },
          });
        }

        await zite.notifications.create({
          record: {
            title: '⚠️ Sanksi: Laporan Palsu',
            body: `Kamu dikenakan ${falseReportPoints} MP karena laporan palsu. Laporan yang tidak berdasar merugikan komunitas MUTARI.`,
            type: 'System',
            recipient: reporterId,
            read: false,
            linkPath: '/wallet',
          },
        });

        actionTaken += ' → Pelapor disanksi (Laporan Palsu -10 MP)';
      }
    }

    // For other status changes, just notify
    if (input.status !== 'Aktif' && input.status !== 'Ditolak' && reportedUserId) {
      const statusEmoji = input.status === 'Dicabut' ? '✅' : input.status === 'Sudah Diperingatkan' ? '⚠️' : '📋';
      await zite.notifications.create({
        record: {
          title: `${statusEmoji} Status Pelanggaran Diperbarui`,
          body: `Pelanggaran "${violation.violationType || 'Pelanggaran'}" diubah dari "${statusLabels[oldStatus] || oldStatus}" ke "${statusLabels[input.status]}".${input.adminNotes ? ` Catatan: ${input.adminNotes}` : ''}`,
          type: 'System',
          recipient: reportedUserId,
          read: false,
          linkPath: '/profile',
        },
      });
    }

    // Audit log
    await zite.adminAuditLog.create({
      record: {
        action: 'Review Pelanggaran',
        adminEmail: context.user.email,
        adminName,
        targetType: 'violation',
        targetId: input.violationId,
        targetName: violation.violationType || null,
        details: actionTaken + (input.adminNotes ? ` | Catatan: ${input.adminNotes}` : ''),
      },
    });

    return { success: true, action: actionTaken };
  },
});

