import { useEffect, useState, useRef } from 'react';
import { getAdminAlerts } from 'zitejs/api';
import { useNavigate } from 'react-router-dom';
import { Bell, AlertTriangle, ChevronRight } from 'lucide-react';
import { Button } from '@project/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@project/components/ui/popover';
import { cn } from '@project/components/lib/utils';
import { formatDistanceToNow } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';

type Alert = {
  id: string;
  violationType: string;
  severity: string;
  status: string;
  userName: string;
  reporterName: string;
  createdAt: string | null;
  notes: string | null;
};

export default function AlertBell() {
  const [totalActive, setTotalActive] = useState(0);
  const [totalBerat, setTotalBerat] = useState(0);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [open, setOpen] = useState(false);
  const [pulse, setPulse] = useState(false);
  const navigate = useNavigate();
  const prevBeratRef = useRef(0);

  // Poll every 30 seconds
  useEffect(() => {
    const fetchAlerts = async () => {
      try {
        const res = await getAdminAlerts({});
        setTotalActive(res.totalActive);
        setTotalBerat(res.totalBerat);
        setAlerts(res.recentAlerts as Alert[]);
        // Pulse animation when new severe violations appear
        if (res.totalBerat > 0 && res.totalBerat > prevBeratRef.current) {
          setPulse(true);
          setTimeout(() => setPulse(false), 3000);
        }
        prevBeratRef.current = res.totalBerat;
      } catch { /* silent */ }
    };
    fetchAlerts();
    const interval = setInterval(fetchAlerts, 30000);
    return () => clearInterval(interval);
  }, []);

  const severityColor = (s: string) => {
    if (s === 'Berat') return 'bg-red-500';
    if (s === 'Sedang') return 'bg-amber-500';
    return 'bg-blue-500';
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button className="relative p-2 rounded-lg hover:bg-muted transition-colors">
          <Bell size={20} className={cn(
            'transition-colors',
            totalBerat > 0 ? 'text-red-500' : totalActive > 0 ? 'text-amber-500' : 'text-muted-foreground'
          )} />
          {totalActive > 0 && (
            <>
              <span className={cn(
                'absolute -top-0.5 -right-0.5 flex h-5 min-w-5 items-center justify-center rounded-full px-1 text-[10px] font-bold text-white',
                totalBerat > 0 ? 'bg-red-500' : 'bg-amber-500'
              )}>
                {totalActive}
              </span>
              {(pulse || totalBerat > 0) && (
                <span className={cn(
                  'absolute -top-0.5 -right-0.5 h-5 w-5 rounded-full animate-ping',
                  totalBerat > 0 ? 'bg-red-400' : 'bg-amber-400'
                )} />
              )}
            </>
          )}
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-96 p-0" align="end" sideOffset={8}>
        <div className="flex items-center justify-between border-b px-4 py-3">
          <div className="flex items-center gap-2">
            <AlertTriangle size={16} className="text-destructive" />
            <p className="font-semibold text-sm">Laporan Pelanggaran</p>
          </div>
          {totalActive > 0 && (
            <span className={cn(
              'rounded-full px-2 py-0.5 text-xs font-bold text-white',
              totalBerat > 0 ? 'bg-red-500' : 'bg-amber-500'
            )}>
              {totalActive} aktif
            </span>
          )}
        </div>

        {totalBerat > 0 && (
          <div className="bg-red-50 border-b border-red-100 px-4 py-2.5 flex items-center gap-2">
            <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse" />
            <p className="text-xs font-semibold text-red-700">
              {totalBerat} pelanggaran BERAT membutuhkan penanganan segera!
            </p>
          </div>
        )}

        <div className="max-h-80 overflow-y-auto divide-y">
          {alerts.length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">Tidak ada laporan aktif 🎉</p>
          ) : (
            alerts.map((a) => (
              <button
                key={a.id}
                className="w-full text-left px-4 py-3 hover:bg-muted/50 transition-colors"
                onClick={() => { setOpen(false); navigate('/violations/' + a.id); }}
              >
                <div className="flex items-start gap-2.5">
                  <div className={cn('mt-1 h-2.5 w-2.5 shrink-0 rounded-full', severityColor(a.severity))} />
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <p className="text-sm font-semibold truncate">{a.violationType}</p>
                      <SeverityTag severity={a.severity} />
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Pelanggar: <span className="font-medium text-foreground">{a.userName}</span>
                    </p>
                    {a.reporterName && (
                      <p className="text-xs text-muted-foreground">Dilaporkan oleh: {a.reporterName}</p>
                    )}
                    {a.notes && (
                      <p className="text-xs text-muted-foreground mt-0.5 line-clamp-1">{a.notes}</p>
                    )}
                    {a.createdAt && (
                      <p className="text-[10px] text-muted-foreground mt-1">
                        {formatDistanceToNow(new Date(a.createdAt), { addSuffix: true, locale: idLocale })}
                      </p>
                    )}
                  </div>
                </div>
              </button>
            ))
          )}
        </div>

        {totalActive > 0 && (
          <div className="border-t p-2">
            <Button
              variant="ghost"
              size="sm"
              className="w-full justify-between text-xs"
              onClick={() => { setOpen(false); navigate('/violations'); }}
            >
              Lihat semua laporan
              <ChevronRight size={14} />
            </Button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  );
}

function SeverityTag({ severity }: { severity: string }) {
  const c: Record<string, string> = {
    Berat: 'bg-red-100 text-red-700',
    Sedang: 'bg-amber-100 text-amber-700',
    Ringan: 'bg-blue-100 text-blue-700',
  };
  return (
    <span className={cn('shrink-0 rounded px-1.5 py-0.5 text-[10px] font-bold', c[severity] ?? 'bg-muted text-muted-foreground')}>
      {severity.toUpperCase()}
    </span>
  );
}

import { useState, useEffect } from 'react';
import { manageChallenge } from 'zitejs/api';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from '@project/components/ui/dialog';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Textarea } from '@project/components/ui/textarea';
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from '@project/components/ui/select';
import { toast } from 'sonner';

type Challenge = {
  id: string;
  title?: string;
  description?: string;
  type?: string;
  categoryFilter?: string;
  startDate?: string;
  endDate?: string;
  status?: string;
  minTarget?: number;
  reward1st?: number;
  reward2nd?: number;
  reward3rd?: number;
  participationReward?: number;
  badge1st?: string;
  badgeParticipant?: string;
  inviteBonusPoints?: number;
  maxInvites?: number;
  visibility?: string;
  icon?: string;
};

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  editing: Challenge | null;
  onSaved: () => void;
}

const defaultForm = {
  title: '',
  description: '',
  type: 'barter_terbanyak',
  categoryFilter: '',
  startDate: '',
  endDate: '',
  status: 'draft',
  minTarget: '',
  reward1st: '',
  reward2nd: '',
  reward3rd: '',
  participationReward: '',
  badge1st: '',
  badgeParticipant: '',
  inviteBonusPoints: '',
  maxInvites: '10',
  visibility: 'public',
  icon: '',
};

const typeMap: Record<string, string> = {
  'Barter Terbanyak': 'barter_terbanyak',
  'Upload Terbanyak': 'upload_terbanyak',
  'Rating Tertinggi': 'rating_tertinggi',
  'Kategori Spesifik': 'kategori_spesifik',
  'Referral Race': 'referral_race',
  'Custom Target': 'custom',
};
const typeMapReverse: Record<string, string> = Object.fromEntries(
  Object.entries(typeMap).map(([k, v]) => [v, k])
);
const statusMap: Record<string, string> = {
  Draft: 'draft', 'Akan Datang': 'upcoming', Aktif: 'active', Selesai: 'ended', Dibatalkan: 'cancelled',
};
const statusMapReverse: Record<string, string> = Object.fromEntries(
  Object.entries(statusMap).map(([k, v]) => [v, k])
);
const visMap: Record<string, string> = { Publik: 'public', Eksklusif: 'exclusive' };
const visMapReverse: Record<string, string> = Object.fromEntries(
  Object.entries(visMap).map(([k, v]) => [v, k])
);

function toLocalDatetime(iso?: string) {
  if (!iso) return '';
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export default function ChallengeFormDialog({ open, onOpenChange, editing, onSaved }: Props) {
  const [form, setForm] = useState(defaultForm);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (editing) {
      setForm({
        title: editing.title ?? '',
        description: editing.description ?? '',
        type: typeMap[editing.type ?? ''] ?? editing.type ?? 'barter_terbanyak',
        categoryFilter: editing.categoryFilter ?? '',
        startDate: toLocalDatetime(editing.startDate),
        endDate: toLocalDatetime(editing.endDate),
        status: statusMap[editing.status ?? ''] ?? editing.status ?? 'draft',
        minTarget: editing.minTarget != null ? String(editing.minTarget) : '',
        reward1st: editing.reward1st != null ? String(editing.reward1st) : '',
        reward2nd: editing.reward2nd != null ? String(editing.reward2nd) : '',
        reward3rd: editing.reward3rd != null ? String(editing.reward3rd) : '',
        participationReward: editing.participationReward != null ? String(editing.participationReward) : '',
        badge1st: editing.badge1st ?? '',
        badgeParticipant: editing.badgeParticipant ?? '',
        inviteBonusPoints: editing.inviteBonusPoints != null ? String(editing.inviteBonusPoints) : '',
        maxInvites: editing.maxInvites != null ? String(editing.maxInvites) : '10',
        visibility: visMap[editing.visibility ?? ''] ?? 'public',
        icon: editing.icon ?? '',
      });
    } else {
      setForm(defaultForm);
    }
  }, [editing, open]);

  const set = (k: keyof typeof form, v: string) => setForm(prev => ({ ...prev, [k]: v }));

  const handleSave = async () => {
    if (!form.title.trim()) { toast.error('Judul wajib diisi'); return; }
    if (!form.startDate || !form.endDate) { toast.error('Tanggal mulai & selesai wajib diisi'); return; }
    setSaving(true);
    try {
      await manageChallenge({
        id: editing?.id,
        title: form.title.trim(),
        description: form.description.trim() || undefined,
        type: typeMapReverse[form.type] ?? form.type,
        categoryFilter: form.categoryFilter.trim() || undefined,
        startDate: new Date(form.startDate).toISOString(),
        endDate: new Date(form.endDate).toISOString(),
        status: statusMapReverse[form.status] ?? form.status,
        minTarget: form.minTarget ? Number(form.minTarget) : undefined,
        reward1st: form.reward1st ? Number(form.reward1st) : undefined,
        reward2nd: form.reward2nd ? Number(form.reward2nd) : undefined,
        reward3rd: form.reward3rd ? Number(form.reward3rd) : undefined,
        participationReward: form.participationReward ? Number(form.participationReward) : undefined,
        badge1st: form.badge1st.trim() || undefined,
        badgeParticipant: form.badgeParticipant.trim() || undefined,
        inviteBonusPoints: form.inviteBonusPoints ? Number(form.inviteBonusPoints) : undefined,
        maxInvites: form.maxInvites ? Number(form.maxInvites) : undefined,
        visibility: visMapReverse[form.visibility] ?? form.visibility,
        icon: form.icon.trim() || undefined,
      });
      toast.success(editing ? 'Challenge diperbarui' : 'Challenge dibuat');
      onSaved();
    } catch {
      toast.error('Gagal menyimpan');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{editing ? '✏️ Edit Challenge' : '🏆 Buat Challenge Baru'}</DialogTitle>
        </DialogHeader>

        <div className="space-y-5 py-2">
          {/* Basic Info */}
          <section className="space-y-3">
            <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">Info Dasar</h3>
            <div className="grid grid-cols-[1fr_80px] gap-3">
              <div>
                <Label>Judul Challenge *</Label>
                <Input value={form.title} onChange={e => set('title', e.target.value)} placeholder="Barter Fest Agustus 🇮🇩" />
              </div>
              <div>
                <Label>Icon</Label>
                <Input value={form.icon} onChange={e => set('icon', e.target.value)} placeholder="🏆" className="text-center text-lg" />
              </div>
            </div>
            <div>
              <Label>Deskripsi</Label>
              <Textarea value={form.description} onChange={e => set('description', e.target.value)} placeholder="Selesaikan barter sebanyak-banyaknya..." rows={2} />
            </div>
          </section>

          {/* Type & Timing */}
          <section className="space-y-3">
            <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">Tipe & Waktu</h3>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Tipe Challenge</Label>
                <Select value={form.type} onValueChange={v => set('type', v)}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="barter_terbanyak">🔄 Barter Terbanyak</SelectItem>
                    <SelectItem value="upload_terbanyak">📦 Upload Terbanyak</SelectItem>
                    <SelectItem value="rating_tertinggi">⭐ Rating Tertinggi</SelectItem>
                    <SelectItem value="kategori_spesifik">🏷️ Kategori Spesifik</SelectItem>
                    <SelectItem value="referral_race">🤝 Referral Race</SelectItem>
                    <SelectItem value="custom">🎯 Custom Target</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Status</Label>
                <Select value={form.status} onValueChange={v => set('status', v)}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">📝 Draft</SelectItem>
                    <SelectItem value="upcoming">📅 Akan Datang</SelectItem>
                    <SelectItem value="active">🟢 Aktif</SelectItem>
                    <SelectItem value="ended">🏁 Selesai</SelectItem>
                    <SelectItem value="cancelled">❌ Dibatalkan</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            {form.type === 'kategori_spesifik' && (
              <div>
                <Label>Filter Kategori</Label>
                <Input value={form.categoryFilter} onChange={e => set('categoryFilter', e.target.value)} placeholder="Elektronik" />
              </div>
            )}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Tanggal Mulai *</Label>
                <Input type="datetime-local" value={form.startDate} onChange={e => set('startDate', e.target.value)} />
              </div>
              <div>
                <Label>Tanggal Selesai *</Label>
                <Input type="datetime-local" value={form.endDate} onChange={e => set('endDate', e.target.value)} />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Target Minimum</Label>
                <Input type="number" value={form.minTarget} onChange={e => set('minTarget', e.target.value)} placeholder="3" />
              </div>
              <div>
                <Label>Visibility</Label>
                <Select value={form.visibility} onValueChange={v => set('visibility', v)}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="public">🌐 Publik</SelectItem>
                    <SelectItem value="exclusive">🔒 Eksklusif</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </section>

          {/* Rewards */}
          <section className="space-y-3">
            <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">Hadiah (Poin)</h3>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
              <div>
                <Label>🥇 Juara 1</Label>
                <Input type="number" value={form.reward1st} onChange={e => set('reward1st', e.target.value)} placeholder="500" />
              </div>
              <div>
                <Label>🥈 Juara 2</Label>
                <Input type="number" value={form.reward2nd} onChange={e => set('reward2nd', e.target.value)} placeholder="300" />
              </div>
              <div>
                <Label>🥉 Juara 3</Label>
                <Input type="number" value={form.reward3rd} onChange={e => set('reward3rd', e.target.value)} placeholder="150" />
              </div>
              <div>
                <Label>🎁 Partisipasi</Label>
                <Input type="number" value={form.participationReward} onChange={e => set('participationReward', e.target.value)} placeholder="50" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Badge Juara 1</Label>
                <Input value={form.badge1st} onChange={e => set('badge1st', e.target.value)} placeholder="Champion Agustus" />
              </div>
              <div>
                <Label>Badge Peserta</Label>
                <Input value={form.badgeParticipant} onChange={e => set('badgeParticipant', e.target.value)} placeholder="Peserta Barter Fest" />
              </div>
            </div>
          </section>

          {/* Invite Bonus */}
          <section className="space-y-3">
            <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wide">Bonus Ajak Teman</h3>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <Label>Poin per Teman Aktif</Label>
                <Input type="number" value={form.inviteBonusPoints} onChange={e => set('inviteBonusPoints', e.target.value)} placeholder="50" />
              </div>
              <div>
                <Label>Maks Undangan</Label>
                <Input type="number" value={form.maxInvites} onChange={e => set('maxInvites', e.target.value)} placeholder="10" />
              </div>
            </div>
          </section>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Batal</Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving ? 'Menyimpan...' : editing ? 'Simpan Perubahan' : 'Buat Challenge'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

