// MUTARI Affiliate Tier System (shared with beranda-barter app)
export interface AffiliateTier {
  id: string;
  name: string;
  emoji: string;
  minReferrals: number;
  maxReferrals: number | null;
  pointsPerReferral: number;
  boostSlots: number;
  boostDurationDays: number;
  description: string;
}

export const AFFILIATE_TIERS: AffiliateTier[] = [
  {
    id: 'bronze',
    name: 'Bronze Affiliate',
    emoji: '🥉',
    minReferrals: 0,
    maxReferrals: 4,
    pointsPerReferral: 50,
    boostSlots: 0,
    boostDurationDays: 0,
    description: 'Mulai perjalanan affiliate',
  },
  {
    id: 'silver',
    name: 'Silver Affiliate',
    emoji: '🥈',
    minReferrals: 5,
    maxReferrals: 14,
    pointsPerReferral: 75,
    boostSlots: 2,
    boostDurationDays: 3,
    description: '+75 MP/referral + 2 boost gratis/bulan',
  },
  {
    id: 'gold',
    name: 'Gold Affiliate',
    emoji: '🏆',
    minReferrals: 15,
    maxReferrals: null,
    pointsPerReferral: 100,
    boostSlots: 5,
    boostDurationDays: 7,
    description: '+100 MP/referral + 5 boost gratis/bulan',
  },
];

export function getAffiliateTier(completedReferrals: number): AffiliateTier {
  for (let i = AFFILIATE_TIERS.length - 1; i >= 0; i--) {
    if (completedReferrals >= AFFILIATE_TIERS[i].minReferrals) return AFFILIATE_TIERS[i];
  }
  return AFFILIATE_TIERS[0];
}

