import { useEffect, useState, useCallback } from 'react';
import { getAuditLog } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Skeleton } from '@project/components/ui/skeleton';
import {
  ClipboardList, ChevronLeft, ChevronRight, User, Package, ArrowLeftRight,
  ShieldCheck, ShieldBan, Coins, Download, FileWarning, Search,
} from 'lucide-react';
import { Input } from '@project/components/ui/input';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';

const PAGE_SIZE = 20;

const actionIcons: Record<string, any> = {
  'Ban User': ShieldBan, 'Unban User': ShieldCheck,
  'Verifikasi Alamat': ShieldCheck, 'Cabut Verifikasi Alamat': ShieldBan,
  'Verifikasi HP': ShieldCheck, 'Cabut Verifikasi HP': ShieldBan,
  'Adjust Poin': Coins, 'Reset Badge': Coins,
  'Listing approve': Package, 'Listing reject': Package, 'Listing delete': Package,
  'Export users': Download, 'Export listings': Download, 'Export barters': Download,
};

const actionColors: Record<string, string> = {
  'Ban User': 'bg-red-100 text-red-600', 'Unban User': 'bg-emerald-100 text-emerald-600',
  'Verifikasi Alamat': 'bg-emerald-100 text-emerald-600', 'Cabut Verifikasi Alamat': 'bg-red-100 text-red-600',
  'Verifikasi HP': 'bg-emerald-100 text-emerald-600', 'Cabut Verifikasi HP': 'bg-red-100 text-red-600',
  'Adjust Poin': 'bg-amber-100 text-amber-600', 'Reset Badge': 'bg-amber-100 text-amber-600',
};

type LogEntry = {
  id: string; action: string; adminEmail: string; adminName: string;
  targetType: string; targetId: string | null; targetName: string | null;
  details: string | null; timestamp: string;
};

export default function AuditLogPage() {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  const fetchLogs = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getAuditLog({ limit: PAGE_SIZE, offset: page * PAGE_SIZE });
      setLogs(res.logs);
      setTotal(res.total);
    } finally {
      setLoading(false);
    }
  }, [page]);

  useEffect(() => { fetchLogs(); }, [fetchLogs]);

  const totalPages = Math.ceil(total / PAGE_SIZE);
  const filtered = search
    ? logs.filter(l =>
        l.action.toLowerCase().includes(search.toLowerCase()) ||
        l.adminName.toLowerCase().includes(search.toLowerCase()) ||
        l.adminEmail.toLowerCase().includes(search.toLowerCase()) ||
        (l.details || '').toLowerCase().includes(search.toLowerCase())
      )
    : logs;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <ClipboardList size={24} /> Audit Log
        </h1>
        <p className="text-sm text-muted-foreground mt-1">
          Riwayat semua tindakan admin di platform. Total: {total.toLocaleString('id-ID')} log.
        </p>
      </div>

      <div className="relative">
        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
        <Input
          placeholder="Cari aksi, admin, atau detail..."
          value={search} onChange={e => setSearch(e.target.value)}
          className="pl-9"
        />
      </div>

      {loading ? (
        <div className="space-y-3">
          {Array.from({ length: 5 }).map((_, i) => (
            <Skeleton key={i} className="h-20 rounded-xl" />
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <Card>
          <CardContent className="p-12 text-center text-muted-foreground">
            <ClipboardList size={40} className="mx-auto mb-3 opacity-30" />
            <p className="font-medium">Belum ada log aktivitas</p>
            <p className="text-sm">Tindakan admin akan tercatat di sini secara otomatis.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-2">
          {filtered.map(log => {
            const Icon = actionIcons[log.action] || FileWarning;
            const color = actionColors[log.action] || 'bg-muted text-muted-foreground';
            return (
              <Card key={log.id} className="hover:shadow-sm transition-shadow">
                <CardContent className="flex items-start gap-3 p-4">
                  <div className={`shrink-0 flex h-10 w-10 items-center justify-center rounded-xl ${color}`}>
                    <Icon size={18} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-semibold text-sm">{log.action}</span>
                      <span className="text-[10px] text-muted-foreground bg-muted px-1.5 py-0.5 rounded-full">{log.targetType}</span>
                    </div>
                    {log.details && <p className="text-xs text-muted-foreground mt-0.5">{log.details}</p>}
                    <div className="flex items-center gap-3 mt-1.5 text-[11px] text-muted-foreground">
                      <span className="inline-flex items-center gap-1">
                        <User size={10} /> {log.adminName}
                      </span>
                      <span>{fmtTime(log.timestamp)}</span>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-xs text-muted-foreground">
            Hal {page + 1} dari {totalPages}
          </p>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
              <ChevronLeft size={14} className="mr-1" /> Sebelumnya
            </Button>
            <Button variant="outline" size="sm" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
              Selanjutnya <ChevronRight size={14} className="ml-1" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

function fmtTime(d: string) {
  if (!d) return '-';
  try { return format(new Date(d), 'dd MMM yyyy, HH:mm', { locale: idLocale }); } catch { return '-'; }
}

