          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input placeholder="Cari..." className="pl-9" value={search}
            onChange={(e) => { setSearch(e.target.value); debouncedSearch(e.target.value); }} />
        </div>
        <Select value={typeFilter} onValueChange={(v) => { setTypeFilter(v as any); setPage(0); }}>
          <SelectTrigger className="w-40"><SelectValue placeholder="Semua Tipe" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Tipe</SelectItem>
            <SelectItem value="barang">📦 Barter Barang</SelectItem>
            <SelectItem value="jasa">🔧 Barter Jasa</SelectItem>
          </SelectContent>
        </Select>
        <Select value={statusFilter} onValueChange={(v) => { setStatusFilter(v === 'all' ? '' : v); setPage(0); }}>
          <SelectTrigger className="w-40"><SelectValue placeholder="Semua Status" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Status</SelectItem>
            {STATUSES.map((s) => <SelectItem key={s} value={s}>{s}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <div className="space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-24 rounded-xl" />)}</div>
      ) : barters.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Tidak ada transaksi ditemukan</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {barters.map((b) => (
            <Card key={`${b.type}-${b.id}`}>
              <CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="truncate font-semibold text-sm">{b.title || 'Barter'}</p>
                    <TypeBadge type={b.type} />
                    <StatusBadge status={b.status} />
                  </div>
                  <div className="mt-1 grid grid-cols-2 gap-x-4 text-xs text-muted-foreground">
                    <div>
                      <span className="font-medium text-foreground">{b.type === 'jasa' ? 'Pemilik Barang:' : 'Initiator:'}</span> {b.initiatorName}
                      {b.initiatorConfirmed && <span className="text-emerald-600 ml-1">✓</span>}
                    </div>
                    <div>
                      <span className="font-medium text-foreground">{b.type === 'jasa' ? 'Penyedia Jasa:' : 'Partner:'}</span> {b.partnerName}
                      {b.partnerConfirmed && <span className="text-emerald-600 ml-1">✓</span>}
                    </div>
                  </div>
                  {b.type === 'jasa' && (b.itemTitle || b.serviceTitle) && (
                    <p className="mt-1 text-xs text-muted-foreground">
                      {b.itemTitle && <span>📦 {b.itemTitle}</span>}
                      {b.itemTitle && b.serviceTitle && <span> ↔ </span>}
                      {b.serviceTitle && <span>🔧 {b.serviceTitle}</span>}
                    </p>
                  )}
                  {b.codAddress && <p className="mt-1 text-xs text-muted-foreground">📍 {b.codAddress}</p>}
                </div>

                <div className="flex items-center gap-2 shrink-0">
                  <div className="text-right text-xs text-muted-foreground hidden sm:block">
                    <p>{b.createdAt ? format(new Date(b.createdAt), 'dd MMM yyyy', { locale: idLocale }) : '-'}</p>
                    {b.completedAt && <p className="text-emerald-600">Selesai {format(new Date(b.completedAt), 'dd MMM', { locale: idLocale })}</p>}
                  </div>
                  {(b.status === 'Menunggu' || b.status === 'Diterima') && b.type === 'barang' && (
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button size="sm" variant="outline" className="text-destructive border-destructive/20">
                          <Ban size={14} className="mr-1" /> Batalkan
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent>
                        <AlertDialogHeader>
                          <AlertDialogTitle>Batalkan Barter?</AlertDialogTitle>
                          <AlertDialogDescription>Transaksi ini akan dibatalkan oleh admin.</AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel>Tidak</AlertDialogCancel>
                          <AlertDialogAction onClick={() => handleCancel(b.id)}>Ya, Batalkan</AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}

function TypeBadge({ type }: { type: string }) {
  if (type === 'jasa') {
    return (
      <span className="inline-flex items-center gap-1 rounded-full bg-violet-100 text-violet-700 px-2 py-0.5 text-xs font-medium">
        <Wrench size={12} /> Jasa
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-sky-100 text-sky-700 px-2 py-0.5 text-xs font-medium">
      <Package size={12} /> Barang
    </span>
  );
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Menunggu: 'bg-amber-100 text-amber-700',
    Diterima: 'bg-sky-100 text-sky-700',
    Selesai: 'bg-emerald-100 text-emerald-700',
    Dibatalkan: 'bg-red-100 text-red-700',
    'Dalam Pengerjaan': 'bg-blue-100 text-blue-700',
    'Menunggu Bukti': 'bg-orange-100 text-orange-700',
    Expired: 'bg-gray-100 text-gray-700',
  };
  return <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${c[status] ?? 'bg-muted text-muted-foreground'}`}>{status}</span>;
}

