import { useState, useEffect } from 'react';
import { getAdminUsers, getUserItems, boostItem, addUserPoints, addFollowers } from 'zitejs/api';
import type { GetAdminUsersOutputType, GetUserItemsOutputType } from 'zitejs/api';
import { Input } from '@project/components/ui/input';
import { Button } from '@project/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Badge } from '@project/components/ui/badge';
import { toast } from 'sonner';
import { Search, Eye, Heart, Zap, TrendingUp, User, MessageCircle, Star, Users } from 'lucide-react';

type ItemType = GetUserItemsOutputType['items'][0];
type UserType = GetAdminUsersOutputType['users'][0];

export default function BoostPage() {
  const [allUsers, setAllUsers] = useState<UserType[]>([]);
  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingItems, setLoadingItems] = useState(false);
  const [userSearch, setUserSearch] = useState('');
  const [selectedUser, setSelectedUser] = useState<UserType | null>(null);
  const [selected, setSelected] = useState<ItemType | null>(null);
  const [addViews, setAddViews] = useState(0);
  const [addLikes, setAddLikes] = useState(0);
  const [addComments, setAddComments] = useState(0);
  const [boosting, setBoosting] = useState(false);
  const [addPoints, setAddPoints] = useState(0);
  const [pointReason, setPointReason] = useState('');
  const [boostingPoints, setBoostingPoints] = useState(false);
  const [addFollowerCount, setAddFollowerCount] = useState(0);
  const [boostingFollowers, setBoostingFollowers] = useState(false);
  const [currentFollowers, setCurrentFollowers] = useState<number | null>(null);

  useEffect(() => {
    getAdminUsers({ limit: 2000 })
      .then((r) => setAllUsers(r.users))
      .catch(() => toast.error('Gagal memuat pengguna'))
      .finally(() => setLoading(false));
  }, []);

  const displayUsers = userSearch.trim()
    ? allUsers.filter((u) => {
        const q = userSearch.toLowerCase();
        return (
          u.name?.toLowerCase().includes(q) ||
          u.displayName?.toLowerCase().includes(q) ||
          u.email?.toLowerCase().includes(q)
        );
      })
    : [];

  useEffect(() => {
    if (!selectedUser) { setItems([]); setSelected(null); return; }
    setLoadingItems(true);
    setSelected(null);
    getUserItems({ userId: selectedUser.id })
      .then((r) => setItems(r.items))
      .catch(() => toast.error('Gagal memuat listing'))
      .finally(() => setLoadingItems(false));
  }, [selectedUser]);



  const handleBoost = async () => {
    if (!selected) return;
    if (addViews === 0 && addLikes === 0 && addComments === 0) {
      toast.error('Masukkan jumlah views, likes, atau komentar');
      return;
    }
    setBoosting(true);
    try {
      const res = await boostItem({ itemId: selected.id, addViews, addLikes, addComments });
      setItems((prev) =>
        prev.map((i) =>
          i.id === selected.id
            ? { ...i, viewsCount: res.newViewsCount, likesCount: res.newLikesCount, commentsCount: i.commentsCount + res.commentsAdded }
            : i
        )
      );
      setSelected((prev) =>
        prev ? { ...prev, viewsCount: res.newViewsCount, likesCount: res.newLikesCount, commentsCount: prev.commentsCount + res.commentsAdded } : prev
      );
      const parts: string[] = [];
      if (addViews > 0) parts.push(`+${addViews} views`);
      if (addLikes > 0) parts.push(`+${addLikes} likes`);
      if (addComments > 0) parts.push(`+${addComments} komentar`);
      toast.success(`Berhasil! ${parts.join(', ')}`);
      setAddViews(0);
      setAddLikes(0);
      setAddComments(0);
    } catch {
      toast.error('Gagal boost item');
    } finally {
      setBoosting(false);
    }
  };

  const handleAddPoints = async () => {
    if (!selectedUser || addPoints <= 0) return;
    setBoostingPoints(true);
    try {
      const res = await addUserPoints({ userId: selectedUser.id, points: addPoints, reason: pointReason || undefined });
      toast.success(`+${res.pointsAdded} poin berhasil ditambahkan! Total: ${res.newTotalPoints}`);
      setAddPoints(0);
      setPointReason('');
    } catch {
      toast.error('Gagal menambah poin');
    } finally {
      setBoostingPoints(false);
    }
  };

  const handleAddFollowers = async () => {
    if (!selectedUser || addFollowerCount <= 0) return;
    setBoostingFollowers(true);
    try {
      const res = await addFollowers({ userId: selectedUser.id, count: addFollowerCount });
      setCurrentFollowers(res.totalFollowers);
      toast.success(`+${res.followersAdded} follower berhasil ditambahkan! Total: ${res.totalFollowers}`);
      setAddFollowerCount(0);
    } catch {
      toast.error('Gagal menambah follower');
    } finally {
      setBoostingFollowers(false);
    }
  };

  const followerPresets = [
    { label: '+10 Follower', f: 10 },
    { label: '+25 Follower', f: 25 },
    { label: '+50 Follower', f: 50 },
    { label: '+100 Follower', f: 100 },
    { label: '+250 Follower', f: 250 },
    { label: '+500 Follower', f: 500 },
    { label: '+1000 Follower', f: 1000 },
  ];

  const pointPresets = [
    { label: '+10 Poin', p: 10 },
    { label: '+25 Poin', p: 25 },
    { label: '+50 Poin', p: 50 },
    { label: '+100 Poin', p: 100 },
    { label: '+500 Poin', p: 500 },
  ];

  const presets = [
    { label: '+50 Views', v: 50, l: 0, c: 0 },
    { label: '+100 Views', v: 100, l: 0, c: 0 },
    { label: '+25 Likes', v: 0, l: 25, c: 0 },
    { label: '+50 Likes', v: 0, l: 50, c: 0 },
    { label: '+5 Komentar', v: 0, l: 0, c: 5 },
    { label: 'Paket Boost', v: 200, l: 50, c: 10 },
  ];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <Zap className="h-6 w-6 text-yellow-500" /> Boost Generator
        </h1>
        <p className="text-muted-foreground mt-1">
          Pilih pengguna Mutari → pilih listing → boost views, likes & komentar
        </p>
      </div>

      <div className="grid gap-6 lg:grid-cols-[260px_1fr_360px]">
        {/* Users */}
        <Card className="flex flex-col" style={{ maxHeight: 'calc(100vh - 200px)' }}>
          <CardHeader className="pb-2 space-y-2">
            <CardTitle className="text-sm flex items-center gap-2">
              <User className="h-4 w-4" /> Pengguna ({allUsers.length})
            </CardTitle>
            <div className="relative">
              <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Cari pengguna..."
                value={userSearch}
                onChange={(e) => setUserSearch(e.target.value)}
                className="pl-8 h-8 text-sm"
              />
            </div>
          </CardHeader>
          <CardContent className="p-0 flex-1 overflow-y-auto">
            {loading ? (
              <p className="p-6 text-center text-sm text-muted-foreground">Memuat...</p>
            ) : displayUsers.length === 0 ? (
              <p className="p-6 text-center text-sm text-muted-foreground">{userSearch ? 'Tidak ditemukan' : 'Ketik nama untuk mencari'}</p>
            ) : (
              <div className="divide-y">
                {displayUsers.map((u) => (
                  <button
                    key={u.id}
                    onClick={() => setSelectedUser(u)}
                    className={`w-full text-left px-3 py-2 hover:bg-muted/50 transition-colors ${selectedUser?.id === u.id ? 'bg-primary/10 border-l-2 border-primary' : ''}`}
                  >
                    <p className="font-medium text-sm truncate">{u.displayName || u.name || 'No name'}</p>
                    <p className="text-xs text-muted-foreground truncate">{u.email}</p>
                  </button>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Items */}
        <Card className="flex flex-col" style={{ maxHeight: 'calc(100vh - 200px)' }}>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">
              {selectedUser ? `Listing — ${selectedUser.displayName || selectedUser.name}` : 'Pilih pengguna dulu'}
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0 flex-1 overflow-y-auto">
            {!selectedUser ? (
              <p className="p-8 text-center text-sm text-muted-foreground">← Pilih pengguna</p>
            ) : loadingItems ? (
              <p className="p-8 text-center text-sm text-muted-foreground">Memuat...</p>
            ) : items.length === 0 ? (
              <p className="p-8 text-center text-sm text-muted-foreground">User ini belum punya listing</p>
            ) : (
              <div className="divide-y">
                {items.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => setSelected(item)}
                    className={`w-full text-left px-4 py-3 hover:bg-muted/50 transition-colors ${selected?.id === item.id ? 'bg-primary/10 border-l-2 border-primary' : ''}`}
                  >
                    <p className="font-medium text-sm truncate">{item.title}</p>
                    <div className="flex items-center gap-3 mt-1 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1"><Eye className="h-3 w-3" />{item.viewsCount}</span>
                      <span className="flex items-center gap-1"><Heart className="h-3 w-3" />{item.likesCount}</span>
                      <span className="flex items-center gap-1"><MessageCircle className="h-3 w-3" />{item.commentsCount}</span>
                      <Badge variant="outline" className="text-[10px] px-1.5 py-0">{item.status}</Badge>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Boost panel */}
        <div className="space-y-4">
          {selected ? (
            <>
              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-base">{selected.title}</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-3 gap-2">
                    <StatBox icon={<Eye className="h-4 w-4 text-blue-500" />} label="Views" value={selected.viewsCount} />
                    <StatBox icon={<Heart className="h-4 w-4 text-red-500" />} label="Likes" value={selected.likesCount} />
                    <StatBox icon={<MessageCircle className="h-4 w-4 text-green-500" />} label="Komentar" value={selected.commentsCount} />
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center gap-2"><TrendingUp className="h-4 w-4" /> Boost</CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <BoostInput label="Tambah Views" value={addViews} onChange={setAddViews} />
                  <BoostInput label="Tambah Likes" value={addLikes} onChange={setAddLikes} />
                  <BoostInput label="Tambah Komentar" value={addComments} onChange={setAddComments} max={20} />

                  <div className="flex flex-wrap gap-1.5">
                    {presets.map((p) => (
                      <Badge
                        key={p.label}
                        variant="outline"
                        className="cursor-pointer hover:bg-primary hover:text-primary-foreground transition-colors text-xs"
                        onClick={() => { setAddViews(p.v); setAddLikes(p.l); setAddComments(p.c); }}
                      >
                        {p.label}
                      </Badge>
                    ))}
                  </div>

                  <Button className="w-full" onClick={handleBoost} disabled={boosting || (addViews === 0 && addLikes === 0 && addComments === 0)}>
                    {boosting ? 'Memproses...' : '⚡ Boost Sekarang'}
                  </Button>
                </CardContent>
              </Card>
            </>
          ) : (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-16 text-center">
                <Zap className="h-12 w-12 text-muted-foreground/30 mb-3" />
                <p className="text-muted-foreground text-sm">Pilih listing untuk boost</p>
              </CardContent>
            </Card>
          )}
          {selectedUser && (
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm flex items-center gap-2"><Star className="h-4 w-4 text-yellow-500" /> Tambah Poin — {selectedUser.displayName || selectedUser.name}</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <BoostInput label="Jumlah Poin" value={addPoints} onChange={setAddPoints} max={10000} />
                <div className="space-y-1">
                  <label className="text-xs font-medium">Alasan (opsional)</label>
                  <Input
                    placeholder="Contoh: Bonus event, reward..."
                    value={pointReason}
                    onChange={(e) => setPointReason(e.target.value)}
                    className="h-8 text-sm"
                  />
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {pointPresets.map((p) => (
                    <Badge
                      key={p.label}
                      variant="outline"
                      className="cursor-pointer hover:bg-yellow-500 hover:text-white transition-colors text-xs"
                      onClick={() => setAddPoints(p.p)}
                    >
                      {p.label}
                    </Badge>
                  ))}
                </div>
                <Button
                  className="w-full"
                  variant="outline"
                  onClick={handleAddPoints}
                  disabled={boostingPoints || addPoints <= 0}
                >
                  {boostingPoints ? 'Memproses...' : `⭐ Tambah ${addPoints > 0 ? addPoints + ' ' : ''}Poin`}
                </Button>
              </CardContent>
            </Card>
          )}
          {selectedUser && (
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm flex items-center gap-2"><Users className="h-4 w-4 text-blue-500" /> Tambah Follower — {selectedUser.displayName || selectedUser.name}</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                {currentFollowers !== null && (
                  <div className="flex items-center gap-2 rounded-lg bg-blue-50 dark:bg-blue-950/30 p-2.5">
                    <Users className="h-4 w-4 text-blue-500" />
                    <div>
                      <p className="text-[10px] text-muted-foreground">Total Follower</p>
                      <p className="font-semibold text-sm">{currentFollowers}</p>
                    </div>
                  </div>
                )}
                <BoostInput label="Jumlah Follower" value={addFollowerCount} onChange={setAddFollowerCount} />
                <div className="flex flex-wrap gap-1.5">
                  {followerPresets.map((p) => (
                    <Badge
                      key={p.label}
                      variant="outline"
                      className="cursor-pointer hover:bg-blue-500 hover:text-white transition-colors text-xs"
                      onClick={() => setAddFollowerCount(p.f)}
                    >
                      {p.label}
                    </Badge>
                  ))}
                </div>
                <Button
                  className="w-full"
                  variant="outline"
                  onClick={handleAddFollowers}
                  disabled={boostingFollowers || addFollowerCount <= 0}
                >
                  {boostingFollowers ? 'Memproses...' : `👥 Tambah ${addFollowerCount > 0 ? addFollowerCount + ' ' : ''}Follower`}
                </Button>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

function StatBox({ icon, label, value }: { icon: React.ReactNode; label: string; value: number }) {
  return (
    <div className="flex items-center gap-2 rounded-lg bg-muted/50 p-2.5">
      {icon}
      <div>
        <p className="text-[10px] text-muted-foreground">{label}</p>
        <p className="font-semibold text-sm">{value}</p>
      </div>
    </div>
  );
}

function BoostInput({ label, value, onChange, max }: { label: string; value: number; onChange: (v: number) => void; max?: number }) {
  return (
    <div className="space-y-1">
      <label className="text-xs font-medium">{label}</label>
      <Input
        type="number"
        min={0}
        max={max}
        value={value}
        onChange={(e) => onChange(Math.max(0, Math.min(max ?? 99999, parseInt(e.target.value) || 0)))}
        className="h-8"
      />
    </div>
  );
}

