import { useEffect, useState, useMemo } from 'react';
import { getChallenges, manageChallenge, deleteChallenge as deleteChallengeApi } from 'zitejs/api';
import type { GetChallengesOutputType } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Skeleton } from '@project/components/ui/skeleton';
import { Badge } from '@project/components/ui/badge';
import { Plus, Pencil, Trash2, Users, Trophy, Calendar, Eye } from 'lucide-react';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { toast } from 'sonner';
import ChallengeFormDialog from '../components/ChallengeFormDialog';

type Challenge = GetChallengesOutputType['challenges'][0];

const statusColors: Record<string, string> = {
  Draft: 'bg-muted text-muted-foreground',
  'Akan Datang': 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
  Aktif: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
  Selesai: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
  Dibatalkan: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
};

const typeIcons: Record<string, string> = {
  'Barter Terbanyak': '🔄',
  'Upload Terbanyak': '📦',
  'Rating Tertinggi': '⭐',
  'Kategori Spesifik': '🏷️',
  'Referral Race': '🤝',
  'Custom Target': '🎯',
};

function formatDate(iso?: string) {
  if (!iso) return '-';
  return new Date(iso).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
}

export default function ChallengesPage() {
  const [challenges, setChallenges] = useState<Challenge[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<Challenge | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const res = await getChallenges({});
      setChallenges(res.challenges);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const openCreate = () => { setEditing(null); setDialogOpen(true); };
  const openEdit = (c: Challenge) => { setEditing(c); setDialogOpen(true); };

  const handleDelete = async (id: string) => {
    try {
      await deleteChallengeApi({ id });
      toast.success('Challenge dihapus');
      fetchData();
    } catch {
      toast.error('Gagal menghapus');
    }
  };

  const handleSaved = () => {
    setDialogOpen(false);
    fetchData();
  };

  const stats = useMemo(() => {
    const active = challenges.filter(c => c.status === 'Aktif').length;
    const upcoming = challenges.filter(c => c.status === 'Akan Datang').length;
    const total = challenges.length;
    const totalParticipants = challenges.reduce((s, c) => s + (c.participantCount ?? 0), 0);
    return { active, upcoming, total, totalParticipants };
  }, [challenges]);

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">🏆 Challenge</h1>
          <p className="text-sm text-muted-foreground mt-0.5">Buat & kelola challenge untuk pengguna MUTARI</p>
        </div>
        <Button onClick={openCreate}>
          <Plus size={16} className="mr-1.5" /> Buat Challenge
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        <StatCard icon="🎯" label="Total Challenge" value={stats.total} />
        <StatCard icon="🟢" label="Aktif" value={stats.active} />
        <StatCard icon="📅" label="Akan Datang" value={stats.upcoming} />
        <StatCard icon="👥" label="Total Peserta" value={stats.totalParticipants} />
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-3">{Array.from({ length: 3 }).map((_, i) => <Skeleton key={i} className="h-28 rounded-xl" />)}</div>
      ) : challenges.length === 0 ? (
        <Card>
          <CardContent className="py-16 text-center">
            <div className="text-4xl mb-3">🏆</div>
            <p className="font-semibold text-lg">Belum ada Challenge</p>
            <p className="text-sm text-muted-foreground mt-1">Buat challenge pertama untuk meningkatkan engagement pengguna</p>
            <Button className="mt-4" onClick={openCreate}>
              <Plus size={16} className="mr-1.5" /> Buat Challenge Pertama
            </Button>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-3">
          {challenges.map((c) => (
            <ChallengeCard
              key={c.id}
              challenge={c}
              onEdit={() => openEdit(c)}
              onDelete={() => handleDelete(c.id)}
            />
          ))}
        </div>
      )}

      <ChallengeFormDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        editing={editing}
        onSaved={handleSaved}
      />
    </div>
  );
}

function StatCard({ icon, label, value }: { icon: string; label: string; value: number }) {
  return (
    <Card>
      <CardContent className="p-4 flex items-center gap-3">
        <div className="text-2xl">{icon}</div>
        <div>
          <p className="text-xl font-bold">{value}</p>
          <p className="text-xs text-muted-foreground">{label}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function ChallengeCard({ challenge: c, onEdit, onDelete }: { challenge: Challenge; onEdit: () => void; onDelete: () => void }) {
  return (
    <Card className="overflow-hidden">
      <CardContent className="p-0">
        <div className="flex">
          {/* Left accent */}
          <div className={`w-1.5 shrink-0 ${c.status === 'Aktif' ? 'bg-green-500' : c.status === 'Akan Datang' ? 'bg-blue-500' : c.status === 'Draft' ? 'bg-muted-foreground' : 'bg-yellow-500'}`} />

          <div className="flex-1 p-4">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-lg">{typeIcons[c.type ?? ''] ?? '🎯'}</span>
                  <h3 className="font-semibold text-sm">{c.title}</h3>
                  <Badge variant="secondary" className={statusColors[c.status ?? ''] ?? ''}>
                    {c.status ?? 'Draft'}
                  </Badge>
                  <Badge variant="outline" className="text-xs">
                    {c.visibility === 'Eksklusif' ? '🔒 Eksklusif' : '🌐 Publik'}
                  </Badge>
                </div>
                {c.description && (
                  <p className="text-xs text-muted-foreground mt-1 line-clamp-1">{c.description}</p>
                )}

                <div className="flex items-center gap-4 mt-2.5 text-xs text-muted-foreground flex-wrap">
                  <span className="flex items-center gap-1">
                    <Calendar size={12} /> {formatDate(c.startDate)} — {formatDate(c.endDate)}
                  </span>
                  <span className="flex items-center gap-1">
                    <Users size={12} /> {c.participantCount ?? 0} peserta
                  </span>
                  <span className="flex items-center gap-1">
                    <Trophy size={12} /> 🥇{c.reward1st ?? 0} 🥈{c.reward2nd ?? 0} 🥉{c.reward3rd ?? 0} poin
                  </span>
                  {c.minTarget && (
                    <span>Target min: {c.minTarget}</span>
                  )}
                </div>
              </div>

              <div className="flex gap-1 shrink-0">
                <Button size="sm" variant="ghost" onClick={onEdit}>
                  <Pencil size={14} />
                </Button>
                <AlertDialog>
                  <AlertDialogTrigger asChild>
                    <Button size="sm" variant="ghost" className="text-destructive">
                      <Trash2 size={14} />
                    </Button>
                  </AlertDialogTrigger>
                  <AlertDialogContent>
                    <AlertDialogHeader>
                      <AlertDialogTitle>Hapus "{c.title}"?</AlertDialogTitle>
                      <AlertDialogDescription>
                        Challenge ini memiliki {c.participantCount ?? 0} peserta. Data peserta juga akan terhapus.
                      </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                      <AlertDialogCancel>Batal</AlertDialogCancel>
                      <AlertDialogAction onClick={onDelete}>Hapus</AlertDialogAction>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

