/* ---- Helper Components ---- */

function KPICard({ icon: Icon, label, value, delta, deltaLabel, color, sparkData, isAlert }: {
  icon: any; label: string; value: number; delta?: number; deltaLabel?: string;
  color: string; sparkData?: { day: string; count: number }[]; isAlert?: boolean;
}) {
  return (
    <Card className={isAlert ? 'border-destructive/30' : ''}>
      <CardContent className="p-4">
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl"
              style={{ backgroundColor: `${color}18`, color }}>
              <Icon size={20} />
            </div>
            <div>
              <p className="text-xs text-muted-foreground">{label}</p>
              <p className="text-2xl font-bold tracking-tight leading-tight">{value.toLocaleString('id-ID')}</p>
            </div>
          </div>
          {delta !== undefined && (
            <div className={`flex items-center gap-0.5 text-xs font-semibold px-1.5 py-0.5 rounded-full ${delta > 0 ? 'text-emerald-700 bg-emerald-100' : 'text-muted-foreground bg-muted'}`}>
              {delta > 0 ? <TrendingUp size={12} /> : <Minus size={12} />}
              +{delta}
            </div>
          )}
        </div>
        {delta !== undefined && deltaLabel && (
          <p className="text-[10px] text-muted-foreground mt-1">{deltaLabel}</p>
        )}
        {sparkData && sparkData.length > 0 && (
          <div className="h-10 mt-2 -mx-1">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={sparkData}>
                <Line type="monotone" dataKey="count" stroke={color} strokeWidth={1.5} dot={false} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Tersedia: 'bg-emerald-100 text-emerald-700', Negosiasi: 'bg-amber-100 text-amber-700',
    'Sudah Ditukar': 'bg-blue-100 text-blue-700', Menunggu: 'bg-amber-100 text-amber-700',
    Diterima: 'bg-sky-100 text-sky-700', Selesai: 'bg-emerald-100 text-emerald-700',
    Dibatalkan: 'bg-red-100 text-red-700',
  };
  return <span className={`shrink-0 rounded-full px-2 py-0.5 text-xs font-medium ${c[status] ?? 'bg-muted text-muted-foreground'}`}>{status || 'Unknown'}</span>;
}

function SeverityBadge({ severity }: { severity: string }) {
  const c: Record<string, string> = {
    Berat: 'bg-red-100 text-red-700', Sedang: 'bg-amber-100 text-amber-700', Ringan: 'bg-blue-100 text-blue-700',
  };
  return <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold ${c[severity] ?? 'bg-muted text-muted-foreground'}`}>{severity}</span>;
}

function fmtDate(d: string) {
  try { return format(new Date(d), 'dd MMM yyyy', { locale: idLocale }); } catch { return '-'; }
}

function fmtRelative(d: string) {
  try { return formatDistanceToNow(new Date(d), { addSuffix: true, locale: idLocale }); } catch { return '-'; }
}

function mergeDailyData(
  users: { day: string; count: number }[],
  items: { day: string; count: number }[],
  barters: { day: string; count: number }[],
) {
  return users.map((u, i) => ({
    day: u.day,
    users: u.count,
    items: items[i]?.count ?? 0,
    barters: barters[i]?.count ?? 0,
  }));
}

