import { useState } from 'react';
import { exportData } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Download, Users, Package, ArrowLeftRight, Loader2, FileDown, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';

const exportTypes = [
  { type: 'users' as const, label: 'Pengguna', desc: 'Email, profil, poin, badge, verifikasi', icon: Users, color: 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400' },
  { type: 'listings' as const, label: 'Listing', desc: 'Judul, kondisi, status, lokasi, pemilik', icon: Package, color: 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400' },
  { type: 'barters' as const, label: 'Transaksi Barter', desc: 'Status, tanggal, initiator, partner, COD', icon: ArrowLeftRight, color: 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400' },
];

export default function ExportPage() {
  const [loading, setLoading] = useState<string | null>(null);
  const [lastExport, setLastExport] = useState<{ type: string; count: number; filename: string } | null>(null);

  const handleExport = async (type: 'users' | 'listings' | 'barters') => {
    setLoading(type);
    try {
      const res = await exportData({ type });
      // Download CSV
      const blob = new Blob(['\uFEFF' + res.csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = res.filename;
      a.click();
      URL.revokeObjectURL(url);

      setLastExport({ type, count: res.count, filename: res.filename });
      toast.success(`${res.count} data berhasil diexport`);
    } catch (e: any) {
      toast.error(e?.message || 'Export gagal');
    } finally {
      setLoading(null);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold flex items-center gap-2">
          <FileDown size={24} /> Export Data
        </h1>
        <p className="text-sm text-muted-foreground mt-1">Download data platform dalam format CSV. Maksimal 2000 baris per export.</p>
      </div>

      <div className="grid gap-4 sm:grid-cols-3">
        {exportTypes.map(et => {
          const isLoading = loading === et.type;
          const justExported = lastExport?.type === et.type;
          return (
            <Card key={et.type} className="relative overflow-hidden">
              <CardContent className="flex flex-col items-center text-center p-6 gap-4">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${et.color}`}>
                  <et.icon size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-lg">{et.label}</h3>
                  <p className="text-xs text-muted-foreground mt-1">{et.desc}</p>
                </div>
                <Button onClick={() => handleExport(et.type)} disabled={!!loading} className="w-full gap-2">
                  {isLoading ? <Loader2 size={16} className="animate-spin" /> : <Download size={16} />}
                  {isLoading ? 'Mengexport...' : 'Export CSV'}
                </Button>
                {justExported && (
                  <p className="text-xs text-emerald-600 flex items-center gap-1">
                    <CheckCircle2 size={12} /> {lastExport.count} baris · {lastExport.filename}
                  </p>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>

      <Card className="bg-muted/30">
        <CardContent className="p-4">
          <p className="text-xs text-muted-foreground">
            💡 <strong>Tips:</strong> File CSV bisa dibuka di Excel, Google Sheets, atau aplikasi spreadsheet lainnya. 
            Encoding UTF-8 dengan BOM agar karakter Indonesia tampil benar. Setiap export tercatat di Audit Log.
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

