  const navigate = useNavigate();
  const limit = 30;

  const fetchData = useCallback(async (p: number) => {
    setLoading(true);
    try {
      const res = await getLeaderboard({ offset: p * limit, limit });
      setEntries(res.leaderboard as LeaderboardEntry[]);
      setTotal(res.total);
      setBadgeDist(res.badgeDistribution);
      setTopStats(res.topStats);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(page); }, [page]);

  const totalPages = Math.max(1, Math.ceil(total / limit));

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-bold">Leaderboard Poin</h1>

      {/* Stats */}
