              <p className="text-xs text-muted-foreground mb-2">Distribusi Badge</p>
              <div className="h-28">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={badgeDist} dataKey="count" nameKey="badge" cx="50%" cy="50%" outerRadius={50} innerRadius={25}>
                      {badgeDist.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                    </Pie>
                    <Tooltip />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Table */}
      {loading ? (
        <div className="space-y-2">{Array.from({ length: 10 }).map((_, i) => <Skeleton key={i} className="h-14 rounded-lg" />)}</div>
      ) : entries.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Belum ada data poin</CardContent></Card>
      ) : (
        <Card>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b text-left text-xs text-muted-foreground">
                    <th className="px-4 py-3 w-12">#</th>
                    <th className="px-4 py-3">User</th>
                    <th className="px-4 py-3 text-center">Badge</th>
                    <th className="px-4 py-3 text-right">Poin</th>
                    <th className="px-4 py-3 text-right hidden sm:table-cell">Listing</th>
                    <th className="px-4 py-3 text-right hidden sm:table-cell">Barter</th>
                    <th className="px-4 py-3 text-right hidden md:table-cell">Likes</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {entries.map((e) => (
                    <tr
                      key={e.userId}
                      className="hover:bg-muted/50 cursor-pointer transition-colors"
                      onClick={() => e.userId && navigate(`/users/${e.userId}`)}
                    >
                      <td className="px-4 py-3">
                        <RankBadge rank={e.rank} />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          {e.userImage ? (
                            <img src={e.userImage} alt="" className="h-8 w-8 rounded-full object-cover" />
                          ) : (
                            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary">
                              {e.userName[0]?.toUpperCase() ?? '?'}
                            </div>
                          )}
                          <div className="min-w-0">
                            <p className="truncate font-medium">{e.userName}</p>
                            <p className="truncate text-xs text-muted-foreground">{e.userEmail}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3 text-center">
                        {e.currentBadge ? (
                          <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${BADGE_COLORS[e.currentBadge] ?? 'bg-muted text-muted-foreground'}`}>
                            {e.currentBadge}
                          </span>
                        ) : (
                          <span className="text-xs text-muted-foreground">—</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-right font-bold tabular-nums">{e.totalPoints.toLocaleString('id-ID')}</td>
                      <td className="px-4 py-3 text-right tabular-nums hidden sm:table-cell">{e.itemsUploaded}</td>
                      <td className="px-4 py-3 text-right tabular-nums hidden sm:table-cell">{e.bartersCompleted}</td>
                      <td className="px-4 py-3 text-right tabular-nums hidden md:table-cell">{e.likesReceived}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}

function MiniStat({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <Card>
      <CardContent className="flex items-center gap-3 p-4">
        <Icon size={20} className="text-muted-foreground shrink-0" />
        <div>
          <p className="text-xs text-muted-foreground">{label}</p>
          <p className="text-xl font-bold">{value}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function RankBadge({ rank }: { rank: number }) {
  if (rank === 1) return <span className="flex h-7 w-7 items-center justify-center rounded-full bg-amber-100 text-amber-700 text-xs font-bold">🥇</span>;
  if (rank === 2) return <span className="flex h-7 w-7 items-center justify-center rounded-full bg-gray-100 text-gray-600 text-xs font-bold">🥈</span>;
  if (rank === 3) return <span className="flex h-7 w-7 items-center justify-center rounded-full bg-orange-100 text-orange-600 text-xs font-bold">🥉</span>;
  return <span className="flex h-7 w-7 items-center justify-center text-sm text-muted-foreground font-medium">{rank}</span>;
}

