import { useEffect, useState, useCallback } from 'react';
import { getAdminListings, updateListingStatus } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Input } from '@project/components/ui/input';
import { Button } from '@project/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Skeleton } from '@project/components/ui/skeleton';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { Search, ChevronLeft, ChevronRight, MapPin, Eye, Heart, Trash2, CheckCircle, XCircle } from 'lucide-react';
import { useDebouncedCallback } from 'use-debounce';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { toast } from 'sonner';

type Item = {
  id: string;
  title: string;
  status: string;
  condition: string;
  location: string;
  estimatedValueMin: number;
  estimatedValueMax: number;
  viewsCount: number;
  likesCount: number;
  createdAt: string | null;
  ownerName: string;
  ownerEmail: string;
};

const STATUS_OPTIONS = ['Tersedia', 'Negosiasi', 'Sudah Ditukar'];

export default function ListingsPage() {
  const [items, setItems] = useState<Item[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [loading, setLoading] = useState(true);
  const limit = 20;

  const fetchItems = useCallback(async (s: string, st: string, p: number) => {
    setLoading(true);
    try {
      const res = await getAdminListings({
        search: s || undefined,
        status: st || undefined,
        offset: p * limit,
        limit,
      });
      setItems(res.items as Item[]);
      setTotal(res.total);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchItems(search, statusFilter, page);
  }, [page, statusFilter]);

  const debouncedSearch = useDebouncedCallback((val: string) => {
    setPage(0);
    fetchItems(val, statusFilter, 0);
  }, 400);

  const handleAction = async (itemId: string, action: 'approve' | 'reject' | 'delete') => {
    try {
      await updateListingStatus({ itemId, action });
      toast.success(action === 'delete' ? 'Listing dihapus' : action === 'approve' ? 'Listing disetujui' : 'Listing ditolak');
      fetchItems(search, statusFilter, page);
    } catch {
      toast.error('Gagal memproses');
    }
  };

  const formatRp = (n: number) => n ? `Rp ${n.toLocaleString('id-ID')}` : '-';
  const totalPages = Math.max(1, Math.ceil(total / limit));

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-bold">Moderasi Listing</h1>

      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative flex-1 max-w-xs">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Cari judul atau lokasi..."
            className="pl-9"
            value={search}
            onChange={(e) => { setSearch(e.target.value); debouncedSearch(e.target.value); }}
          />
        </div>
        <Select value={statusFilter} onValueChange={(v) => { setStatusFilter(v === 'all' ? '' : v); setPage(0); }}>
          <SelectTrigger className="w-40">
            <SelectValue placeholder="Semua Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Status</SelectItem>
            {STATUS_OPTIONS.map((s) => (
              <SelectItem key={s} value={s}>{s}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <div className="space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-20 rounded-xl" />)}</div>
      ) : items.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Tidak ada listing ditemukan</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {items.map((item) => (
            <Card key={item.id}>
              <CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <p className="truncate font-semibold text-sm">{item.title || 'Tanpa Judul'}</p>
                    <StatusBadge status={item.status} />
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {item.ownerName} · {item.ownerEmail}
                  </p>
                  <div className="mt-1.5 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                    {item.location && <span className="inline-flex items-center gap-1"><MapPin size={12} />{item.location}</span>}
                    <span className="inline-flex items-center gap-1"><Eye size={12} />{item.viewsCount}</span>
                    <span className="inline-flex items-center gap-1"><Heart size={12} />{item.likesCount}</span>
                    <span>{item.condition}</span>
                    <span>{formatRp(item.estimatedValueMin)} – {formatRp(item.estimatedValueMax)}</span>
                  </div>
                </div>

                <div className="flex items-center gap-1.5 shrink-0">
                  <p className="mr-2 text-xs text-muted-foreground hidden sm:block">
                    {item.createdAt ? format(new Date(item.createdAt), 'dd MMM yyyy', { locale: idLocale }) : ''}
                  </p>
                  <Button size="sm" variant="outline" className="text-emerald-600 border-emerald-200 hover:bg-emerald-50"
                    onClick={() => handleAction(item.id, 'approve')}>
                    <CheckCircle size={14} className="mr-1" /> Approve
                  </Button>
                  <Button size="sm" variant="outline" className="text-amber-600 border-amber-200 hover:bg-amber-50"
                    onClick={() => handleAction(item.id, 'reject')}>
                    <XCircle size={14} className="mr-1" /> Reject
                  </Button>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button size="sm" variant="outline" className="text-destructive border-destructive/20 hover:bg-destructive/5">
                        <Trash2 size={14} />
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>Hapus Listing?</AlertDialogTitle>
                        <AlertDialogDescription>Listing "{item.title}" akan dihapus permanen.</AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Batal</AlertDialogCancel>
                        <AlertDialogAction onClick={() => handleAction(item.id, 'delete')}>Hapus</AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Tersedia: 'bg-emerald-100 text-emerald-700',
    Negosiasi: 'bg-amber-100 text-amber-700',
    'Sudah Ditukar': 'bg-blue-100 text-blue-700',
  };
  return <span className={`rounded-full px-2 py-0.5 text-xs font-medium ${c[status] ?? 'bg-muted text-muted-foreground'}`}>{status}</span>;
}

