import { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { getReferrals, GetReferralsOutputType } from 'zitejs/api';
import { Input } from '@project/components/ui/input';
import { Badge } from '@project/components/ui/badge';
import { Button } from '@project/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Skeleton } from '@project/components/ui/skeleton';
import { Search, Gift, CheckCircle2, Clock, XCircle, ChevronLeft, ChevronRight, Award, Users, Crown, TrendingUp, Zap, ExternalLink } from 'lucide-react';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';
import { useDebouncedCallback } from 'use-debounce';

type Stats = GetReferralsOutputType['stats'];
type Referral = GetReferralsOutputType['referrals'][0];
type TopAffiliate = GetReferralsOutputType['topAffiliates'][0];

function StatCard({ icon: Icon, label, value, color }: { icon: React.ElementType; label: string; value: number | string; color: string }) {
  return (
    <div className="rounded-xl border bg-card p-4 flex items-center gap-4">
      <div className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-lg ${color}`}>
        <Icon size={20} />
      </div>
      <div>
        <p className="text-sm text-muted-foreground">{label}</p>
        <p className="text-xl font-bold">{value}</p>
      </div>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  if (status === 'Completed') return <Badge className="bg-emerald-500/15 text-emerald-600 hover:bg-emerald-500/20 border-0">Selesai</Badge>;
  if (status === 'Pending') return <Badge className="bg-amber-500/15 text-amber-600 hover:bg-amber-500/20 border-0">Menunggu</Badge>;
  if (status === 'Expired') return <Badge className="bg-red-500/15 text-red-500 hover:bg-red-500/20 border-0">Kadaluarsa</Badge>;
  return <Badge variant="secondary">{status}</Badge>;
}

function TierBadge({ tierId, tierName, tierEmoji }: { tierId: string; tierName: string; tierEmoji: string }) {
  const colors: Record<string, string> = {
    bronze: 'bg-amber-100 text-amber-700 border-amber-200',
    silver: 'bg-slate-100 text-slate-700 border-slate-200',
    gold: 'bg-yellow-100 text-yellow-700 border-yellow-200',
  };
  return (
    <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-semibold border ${colors[tierId] ?? 'bg-muted text-muted-foreground border-border'}`}>
      {tierEmoji} {tierName.replace(' Affiliate', '')}
    </span>
  );
}

function TopAffiliatesSection({ affiliates, onUserClick }: { affiliates: TopAffiliate[]; onUserClick: (id: string) => void }) {
  if (affiliates.length === 0) return null;

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          <Crown size={18} className="text-yellow-500" /> Top Affiliate — Pengguna Berjasa
        </CardTitle>
        <p className="text-xs text-muted-foreground mt-0.5">
          Pengguna yang paling aktif mengajak teman dan berkontribusi pada pertumbuhan platform
        </p>
      </CardHeader>
      <CardContent className="p-0">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b bg-muted/40">
                <th className="text-left px-4 py-2.5 font-medium text-muted-foreground w-10">#</th>
                <th className="text-left px-4 py-2.5 font-medium text-muted-foreground">Affiliate</th>
                <th className="text-left px-4 py-2.5 font-medium text-muted-foreground">Tier</th>
                <th className="text-right px-4 py-2.5 font-medium text-muted-foreground">Referral Selesai</th>
                <th className="text-right px-4 py-2.5 font-medium text-muted-foreground">MP/Referral</th>
                <th className="text-right px-4 py-2.5 font-medium text-muted-foreground">Boost/Bulan</th>
                <th className="text-right px-4 py-2.5 font-medium text-muted-foreground">Total Bonus</th>
                <th className="px-4 py-2.5 w-10"></th>
              </tr>
            </thead>
            <tbody>
              {affiliates.map((a, i) => (
                <tr key={a.userId} className="border-b last:border-0 hover:bg-muted/30 transition-colors">
                  <td className="px-4 py-3">
                    {i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : (
                      <span className="text-muted-foreground font-medium">{i + 1}</span>
                    )}
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2.5">
                      {a.image ? (
                        <img src={a.image} alt="" className="h-8 w-8 rounded-full object-cover" />
                      ) : (
                        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/10 text-primary font-bold text-xs">
                          {a.name[0]?.toUpperCase() ?? '?'}
                        </div>
                      )}
                      <div className="min-w-0">
                        <p className="font-medium truncate">{a.name}</p>
                        <p className="text-xs text-muted-foreground truncate">{a.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <TierBadge tierId={a.tierId} tierName={a.tierName} tierEmoji={a.tierEmoji} />
                  </td>
                  <td className="px-4 py-3 text-right font-bold">{a.completedReferrals}</td>
                  <td className="px-4 py-3 text-right text-primary font-medium">+{a.pointsPerReferral}</td>
                  <td className="px-4 py-3 text-right">
                    {a.boostSlots > 0 ? (
                      <span className="inline-flex items-center gap-1 text-amber-600 font-medium">
                        <Zap size={12} /> {a.boostSlots}x
                      </span>
                    ) : (
                      <span className="text-muted-foreground">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-right font-bold text-emerald-600">{a.totalBonus.toLocaleString()}</td>
                  <td className="px-4 py-3">
                    <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => onUserClick(a.userId)}>
                      <ExternalLink size={14} />
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </CardContent>
    </Card>
  );
}

const PAGE_SIZE = 15;

export default function ReferralsPage() {
  const navigate = useNavigate();
  const [data, setData] = useState<GetReferralsOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState('all');
  const [page, setPage] = useState(0);

  const load = useCallback(async (s: string, st: string, p: number) => {
    setLoading(true);
    try {
      const res = await getReferrals({
        search: s || undefined,
        status: st === 'all' ? undefined : st,
        limit: PAGE_SIZE,
        offset: p * PAGE_SIZE,
      });
      setData(res);
    } catch { /* ignore */ } finally {
      setLoading(false);
    }
  }, []);

  const debouncedSearch = useDebouncedCallback((val: string) => {
    setPage(0);
    load(val, status, 0);
  }, 400);

  useEffect(() => { load(search, status, page); }, []);

  const handleStatusChange = (val: string) => {
    setStatus(val);
    setPage(0);
    load(search, val, 0);
  };

  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold">Program Affiliate & Referral</h1>
        <p className="text-muted-foreground text-sm mt-1">Kelola program affiliate berjenjang dan lihat kontribusi pengguna</p>
      </div>

      {/* Stats */}
      {!data && loading ? (
        <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
          {Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-[76px] rounded-xl" />)}
        </div>
      ) : data && (
        <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
          <StatCard icon={Users} label="Total Referral" value={data.stats.totalCodes} color="bg-primary/10 text-primary" />
          <StatCard icon={CheckCircle2} label="Selesai" value={data.stats.totalCompleted} color="bg-emerald-500/10 text-emerald-600" />
          <StatCard icon={Clock} label="Menunggu" value={data.stats.totalPending} color="bg-amber-500/10 text-amber-600" />
          <StatCard icon={XCircle} label="Kadaluarsa" value={data.stats.totalExpired} color="bg-red-500/10 text-red-500" />
          <StatCard icon={Award} label="Bonus Diberikan" value={`${data.stats.totalBonusAwarded.toLocaleString()} MP`} color="bg-violet-500/10 text-violet-600" />
        </div>
      )}

      {/* Top Affiliates */}
      {!data && loading ? (
        <Skeleton className="h-64 rounded-xl" />
      ) : data && (
        <TopAffiliatesSection
          affiliates={data.topAffiliates}
          onUserClick={(id) => navigate(`/users/${id}`)}
        />
      )}

      {/* Referrals Table */}
      <div>
        <h2 className="text-lg font-bold mb-3">Semua Referral</h2>
