              <thead>
                <tr className="border-b bg-muted/40">
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Kode Referral</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Pemberi Referral</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Pengguna Direferral</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Status</th>
                  <th className="text-right px-4 py-3 font-medium text-muted-foreground">Bonus Poin</th>
                  <th className="text-left px-4 py-3 font-medium text-muted-foreground">Tanggal</th>
                </tr>
