                        <td key={j} className="px-4 py-3"><Skeleton className="h-4 w-24" /></td>
                      ))}
                    </tr>
                  ))
                ) : data && data.referrals.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="px-4 py-12 text-center text-muted-foreground">
                      Belum ada data referral
                    </td>
                  </tr>
                ) : data?.referrals.map((r) => (
                  <tr key={r.id} className="border-b last:border-0 hover:bg-muted/30 transition-colors">
                    <td className="px-4 py-3 font-mono font-semibold text-primary">{r.referralCode}</td>
                    <td className="px-4 py-3">
                      <p className="font-medium">{r.referrerName}</p>
                      <p className="text-xs text-muted-foreground">{r.referrerEmail}</p>
                    </td>
                    <td className="px-4 py-3">
                      {r.referredName ? (
                        <>
                          <p className="font-medium">{r.referredName}</p>
                          <p className="text-xs text-muted-foreground">{r.referredEmail}</p>
                        </>
                      ) : (
                        <span className="text-muted-foreground italic">Belum digunakan</span>
                      )}
                    </td>
                    <td className="px-4 py-3"><StatusBadge status={r.status} /></td>
                    <td className="px-4 py-3 text-right font-medium">{r.bonusPoints > 0 ? `+${r.bonusPoints}` : '0'}</td>
                    <td className="px-4 py-3 text-muted-foreground whitespace-nowrap">
                      {r.createdAt ? format(new Date(r.createdAt), 'd MMM yyyy', { locale: id }) : '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {data && data.total > PAGE_SIZE && (
            <div className="flex items-center justify-between border-t px-4 py-3">
              <p className="text-sm text-muted-foreground">
                {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, data.total)} dari {data.total}
              </p>
              <div className="flex gap-1">
                <Button variant="ghost" size="icon" disabled={page === 0} onClick={() => { setPage(page - 1); load(search, status, page - 1); }}>
                  <ChevronLeft size={16} />
                </Button>
                <Button variant="ghost" size="icon" disabled={page >= totalPages - 1} onClick={() => { setPage(page + 1); load(search, status, page + 1); }}>
                  <ChevronRight size={16} />
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

