import { useEffect, useState, useCallback } from 'react';
import { getAdminReviews, deleteReview } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Skeleton } from '@project/components/ui/skeleton';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { ChevronLeft, ChevronRight, Star, Trash2, Search } from 'lucide-react';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { toast } from 'sonner';
import { useDebouncedCallback } from 'use-debounce';

type Review = {
  id: string;
  rating: number;
  comment: string | null;
  aspect: string | null;
  createdAt: string | null;
  reviewerName: string;
  reviewerEmail: string;
  revieweeName: string;
  barterTitle: string | null;
};

type Stats = {
  totalReviews: number;
  averageRating: number;
  ratingDistribution: { rating: number; count: number }[];
};

export default function ReviewsPage() {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [total, setTotal] = useState(0);
  const [stats, setStats] = useState<Stats | null>(null);
  const [page, setPage] = useState(0);
  const [ratingFilter, setRatingFilter] = useState('');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const limit = 20;

  const fetchData = useCallback(async (rf: string, s: string, p: number) => {
    setLoading(true);
    try {
      const res = await getAdminReviews({
        ratingFilter: rf ? Number(rf) : undefined,
        search: s || undefined,
        offset: p * limit,
        limit,
      });
      setReviews(res.reviews as Review[]);
      setTotal(res.total);
      setStats(res.stats as Stats);
    } finally {
      setLoading(false);
    }
  }, []);

  const debouncedSearch = useDebouncedCallback((val: string) => {
    setPage(0);
    fetchData(ratingFilter, val, 0);
  }, 400);

  useEffect(() => { fetchData(ratingFilter, search, page); }, [page, ratingFilter]);

  const handleDelete = async (id: string) => {
    try {
      await deleteReview({ reviewId: id });
      toast.success('Review berhasil dihapus');
      fetchData(ratingFilter, search, page);
    } catch {
      toast.error('Gagal menghapus review');
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / limit));

  return (
    <div className="space-y-5">
      <h1 className="text-2xl font-bold">Review & Rating</h1>

      {/* Stats cards */}
      {stats && (
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          <StatCard label="Total Review" value={String(stats.totalReviews)} />
          <StatCard label="Rata-rata Rating" value={`${stats.averageRating} / 5`} icon />
          <Card>
            <CardContent className="p-4">
              <p className="text-xs text-muted-foreground mb-2">Distribusi Rating</p>
              <div className="space-y-1">
                {stats.ratingDistribution.map((d) => {
                  const maxCount = Math.max(...stats.ratingDistribution.map(x => x.count), 1);
                  return (
                    <div key={d.rating} className="flex items-center gap-2 text-xs">
                      <span className="w-3 text-right">{d.rating}</span>
                      <Star size={10} className="text-amber-500 fill-amber-500" />
                      <div className="flex-1 h-2 bg-muted rounded-full overflow-hidden">
                        <div className="h-full bg-amber-500 rounded-full transition-all" style={{ width: `${(d.count / maxCount) * 100}%` }} />
                      </div>
                      <span className="w-8 text-muted-foreground text-right">{d.count}</span>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-col gap-3 sm:flex-row">
        <div className="relative max-w-sm flex-1">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Cari reviewer, reviewee, komentar..."
            className="pl-9"
            value={search}
            onChange={(e) => { setSearch(e.target.value); debouncedSearch(e.target.value); }}
          />
        </div>
        <Select value={ratingFilter} onValueChange={(v) => { setRatingFilter(v === 'all' ? '' : v); setPage(0); }}>
          <SelectTrigger className="w-40"><SelectValue placeholder="Semua Rating" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Semua Rating</SelectItem>
            {[5, 4, 3, 2, 1].map((r) => (
              <SelectItem key={r} value={String(r)}>
                {r} ★
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* List */}
      {loading ? (
        <div className="space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-24 rounded-xl" />)}</div>
      ) : reviews.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Tidak ada review ditemukan</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {reviews.map((r) => (
            <Card key={r.id}>
              <CardContent className="flex items-start gap-3 p-4">
                <div className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-amber-100 text-amber-600">
                  <Star size={18} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="text-sm font-semibold">{r.reviewerName}</p>
                    <span className="text-xs text-muted-foreground">→</span>
                    <p className="text-sm font-medium text-muted-foreground">{r.revieweeName}</p>
                    <RatingStars rating={r.rating} />
                  </div>
                  {r.barterTitle && (
                    <p className="text-xs text-muted-foreground mt-0.5">
                      Barter: <span className="font-medium text-foreground">{r.barterTitle}</span>
                    </p>
                  )}
                  {r.aspect && (
                    <span className="inline-block mt-1 rounded-full bg-muted px-2 py-0.5 text-xs font-medium text-muted-foreground">
                      {r.aspect}
                    </span>
                  )}
                  {r.comment && (
                    <p className="mt-1.5 text-sm text-foreground leading-relaxed">{r.comment}</p>
                  )}
                  {r.createdAt && (
                    <p className="text-xs text-muted-foreground mt-1.5">
                      {format(new Date(r.createdAt), 'dd MMM yyyy, HH:mm', { locale: idLocale })}
                    </p>
                  )}
                </div>
                <AlertDialog>
                  <AlertDialogTrigger asChild>
                    <Button variant="ghost" size="icon" className="shrink-0 text-muted-foreground hover:text-destructive">
                      <Trash2 size={16} />
                    </Button>
                  </AlertDialogTrigger>
                  <AlertDialogContent>
                    <AlertDialogHeader>
                      <AlertDialogTitle>Hapus review?</AlertDialogTitle>
                      <AlertDialogDescription>
                        Review dari {r.reviewerName} akan dihapus permanen. Tindakan ini tidak bisa dibatalkan.
                      </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                      <AlertDialogCancel>Batal</AlertDialogCancel>
                      <AlertDialogAction onClick={() => handleDelete(r.id)} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                        Hapus
                      </AlertDialogAction>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}

function StatCard({ label, value, icon }: { label: string; value: string; icon?: boolean }) {
  return (
    <Card>
      <CardContent className="p-4">
        <p className="text-xs text-muted-foreground">{label}</p>
        <p className="mt-1 text-2xl font-bold flex items-center gap-1.5">
          {icon && <Star size={18} className="text-amber-500 fill-amber-500" />}
          {value}
        </p>
      </CardContent>
    </Card>
  );
}

function RatingStars({ rating }: { rating: number }) {
  return (
    <div className="flex items-center gap-0.5">
      {[1, 2, 3, 4, 5].map((i) => (
        <Star
          key={i}
          size={12}
          className={i <= rating ? 'text-amber-500 fill-amber-500' : 'text-muted-foreground/30'}
        />
      ))}
    </div>
  );
}

