import { useState, useEffect } from 'react';
import { adminSendWarning, getAdminUsers, GetAdminUsersOutputType } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Textarea } from '@project/components/ui/textarea';
import { Label } from '@project/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Switch } from '@project/components/ui/switch';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { AlertTriangle, Send, Search, User, Shield, Ban } from 'lucide-react';
import { toast } from 'sonner';
import { useDebouncedCallback } from 'use-debounce';

type UserType = GetAdminUsersOutputType['users'][0];

export default function SendWarningPage() {
  const [users, setUsers] = useState<UserType[]>([]);
  const [search, setSearch] = useState('');
  const [selectedUser, setSelectedUser] = useState<UserType | null>(null);
  const [title, setTitle] = useState('');
  const [message, setMessage] = useState('');
  const [severity, setSeverity] = useState('');
  const [deductPoints, setDeductPoints] = useState(0);
  const [autoSuspend, setAutoSuspend] = useState(false);
  const [autoBan, setAutoBan] = useState(false);
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(false);

  const searchUsers = useDebouncedCallback(async (q: string) => {
    if (!q.trim()) { setUsers([]); return; }
    setLoading(true);
    try {
      const res = await getAdminUsers({ search: q, limit: 20 });
      setUsers(res.users);
    } catch { /* ignore */ }
    setLoading(false);
  }, 400);

  useEffect(() => { searchUsers(search); }, [search]);

  const canSend = selectedUser && title.trim() && message.trim();

  const handleSend = async () => {
    if (!selectedUser) return;
    setSending(true);
    try {
      const res = await adminSendWarning({
        userId: selectedUser.id,
        title,
        message,
        severity: severity as any || undefined,
        deductPoints: deductPoints || undefined,
        autoSuspend: autoSuspend || undefined,
        autoBan: autoBan || undefined,
      });
      toast.success(res.actionTaken);
      setTitle('');
      setMessage('');
      setSeverity('');
      setDeductPoints(0);
      setAutoSuspend(false);
      setAutoBan(false);
      setSelectedUser(null);
      setSearch('');
    } catch {
      toast.error('Gagal mengirim peringatan');
    }
    setSending(false);
  };

  return (
    <div className="space-y-5 max-w-2xl">
      <h1 className="text-2xl font-bold flex items-center gap-2">
        <AlertTriangle className="text-amber-500" size={24} />
        Kirim Peringatan Langsung
      </h1>
      <p className="text-sm text-muted-foreground">
        Kirim peringatan langsung ke pengguna tertentu. Notifikasi akan muncul di aplikasi mereka.
      </p>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">1. Pilih Pengguna</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {selectedUser ? (
            <div className="flex items-center justify-between rounded-lg border p-3 bg-muted/50">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                  <User size={18} className="text-primary" />
                </div>
                <div>
                  <p className="font-medium text-sm">{selectedUser.name || selectedUser.email}</p>
                  <p className="text-xs text-muted-foreground">{selectedUser.email}</p>
                </div>
              </div>
              <Button variant="ghost" size="sm" onClick={() => setSelectedUser(null)}>Ganti</Button>
            </div>
          ) : (
            <>
              <div className="relative">
                <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                <Input
                  placeholder="Cari nama atau email pengguna..."
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                  className="pl-9"
                />
              </div>
              {loading && <p className="text-xs text-muted-foreground">Mencari...</p>}
              {users.length > 0 && (
                <div className="border rounded-lg max-h-48 overflow-y-auto divide-y">
                  {users.map(u => (
                    <button
                      key={u.id}
                      onClick={() => { setSelectedUser(u); setSearch(''); setUsers([]); }}
                      className="w-full text-left px-3 py-2 hover:bg-muted/50 flex items-center gap-3"
                    >
                      <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                        <User size={14} className="text-primary" />
                      </div>
                      <div>
                        <p className="text-sm font-medium">{u.name || 'Tanpa Nama'}</p>
                        <p className="text-xs text-muted-foreground">{u.email}</p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">2. Isi Peringatan</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <Label>Judul Peringatan *</Label>
            <Input
              placeholder="misal: Peringatan Pelanggaran COD"
              value={title}
              onChange={e => setTitle(e.target.value)}
            />
          </div>
          <div>
            <Label>Pesan Detail *</Label>
            <Textarea
              placeholder="Jelaskan alasan peringatan secara detail..."
              value={message}
              onChange={e => setMessage(e.target.value)}
              rows={4}
            />
          </div>
          <div>
            <Label>Tingkat Keparahan (opsional)</Label>
            <Select value={severity} onValueChange={setSeverity}>
              <SelectTrigger>
                <SelectValue placeholder="Pilih severity..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="Ringan">🟡 Ringan</SelectItem>
                <SelectItem value="Sedang">🟠 Sedang</SelectItem>
                <SelectItem value="Berat">🔴 Berat</SelectItem>
                <SelectItem value="Paling Berat">⛔ Paling Berat</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label>Kurangi Poin (opsional)</Label>
            <Input
              type="number"
              min={0}
              value={deductPoints}
              onChange={e => setDeductPoints(Number(e.target.value))}
              placeholder="0"
            />
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-base">3. Tindakan Tambahan</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between rounded-lg border p-3">
            <div className="flex items-center gap-2">
              <Shield size={16} className="text-orange-500" />
              <div>
                <p className="text-sm font-medium">Tangguhkan Akun</p>
                <p className="text-xs text-muted-foreground">User tidak bisa melakukan aktivitas</p>
              </div>
            </div>
            <Switch checked={autoSuspend} onCheckedChange={v => { setAutoSuspend(v); if (v) setAutoBan(false); }} />
          </div>
          <div className="flex items-center justify-between rounded-lg border p-3 border-destructive/30">
            <div className="flex items-center gap-2">
              <Ban size={16} className="text-destructive" />
              <div>
                <p className="text-sm font-medium text-destructive">Blokir Akun Permanen</p>
                <p className="text-xs text-muted-foreground">User akan diblokir dan tidak bisa login</p>
              </div>
            </div>
            <Switch checked={autoBan} onCheckedChange={v => { setAutoBan(v); if (v) setAutoSuspend(false); }} />
          </div>
        </CardContent>
      </Card>

      <AlertDialog>
        <AlertDialogTrigger asChild>
          <Button disabled={!canSend || sending} className="w-full gap-2" size="lg">
            <Send size={16} />
            Kirim Peringatan
          </Button>
        </AlertDialogTrigger>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Konfirmasi Kirim Peringatan</AlertDialogTitle>
            <AlertDialogDescription>
              Peringatan "{title}" akan dikirim ke {selectedUser?.name || selectedUser?.email}.
              {deductPoints > 0 && ` Poin dikurangi: ${deductPoints}.`}
              {autoBan && ' Akun akan DIBLOKIR PERMANEN.'}
              {autoSuspend && ' Akun akan DITANGGUHKAN.'}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Batal</AlertDialogCancel>
            <AlertDialogAction onClick={handleSend} disabled={sending}>
              {sending ? 'Mengirim...' : 'Ya, Kirim'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

