import { useState, useEffect, useRef } from 'react';
import { getSupportChats, getSupportChatMessages, replySupportChat, GetSupportChatsOutputType, GetSupportChatMessagesOutputType } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Input } from '@project/components/ui/input';
import { Button } from '@project/components/ui/button';
import { Badge } from '@project/components/ui/badge';
import { Headphones, Send, ArrowLeft, User, Loader2, MessageSquare, Search } from 'lucide-react';
import { toast } from 'sonner';

type Convo = GetSupportChatsOutputType['conversations'][0];
type Msg = GetSupportChatMessagesOutputType['messages'][0];

export default function SupportChatsPage() {
  const [conversations, setConversations] = useState<Convo[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<Convo | null>(null);
  const [search, setSearch] = useState('');

  const loadConvos = async () => {
    try {
      const res = await getSupportChats({});
      setConversations(res.conversations);
    } catch { /* ignore */ }
    setLoading(false);
  };

  useEffect(() => { loadConvos(); }, []);

