                </div>
                <div className="text-right shrink-0">
                  <p className="text-[10px] text-muted-foreground">
                    {formatRelative(c.lastMessageAt)}
                  </p>
                  <p className="text-[10px] text-muted-foreground">{c.totalMessages} pesan</p>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

function formatRelative(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  const now = new Date();
  const diff = now.getTime() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'Baru saja';
  if (mins < 60) return `${mins}m lalu`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}j lalu`;
  const days = Math.floor(hrs / 24);
  if (days < 7) return `${days}h lalu`;
  return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' });
}

function ChatDetailView({ convo, onBack }: { convo: Convo; onBack: () => void }) {
  const [messages, setMessages] = useState<Msg[]>([]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(true);
  const bottomRef = useRef<HTMLDivElement>(null);

  const loadMessages = async () => {
    try {
      const res = await getSupportChatMessages({ userId: convo.userId });
      setMessages(res.messages);
    } catch { /* ignore */ }
    setLoading(false);
  };

  useEffect(() => { loadMessages(); }, []);
  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages]);

  // Poll every 5s
  useEffect(() => {
    const iv = setInterval(async () => {
      try {
        const res = await getSupportChatMessages({ userId: convo.userId });
        setMessages(res.messages);
      } catch { /* ignore */ }
    }, 5000);
    return () => clearInterval(iv);
  }, [convo.userId]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || sending) return;
    setSending(true);
    setInput('');

    const optimistic: Msg = {
      id: 'temp-' + Date.now(),
      content: text,
      senderRole: 'admin',
      read: false,
      createdAt: new Date().toISOString(),
    };
    setMessages(prev => [...prev, optimistic]);

    try {
      await replySupportChat({ userId: convo.userId, content: text });
      toast.success('Balasan terkirim');
      await loadMessages();
    } catch {
      toast.error('Gagal mengirim');
      setMessages(prev => prev.filter(m => m.id !== optimistic.id));
      setInput(text);
    }
    setSending(false);
  };

  const formatTime = (iso: string) => {
    try { return new Date(iso).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }); }
    catch { return ''; }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={onBack}>
          <ArrowLeft size={18} />
        </Button>
        <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center">
          <User size={16} className="text-primary" />
        </div>
        <div>
          <p className="font-semibold text-sm">{convo.userName}</p>
          <p className="text-xs text-muted-foreground">{convo.userEmail}</p>
        </div>
      </div>

      <Card>
        <CardContent className="p-0">
          <div className="h-[60vh] overflow-y-auto p-4 space-y-2 bg-muted/30">
            {loading ? (
              <div className="flex justify-center py-12">
                <Loader2 className="w-5 h-5 animate-spin text-primary" />
              </div>
            ) : messages.length === 0 ? (
              <p className="text-center text-sm text-muted-foreground py-12">Belum ada pesan</p>
            ) : (
              messages.map(m => {
                const isAdmin = m.senderRole === 'admin';
                return (
                  <div key={m.id} className={`flex ${isAdmin ? 'justify-end' : 'justify-start'}`}>
                    <div
                      className={`max-w-[70%] rounded-2xl px-3.5 py-2.5 ${
                        isAdmin
                          ? 'bg-primary text-primary-foreground rounded-br-sm'
                          : 'bg-card border border-border rounded-bl-sm'
                      }`}
                    >
                      <p className="text-sm whitespace-pre-wrap">{m.content}</p>
                      <p className={`text-[10px] mt-1 text-right ${isAdmin ? 'text-primary-foreground/60' : 'text-muted-foreground'}`}>
                        {formatTime(m.createdAt)}
                      </p>
                    </div>
                  </div>
                );
              })
            )}
            <div ref={bottomRef} />
          </div>

          <div className="p-3 border-t flex gap-2">
            <Input
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Balas pesan pengguna..."
              className="flex-1"
            />
            <Button onClick={handleSend} disabled={!input.trim() || sending} size="icon">
              {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

