export default function UserDetailPage() {
  const { userId } = useParams<{ userId: string }>();
  const navigate = useNavigate();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    if (!userId) return;
    setLoading(true);
    try {
      const res = await getUserDetail({ userId });
      setData(res);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [userId]);

  const scrollTo = (hash: string) => {
    setTimeout(() => {
      document.getElementById(hash)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  };

  const handleBan = async (action: 'ban' | 'unban', reason?: string) => {
    if (!userId) return;
    try {
      await banUser({ userId, action, reason });
      toast.success(action === 'ban' ? 'Pengguna di-ban' : 'Ban dicabut');
      fetchData();
    } catch { toast.error('Gagal'); }
  };

  const handleAction = async (action: string, extra?: Record<string, any>) => {
    if (!userId) return;
    try {
      const res = await adminUserActions({ userId, action: action as any, ...extra });
      toast.success(res.message);
      fetchData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal');
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-40 rounded-xl" />
        <div className="grid gap-4 lg:grid-cols-2">
          <Skeleton className="h-64 rounded-xl" />
          <Skeleton className="h-64 rounded-xl" />
        </div>
      </div>
    );
  }

  if (!data?.user) {
    return (
      <div className="space-y-4">
        <Button variant="ghost" onClick={() => navigate('/users')}><ArrowLeft size={16} className="mr-1" /> Kembali</Button>
        <p className="text-center text-muted-foreground py-12">User tidak ditemukan</p>
      </div>
    );
  }

  const { user, profile, points, items, barters, serviceBarters, violations, reviews, violationCount, affiliate } = data;
  const isBanned = profile?.banned ?? false;
  const avgRating = reviews.length > 0
    ? (reviews.reduce((s: number, r: any) => s + r.rating, 0) / reviews.length).toFixed(1)
    : null;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate('/users')}>
          <ArrowLeft size={18} />
        </Button>
        <h1 className="text-2xl font-bold">Detail Pengguna</h1>
