      {/* Profile Card */}
      <ProfileCard user={user} profile={profile} isBanned={isBanned} violationCount={violationCount} points={points} />

      {/* Stats Row */}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-6">
        <StatMini icon={Trophy} label="Poin" value={points?.totalPoints ?? 0} />
        <StatMini icon={Package} label="Listing" value={points?.itemsUploaded ?? 0} />
        <StatMini icon={ArrowLeftRight} label="Barter Barang" value={points?.bartersCompleted ?? 0} />
        <StatMini icon={Wrench} label="Barter Jasa" value={(data.serviceBarters || []).length} />
        <StatMini icon={Star} label="Rating" value={avgRating ?? '-'} />
        <StatMini icon={AlertTriangle} label="Pelanggaran" value={violationCount} color={violationCount >= 3 ? 'text-amber-600' : undefined} />
      </div>

      {/* Verifikasi & Manajemen */}
      <VerificationCard profile={profile} onAction={handleAction} />
      <PointsManagementCard points={points} onAction={handleAction} />

      {/* Affiliate Status */}
      <AffiliateCard affiliate={affiliate} />

      {/* Informasi Lengkap Pengguna (Admin Only) */}
      <AdminInfoCard user={user} profile={profile} />

      {/* Peringatan Pelanggaran */}
      <WarningCard userId={userId!} onDone={fetchData} />

      {/* Tindakan Admin */}
      <BanCard userId={userId!} isBanned={isBanned} bannedReason={profile?.bannedReason} onBan={handleBan} onDone={fetchData} scrollTo={scrollTo} />

      {/* Tabs-like sections */}
      <div className="grid gap-4 lg:grid-cols-2">
        <ListingsSection items={items} />
        <BartersSection barters={barters} />
        <ServiceBartersSection serviceBarters={serviceBarters || []} />
        <ViolationsSection violations={violations} />
        <ReviewsSection reviews={reviews} />
      </div>
    </div>
  );
}

