/* ─── Points Management Card ─── */
function PointsManagementCard({ points, onAction }: { points: any; onAction: (a: string, e?: any) => Promise<void> }) {
  const [showAdjust, setShowAdjust] = useState(false);
  const [showResetBadge, setShowResetBadge] = useState(false);
  const [adjustAmount, setAdjustAmount] = useState('');
  const [adjustReason, setAdjustReason] = useState('');
  const [adjustType, setAdjustType] = useState<'add' | 'subtract'>('add');
  const [badgeValue, setBadgeValue] = useState('pemula');
  const [busy, setBusy] = useState(false);

  const currentPoints = points?.totalPoints ?? 0;
  const currentBadge = points?.currentBadge ?? 'Pemula';

  const handleAdjust = async () => {
    const amt = parseInt(adjustAmount);
    if (!amt || amt <= 0) { toast.error('Jumlah harus lebih dari 0'); return; }
    setBusy(true);
    try {
      await onAction('adjustPoints', {
        pointsAmount: adjustType === 'add' ? amt : -amt,
        pointsReason: adjustReason || undefined,
      });
      setShowAdjust(false);
      setAdjustAmount('');
      setAdjustReason('');
    } finally { setBusy(false); }
  };

  const handleResetBadge = async () => {
    setBusy(true);
    try {
      await onAction('resetBadge', { badgeValue });
      setShowResetBadge(false);
    } finally { setBusy(false); }
  };

  return (
    <>
      <Card className="border-amber-200/60 bg-amber-50/30 dark:border-amber-900/40 dark:bg-amber-950/20">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Coins size={16} className="text-amber-600" /> Manajemen Poin & Badge
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 gap-3 mb-4">
            <div className="rounded-lg border bg-card p-3 text-center">
              <Trophy size={20} className="mx-auto text-amber-500 mb-1" />
              <p className="text-2xl font-bold">{currentPoints.toLocaleString('id-ID')}</p>
              <p className="text-xs text-muted-foreground">Total Poin</p>
            </div>
            <div className="rounded-lg border bg-card p-3 text-center">
              <Award size={20} className="mx-auto text-primary mb-1" />
              <p className="text-lg font-bold">{currentBadge}</p>
              <p className="text-xs text-muted-foreground">Badge Saat Ini</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button variant="outline" size="sm" onClick={() => { setAdjustType('add'); setShowAdjust(true); }}>
              <Plus size={14} className="mr-1 text-emerald-600" /> Tambah Poin
            </Button>
            <Button variant="outline" size="sm" onClick={() => { setAdjustType('subtract'); setShowAdjust(true); }}>
              <Minus size={14} className="mr-1 text-destructive" /> Kurangi Poin
            </Button>
            <Button variant="outline" size="sm" onClick={() => setShowResetBadge(true)}>
              <RotateCcw size={14} className="mr-1" /> Ubah Badge
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Adjust Points Dialog */}
      <Dialog open={showAdjust} onOpenChange={setShowAdjust}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              {adjustType === 'add' ? <Plus size={18} className="text-emerald-600" /> : <Minus size={18} className="text-destructive" />}
              {adjustType === 'add' ? 'Tambah Poin' : 'Kurangi Poin'}
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="text-center text-sm text-muted-foreground">
              Poin saat ini: <span className="font-bold text-foreground">{currentPoints.toLocaleString('id-ID')}</span>
            </div>
            <div>
              <Label>Jumlah Poin</Label>
              <Input
                type="number" placeholder="Contoh: 50" min={1}
                value={adjustAmount} onChange={e => setAdjustAmount(e.target.value)}
              />
            </div>
            <div>
              <Label>Alasan (opsional)</Label>
              <Textarea
                placeholder={adjustType === 'add' ? 'Contoh: Bonus event spesial' : 'Contoh: Koreksi poin duplikat'}
                value={adjustReason} onChange={e => setAdjustReason(e.target.value)}
                rows={2}
              />
            </div>
            {adjustAmount && parseInt(adjustAmount) > 0 && (
              <div className={`text-center text-sm font-medium rounded-lg p-2 ${adjustType === 'add' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'}`}>
                {currentPoints.toLocaleString('id-ID')} → {(adjustType === 'add' ? currentPoints + parseInt(adjustAmount) : Math.max(0, currentPoints - parseInt(adjustAmount))).toLocaleString('id-ID')} poin
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAdjust(false)}>Batal</Button>
            <Button
              onClick={handleAdjust} disabled={busy || !adjustAmount || parseInt(adjustAmount) <= 0}
              className={adjustType === 'add' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-destructive hover:bg-destructive/90'}
            >
              {busy ? 'Menyimpan...' : 'Konfirmasi'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Reset Badge Dialog */}
