/* ─── Warning Card ─── */
const VIOLATION_OPTIONS = [
  'Tidak Hadir COD', 'Barang Tidak Sesuai', 'Fake Listing',
  'Batal Setelah COD Di-set', 'Batal Sepihak Setelah Deal',
  'Ghosting Negosiasi', 'Barter Expired Berulang',
  'Respons Lambat Berulang', 'Listing Tidak Lengkap',
  'Ubah Syarat di Menit Terakhir', 'Multi-Negosiasi Ghost', 'COD Egois',
];

function WarningCard({ userId, onDone }: { userId: string; onDone: () => void }) {
  const [showDialog, setShowDialog] = useState(false);
  const [violationType, setViolationType] = useState(VIOLATION_OPTIONS[0]);
  const [notes, setNotes] = useState('');
  const [busy, setBusy] = useState(false);

  const handleSend = async () => {
    setBusy(true);
    try {
      const res = await adminWarnUser({ userId, violationType, notes: notes || undefined });
      toast.success(res.message);
      setShowDialog(false);
      setNotes('');
      setViolationType(VIOLATION_OPTIONS[0]);
      onDone();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal memberikan peringatan');
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <Card className="border-amber-200/60 bg-amber-50/30 dark:border-amber-900/40 dark:bg-amber-950/20">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <AlertTriangle size={16} className="text-amber-600" /> Peringatan Pelanggaran
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground mb-3">
            Berikan peringatan resmi kepada pengguna. Poin akan dikurangi secara otomatis berdasarkan tingkat pelanggaran. User dengan 5+ pelanggaran aktif akan otomatis di-ban.
          </p>
          <Button className="bg-amber-600 hover:bg-amber-700 text-white" onClick={() => setShowDialog(true)}>
            <AlertTriangle size={16} className="mr-1.5" /> Berikan Peringatan
          </Button>
        </CardContent>
      </Card>

      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <AlertTriangle size={18} className="text-amber-600" /> Berikan Peringatan
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <Label>Jenis Pelanggaran</Label>
              <Select value={violationType} onValueChange={setViolationType}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {VIOLATION_OPTIONS.map(v => (
                    <SelectItem key={v} value={v}>{v}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Catatan / Alasan (opsional)</Label>
              <Textarea
                placeholder="Jelaskan detail pelanggaran..."
                value={notes}
                onChange={e => setNotes(e.target.value)}
                rows={3}
              />
            </div>
            <div className="rounded-lg bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 p-3 text-sm">
              <p className="font-semibold text-amber-800 dark:text-amber-300">Dampak peringatan ini:</p>
              <ul className="list-disc list-inside text-amber-700 dark:text-amber-400 text-xs mt-1 space-y-0.5">
                <li>Poin pengguna akan dikurangi sesuai tingkat pelanggaran</li>
                <li>Notifikasi peringatan dikirim ke pengguna</li>
                <li>Tercatat di riwayat pelanggaran pengguna</li>
              </ul>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowDialog(false)}>Batal</Button>
            <Button className="bg-amber-600 hover:bg-amber-700 text-white" onClick={handleSend} disabled={busy}>
              {busy ? 'Mengirim...' : 'Kirim Peringatan'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/* ─── Ban Card ─── */
function BanCard({ userId, isBanned, bannedReason, onBan, onDone, scrollTo }: {
  userId: string;
  isBanned: boolean;
  bannedReason?: string;
  onBan: (action: 'ban' | 'unban', reason?: string) => Promise<void>;
  onDone: () => void;
  scrollTo: (hash: string) => void;
}) {
  const [showBanDialog, setShowBanDialog] = useState(false);
  const [banReason, setBanReason] = useState('');
  const [busy, setBusy] = useState(false);

  const handleBanSubmit = async () => {
    setBusy(true);
    try {
      await onBan('ban', banReason || 'Pelanggaran berulang');
      setShowBanDialog(false);
      setBanReason('');
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <Card>
        <CardHeader><CardTitle className="text-base">Tindakan Admin</CardTitle></CardHeader>
        <CardContent className="flex flex-wrap gap-3">
          <Button variant="outline" onClick={() => scrollTo('listings')}>
            <Activity size={16} className="mr-1.5" /> Lihat Aktivitas
          </Button>
          <Button variant="outline" onClick={() => scrollTo('barters')}>
            <ArrowLeftRight size={16} className="mr-1.5" /> Lihat Riwayat Barter
          </Button>
          <Button variant="outline" onClick={() => scrollTo('violations')}>
            <FileWarning size={16} className="mr-1.5" /> Lihat Laporan
          </Button>

          <div className="w-full border-t my-1" />

          {isBanned ? (
            <div className="w-full space-y-3">
              <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-3">
                <p className="text-sm font-semibold text-destructive flex items-center gap-1.5">
                  <ShieldBan size={16} /> Akun Dibatasi (Banned)
                </p>
                {bannedReason && (
                  <p className="text-xs text-destructive/80 mt-1">Alasan: {bannedReason}</p>
                )}
                <p className="text-[11px] text-muted-foreground mt-1.5">
                  Pengguna hanya bisa melihat beranda. Tidak bisa upload, barter, chat, dan fitur lainnya.
                </p>
              </div>
              <AlertDialog>
                <AlertDialogTrigger asChild>
                  <Button variant="outline" className="text-emerald-600 border-emerald-200">
                    <ShieldCheck size={16} className="mr-1.5" /> Pulihkan Akun
                  </Button>
                </AlertDialogTrigger>
                <AlertDialogContent>
                  <AlertDialogHeader>
                    <AlertDialogTitle>Pulihkan Akun?</AlertDialogTitle>
                    <AlertDialogDescription>User akan bisa menggunakan semua fitur platform kembali.</AlertDialogDescription>
                  </AlertDialogHeader>
                  <AlertDialogFooter>
                    <AlertDialogCancel>Batal</AlertDialogCancel>
                    <AlertDialogAction onClick={() => onBan('unban')}>Ya, Pulihkan</AlertDialogAction>
                  </AlertDialogFooter>
                </AlertDialogContent>
              </AlertDialog>
            </div>
          ) : (
            <Button variant="destructive" onClick={() => setShowBanDialog(true)}>
              <ShieldBan size={16} className="mr-1.5" /> Batasi Akun (Ban)
            </Button>
          )}
        </CardContent>
      </Card>

      {/* Ban Dialog with reason */}
      <Dialog open={showBanDialog} onOpenChange={setShowBanDialog}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-destructive">
              <ShieldBan size={18} /> Batasi Akun (Ban)
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="rounded-lg bg-destructive/10 border border-destructive/20 p-3 text-sm">
              <p className="font-semibold text-destructive">Dampak pembatasan:</p>
              <ul className="list-disc list-inside text-destructive/80 text-xs mt-1 space-y-0.5">
                <li>User <strong>tidak bisa</strong> upload barang</li>
                <li>User <strong>tidak bisa</strong> melakukan barter</li>
                <li>User <strong>tidak bisa</strong> kirim chat / pesan</li>
                <li>User <strong>tidak bisa</strong> menggunakan semua fitur</li>
                <li>User <strong>hanya bisa</strong> melihat beranda saja</li>
              </ul>
            </div>
            <div>
              <Label>Alasan Ban</Label>
              <Textarea
                placeholder="Contoh: Pelanggaran berulang, fake listing, dll..."
                value={banReason}
                onChange={e => setBanReason(e.target.value)}
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowBanDialog(false)}>Batal</Button>
            <Button variant="destructive" onClick={handleBanSubmit} disabled={busy}>
              {busy ? 'Memproses...' : 'Ya, Batasi Akun'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

