}

function fmtDate(d: string | null) {
  if (!d) return '-';
  try { return format(new Date(d), 'dd MMM yyyy', { locale: idLocale }); } catch { return '-'; }
}

function StatusBadge({ status }: { status: string }) {
  const c: Record<string, string> = {
    Tersedia: 'bg-emerald-100 text-emerald-700', Negosiasi: 'bg-amber-100 text-amber-700',
    'Sudah Ditukar': 'bg-blue-100 text-blue-700', Menunggu: 'bg-amber-100 text-amber-700',
    Diterima: 'bg-sky-100 text-sky-700', Selesai: 'bg-emerald-100 text-emerald-700',
    Dibatalkan: 'bg-red-100 text-red-700', Aktif: 'bg-red-100 text-red-700',
    'Sudah Diperingatkan': 'bg-amber-100 text-amber-700', Dicabut: 'bg-emerald-100 text-emerald-700',
  };
  return <span className={`shrink-0 rounded-full px-2 py-0.5 text-xs font-medium ${c[status] ?? 'bg-muted text-muted-foreground'}`}>{status}</span>;
}

function SeverityBadge({ severity }: { severity: string }) {
  const c: Record<string, string> = { Berat: 'text-red-600', Sedang: 'text-amber-600', Ringan: 'text-blue-600' };
  return <span className={`font-medium ${c[severity] ?? ''}`}>{severity}</span>;
}

