        <p className={`text-sm ${muted ? 'text-muted-foreground italic' : 'font-medium'}`}>{value}</p>
      </div>
      {verified !== undefined && (
        <span className={`shrink-0 text-[10px] font-semibold px-1.5 py-0.5 rounded-full ${verified ? 'bg-emerald-100 text-emerald-700' : 'bg-muted text-muted-foreground'}`}>
