}

import { useEffect, useState, useCallback } from 'react';
import { getAdminUsers, banUser } from 'zitejs/api';
import { Card, CardContent } from '@project/components/ui/card';
import { Input } from '@project/components/ui/input';
import { Button } from '@project/components/ui/button';
import { Skeleton } from '@project/components/ui/skeleton';
import { Switch } from '@project/components/ui/switch';
import { Label } from '@project/components/ui/label';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger,
} from '@project/components/ui/alert-dialog';
import { Search, ChevronLeft, ChevronRight, Phone, MapPin, Trophy, AlertTriangle, Ban, ShieldCheck, Eye } from 'lucide-react';
import { useDebouncedCallback } from 'use-debounce';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

type User = {
  id: string;
  name: string;
  email: string;
  image: string | null;
  createdAt: string | null;
  displayName: string | null;
  phone: string | null;
  city: string | null;
  phoneVerified: boolean;
  banned: boolean;
  bannedReason: string | null;
  totalPoints: number;
  bartersCompleted: number;
  itemsUploaded: number;
  currentBadge: string | null;
  activeViolations: number;
};

export default function UsersPage() {
  const [users, setUsers] = useState<User[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(0);
  const [search, setSearch] = useState('');
  const [flaggedOnly, setFlaggedOnly] = useState(false);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  const limit = 20;

  const fetchUsers = useCallback(async (s: string, p: number, flagged: boolean) => {
    setLoading(true);
    try {
      const res = await getAdminUsers({ search: s || undefined, offset: p * limit, limit, flagged: flagged || undefined });
      setUsers(res.users as User[]);
      setTotal(res.total);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchUsers(search, page, flaggedOnly); }, [page, flaggedOnly]);

  const debouncedSearch = useDebouncedCallback((val: string) => {
    setPage(0);
    fetchUsers(val, 0, flaggedOnly);
  }, 400);

  const handleBan = async (userId: string, action: 'ban' | 'unban') => {
    try {
      await banUser({ userId, action, reason: action === 'ban' ? 'Pelanggaran berulang' : undefined });
      toast.success(action === 'ban' ? 'Pengguna di-ban' : 'Ban dicabut');
      fetchUsers(search, page, flaggedOnly);
    } catch { toast.error('Gagal memproses'); }
  };

  const totalPages = Math.max(1, Math.ceil(total / limit));

  return (
    <div className="space-y-5">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <h1 className="text-2xl font-bold">Pengguna</h1>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Switch id="flagged" checked={flaggedOnly} onCheckedChange={(v) => { setFlaggedOnly(v); setPage(0); }} />
            <Label htmlFor="flagged" className="text-sm whitespace-nowrap flex items-center gap-1">
              <AlertTriangle size={14} className="text-amber-500" /> Bermasalah
            </Label>
          </div>
          <div className="relative w-full max-w-xs">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <Input placeholder="Cari nama atau email..." className="pl-9" value={search}
              onChange={(e) => { setSearch(e.target.value); debouncedSearch(e.target.value); }} />
          </div>
        </div>
      </div>

      {loading ? (
        <div className="space-y-3">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-20 rounded-xl" />)}</div>
      ) : users.length === 0 ? (
        <Card><CardContent className="py-12 text-center text-muted-foreground">Tidak ada pengguna ditemukan</CardContent></Card>
      ) : (
        <div className="space-y-3">
          {users.map((u) => (
            <Card key={u.id} className={u.banned ? 'border-destructive/30 bg-destructive/5' : u.activeViolations >= 3 ? 'border-amber-300/50 bg-amber-50/50' : ''}>
              <CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center">
                {/* Avatar & Name */}
                <div className="flex items-center gap-3 min-w-0 flex-1">
                  <div className="relative shrink-0">
                    {u.image ? (
                      <img src={u.image} alt="" className="h-10 w-10 rounded-full object-cover" />
                    ) : (
                      <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 text-primary font-bold text-sm">
                        {(u.displayName || u.name)?.[0]?.toUpperCase() ?? '?'}
                      </div>
                    )}
                    {u.banned && (
                      <div className="absolute -bottom-0.5 -right-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-destructive">
                        <Ban size={10} className="text-white" />
                      </div>
                    )}
                    {!u.banned && u.activeViolations >= 3 && (
                      <div className="absolute -bottom-0.5 -right-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-amber-500">
                        <AlertTriangle size={10} className="text-white" />
                      </div>
                    )}
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <p className="truncate font-semibold text-sm">{u.displayName || u.name}</p>
                      {u.banned && <span className="rounded-full bg-destructive/10 px-2 py-0.5 text-xs font-medium text-destructive">BANNED</span>}
                      {!u.banned && u.activeViolations >= 3 && (
                        <span className="rounded-full bg-amber-100 px-2 py-0.5 text-xs font-medium text-amber-700">
                          ⚠ {u.activeViolations} pelanggaran
                        </span>
                      )}
                      {!u.banned && u.activeViolations > 0 && u.activeViolations < 3 && (
                        <span className="rounded-full bg-muted px-2 py-0.5 text-xs text-muted-foreground">
                          {u.activeViolations} pelanggaran
                        </span>
                      )}
                    </div>
                    <p className="truncate text-xs text-muted-foreground">{u.email}</p>
                  </div>
                </div>

                {/* Info chips */}
                <div className="flex flex-wrap items-center gap-1.5 text-xs text-muted-foreground">
                  {u.city && <span className="inline-flex items-center gap-1 rounded-full bg-muted px-2 py-0.5"><MapPin size={11} />{u.city}</span>}
                  <span className="inline-flex items-center gap-1 rounded-full bg-muted px-2 py-0.5"><Trophy size={11} />{u.totalPoints}</span>
                  <span className="rounded-full bg-muted px-2 py-0.5">{u.itemsUploaded} listing</span>
                  <span className="rounded-full bg-muted px-2 py-0.5">{u.bartersCompleted} barter</span>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1.5 shrink-0">
                  <Button size="sm" variant="outline" onClick={() => navigate(`/users/${u.id}`)}>
                    <Eye size={14} className="mr-1" /> Detail
                  </Button>
                  {u.banned ? (
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button size="sm" variant="outline" className="text-emerald-600 border-emerald-200">
                          <ShieldCheck size={14} className="mr-1" /> Unban
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent>
                        <AlertDialogHeader>
                          <AlertDialogTitle>Cabut Ban?</AlertDialogTitle>
                          <AlertDialogDescription>User "{u.displayName || u.name}" akan bisa menggunakan platform kembali.</AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel>Batal</AlertDialogCancel>
                          <AlertDialogAction onClick={() => handleBan(u.id, 'unban')}>Ya, Cabut Ban</AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  ) : (
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button size="sm" variant="outline" className="text-destructive border-destructive/20">
                          <Ban size={14} className="mr-1" /> Ban
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent>
                        <AlertDialogHeader>
                          <AlertDialogTitle>Ban Pengguna?</AlertDialogTitle>
                          <AlertDialogDescription>
                            User "{u.displayName || u.name}" tidak akan bisa upload listing atau barter lagi.
                            {u.activeViolations > 0 && ` Saat ini memiliki ${u.activeViolations} pelanggaran aktif.`}
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel>Batal</AlertDialogCancel>
                          <AlertDialogAction className="bg-destructive hover:bg-destructive/90" onClick={() => handleBan(u.id, 'ban')}>
                            Ya, Ban User
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {total > limit && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">{page * limit + 1}–{Math.min((page + 1) * limit, total)} dari {total}</p>
          <div className="flex gap-1">
            <Button variant="outline" size="icon" disabled={page === 0} onClick={() => setPage(page - 1)}><ChevronLeft size={16} /></Button>
            <Button variant="outline" size="icon" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}><ChevronRight size={16} /></Button>
          </div>
        </div>
      )}
    </div>
  );
}

