import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getViolationDetail, updateViolationStatus, getBarterTrail } from 'zitejs/api';
import type { GetBarterTrailOutputType } from 'zitejs/api';
import { Card, CardContent, CardHeader, CardTitle } from '@project/components/ui/card';
import { Button } from '@project/components/ui/button';
import { Skeleton } from '@project/components/ui/skeleton';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import {
  Dialog, DialogContent, DialogTrigger,
} from '@project/components/ui/dialog';
import {
  ArrowLeft, AlertTriangle, UserCheck, ImageIcon,
  FileText, ArrowLeftRight, Calendar, ShieldAlert, MinusCircle,
  MessageSquare, Star, CheckCircle, XCircle, Package, Truck, Shield,
} from 'lucide-react';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { toast } from 'sonner';

const V_STATUSES = ['Menunggu Review', 'Aktif', 'Sudah Diperingatkan', 'Banding', 'Kedaluwarsa', 'Dicabut', 'Ditolak'];

type Evidence = { url: string; filename: string; mimeType: string };

type ViolationDetail = {
  id: string;
  label: string;
  violationType: string;
  severity: string;
  minusPoints: number;
  status: string;
  notes: string | null;
  createdAt: string | null;
  evidence: Evidence[];
  userName: string;
  userEmail: string;
  userId: string | null;
  userImage: string | null;
  reporterName: string;
  reporterEmail: string;
  reporterImage: string | null;
  barterTitle: string | null;
  barterStatus: string | null;
  barterId?: string | null;
};

type BarterTrail = GetBarterTrailOutputType;

export default function ViolationDetailPage() {
  const { violationId } = useParams<{ violationId: string }>();
  const navigate = useNavigate();
  const [data, setData] = useState<ViolationDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [trail, setTrail] = useState<BarterTrail | null>(null);
  const [trailLoading, setTrailLoading] = useState(false);

  const fetchData = async () => {
    if (!violationId) return;
    setLoading(true);
    try {
      const res = await getViolationDetail({ violationId });
      setData(res.violation as ViolationDetail);
    } catch {
      toast.error('Gagal memuat detail pelanggaran');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, [violationId]);

  // Load barter trail when we have barterId
  useEffect(() => {
    if (!data?.barterId) return;
    setTrailLoading(true);
    getBarterTrail({ barterId: data.barterId })
      .then(res => setTrail(res))
      .catch(() => {})
      .finally(() => setTrailLoading(false));
  }, [data?.barterId]);

  const handleUpdateStatus = async (newStatus: string) => {
    if (!violationId) return;
    try {
      await updateViolationStatus({ violationId, status: newStatus as any });
      toast.success('Status diubah ke "' + newStatus + '"');
      fetchData();
    } catch {
      toast.error('Gagal mengubah status');
    }
  };

  if (loading) {
    return (
      <div className="space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-48 rounded-xl" />
        <div className="grid gap-4 lg:grid-cols-2">
          <Skeleton className="h-40 rounded-xl" />
          <Skeleton className="h-40 rounded-xl" />
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="space-y-4">
        <Button variant="ghost" onClick={() => navigate('/violations')}>
          <ArrowLeft size={16} className="mr-1" /> Kembali
        </Button>
        <p className="text-center text-muted-foreground py-12">Pelanggaran tidak ditemukan</p>
      </div>
    );
  }

  const severityColor = data.severity === 'Berat' ? 'border-red-300 bg-red-50' :
    data.severity === 'Sedang' ? 'border-amber-300 bg-amber-50' : 'border-blue-200 bg-blue-50';
  const severityIcon = data.severity === 'Berat' ? 'bg-red-500' :
    data.severity === 'Sedang' ? 'bg-amber-500' : 'bg-blue-500';

  return (
    <div className="space-y-6 max-w-4xl">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate('/violations')}>
          <ArrowLeft size={18} />
        </Button>
        <h1 className="text-2xl font-bold">Detail Pengaduan</h1>
      </div>

      {/* Main report card */}
      <Card className={'border-2 ' + severityColor}>
        <CardContent className="p-5 space-y-4">
          <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-3">
              <div className={'flex h-11 w-11 shrink-0 items-center justify-center rounded-xl ' + severityIcon}>
                <AlertTriangle size={22} className="text-white" />
              </div>
              <div>
                <h2 className="text-lg font-bold">{data.violationType}</h2>
                <div className="flex items-center gap-2 mt-0.5">
                  <SeverityBadge severity={data.severity} />
                  <StatusBadge status={data.status} />
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-xs text-muted-foreground">Ubah status:</span>
              <Select value={data.status} onValueChange={handleUpdateStatus}>
                <SelectTrigger className="w-44 h-9 text-sm"><SelectValue /></SelectTrigger>
                <SelectContent>
                  {V_STATUSES.map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
            <InfoItem icon={MinusCircle} label="Poin Dikurangi" value={'-' + data.minusPoints} className="text-destructive font-bold" />
            <InfoItem icon={Calendar} label="Tanggal Laporan" value={data.createdAt ? format(new Date(data.createdAt), 'dd MMMM yyyy, HH:mm', { locale: idLocale }) : '-'} />
            {data.barterTitle && (
              <InfoItem icon={ArrowLeftRight} label="Barter Terkait" value={data.barterTitle + (data.barterStatus ? ' (' + data.barterStatus + ')' : '')} />
            )}
          </div>
        </CardContent>
      </Card>

      {/* People */}
      <div className="grid gap-4 sm:grid-cols-2">
        <PersonCard
          title="Pelanggar"
          icon={<ShieldAlert size={16} className="text-destructive" />}
          name={data.userName}
          email={data.userEmail}
          image={data.userImage}
          onClick={data.userId ? () => navigate('/users/' + data.userId) : undefined}
          accent="destructive"
        />
        <PersonCard
          title="Pelapor"
          icon={<UserCheck size={16} className="text-emerald-600" />}
          name={data.reporterName || 'Sistem'}
          email={data.reporterEmail}
          image={data.reporterImage}
          accent="emerald"
        />
      </div>

      {/* Alasan / Notes */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <FileText size={16} /> Alasan & Detail Masalah
          </CardTitle>
        </CardHeader>
        <CardContent>
          {data.notes ? (
            <div className="rounded-lg bg-muted/50 p-4">
              <p className="text-sm leading-relaxed whitespace-pre-wrap">{data.notes}</p>
            </div>
          ) : (
            <p className="text-sm text-muted-foreground italic">Tidak ada catatan/alasan yang diberikan.</p>
          )}
        </CardContent>
      </Card>

      {/* Evidence */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <ImageIcon size={16} /> Bukti Pengaduan ({data.evidence.length} file)
          </CardTitle>
        </CardHeader>
        <CardContent>
          {data.evidence.length === 0 ? (
            <div className="rounded-lg border-2 border-dashed border-muted-foreground/20 py-10 text-center">
              <ImageIcon size={32} className="mx-auto text-muted-foreground/30 mb-2" />
              <p className="text-sm text-muted-foreground">Tidak ada bukti yang dilampirkan</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
              {data.evidence.map((e, i) => (
                <EvidenceThumb key={i} evidence={e} />
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* ===== BARTER NEGOTIATION TRAIL ===== */}
      {data.barterId && (
        <BarterTrailSection trail={trail} loading={trailLoading} onViewUser={(uid) => navigate('/users/' + uid)} />
      )}
    </div>
  );
}

/* ===== BARTER TRAIL SECTION ===== */
function BarterTrailSection({ trail, loading, onViewUser }: {
  trail: BarterTrail | null;
  loading: boolean;
  onViewUser: (uid: string) => void;
}) {
  if (loading) {
    return (
      <Card>
        <CardHeader><CardTitle className="text-base flex items-center gap-2">
          <MessageSquare size={16} /> Jejak Negosiasi
        </CardTitle></CardHeader>
        <CardContent className="space-y-3">
          {[0, 1, 2, 3].map(i => <Skeleton key={i} className="h-12 w-full rounded-lg" />)}
        </CardContent>
      </Card>
    );
  }
  if (!trail) return null;

  const { barter, initiator, partner, messages, reviews } = trail;

  const fmtDate = (d: string | null) => d ? format(new Date(d), 'dd MMM yyyy, HH:mm', { locale: idLocale }) : '-';
  const statusColor: Record<string, string> = {
    Menunggu: 'bg-blue-100 text-blue-700',
    Diterima: 'bg-emerald-100 text-emerald-700',
    Selesai: 'bg-green-100 text-green-700',
    Dibatalkan: 'bg-red-100 text-red-700',
  };

  return (
    <>
      {/* Barter Overview */}
      <Card className="border-2 border-primary/20">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <ArrowLeftRight size={16} className="text-primary" /> Detail Barter Terkait
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Status & timeline */}
          <div className="flex flex-wrap items-center gap-3">
            <span className={'rounded-full px-3 py-1 text-xs font-bold ' + (statusColor[barter.status] ?? 'bg-muted text-muted-foreground')}>
              {barter.status}
            </span>
            <span className="text-xs text-muted-foreground">
              Dibuat: {fmtDate(barter.createdAt)}
            </span>
            {barter.completedAt && (
              <span className="text-xs text-muted-foreground">
                Selesai: {fmtDate(barter.completedAt)}
              </span>
            )}
            {barter.expiresAt && (
              <span className="text-xs text-muted-foreground">
                Expired: {fmtDate(barter.expiresAt)}
              </span>
            )}
          </div>

          {/* Two parties */}
          <div className="grid gap-3 sm:grid-cols-2">
            <PartyCard
              label="Inisiator (Pengirim Tawaran)"
              user={initiator}
              confirmed={barter.initiatorConfirmed}
              onViewUser={onViewUser}
            />
            <PartyCard
              label="Partner (Penerima Tawaran)"
              user={partner}
              confirmed={barter.partnerConfirmed}
              onViewUser={onViewUser}
            />
          </div>

          {/* Delivery info */}
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
            {barter.deliveryMethod && (
              <div className="flex items-center gap-2 text-sm">
                {barter.deliveryMethod.includes('COD') ? <Package size={14} className="text-primary" /> : <Truck size={14} className="text-primary" />}
                <div>
                  <p className="text-xs text-muted-foreground">Metode</p>
                  <p className="font-medium text-sm">{barter.deliveryMethod}</p>
                </div>
              </div>
            )}
            {barter.codAddress && (
              <div className="text-sm">
                <p className="text-xs text-muted-foreground">Alamat COD</p>
                <p className="font-medium text-sm">{barter.codAddress}</p>
              </div>
            )}
            {barter.premiumInsuranceStatus && (
              <div className="flex items-center gap-2 text-sm">
                <Shield size={14} className="text-primary" />
                <div>
                  <p className="text-xs text-muted-foreground">Asuransi Premium</p>
                  <p className="font-medium text-sm">{barter.premiumInsuranceStatus} {barter.premiumInsuranceAmount ? '(Rp' + barter.premiumInsuranceAmount.toLocaleString('id-ID') + ')' : ''}</p>
                </div>
              </div>
            )}
          </div>

          {barter.notes && (
            <div className="bg-muted/50 rounded-lg p-3">
              <p className="text-xs text-muted-foreground mb-1">Catatan Barter</p>
              <p className="text-sm whitespace-pre-wrap">{barter.notes}</p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Chat trail */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <MessageSquare size={16} className="text-primary" /> Jejak Negosiasi ({messages.length} pesan)
          </CardTitle>
        </CardHeader>
        <CardContent>
          {messages.length === 0 ? (
            <p className="text-sm text-muted-foreground italic text-center py-6">Tidak ada pesan dalam negosiasi ini.</p>
          ) : (
            <div className="space-y-1 max-h-[600px] overflow-y-auto pr-1">
              {messages.map((msg) => {
                const isInitiator = msg.senderId === initiator.id;
                const isSystem = msg.type === 'System' || msg.type === 'COD Proposal' || msg.type === 'Deal Accepted';
                return (
                  <ChatBubble key={msg.id} msg={msg} isInitiator={isInitiator} isSystem={isSystem} />
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Reviews */}
      {reviews.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Star size={16} className="text-amber-500" /> Review Barter ({reviews.length})
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {reviews.map((rev, i) => (
              <div key={i} className="bg-muted/50 rounded-lg p-3">
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-semibold text-sm">{rev.reviewerName}</span>
                  <div className="flex gap-0.5">
                    {Array.from({ length: 5 }).map((_, s) => (
                      <Star key={s} size={12} className={s < rev.rating ? 'text-amber-400 fill-amber-400' : 'text-muted-foreground/30'} />
                    ))}
                  </div>
                  <span className="text-xs text-muted-foreground ml-auto">{fmtDate(rev.createdAt)}</span>
                </div>
                {rev.comment && <p className="text-sm text-muted-foreground">{rev.comment}</p>}
              </div>
            ))}
          </CardContent>
        </Card>
      )}
    </>
  );
}

function PartyCard({ label, user, confirmed, onViewUser }: {
  label: string;
  user: { id: string; name: string; email: string; image: string | null; itemTitle: string; itemPhoto: string | null };
  confirmed: boolean;
  onViewUser: (uid: string) => void;
}) {
  return (
    <div
      onClick={() => user.id && onViewUser(user.id)}
      className="bg-muted/30 border border-border rounded-xl p-3 cursor-pointer hover:shadow-md transition-shadow"
    >
      <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-2">{label}</p>
      <div className="flex items-center gap-2.5">
        {user.image ? (
          <img src={user.image} alt="" className="h-9 w-9 rounded-full object-cover" />
        ) : (
          <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center text-sm font-bold text-primary">
            {user.name[0]?.toUpperCase() ?? '?'}
          </div>
        )}
        <div className="min-w-0 flex-1">
          <p className="font-semibold text-sm truncate">{user.name}</p>
          <p className="text-xs text-muted-foreground truncate">{user.email}</p>
        </div>
        <div className="flex-shrink-0">
          {confirmed ? (
            <div className="flex items-center gap-1 text-emerald-600">
              <CheckCircle size={14} />
              <span className="text-[10px] font-bold">Konfirmasi</span>
            </div>
          ) : (
            <div className="flex items-center gap-1 text-muted-foreground">
              <XCircle size={14} />
              <span className="text-[10px]">Belum</span>
            </div>
          )}
