        ) : (
          <div className="h-8 w-8 rounded-lg bg-muted flex items-center justify-center">
            <Package size={12} className="text-muted-foreground" />
          </div>
        )}
        <p className="text-xs font-medium truncate flex-1">{user.itemTitle}</p>
      </div>
    </div>
  );
}

function ChatBubble({ msg, isInitiator, isSystem }: {
  msg: { id: string; senderName: string; content: string; type: string; sentAt: string | null };
  isInitiator: boolean;
  isSystem: boolean;
}) {
  const fmtTime = (d: string | null) => d ? format(new Date(d), 'HH:mm', { locale: idLocale }) : '';

  if (isSystem) {
    return (
      <div className="flex justify-center py-1">
        <span className="text-[11px] text-muted-foreground bg-muted/70 rounded-full px-3 py-1 max-w-[90%] text-center">
          {msg.content}
        </span>
      </div>
    );
  }

  return (
    <div className={`flex ${isInitiator ? 'justify-start' : 'justify-end'} mb-0.5`}>
      <div className={`max-w-[75%] rounded-2xl px-3 py-2 ${isInitiator ? 'bg-muted' : 'bg-primary/10'}`}>
        <p className={`text-[10px] font-bold mb-0.5 ${isInitiator ? 'text-blue-600' : 'text-emerald-600'}`}>
          {msg.senderName}
        </p>
        <p className="text-sm whitespace-pre-wrap break-words">{msg.content}</p>
        <p className="text-[9px] text-muted-foreground text-right mt-0.5">{fmtTime(msg.sentAt)}</p>
      </div>
    </div>
  );
}

