    "src/pages/MyItemsPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Plus, Eye, Heart, MapPin, Package } from 'lucide-react';
import { getMyItems, GetMyItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

type MyItem = GetMyItemsOutputType['items'][0];

const STATUS_COLORS: Record<string, string> = {
