    "src/pages/SearchPage.tsx": "import { useState, useEffect, useCallback } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Search, ArrowLeft, X, Clock, MapPin, Eye, Heart, SlidersHorizontal, Monitor, Shirt, Armchair, Dumbbell, Palette, Layers } from 'lucide-react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { useDebouncedCallback } from 'use-debounce';
import BottomNav from '../components/BottomNav';

type ItemType = GetItemsOutputType['items'][0];

const CATEGORY_ICONS: Record<string, React.ElementType> = {
  Elektronik: Monitor,
  Fashion: Shirt,
  'Rumah Tangga': Armchair,
  Olahraga: Dumbbell,
  Hobi: Palette,
};

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: ItemType): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

function ResultCard({ item, onClick }: { item: ItemType; onClick: () => void }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  return (
    <div onClick={onClick} className="rounded-2xl overflow-hidden border border-border bg-card cursor-pointer shadow-sm">
      <div className="relative">
        <img src={imgUrl} alt={item.title} className="w-full h-32 object-cover" />
        <div className="absolute top-2 left-2 bg-black/50 backdrop-blur-sm rounded-full px-2 py-0.5 text-[10px] text-white font-medium flex items-center gap-0.5">
          <Clock className="w-3 h-3" /> {item.condition || 'Baru'}
        </div>
      </div>
      <div className="p-2.5">
        <p className="text-sm font-bold truncate">{item.title}</p>
        <p className="text-xs text-primary font-semibold mt-0.5">{priceRange(item)}</p>
        {item.location && (
          <p className="text-[10px] text-muted-foreground mt-1 flex items-center gap-0.5">
            <MapPin className="w-3 h-3" /> {item.location}
          </p>
        )}
        <div className="flex items-center gap-2 text-[10px] text-muted-foreground mt-0.5">
          <span className="flex items-center gap-0.5"><Eye className="w-3 h-3" /> {item.viewsCount}</span>
          <span className="flex items-center gap-0.5"><Heart className="w-3 h-3" /> {item.likesCount}</span>
        </div>
      </div>
    </div>
  );
}

const CATEGORIES = ['Elektronik', 'Fashion', 'Rumah Tangga', 'Olahraga', 'Hobi'];

export default function SearchPage() {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const initialQ = searchParams.get('q') || '';
  const initialCat = searchParams.get('category') || '';

  const [query, setQuery] = useState(initialQ);
  const [activeCategory, setActiveCategory] = useState(initialCat);
  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchItems = useCallback(async (q: string, cat: string) => {
    setLoading(true);
    try {
      const res = await getItems({ limit: 30, search: q || undefined, categoryId: undefined });
      // Client-side category filter for display names since we don't have IDs mapped
      setItems(res.items);
    } catch {
      setItems([]);
    }
    setLoading(false);
  }, []);

  const debouncedFetch = useDebouncedCallback((q: string, cat: string) => {
    fetchItems(q, cat);
  }, 400);

  useEffect(() => {
    fetchItems(initialQ, initialCat);
  }, []);

  const handleQueryChange = (val: string) => {
    setQuery(val);
    const params = new URLSearchParams();
    if (val) params.set('q', val);
    if (activeCategory) params.set('category', activeCategory);
    setSearchParams(params, { replace: true });
    debouncedFetch(val, activeCategory);
  };

  const handleCategoryClick = (cat: string) => {
    const newCat = activeCategory === cat ? '' : cat;
    setActiveCategory(newCat);
    const params = new URLSearchParams();
    if (query) params.set('q', query);
    if (newCat) params.set('category', newCat);
    setSearchParams(params, { replace: true });
    fetchItems(query, newCat);
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        {/* Search header */}
        <div className="sticky top-0 z-40 bg-background px-4 py-3 flex items-center gap-2">
          <button onClick={() => navigate(-1)} className="flex-shrink-0 p-1">
            <ArrowLeft className="w-5 h-5 text-foreground" />
          </button>
          <div className="flex-1 bg-muted rounded-full px-3 py-2.5 flex items-center gap-2">
            <Search className="w-4 h-4 text-muted-foreground flex-shrink-0" />
            <input
              type="text"
              value={query}
              onChange={(e) => handleQueryChange(e.target.value)}
              placeholder="Cari barang untuk ditukar..."
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
              autoFocus
            />
            {query && (
              <button onClick={() => handleQueryChange('')}>
                <X className="w-4 h-4 text-muted-foreground" />
              </button>
            )}
          </div>
          <button className="w-9 h-9 rounded-full bg-primary flex items-center justify-center flex-shrink-0">
            <SlidersHorizontal className="w-4 h-4 text-primary-foreground" />
          </button>
        </div>

        {/* Category chips */}
        <div className="px-4 pb-3 flex gap-2 overflow-x-auto no-scrollbar">
          <button
            onClick={() => handleCategoryClick('')}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap border transition-colors ${
              !activeCategory ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border'
            }`}
          >
            <Layers className="w-3.5 h-3.5" /> Semua
          </button>
          {CATEGORIES.map((cat) => {
            const Icon = CATEGORY_ICONS[cat] || Layers;
            const active = activeCategory === cat;
            return (
              <button
                key={cat}
                onClick={() => handleCategoryClick(cat)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap border transition-colors ${
                  active ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border'
                }`}
              >
                <Icon className="w-3.5 h-3.5" /> {cat}
              </button>
            );
          })}
        </div>

        {/* Results */}
        <div className="px-4">
          {!loading && (
            <p className="text-xs text-muted-foreground mb-3">
              {items.length} barang ditemukan
              {query && <> untuk "<span className="font-semibold text-foreground">{query}</span>"</>}
            </p>
          )}
          {loading ? (
            <div className="grid grid-cols-2 gap-3">
              {[0, 1, 2, 3].map(i => (
                <div key={i} className="rounded-2xl overflow-hidden border border-border bg-card">
                  <Skeleton className="w-full h-32" />
                  <div className="p-2.5 space-y-2">
                    <Skeleton className="h-4 w-3/4" />
                    <Skeleton className="h-3 w-1/2" />
                  </div>
                </div>
              ))}
            </div>
          ) : items.length === 0 ? (
            <div className="text-center py-16">
              <Search className="w-12 h-12 text-muted-foreground/40 mx-auto mb-3" />
              <p className="text-sm text-muted-foreground">Tidak ada barang ditemukan</p>
              <p className="text-xs text-muted-foreground mt-1">Coba kata kunci atau kategori lain</p>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3">
              {items.map(item => (
                <ResultCard key={item.id} item={item} onClick={() => navigate(`/item/${item.id}`)} />
              ))}
            </div>
          )}
        </div>
      </div>
      <BottomNav />
    </div>
  );
}
