          </div>
        </div>

        {/* Stats row */}
        <div className="flex items-center justify-between mt-3 pt-3 border-t border-border text-[10px] text-muted-foreground">
          <span className="flex items-center gap-1"><Star className="w-3 h-3 text-amber-400" /> {match.condition}</span>
          <span className="flex items-center gap-1"><TrendingUp className="w-3 h-3 text-primary" /> {match.priceRange}</span>
