    "src/pages/WalletPage.tsx": "import { ArrowLeft, Wallet, TrendingUp, ArrowUpRight, ArrowDownLeft, Gift, Package, Heart, UserCheck, Sparkles, ChevronRight, Info, Shield, Crown, Trophy, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { useAuth } from 'zitejs/auth';
import { useUserPoints } from '../hooks/useUserPoints';
import { getBadge, getNextBadge, getProgressToNext, BADGES } from '../lib/badges';
import { getNotifications, GetNotificationsOutputType, markNotificationRead } from 'zitejs/api';
import BadgeChip from '../components/BadgeChip';
import { Skeleton } from '@project/components/ui/skeleton';
import { motion, AnimatePresence } from 'framer-motion';

function activityIcon(type: string) {
  switch (type) {
    case 'upload': return <Package className="w-4 h-4" />;
    case 'like_received': return <Heart className="w-4 h-4" />;
    case 'barter': return <TrendingUp className="w-4 h-4" />;
    case 'join': return <Gift className="w-4 h-4" />;
    case 'verify': return <UserCheck className="w-4 h-4" />;
    default: return <Sparkles className="w-4 h-4" />;
  }
}

function activityColor(type: string) {
  switch (type) {
    case 'upload': return 'bg-sky-100 text-sky-600';
    case 'like_received': return 'bg-pink-100 text-pink-600';
    case 'barter': return 'bg-emerald-100 text-emerald-600';
    case 'join': return 'bg-violet-100 text-violet-600';
    case 'verify': return 'bg-amber-100 text-amber-600';
    default: return 'bg-primary/10 text-primary';
  }
}

function formatDate(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
}

function formatTime(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
}

const EARN_OPTIONS = [
  { icon: Package, label: 'Upload Barang', desc: 'Dapatkan +20 MP', points: '+20 MP', path: '/upload' },
  { icon: TrendingUp, label: 'Selesaikan Barter', desc: 'Dapatkan +50 MP', points: '+50 MP', path: '/search' },
  { icon: UserCheck, label: 'Verifikasi Profil', desc: 'Dapatkan +30 MP', points: '+30 MP', path: '/security' },
];

export default function WalletPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { totalPoints, itemsUploaded, bartersCompleted, likesReceived, history, loading } = useUserPoints();
  const badge = getBadge(totalPoints);
  const next = getNextBadge(totalPoints);
  const progress = getProgressToNext(totalPoints);

  // Badge notification banner
  type NotifType = GetNotificationsOutputType['notifications'][0];
  const [badgeNotif, setBadgeNotif] = useState<NotifType | null>(null);

  useEffect(() => {
    getNotifications({ limit: 5, unreadOnly: true })
      .then(res => {
        const bn = res.notifications.find(n => n.type === 'badge' && !n.read);
        if (bn) setBadgeNotif(bn);
      })
      .catch(() => {});
  }, []);

  const dismissBadgeNotif = () => {
    if (badgeNotif) {
      markNotificationRead({ notificationId: badgeNotif.id }).catch(() => {});
      setBadgeNotif(null);
    }
  };

  // Calculate points earned this month
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthlyPoints = history
    .filter(h => new Date(h.earnedAt) >= monthStart)
    .reduce((sum, h) => sum + h.points, 0);

  // Group history by date
  const grouped: Record<string, typeof history> = {};
  history.forEach(h => {
    const key = formatDate(h.earnedAt);
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(h);
  });
  const dateKeys = Object.keys(grouped);

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
