        <div className="relative overflow-hidden rounded-b-2xl" style={{ background: 'linear-gradient(135deg, hsl(156 58% 26%), hsl(170 55% 30%))' }}>
          <div className="absolute -right-10 -top-10 w-32 h-32 rounded-full bg-white/5" />
          <div className="absolute right-16 -bottom-6 w-20 h-20 rounded-full bg-white/5" />

          <div className="relative z-10 px-4 pt-4 pb-4">
            {/* Top bar */}
            <div className="flex items-center gap-3 mb-4">
              <button onClick={() => navigate(-1)} className="w-9 h-9 rounded-full bg-white/20 flex items-center justify-center">
                <ArrowLeft className="w-4 h-4 text-white" />
              </button>
              <div className="flex-1">
                <h1 className="text-white font-bold text-base">Wallet MUTARI</h1>
                <p className="text-white/60 text-[10px]">Kelola poin & reputasimu</p>
              </div>
              {user?.image ? (
                <img src={user.image} alt="" className="w-9 h-9 rounded-full object-cover border-2 border-white/30" />
              ) : (
                <div className="w-9 h-9 rounded-full bg-white/20 text-white flex items-center justify-center text-xs font-bold border-2 border-white/30">
                  {((user?.firstName?.[0] || '') + (user?.lastName?.[0] || '') || user?.email?.[0] || 'U').toUpperCase()}
                </div>
              )}
            </div>

            {/* Balance card */}
            {loading ? (
              <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-5 space-y-3">
                <Skeleton className="h-4 w-20 bg-white/20" />
                <Skeleton className="h-10 w-32 bg-white/20" />
                <Skeleton className="h-5 w-28 bg-white/20 rounded-full" />
              </div>
            ) : (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="bg-white/10 backdrop-blur-sm rounded-2xl p-5">
                <p className="text-white/60 text-xs mb-1">Saldo Mutari Point</p>
                <div className="flex items-end gap-2 mb-3">
                  <span className="text-white font-bold text-4xl leading-none">{totalPoints.toLocaleString('id-ID')}</span>
                  <span className="text-white/60 text-sm pb-0.5">MP</span>
                </div>
                <div className="flex items-center gap-2">
                  <BadgeChip points={totalPoints} size="md" />
                  {monthlyPoints > 0 && (
                    <span className="text-emerald-300 text-[11px] font-medium flex items-center gap-0.5">
                      <ArrowUpRight className="w-3 h-3" /> +{monthlyPoints} MP bulan ini
                    </span>
                  )}
                </div>
              </motion.div>
            )}

            {/* Badge progress */}
            {!loading && next && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.15 }} className="mt-3 bg-white/10 backdrop-blur-sm rounded-xl p-3">
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-white/70 text-[11px]">{badge.emoji} {badge.name}</span>
