                    className="bg-white rounded-full h-2"
                    initial={{ width: 0 }}
                    animate={{ width: `${progress.percent}%` }}
                    transition={{ duration: 0.8, delay: 0.3 }}
                  />
                </div>
                <p className="text-white/50 text-[9px] mt-1.5">{progress.remaining} MP lagi menuju {next.name}</p>
              </motion.div>
            )}
          </div>
        </div>

        {/* Badge achievement banner */}
        <AnimatePresence>
          {badgeNotif && (
            <motion.div
              initial={{ opacity: 0, y: -10, height: 0 }}
              animate={{ opacity: 1, y: 0, height: 'auto' }}
              exit={{ opacity: 0, y: -10, height: 0 }}
              className="px-4 pt-3"
            >
              <div className="relative overflow-hidden rounded-2xl p-4" style={{ background: 'linear-gradient(135deg, hsl(45 93% 47%), hsl(36 100% 50%))' }}>
                <div className="absolute -right-6 -top-6 w-24 h-24 rounded-full bg-white/10" />
                <button onClick={dismissBadgeNotif} className="absolute top-2 right-2 w-6 h-6 rounded-full bg-black/20 flex items-center justify-center">
                  <X className="w-3 h-3 text-white" />
