                <div className="flex items-center gap-3 relative z-10">
                  <div className="w-12 h-12 rounded-full bg-white/20 flex items-center justify-center">
                    <Trophy className="w-6 h-6 text-white" />
                  </div>
                  <div className="flex-1">
                    <p className="text-white font-bold text-sm">{badgeNotif.title}</p>
                    <p className="text-white/80 text-[11px] mt-0.5 leading-relaxed">{badgeNotif.body}</p>
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Quick stats */}
        <div className="px-4 -mt-0 pt-4">
          <div className="grid grid-cols-3 gap-2">
            {[
              { label: 'Upload', value: itemsUploaded, icon: Package, color: 'text-sky-500' },
              { label: 'Barter', value: bartersCompleted, icon: TrendingUp, color: 'text-emerald-500' },
              { label: 'Like Diterima', value: likesReceived, icon: Heart, color: 'text-pink-500' },
            ].map(s => (
              <div key={s.label} className="bg-card border border-border rounded-xl p-3 text-center">
                <s.icon className={`w-4 h-4 mx-auto mb-1 ${s.color}`} />
                <p className="font-bold text-lg leading-none">{loading ? '…' : s.value}</p>
                <p className="text-[10px] text-muted-foreground mt-0.5">{s.label}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Reputation detail */}
        <div className="px-4 mt-4">
          <div className="bg-card border border-border rounded-2xl p-4">
            <div className="flex items-center gap-2 mb-1">
              <Shield className="w-4 h-4 text-primary" />
              <p className="font-bold text-sm">Detail Reputasi</p>
            </div>
            <p className="text-[10px] text-muted-foreground mb-4 ml-6">Level badge berdasarkan total Mutari Point (MP)</p>

            <div className="space-y-2">
              {BADGES.map((b) => {
                const unlocked = totalPoints >= b.minPoints;
                const isCurrent = b.id === badge.id;
                const rangeText = b.maxPoints
                  ? `${b.minPoints.toLocaleString('id-ID')} – ${b.maxPoints.toLocaleString('id-ID')} MP`
                  : `${b.minPoints.toLocaleString('id-ID')}+ MP`;

                return (
                  <div
                    key={b.id}
                    className={`rounded-xl p-3 flex items-center gap-3 transition-colors ${
                      isCurrent
                        ? 'bg-primary/10 border-2 border-primary'
                        : unlocked
                          ? 'bg-muted/50 border border-border'
                          : 'bg-muted/20 border border-border/50 opacity-60'
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg flex-shrink-0 ${
                      isCurrent ? 'bg-primary text-primary-foreground' : unlocked ? 'bg-muted' : 'bg-muted/50'
                    }`}>
                      {b.emoji}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5">
                        <p className={`text-sm font-bold truncate ${isCurrent ? 'text-primary' : ''}`}>{b.name}</p>
                        {isCurrent && (
                          <span className="text-[8px] font-bold bg-primary text-primary-foreground px-1.5 py-0.5 rounded-full flex-shrink-0">LEVEL KAMU</span>
                        )}
                      </div>
                      <p className="text-[10px] text-muted-foreground mt-0.5">{b.description}</p>
                    </div>
                    <div className="text-right flex-shrink-0">
                      <p className={`text-[11px] font-bold ${isCurrent ? 'text-primary' : 'text-foreground'}`}>{rangeText}</p>
                      {isCurrent && (
                        <p className="text-[9px] text-primary font-medium">{totalPoints.toLocaleString('id-ID')} MP</p>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Visual progress bar across all levels */}
            {!loading && (
              <div className="mt-4 pt-3 border-t border-border">
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-[10px] text-muted-foreground">Progress keseluruhan</span>
                  <span className="text-[10px] font-bold text-primary">{totalPoints.toLocaleString('id-ID')} MP</span>
                </div>
                <div className="flex gap-0.5">
                  {BADGES.map((b) => {
                    const segmentMax = b.maxPoints ?? (b.minPoints + 500);
                    const segmentRange = segmentMax - b.minPoints;
                    let fillPercent = 0;
                    if (totalPoints >= segmentMax) fillPercent = 100;
                    else if (totalPoints > b.minPoints) fillPercent = ((totalPoints - b.minPoints) / segmentRange) * 100;
                    const isCurrent = b.id === badge.id;

                    return (
                      <div key={b.id} className="flex-1">
                        <div className={`h-2.5 rounded-full overflow-hidden ${isCurrent ? 'ring-1 ring-primary ring-offset-1' : 'bg-muted'}`}>
                          <motion.div
                            className="h-full rounded-full bg-primary"
                            initial={{ width: 0 }}
                            animate={{ width: `${fillPercent}%` }}
                            transition={{ duration: 0.6, delay: 0.2 }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
                <div className="flex justify-between mt-1">
                  {BADGES.map(b => (
                    <span key={b.id} className="text-[8px] text-muted-foreground text-center flex-1">{b.emoji}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Earn points */}
        <div className="px-4 mt-4">
          <p className="font-bold text-sm mb-3">Cara Mendapatkan Poin</p>
          <div className="space-y-2">
            {EARN_OPTIONS.map(opt => (
              <button
                key={opt.label}
                onClick={() => navigate(opt.path)}
                className="w-full bg-card border border-border rounded-xl p-3 flex items-center gap-3 text-left hover:bg-muted/50 transition-colors"
              >
                <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
                  <opt.icon className="w-5 h-5 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">{opt.label}</p>
                  <p className="text-[10px] text-muted-foreground">{opt.desc}</p>
                </div>
                <span className="text-xs font-bold text-primary flex-shrink-0">{opt.points}</span>
                <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0" />
              </button>
            ))}
          </div>
        </div>

        {/* Transaction history */}
        <div className="px-4 mt-5">
          <div className="flex items-center justify-between mb-3">
            <p className="font-bold text-sm">Riwayat Transaksi</p>
            <button onClick={() => navigate('/achievements')} className="text-xs text-primary font-semibold">Semua →</button>
          </div>

          {loading ? (
            <div className="bg-card border border-border rounded-2xl p-4 space-y-4">
              {[0, 1, 2].map(i => (
                <div key={i} className="flex items-center gap-3">
                  <Skeleton className="w-10 h-10 rounded-xl" />
                  <div className="flex-1 space-y-1">
                    <Skeleton className="h-3.5 w-3/4" />
                    <Skeleton className="h-2.5 w-1/3" />
                  </div>
                  <Skeleton className="h-4 w-12" />
                </div>
              ))}
            </div>
          ) : history.length === 0 ? (
            <div className="bg-card border border-border rounded-2xl p-8 text-center">
              <div className="w-12 h-12 rounded-full bg-muted flex items-center justify-center mx-auto mb-3">
                <Wallet className="w-6 h-6 text-muted-foreground" />
              </div>
              <p className="text-sm font-semibold">Belum Ada Transaksi</p>
              <p className="text-xs text-muted-foreground mt-1">Upload barang untuk mulai mendapatkan poin.</p>
            </div>
          ) : (
            <div className="space-y-4">
              {dateKeys.slice(0, 5).map(dateKey => (
                <div key={dateKey}>
                  <p className="text-[10px] text-muted-foreground font-medium mb-2">{dateKey}</p>
                  <div className="bg-card border border-border rounded-2xl divide-y divide-border overflow-hidden">
                    {grouped[dateKey].map((h, i) => (
                      <motion.div
                        key={i}
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: i * 0.05 }}
                        className="px-4 py-3 flex items-center gap-3"
                      >
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${activityColor(h.activityType)}`}>
                          {activityIcon(h.activityType)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-semibold truncate">{h.activity}</p>
                          <p className="text-[10px] text-muted-foreground">{formatTime(h.earnedAt)}</p>
                        </div>
                        <span className={`text-sm font-bold flex items-center gap-0.5 flex-shrink-0 ${h.points >= 0 ? 'text-emerald-600' : 'text-destructive'}`}>
                          {h.points >= 0 ? <ArrowDownLeft className="w-3 h-3" /> : <ArrowUpRight className="w-3 h-3" />}
                          {h.points >= 0 ? '+' : ''}{h.points} MP
                        </span>
                      </motion.div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
