    "src/pages/WishlistPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Heart, Trash2, MapPin, Loader2 } from 'lucide-react';
import { getWishlist, toggleWishlist, GetWishlistOutputType } from 'zitejs/api';
import { toast } from 'sonner';
import { Skeleton } from '@project/components/ui/skeleton';
import BottomNav from '../components/BottomNav';

type WishlistItem = GetWishlistOutputType['items'][0];

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/aYmFPbU63ZSYCP5WK76Yni/img_5j_3U1FxA70D24aF.jpg';

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: WishlistItem): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

export default function WishlistPage() {
  const navigate = useNavigate();
  const [items, setItems] = useState<WishlistItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [removing, setRemoving] = useState<string | null>(null);

  useEffect(() => {
    getWishlist({}).then(res => {
      setItems(res.items);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const handleRemove = async (item: WishlistItem) => {
    setRemoving(item.wishlistId);
    try {
      await toggleWishlist({ itemId: item.itemId });
      setItems(prev => prev.filter(i => i.wishlistId !== item.wishlistId));
      toast.success('Dihapus dari wishlist');
    } catch {
      toast.error('Gagal menghapus');
    }
    setRemoving(null);
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1">
              <ArrowLeft className="w-5 h-5 text-white" />
            </button>
            <h1 className="font-bold text-base text-white flex-1">Wishlist</h1>
            {!loading && (
              <span className="text-white/70 text-xs">{items.length} barang</span>
            )}
          </div>
        </div>

        {loading ? (
          <div className="px-4 mt-4 space-y-3">
            {[0, 1, 2].map(i => (
              <div key={i} className="rounded-2xl border border-border bg-card p-3 flex gap-3">
                <Skeleton className="w-[90px] h-[80px] rounded-xl flex-shrink-0" />
                <div className="flex-1 space-y-2 py-1">
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-1/2" />
                  <Skeleton className="h-3 w-1/3" />
                </div>
              </div>
            ))}
          </div>
        ) : items.length === 0 ? (
          <div className="px-4 mt-16 text-center">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
              <Heart className="w-8 h-8 text-muted-foreground" />
            </div>
            <p className="font-semibold text-sm">Wishlist masih kosong</p>
            <p className="text-xs text-muted-foreground mt-1">Simpan barang yang kamu suka dari halaman detail barang</p>
            <button
              onClick={() => navigate('/')}
              className="mt-4 px-6 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold"
            >
              Jelajahi Barang
            </button>
          </div>
        ) : (
          <div className="px-4 mt-4 space-y-3">
            {items.map(item => (
              <div
                key={item.wishlistId}
                className="rounded-2xl border border-border bg-card p-3 flex gap-3 shadow-sm"
              >
                <img
                  src={item.photo || PLACEHOLDER_IMG}
                  alt={item.title}
                  className="w-[90px] h-[80px] rounded-xl object-cover flex-shrink-0 cursor-pointer"
                  onClick={() => navigate(`/item/${item.itemId}`)}
                />
                <div className="flex-1 min-w-0 flex flex-col justify-between">
                  <div>
                    <p
                      className="text-sm font-bold truncate cursor-pointer hover:text-primary transition-colors"
                      onClick={() => navigate(`/item/${item.itemId}`)}
                    >
                      {item.title}
                    </p>
                    <p className="text-xs text-primary font-semibold mt-0.5">{priceRange(item)}</p>
                    {item.location && (
                      <p className="text-[10px] text-muted-foreground flex items-center gap-0.5 mt-1">
                        <MapPin className="w-3 h-3 flex-shrink-0" /> {item.location}
                      </p>
                    )}
                  </div>
                  <div className="flex items-center justify-between mt-1.5">
                    <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full ${
                      item.status === 'Tersedia' ? 'bg-emerald-100 text-emerald-700' :
                      item.status === 'Sudah Ditukar' ? 'bg-red-100 text-red-600' :
                      'bg-amber-100 text-amber-700'
                    }`}>
                      {item.status}
                    </span>
                    <button
                      onClick={() => handleRemove(item)}
                      disabled={removing === item.wishlistId}
                      className="p-1.5 rounded-lg hover:bg-destructive/10 text-muted-foreground hover:text-destructive transition-colors"
                    >
                      {removing === item.wishlistId ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : (
                        <Trash2 className="w-4 h-4" />
                      )}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}
",
    "src/pages/BarterOfferPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, Check, Loader2 } from 'lucide-react';
import { getMyItems, createBarterOffer } from 'zitejs/api';
import type { GetMyItemsOutputType } from 'zitejs/api';
import { toast } from 'sonner';

type ItemType = GetMyItemsOutputType['items'][0];

export default function BarterOfferPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const targetItemId = params.get('targetItemId') || '';
  const targetTitle = params.get('targetTitle') || 'Barang';

  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [message, setMessage] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    getMyItems({}).then(res => {
      setItems(res.items.filter(i => i.status === 'Tersedia'));
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const handleSubmit = async () => {
    if (!selectedId) return;
    setSubmitting(true);
    try {
      const res = await createBarterOffer({
        targetItemId,
        offeredItemId: selectedId,
        message: message || undefined,
      });
      toast.success('Penawaran barter terkirim!');
      navigate(`/barter/${res.barterId}`);
    } catch (e: any) {
      toast.error(e?.message || 'Gagal mengirim penawaran');
    }
    setSubmitting(false);
  };

  const fmt = (v: number | null) => v ? 'Rp' + v.toLocaleString('id-ID') : '';

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex-1 min-w-0">
              <h1 className="font-bold text-base">Ajukan Barter</h1>
              <p className="text-xs text-muted-foreground truncate">Untuk: {targetTitle}</p>
            </div>
          </div>
        </div>

        {/* Info */}
        <div className="px-4 pt-4 pb-2">
          <div className="bg-accent/50 rounded-xl p-3 border border-primary/10">
            <p className="text-sm text-foreground font-medium">Pilih barang milikmu yang ingin ditukar</p>
            <p className="text-xs text-muted-foreground mt-1">Barang yang sudah dalam negosiasi tidak bisa dipilih</p>
          </div>
        </div>

        {/* My items */}
        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-6 h-6 animate-spin text-primary" />
          </div>
        ) : items.length === 0 ? (
          <div className="px-4 py-16 text-center">
            <p className="text-muted-foreground text-sm">Kamu belum punya barang yang tersedia</p>
            <button onClick={() => navigate('/upload')} className="mt-3 text-primary text-sm font-medium">
              + Upload Barang
            </button>
          </div>
        ) : (
          <div className="px-4 py-3 space-y-2">
            {items.map(item => (
              <button
                key={item.id}
                onClick={() => setSelectedId(item.id)}
                className={`w-full flex items-center gap-3 p-3 rounded-xl border transition-all active:scale-[0.98] ${
                  selectedId === item.id
                    ? 'border-primary bg-primary/5 ring-1 ring-primary/30'
                    : 'border-border bg-card hover:bg-muted/30'
                }`}
              >
                <div className="w-16 h-16 rounded-lg overflow-hidden bg-muted flex-shrink-0">
                  {item.photo ? (
                    <img src={item.photo} alt={item.title} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-muted-foreground text-xs">No foto</div>
                  )}
                </div>
                <div className="flex-1 text-left min-w-0">
                  <p className="font-semibold text-sm truncate">{item.title}</p>
                  <p className="text-xs text-muted-foreground">{item.condition} • {item.location || 'Lokasi belum diset'}</p>
                  {(item.estimatedValueMin || item.estimatedValueMax) && (
                    <p className="text-xs text-primary font-medium mt-0.5">
                      {fmt(item.estimatedValueMin)}{item.estimatedValueMin && item.estimatedValueMax ? ' – ' : ''}{item.estimatedValueMax && item.estimatedValueMin !== item.estimatedValueMax ? fmt(item.estimatedValueMax) : ''}
                    </p>
                  )}
                </div>
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 transition ${
                  selectedId === item.id ? 'border-primary bg-primary' : 'border-border'
                }`}>
                  {selectedId === item.id && <Check className="w-3.5 h-3.5 text-primary-foreground" />}
                </div>
              </button>
            ))}
          </div>
        )}

        {/* Message input */}
        {selectedId && (
          <div className="px-4 py-3">
            <label className="text-sm font-medium text-foreground">Pesan untuk pemilik (opsional)</label>
            <textarea
              value={message}
              onChange={e => setMessage(e.target.value)}
              placeholder="Contoh: Saya tertarik menukar karena..."
              className="mt-2 w-full rounded-xl border border-border bg-card px-3 py-2.5 text-sm resize-none h-20 focus:outline-none focus:ring-1 focus:ring-primary"
            />
          </div>
        )}

        {/* Submit bar */}
        <div className="fixed bottom-0 left-0 right-0 bg-card/95 backdrop-blur-md border-t border-border z-50">
          <div className="max-w-[420px] mx-auto px-4 py-3">
            <button
              onClick={handleSubmit}
              disabled={!selectedId || submitting}
              className="w-full py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
            >
              {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
              {submitting ? 'Mengirim...' : 'Kirim Penawaran Barter'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
",
    "src/pages/BarterNegotiationPage.tsx": "import { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Send, MapPin, CheckCircle2, Loader2, AlertTriangle, Clock, XCircle, Star } from 'lucide-react';
import { getBarterDetail, getBarterMessages, sendBarterMessage, respondBarterOffer, setCodLocation, confirmBarterComplete, cancelBarter, submitBarterReview } from 'zitejs/api';
import type { GetBarterDetailOutputType, GetBarterMessagesOutputType } from 'zitejs/api';
import { useAuth } from 'zitejs/auth';
import { toast } from 'sonner';
import BarterItemCard from '../components/barter/BarterItemCard';
import CodModal from '../components/barter/CodModal';
import ConfirmModal from '../components/barter/ConfirmModal';
import ReviewModal from '../components/barter/ReviewModal';
import CancelModal from '../components/barter/CancelModal';

type BarterType = GetBarterDetailOutputType['barter'];
type MessageType = GetBarterMessagesOutputType['messages'][0];

export default function BarterNegotiationPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [barter, setBarter] = useState<BarterType | null>(null);
  const [messages, setMessages] = useState<MessageType[]>([]);
  const [loading, setLoading] = useState(true);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const [showCod, setShowCod] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const [showCancel, setShowCancel] = useState(false);
  const [responding, setResponding] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async () => {
    if (!id) return;
    try {
      const [bd, bm] = await Promise.all([
        getBarterDetail({ barterId: id }),
        getBarterMessages({ barterId: id }),
      ]);
      setBarter(bd.barter);
      setMessages(bm.messages);
    } catch { /* ignore */ }
    setLoading(false);
  }, [id]);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!id) return;
    const iv = setInterval(async () => {
      try {
        const bm = await getBarterMessages({ barterId: id });
        setMessages(bm.messages);
      } catch { /* ignore */ }
    }, 5000);
    return () => clearInterval(iv);
  }, [id]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!text.trim() || !id) return;
    const content = text.trim();
    setText('');
    setSending(true);
    try {
      await sendBarterMessage({ barterId: id, content, type: 'Text' });
      await loadData();
    } catch {
      toast.error('Gagal mengirim pesan');
    }
    setSending(false);
  };

  const handleRespond = async (action: 'accept' | 'reject') => {
    if (!id) return;
    setResponding(true);
    try {
      await respondBarterOffer({ barterId: id, action });
      toast.success(action === 'accept' ? 'Penawaran diterima!' : 'Penawaran ditolak');
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal merespons');
    }
    setResponding(false);
  };

  const handleCodSubmit = async (address: string, detail: string) => {
    if (!id) return;
    try {
      await setCodLocation({ barterId: id, address, detail: detail || undefined });
      toast.success('Lokasi COD berhasil diset');
      setShowCod(false);
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal');
    }
  };

  const handleConfirmComplete = async () => {
    if (!id) return;
    try {
      const res = await confirmBarterComplete({ barterId: id });
      if (res.bothConfirmed) {
        toast.success(`🎉 Barter selesai! +${res.pointsEarned} poin`);
      } else {
        toast.success('Konfirmasi dikirim. Menunggu pihak lain.');
      }
      setShowConfirm(false);
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal mengonfirmasi');
    }
  };

  const handleCancel = async (reason: string) => {
    if (!id) return;
    try {
      await cancelBarter({ barterId: id, reason });
      toast.success('Barter dibatalkan');
      setShowCancel(false);
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal membatalkan');
    }
  };

  const handleReview = async (rating: number, comment: string, aspect: string) => {
    if (!id) return;
    try {
      const res = await submitBarterReview({ barterId: id, rating, comment, aspect: aspect as any });
      toast.success(`Review terkirim! +${res.bonusPoints} poin`);
      setShowReview(false);
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal mengirim review');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader2 className="w-6 h-6 animate-spin text-primary" />
      </div>
    );
  }

  if (!barter) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <p className="text-muted-foreground">Barter tidak ditemukan</p>
      </div>
    );
  }

  const myConfirmed = barter.myRole === 'initiator' ? barter.initiatorConfirmed : barter.partnerConfirmed;
  const otherConfirmed = barter.myRole === 'initiator' ? barter.partnerConfirmed : barter.initiatorConfirmed;
  const isWaiting = barter.status === 'Menunggu' && barter.myRole === 'partner';
  const isWaitingInitiator = barter.status === 'Menunggu' && barter.myRole === 'initiator';
  const isAccepted = barter.status === 'Diterima';
  const isComplete = barter.status === 'Selesai';
  const isCancelled = barter.status === 'Dibatalkan';
  const otherName = barter.myRole === 'initiator' ? barter.partner.name : barter.initiator.name;
  const canCancel = barter.status === 'Menunggu' || barter.status === 'Diterima';

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <div className="max-w-[420px] mx-auto w-full flex flex-col flex-1">
        {/* Header */}
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex-1 min-w-0">
              <h1 className="font-bold text-sm truncate">Negosiasi Barter</h1>
              <p className="text-[11px] text-muted-foreground">dengan {otherName}</p>
            </div>
            <StatusBadge status={barter.status} />
          </div>
        </div>

        {/* Items comparison */}
        <div className="px-4 py-3 border-b border-border bg-card">
          <div className="flex items-center gap-2">
            <BarterItemCard
              title={barter.offeredItem?.title || ''}
              photo={barter.offeredItem?.photo || null}
              condition={barter.offeredItem?.condition || ''}
              label={barter.myRole === 'initiator' ? 'Barangmu' : 'Barang mereka'}
              valueMin={barter.offeredItem?.estimatedValueMin ?? null}
              valueMax={barter.offeredItem?.estimatedValueMax ?? null}
            />
            <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
              <span className="text-primary text-sm font-bold">↔</span>
            </div>
            <BarterItemCard
              title={barter.requestedItem?.title || ''}
              photo={barter.requestedItem?.photo || null}
              condition={barter.requestedItem?.condition || ''}
              label={barter.myRole === 'initiator' ? 'Barang mereka' : 'Barangmu'}
              valueMin={barter.requestedItem?.estimatedValueMin ?? null}
              valueMax={barter.requestedItem?.estimatedValueMax ?? null}
            />
          </div>
        </div>

        {/* Expiry countdown */}
        {barter.status === 'Menunggu' && barter.expiresAt && (
          <ExpiryBanner expiresAt={barter.expiresAt} />
        )}

        {/* COD Location banner */}
        {barter.codAddress && (
          <div className="px-4 py-2 bg-accent/30 border-b border-primary/10">
            <div className="flex items-start gap-2">
              <MapPin className="w-4 h-4 text-primary mt-0.5 flex-shrink-0" />
              <div>
                <p className="text-xs font-semibold text-primary">Lokasi COD</p>
                <p className="text-xs text-foreground">{barter.codAddress}</p>
                {barter.codDetail && <p className="text-[11px] text-muted-foreground">{barter.codDetail}</p>}
              </div>
            </div>
          </div>
        )}

        {/* Confirmation status */}
        {isAccepted && (myConfirmed || otherConfirmed) && (
          <div className="px-4 py-2 bg-green-50 dark:bg-green-950/20 border-b border-green-200 dark:border-green-800">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4 text-green-600" />
              <p className="text-xs text-green-700 dark:text-green-400">
                {myConfirmed && otherConfirmed ? 'Kedua pihak sudah konfirmasi' :
                 myConfirmed ? 'Anda sudah konfirmasi. Menunggu pihak lain.' :
                 'Pihak lain sudah konfirmasi. Giliran Anda!'}
              </p>
            </div>
          </div>
        )}

        {/* Accept/Reject bar for partner */}
        {isWaiting && (
          <div className="px-4 py-3 bg-yellow-50 dark:bg-yellow-950/20 border-b border-yellow-200 dark:border-yellow-800">
            <p className="text-xs text-yellow-700 dark:text-yellow-400 font-medium mb-2 flex items-center gap-1.5">
              <AlertTriangle className="w-3.5 h-3.5" /> Anda menerima penawaran barter
            </p>
            <div className="flex gap-2">
              <button
                onClick={() => handleRespond('accept')}
                disabled={responding}
                className="flex-1 py-2.5 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 active:scale-[0.98] transition"
              >
                {responding ? '...' : 'Terima'}
              </button>
              <button
                onClick={() => handleRespond('reject')}
                disabled={responding}
                className="flex-1 py-2.5 rounded-xl border border-destructive text-destructive font-semibold text-sm disabled:opacity-50 active:scale-[0.98] transition"
              >
                Tolak
              </button>
            </div>
          </div>
        )}

        {/* Chat messages */}
        <div className="flex-1 overflow-y-auto px-4 py-3 space-y-2">
          {messages.map(msg => {
            const isMe = msg.senderId === user?.id;
            const isSystem = msg.type === 'System' || msg.type === 'COD Proposal';
            if (isSystem) {
              return (
                <div key={msg.id} className="flex justify-center py-1">
                  <div className="bg-muted/60 px-3 py-1.5 rounded-full max-w-[85%]">
                    <p className="text-[11px] text-muted-foreground text-center">{msg.content}</p>
                  </div>
                </div>
              );
            }
            return (
              <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[75%] px-3 py-2 rounded-2xl ${
                  isMe
                    ? 'bg-primary text-primary-foreground rounded-br-md'
                    : 'bg-card border border-border rounded-bl-md'
                }`}>
                  <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                  <p className={`text-[10px] mt-1 ${isMe ? 'text-primary-foreground/60' : 'text-muted-foreground'}`}>
                    {msg.sentAt ? new Date(msg.sentAt).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : ''}
                  </p>
                </div>
              </div>
            );
          })}
          <div ref={chatEndRef} />
        </div>

        {/* Bottom action bar — active barter */}
        {!isComplete && !isCancelled && (
          <div className="sticky bottom-0 bg-card/95 backdrop-blur-md border-t border-border">
            {/* Action buttons */}
            <div className="flex gap-2 px-4 pt-2 flex-wrap">
              {isAccepted && (
                <>
                  <button
                    onClick={() => setShowCod(true)}
                    className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-accent border border-primary/20 text-primary text-xs font-medium active:scale-95 transition"
                  >
                    <MapPin className="w-3.5 h-3.5" /> Atur COD
                  </button>
                  {!myConfirmed && (
                    <button
                      onClick={() => setShowConfirm(true)}
                      className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-green-600 text-white text-xs font-medium active:scale-95 transition"
                    >
                      <CheckCircle2 className="w-3.5 h-3.5" /> Selesai Barter
                    </button>
                  )}
                </>
              )}
              {canCancel && (
                <button
                  onClick={() => setShowCancel(true)}
                  className="flex items-center gap-1 px-3 py-1.5 rounded-lg border border-destructive/30 text-destructive text-xs font-medium active:scale-95 transition ml-auto"
                >
                  <XCircle className="w-3.5 h-3.5" /> Batalkan
                </button>
              )}
            </div>
            {/* Chat input */}
            <div className="flex items-center gap-2 px-4 py-2.5">
              <input
                type="text"
                value={text}
                onChange={e => setText(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleSend()}
                placeholder="Tulis pesan..."
                className="flex-1 bg-muted rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
              />
              <button
                onClick={handleSend}
                disabled={!text.trim() || sending}
                className="p-2 rounded-full bg-primary text-primary-foreground disabled:opacity-40 active:scale-90 transition"
              >
                <Send className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        {/* Complete status + review prompt */}
        {isComplete && (
          <div className="sticky bottom-0 bg-card border-t border-border px-4 py-4">
            <div className="flex items-center justify-center gap-2 text-green-600">
              <CheckCircle2 className="w-5 h-5" />
              <p className="font-semibold text-sm">Barter Selesai! 🎉</p>
            </div>
            <p className="text-xs text-muted-foreground mt-1 text-center">Kedua pihak telah mengonfirmasi</p>

            {!barter.myReviewSubmitted ? (
              <button
                onClick={() => setShowReview(true)}
                className="w-full mt-3 py-2.5 rounded-xl bg-primary text-primary-foreground font-semibold text-sm flex items-center justify-center gap-2 active:scale-[0.98] transition"
              >
                <Star className="w-4 h-4" /> Beri Rating & Review (+10 poin)
              </button>
            ) : (
              <div className="mt-3 bg-accent/50 rounded-xl p-3 border border-primary/10 text-center">
                <p className="text-xs text-primary font-medium">✅ Anda sudah memberikan review</p>
                {!barter.otherReviewSubmitted && (
                  <p className="text-[11px] text-muted-foreground mt-1">Menunggu review dari {otherName}</p>
                )}
              </div>
            )}
          </div>
        )}

        {/* Cancelled status */}
        {isCancelled && (
          <div className="sticky bottom-0 bg-card border-t border-border px-4 py-4 text-center">
            <div className="flex items-center justify-center gap-2 text-destructive">
              <XCircle className="w-5 h-5" />
              <p className="font-semibold text-sm">
                {barter.isExpired ? 'Penawaran Kedaluwarsa' : 'Barter Dibatalkan'}
              </p>
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              {barter.isExpired ? 'Tidak ada respon dalam 3 hari' : 'Salah satu pihak membatalkan barter ini'}
            </p>
          </div>
        )}
      </div>

      {/* Modals */}
      {showCod && (
        <CodModal currentAddress={barter.codAddress || ''} currentDetail={barter.codDetail || ''} onClose={() => setShowCod(false)} onSubmit={handleCodSubmit} />
      )}
      {showConfirm && (
        <ConfirmModal onClose={() => setShowConfirm(false)} onConfirm={handleConfirmComplete} />
      )}
      {showReview && (
        <ReviewModal partnerName={otherName} onClose={() => setShowReview(false)} onSubmit={handleReview} />
      )}
      {showCancel && (
        <CancelModal isAfterAccepted={isAccepted} onClose={() => setShowCancel(false)} onSubmit={handleCancel} />
      )}
    </div>
  );
}

function ExpiryBanner({ expiresAt }: { expiresAt: string }) {
  const [timeLeft, setTimeLeft] = useState('');

  useEffect(() => {
    const update = () => {
      const diff = new Date(expiresAt).getTime() - Date.now();
      if (diff <= 0) {
        setTimeLeft('Kedaluwarsa');
        return;
      }
      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      if (hours >= 24) {
        const days = Math.floor(hours / 24);
        setTimeLeft(`${days} hari ${hours % 24} jam`);
      } else {
        setTimeLeft(`${hours} jam ${minutes} menit`);
      }
    };
    update();
    const iv = setInterval(update, 60000);
    return () => clearInterval(iv);
  }, [expiresAt]);

  const isUrgent = new Date(expiresAt).getTime() - Date.now() < 24 * 60 * 60 * 1000;

  return (
    <div className={`px-4 py-2 border-b flex items-center gap-2 ${
      isUrgent
        ? 'bg-red-50 dark:bg-red-950/20 border-red-200 dark:border-red-800'
        : 'bg-yellow-50 dark:bg-yellow-950/20 border-yellow-200 dark:border-yellow-800'
    }`}>
      <Clock className={`w-4 h-4 flex-shrink-0 ${isUrgent ? 'text-red-600' : 'text-yellow-600'}`} />
      <p className={`text-xs font-medium ${isUrgent ? 'text-red-700 dark:text-red-400' : 'text-yellow-700 dark:text-yellow-400'}`}>
        Batas waktu respon: <span className="font-bold">{timeLeft}</span>
      </p>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, { bg: string; text: string }> = {
    Menunggu: { bg: 'bg-yellow-100 dark:bg-yellow-900/30', text: 'text-yellow-700 dark:text-yellow-400' },
    Diterima: { bg: 'bg-blue-100 dark:bg-blue-900/30', text: 'text-blue-700 dark:text-blue-400' },
    Selesai: { bg: 'bg-green-100 dark:bg-green-900/30', text: 'text-green-700 dark:text-green-400' },
    Dibatalkan: { bg: 'bg-red-100 dark:bg-red-900/30', text: 'text-red-700 dark:text-red-400' },
  };
  const s = map[status] || map.Menunggu;
  return (
    <span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${s.bg} ${s.text}`}>
      {status}
    </span>
  );
}
