    "src/components/detail/AIAnalysis.tsx": "import { Sparkles, ShieldCheck, TrendingUp, MapPin, CheckCircle, Lightbulb, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface Props {
  matchPercent: number;
  condition: string;
  priceRange: string;
  distance: string;
  itemId?: string;
  title?: string;
  estimatedValueMin?: number | null;
  estimatedValueMax?: number | null;
  likesCount?: number;
  viewsCount?: number;
}

function generateRecommendations(props: Props): string[] {
  const recs: string[] = [];
  const { estimatedValueMin, estimatedValueMax, condition, likesCount, viewsCount } = props;

  // Price analysis
  const min = estimatedValueMin ?? 0;
  const max = estimatedValueMax ?? 0;
  if (min > 0 || max > 0) {
    const fmt = (v: number) => 'Rp ' + v.toLocaleString('id-ID');
    if (min && max && min !== max) {
      recs.push(`Estimasi nilai pasar: ${fmt(min)} – ${fmt(max)}. Berada di rentang wajar untuk kategori ini.`);
    } else if (min || max) {
      recs.push(`Estimasi nilai pasar sekitar ${fmt(min || max)}. AI menghitung berdasarkan kondisi & kategori.`);
    }
  } else {
    recs.push('Nilai pasar belum dapat diestimasi — tambahkan detail lebih lengkap untuk analisis yang lebih akurat.');
  }

  // Condition analysis
  const condMap: Record<string, string> = {
    'Baru': 'Barang dalam kondisi baru — nilai tukar optimal.',
    'Seperti Baru': 'Kondisi seperti baru — peluang barter sangat baik.',
    'Baik': 'Kondisi baik — cocok untuk ditukar dengan barang sejenis.',
    'Cukup': 'Kondisi cukup — pertimbangkan menambah detail foto untuk meningkatkan daya tarik.',
  };
  recs.push(condMap[condition] || 'Kondisi barang sesuai deskripsi berdasarkan analisis data.');

  // Popularity analysis
  const likes = likesCount ?? 0;
  const views = viewsCount ?? 0;
  if (likes > 10) {
    recs.push(`Barang ini sangat diminati (${likes} suka) — banyak calon penukar tertarik.`);
  } else if (views > 20) {
    recs.push(`Sudah dilihat ${views} kali — tingkat ketertarikan cukup tinggi.`);
  } else if (views > 0) {
    recs.push('Barang mulai menarik perhatian — pastikan foto dan deskripsi lengkap untuk meningkatkan minat.');
  } else {
    recs.push('Barang baru diunggah — AI akan terus menganalisis seiring bertambahnya data.');
  }

  return recs;
}

function generateWhyText(props: Props): string {
  const { matchPercent, likesCount, viewsCount } = props;
  if (matchPercent >= 85) {
    return 'Barang ini memiliki peluang barter tinggi berdasarkan nilai, kondisi, dan lokasi yang sesuai dengan banyak pengguna.';
  }
  if ((likesCount ?? 0) > 5) {
    return 'Barang ini diminati banyak pengguna — AI mencocokkan berdasarkan preferensi dan nilai pasar.';
  }
  if ((viewsCount ?? 0) > 10) {
    return 'Berdasarkan aktivitas pengguna dan data pasar, barang ini memiliki potensi barter yang baik.';
  }
  return 'AI memperkirakan nilai dari kategori, kondisi, dan data pasar terkini.';
}

export default function AIAnalysis(props: Props) {
  const { matchPercent, condition, priceRange, distance, itemId } = props;
  const navigate = useNavigate();
  const recommendations = generateRecommendations(props);
  const whyText = generateWhyText(props);

  return (
    <div className="mx-4 mt-3 bg-card rounded-2xl border border-border overflow-hidden">
      {/* Header */}
      <div className="bg-accent px-4 py-3 flex items-center gap-3">
        <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
          <Sparkles className="w-5 h-5 text-primary" />
        </div>
        <div>
          <p className="font-bold text-sm">Analisis AI</p>
          <p className="text-[10px] text-muted-foreground">Micro AI · hanya barang ini</p>
        </div>
      </div>

      <div className="p-4">
        {/* Match circle + stats */}
        <div className="flex items-center gap-6">
          {/* Circle */}
          <div className="relative w-24 h-24 flex-shrink-0">
            <svg className="w-24 h-24 -rotate-90" viewBox="0 0 100 100">
              <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="8" className="text-muted" />
              <circle
                cx="50" cy="50" r="42" fill="none"
                stroke="currentColor" strokeWidth="8"
                className="text-primary"
                strokeDasharray={`${matchPercent * 2.64} 264`}
                strokeLinecap="round"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-2xl font-bold text-foreground">{matchPercent}%</span>
              <span className="text-[10px] text-muted-foreground">Match</span>
            </div>
          </div>

          {/* Stats */}
          <div className="flex-1 space-y-2.5">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <ShieldCheck className="w-3.5 h-3.5 text-primary" />
                <span>Estimasi Kondisi</span>
              </div>
              <span className="text-xs font-bold">{condition || '-'}</span>
            </div>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <TrendingUp className="w-3.5 h-3.5 text-primary" />
                <span>Estimasi Nilai Pasar</span>
              </div>
              <span className="text-xs font-bold">{priceRange}</span>
            </div>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <MapPin className="w-3.5 h-3.5 text-primary" />
                <span>Lokasi</span>
              </div>
              <span className="text-xs font-bold">{distance}</span>
            </div>
          </div>
        </div>

        {/* AI explanation */}
        <div className="mt-4 pt-4 border-t border-border">
          <div className="flex items-center gap-2 mb-2">
            <CheckCircle className="w-4 h-4 text-primary" />
            <span className="font-semibold text-sm">Mengapa AI merekomendasikan ini</span>
          </div>
          <p className="text-xs text-muted-foreground">{whyText}</p>
        </div>

        {/* AI recommendations */}
        <div className="mt-4 pt-4 border-t border-border">
          <div className="flex items-center gap-2 mb-3">
            <Lightbulb className="w-4 h-4 text-primary" />
            <span className="font-semibold text-sm">Rekomendasi AI</span>
          </div>
          <div className="space-y-3">
            {recommendations.map((text, i) => (
              <div key={i} className="flex gap-3">
                <div className="w-5 h-5 rounded-full bg-accent text-primary text-[10px] font-bold flex items-center justify-center flex-shrink-0 mt-0.5">
                  {i + 1}
                </div>
                <p className="text-xs text-muted-foreground">{text}</p>
              </div>
            ))}
          </div>
        </div>

        {/* CTA */}
        <button onClick={() => navigate(`/smart-match/${itemId || ''}`)} className="w-full mt-4 bg-primary text-primary-foreground rounded-xl py-3.5 flex items-center justify-center gap-2 font-semibold text-sm">
          <Sparkles className="w-4 h-4" />
          Buka AI Smart Match
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}
