    "src/api/likeItem.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

function badgeId(points: number): string {
  if (points >= 2500) return 'legenda';
  if (points >= 1000) return 'profesional';
  if (points >= 500) return 'terpercaya';
  if (points >= 200) return 'aktif';
  return 'pemula';
}

const BADGE_NAMES: Record<string, { name: string; emoji: string }> = {
  pemula: { name: 'MUTARI Pemula', emoji: '🌱' },
  aktif: { name: 'Barter Aktif', emoji: '🤝' },
  terpercaya: { name: 'Mitra Terpercaya', emoji: '⭐' },
  profesional: { name: 'Barter Profesional', emoji: '🛡️' },
  legenda: { name: 'Legenda MUTARI', emoji: '👑' },
};

async function notifyBadgeUpgrade(userId: string, oldBadge: string, newTotal: number) {
  const newBadge = badgeId(newTotal);
  if (newBadge === oldBadge) return;
  const info = BADGE_NAMES[newBadge];
  if (!info) return;
  await zite.notifications.create({
    record: {
      title: `${info.emoji} Badge Baru: ${info.name}!`,
      body: `Selamat! Kamu telah mencapai level ${info.name} dengan ${newTotal} MP. Terus tingkatkan reputasimu!`,
      type: 'badge',
      recipient: userId,
      read: false,
      linkPath: '/wallet',
    },
  });
}

export default createEndpoint({
  description: 'Toggle like on an item and award points to item owner',
  authenticated: true,
  inputSchema: z.object({
    id: z.string(),
    liked: z.boolean(),
  }),
  outputSchema: z.object({
    likesCount: z.number(),
  }),
  execute: async ({ input, context }) => {
    const record = await zite.items.findOne({ id: input.id });
    if (!record) throw new Error('Item not found');

    const current = record.likesCount ?? 0;
    const newCount = input.liked ? current + 1 : Math.max(0, current - 1);

    await zite.items.update({ id: input.id, record: { likesCount: newCount } });

    // Award 2 points to the item owner when liked (not when unliked)
    if (input.liked && record.owner) {
      const ownerId = Array.isArray(record.owner) ? record.owner[0] : record.owner;
      // Don't award points for liking your own item
      if (ownerId && ownerId !== context.user.id) {
        let ownerPoints = await zite.userPoints.findOne({ filters: { user: ownerId } });
        if (ownerPoints) {
          const oldBadge = ownerPoints.currentBadge || 'pemula';
          const newTotal = (ownerPoints.totalPoints ?? 0) + 2;
          const newLikes = (ownerPoints.likesReceived ?? 0) + 1;
          await zite.userPoints.update({
            id: ownerPoints.id,
            record: {
              totalPoints: newTotal,
              likesReceived: newLikes,
              currentBadge: badgeId(newTotal),
            },
          });
          await notifyBadgeUpgrade(ownerId, oldBadge, newTotal);
        } else {
          await zite.userPoints.create({
            record: {
              label: 'User',
              user: ownerId,
              totalPoints: 12,
              itemsUploaded: 0,
              bartersCompleted: 0,
              likesReceived: 1,
              currentBadge: 'pemula',
            },
          });
        }
        await zite.pointHistory.create({
          record: {
            activity: `Barangmu "${record.title}" disukai`,
            user: ownerId,
            points: 2,
            activityType: 'like_received',
          },
        });
      }
    }

    return { likesCount: newCount };
  },
});
