    "src/api/getBarterDetail.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const itemSchema = z.object({
  id: z.string(),
  title: z.string(),
  photo: z.string().nullable(),
  condition: z.string(),
  estimatedValueMin: z.number().nullable(),
  estimatedValueMax: z.number().nullable(),
});

export default createEndpoint({
  description: 'Get full barter detail including items, users, status, review info, and expiry',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    barter: z.object({
      id: z.string(),
      title: z.string(),
      status: z.string(),
      createdAt: z.string().nullable(),
      completedAt: z.string().nullable(),
      expiresAt: z.string().nullable(),
      codAddress: z.string().nullable(),
      codDetail: z.string().nullable(),
      initiatorConfirmed: z.boolean(),
      partnerConfirmed: z.boolean(),
      notes: z.string().nullable(),
      initiator: z.object({ id: z.string(), name: z.string(), image: z.string().nullable() }),
      partner: z.object({ id: z.string(), name: z.string(), image: z.string().nullable() }),
      offeredItem: itemSchema.nullable(),
      requestedItem: itemSchema.nullable(),
      myRole: z.enum(['initiator', 'partner']),
      myReviewSubmitted: z.boolean(),
      otherReviewSubmitted: z.boolean(),
      isExpired: z.boolean(),
    }),
  }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Check expiry: auto-cancel if "Menunggu" and past 3 days
    let currentStatus = barter.status || 'Menunggu';
    let isExpired = false;
    const expiresAt = barter.expiresAt ?? null;

    if (currentStatus === 'Menunggu' && expiresAt) {
      const expiry = new Date(expiresAt);
      if (new Date() > expiry) {
        isExpired = true;
        currentStatus = 'Dibatalkan';
        // Auto-cancel expired barter
        await zite.barterHistory.update({ id: input.barterId, record: { status: 'Dibatalkan' } });
        const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
        const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
        if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Tersedia' } });
        if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Tersedia' } });
        await zite.barterMessages.create({
          record: {
            barter: input.barterId,
            sender: context.user.id,
            content: '⏰ Penawaran otomatis dibatalkan karena tidak ada respon dalam 3 hari.',
            type: 'System',
          },
        });
      }
    }

    // Fetch users
    const users = await zite.auth.findAllUsers({ limit: 50 });
    const initiatorUser = users.records.find(u => u.id === initiatorId);
    const partnerUser = users.records.find(u => u.id === partnerId);

    // Fetch items
    const offeredItemId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
    const requestedItemId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;

    const [offeredItem, requestedItem] = await Promise.all([
      offeredItemId ? zite.items.findOne({ id: offeredItemId }) : null,
      requestedItemId ? zite.items.findOne({ id: requestedItemId }) : null,
    ]);

    const mapItem = (item: typeof offeredItem) => item ? {
      id: item.id,
      title: item.title || 'Tanpa judul',
      photo: item.photos?.[0]?.url || null,
      condition: item.condition || '',
      estimatedValueMin: item.estimatedValueMin ?? null,
      estimatedValueMax: item.estimatedValueMax ?? null,
    } : null;

    // Check review status
    const { records: reviews } = await zite.barterReviews.findAll({
      limit: 10,
    });
    const barterReviews = reviews.filter(r => {
      const bIds = Array.isArray(r.barter) ? r.barter : r.barter ? [r.barter] : [];
      return bIds.includes(input.barterId);
    });

    const myReviewSubmitted = barterReviews.some(r => {
      const rIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      return rIds.includes(context.user.id);
    });
    const otherUserId = context.user.id === initiatorId ? partnerId : initiatorId;
    const otherReviewSubmitted = barterReviews.some(r => {
      const rIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      return rIds.includes(otherUserId || '');
    });

    return {
      barter: {
        id: barter.id,
        title: barter.title || '',
        status: currentStatus,
        createdAt: barter.createdAt ?? null,
        completedAt: barter.completedAt ?? null,
        expiresAt,
        codAddress: barter.codAddress ?? null,
        codDetail: barter.codDetail ?? null,
        initiatorConfirmed: barter.initiatorConfirmed ?? false,
        partnerConfirmed: barter.partnerConfirmed ?? false,
        notes: barter.notes ?? null,
        initiator: {
          id: initiatorId || '',
          name: initiatorUser?.name || 'Pengguna',
          image: initiatorUser?.image ?? null,
        },
        partner: {
          id: partnerId || '',
          name: partnerUser?.name || 'Pengguna',
          image: partnerUser?.image ?? null,
        },
        offeredItem: mapItem(offeredItem),
        requestedItem: mapItem(requestedItem),
        myRole: context.user.id === initiatorId ? 'initiator' as const : 'partner' as const,
        myReviewSubmitted,
        otherReviewSubmitted,
        isExpired,
      },
    };
  },
});
