    "src/api/getActiveChats.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get active barter conversations for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    chats: z.array(z.object({
      barterId: z.string(),
      title: z.string(),
      status: z.string(),
      otherUserName: z.string(),
      otherUserImage: z.string().nullable(),
      lastMessage: z.string().nullable(),
      lastMessageAt: z.string().nullable(),
      offeredItemPhoto: z.string().nullable(),
      requestedItemPhoto: z.string().nullable(),
    })),
  }),
  execute: async ({ context }) => {
    // Find all barters where user is initiator or partner
    const { rows } = await zite.sql({
      query: `SELECT bh."id", bh."title", bh."status", bh."initiator", bh."partner",
                     bh."offeredItem", bh."requestedItem", bh."createdAt"
              FROM "BarterHistory" bh
              WHERE bh."status" IN ('Menunggu', 'Diterima')
              ORDER BY bh."createdAt" DESC
              LIMIT 50`,
    });

    const users = await zite.auth.findAllUsers({ limit: 100 });
    const userMap = new Map(users.records.map(u => [u.id, u]));

    const chats: Array<{
      barterId: string;
      title: string;
      status: string;
      otherUserName: string;
      otherUserImage: string | null;
      lastMessage: string | null;
      lastMessageAt: string | null;
      offeredItemPhoto: string | null;
      requestedItemPhoto: string | null;
    }> = [];
    for (const r of rows) {
      const initiatorIds = Array.isArray(r.initiator) ? r.initiator as string[] : r.initiator ? [r.initiator as string] : [];
      const partnerIds = Array.isArray(r.partner) ? r.partner as string[] : r.partner ? [r.partner as string] : [];

      const isInitiator = initiatorIds.includes(context.user.id);
      const isPartner = partnerIds.includes(context.user.id);
      if (!isInitiator && !isPartner) continue;

      const otherUserId = isInitiator ? partnerIds[0] : initiatorIds[0];
      const otherUser = otherUserId ? userMap.get(otherUserId) : null;

      // Get last message
      const { rows: msgRows } = await zite.sql({
        query: `SELECT bm."content", bm."sentAt"
                FROM "BarterMessages" bm
                JOIN "BarterMessagesBarterHistory" link ON link."barterMessagesId" = bm."id"
                WHERE link."barterHistoryId" = $1
                ORDER BY bm."sentAt" DESC
                LIMIT 1`,
        params: [r.id as string],
      });

      // Get item photos
      const offeredItemIds = Array.isArray(r.offeredItem) ? r.offeredItem as string[] : r.offeredItem ? [r.offeredItem as string] : [];
      const requestedItemIds = Array.isArray(r.requestedItem) ? r.requestedItem as string[] : r.requestedItem ? [r.requestedItem as string] : [];

      const [offeredItem, requestedItem] = await Promise.all([
        offeredItemIds[0] ? zite.items.findOne({ id: offeredItemIds[0], fields: ['photos'] }) : null,
        requestedItemIds[0] ? zite.items.findOne({ id: requestedItemIds[0], fields: ['photos'] }) : null,
      ]);

      chats.push({
        barterId: r.id as string,
        title: (r.title as string) || 'Barter',
        status: (r.status as string) || 'Menunggu',
        otherUserName: otherUser?.name || 'Pengguna',
        otherUserImage: otherUser?.image ?? null,
        lastMessage: msgRows[0]?.content as string ?? null,
        lastMessageAt: msgRows[0]?.sentAt as string ?? null,
        offeredItemPhoto: offeredItem?.photos?.[0]?.url || null,
        requestedItemPhoto: requestedItem?.photos?.[0]?.url || null,
      });
    }

    return { chats };
  },
});
