    "useLocation": "src/context/LocationContext.tsx — GPS location context (kecamatan, kabupaten, lat, lng, radius)"
  },

  "theme": {
    "font": "Plus Jakarta Sans",
    "primaryColor": "hsl(156 58% 26%) — hijau tua MUTARI",
    "borderRadius": "0.75rem",
    "mode": "light",
    "cssFile": "src/index.css"
  },

  "uploadConfig": {
    "categories": ["Elektronik", "Fashion", "Olahraga", "Otomotif", "Buku & Hobi", "Peralatan Rumah", "Gaming", "Lainnya"],
    "conditions": ["Baru", "Seperti Baru", "Baik", "Cukup"],
    "completeness": ["Dus / Box", "Kartu Garansi", "Nota Pembelian", "Charger", "Kabel", "Tas / Case", "Buku Manual", "Aksesori Tambahan"],
    "phoneVerificationRequired": false,
    "note": "Phone verification di-skip sementara karena WhatsApp OTP gateway belum terhubung"
  },

  "smartMatch": {
    "algorithm": "Multi-factor scoring",
    "factors": [
      "Value similarity (up to 30 pts) — perbandingan estimatedValueMin/Max",
      "Condition match (up to 15 pts) — ranking: Baru=4, Seperti Baru=3, Baik=2, Cukup=1",
      "Location proximity (up to 15 pts) — haversine distance: <2km=15, <5km=10, <10km=5",
      "Popularity bonus (up to 10 pts) — likes>5=+5, views>20=+5"
    ],
    "baseScore": 50,
    "maxScore": 99,
    "minScore": 30,
    "topResults": 10,
    "dataSource": "SQL join Items + ziteUsers, status=Tersedia, limit 50"
  },

  "locationSystem": {
    "provider": "navigator.geolocation + Nominatim reverse geocoding",
    "reverseGeocodeUrl": "https://nominatim.openstreetmap.org/reverse",
    "fields": ["kecamatan", "kabupaten", "lat", "lng"],
    "mandatory": true,
    "defaultRadius": 10
  },

  "bottomNavTabs": [
    { "icon": "Home", "label": "Beranda", "path": "/" },
    { "icon": "Search", "label": "Cari", "path": "/search" },
    { "icon": "Plus", "label": "Barter", "path": "/upload", "center": true },
    { "icon": "MessageCircle", "label": "Chat", "path": "/chat" },
    { "icon": "User", "label": "Profil", "path": "/profile" }
  ],

  "detailBottomBarActions": [
    { "icon": "Bookmark", "label": "Simpan", "action": "toggleWishlist" },
    { "icon": "MessageCircle", "label": "Chat", "action": "navigate /chat with state" },
    { "icon": "Sparkles", "label": "AI", "action": "navigate /smart-match/:id" },
    { "icon": "Repeat", "label": "Barter", "action": "navigate /smart-match/:id" }
  ],

  "profilePage": {
    "file": "src/pages/ProfilePage.tsx",
    "route": "/profile",
    "features": [
      "Green header dengan avatar, nama, email",
      "Inline progress bar MP menuju badge berikutnya (link ke /wallet)",
      "Menu: Wallet MUTARI, Barang Saya, Wishlist, Riwayat Barter, Achievements",
      "Menu: Edit Profil, Alamat, Notifikasi, Keamanan, Pengaturan, Bantuan"
    ],
    "menuItems": [
      { "icon": "Wallet", "label": "Wallet MUTARI", "path": "/wallet" },
      { "icon": "Package", "label": "Barang Saya", "path": "/my-items" },
      { "icon": "Heart", "label": "Wishlist", "path": "/wishlist" },
      { "icon": "History", "label": "Riwayat Barter", "path": "/barter-history" },
      { "icon": "Trophy", "label": "Achievements", "path": "/achievements" },
      { "icon": "UserCog", "label": "Edit Profil", "path": "/edit-profile" },
      { "icon": "MapPin", "label": "Alamat", "path": "/address" },
      { "icon": "Bell", "label": "Notifikasi", "path": "/notification-settings" },
      { "icon": "Shield", "label": "Keamanan", "path": "/security" },
      { "icon": "Settings", "label": "Pengaturan", "path": "/settings" },
      { "icon": "HelpCircle", "label": "Bantuan", "path": "/help" }
    ]
  },

  "notificationSystem": {
    "database": "Notifications table (sdkName: notifications)",
    "types": ["Badge", "Barter", "Like", "Chat", "Milestone", "System"],
    "endpoints": {
      "getNotifications": "Fetch user notifications with optional limit & unreadOnly filter",
      "markNotificationRead": "Mark single notification or all unread as read"
    },
    "ui": {
      "notificationsPage": "src/pages/Notifications.tsx — Full list dengan icon per type, time ago, mark all read",
      "walletBanner": "src/pages/WalletPage.tsx — Animated banner untuk badge notification terbaru"
    },
    "triggerPoints": {
      "uploadItem": "Badge upgrade check setelah +20 poin → buat notification jika badge naik",
      "likeItem": "Badge upgrade check setelah +2 poin ke owner → buat notification jika badge naik"
    }
  },

  "pendingFeatures": {
    "whatsappOtp": "Menunggu WhatsApp gateway (Fonnte/Twilio) untuk kirim OTP sungguhan",
    "chatPage": "ChatPage.tsx masih berisi mock chat — belum ada real-time messaging"
  }
}
