    "src/App.tsx": "import { useEffect } from 'react';
import { useAuth } from 'zitejs/auth';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { Toaster } from '@project/components/ui/sonner';
import { LocationProvider } from './context/LocationContext';
import { UnreadProvider } from './context/UnreadContext';
import { I18nProvider } from './context/I18nContext';
import LocationGate from './components/LocationGate';
import SetupGate from './components/SetupGate';
import LandingPage from './pages/LandingPage';
import Beranda from './pages/Beranda';
import ItemDetail from './pages/ItemDetail';
import SmartMatch from './pages/SmartMatch';
import AIIntelligence from './pages/AIIntelligence';
import UploadBarang from './pages/UploadBarang';
import SearchPage from './pages/SearchPage';
import Notifications from './pages/Notifications';
import ChatPage from './pages/ChatPage';
import ProfilePage from './pages/ProfilePage';
import AchievementsPage from './pages/AchievementsPage';
import EditProfilePage from './pages/EditProfilePage';
import AddressPage from './pages/AddressPage';
import NotificationSettingsPage from './pages/NotificationSettingsPage';
import SecurityPage from './pages/SecurityPage';
import SettingsPage from './pages/SettingsPage';
import HelpPage from './pages/HelpPage';
import WishlistPage from './pages/WishlistPage';
import BarterHistoryPage from './pages/BarterHistoryPage';
import MyItemsPage from './pages/MyItemsPage';
import WalletPage from './pages/WalletPage';
import BarterOfferPage from './pages/BarterOfferPage';
import BarterNegotiationPage from './pages/BarterNegotiationPage';
import UserProfilePage from './pages/UserProfilePage';
import ReferralPage from './pages/ReferralPage';
import MyPublicProfilePage from './pages/MyPublicProfilePage';
import LinkedAccountsPage from './pages/LinkedAccountsPage';
import PreferredCategoriesPage from './pages/PreferredCategoriesPage';
import StatsPage from './pages/StatsPage';

export default function App() {
  const { user, isLoading } = useAuth();

  // Restore theme from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('mutari-theme');
    if (saved === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, []);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="flex flex-col items-center gap-3">
          <div className="w-14 h-14 rounded-2xl bg-primary flex items-center justify-center animate-pulse">
