    "src/api/getBarterMessages.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get chat messages for a barter negotiation',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    messages: z.array(z.object({
      id: z.string(),
      senderId: z.string(),
      senderName: z.string(),
      content: z.string(),
      type: z.string(),
      sentAt: z.string().nullable(),
    })),
  }),
  execute: async ({ input, context }) => {
    // Verify user is part of this barter
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Fetch messages
    const { rows } = await zite.sql({
      query: `SELECT bm."id", bm."sender", bm."content", bm."type", bm."sentAt"
              FROM "BarterMessages" bm
              JOIN "BarterMessagesBarterHistory" link ON link."barterMessagesId" = bm."id"
              WHERE link."barterHistoryId" = $1
              ORDER BY bm."sentAt" ASC
              LIMIT 500`,
      params: [input.barterId],
    });

    // Get user names
    const users = await zite.auth.findAllUsers({ limit: 50 });
    const userMap = new Map(users.records.map(u => [u.id, u.name]));

    return {
      messages: rows.map((r: any) => {
        const senderIds = Array.isArray(r.sender) ? r.sender : r.sender ? [r.sender] : [];
        const senderId = senderIds[0] || '';
        return {
          id: r.id as string,
          senderId,
          senderName: userMap.get(senderId) || 'Pengguna',
          content: (r.content as string) || '',
          type: (r.type as string) || 'Text',
          sentAt: (r.sentAt as string) ?? null,
        };
      }),
    };
  },
});
