    "src/api/getReferral.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Gets the current user referral code and stats',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    referralCode: z.string(),
    totalReferred: z.number(),
    completedReferrals: z.number(),
    totalBonusPoints: z.number(),
    referrals: z.array(z.object({
      id: z.string(),
      referredName: z.string(),
      referredImage: z.string().nullable(),
      status: z.string(),
      bonusPoints: z.number(),
      createdAt: z.string(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Generate a stable referral code from user id
    const codeBase = userId.replace(/-/g, '').slice(0, 8).toUpperCase();
    const referralCode = `MUTARI-${codeBase}`;

    // Get all referrals where this user is the referrer
    const { records } = await zite.referrals.findAll({
      filters: { referrer: userId },
      limit: 100,
    });

    const completedReferrals = records.filter(r => r.status === 'completed').length;
    const totalBonusPoints = records.reduce((sum, r) => sum + (r.bonusPoints || 0), 0);

    // Get referred user details
    const referredUserIds = records
      .map(r => {
        const val = r.referredUser;
        return Array.isArray(val) ? val[0] : val;
      })
      .filter(Boolean) as string[];

    let userMap: Record<string, { name: string; image: string | null }> = {};
    if (referredUserIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: { in: referredUserIds } },
        limit: 100,
      });
      for (const u of users) {
        userMap[u.id] = { name: u.name || u.email, image: u.image };
      }
    }

    const referrals = records.map(r => {
      const refUserId = Array.isArray(r.referredUser) ? r.referredUser[0] : r.referredUser;
      const u = refUserId ? userMap[refUserId] : undefined;
      return {
        id: r.id,
        referredName: u?.name || 'Pengguna',
        referredImage: u?.image || null,
        status: r.status || 'pending',
        bonusPoints: r.bonusPoints || 0,
        createdAt: r.createdAt || new Date().toISOString(),
      };
    });

    return {
      referralCode,
      totalReferred: records.length,
      completedReferrals,
      totalBonusPoints,
      referrals,
    };
  },
});
