    "src/api/getUnreadCounts.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get unread counts for chat messages and notifications',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    unreadChats: z.number(),
    unreadNotifications: z.number(),
    latestNotification: z.object({
      id: z.string(),
      title: z.string(),
      body: z.string(),
      type: z.string(),
      createdAt: z.string(),
    }).nullable(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Count unread chat notifications
    const { rows: chatRows } = await zite.sql({
      query: `SELECT COUNT(*)::int AS cnt FROM "Notifications"
              WHERE "type" = 'Chat' AND "read" = false
              AND "recipient" @> to_jsonb(ARRAY[$1])`,
      params: [userId],
    });

    // Count all unread notifications
    const { rows: notifRows } = await zite.sql({
      query: `SELECT COUNT(*)::int AS cnt FROM "Notifications"
              WHERE "read" = false
              AND "recipient" @> to_jsonb(ARRAY[$1])`,
      params: [userId],
    });

    // Get latest unread notification for push
    const { rows: latestRows } = await zite.sql({
      query: `SELECT "id", "title", "body", "type", "createdAt"
              FROM "Notifications"
              WHERE "read" = false
              AND "recipient" @> to_jsonb(ARRAY[$1])
              ORDER BY "createdAt" DESC
              LIMIT 1`,
      params: [userId],
    });

    const latest = latestRows[0];

    return {
      unreadChats: (chatRows[0]?.cnt as number) || 0,
      unreadNotifications: (notifRows[0]?.cnt as number) || 0,
      latestNotification: latest ? {
        id: latest.id as string,
        title: (latest.title as string) || '',
        body: (latest.body as string) || '',
        type: (latest.type as string) || 'system',
        createdAt: (latest.createdAt as string) || '',
      } : null,
    };
  },
});
",
    "src/api/getUserPoints.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get the current user points, badge, and achievement history',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalPoints: z.number(),
    itemsUploaded: z.number(),
    bartersCompleted: z.number(),
    likesReceived: z.number(),
    currentBadge: z.string(),
    totalMinusPoints: z.number(),
    activeViolations: z.number(),
    history: z.array(z.object({
      activity: z.string(),
      points: z.number(),
      activityType: z.string(),
      earnedAt: z.string(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Get or create user points record
    let userPoints = await zite.userPoints.findOne({
      filters: { user: userId },
    });

    if (!userPoints) {
      // First time — create record and award join bonus
      userPoints = await zite.userPoints.create({
        record: {
          label: context.user.email || 'User',
          user: userId,
          totalPoints: 10,
          itemsUploaded: 0,
          bartersCompleted: 0,
          likesReceived: 0,
          currentBadge: 'pemula',
        },
      });
      await zite.pointHistory.create({
        record: {
          activity: 'Bergabung di MUTARI',
          user: userId,
          points: 10,
          activityType: 'join',
        },
      });
    }

    // Fetch violations summary
    const { records: violations } = await zite.violations.findAll({
      filters: { user: userId, status: 'Aktif' },
      limit: 500,
    });
    const totalMinusPoints = violations.reduce((sum, v) => sum + (v.minusPoints ?? 0), 0);
    const activeViolations = violations.length;

    // Fetch history
    const { records: history } = await zite.pointHistory.findAll({
      filters: { user: userId },
      limit: 50,
    });

    // Sort by earnedAt desc (since findAll sort is ignored)
    const sorted = history.sort((a, b) =>
      new Date(b.earnedAt || '').getTime() - new Date(a.earnedAt || '').getTime()
    );

    return {
      totalPoints: userPoints.totalPoints ?? 0,
      itemsUploaded: userPoints.itemsUploaded ?? 0,
      bartersCompleted: userPoints.bartersCompleted ?? 0,
      likesReceived: userPoints.likesReceived ?? 0,
      currentBadge: userPoints.currentBadge ?? 'pemula',
      totalMinusPoints,
      activeViolations,
      history: sorted.map(h => ({
        activity: h.activity || '',
        points: h.points ?? 0,
        activityType: h.activityType || '',
        earnedAt: h.earnedAt || '',
      })),
    };
  },
});
