    "src/api/reportViolation.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const VIOLATION_POINTS: Record<string, number> = {
  multi_nego_ghost: -35,
  cherry_picker: -30,
  cod_egois: -28,
  upgrade_hunter: -27,
  fake_listing: -25,
  no_show: -15,
  item_mismatch: -10,
  cancel_after_cod_set: -8,
  cancel_after_deal: -7,
  ghosting: -3,
  expired_repeated: -2,
  slow_response: -1,
  incomplete_listing: -1,
  last_minute_change: -1,
};

const VIOLATION_SEVERITY: Record<string, string> = {
  multi_nego_ghost: 'paling_berat',
  cherry_picker: 'paling_berat',
  cod_egois: 'paling_berat',
  upgrade_hunter: 'paling_berat',
  fake_listing: 'berat',
  no_show: 'berat',
  item_mismatch: 'berat',
  cancel_after_cod_set: 'sedang',
  cancel_after_deal: 'sedang',
  ghosting: 'sedang',
  expired_repeated: 'sedang',
  slow_response: 'ringan',
  incomplete_listing: 'ringan',
  last_minute_change: 'ringan',
};

const VIOLATION_LABELS: Record<string, string> = {
  multi_nego_ghost: 'Multi-Negosiasi Ghost',
  cherry_picker: 'Cherry-Picker',
  cod_egois: 'COD Egois',
  upgrade_hunter: 'Upgrade Hunter',
  fake_listing: 'Fake Listing',
  no_show: 'Tidak Hadir COD',
  item_mismatch: 'Barang Tidak Sesuai',
  cancel_after_cod_set: 'Batal Setelah COD Di-set',
  cancel_after_deal: 'Batal Sepihak Setelah Deal',
  ghosting: 'Ghosting Negosiasi',
  expired_repeated: 'Barter Expired Berulang',
  slow_response: 'Respons Lambat Berulang',
  incomplete_listing: 'Listing Tidak Lengkap',
  last_minute_change: 'Ubah Syarat di Menit Terakhir',
};

export default createEndpoint({
  description: 'Report a violation against a user with evidence, deduct minus points, and flag for admin review',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
    violationType: z.string(),
    barterId: z.string().optional(),
    notes: z.string().optional(),
    evidenceUrls: z.array(z.string()).optional(),
    reportedUserName: z.string().optional(),
    reportedUserPhone: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    violation: z.object({
      id: z.string(),
      type: z.string(),
      severity: z.string(),
      minusPoints: z.number(),
    }),
    newTotalMinus: z.number(),
  }),
  execute: async ({ input, context }) => {
    // Prevent self-report
    if (input.userId === context.user.id) {
      throw new ZiteError('Tidak bisa melaporkan diri sendiri');
    }

    const minusPoints = VIOLATION_POINTS[input.violationType] ?? -1;
    const severity = VIOLATION_SEVERITY[input.violationType] ?? 'ringan';
    const label = VIOLATION_LABELS[input.violationType] ?? input.violationType;

    // Build detailed notes with reporter info
    const detailParts: string[] = [];
    if (input.reportedUserName) detailParts.push(`Nama terlapor: ${input.reportedUserName}`);
    if (input.reportedUserPhone) detailParts.push(`No. HP terlapor: ${input.reportedUserPhone}`);
    if (input.notes) detailParts.push(`Keterangan: ${input.notes}`);
    detailParts.push(`Dilaporkan oleh: ${context.user.firstName || context.user.email}`);
    const fullNotes = detailParts.join('\n');

    // Build evidence attachments
    const evidenceAttachments = (input.evidenceUrls || []).map((url, i) => ({
      url,
      filename: `bukti-${i + 1}.jpg`,
    }));

    const violation = await zite.violations.create({
      record: {
        label,
        user: input.userId,
        violationType: label,
        severity: severity === 'paling_berat' ? 'Paling Berat' : severity === 'berat' ? 'Berat' : severity === 'sedang' ? 'Sedang' : 'Ringan',
        minusPoints,
        barter: input.barterId || null,
        reportedBy: context.user.id,
        notes: fullNotes,
        status: 'Aktif',
        evidence: evidenceAttachments.length > 0 ? evidenceAttachments : null,
      } as any,
    });

    // Log in point history
    await zite.pointHistory.create({
      record: {
        activity: `Pelanggaran: ${label}`,
        user: input.userId,
        points: minusPoints,
        activityType: 'violation',
      },
    });

    // Update user points
    const userPoints = await zite.userPoints.findOne({
      filters: { user: input.userId },
    });
    if (userPoints) {
      const newTotal = Math.max(0, (userPoints.totalPoints ?? 0) + minusPoints);
      await zite.userPoints.update({
        id: userPoints.id,
        record: { totalPoints: newTotal },
      });
    }

    // Total minus
    const { records: allViolations } = await zite.violations.findAll({
      filters: { user: input.userId, status: 'Aktif' },
      limit: 500,
    });
    const totalMinus = allViolations.reduce((sum, v) => sum + (v.minusPoints ?? 0), 0);

    // Notify the violator
    await zite.notifications.create({
      record: {
        title: `Pelanggaran: ${label}`,
        body: `Kamu mendapat ${minusPoints} MP karena ${label.toLowerCase()}. Laporan ini akan ditinjau oleh admin.`,
        type: 'System',
        recipient: input.userId,
        read: false,
        linkPath: '/wallet',
      },
    });

    return {
      success: true,
      violation: {
        id: violation.id,
        type: input.violationType,
        severity,
        minusPoints,
      },
      newTotalMinus: totalMinus,
    };
  },
});
",
    "src/api/respondBarterOffer.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Accept or reject a barter offer',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    action: z.enum(['accept', 'reject']),
  }),
  outputSchema: z.object({ success: z.boolean(), status: z.string() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== partnerId) {
      throw new ZiteError('Hanya penerima yang bisa merespons');
    }
    if (barter.status !== 'Menunggu') {
      throw new ZiteError('Penawaran sudah direspons');
    }

    const newStatus = input.action === 'accept' ? 'Diterima' : 'Dibatalkan';
    await zite.barterHistory.update({ id: input.barterId, record: { status: newStatus } });

    if (input.action === 'reject') {
      // Reset item statuses
      const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
      const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
      if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Tersedia' } });
      if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Tersedia' } });
    }

    // System message
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: input.action === 'accept' ? '✅ Penawaran diterima! Silakan tentukan lokasi COD.' : '❌ Penawaran ditolak.',
        type: 'System',
      },
    });

    // Notify initiator
    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    if (initiatorId) {
      await zite.notifications.create({
        record: {
          title: input.action === 'accept' ? 'Penawaran Diterima! 🎉' : 'Penawaran Ditolak',
          body: input.action === 'accept' ? `${`${context.user.firstName || context.user.email.split("@")[0]}`} menerima penawaran barter Anda` : `${`${context.user.firstName || context.user.email.split("@")[0]}`} menolak penawaran barter Anda`,
          type: 'Barter',
          recipient: initiatorId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { success: true, status: newStatus };
  },
});
