    "src/api/sendPhoneOtp.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Send a 6-digit OTP code to verify a phone number via simulated SMS/WA',
  authenticated: true,
  inputSchema: z.object({
    phone: z.string().min(8),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const code = String(Math.floor(100000 + Math.random() * 900000));

    let profile = await zite.userProfiles.findOne({ filters: { user: userId } });
    if (!profile) {
      profile = await zite.userProfiles.create({
        record: {
          displayName: context.user.email.split('@')[0],
          user: userId,
          phone: input.phone,
          bio: null, address: null, city: null, province: null, postalCode: null,
          preferredBarterMethod: 'COD',
          phoneVerified: false, addressVerified: false,
          emailNotifications: true, pushNotifications: true,
          chatNotifications: true, barterNotifications: true,
        },
      });
    } else {
      await zite.userProfiles.update({
        id: profile.id,
        record: { phone: input.phone, phoneVerified: false },
      });
    }

    // Store the OTP code temporarily in the bio field with a prefix (simple approach)
    // In production you'd use SMS/WA API — here we store and auto-verify
    const otpData = `OTP:${code}:${Date.now()}`;
    await zite.userProfiles.update({
      id: profile.id,
      record: { bio: profile.bio ? `${profile.bio}|||${otpData}` : otpData },
    });

    return {
      success: true,
      message: `Kode verifikasi telah dikirim ke ${input.phone}`,
    };
  },
});
