    "src/api/submitBarterReview.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Submit a review and rating for the other party after barter is completed',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    rating: z.number().min(1).max(5),
    comment: z.string().min(1).max(500),
    aspect: z.enum([
      'barang_sesuai', 'komunikasi_baik', 'tepat_waktu', 'ramah',
      'tidak_sesuai', 'tidak_responsif',
    ]),
  }),
  outputSchema: z.object({ reviewId: z.string(), bonusPoints: z.number() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    if (barter.status !== 'Selesai') {
      throw new ZiteError('Hanya bisa review setelah barter selesai');
    }

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Determine reviewee
    const revieweeId = context.user.id === initiatorId ? partnerId : initiatorId;
    if (!revieweeId) throw new ZiteError('Partner tidak ditemukan');

    // Check if already reviewed
    const { records: existing } = await zite.barterReviews.findAll({
      filters: { reviewer: context.user.id },
      limit: 100,
    });
    // Filter by barter id — the barter field is a linked record
    const alreadyReviewed = existing.some(r => {
      const barterIds = Array.isArray(r.barter) ? r.barter : r.barter ? [r.barter] : [];
      return barterIds.includes(input.barterId);
    });
    if (alreadyReviewed) {
      throw new ZiteError('Anda sudah memberikan review untuk barter ini');
    }

    // Map aspect value to label for display
    const aspectMap: Record<string, string> = {
      barang_sesuai: 'Barang Sesuai Deskripsi',
      komunikasi_baik: 'Komunikasi Baik',
      tepat_waktu: 'Tepat Waktu COD',
      ramah: 'Ramah & Sopan',
      tidak_sesuai: 'Barang Tidak Sesuai',
      tidak_responsif: 'Tidak Responsif',
    };

    const review = await zite.barterReviews.create({
      record: {
        barter: input.barterId,
        reviewer: context.user.id,
        reviewee: revieweeId,
        rating: input.rating,
        comment: input.comment,
        aspect: aspectMap[input.aspect] || input.aspect,
      },
    });

    // Bonus points for leaving a review
    const bonusPoints = 10;
    const existingPoints = await zite.userPoints.findOne({ filters: { user: context.user.id } });
    if (existingPoints) {
      await zite.userPoints.update({
        id: existingPoints.id,
        record: { totalPoints: (existingPoints.totalPoints ?? 0) + bonusPoints },
      });
    }
    await zite.pointHistory.create({
      record: {
        activity: 'Menulis Review Barter',
        user: context.user.id,
        points: bonusPoints,
        activityType: 'review_submitted',
      },
    });

    // System message in barter chat
    const stars = '⭐'.repeat(input.rating);
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: `${stars} Review diberikan: "${input.comment}"`,
        type: 'System',
      },
    });

    // Notify reviewee
    await zite.notifications.create({
      record: {
        title: `Anda mendapat rating ${input.rating}⭐`,
        body: `"${input.comment.slice(0, 80)}"`,
        type: 'Barter',
        recipient: revieweeId,
        read: false,
        linkPath: `/barter/${input.barterId}`,
      },
    });

    return { reviewId: review.id, bonusPoints };
  },
});
",
    "src/api/toggleWishlist.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Toggle an item in the user wishlist (add or remove)',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    saved: z.boolean(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Check if already saved
    const { records } = await zite.wishlist.findAll({
      filters: { user: userId, item: input.itemId },
      limit: 1,
    });

    if (records.length > 0) {
      // Remove from wishlist
