    // Fetch item title for label
    const item = await zite.items.findOne({ id: input.itemId });
    const label = item?.title || 'Item';

    // Add to wishlist
    await zite.wishlist.create({
      record: {
        label,
        user: userId,
        item: input.itemId,
      },
    });

    return { saved: true };
  },
});
