        <div className="flex items-center gap-1.5 mt-1.5 pt-1.5 border-t border-border">
          {item.ownerImage ? (
            <img src={item.ownerImage} alt={item.ownerName} className="w-5 h-5 rounded-full object-cover border border-border" />
          ) : (
            <div className="w-5 h-5 rounded-full bg-primary text-primary-foreground text-[8px] flex items-center justify-center font-bold">
              {(item.ownerName || 'P').charAt(0).toUpperCase()}
            </div>
          )}
          <span className="text-[10px] font-medium truncate">{item.ownerName || 'Pengguna'}</span>
        </div>
      </div>
    </div>
  );
}

