    "src/components/SetupGate.tsx": "import { useState, useEffect, type ReactNode } from 'react';
import { Eye, EyeOff, Lock, Loader2, ShieldCheck } from 'lucide-react';
import { getProfile, setupPassword } from 'zitejs/api';
import { useAuth } from 'zitejs/auth';
import { toast } from 'sonner';

export default function SetupGate({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [checking, setChecking] = useState(true);
  const [needsSetup, setNeedsSetup] = useState(false);

  useEffect(() => {
    if (!user) { setChecking(false); return; }
    getProfile({}).then(res => {
      setNeedsSetup(!res.hasPassword);
      setChecking(false);
    }).catch(() => setChecking(false));
  }, [user]);

  if (checking) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="w-10 h-10 rounded-full bg-primary flex items-center justify-center animate-pulse">
          <span className="text-primary-foreground font-bold text-sm">M</span>
        </div>
      </div>
    );
  }

  if (needsSetup && user) {
    return <PasswordSetup onComplete={() => setNeedsSetup(false)} />;
  }

  return <>{children}</>;
}

function PasswordSetup({ onComplete }: { onComplete: () => void }) {
  const { user } = useAuth();
  const [pw, setPw] = useState('');
  const [confirmPw, setConfirmPw] = useState('');
  const [showPw, setShowPw] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async () => {
    setError('');
    if (pw.length < 6) { setError('Password minimal 6 karakter'); return; }
    if (pw !== confirmPw) { setError('Password tidak cocok'); return; }

    setSaving(true);
    try {
      await setupPassword({ password: pw });
      toast.success('Password MUTARI berhasil dibuat!');
      onComplete();
    } catch {
      setError('Gagal menyimpan password');
    }
    setSaving(false);
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center px-6">
      <div className="max-w-[380px] w-full">
        {/* Logo */}
        <div className="text-center mb-8">
          <div className="mx-auto w-20 h-20 rounded-2xl bg-primary flex items-center justify-center mb-4">
            <ShieldCheck className="w-10 h-10 text-primary-foreground" />
          </div>
          <h1 className="text-2xl font-bold text-foreground">Selamat Datang!</h1>
          <p className="text-sm text-muted-foreground mt-1">Buat password MUTARI untuk akun kamu</p>
        </div>

        {/* User info */}
        <div className="bg-card rounded-2xl border border-border p-4 mb-6 flex items-center gap-3">
          {user?.image ? (
            <img src={user.image} alt="" className="w-12 h-12 rounded-full object-cover" />
          ) : (
            <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold text-lg">
              {user?.name?.[0]?.toUpperCase() || 'U'}
            </div>
          )}
          <div className="flex-1 min-w-0">
            <p className="font-semibold text-sm truncate">{user?.name || 'Pengguna'}</p>
            <p className="text-xs text-muted-foreground truncate">{user?.email}</p>
          </div>
        </div>

        {/* Password fields */}
        <div className="space-y-4">
          <div>
            <label className="text-sm font-semibold text-foreground mb-1.5 block">Password MUTARI</label>
            <div className="relative">
              <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <input
                type={showPw ? 'text' : 'password'}
                value={pw}
                onChange={e => setPw(e.target.value)}
                placeholder="Minimal 6 karakter"
                className="w-full bg-muted rounded-xl pl-10 pr-10 py-3.5 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
              />
              <button type="button" onClick={() => setShowPw(!showPw)} className="absolute right-3 top-1/2 -translate-y-1/2 p-0.5">
                {showPw ? <EyeOff className="w-4 h-4 text-muted-foreground" /> : <Eye className="w-4 h-4 text-muted-foreground" />}
              </button>
            </div>
          </div>

          <div>
            <label className="text-sm font-semibold text-foreground mb-1.5 block">Konfirmasi Password</label>
            <div className="relative">
              <Lock className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <input
                type={showConfirm ? 'text' : 'password'}
                value={confirmPw}
                onChange={e => setConfirmPw(e.target.value)}
                placeholder="Ulangi password"
                className="w-full bg-muted rounded-xl pl-10 pr-10 py-3.5 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
              />
              <button type="button" onClick={() => setShowConfirm(!showConfirm)} className="absolute right-3 top-1/2 -translate-y-1/2 p-0.5">
                {showConfirm ? <EyeOff className="w-4 h-4 text-muted-foreground" /> : <Eye className="w-4 h-4 text-muted-foreground" />}
              </button>
            </div>
          </div>

          {error && (
            <p className="text-sm text-destructive font-medium">{error}</p>
          )}

          <button
            onClick={handleSubmit}
            disabled={saving || !pw || !confirmPw}
            className="w-full bg-primary text-primary-foreground rounded-xl py-3.5 font-semibold text-sm flex items-center justify-center gap-2 active:scale-[0.98] transition-transform disabled:opacity-60"
          >
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
            {saving ? 'Menyimpan...' : 'Buat Password & Lanjutkan'}
          </button>
        </div>

        <p className="text-[10px] text-muted-foreground text-center mt-6 leading-relaxed">
          Password ini khusus untuk MUTARI dan berbeda dari password Google kamu. Gunakan untuk keamanan tambahan saat bertransaksi.
        </p>
      </div>
    </div>
  );
}
