    "src/components/detail/CommentSection.tsx": "import { useState, useEffect } from 'react';
import { useAuth } from 'zitejs/auth';
import { MessageCircle, Send, Loader2 } from 'lucide-react';
import { getComments, postComment, GetCommentsOutputType } from 'zitejs/api';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';

type Comment = GetCommentsOutputType['comments'][0];

export default function CommentSection({ itemId }: { itemId: string }) {
  const { user } = useAuth();
  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);

  useEffect(() => {
    getComments({ itemId })
      .then(r => setComments(r.comments))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [itemId]);

  const handleSend = async () => {
    if (!text.trim() || sending) return;
    setSending(true);
    try {
      const c = await postComment({ itemId, content: text.trim() });
      setComments(prev => [c, ...prev]);
      setText('');
    } catch {
      toast.error('Gagal mengirim komentar');
    }
    setSending(false);
  };

  return (
    <div className="px-4 mt-2 mb-4">
      <div className="flex items-center gap-2 mb-3">
        <MessageCircle className="w-4 h-4 text-primary" />
        <p className="font-bold text-sm text-foreground">
          Komentar {comments.length > 0 && <span className="text-muted-foreground font-normal">({comments.length})</span>}
        </p>
      </div>

      {/* Input */}
      <div className="flex gap-2 mb-4">
        {user?.image ? (
          <img src={user.image} alt="" className="w-8 h-8 rounded-full object-cover flex-shrink-0 border border-border" />
        ) : (
          <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center flex-shrink-0 text-xs font-bold border border-border">
            {(user?.firstName?.[0] || user?.email?.[0] || 'U').toUpperCase()}
          </div>
        )}
        <div className="flex-1 flex gap-2">
          <input
            value={text}
            onChange={e => setText(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Tulis komentar..."
            maxLength={500}
            className="flex-1 border border-border rounded-full px-4 py-2 text-sm bg-card text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-colors"
          />
          <button
            onClick={handleSend}
            disabled={!text.trim() || sending}
            className="w-9 h-9 rounded-full bg-primary text-primary-foreground flex items-center justify-center flex-shrink-0 disabled:opacity-40 transition-opacity"
          >
            {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Comments list */}
      {loading ? (
        <div className="flex items-center justify-center py-6">
          <Loader2 className="w-5 h-5 animate-spin text-muted-foreground" />
        </div>
      ) : comments.length === 0 ? (
        <div className="text-center py-6">
          <MessageCircle className="w-8 h-8 text-muted-foreground/30 mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">Belum ada komentar. Jadilah yang pertama!</p>
        </div>
      ) : (
        <div className="space-y-3">
          {comments.map(c => (
            <div key={c.id} className="flex gap-2.5">
              {c.authorImage ? (
                <img src={c.authorImage} alt="" className="w-8 h-8 rounded-full object-cover flex-shrink-0 border border-border" />
              ) : (
                <div className="w-8 h-8 rounded-full bg-muted text-foreground flex items-center justify-center flex-shrink-0 text-xs font-bold">
                  {c.authorName[0]?.toUpperCase() || 'A'}
                </div>
              )}
              <div className="flex-1 min-w-0">
                <div className="flex items-baseline gap-2">
                  <span className="text-xs font-semibold text-foreground">{c.authorName}</span>
                  <span className="text-[10px] text-muted-foreground">
                    {formatDistanceToNow(new Date(c.createdAt), { addSuffix: true, locale: idLocale })}
                  </span>
                </div>
                <p className="text-sm text-foreground mt-0.5 break-words">{c.content}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
