    "src/hooks/useProfile.ts": "import { useState, useEffect, useCallback } from 'react';
import { getProfile, GetProfileOutputType } from 'zitejs/api';

type ProfileData = GetProfileOutputType;

export function useProfile() {
  const [data, setData] = useState<ProfileData | null>(null);
