    "src/lib/violations.ts": "// MUTARI Violation/Minus Point System

export interface ViolationDef {
  type: string;
  label: string;
  severity: 'paling_berat' | 'berat' | 'sedang' | 'ringan';
  minusPoints: number;
  description: string;
  emoji: string;
}

export const VIOLATION_TYPES: ViolationDef[] = [
  // Paling Berat — "Mementingkan Diri Sendiri"
  { type: 'multi_nego_ghost', label: 'Multi-Negosiasi Ghost', severity: 'paling_berat', minusPoints: -35, description: 'Nego dengan banyak orang untuk 1 barang, pilih yang paling untung, ghost sisanya tanpa kabar.', emoji: '🎣' },
  { type: 'cherry_picker', label: 'Cherry-Picker', severity: 'paling_berat', minusPoints: -30, description: 'Terima tawaran lalu batalkan karena dapat tawaran lebih bagus dari user lain.', emoji: '🍒' },
  { type: 'cod_egois', label: 'COD Egois', severity: 'paling_berat', minusPoints: -28, description: 'Minta lokasi COD yang cuma enak buat dirinya, kalau lawan keberatan langsung cancel.', emoji: '🏠' },
  { type: 'upgrade_hunter', label: 'Upgrade Hunter', severity: 'paling_berat', minusPoints: -27, description: 'Maksa/spam barter barang tidak setara demi keuntungan sendiri.', emoji: '📈' },
  // Berat
  { type: 'fake_listing', label: 'Fake Listing', severity: 'berat', minusPoints: -25, description: 'Upload barang yang tidak dimiliki untuk memancing penawaran.', emoji: '🚫' },
  { type: 'no_show', label: 'Tidak Hadir COD', severity: 'berat', minusPoints: -15, description: 'Tidak datang ke COD tanpa kabar setelah sepakat lokasi & waktu.', emoji: '👻' },
  { type: 'item_mismatch', label: 'Barang Tidak Sesuai', severity: 'berat', minusPoints: -10, description: 'Kondisi barang berbeda jauh dari foto/deskripsi yang di-upload.', emoji: '⚠️' },
  // Sedang
  { type: 'cancel_after_cod_set', label: 'Batal Setelah COD Di-set', severity: 'sedang', minusPoints: -8, description: 'Membatalkan setelah lokasi & waktu COD sudah diatur.', emoji: '📍' },
  { type: 'cancel_after_deal', label: 'Batal Sepihak Setelah Deal', severity: 'sedang', minusPoints: -7, description: 'Membatalkan sepihak setelah kedua pihak sepakat.', emoji: '💔' },
  { type: 'ghosting', label: 'Ghosting Negosiasi', severity: 'sedang', minusPoints: -3, description: 'Menghilang tanpa kabar saat negosiasi aktif.', emoji: '🙈' },
  { type: 'expired_repeated', label: 'Barter Expired Berulang', severity: 'sedang', minusPoints: -2, description: 'Membiarkan negosiasi hangus berkali-kali tanpa respon.', emoji: '⏳' },
  // Ringan
  { type: 'slow_response', label: 'Respons Lambat Berulang', severity: 'ringan', minusPoints: -1, description: 'Pola respon sangat lambat yang menghambat proses barter.', emoji: '🐢' },
  { type: 'incomplete_listing', label: 'Listing Tidak Lengkap', severity: 'ringan', minusPoints: -1, description: 'Upload barang dengan informasi yang sangat minim.', emoji: '📝' },
  { type: 'last_minute_change', label: 'Ubah Syarat di Menit Terakhir', severity: 'ringan', minusPoints: -1, description: 'Mengubah syarat barter saat sudah hampir deal.', emoji: '🔄' },
];

export function getViolationDef(type: string): ViolationDef | undefined {
  return VIOLATION_TYPES.find(v => v.type === type);
}

export function severityColor(severity: string) {
  switch (severity) {
    case 'paling_berat': return { bg: 'bg-red-200', text: 'text-red-900', border: 'border-red-400' };
    case 'berat': return { bg: 'bg-red-100', text: 'text-red-700', border: 'border-red-200' };
    case 'sedang': return { bg: 'bg-orange-100', text: 'text-orange-700', border: 'border-orange-200' };
    case 'ringan': return { bg: 'bg-yellow-100', text: 'text-yellow-700', border: 'border-yellow-200' };
    default: return { bg: 'bg-muted', text: 'text-muted-foreground', border: 'border-border' };
  }
}

export function severityLabel(severity: string) {
  switch (severity) {
    case 'paling_berat': return 'Paling Berat';
    case 'berat': return 'Berat';
    case 'sedang': return 'Sedang';
    case 'ringan': return 'Ringan';
    default: return severity;
  }
}

// Threshold system
export const THRESHOLDS = {
  WARNING: -20,       // Peringatan pertama
  SUSPENSION: -50,    // Suspend sementara
  BAN: -75,           // Ban permanen
};

export function getUserStatus(totalMinusPoints: number) {
  if (totalMinusPoints <= THRESHOLDS.BAN) return { status: 'banned', label: 'Diblokir', color: 'text-red-700 bg-red-100' };
  if (totalMinusPoints <= THRESHOLDS.SUSPENSION) return { status: 'suspended', label: 'Ditangguhkan', color: 'text-orange-700 bg-orange-100' };
  if (totalMinusPoints <= THRESHOLDS.WARNING) return { status: 'warned', label: 'Peringatan', color: 'text-yellow-700 bg-yellow-100' };
  return { status: 'good', label: 'Baik', color: 'text-emerald-700 bg-emerald-100' };
}
