    "src/pages/BarterNegotiationPage.tsx": "import { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, MapPin, CheckCircle2, Loader2, AlertTriangle, Clock, XCircle, Star, Flag } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { getBarterDetail, getBarterMessages, sendBarterMessage, respondBarterOffer, setCodLocation, confirmBarterComplete, cancelBarter, submitBarterReview } from 'zitejs/api';
import type { GetBarterDetailOutputType, GetBarterMessagesOutputType } from 'zitejs/api';
import { useAuth } from 'zitejs/auth';
import { toast } from 'sonner';
import BarterItemCard from '../components/barter/BarterItemCard';
import CodModal from '../components/barter/CodModal';
import ConfirmModal from '../components/barter/ConfirmModal';
import ReviewModal from '../components/barter/ReviewModal';
import CancelModal from '../components/barter/CancelModal';
import ChatInput from '../components/barter/ChatInput';
import ReportModal from '../components/barter/ReportModal';

type BarterType = GetBarterDetailOutputType['barter'];
type MessageType = GetBarterMessagesOutputType['messages'][0];

export default function BarterNegotiationPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [barter, setBarter] = useState<BarterType | null>(null);
  const [messages, setMessages] = useState<MessageType[]>([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [otherTyping, setOtherTyping] = useState(false);
  const [showCod, setShowCod] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const [showCancel, setShowCancel] = useState(false);
  const [showReport, setShowReport] = useState(false);
  const [responding, setResponding] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async () => {
    if (!id) return;
    try {
      const [bd, bm] = await Promise.all([
        getBarterDetail({ barterId: id }),
        getBarterMessages({ barterId: id }),
      ]);
      setBarter(bd.barter);
      setMessages(bm.messages);
    } catch { /* ignore */ }
    setLoading(false);
  }, [id]);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!id) return;
    const iv = setInterval(async () => {
      try {
        const bm = await getBarterMessages({ barterId: id });
        setMessages(bm.messages);
      } catch { /* ignore */ }
    }, 5000);
    return () => clearInterval(iv);
  }, [id]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (content: string, type: 'Text' | 'Photo') => {
    if (!id) return;
    setSending(true);
    try {
      await sendBarterMessage({ barterId: id, content, type });
      await loadData();
    } catch {
      toast.error('Gagal mengirim pesan');
    }
    setSending(false);
  };

  const handleRespond = async (action: 'accept' | 'reject') => {
    if (!id) return;
    setResponding(true);
    try {
      await respondBarterOffer({ barterId: id, action });
      toast.success(action === 'accept' ? 'Penawaran diterima!' : 'Penawaran ditolak');
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal merespons');
    }
    setResponding(false);
  };

  const handleCodSubmit = async (address: string, detail: string) => {
    if (!id) return;
    try {
      await setCodLocation({ barterId: id, address, detail: detail || undefined });
      toast.success('Lokasi COD berhasil diset');
      setShowCod(false);
      await loadData();
    } catch (e: any) {
      toast.error(e?.message || 'Gagal');
    }
  };

  const handleConfirmComplete = async () => {
    if (!id) return;
    try {
      const res = await confirmBarterComplete({ barterId: id });
      if (res.bothConfirmed) {
