    "src/pages/ChatPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, MessageCircle } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { getActiveChats } from 'zitejs/api';
import type { GetActiveChatsOutputType } from 'zitejs/api';
import { formatDistanceToNow } from 'date-fns';
import { id as localeId } from 'date-fns/locale';
import BottomNav from '../components/BottomNav';

type ChatItem = GetActiveChatsOutputType['chats'][0];

export default function ChatPage() {
  const navigate = useNavigate();
  const [chats, setChats] = useState<ChatItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getActiveChats({}).then(res => {
      setChats(res.chats);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  return (
    <div className="min-h-screen bg-background pb-20">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate('/')} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <h1 className="font-bold text-lg">Chat Barter</h1>
          </div>
        </div>

        {loading ? (
          <div className="divide-y divide-border">
            {[0, 1, 2, 3, 4].map(i => (
              <div key={i} className="px-4 py-3 flex items-center gap-3">
                <div className="flex-shrink-0 relative w-12 h-12">
                  <Skeleton className="w-10 h-10 rounded-lg absolute top-0 left-0" />
                  <Skeleton className="w-10 h-10 rounded-lg absolute bottom-0 right-0" />
                </div>
                <div className="flex-1 space-y-2">
                  <div className="flex items-center justify-between">
                    <Skeleton className="h-4 w-24" />
                    <Skeleton className="h-3 w-16" />
                  </div>
                  <Skeleton className="h-3 w-3/4" />
                  <Skeleton className="h-4 w-16 rounded-full" />
                </div>
              </div>
            ))}
          </div>
        ) : chats.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mb-4">
              <MessageCircle className="w-8 h-8 text-muted-foreground" />
            </div>
            <p className="text-muted-foreground text-sm font-medium">Belum ada negosiasi aktif</p>
            <p className="text-muted-foreground text-xs mt-1">Mulai barter dari halaman detail barang</p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {chats.map(chat => (
              <button
                key={chat.barterId}
                onClick={() => navigate(`/barter/${chat.barterId}`)}
                className="w-full flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition active:bg-muted/50 text-left"
              >
                {/* Avatars / item photos */}
                <div className="flex-shrink-0 relative w-12 h-12">
                  <div className="w-10 h-10 rounded-lg overflow-hidden bg-muted absolute top-0 left-0 border-2 border-card">
                    {chat.offeredItemPhoto ? (
                      <img src={chat.offeredItemPhoto} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-primary/10 flex items-center justify-center text-primary text-xs font-bold">B</div>
                    )}
                  </div>
                  <div className="w-10 h-10 rounded-lg overflow-hidden bg-muted absolute bottom-0 right-0 border-2 border-card">
                    {chat.requestedItemPhoto ? (
                      <img src={chat.requestedItemPhoto} className="w-full h-full object-cover" />
                    ) : (
                      <div className="w-full h-full bg-accent flex items-center justify-center text-primary text-xs font-bold">B</div>
                    )}
                  </div>
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between">
                    <p className="font-semibold text-sm truncate">{chat.otherUserName}</p>
                    {chat.lastMessageAt && (
                      <span className="text-[10px] text-muted-foreground flex-shrink-0 ml-2">
                        {formatDistanceToNow(new Date(chat.lastMessageAt), { addSuffix: true, locale: localeId })}
                      </span>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground truncate mt-0.5">
                    {chat.lastMessage || chat.title}
                  </p>
                  <StatusChip status={chat.status} />
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}

function StatusChip({ status }: { status: string }) {
  const colors: Record<string, string> = {
    Menunggu: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
    Diterima: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
  };
  return (
    <span className={`inline-block mt-1 px-1.5 py-0.5 rounded text-[9px] font-semibold ${colors[status] || colors.Menunggu}`}>
      {status}
    </span>
  );
}
