    "src/pages/ItemDetail.tsx": "import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getItem, GetItemOutputType, likeItem } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import ImageGallery from '../components/detail/ImageGallery';
import ProductInfo from '../components/detail/ProductInfo';
import OwnerCard from '../components/detail/OwnerCard';
import ProductDetails from '../components/detail/ProductDetails';
import AIAnalysis from '../components/detail/AIAnalysis';
import CommentSection from '../components/detail/CommentSection';
import DetailBottomBar from '../components/detail/DetailBottomBar';

type ItemType = NonNullable<GetItemOutputType['item']>;

export default function ItemDetail() {
  const { id } = useParams<{ id: string }>();
  const [item, setItem] = useState<ItemType | null>(null);
  const [loading, setLoading] = useState(true);
  const [liked, setLiked] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  useEffect(() => {
    if (!id) return;
    setLoading(true);
    getItem({ id }).then(res => {
      setItem(res.item ?? null);
      setLiked(res.item?.liked ?? false);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [id]);

  const handleLike = async () => {
    if (!id || !item) return;
    const newLiked = !liked;
    setLiked(newLiked);
    setItem(prev => prev ? { ...prev, likesCount: newLiked ? prev.likesCount + 1 : Math.max(0, prev.likesCount - 1) } : null);
    try {
      const res = await likeItem({ id });
      setLiked(res.liked);
      setItem(prev => prev ? { ...prev, likesCount: res.likesCount } : null);
    } catch {
      setLiked(!newLiked);
      setItem(prev => prev ? { ...prev, likesCount: newLiked ? prev.likesCount - 1 : prev.likesCount + 1 } : null);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background pb-24">
        <div className="max-w-[420px] mx-auto">
          <Skeleton className="w-full aspect-square" />
          <div className="p-4 space-y-3">
            <Skeleton className="h-6 w-3/4" />
            <Skeleton className="h-4 w-1/2" />
            <Skeleton className="h-20 w-full" />
          </div>
        </div>
      </div>
    );
  }

  if (!item) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <p className="text-muted-foreground">Barang tidak ditemukan</p>
      </div>
    );
  }

  const priceRange = formatPrice(item.estimatedValueMin, item.estimatedValueMax);
  const images = item.photos.length > 0 ? item.photos.map(p => p.url) : ['https://images.fillout.com/811181/exc3bfzedf/generated-images/chksYvwfs48kEKkvWojfxZ/img_reI--uAdII5h1cTE.jpg'];

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        <ImageGallery
          images={images}
          views={item.viewsCount}
          likes={item.likesCount}
          liked={liked}
          onLike={handleLike}
          createdAt={item.createdAt}
        />
        <ProductInfo
          title={item.title}
          matchPercent={computeMatchPercent(item)}
          priceRange={priceRange}
          distance={item.location || 'Sekitar Anda'}
          views={item.viewsCount}
          likes={item.likesCount}
          createdAt={item.createdAt}
        />
        <OwnerCard
          name={item.ownerName}
          image={item.ownerImage}
          initial={item.ownerName?.[0]?.toUpperCase() || 'P'}
          rating={5}
          barterCount={item.ownerBarterCount}
          memberSince={item.ownerMemberSince}
          points={item.ownerPoints}
          userId={item.ownerId}
        />
        <ProductDetails
          condition={item.condition}
          description={item.description}
          completeness={item.completeness}
          defects={item.defects}
          barterReason={item.barterReason}
          desiredItems={item.desiredItems}
          barterMethods={item.barterMethod}
        />
        <AIAnalysis
          matchPercent={computeMatchPercent(item)}
          condition={item.condition}
          priceRange={priceRange}
          distance={item.location || 'Sekitar Anda'}
          itemId={id || ''}
          title={item.title}
          estimatedValueMin={item.estimatedValueMin}
          estimatedValueMax={item.estimatedValueMax}
          likesCount={item.likesCount}
          viewsCount={item.viewsCount}
        />
        <CommentSection itemId={id || ''} />
        <div className="h-4" />
      </div>
      <DetailBottomBar itemId={id || ''} itemTitle={item.title} ownerName={item.ownerName} />
    </div>
  );
}

function computeMatchPercent(item: ItemType): number {
  let score = 60;
  if (item.photos.length > 0) score += 5;
  if (item.photos.length > 2) score += 5;
  if (item.estimatedValueMin || item.estimatedValueMax) score += 5;
  if (item.description && item.description.length > 50) score += 4;
  if (item.viewsCount > 5) score += 3;
  if (item.likesCount > 2) score += 5;
  if (item.condition === 'Baru' || item.condition === 'Seperti Baru') score += 5;
  if (item.condition === 'Baik') score += 3;
  if (item.location) score += 3;
  if (item.ownerBarterCount > 0) score += 5;
  return Math.min(99, score);
}

function formatPrice(min: number | null, max: number | null): string {
  const fmt = (v: number) => 'Rp' + v.toLocaleString('id-ID');
  if (min && max && min !== max) return `${fmt(min)} – ${fmt(max)}`;
  if (min) return fmt(min);
  if (max) return fmt(max);
  return '-';
}
