    "src/pages/NotificationSettingsPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { useProfile } from '../hooks/useProfile';
import { updateProfile } from 'zitejs/api';
import { Switch } from '@project/components/ui/switch';
import { Skeleton } from '@project/components/ui/skeleton';

interface NotifSetting {
  key: 'emailNotifications' | 'pushNotifications' | 'chatNotifications' | 'barterNotifications';
  label: string;
  description: string;
}

const SETTINGS: NotifSetting[] = [
  { key: 'emailNotifications', label: 'Notifikasi Email', description: 'Terima update via email tentang barter dan promo' },
  { key: 'pushNotifications', label: 'Notifikasi Push', description: 'Terima notifikasi langsung di perangkat kamu' },
  { key: 'chatNotifications', label: 'Notifikasi Chat', description: 'Pemberitahuan pesan baru dari pengguna lain' },
  { key: 'barterNotifications', label: 'Notifikasi Barter', description: 'Update tentang penawaran dan status barter' },
];

export default function NotificationSettingsPage() {
  const navigate = useNavigate();
  const { profile, loading } = useProfile();

  const [values, setValues] = useState<Record<string, boolean>>({
    emailNotifications: true,
    pushNotifications: true,
    chatNotifications: true,
    barterNotifications: true,
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (profile) {
      setValues({
        emailNotifications: profile.emailNotifications,
        pushNotifications: profile.pushNotifications,
        chatNotifications: profile.chatNotifications,
        barterNotifications: profile.barterNotifications,
      });
    }
  }, [profile]);

  const toggle = (key: string) => {
    setValues(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile(values as any);
      toast.success('Pengaturan notifikasi disimpan');
      navigate(-1);
    } catch {
      toast.error('Gagal menyimpan pengaturan');
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-[420px] mx-auto">
          <div className="bg-primary px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white">Pengaturan Notifikasi</h1>
          </div>
          <div className="p-4 space-y-4">
            {[0,1,2,3].map(i => <Skeleton key={i} className="h-16 w-full rounded-xl" />)}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">Pengaturan Notifikasi</h1>
          </div>
        </div>

        <div className="px-4 mt-4">
          <div className="bg-card rounded-2xl border border-border overflow-hidden divide-y divide-border">
            {SETTINGS.map(s => (
              <div key={s.key} className="px-4 py-4 flex items-center gap-3">
                <div className="flex-1">
                  <p className="text-sm font-semibold">{s.label}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">{s.description}</p>
                </div>
                <Switch checked={values[s.key]} onCheckedChange={() => toggle(s.key)} />
              </div>
            ))}
          </div>
        </div>

        <div className="px-4 mt-8">
          <button
            onClick={handleSave}
            disabled={saving}
            className="w-full py-3.5 rounded-2xl bg-primary text-primary-foreground font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            Simpan Pengaturan
          </button>
        </div>
      </div>
    </div>
  );
}
