    "src/pages/PreferredCategoriesPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Loader2, Check, Sparkles } from 'lucide-react';
import { toast } from 'sonner';
import { useProfile } from '../hooks/useProfile';
import { getCategories, GetCategoriesOutputType, updateProfile } from 'zitejs/api';
import { useI18n } from '../context/I18nContext';
import { Skeleton } from '@project/components/ui/skeleton';

type Cat = GetCategoriesOutputType['categories'][0];

export default function PreferredCategoriesPage() {
  const navigate = useNavigate();
  const { profile, loading: profileLoading } = useProfile();
  const { lang } = useI18n();
  const [categories, setCategories] = useState<Cat[]>([]);
  const [selected, setSelected] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    getCategories({}).then(r => {
      setCategories(r.categories);
    }).catch(() => {}).finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    if (profile) {
      const saved = (profile as any).preferredCategories;
      if (saved) {
        try {
          setSelected(JSON.parse(saved));
        } catch {
          setSelected(saved.split(',').map((s: string) => s.trim()).filter(Boolean));
        }
      }
    }
  }, [profile]);

  const toggle = (name: string) => {
    setSelected(prev => prev.includes(name) ? prev.filter(s => s !== name) : [...prev, name]);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile({ preferredCategories: JSON.stringify(selected) });
      toast.success(lang === 'id' ? 'Preferensi kategori disimpan!' : 'Category preferences saved!');
      navigate(-1);
    } catch {
      toast.error(lang === 'id' ? 'Gagal menyimpan' : 'Failed to save');
    }
    setSaving(false);
  };

  const isLoading = loading || profileLoading;

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">{lang === 'id' ? 'Preferensi Kategori' : 'Category Preferences'}</h1>
          </div>
        </div>

        {/* Info */}
        <div className="px-4 mt-4">
