    "src/pages/ReferralPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Copy, Share2, Gift, Users, Coins, CheckCircle2, Clock, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { getReferral, GetReferralOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { useI18n } from '../context/I18nContext';

type Referral = GetReferralOutputType['referrals'][0];

function StatCard({ icon: Icon, label, value, color }: { icon: typeof Gift; label: string; value: string; color: string }) {
  return (
    <div className="bg-card border border-border rounded-xl p-3 text-center">
