}

function ReferralItem({ r }: { r: Referral }) {
  const initials = (r.referredName?.[0] || 'U').toUpperCase();
  const isCompleted = r.status === 'completed';
  return (
    <div className="flex items-center gap-3 py-3">
      {r.referredImage ? (
