    "src/pages/SmartMatch.tsx": "import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Sparkles, MapPin, CheckCircle, Star, TrendingUp, ShieldCheck, Clock, ChevronRight } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { getSmartMatch, GetSmartMatchOutputType } from 'zitejs/api';

type MatchType = GetSmartMatchOutputType['matches'][0];
type ItemInfo = NonNullable<GetSmartMatchOutputType['item']>;

const LOADING_STEPS = [
  'Menganalisis kategori barang...',
  'Menganalisis kondisi barang...',
  'Mengestimasi nilai pasar...',
  'Menganalisis lokasi terdekat...',
  'Memeriksa riwayat transaksi...',
  'Mencari pasangan barter terbaik...',
  'Membandingkan lokasi...',
  'Menyusun rekomendasi...',
];

export default function SmartMatch() {
  const navigate = useNavigate();
  const { id } = useParams<{ id: string }>();
  const [loading, setLoading] = useState(true);
  const [step, setStep] = useState(0);
  const [item, setItem] = useState<ItemInfo | null>(null);
  const [matches, setMatches] = useState<MatchType[]>([]);
  const [dataReady, setDataReady] = useState(false);

  // Fetch real data
  useEffect(() => {
    if (!id) return;
    getSmartMatch({ itemId: id }).then(res => {
      setItem(res.item);
      setMatches(res.matches);
      setDataReady(true);
    }).catch(() => setDataReady(true));
  }, [id]);

  // Loading animation
  useEffect(() => {
    const interval = setInterval(() => {
      setStep((s) => {
        if (s >= LOADING_STEPS.length - 1) {
          clearInterval(interval);
          return s;
        }
        return s + 1;
      });
    }, 500);
    return () => clearInterval(interval);
  }, []);

  // Stop loading when both animation done and data ready
  useEffect(() => {
    if (step >= LOADING_STEPS.length - 1 && dataReady) {
      const t = setTimeout(() => setLoading(false), 600);
      return () => clearTimeout(t);
    }
  }, [step, dataReady]);

  const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

  return (
    <div className="min-h-screen bg-background">
      <div className="max-w-[420px] mx-auto">
        {/* Header — green */}
        <div className="bg-primary px-4 pt-4 pb-6 rounded-b-3xl">
          <div className="flex items-center gap-3 mb-4">
            <button onClick={() => navigate(-1)} className="w-9 h-9 rounded-full bg-white/20 flex items-center justify-center">
              <ArrowLeft className="w-4 h-4 text-primary-foreground" />
            </button>
            <div className="flex-1">
              <h1 className="text-primary-foreground font-bold text-base">AI Smart Match</h1>
              <p className="text-primary-foreground/70 text-[10px]">Micro AI · Analisis satu barang</p>
            </div>
            <div className="w-9 h-9 rounded-full bg-white/20 flex items-center justify-center">
              <Sparkles className="w-4 h-4 text-primary-foreground" />
            </div>
          </div>

          {/* Your item */}
          <div className="bg-white/10 backdrop-blur-sm rounded-xl p-3 flex gap-3">
            <img src={item?.img || PLACEHOLDER_IMG} alt={item?.title || 'Barang'} className="w-16 h-16 rounded-lg object-cover" />
            <div>
              <p className="text-primary-foreground font-bold text-sm">{item?.title || 'Memuat...'}</p>
              <p className="text-primary-foreground/70 text-xs">{item?.priceRange || '-'}</p>
              <p className="text-primary-foreground/60 text-[10px] mt-0.5">Barang Anda</p>
            </div>
          </div>
        </div>

        <AnimatePresence mode="wait">
          {loading ? (
            <motion.div
              key="loading"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="px-4 py-12 flex flex-col items-center"
            >
              {/* Robot animation */}
              <div className="w-20 h-20 rounded-full bg-accent flex items-center justify-center mb-6">
                <motion.div animate={{ rotate: [0, 10, -10, 0] }} transition={{ repeat: Infinity, duration: 2 }}>
                  <Sparkles className="w-10 h-10 text-primary" />
                </motion.div>
              </div>

              {/* Progress steps */}
              <div className="w-full space-y-2">
                {LOADING_STEPS.map((text, i) => (
                  <motion.div
                    key={i}
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: i <= step ? 1 : 0.3, x: 0 }}
                    transition={{ delay: i * 0.1 }}
                    className="flex items-center gap-2"
                  >
                    {i < step ? (
                      <CheckCircle className="w-4 h-4 text-primary flex-shrink-0" />
                    ) : i === step ? (
                      <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}>
                        <Sparkles className="w-4 h-4 text-primary flex-shrink-0" />
                      </motion.div>
                    ) : (
                      <div className="w-4 h-4 rounded-full border border-border flex-shrink-0" />
                    )}
                    <span className={`text-xs ${i <= step ? 'text-foreground' : 'text-muted-foreground'}`}>{text}</span>
                  </motion.div>
                ))}
              </div>

              {/* Progress bar */}
              <div className="w-full h-1.5 bg-muted rounded-full mt-6 overflow-hidden">
                <motion.div
                  className="h-full bg-primary rounded-full"
                  animate={{ width: `${((step + 1) / LOADING_STEPS.length) * 100}%` }}
                  transition={{ duration: 0.3 }}
                />
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="results"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="px-4 py-4"
            >
              {matches.length === 0 ? (
                <div className="text-center py-12">
                  <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
                    <Sparkles className="w-8 h-8 text-muted-foreground" />
                  </div>
                  <p className="font-bold text-base mb-1">Belum Ada Pasangan</p>
                  <p className="text-sm text-muted-foreground">AI belum menemukan pasangan barter yang cocok untuk barang ini. Coba lagi nanti!</p>
                </div>
              ) : (
                <>
                  <div className="flex items-center justify-between mb-3">
                    <p className="font-bold text-base">Pasangan Barter Terbaik</p>
                    <span className="text-xs text-muted-foreground">{matches.length} ditemukan</span>
                  </div>

                  <div className="space-y-3">
                    {matches.map((match, i) => (
                      <MatchCard key={match.id} rank={i + 1} item={item!} match={match} />
                    ))}
                  </div>

                  <p className="text-center text-[10px] text-muted-foreground mt-6 italic">
                    "Biarkan AI bekerja. Anda tinggal memilih peluang terbaik."
                  </p>
                </>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

