    "src/pages/WalletPage.tsx": "import { ArrowLeft, Wallet, TrendingUp, ArrowUpRight, ArrowDownLeft, Gift, Package, Heart, UserCheck, Sparkles, ChevronRight, Info, Shield, Crown, Trophy, X, AlertTriangle, Ban, ChevronDown, Plus, Minus, BookOpen } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { useAuth } from 'zitejs/auth';
import { useUserPoints } from '../hooks/useUserPoints';
import { getBadge, getNextBadge, getProgressToNext, BADGES } from '../lib/badges';
import { getNotifications, GetNotificationsOutputType, markNotificationRead, getViolations, GetViolationsOutputType } from 'zitejs/api';
import { VIOLATION_TYPES, getUserStatus, severityColor, severityLabel } from '../lib/violations';
import BadgeChip from '../components/BadgeChip';
import { Skeleton } from '@project/components/ui/skeleton';
import { motion, AnimatePresence } from 'framer-motion';

function activityIcon(type: string) {
  switch (type) {
    case 'upload': return <Package className="w-4 h-4" />;
    case 'like_received': return <Heart className="w-4 h-4" />;
    case 'barter': return <TrendingUp className="w-4 h-4" />;
    case 'join': return <Gift className="w-4 h-4" />;
    case 'verify': return <UserCheck className="w-4 h-4" />;
    case 'violation': return <AlertTriangle className="w-4 h-4" />;
    default: return <Sparkles className="w-4 h-4" />;
  }
}

function activityColor(type: string) {
  switch (type) {
    case 'upload': return 'bg-sky-100 text-sky-600';
    case 'like_received': return 'bg-pink-100 text-pink-600';
    case 'barter': return 'bg-emerald-100 text-emerald-600';
    case 'join': return 'bg-violet-100 text-violet-600';
    case 'verify': return 'bg-amber-100 text-amber-600';
    case 'violation': return 'bg-red-100 text-red-600';
    default: return 'bg-primary/10 text-primary';
  }
}

function formatDate(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
}

function formatTime(iso: string) {
  if (!iso) return '';
  const d = new Date(iso);
  return d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
}

const EARN_OPTIONS = [
  { icon: Package, label: 'Upload Barang', desc: 'Dapatkan +20 MP', points: '+20 MP', path: '/upload' },
  { icon: TrendingUp, label: 'Selesaikan Barter', desc: 'Dapatkan +50 MP', points: '+50 MP', path: '/search' },
  { icon: UserCheck, label: 'Verifikasi Profil', desc: 'Dapatkan +30 MP', points: '+30 MP', path: '/security' },
];

