import { useEffect, useState } from 'react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

type ItemType = GetItemsOutputType['items'][0];

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function MatchBadge({ percent }: { percent: number }) {
  return (
    <div className="bg-card/90 backdrop-blur-sm rounded-full px-2.5 py-1 flex items-center gap-1 text-[11px] font-bold shadow-sm">
      <Sparkles className="w-3.5 h-3.5 text-primary" /> {percent}%
    </div>
  );
}

function estimateMatch(item: ItemType): number {
  // Simple heuristic based on item data completeness + views
  let score = 70;
  if (item.photos && item.photos.length > 0) score += 5;
  if (item.photos && item.photos.length > 2) score += 5;
  if (item.location) score += 3;
  if (item.description && item.description.length > 50) score += 4;
  if (item.viewsCount > 5) score += 3;
  if (item.likesCount > 2) score += 5;
  if (item.condition === 'Baru' || item.condition === 'Seperti Baru') score += 5;
  return Math.min(99, score);
}

function SmallCard({ item, onClick }: { item: ItemType; onClick: () => void }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  return (
    <div onClick={onClick} className="min-w-[150px] max-w-[150px] rounded-2xl overflow-hidden border border-border bg-card cursor-pointer shadow-sm hover:shadow-md transition-shadow">
      <div className="relative">
        <img src={imgUrl} alt={item.title} className="w-full h-[110px] object-cover" />
