    "src/components/achievements/AchievementTimeline.tsx": "import { format } from 'date-fns';
import { id } from 'date-fns/locale';

interface HistoryItem {
  label: string;
  points: number;
  date: string;
}

export default function AchievementTimeline({ history }: { history: HistoryItem[] }) {
  const sorted = [...history].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

