    "src/components/barter/CancelModal.tsx": "import { useState } from 'react';
import { X, AlertTriangle, Loader2 } from 'lucide-react';

const CANCEL_REASONS = [
  'Berubah pikiran',
  'Menemukan penawaran lebih baik',
  'Barang sudah tidak tersedia',
  'Tidak bisa COD di lokasi yang ditentukan',
  'Komunikasi tidak responsif',
];

interface Props {
  isAfterAccepted: boolean;
  onClose: () => void;
  onSubmit: (reason: string) => Promise<void>;
}

export default function CancelModal({ isAfterAccepted, onClose, onSubmit }: Props) {
  const [reason, setReason] = useState('');
  const [customReason, setCustomReason] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const finalReason = reason === 'custom' ? customReason.trim() : reason;

  const handleSubmit = async () => {
    if (!finalReason) return;
    setSubmitting(true);
    await onSubmit(finalReason);
    setSubmitting(false);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center px-6">
      <div className="max-w-[360px] w-full bg-card rounded-2xl p-5 animate-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-bold text-base text-destructive">Batalkan Barter</h3>
          <button onClick={onClose} className="p-1 rounded-lg hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        {isAfterAccepted && (
          <div className="flex items-start gap-3 bg-red-50 dark:bg-red-950/20 p-3 rounded-xl border border-red-200 dark:border-red-800 mb-4">
            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-xs text-red-700 dark:text-red-400 font-medium">Peringatan Penalti!</p>
              <p className="text-[11px] text-red-600 dark:text-red-500 mt-1">
                Membatalkan barter setelah diterima akan mengurangi <strong>-5 poin</strong> dari reputasi Anda. Ini tercatat di riwayat Anda.
              </p>
            </div>
          </div>
        )}

        <p className="text-xs text-muted-foreground mb-3">Pilih alasan pembatalan:</p>

        <div className="space-y-2 mb-3">
          {CANCEL_REASONS.map(r => (
            <button
              key={r}
              onClick={() => { setReason(r); setCustomReason(''); }}
              className={`w-full text-left px-3 py-2 rounded-xl border text-xs font-medium transition-all active:scale-[0.98] ${
                reason === r
                  ? 'border-destructive bg-destructive/5 text-destructive'
                  : 'border-border hover:bg-muted/30'
              }`}
            >
              {r}
            </button>
          ))}
          <button
            onClick={() => setReason('custom')}
            className={`w-full text-left px-3 py-2 rounded-xl border text-xs font-medium transition-all ${
              reason === 'custom'
                ? 'border-destructive bg-destructive/5 text-destructive'
                : 'border-border hover:bg-muted/30'
            }`}
          >
            Alasan lain...
          </button>
        </div>

        {reason === 'custom' && (
          <textarea
            value={customReason}
            onChange={e => setCustomReason(e.target.value)}
            placeholder="Tuliskan alasan..."
            maxLength={200}
            className="w-full rounded-xl border border-border bg-background px-3 py-2 text-sm resize-none h-16 focus:outline-none focus:ring-1 focus:ring-destructive mb-3"
          />
        )}

        <div className="flex gap-2">
          <button
            onClick={onClose}
            className="flex-1 py-2.5 rounded-xl border border-border text-foreground text-sm font-medium active:scale-[0.98] transition"
          >
            Kembali
          </button>
          <button
            onClick={handleSubmit}
            disabled={!finalReason || submitting}
            className="flex-1 py-2.5 rounded-xl bg-destructive text-destructive-foreground text-sm font-semibold disabled:opacity-50 flex items-center justify-center gap-1.5 active:scale-[0.98] transition"
          >
            {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
            {submitting ? 'Membatalkan...' : 'Batalkan'}
          </button>
        </div>
      </div>
    </div>
  );
}
