    "src/components/barter/ChatInput.tsx": "import { useState, useRef } from 'react';
import { Send, Plus, X, Camera, ImageIcon, Loader2 } from 'lucide-react';
import { useUpload } from 'zitejs/upload';

const QUICK_REPLIES = [
  'Apakah barang masih tersedia?',
  'Bisa tukar tambah?',
  'Kondisi barangnya bagaimana?',
  'Bisa COD di mana?',
  'Kapan bisa ketemuan?',
  'Saya tertarik, yuk deal!',
];

interface ChatInputProps {
  onSend: (content: string, type: 'Text' | 'Photo') => Promise<void>;
  sending: boolean;
  isTyping: boolean;
  onTypingChange: (typing: boolean) => void;
}

export default function ChatInput({ onSend, sending, isTyping, onTypingChange }: ChatInputProps) {
  const [text, setText] = useState('');
  const [showAttach, setShowAttach] = useState(false);
  const [showQuick, setShowQuick] = useState(true);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const cameraRef = useRef<HTMLInputElement>(null);
  const typingTimer = useRef<ReturnType<typeof setTimeout>>();
  const { upload } = useUpload();

  const handleTextChange = (val: string) => {
    setText(val);
    onTypingChange(true);
    clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(() => onTypingChange(false), 2000);
  };

  const handleSendText = async () => {
    if (!text.trim()) return;
    const content = text.trim();
    setText('');
    onTypingChange(false);
    setShowQuick(false);
    await onSend(content, 'Text');
  };

  const handleQuickReply = async (msg: string) => {
    setShowQuick(false);
    await onSend(msg, 'Text');
  };

  const handleFileSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setShowAttach(false);
    setUploading(true);
    try {
      const { url } = await upload(file);
      setPreviewUrl(url);
    } catch {
      // silently fail
    }
    setUploading(false);
    e.target.value = '';
  };

  const handleSendPhoto = async () => {
    if (!previewUrl) return;
    const url = previewUrl;
    setPreviewUrl(null);
    await onSend(url, 'Photo');
  };

  return (
    <div>
      {/* Typing indicator */}
      {isTyping && (
        <div className="px-4 py-1.5">
          <div className="flex items-center gap-1.5">
            <div className="flex gap-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:0ms]" />
              <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:150ms]" />
              <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:300ms]" />
            </div>
            <span className="text-[11px] text-muted-foreground italic">Sedang mengetik...</span>
          </div>
        </div>
      )}

      {/* Quick reply suggestions */}
      {showQuick && (
        <div className="px-4 py-2 flex gap-1.5 overflow-x-auto no-scrollbar">
          {QUICK_REPLIES.map(q => (
            <button
              key={q}
              onClick={() => handleQuickReply(q)}
              disabled={sending}
              className="flex-shrink-0 px-3 py-1.5 rounded-full bg-accent border border-primary/15 text-primary text-xs font-medium active:scale-95 transition disabled:opacity-50 whitespace-nowrap"
            >
              {q}
            </button>
          ))}
        </div>
      )}

      {/* Photo preview */}
      {previewUrl && (
        <div className="px-4 py-2">
          <div className="relative inline-block">
            <img src={previewUrl} alt="Preview" className="w-28 h-28 rounded-xl object-cover border border-border" />
            <button onClick={() => setPreviewUrl(null)} className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-destructive text-white flex items-center justify-center">
              <X className="w-3 h-3" />
            </button>
            <button
              onClick={handleSendPhoto}
              disabled={sending}
              className="absolute bottom-1.5 right-1.5 p-1.5 rounded-full bg-primary text-primary-foreground active:scale-90 transition"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}

      {/* Attachment overlay */}
      {showAttach && (
        <div className="px-4 py-2 flex gap-2">
          <button
            onClick={() => { cameraRef.current?.click(); }}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-accent border border-primary/15 text-sm font-medium active:scale-95 transition"
          >
            <Camera className="w-4 h-4 text-primary" /> Kamera
          </button>
          <button
            onClick={() => { fileRef.current?.click(); }}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-accent border border-primary/15 text-sm font-medium active:scale-95 transition"
          >
            <ImageIcon className="w-4 h-4 text-primary" /> Galeri
          </button>
        </div>
      )}

      {/* Text input row */}
      <div className="flex items-center gap-2 px-4 py-2.5">
        <button
          onClick={() => setShowAttach(prev => !prev)}
          className={`p-2 rounded-full transition active:scale-90 ${showAttach ? 'bg-primary text-primary-foreground' : 'bg-muted text-foreground'}`}
        >
          {uploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
        </button>
        <input
          type="text"
          value={text}
          onChange={e => handleTextChange(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleSendText()}
          placeholder="Tulis pesan..."
          className="flex-1 bg-muted rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
        />
        <button
          onClick={handleSendText}
          disabled={!text.trim() || sending}
          className="p-2 rounded-full bg-primary text-primary-foreground disabled:opacity-40 active:scale-90 transition"
        >
          <Send className="w-4 h-4" />
        </button>
      </div>

      {/* Hidden file inputs */}
      <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleFileSelected} />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFileSelected} />
    </div>
  );
}
",
    "src/components/barter/CodModal.tsx": "import { useState } from 'react';
import { X, MapPin, Loader2 } from 'lucide-react';

interface Props {
  currentAddress: string;
  currentDetail: string;
  onClose: () => void;
  onSubmit: (address: string, detail: string) => Promise<void>;
}

export default function CodModal({ currentAddress, currentDetail, onClose, onSubmit }: Props) {
