    "src/components/detail/DetailBottomBar.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Bookmark, BookmarkCheck, MessageCircle, Sparkles, Repeat, Loader2 } from 'lucide-react';
import { toggleWishlist, getWishlist } from 'zitejs/api';
import { useAuth, loginWithRedirect } from 'zitejs/auth';
import { toast } from 'sonner';

interface Props {
  itemId: string;
  itemTitle?: string;
  ownerName?: string;
}

export default function DetailBottomBar({ itemId, itemTitle, ownerName }: Props) {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [checkedInitial, setCheckedInitial] = useState(false);

  // Check if item is already in wishlist on mount
  useEffect(() => {
    if (!user) return;
    getWishlist({}).then(res => {
      const isSaved = res.items.some(i => i.itemId === itemId);
      setSaved(isSaved);
      setCheckedInitial(true);
    }).catch(() => setCheckedInitial(true));
  }, [user, itemId]);

  const requireAuth = (action: () => void) => {
    if (!user) {
      loginWithRedirect();
      return;
    }
    action();
  };

  const handleSave = async () => {
    requireAuth(async () => {
      setSaving(true);
      try {
        const res = await toggleWishlist({ itemId });
        setSaved(res.saved);
        toast.success(res.saved ? 'Tersimpan di wishlist' : 'Dihapus dari wishlist');
      } catch {
        toast.error('Gagal menyimpan');
      }
      setSaving(false);
    });
  };

  const handleChat = () => {
    requireAuth(() => {
      navigate('/chat', { state: { fromItem: itemId, itemTitle, ownerName } });
    });
  };

  const handleBarter = () => {
    requireAuth(() => {
      navigate(`/barter-offer?targetItemId=${itemId}&targetTitle=${encodeURIComponent(itemTitle || 'Barang')}`);
    });
  };

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-card/95 backdrop-blur-md border-t border-border z-50">
      <div className="max-w-[420px] mx-auto px-3 py-2.5 flex gap-2">
        {/* Save */}
        <button
          onClick={handleSave}
          disabled={saving}
          className={`flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl border transition-all active:scale-95 ${
            saved ? 'bg-primary/10 border-primary/30' : 'border-border bg-card hover:bg-muted/50'
          }`}
        >
          {saving ? (
            <Loader2 className="w-5 h-5 text-primary animate-spin" />
          ) : saved ? (
            <BookmarkCheck className="w-5 h-5 text-primary" />
          ) : (
            <Bookmark className="w-5 h-5 text-foreground" />
          )}
          <span className={`text-[10px] ${saved ? 'text-primary font-semibold' : 'text-foreground'}`}>
            {saved ? 'Tersimpan' : 'Simpan'}
          </span>
        </button>

        {/* Chat */}
        <button
          onClick={handleChat}
          className="flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl border border-border bg-card hover:bg-muted/50 transition-all active:scale-95"
        >
          <MessageCircle className="w-5 h-5 text-foreground" />
          <span className="text-[10px] text-foreground">Chat</span>
        </button>

        {/* AI */}
        <button
          onClick={() => requireAuth(() => navigate(`/smart-match/${itemId}`))}
          className="flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl bg-accent border border-primary/20 hover:bg-accent/80 transition-all active:scale-95"
        >
          <Sparkles className="w-5 h-5 text-primary" />
          <span className="text-[10px] text-primary font-semibold">AI</span>
        </button>

        {/* Barter */}
        <button
          onClick={handleBarter}
          className="flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl bg-primary hover:bg-primary/90 transition-all active:scale-95"
        >
          <Repeat className="w-5 h-5 text-primary-foreground" />
          <span className="text-[10px] text-primary-foreground font-semibold">Barter</span>
        </button>
      </div>
    </div>
  );
}
