    "src/components/upload/LocationAuto.tsx": "import { useEffect, useCallback } from 'react';
import { MapPin, Loader2, RefreshCw } from 'lucide-react';

interface Props {
  value: string;
  onChange: (v: string) => void;
  loading: boolean;
  onLoadingChange: (v: boolean) => void;
}

export default function LocationAuto({ value, onChange, loading, onLoadingChange }: Props) {
  const detect = useCallback(async () => {
    if (!navigator.geolocation) {
      onChange('Lokasi tidak tersedia');
      return;
    }
    onLoadingChange(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&accept-language=id`
          );
          const data = await res.json();
          const addr = data.address || {};
          const parts = [
            addr.suburb || addr.village || addr.town || addr.city_district,
            addr.city || addr.county,
            addr.state,
          ].filter(Boolean);
          onChange(parts.join(', '));
        } catch {
          onChange(`${latitude.toFixed(4)}, ${longitude.toFixed(4)}`);
        }
        onLoadingChange(false);
      },
      () => {
        onChange('Gagal mendeteksi lokasi');
        onLoadingChange(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, [onChange, onLoadingChange]);

  useEffect(() => {
    detect();
  }, [detect]);

  return (
    <div>
      <p className="text-sm font-semibold text-foreground mb-2">Lokasi</p>
      <div className="form-input flex items-center gap-3 bg-muted/50">
        {loading ? (
          <Loader2 className="w-4 h-4 text-primary animate-spin flex-shrink-0" />
        ) : (
          <MapPin className="w-4 h-4 text-primary flex-shrink-0" />
        )}
        <span className={`flex-1 text-sm ${value ? 'text-foreground' : 'text-muted-foreground'}`}>
          {loading ? 'Mendeteksi lokasi...' : value || 'Menunggu GPS...'}
        </span>
        {!loading && (
          <button type="button" onClick={detect} className="text-primary">
            <RefreshCw className="w-4 h-4" />
          </button>
        )}
      </div>
      <p className="text-[11px] text-muted-foreground mt-1">Otomatis terdeteksi dari GPS perangkatmu</p>
    </div>
  );
}
