    "src/context/LocationContext.tsx": "import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';

interface LocationData {
  kecamatan: string;
  kabupaten: string;
  lat: number;
  lng: number;
}

interface LocationContextType {
  location: LocationData | null;
  loading: boolean;
  error: string | null;
  radius: number;
  setRadius: (r: number) => void;
  detectLocation: () => void;
  granted: boolean;
}

const LocationContext = createContext<LocationContextType | null>(null);

export function useLocation() {
  const ctx = useContext(LocationContext);
  if (!ctx) throw new Error('useLocation must be inside LocationProvider');
  return ctx;
}

export function LocationProvider({ children }: { children: ReactNode }) {
  const [location, setLocation] = useState<LocationData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [radius, setRadius] = useState(10);
  const [granted, setGranted] = useState(false);

  const detectLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setError('GPS tidak didukung di perangkat ini');
      return;
    }
    setLoading(true);
    setError(null);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&accept-language=id`
          );
          const data = await res.json();
          const addr = data.address || {};
          setLocation({
            kecamatan: addr.suburb || addr.village || addr.town || addr.city_district || '',
            kabupaten: addr.city || addr.county || addr.state || '',
            lat: latitude,
            lng: longitude,
          });
          setGranted(true);
        } catch {
          setLocation({
            kecamatan: '',
            kabupaten: `${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,
            lat: latitude,
            lng: longitude,
          });
          setGranted(true);
        }
        setLoading(false);
      },
      () => {
        setError('Izin lokasi ditolak. Aktifkan GPS di pengaturan perangkat kamu.');
        setGranted(false);
        setLoading(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  // Try on mount
  useEffect(() => {
    detectLocation();
  }, [detectLocation]);

  return (
    <LocationContext.Provider value={{ location, loading, error, radius, setRadius, detectLocation, granted }}>
      {children}
    </LocationContext.Provider>
  );
}
