    "src/lib/badges.ts": "// MUTARI Badge System
export interface MutariBadge {
  id: string;
  emoji: string;
  name: string;
  minPoints: number;
  maxPoints: number | null;
  description: string;
  color: string;
  textColor: string;
  borderColor: string;
