    name: 'Mitra Terpercaya',
    minPoints: 500,
    maxPoints: 999,
    description: 'Anggota terpercaya dengan rating positif dan riwayat barter yang sukses.',
    color: 'bg-amber-100',
    textColor: 'text-amber-700',
    borderColor: 'border-amber-300',
    glowColor: 'shadow-amber-200',
  },
  {
    id: 'profesional',
    emoji: '🛡️',
    name: 'Barter Profesional',
    minPoints: 1000,
    maxPoints: 2499,
    description: 'Anggota yang sangat andal dengan reputasi luar biasa dan transaksi bertanggung jawab.',
    color: 'bg-purple-100',
    textColor: 'text-purple-700',
    borderColor: 'border-purple-300',
    glowColor: 'shadow-purple-200',
  },
  {
    id: 'legenda',
    emoji: '👑',
    name: 'Legenda MUTARI',
    minPoints: 2500,
    maxPoints: null,
    description: 'Anggota elit dengan reputasi luar biasa, aktivitas tinggi, dan kepercayaan istimewa dari komunitas.',
    color: 'bg-gradient-to-r from-amber-100 to-yellow-50',
    textColor: 'text-amber-800',
    borderColor: 'border-amber-400',
    glowColor: 'shadow-amber-300',
  },
];

export function getBadge(points: number): MutariBadge {
  for (let i = BADGES.length - 1; i >= 0; i--) {
    if (points >= BADGES[i].minPoints) return BADGES[i];
  }
  return BADGES[0];
}

export function getNextBadge(points: number): MutariBadge | null {
  const current = getBadge(points);
  const idx = BADGES.indexOf(current);
  return idx < BADGES.length - 1 ? BADGES[idx + 1] : null;
}

export function getProgressToNext(points: number): { percent: number; remaining: number } {
  const current = getBadge(points);
  const next = getNextBadge(points);
  if (!next) return { percent: 100, remaining: 0 };
  const rangeStart = current.minPoints;
  const rangeEnd = next.minPoints;
  const progress = points - rangeStart;
  const total = rangeEnd - rangeStart;
  return {
    percent: Math.min(100, Math.round((progress / total) * 100)),
    remaining: rangeEnd - points,
  };
}

