    "src/pages/AddressPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Loader2, MapPin, CheckCircle } from 'lucide-react';
import { toast } from 'sonner';
import { useProfile } from '../hooks/useProfile';
import { updateProfile } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

const PROVINCES = [
  'Aceh', 'Sumatera Utara', 'Sumatera Barat', 'Riau', 'Jambi', 'Sumatera Selatan',
  'Bengkulu', 'Lampung', 'Kep. Bangka Belitung', 'Kep. Riau', 'DKI Jakarta',
  'Jawa Barat', 'Jawa Tengah', 'DI Yogyakarta', 'Jawa Timur', 'Banten',
  'Bali', 'Nusa Tenggara Barat', 'Nusa Tenggara Timur', 'Kalimantan Barat',
  'Kalimantan Tengah', 'Kalimantan Selatan', 'Kalimantan Timur', 'Kalimantan Utara',
  'Sulawesi Utara', 'Sulawesi Tengah', 'Sulawesi Selatan', 'Sulawesi Tenggara',
  'Gorontalo', 'Sulawesi Barat', 'Maluku', 'Maluku Utara', 'Papua', 'Papua Barat',
  'Papua Selatan', 'Papua Tengah', 'Papua Pegunungan', 'Papua Barat Daya',
];

export default function AddressPage() {
  const navigate = useNavigate();
  const { profile, loading } = useProfile();

  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [province, setProvince] = useState('');
  const [postalCode, setPostalCode] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (profile) {
      setAddress(profile.address);
      setCity(profile.city);
      setProvince(profile.province);
      setPostalCode(profile.postalCode);
    }
  }, [profile]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile({ address, city, province, postalCode });
      toast.success('Alamat berhasil disimpan');
      navigate(-1);
    } catch {
      toast.error('Gagal menyimpan alamat');
    }
    setSaving(false);
  };

  const isComplete = address && city && province && postalCode;

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-[420px] mx-auto">
          <div className="bg-primary px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white">Alamat Saya</h1>
          </div>
          <div className="p-4 space-y-4">
            {[0,1,2,3].map(i => <Skeleton key={i} className="h-12 w-full rounded-xl" />)}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">Alamat Saya</h1>
          </div>
        </div>

        {/* Status */}
        <div className={`mx-4 mt-4 rounded-xl p-3 flex items-center gap-2.5 ${isComplete ? 'bg-emerald-50 border border-emerald-200' : 'bg-amber-50 border border-amber-200'}`}>
          {isComplete ? (
            <>
              <CheckCircle className="w-5 h-5 text-emerald-600 flex-shrink-0" />
              <p className="text-xs text-emerald-700 font-medium">Alamat sudah lengkap</p>
            </>
          ) : (
            <>
              <MapPin className="w-5 h-5 text-amber-600 flex-shrink-0" />
              <p className="text-xs text-amber-700 font-medium">Lengkapi alamat untuk pengalaman barter lebih baik</p>
            </>
          )}
        </div>

        <div className="px-4 mt-5 space-y-4">
          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Alamat Lengkap</label>
            <textarea
              className="form-input min-h-[80px] resize-none"
              value={address}
              onChange={e => setAddress(e.target.value)}
              placeholder="Nama jalan, nomor rumah, RT/RW, kelurahan, kecamatan"
            />
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Kota / Kabupaten</label>
            <input className="form-input" value={city} onChange={e => setCity(e.target.value)} placeholder="Contoh: Jakarta Selatan" />
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Provinsi</label>
            <select
              className="form-input appearance-none"
              value={province}
              onChange={e => setProvince(e.target.value)}
            >
              <option value="">Pilih provinsi</option>
              {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Kode Pos</label>
            <input className="form-input" value={postalCode} onChange={e => setPostalCode(e.target.value)} placeholder="Contoh: 12345" maxLength={5} inputMode="numeric" />
          </div>
        </div>

        <div className="px-4 mt-8">
          <button
            onClick={handleSave}
            disabled={saving}
            className="w-full py-3.5 rounded-2xl bg-primary text-primary-foreground font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            Simpan Alamat
          </button>
        </div>
      </div>
    </div>
  );
}
",
    "src/pages/BarterHistoryPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, ArrowRightLeft, Clock, CheckCircle, XCircle, Loader2 } from 'lucide-react';
import { getBarterHistory, GetBarterHistoryOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import BottomNav from '../components/BottomNav';

type HistoryItem = GetBarterHistoryOutputType['history'][0];

const STATUS_MAP: Record<string, { label: string; color: string; icon: typeof CheckCircle }> = {
  pending: { label: 'Menunggu', color: 'bg-amber-100 text-amber-700', icon: Clock },
  accepted: { label: 'Diterima', color: 'bg-blue-100 text-blue-700', icon: ArrowRightLeft },
  completed: { label: 'Selesai', color: 'bg-emerald-100 text-emerald-700', icon: CheckCircle },
  cancelled: { label: 'Dibatalkan', color: 'bg-red-100 text-red-600', icon: XCircle },
};

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/aYmFPbU63ZSYCP5WK76Yni/img_5j_3U1FxA70D24aF.jpg';

function BarterCard({ item, onClick }: { item: HistoryItem; onClick: () => void }) {
  const status = STATUS_MAP[item.status] || STATUS_MAP.pending;
  const StatusIcon = status.icon;

  return (
    <div onClick={onClick} className="bg-card rounded-2xl border border-border p-4 cursor-pointer hover:shadow-md transition-shadow">
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full flex items-center gap-1 ${status.color}`}>
            <StatusIcon className="w-3 h-3" /> {status.label}
          </span>
          {item.isInitiator && (
            <span className="text-[9px] font-medium text-muted-foreground bg-muted px-1.5 py-0.5 rounded-full">
              Kamu yang memulai
            </span>
          )}
        </div>
        {item.createdAt && (
          <span className="text-[10px] text-muted-foreground">
            {format(new Date(item.createdAt), 'd MMM yyyy', { locale: idLocale })}
          </span>
        )}
      </div>

      {/* Barter items */}
      <div className="flex items-center gap-2">
        <div className="flex-1 flex items-center gap-2 min-w-0">
          <img
            src={item.offeredItemPhoto || PLACEHOLDER_IMG}
            alt=""
            className="w-12 h-12 rounded-lg object-cover flex-shrink-0"
          />
          <div className="min-w-0">
            <p className="text-[10px] text-muted-foreground">Ditawarkan</p>
            <p className="text-xs font-semibold truncate">{item.offeredItemTitle}</p>
          </div>
        </div>
        <div className="flex-shrink-0">
          <ArrowRightLeft className="w-4 h-4 text-primary" />
        </div>
        <div className="flex-1 flex items-center gap-2 min-w-0">
          <img
            src={item.requestedItemPhoto || PLACEHOLDER_IMG}
            alt=""
