    "src/pages/HelpPage.tsx": "import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Search, ChevronDown, ChevronUp, MessageSquare, BookOpen, HelpCircle, Phone, Mail, ExternalLink } from 'lucide-react';

const FAQ_DATA = [
  { q: 'Bagaimana cara upload barang?', a: 'Buka tab Barter di navigasi bawah, lalu ketuk tombol "+ Upload Barang". Isi foto, nama, deskripsi, kategori, kondisi, dan lokasi barang kamu. Pastikan foto jelas agar menarik minat penukar lain.' },
