    "src/pages/SecurityPage.tsx": "import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Shield, Mail, Smartphone, Key, CheckCircle, AlertTriangle, Pencil, X, Loader2 } from 'lucide-react';
import { useAuth } from 'zitejs/auth';
import { useProfile } from '../hooks/useProfile';
import { updateProfile } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { toast } from 'sonner';

type EditingField = 'phone' | null;

export default function SecurityPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { profile, loading, refresh } = useProfile();
  const [editing, setEditing] = useState<EditingField>(null);
  const [phoneValue, setPhoneValue] = useState('');
  const [saving, setSaving] = useState(false);

  const startEditPhone = () => {
    setPhoneValue(profile?.phone || '');
    setEditing('phone');
  };

  const cancelEdit = () => {
    setEditing(null);
    setPhoneValue('');
  };

  const savePhone = async () => {
    if (!phoneValue.trim()) {
      toast.error('Nomor telepon tidak boleh kosong');
      return;
    }
    setSaving(true);
    try {
      await updateProfile({ phone: phoneValue.trim() });
      toast.success('Nomor telepon berhasil diperbarui');
      refresh();
      setEditing(null);
    } catch {
      toast.error('Gagal menyimpan');
    }
    setSaving(false);
  };

  // Calculate security score
  const checks = [
    !!user?.emailVerified,
    !!profile?.phone,
    true, // password always set
    !!profile?.address,
  ];
  const score = Math.round((checks.filter(Boolean).length / checks.length) * 100);

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-[420px] mx-auto">
          <div className="bg-primary px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white">Keamanan Akun</h1>
          </div>
          <div className="p-4 space-y-4">
            {[0,1,2,3].map(i => <Skeleton key={i} className="h-16 w-full rounded-xl" />)}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">Keamanan Akun</h1>
          </div>
        </div>

        {/* Security score */}
        <div className="mx-4 mt-4 bg-card rounded-2xl border border-border p-4">
          <div className="flex items-center gap-3 mb-3">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center ${score >= 75 ? 'bg-emerald-100' : 'bg-amber-100'}`}>
              <Shield className={`w-6 h-6 ${score >= 75 ? 'text-emerald-600' : 'text-amber-600'}`} />
            </div>
            <div>
              <p className="font-bold text-sm">Skor Keamanan</p>
              <p className={`text-2xl font-bold ${score >= 75 ? 'text-emerald-600' : 'text-amber-600'}`}>{score}%</p>
            </div>
          </div>
          <div className="w-full bg-muted rounded-full h-2">
            <div
              className={`rounded-full h-2 transition-all ${score >= 75 ? 'bg-emerald-500' : 'bg-amber-500'}`}
              style={{ width: `${score}%` }}
            />
          </div>
          <p className="text-[10px] text-muted-foreground mt-2">
            {score >= 75
              ? 'Akun kamu cukup aman. Pertahankan!'
              : 'Lengkapi verifikasi untuk meningkatkan keamanan akun.'}
          </p>
        </div>

        {/* Security items */}
        <div className="px-4 mt-4">
          <div className="bg-card rounded-2xl border border-border overflow-hidden divide-y divide-border">
            {/* Email */}
            <div className="px-4 py-4">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                  <Mail className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">Email</p>
                  <p className="text-[11px] text-muted-foreground truncate">{user?.email || '-'}</p>
                </div>
                {user?.emailVerified ? (
                  <span className="flex items-center gap-1 text-[10px] text-emerald-600 font-medium">
                    <CheckCircle className="w-3.5 h-3.5" /> Terverifikasi
                  </span>
                ) : (
                  <span className="flex items-center gap-1 text-[10px] text-amber-600 font-medium">
                    <AlertTriangle className="w-3.5 h-3.5" /> Belum verifikasi
                  </span>
                )}
              </div>
              <p className="text-[10px] text-muted-foreground mt-1.5 ml-12">
                Email dikelola melalui sistem login. Untuk mengubah email, silakan hubungi admin.
              </p>
            </div>

            {/* Phone — editable */}
            <div className="px-4 py-4">
              {editing === 'phone' ? (
                <div>
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                      <Smartphone className="w-4 h-4 text-primary" />
                    </div>
                    <p className="text-sm font-semibold flex-1">Edit Nomor Telepon</p>
                    <button onClick={cancelEdit} className="p-1">
                      <X className="w-4 h-4 text-muted-foreground" />
                    </button>
                  </div>
                  <input
                    type="tel"
                    value={phoneValue}
                    onChange={e => setPhoneValue(e.target.value)}
                    placeholder="08xxxxxxxxxx"
                    className="w-full bg-muted rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
                    autoFocus
                  />
                  <div className="flex gap-2 mt-3">
                    <button onClick={cancelEdit} className="flex-1 py-2.5 rounded-xl border border-border text-sm font-semibold text-foreground">
                      Batal
                    </button>
                    <button onClick={savePhone} disabled={saving} className="flex-1 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold flex items-center justify-center gap-1.5">
                      {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Simpan'}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                    <Smartphone className="w-4 h-4 text-primary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold">Nomor Telepon</p>
                    <p className="text-[11px] text-muted-foreground truncate">{profile?.phone || 'Belum diisi'}</p>
                  </div>
                  <button onClick={startEditPhone} className="flex items-center gap-1 text-[10px] text-primary font-medium px-2 py-1 rounded-lg hover:bg-primary/5 transition-colors">
                    <Pencil className="w-3 h-3" /> Edit
                  </button>
                </div>
              )}
            </div>

            {/* Password */}
            <div className="px-4 py-4">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                  <Key className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">Password</p>
                  <p className="text-[11px] text-muted-foreground">••••••••</p>
                </div>
                <span className="flex items-center gap-1 text-[10px] text-emerald-600 font-medium">
                  <CheckCircle className="w-3.5 h-3.5" /> Aktif
                </span>
              </div>
              <p className="text-[10px] text-muted-foreground mt-1.5 ml-12">
                Password dikelola oleh sistem autentikasi MUTARI. Gunakan fitur "Lupa Password" di halaman login untuk mereset.
              </p>
            </div>
          </div>
        </div>

        {/* Tips */}
        <div className="px-4 mt-5">
          <h3 className="font-bold text-sm mb-2">Tips Keamanan</h3>
          <div className="bg-card rounded-2xl border border-border p-4 space-y-2.5">
            {[
              'Jangan bagikan password kepada siapapun.',
              'Lengkapi nomor telepon untuk verifikasi dua langkah.',
              'Pastikan email yang terdaftar masih aktif.',
              'Perbarui alamat agar proses barter COD aman.',
            ].map((tip, i) => (
              <div key={i} className="flex items-start gap-2">
                <span className="text-primary text-xs mt-0.5">•</span>
                <p className="text-xs text-foreground">{tip}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
