    "src/pages/SettingsPage.tsx": "import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Globe, Moon, Sun, FileText, Info, ChevronRight, Check, X } from 'lucide-react';
import { useI18n, type Lang } from '../context/I18nContext';

type Overlay = null | 'bahasa' | 'tampilan' | 'syarat' | 'privasi' | 'tentang';

export default function SettingsPage() {
  const navigate = useNavigate();
  const { lang, setLang, t } = useI18n();
  const [overlay, setOverlay] = useState<Overlay>(null);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('mutari-theme');
    if (saved === 'dark') return 'dark';
    if (saved === 'light') return 'light';
    return document.documentElement.classList.contains('dark') ? 'dark' : 'light';
  });

  const toggleTheme = (t: 'light' | 'dark') => {
    setTheme(t);
    localStorage.setItem('mutari-theme', t);
    if (t === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  };

  const items = [
    { icon: Globe, label: t('settings.language'), value: lang === 'id' ? 'Indonesia' : 'English', target: 'bahasa' as Overlay },
    { icon: theme === 'dark' ? Moon : Sun, label: t('settings.theme'), value: theme === 'dark' ? t('settings.dark') : t('settings.light'), target: 'tampilan' as Overlay },
    { icon: FileText, label: t('settings.terms'), value: '', target: 'syarat' as Overlay },
    { icon: FileText, label: t('settings.privacy'), value: '', target: 'privasi' as Overlay },
    { icon: Info, label: t('settings.about'), value: 'v1.0.0', target: 'tentang' as Overlay },
  ];

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">{t('settings.title')}</h1>
          </div>
        </div>

        <div className="px-4 mt-4">
          <div className="bg-card rounded-2xl border border-border overflow-hidden divide-y divide-border">
            {items.map(item => (
              <button key={item.label} onClick={() => setOverlay(item.target)} className="w-full px-4 py-3.5 flex items-center gap-3 text-left hover:bg-muted/50 transition-colors">
                <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                  <item.icon className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">{item.label}</p>
                </div>
                {item.value && <span className="text-xs text-muted-foreground">{item.value}</span>}
                <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0" />
              </button>
            ))}
          </div>
        </div>

        <div className="px-4 mt-6 text-center">
          <div className="w-14 h-14 rounded-full bg-primary text-primary-foreground flex items-center justify-center mx-auto text-xl font-bold mb-2">M</div>
          <p className="font-bold text-sm">MUTARI</p>
          <p className="text-[10px] text-muted-foreground mt-0.5">Barang Berputar, Manfaat Berlanjut</p>
          <p className="text-[10px] text-muted-foreground mt-1">© 2026 MUTARI. All rights reserved.</p>
        </div>
      </div>

      {overlay && (
        <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/40" onClick={() => setOverlay(null)}>
          <div className="max-w-[420px] w-full bg-card rounded-t-2xl max-h-[80vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between px-4 py-3 border-b border-border sticky top-0 bg-card z-10">
              <h2 className="font-bold text-sm">
                {overlay === 'bahasa' && t('settings.chooseLanguage')}
                {overlay === 'tampilan' && t('settings.appearance')}
                {overlay === 'syarat' && t('settings.terms')}
                {overlay === 'privasi' && t('settings.privacy')}
                {overlay === 'tentang' && t('settings.about')}
              </h2>
              <button onClick={() => setOverlay(null)} className="p-1"><X className="w-5 h-5 text-muted-foreground" /></button>
            </div>

            <div className="p-4">
              {overlay === 'bahasa' && <BahasaContent lang={lang} onSelect={(l) => { setLang(l); setOverlay(null); }} />}
              {overlay === 'tampilan' && <TampilanContent theme={theme} onToggle={toggleTheme} lang={lang} />}
              {overlay === 'syarat' && <SyaratContent lang={lang} />}
              {overlay === 'privasi' && <PrivasiContent lang={lang} />}
              {overlay === 'tentang' && <TentangContent />}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function BahasaContent({ lang, onSelect }: { lang: Lang; onSelect: (l: Lang) => void }) {
  const options: { code: Lang; label: string; flag: string }[] = [
    { code: 'id', label: 'Indonesia', flag: '🇮🇩' },
    { code: 'en', label: 'English', flag: '🇬🇧' },
  ];
  return (
    <div className="space-y-2">
      {options.map(o => (
        <button key={o.code} onClick={() => onSelect(o.code)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl border transition-colors ${o.code === lang ? 'border-primary bg-primary/5' : 'border-border hover:bg-muted/50'}`}>
          <span className="text-lg">{o.flag}</span>
          <span className="text-sm flex-1 text-left">{o.label}</span>
          {o.code === lang && <Check className="w-4 h-4 text-primary" />}
        </button>
      ))}
    </div>
  );
}

function TampilanContent({ theme, onToggle, lang }: { theme: string; onToggle: (t: 'light' | 'dark') => void; lang: Lang }) {
  const options = [
    { val: 'light' as const, label: lang === 'id' ? 'Terang' : 'Light', Icon: Sun },
    { val: 'dark' as const, label: lang === 'id' ? 'Gelap' : 'Dark', Icon: Moon },
  ];
  return (
    <div className="space-y-2">
      {options.map(({ val, label, Icon }) => (
        <button key={val} onClick={() => onToggle(val)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl border transition-colors ${theme === val ? 'border-primary bg-primary/5' : 'border-border hover:bg-muted/50'}`}>
          <Icon className="w-4 h-4 text-primary" />
          <span className="text-sm flex-1 text-left">{label}</span>
          {theme === val && <Check className="w-4 h-4 text-primary" />}
        </button>
      ))}
    </div>
  );
}

function SyaratContent({ lang }: { lang: Lang }) {
  if (lang === 'en') {
    return (
      <div className="text-xs text-muted-foreground leading-relaxed space-y-3">
        <p className="font-semibold text-foreground">MUTARI Terms of Use</p>
        <p>By using MUTARI, you agree to the following terms and conditions:</p>
        <p><strong className="text-foreground">1. General Terms</strong><br/>MUTARI is a platform for bartering used goods, connecting users to exchange items without money.</p>
        <p><strong className="text-foreground">2. User Accounts</strong><br/>Users must provide accurate information when registering. Each user is responsible for their account security.</p>
