                <span>{r}</span>
              </div>
            ))}
          </div>

          <div className="flex gap-2 mt-3">
            <button onClick={() => navigate(`/item/${match.id}`)} className="flex-1 bg-muted text-foreground rounded-xl py-2.5 text-xs font-semibold">
              Detail
            </button>
            <button className="flex-1 bg-primary text-primary-foreground rounded-xl py-2.5 text-xs font-semibold">
              Ajukan Barter
            </button>
          </div>
        </motion.div>
      )}
    </motion.div>
  );
}
