              ) : (
                <div className="w-9 h-9 rounded-full bg-white/20 text-white flex items-center justify-center text-xs font-bold border-2 border-white/30">
                  {((user?.firstName?.[0] || '') + (user?.lastName?.[0] || '') || user?.email?.[0] || 'U').toUpperCase()}
                </div>
              )}
            </div>

            {/* Balance card */}
            {loading ? (
              <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-5 space-y-3">
                <Skeleton className="h-4 w-20 bg-white/20" />
                <Skeleton className="h-10 w-32 bg-white/20" />
                <Skeleton className="h-5 w-28 bg-white/20 rounded-full" />
