                <div className="flex gap-0.5">
                  {BADGES.map((b) => {
                    const segmentMax = b.maxPoints ?? (b.minPoints + 500);
                    const segmentRange = segmentMax - b.minPoints;
                    let fillPercent = 0;
                    if (totalPoints >= segmentMax) fillPercent = 100;
                    else if (totalPoints > b.minPoints) fillPercent = ((totalPoints - b.minPoints) / segmentRange) * 100;
                    const isCurrent = b.id === badge.id;

                    return (
                      <div key={b.id} className="flex-1">
