  "src/api/cancelBarter.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Cancel a barter — initiator can cancel when waiting, either party when accepted',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    reason: z.string().min(1).max(200),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Only allow cancel if Menunggu or Diterima
    if (barter.status !== 'Menunggu' && barter.status !== 'Diterima') {
      throw new ZiteError('Barter tidak bisa dibatalkan pada status ini');
    }

    // If status is Menunggu, only initiator can cancel
    if (barter.status === 'Menunggu' && context.user.id !== initiatorId) {
      throw new ZiteError('Hanya pengirim penawaran yang bisa membatalkan pada tahap ini');
    }

    // Cancel the barter
    await zite.barterHistory.update({
      id: input.barterId,
      record: { status: 'Dibatalkan' },
    });

    // Reset item statuses back to available
    const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
    const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
    if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Tersedia' } });
    if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Tersedia' } });

    // Reputation penalty: -5 points if cancelling after accepted (breaking a deal)
    let penaltyApplied = false;
    if (barter.status === 'Diterima') {
      penaltyApplied = true;
      const existingPoints = await zite.userPoints.findOne({ filters: { user: context.user.id } });
      if (existingPoints) {
        await zite.userPoints.update({
          id: existingPoints.id,
          record: { totalPoints: Math.max(0, (existingPoints.totalPoints ?? 0) - 5) },
        });
      }
      await zite.pointHistory.create({
        record: {
          activity: 'Membatalkan Barter (setelah diterima)',
          user: context.user.id,
          points: -5,
          activityType: 'barter_cancel_penalty',
        },
      });
    }

    const userName = context.user.firstName || context.user.email.split('@')[0];

    // System message
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: `❌ ${userName} membatalkan barter. Alasan: "${input.reason}"${penaltyApplied ? ' (-5 poin penalti)' : ''}`,
        type: 'System',
      },
    });

    // Notify the other party
    const recipientId = context.user.id === initiatorId ? partnerId : initiatorId;
    if (recipientId) {
      await zite.notifications.create({
        record: {
          title: 'Barter Dibatalkan',
          body: `${userName} membatalkan barter. Alasan: "${input.reason.slice(0, 60)}"`,
          type: 'Barter',
          recipient: recipientId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { success: true };
  },
});
