  "src/api/confirmBarterComplete.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Confirm barter completion — both parties must confirm for it to be final',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    confirmed: z.boolean(),
    bothConfirmed: z.boolean(),
    pointsEarned: z.number(),
  }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    if (barter.status !== 'Diterima') {
      throw new ZiteError('Barter belum diterima');
    }

    const isInitiator = context.user.id === initiatorId;
    const updateField = isInitiator ? 'initiatorConfirmed' : 'partnerConfirmed';
    const alreadyConfirmed = isInitiator ? barter.initiatorConfirmed : barter.partnerConfirmed;

    if (alreadyConfirmed) {
      throw new ZiteError('Anda sudah mengonfirmasi');
    }

    await zite.barterHistory.update({ id: input.barterId, record: { [updateField]: true } });

    // Check if both confirmed
    const otherConfirmed = isInitiator ? barter.partnerConfirmed : barter.initiatorConfirmed;
    const bothConfirmed = otherConfirmed === true;

    let pointsEarned = 0;

    if (bothConfirmed && !barter.pointsAwarded) {
      // Both confirmed! Complete the barter
      pointsEarned = 50;

      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          status: 'Selesai',
          completedAt: new Date().toISOString(),
          pointsAwarded: true,
        },
      });

      // Mark items as traded
      const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
      const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
      if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Sudah Ditukar' } });
      if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Sudah Ditukar' } });

      // Award points to both users
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        const existing = await zite.userPoints.findOne({ filters: { user: userId } });
        if (existing) {
          await zite.userPoints.update({
            id: existing.id,
            record: {
              totalPoints: (existing.totalPoints ?? 0) + pointsEarned,
              bartersCompleted: (existing.bartersCompleted ?? 0) + 1,
            },
          });
        }
        await zite.pointHistory.create({
          record: {
            activity: 'Barter Selesai',
            user: userId,
            points: pointsEarned,
            activityType: 'barter_complete',
          },
        });
      }

      // System message
      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `🎉 Barter berhasil diselesaikan! Kedua pihak mendapat +${pointsEarned} poin.`,
          type: 'System',
        },
      });

      // Notify both
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        await zite.notifications.create({
          record: {
            title: 'Barter Selesai! 🎉',
            body: `Selamat! Barter berhasil. Anda mendapat +${pointsEarned} poin.`,
            type: 'Barter',
            recipient: userId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    } else {
      // Notify the other party
      const recipientId = isInitiator ? partnerId : initiatorId;
      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `✅ ${`${context.user.firstName || context.user.email.split("@")[0]}`} telah mengonfirmasi barter selesai. Menunggu konfirmasi pihak lain.`,
          type: 'System',
        },
      });
      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: 'Konfirmasi Barter',
            body: `${`${context.user.firstName || context.user.email.split("@")[0]}`} sudah konfirmasi barter selesai. Giliran Anda!`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    }

    return { confirmed: true, bothConfirmed, pointsEarned };
  },
});
",
  "src/api/createBarterOffer.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Creates a barter offer — user picks their item to trade for a target item',
  authenticated: true,
  inputSchema: z.object({
    targetItemId: z.string(),
    offeredItemId: z.string(),
    message: z.string().optional(),
  }),
  outputSchema: z.object({
    barterId: z.string(),
  }),
  execute: async ({ input, context }) => {
    // Validate target item exists
    const targetItem = await zite.items.findOne({ id: input.targetItemId });
    if (!targetItem) throw new ZiteError('Barang target tidak ditemukan');

    // Can't barter with yourself
    const ownerIds = Array.isArray(targetItem.owner) ? targetItem.owner : [targetItem.owner];
    if (ownerIds.includes(context.user.id)) {
      throw new ZiteError('Tidak bisa barter dengan barang sendiri');
    }

    // Validate offered item belongs to current user
    const offeredItem = await zite.items.findOne({ id: input.offeredItemId });
    if (!offeredItem) throw new ZiteError('Barang yang ditawarkan tidak ditemukan');
    const offeredOwnerIds = Array.isArray(offeredItem.owner) ? offeredItem.owner : [offeredItem.owner];
    if (!offeredOwnerIds.includes(context.user.id)) {
      throw new ZiteError('Barang ini bukan milik Anda');
    }

    // Create barter history record
    const barter = await zite.barterHistory.create({
      record: {
        title: `${offeredItem.title || 'Barang'} ↔ ${targetItem.title || 'Barang'}`,
        initiator: context.user.id,
        partner: ownerIds[0] || null,
        offeredItem: input.offeredItemId,
        requestedItem: input.targetItemId,
        status: 'Menunggu',
        notes: input.message || null,
        completedAt: null,
        codAddress: null,
        codDetail: null,
        initiatorConfirmed: false,
        partnerConfirmed: false,
        pointsAwarded: false,
        expiresAt: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
      },
    });

    // Send initial system message
    await zite.barterMessages.create({
      record: {
        barter: barter.id,
        sender: context.user.id,
        content: input.message || `Halo! Saya ingin menukar "${offeredItem.title}" dengan "${targetItem.title}" milik Anda.`,
        type: 'Text',
      },
    });

    // Update item statuses
    await zite.items.update({ id: input.targetItemId, record: { status: 'Negosiasi' } });
    await zite.items.update({ id: input.offeredItemId, record: { status: 'Negosiasi' } });

    // Notify the owner
    await zite.notifications.create({
      record: {
        title: 'Penawaran Barter Baru!',
        body: `${`${context.user.firstName || context.user.email.split("@")[0]}`} ingin menukar "${offeredItem.title}" dengan "${targetItem.title}" Anda`,
        type: 'Barter',
        recipient: ownerIds[0] || null,
        read: false,
        linkPath: `/barter/${barter.id}`,
      },
    });

    return { barterId: barter.id };
  },
});
",
  "src/api/getActiveChats.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get active barter conversations for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    chats: z.array(z.object({
      barterId: z.string(),
      title: z.string(),
      status: z.string(),
      otherUserName: z.string(),
      otherUserImage: z.string().nullable(),
      lastMessage: z.string().nullable(),
      lastMessageAt: z.string().nullable(),
      offeredItemPhoto: z.string().nullable(),
      requestedItemPhoto: z.string().nullable(),
    })),
  }),
  execute: async ({ context }) => {
    // Find all barters where user is initiator or partner
    const { rows } = await zite.sql({
      query: `SELECT bh."id", bh."title", bh."status", bh."initiator", bh."partner",
                     bh."offeredItem", bh."requestedItem", bh."createdAt"
              FROM "BarterHistory" bh
              WHERE bh."status" IN ('Menunggu', 'Diterima')
              ORDER BY bh."createdAt" DESC
              LIMIT 50`,
    });

    const users = await zite.auth.findAllUsers({ limit: 100 });
    const userMap = new Map(users.records.map(u => [u.id, u]));

    const chats: Array<{
      barterId: string;
      title: string;
      status: string;
      otherUserName: string;
      otherUserImage: string | null;
      lastMessage: string | null;
      lastMessageAt: string | null;
      offeredItemPhoto: string | null;
      requestedItemPhoto: string | null;
    }> = [];
    for (const r of rows) {
      const initiatorIds = Array.isArray(r.initiator) ? r.initiator as string[] : r.initiator ? [r.initiator as string] : [];
      const partnerIds = Array.isArray(r.partner) ? r.partner as string[] : r.partner ? [r.partner as string] : [];

      const isInitiator = initiatorIds.includes(context.user.id);
      const isPartner = partnerIds.includes(context.user.id);
      if (!isInitiator && !isPartner) continue;

      const otherUserId = isInitiator ? partnerIds[0] : initiatorIds[0];
      const otherUser = otherUserId ? userMap.get(otherUserId) : null;

      // Get last message
      const { rows: msgRows } = await zite.sql({
        query: `SELECT bm."content", bm."sentAt"
                FROM "BarterMessages" bm
                JOIN "BarterMessagesBarterHistory" link ON link."barterMessagesId" = bm."id"
                WHERE link."barterHistoryId" = $1
                ORDER BY bm."sentAt" DESC
                LIMIT 1`,
        params: [r.id as string],
      });

      // Get item photos
      const offeredItemIds = Array.isArray(r.offeredItem) ? r.offeredItem as string[] : r.offeredItem ? [r.offeredItem as string] : [];
      const requestedItemIds = Array.isArray(r.requestedItem) ? r.requestedItem as string[] : r.requestedItem ? [r.requestedItem as string] : [];

      const [offeredItem, requestedItem] = await Promise.all([
        offeredItemIds[0] ? zite.items.findOne({ id: offeredItemIds[0], fields: ['photos'] }) : null,
        requestedItemIds[0] ? zite.items.findOne({ id: requestedItemIds[0], fields: ['photos'] }) : null,
      ]);

      chats.push({
        barterId: r.id as string,
        title: (r.title as string) || 'Barter',
        status: (r.status as string) || 'Menunggu',
        otherUserName: otherUser?.name || 'Pengguna',
        otherUserImage: otherUser?.image ?? null,
        lastMessage: msgRows[0]?.content as string ?? null,
        lastMessageAt: msgRows[0]?.sentAt as string ?? null,
        offeredItemPhoto: offeredItem?.photos?.[0]?.url || null,
        requestedItemPhoto: requestedItem?.photos?.[0]?.url || null,
      });
    }

    return { chats };
  },
});
",
  "src/api/getBarterDetail.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const itemSchema = z.object({
  id: z.string(),
  title: z.string(),
  photo: z.string().nullable(),
  condition: z.string(),
  estimatedValueMin: z.number().nullable(),
  estimatedValueMax: z.number().nullable(),
});

export default createEndpoint({
  description: 'Get full barter detail including items, users, status, review info, and expiry',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    barter: z.object({
      id: z.string(),
      title: z.string(),
      status: z.string(),
      createdAt: z.string().nullable(),
      completedAt: z.string().nullable(),
      expiresAt: z.string().nullable(),
      codAddress: z.string().nullable(),
      codDetail: z.string().nullable(),
      initiatorConfirmed: z.boolean(),
      partnerConfirmed: z.boolean(),
      notes: z.string().nullable(),
      initiator: z.object({ id: z.string(), name: z.string(), image: z.string().nullable() }),
      partner: z.object({ id: z.string(), name: z.string(), image: z.string().nullable() }),
      offeredItem: itemSchema.nullable(),
      requestedItem: itemSchema.nullable(),
      myRole: z.enum(['initiator', 'partner']),
      myReviewSubmitted: z.boolean(),
      otherReviewSubmitted: z.boolean(),
      isExpired: z.boolean(),
    }),
  }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Check expiry: auto-cancel if "Menunggu" and past 3 days
    let currentStatus = barter.status || 'Menunggu';
    let isExpired = false;
    const expiresAt = barter.expiresAt ?? null;

    if (currentStatus === 'Menunggu' && expiresAt) {
      const expiry = new Date(expiresAt);
      if (new Date() > expiry) {
        isExpired = true;
        currentStatus = 'Dibatalkan';
        // Auto-cancel expired barter
        await zite.barterHistory.update({ id: input.barterId, record: { status: 'Dibatalkan' } });
        const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
        const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
        if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Tersedia' } });
        if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Tersedia' } });
        await zite.barterMessages.create({
          record: {
            barter: input.barterId,
            sender: context.user.id,
            content: '⏰ Penawaran otomatis dibatalkan karena tidak ada respon dalam 3 hari.',
            type: 'System',
          },
        });
      }
    }

    // Fetch users
    const users = await zite.auth.findAllUsers({ limit: 50 });
    const initiatorUser = users.records.find(u => u.id === initiatorId);
    const partnerUser = users.records.find(u => u.id === partnerId);

    // Fetch items
    const offeredItemId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
    const requestedItemId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;

    const [offeredItem, requestedItem] = await Promise.all([
      offeredItemId ? zite.items.findOne({ id: offeredItemId }) : null,
      requestedItemId ? zite.items.findOne({ id: requestedItemId }) : null,
    ]);

    const mapItem = (item: typeof offeredItem) => item ? {
      id: item.id,
      title: item.title || 'Tanpa judul',
      photo: item.photos?.[0]?.url || null,
      condition: item.condition || '',
      estimatedValueMin: item.estimatedValueMin ?? null,
      estimatedValueMax: item.estimatedValueMax ?? null,
    } : null;

    // Check review status
    const { records: reviews } = await zite.barterReviews.findAll({
      limit: 10,
    });
    const barterReviews = reviews.filter(r => {
      const bIds = Array.isArray(r.barter) ? r.barter : r.barter ? [r.barter] : [];
      return bIds.includes(input.barterId);
    });

    const myReviewSubmitted = barterReviews.some(r => {
      const rIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      return rIds.includes(context.user.id);
    });
    const otherUserId = context.user.id === initiatorId ? partnerId : initiatorId;
    const otherReviewSubmitted = barterReviews.some(r => {
      const rIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      return rIds.includes(otherUserId || '');
    });

    return {
      barter: {
        id: barter.id,
        title: barter.title || '',
        status: currentStatus,
        createdAt: barter.createdAt ?? null,
        completedAt: barter.completedAt ?? null,
        expiresAt,
        codAddress: barter.codAddress ?? null,
        codDetail: barter.codDetail ?? null,
        initiatorConfirmed: barter.initiatorConfirmed ?? false,
        partnerConfirmed: barter.partnerConfirmed ?? false,
        notes: barter.notes ?? null,
        initiator: {
          id: initiatorId || '',
          name: initiatorUser?.name || 'Pengguna',
          image: initiatorUser?.image ?? null,
        },
        partner: {
          id: partnerId || '',
          name: partnerUser?.name || 'Pengguna',
          image: partnerUser?.image ?? null,
        },
        offeredItem: mapItem(offeredItem),
        requestedItem: mapItem(requestedItem),
        myRole: context.user.id === initiatorId ? 'initiator' as const : 'partner' as const,
        myReviewSubmitted,
        otherReviewSubmitted,
        isExpired,
      },
    };
  },
});
",
  "src/api/getBarterHistory.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get barter history for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    history: z.array(z.object({
      id: z.string(),
      title: z.string(),
      partnerName: z.string(),
      offeredItemTitle: z.string(),
      offeredItemPhoto: z.string().nullable(),
      requestedItemTitle: z.string(),
      requestedItemPhoto: z.string().nullable(),
      status: z.string(),
      notes: z.string(),
      createdAt: z.string(),
      completedAt: z.string().nullable(),
      isInitiator: z.boolean(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Find barters where user is initiator or partner
    const [asInitiator, asPartner] = await Promise.all([
      zite.barterHistory.findAll({ filters: { initiator: userId }, limit: 100 }),
      zite.barterHistory.findAll({ filters: { partner: userId }, limit: 100 }),
    ]);

    const all = [
      ...asInitiator.records.map(r => ({ ...r, isInitiator: true })),
      ...asPartner.records.map(r => ({ ...r, isInitiator: false })),
    ];

    // Sort by createdAt desc
    all.sort((a, b) => new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime());

    // Fetch related data
    const history = await Promise.all(
      all.map(async (barter) => {
        const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
        const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;

        const [offered, requested] = await Promise.all([
          offeredId ? zite.items.findOne({ id: offeredId }) : null,
          requestedId ? zite.items.findOne({ id: requestedId }) : null,
        ]);

        // Get partner name
        const partnerId = barter.isInitiator
          ? (Array.isArray(barter.partner) ? barter.partner[0] : barter.partner)
          : (Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator);

        let partnerName = 'Pengguna';
        if (partnerId) {
          const { records: users } = await zite.auth.findAllUsers({
            filters: { id: partnerId },
            limit: 1,
          });
          if (users.length > 0) partnerName = users[0].name || users[0].email;
        }

        return {
          id: barter.id,
          title: barter.title || 'Barter',
          partnerName,
          offeredItemTitle: offered?.title || 'Barang',
          offeredItemPhoto: offered?.photos?.[0]?.url || null,
          requestedItemTitle: requested?.title || 'Barang',
          requestedItemPhoto: requested?.photos?.[0]?.url || null,
          status: barter.status || 'pending',
          notes: barter.notes || '',
          createdAt: barter.createdAt || '',
          completedAt: barter.completedAt || null,
          isInitiator: barter.isInitiator,
        };
      })
    );

    return { history };
  },
});
",
