  "src/api/getItem.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch a single item by ID and increment its view count',
  inputSchema: z.object({
    id: z.string(),
  }),
  outputSchema: z.object({
    item: z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      photos: z.array(z.object({ url: z.string(), filename: z.string().optional() })),
      condition: z.string(),
      completeness: z.string(),
      defects: z.string(),
      specifications: z.string(),
      estimatedValueMin: z.number().nullable(),
      estimatedValueMax: z.number().nullable(),
      desiredItems: z.string(),
      additionalWants: z.string(),
      barterReason: z.string(),
      barterMethod: z.array(z.string()),
      location: z.string(),
      status: z.string(),
      viewsCount: z.number(),
      likesCount: z.number(),
      createdAt: z.string().nullable(),
      ownerName: z.string(),
      ownerImage: z.string().nullable(),
      ownerPoints: z.number(),
      ownerBarterCount: z.number(),
      ownerMemberSince: z.string(),
      ownerId: z.string(),
    }).nullable(),
  }),
  execute: async ({ input }) => {
    const record = await zite.items.findOne({ id: input.id });
    if (!record) return { item: null };

    // Increment views
    const newViews = (record.viewsCount ?? 0) + 1;
    await zite.items.update({ id: input.id, record: { viewsCount: newViews } });

    // Get owner info
    let ownerName = 'Pemilik';
    let ownerImage: string | null = null;
    let ownerPoints = 0;
    let ownerBarterCount = 0;
    let ownerMemberSince = '2024';

    let ownerId = '';

    if (record.owner) {
      ownerId = Array.isArray(record.owner) ? record.owner[0] : record.owner;
      if (ownerId) {
        const { records: users } = await zite.auth.findAllUsers({
          filters: { id: ownerId },
          limit: 1,
        });
        if (users.length > 0) {
          ownerName = users[0].name || users[0].firstName || users[0].email;
          ownerImage = users[0].image ?? null;
          const created = (users[0] as any).createdAt;
          if (created) {
            ownerMemberSince = new Date(created).getFullYear().toString();
          }
        }

        // Get owner points
        const ownerPts = await zite.userPoints.findOne({ filters: { user: ownerId } });
        if (ownerPts) {
          ownerPoints = ownerPts.totalPoints ?? 0;
          ownerBarterCount = ownerPts.bartersCompleted ?? 0;
        }
      }
    }

    return {
      item: {
        id: record.id,
        title: record.title || '',
        description: record.description || '',
        photos: record.photos?.map(p => ({ url: p.url, filename: p.filename })) || [],
        condition: record.condition || '',
        completeness: record.completeness || '',
        defects: record.defects || '',
        specifications: record.specifications || '',
        estimatedValueMin: record.estimatedValueMin ?? null,
        estimatedValueMax: record.estimatedValueMax ?? null,
        desiredItems: record.desiredItems || '',
        additionalWants: record.additionalWants || '',
        barterReason: record.barterReason || '',
        barterMethod: Array.isArray(record.barterMethod) ? record.barterMethod : record.barterMethod ? [record.barterMethod] : [],
        location: record.location || '',
        status: record.status || '',
        viewsCount: newViews,
        likesCount: record.likesCount ?? 0,
        createdAt: record.createdAt ?? null,
        ownerName,
        ownerImage,
        ownerPoints,
        ownerBarterCount,
        ownerMemberSince,
        ownerId,
      },
    };
  },
});
",
  "src/api/getItems.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch available barter items with optional search and category filter',
  inputSchema: z.object({
    limit: z.number().optional(),
    search: z.string().optional(),
    categoryId: z.string().optional(),
  }),
  outputSchema: z.object({
    items: z.array(z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      photos: z.array(z.object({ url: z.string(), filename: z.string().optional() })).optional(),
      condition: z.string(),
      estimatedValueMin: z.number().nullable(),
      estimatedValueMax: z.number().nullable(),
      location: z.string(),
      status: z.string(),
      viewsCount: z.number(),
      likesCount: z.number(),
      createdAt: z.string().nullable(),
      category: z.array(z.string()).nullable(),
      ownerName: z.string(),
      ownerImage: z.string().nullable(),
    })),
  }),
  execute: async ({ input }) => {
    const limit = input.limit || 20;

    // Get all users for owner lookup
    const allUsers = await zite.auth.findAllUsers({ limit: 200 });
    const userMap = new Map(allUsers.records.map(u => [u.id, u]));

    if (input.search || input.categoryId) {
      let query = `SELECT "Items".* FROM "Items"`;
      const params: unknown[] = [];
      let paramIdx = 1;

      if (input.categoryId) {
        query += ` JOIN "CategoriesItems" ON "CategoriesItems"."itemsId" = "Items"."id" AND "CategoriesItems"."categoriesId" = $${paramIdx}`;
        params.push(input.categoryId);
        paramIdx++;
      }

      query += ` WHERE "Items"."status" = 'Tersedia'`;

      if (input.search) {
        query += ` AND (LOWER("Items"."title") LIKE $${paramIdx} OR LOWER("Items"."description") LIKE $${paramIdx})`;
        params.push(`%${input.search.toLowerCase()}%`);
        paramIdx++;
      }

      query += ` ORDER BY "Items"."createdAt" DESC NULLS LAST LIMIT $${paramIdx}`;
      params.push(limit);

      const result = await zite.sql({ query, params });

      return {
        items: result.rows.map((r: Record<string, unknown>) => {
          const ownerIds = Array.isArray(r.owner) ? r.owner as string[] : r.owner ? [r.owner as string] : [];
          const owner = ownerIds[0] ? userMap.get(ownerIds[0]) : null;
          return {
            id: String(r.id || ''),
            title: String(r.title || ''),
            description: String(r.description || ''),
            photos: r.photos as { url: string; filename?: string }[] | undefined,
            condition: String(r.condition || ''),
            estimatedValueMin: (r.estimatedValueMin as number) ?? null,
            estimatedValueMax: (r.estimatedValueMax as number) ?? null,
            location: String(r.location || ''),
            status: String(r.status || ''),
            viewsCount: (r.viewsCount as number) ?? 0,
            likesCount: (r.likesCount as number) ?? 0,
            createdAt: r.createdAt as string ?? null,
            category: r.category as string[] ?? null,
            ownerName: owner?.name || 'Pengguna',
            ownerImage: owner?.image ?? null,
          };
        }),
      };
    }

    const { records } = await zite.items.findAll({
      filters: { status: 'Tersedia' },
      limit,
    });

    return {
      items: records.map(r => {
        const ownerIds = Array.isArray(r.owner) ? r.owner : r.owner ? [r.owner] : [];
        const owner = ownerIds[0] ? userMap.get(ownerIds[0]) : null;
        return {
          id: r.id,
          title: r.title || '',
          description: r.description || '',
          photos: r.photos?.map(p => ({ url: p.url, filename: p.filename })),
          condition: r.condition || '',
          estimatedValueMin: r.estimatedValueMin ?? null,
          estimatedValueMax: r.estimatedValueMax ?? null,
          location: r.location || '',
          status: r.status || '',
          viewsCount: r.viewsCount ?? 0,
          likesCount: r.likesCount ?? 0,
