  "src/api/updateProfile.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Update the current user profile',
  authenticated: true,
  inputSchema: z.object({
    displayName: z.string().optional(),
    phone: z.string().optional(),
    bio: z.string().optional(),
    address: z.string().optional(),
    city: z.string().optional(),
    province: z.string().optional(),
    postalCode: z.string().optional(),
    preferredBarterMethod: z.string().optional(),
    emailNotifications: z.boolean().optional(),
    pushNotifications: z.boolean().optional(),
    chatNotifications: z.boolean().optional(),
    barterNotifications: z.boolean().optional(),
    firstName: z.string().optional(),
    lastName: z.string().optional(),
    image: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    let profile = await zite.userProfiles.findOne({ filters: { user: userId } });

    // Build record update from provided fields
    const record: Record<string, unknown> = {};
    if (input.displayName !== undefined) record.displayName = input.displayName;
    if (input.phone !== undefined) record.phone = input.phone;
    if (input.bio !== undefined) record.bio = input.bio;
    if (input.address !== undefined) record.address = input.address;
    if (input.city !== undefined) record.city = input.city;
    if (input.province !== undefined) record.province = input.province;
    if (input.postalCode !== undefined) record.postalCode = input.postalCode;
    if (input.preferredBarterMethod !== undefined) record.preferredBarterMethod = input.preferredBarterMethod;
    if (input.emailNotifications !== undefined) record.emailNotifications = input.emailNotifications;
    if (input.pushNotifications !== undefined) record.pushNotifications = input.pushNotifications;
    if (input.chatNotifications !== undefined) record.chatNotifications = input.chatNotifications;
    if (input.barterNotifications !== undefined) record.barterNotifications = input.barterNotifications;

    if (!profile) {
      profile = await zite.userProfiles.create({
        record: {
          displayName: input.displayName || context.user.email.split('@')[0],
          user: userId,
          phone: input.phone || null,
          bio: input.bio || null,
          address: input.address || null,
          city: input.city || null,
          province: input.province || null,
          postalCode: input.postalCode || null,
          preferredBarterMethod: input.preferredBarterMethod || 'COD',
          phoneVerified: false,
          addressVerified: false,
          emailNotifications: input.emailNotifications ?? true,
          pushNotifications: input.pushNotifications ?? true,
          chatNotifications: input.chatNotifications ?? true,
          barterNotifications: input.barterNotifications ?? true,
        },
      });
    } else {
      await zite.userProfiles.update({ id: profile.id, record: record as any });
    }

    // Update auth user name if provided
    if (input.firstName !== undefined || input.lastName !== undefined || input.image !== undefined) {
      const updates: { firstName?: string; lastName?: string; image?: string } = {};
      if (input.firstName !== undefined) updates.firstName = input.firstName;
      if (input.lastName !== undefined) updates.lastName = input.lastName;
      if (input.image !== undefined) updates.image = input.image;
      await zite.auth.updateUserProfile(userId, updates);
    }

    return { success: true };
  },
});
