  "src/components/PilihanAI.tsx": "import { Sparkles, MapPin, CheckCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

type ItemType = GetItemsOutputType['items'][0];

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function MatchBadge({ percent }: { percent: number }) {
  return (
    <div className="bg-card/90 backdrop-blur-sm rounded-full px-2.5 py-1 flex items-center gap-1 text-[11px] font-bold shadow-sm">
      <Sparkles className="w-3.5 h-3.5 text-primary" /> {percent}%
    </div>
  );
}

function estimateMatch(item: ItemType): number {
  // Simple heuristic based on item data completeness + views
  let score = 70;
  if (item.photos && item.photos.length > 0) score += 5;
  if (item.photos && item.photos.length > 2) score += 5;
  if (item.location) score += 3;
  if (item.description && item.description.length > 50) score += 4;
  if (item.viewsCount > 5) score += 3;
  if (item.likesCount > 2) score += 5;
  if (item.condition === 'Baru' || item.condition === 'Seperti Baru') score += 5;
  return Math.min(99, score);
}

function SmallCard({ item, onClick }: { item: ItemType; onClick: () => void }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  return (
    <div onClick={onClick} className="min-w-[150px] max-w-[150px] rounded-2xl overflow-hidden border border-border bg-card cursor-pointer shadow-sm hover:shadow-md transition-shadow">
      <div className="relative">
        <img src={imgUrl} alt={item.title} className="w-full h-[110px] object-cover" />
        <div className="absolute top-2 right-2">
          <MatchBadge percent={estimateMatch(item)} />
        </div>
      </div>
      <div className="p-2.5">
        <p className="text-sm font-bold truncate">{item.title}</p>
        <p className="text-[10px] text-muted-foreground mt-0.5 flex items-center gap-0.5">
          <MapPin className="w-3 h-3" /> {item.location || 'Sekitar Anda'}
        </p>
        <div className="flex items-center gap-1.5 mt-1.5 pt-1.5 border-t border-border">
          {item.ownerImage ? (
            <img src={item.ownerImage} alt={item.ownerName} className="w-5 h-5 rounded-full object-cover border border-border" />
          ) : (
            <div className="w-5 h-5 rounded-full bg-primary text-primary-foreground text-[8px] flex items-center justify-center font-bold">
              {(item.ownerName || 'P').charAt(0).toUpperCase()}
            </div>
          )}
          <span className="text-[10px] font-medium truncate">{item.ownerName || 'Pengguna'}</span>
        </div>
      </div>
    </div>
  );
}

export default function PilihanAI() {
  const navigate = useNavigate();
  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getItems({ limit: 5 }).then(res => {
      setItems(res.items);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const featured = items[0];
  const rest = items.slice(1);

  return (
    <div className="px-4 py-4">
      {/* Header */}
      <div className="flex items-center gap-2 mb-1">
        <div className="w-7 h-7 rounded-lg bg-primary/10 flex items-center justify-center">
          <Sparkles className="w-4 h-4 text-primary" />
        </div>
        <div className="flex-1">
          <p className="font-bold text-[15px] text-foreground">Pilihan AI Untukmu</p>
        </div>
        <button className="text-xs text-primary font-semibold">Semua →</button>
      </div>
      <p className="text-[11px] text-muted-foreground mb-4 ml-9">Berdasarkan preferensimu</p>

      {loading ? (
        <>
          <div className="rounded-2xl overflow-hidden border border-border bg-card mb-4">
            <Skeleton className="w-full h-44" />
            <div className="p-3 space-y-2">
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-3 w-1/2" />
            </div>
          </div>
          <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1">
            {[0, 1, 2].map(i => (
              <div key={i} className="min-w-[150px] rounded-2xl overflow-hidden border border-border bg-card">
