  "src/components/Rekomendasi.tsx": "import { Clock, MapPin, Eye, Heart, CheckCircle } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

type ItemType = GetItemsOutputType['items'][0];

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: ItemType): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function ItemCard({ item, onClick }: { item: ItemType; onClick: () => void }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  return (
    <div onClick={onClick} className="rounded-2xl overflow-hidden border border-border bg-card cursor-pointer shadow-sm hover:shadow-md transition-shadow">
      <div className="relative">
        <img src={imgUrl} alt={item.title} className="w-full h-36 object-cover" />
        <div className="absolute top-2 left-2 bg-black/50 backdrop-blur-sm rounded-full px-2.5 py-0.5 flex items-center gap-1 text-[10px] text-white font-medium">
          <Clock className="w-3 h-3" /> {item.condition || 'Baru'}
        </div>
      </div>
      <div className="p-3">
        <p className="text-sm font-bold truncate">{item.title}</p>
        <p className="text-xs text-primary font-semibold mt-1">{priceRange(item)}</p>
        {item.location && (
          <p className="text-[10px] text-muted-foreground mt-1.5 flex items-center gap-0.5">
            <MapPin className="w-3 h-3 flex-shrink-0" /> {item.location}
          </p>
        )}
        <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-1">
          <span className="flex items-center gap-0.5"><Eye className="w-3 h-3" /> {item.viewsCount}</span>
          <span className="flex items-center gap-0.5"><Heart className="w-3 h-3" /> {item.likesCount}</span>
        </div>
        <div className="flex items-center gap-1.5 mt-2.5 pt-2.5 border-t border-border">
          {item.ownerImage ? (
            <img src={item.ownerImage} alt={item.ownerName} className="w-6 h-6 rounded-full object-cover flex-shrink-0 border border-border" />
          ) : (
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground text-[9px] flex items-center justify-center font-bold flex-shrink-0">
              {(item.ownerName || 'P').charAt(0).toUpperCase()}
            </div>
          )}
          <span className="text-[11px] font-semibold truncate flex-1">{item.ownerName || 'Pengguna'}</span>
          <CheckCircle className="w-3.5 h-3.5 text-primary flex-shrink-0" />
          <span className="text-[9px] text-emerald-600 font-medium flex-shrink-0">● Tersedia</span>
        </div>
      </div>
    </div>
  );
}

export default function Rekomendasi() {
  const navigate = useNavigate();
  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getItems({ limit: 6 }).then(res => {
      setItems(res.items);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  return (
    <div className="px-4 py-4">
      <div className="flex items-center justify-between mb-4">
        <p className="font-bold text-[15px] text-foreground">Rekomendasi untukmu</p>
        <button className="text-xs text-primary font-semibold">Lihat Semua</button>
      </div>
      {loading ? (
        <div className="grid grid-cols-2 gap-3">
          {[0, 1].map(i => (
            <div key={i} className="rounded-2xl overflow-hidden border border-border bg-card">
              <Skeleton className="w-full h-36" />
              <div className="p-3 space-y-2">
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="h-3 w-1/2" />
              </div>
            </div>
          ))}
        </div>
      ) : items.length === 0 ? (
        <p className="text-sm text-muted-foreground text-center py-8">Belum ada barang tersedia</p>
      ) : (
        <div className="grid grid-cols-2 gap-3">
          {items.map((item) => (
            <ItemCard key={item.id} item={item} onClick={() => navigate(`/item/${item.id}`)} />
          ))}
        </div>
      )}
    </div>
  );
}
