  "src/components/barter/ReviewModal.tsx": "import { useState } from 'react';
import { X, Star, Loader2, MessageSquare } from 'lucide-react';

const ASPECTS = [
  { value: 'barang_sesuai' as const, label: '✅ Barang Sesuai Deskripsi', positive: true },
  { value: 'komunikasi_baik' as const, label: '💬 Komunikasi Baik', positive: true },
  { value: 'tepat_waktu' as const, label: '⏰ Tepat Waktu COD', positive: true },
  { value: 'ramah' as const, label: '🤝 Ramah & Sopan', positive: true },
  { value: 'tidak_sesuai' as const, label: '⚠️ Barang Tidak Sesuai', positive: false },
  { value: 'tidak_responsif' as const, label: '😶 Tidak Responsif', positive: false },
];

type AspectValue = typeof ASPECTS[number]['value'];

interface Props {
  partnerName: string;
  onClose: () => void;
  onSubmit: (rating: number, comment: string, aspect: AspectValue) => Promise<void>;
}

export default function ReviewModal({ partnerName, onClose, onSubmit }: Props) {
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [comment, setComment] = useState('');
  const [aspect, setAspect] = useState<AspectValue | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!rating || !comment.trim() || !aspect) return;
    setSubmitting(true);
    await onSubmit(rating, comment.trim(), aspect);
    setSubmitting(false);
  };

  const displayRating = hoverRating || rating;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end justify-center">
      <div className="max-w-[420px] w-full bg-card rounded-t-2xl p-5 animate-in slide-in-from-bottom duration-300 max-h-[85vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-bold text-base flex items-center gap-2">
            <MessageSquare className="w-5 h-5 text-primary" /> Beri Rating & Review
          </h3>
          <button onClick={onClose} className="p-1 rounded-lg hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        <p className="text-xs text-muted-foreground mb-4">
          Berikan penilaian jujur untuk <span className="font-semibold text-foreground">{partnerName}</span>. Review ini menjaga reputasi komunitas Mutari.
        </p>

        {/* Star Rating */}
        <div className="text-center mb-5">
          <p className="text-sm font-medium mb-2">Rating keseluruhan</p>
          <div className="flex items-center justify-center gap-1.5">
            {[1, 2, 3, 4, 5].map(star => (
              <button
                key={star}
                onMouseEnter={() => setHoverRating(star)}
                onMouseLeave={() => setHoverRating(0)}
                onClick={() => setRating(star)}
                className="p-0.5 transition-transform hover:scale-110 active:scale-95"
              >
                <Star
                  className={`w-9 h-9 transition-colors ${
                    star <= displayRating
                      ? 'text-yellow-400 fill-yellow-400'
                      : 'text-border'
                  }`}
                />
              </button>
            ))}
          </div>
          {displayRating > 0 && (
            <p className="text-xs text-muted-foreground mt-1">
              {displayRating === 1 ? 'Sangat Buruk' : displayRating === 2 ? 'Kurang' : displayRating === 3 ? 'Cukup' : displayRating === 4 ? 'Baik' : 'Sangat Baik'}
            </p>
          )}
        </div>

        {/* Aspect chips */}
        <p className="text-sm font-medium mb-2">Apa yang paling menonjol?</p>
        <div className="flex flex-wrap gap-2 mb-4">
          {ASPECTS.map(a => (
            <button
              key={a.value}
              onClick={() => setAspect(a.value)}
              className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all active:scale-95 ${
                aspect === a.value
                  ? a.positive
                    ? 'bg-primary/10 border-primary text-primary'
                    : 'bg-destructive/10 border-destructive text-destructive'
                  : 'border-border text-muted-foreground hover:bg-muted/50'
              }`}
            >
              {a.label}
            </button>
          ))}
        </div>

        {/* Comment */}
        <p className="text-sm font-medium mb-2">Komentar</p>
        <textarea
          value={comment}
          onChange={e => setComment(e.target.value)}
          placeholder="Ceritakan pengalamanmu barter dengan orang ini..."
          maxLength={500}
          className="w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm resize-none h-24 focus:outline-none focus:ring-1 focus:ring-primary"
        />
        <p className="text-[10px] text-muted-foreground text-right mt-1">{comment.length}/500</p>

        {/* Warning */}
        <div className="bg-accent/50 rounded-xl p-3 mt-2 border border-primary/10">
          <p className="text-[11px] text-foreground font-medium">⚖️ Review yang adil dan jujur</p>
          <p className="text-[11px] text-muted-foreground mt-1">
            Review Anda bersifat permanen dan memengaruhi reputasi pengguna. Berikan penilaian berdasarkan pengalaman nyata. +10 poin untuk setiap review.
          </p>
        </div>

        <button
          onClick={handleSubmit}
          disabled={!rating || !comment.trim() || !aspect || submitting}
          className="w-full mt-4 py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
        >
          {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
          {submitting ? 'Mengirim...' : `Kirim Review ${rating > 0 ? '⭐'.repeat(rating) : ''}`}
        </button>
      </div>
    </div>
  );
}
