  "src/context/UnreadContext.tsx": "import { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { getUnreadCounts } from 'zitejs/api';

type UnreadState = {
  unreadChats: number;
  unreadNotifications: number;
  refresh: () => void;
};

const UnreadContext = createContext<UnreadState>({
  unreadChats: 0,
  unreadNotifications: 0,
  refresh: () => {},
});

export function useUnread() {
  return useContext(UnreadContext);
}

// Request permission for browser notifications
function requestNotificationPermission() {
  if ('Notification' in window && Notification.permission === 'default') {
    Notification.requestPermission();
  }
}

function showBrowserNotification(title: string, body: string) {
  if ('Notification' in window && Notification.permission === 'granted') {
    try {
      new Notification(title, {
        body,
        icon: 'https://images.fillout.com/orgid-793308/flowpublicid-exc3bfzedf/widgetid-default/72HsAJL5x3Bc2QsVEVCZ5d/pasted-image-1786853332904-12t9kw3e.png',
        badge: 'https://images.fillout.com/orgid-793308/flowpublicid-exc3bfzedf/widgetid-default/72HsAJL5x3Bc2QsVEVCZ5d/pasted-image-1786853332904-12t9kw3e.png',
        tag: 'mutari-notification',
      });
    } catch {
      // Fallback — some mobile browsers don't support new Notification()
    }
  }
}

export function UnreadProvider({ children }: { children: React.ReactNode }) {
  const [unreadChats, setUnreadChats] = useState(0);
  const [unreadNotifications, setUnreadNotifications] = useState(0);
  const lastNotifIdRef = useRef<string | null>(null);
  const hasMountedRef = useRef(false);

  const refresh = useCallback(async () => {
    try {
      const res = await getUnreadCounts({});
      setUnreadChats(res.unreadChats);
      setUnreadNotifications(res.unreadNotifications);

      // Show browser notification for new notifications
      if (res.latestNotification && hasMountedRef.current) {
        if (lastNotifIdRef.current && res.latestNotification.id !== lastNotifIdRef.current) {
          showBrowserNotification(
            res.latestNotification.title,
            res.latestNotification.body,
          );
        }
      }
      if (res.latestNotification) {
        lastNotifIdRef.current = res.latestNotification.id;
      }
      hasMountedRef.current = true;
    } catch {
      // silently fail
    }
  }, []);

  useEffect(() => {
    requestNotificationPermission();
    refresh();
    const interval = setInterval(refresh, 15_000); // poll every 15s
    return () => clearInterval(interval);
  }, [refresh]);

  // Also refresh when tab becomes visible
  useEffect(() => {
    const handler = () => {
      if (document.visibilityState === 'visible') refresh();
    };
    document.addEventListener('visibilitychange', handler);
    return () => document.removeEventListener('visibilitychange', handler);
  }, [refresh]);

  return (
    <UnreadContext.Provider value={{ unreadChats, unreadNotifications, refresh }}>
      {children}
    </UnreadContext.Provider>
  );
}
