      )}
      {showReport && (
        <ReportModal
          onClose={() => setShowReport(false)}
          reportedUserId={barter.myRole === 'initiator' ? barter.partner.id : barter.initiator.id}
          reportedUserName={otherName}
          barterId={id}
        />
      )}
    </div>
  );
}

function ExpiryBanner({ expiresAt }: { expiresAt: string }) {
  const [timeLeft, setTimeLeft] = useState('');

  useEffect(() => {
    const update = () => {
      const diff = new Date(expiresAt).getTime() - Date.now();
      if (diff <= 0) {
        setTimeLeft('Kedaluwarsa');
        return;
      }
      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      if (hours >= 24) {
        const days = Math.floor(hours / 24);
        setTimeLeft(`${days} hari ${hours % 24} jam`);
      } else {
        setTimeLeft(`${hours} jam ${minutes} menit`);
      }
    };
    update();
    const iv = setInterval(update, 60000);
    return () => clearInterval(iv);
  }, [expiresAt]);

  const isUrgent = new Date(expiresAt).getTime() - Date.now() < 24 * 60 * 60 * 1000;

  return (
    <div className={`px-4 py-2 border-b flex items-center gap-2 ${
      isUrgent
        ? 'bg-red-50 dark:bg-red-950/20 border-red-200 dark:border-red-800'
        : 'bg-yellow-50 dark:bg-yellow-950/20 border-yellow-200 dark:border-yellow-800'
    }`}>
      <Clock className={`w-4 h-4 flex-shrink-0 ${isUrgent ? 'text-red-600' : 'text-yellow-600'}`} />
      <p className={`text-xs font-medium ${isUrgent ? 'text-red-700 dark:text-red-400' : 'text-yellow-700 dark:text-yellow-400'}`}>
        Batas waktu respon: <span className="font-bold">{timeLeft}</span>
      </p>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, { bg: string; text: string }> = {
    Menunggu: { bg: 'bg-yellow-100 dark:bg-yellow-900/30', text: 'text-yellow-700 dark:text-yellow-400' },
    Diterima: { bg: 'bg-blue-100 dark:bg-blue-900/30', text: 'text-blue-700 dark:text-blue-400' },
    Selesai: { bg: 'bg-green-100 dark:bg-green-900/30', text: 'text-green-700 dark:text-green-400' },
    Dibatalkan: { bg: 'bg-red-100 dark:bg-red-900/30', text: 'text-red-700 dark:text-red-400' },
  };
  const s = map[status] || map.Menunggu;
  return (
    <span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold ${s.bg} ${s.text}`}>
      {status}
    </span>
  );
}
