  "src/pages/EditProfilePage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Camera, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { useProfile } from '../hooks/useProfile';
import { updateProfile } from 'zitejs/api';
import { useUpload } from 'zitejs/upload';
import { useAuth } from 'zitejs/auth';
import { Skeleton } from '@project/components/ui/skeleton';

export default function EditProfilePage() {
  const navigate = useNavigate();
  const { profile, loading } = useProfile();
  const { user } = useAuth();
  const { upload, isUploading } = useUpload();

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [phone, setPhone] = useState('');
  const [bio, setBio] = useState('');
  const [method, setMethod] = useState('COD');
  const [saving, setSaving] = useState(false);
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);

  useEffect(() => {
    if (profile) {
      setFirstName(profile.firstName);
      setLastName(profile.lastName);
      setDisplayName(profile.displayName);
      setPhone(profile.phone);
      setBio(profile.bio);
      setMethod(profile.preferredBarterMethod || 'COD');
      setAvatarUrl(profile.image || user?.image || null);
    }
  }, [profile, user]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile({ firstName, lastName, displayName, phone, bio, preferredBarterMethod: method, image: avatarUrl || undefined });
      toast.success('Profil berhasil diperbarui');
      navigate(-1);
    } catch {
      toast.error('Gagal menyimpan profil');
    }
    setSaving(false);
  };

  const handleAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const { url } = await upload(file);
      setAvatarUrl(url);
      toast.success('Foto profil diperbarui');
    } catch {
      toast.error('Gagal upload foto');
    }
  };

  const initials = ((firstName?.[0] || '') + (lastName?.[0] || '') || 'U').toUpperCase();

  const METHODS = ['COD', 'Kirim', 'Keduanya'];

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-[420px] mx-auto">
          <div className="bg-primary px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white">Edit Profil</h1>
          </div>
          <div className="p-4 space-y-4">
            {[0,1,2,3,4].map(i => <Skeleton key={i} className="h-12 w-full rounded-xl" />)}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">Edit Profil</h1>
          </div>
        </div>

        {/* Avatar */}
        <div className="flex justify-center py-6">
          <div className="relative">
            {avatarUrl ? (
              <img src={avatarUrl} alt="" className="w-24 h-24 rounded-full object-cover border-4 border-primary/20" />
            ) : (
              <div className="w-24 h-24 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-3xl font-bold border-4 border-primary/20">
                {initials}
              </div>
            )}
            <label className="absolute bottom-0 right-0 w-8 h-8 rounded-full bg-primary text-primary-foreground flex items-center justify-center cursor-pointer shadow-md">
              {isUploading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Camera className="w-4 h-4" />}
              <input type="file" accept="image/*" className="hidden" onChange={handleAvatar} disabled={isUploading} />
            </label>
          </div>
        </div>

        {/* Form */}
        <div className="px-4 space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-semibold text-muted-foreground mb-1 block">Nama Depan</label>
              <input className="form-input" value={firstName} onChange={e => setFirstName(e.target.value)} placeholder="Nama depan" />
            </div>
            <div>
              <label className="text-xs font-semibold text-muted-foreground mb-1 block">Nama Belakang</label>
              <input className="form-input" value={lastName} onChange={e => setLastName(e.target.value)} placeholder="Nama belakang" />
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Nama Tampilan</label>
            <input className="form-input" value={displayName} onChange={e => setDisplayName(e.target.value)} placeholder="Nama yang terlihat oleh pengguna lain" />
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Email</label>
            <input className="form-input bg-muted text-muted-foreground cursor-not-allowed" value={profile?.email || ''} disabled />
            <p className="text-[10px] text-muted-foreground mt-1">Email tidak dapat diubah</p>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Nomor Telepon</label>
            <input className="form-input" value={phone} onChange={e => setPhone(e.target.value)} placeholder="+62 812 xxxx xxxx" type="tel" />
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1 block">Bio</label>
            <textarea className="form-input min-h-[80px] resize-none" value={bio} onChange={e => setBio(e.target.value)} placeholder="Ceritakan sedikit tentang kamu…" maxLength={200} />
            <p className="text-[10px] text-muted-foreground text-right mt-0.5">{bio.length}/200</p>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Metode Barter Favorit</label>
            <div className="flex gap-2">
              {METHODS.map(m => (
                <button
                  key={m}
                  onClick={() => setMethod(m)}
                  className={`flex-1 py-2.5 rounded-xl text-xs font-semibold border transition-colors ${
                    method === m ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border'
                  }`}
                >
                  {m}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Save */}
        <div className="px-4 mt-8">
          <button
            onClick={handleSave}
            disabled={saving}
            className="w-full py-3.5 rounded-2xl bg-primary text-primary-foreground font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            Simpan Perubahan
          </button>
        </div>
      </div>
    </div>
  );
}
