  "src/pages/Notifications.tsx": "import { useState, useEffect } from 'react';
import { ArrowLeft, Bell, Package, MessageCircle, Heart, CheckCircle, Trophy, Sparkles, Wallet } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { getNotifications, GetNotificationsOutputType, markNotificationRead } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { toast } from 'sonner';
import BottomNav from '../components/BottomNav';
import { useUnread } from '../context/UnreadContext';

type NotifType = GetNotificationsOutputType['notifications'][0];

const ICON_MAP: Record<string, { icon: typeof Bell; color: string }> = {
  barter: { icon: Package, color: 'bg-primary/10 text-primary' },
  like: { icon: Heart, color: 'bg-pink-50 text-pink-500' },
  chat: { icon: MessageCircle, color: 'bg-blue-50 text-blue-500' },
  badge: { icon: Trophy, color: 'bg-amber-50 text-amber-500' },
  milestone: { icon: Sparkles, color: 'bg-violet-50 text-violet-500' },
  system: { icon: Bell, color: 'bg-muted text-muted-foreground' },
};

function timeAgo(iso: string) {
  if (!iso) return '';
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'Baru saja';
  if (mins < 60) return `${mins} menit lalu`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} jam lalu`;
  const days = Math.floor(hours / 24);
  if (days === 1) return 'Kemarin';
  return `${days} hari lalu`;
}

export default function Notifications() {
  const navigate = useNavigate();
  const { refresh: refreshUnread } = useUnread();
  const [notifications, setNotifications] = useState<NotifType[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getNotifications({ limit: 50 })
      .then(res => {
        setNotifications(res.notifications);
        setUnreadCount(res.unreadCount);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const handleMarkAllRead = async () => {
    try {
      await markNotificationRead({ markAll: true });
      setNotifications(prev => prev.map(n => ({ ...n, read: true })));
      setUnreadCount(0);
      refreshUnread();
      toast.success('Semua notifikasi ditandai dibaca');
    } catch { /* ignore */ }
  };

  const handleTap = async (n: NotifType) => {
    if (!n.read) {
      markNotificationRead({ notificationId: n.id }).catch(() => {});
      setNotifications(prev => prev.map(x => x.id === n.id ? { ...x, read: true } : x));
      setUnreadCount(c => Math.max(0, c - 1));
      refreshUnread();
    }
    if (n.linkPath) navigate(n.linkPath);
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background px-4 py-3 flex items-center gap-3 border-b border-border">
          <button onClick={() => navigate(-1)} className="p-1">
            <ArrowLeft className="w-5 h-5 text-foreground" />
          </button>
          <h1 className="font-bold text-base flex-1">
            Notifikasi
            {unreadCount > 0 && (
              <span className="ml-2 text-xs font-bold bg-primary text-primary-foreground px-2 py-0.5 rounded-full">{unreadCount}</span>
            )}
          </h1>
          {unreadCount > 0 && (
            <button onClick={handleMarkAllRead} className="text-xs text-primary font-semibold">Tandai dibaca</button>
          )}
        </div>

        {/* List */}
        {loading ? (
          <div className="divide-y divide-border">
            {[0, 1, 2, 3].map(i => (
              <div key={i} className="px-4 py-3.5 flex gap-3">
                <Skeleton className="w-10 h-10 rounded-full flex-shrink-0" />
                <div className="flex-1 space-y-2">
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-full" />
                  <Skeleton className="h-2.5 w-20" />
                </div>
              </div>
            ))}
          </div>
        ) : notifications.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 px-4 text-center">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mb-4">
              <Bell className="w-8 h-8 text-muted-foreground" />
            </div>
            <p className="font-semibold text-base">Belum Ada Notifikasi</p>
            <p className="text-sm text-muted-foreground mt-1">Notifikasi badge, barter, dan aktivitas lainnya akan muncul di sini.</p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {notifications.map((n) => {
              const config = ICON_MAP[n.type] || ICON_MAP.system;
              const Icon = config.icon;
              return (
                <button
                  key={n.id}
                  onClick={() => handleTap(n)}
                  className={`w-full px-4 py-3.5 flex gap-3 text-left transition-colors hover:bg-muted/50 ${!n.read ? 'bg-primary/[0.03]' : ''}`}
                >
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${config.color}`}>
                    <Icon className="w-5 h-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <p className={`text-sm truncate ${!n.read ? 'font-bold' : 'font-semibold'}`}>{n.title}</p>
                      {!n.read && <div className="w-2 h-2 rounded-full bg-primary flex-shrink-0" />}
                    </div>
                    <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{n.body}</p>
                    <p className="text-[10px] text-muted-foreground mt-1">{timeAgo(n.createdAt)}</p>
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}
