  "src/pages/SearchPage.tsx": "import { useState, useEffect, useCallback } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Search, ArrowLeft, X, Clock, MapPin, Eye, Heart, SlidersHorizontal, Monitor, Shirt, Armchair, Dumbbell, Palette, Layers } from 'lucide-react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { useDebouncedCallback } from 'use-debounce';
import BottomNav from '../components/BottomNav';

type ItemType = GetItemsOutputType['items'][0];

const CATEGORY_ICONS: Record<string, React.ElementType> = {
  Elektronik: Monitor,
  Fashion: Shirt,
  'Rumah Tangga': Armchair,
  Olahraga: Dumbbell,
  Hobi: Palette,
};

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: ItemType): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

function ResultCard({ item, onClick }: { item: ItemType; onClick: () => void }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  return (
    <div onClick={onClick} className="rounded-2xl overflow-hidden border border-border bg-card cursor-pointer shadow-sm">
      <div className="relative">
        <img src={imgUrl} alt={item.title} className="w-full h-32 object-cover" />
