  "src/pages/WishlistPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Heart, Trash2, MapPin, Loader2 } from 'lucide-react';
import { getWishlist, toggleWishlist, GetWishlistOutputType } from 'zitejs/api';
import { toast } from 'sonner';
import { Skeleton } from '@project/components/ui/skeleton';
import BottomNav from '../components/BottomNav';

type WishlistItem = GetWishlistOutputType['items'][0];

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/aYmFPbU63ZSYCP5WK76Yni/img_5j_3U1FxA70D24aF.jpg';

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: WishlistItem): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

export default function WishlistPage() {
  const navigate = useNavigate();
  const [items, setItems] = useState<WishlistItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [removing, setRemoving] = useState<string | null>(null);

  useEffect(() => {
    getWishlist({}).then(res => {
      setItems(res.items);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const handleRemove = async (item: WishlistItem) => {
    setRemoving(item.wishlistId);
    try {
      await toggleWishlist({ itemId: item.itemId });
      setItems(prev => prev.filter(i => i.wishlistId !== item.wishlistId));
      toast.success('Dihapus dari wishlist');
    } catch {
      toast.error('Gagal menghapus');
    }
    setRemoving(null);
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1">
              <ArrowLeft className="w-5 h-5 text-white" />
            </button>
            <h1 className="font-bold text-base text-white flex-1">Wishlist</h1>
            {!loading && (
              <span className="text-white/70 text-xs">{items.length} barang</span>
            )}
          </div>
        </div>

        {loading ? (
          <div className="px-4 mt-4 space-y-3">
            {[0, 1, 2].map(i => (
              <div key={i} className="rounded-2xl border border-border bg-card p-3 flex gap-3">
                <Skeleton className="w-[90px] h-[80px] rounded-xl flex-shrink-0" />
                <div className="flex-1 space-y-2 py-1">
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-1/2" />
                  <Skeleton className="h-3 w-1/3" />
                </div>
              </div>
            ))}
          </div>
        ) : items.length === 0 ? (
          <div className="px-4 mt-16 text-center">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
              <Heart className="w-8 h-8 text-muted-foreground" />
            </div>
            <p className="font-semibold text-sm">Wishlist masih kosong</p>
            <p className="text-xs text-muted-foreground mt-1">Simpan barang yang kamu suka dari halaman detail barang</p>
            <button
              onClick={() => navigate('/')}
              className="mt-4 px-6 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold"
            >
              Jelajahi Barang
            </button>
          </div>
        ) : (
          <div className="px-4 mt-4 space-y-3">
            {items.map(item => (
              <div
                key={item.wishlistId}
                className="rounded-2xl border border-border bg-card p-3 flex gap-3 shadow-sm"
              >
                <img
                  src={item.photo || PLACEHOLDER_IMG}
                  alt={item.title}
                  className="w-[90px] h-[80px] rounded-xl object-cover flex-shrink-0 cursor-pointer"
                  onClick={() => navigate(`/item/${item.itemId}`)}
                />
                <div className="flex-1 min-w-0 flex flex-col justify-between">
                  <div>
                    <p
                      className="text-sm font-bold truncate cursor-pointer hover:text-primary transition-colors"
                      onClick={() => navigate(`/item/${item.itemId}`)}
                    >
                      {item.title}
                    </p>
                    <p className="text-xs text-primary font-semibold mt-0.5">{priceRange(item)}</p>
                    {item.location && (
                      <p className="text-[10px] text-muted-foreground flex items-center gap-0.5 mt-1">
                        <MapPin className="w-3 h-3 flex-shrink-0" /> {item.location}
                      </p>
                    )}
                  </div>
                  <div className="flex items-center justify-between mt-1.5">
                    <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full ${
                      item.status === 'Tersedia' ? 'bg-emerald-100 text-emerald-700' :
                      item.status === 'Sudah Ditukar' ? 'bg-red-100 text-red-600' :
                      'bg-amber-100 text-amber-700'
                    }`}>
                      {item.status}
                    </span>
                    <button
                      onClick={() => handleRemove(item)}
                      disabled={removing === item.wishlistId}
                      className="p-1.5 rounded-lg hover:bg-destructive/10 text-muted-foreground hover:text-destructive transition-colors"
                    >
                      {removing === item.wishlistId ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                      ) : (
                        <Trash2 className="w-4 h-4" />
                      )}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}
