    "src/api/changePassword.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Change the MUTARI password for the signed-in user',
  authenticated: true,
  inputSchema: z.object({
    currentPassword: z.string().min(1),
    newPassword: z.string().min(6),
    otpCode: z.string().optional(), // OTP will be activated later
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    const profile = await zite.userProfiles.findOne({ filters: { user: userId } });
    if (!profile) throw new ZiteError('Profil tidak ditemukan');

    // Verify current password
    if (profile.mutariPassword !== input.currentPassword) {
      throw new ZiteError('Password lama tidak sesuai');
    }

    if (input.newPassword === input.currentPassword) {
      throw new ZiteError('Password baru harus berbeda dari password lama');
    }

    // TODO: OTP verification will be activated at end of project
    // if (input.otpCode) { verify OTP code here }

    await zite.userProfiles.update({
      id: profile.id,
      record: { mutariPassword: input.newPassword },
    });

    return { success: true };
  },
});
