    "src/api/checkItemBarter.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Check if an item has an active barter negotiation for the current user',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    activeBarter: z.object({
      barterId: z.string(),
      status: z.string(),
      role: z.enum(['initiator', 'partner']),
      otherItemTitle: z.string(),
      otherItemPhoto: z.string().nullable(),
      otherUserName: z.string(),
      createdAt: z.string().nullable(),
    }).nullable(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Find any active barter where this item is either the offered or requested item
    // and the current user is involved
    const { rows } = await zite.sql({
      query: `
        SELECT bh."id", bh."status", bh."initiator", bh."partner",
               bh."offeredItem", bh."requestedItem", bh."createdAt"
        FROM "Barter History" bh
        WHERE bh."status" IN ('Menunggu', 'Diterima')
          AND (bh."requestedItem" @> to_jsonb(ARRAY[$1]) OR bh."offeredItem" @> to_jsonb(ARRAY[$1]))
          AND (bh."initiator" @> to_jsonb(ARRAY[$2]) OR bh."partner" @> to_jsonb(ARRAY[$2]))
        ORDER BY bh."createdAt" DESC
        LIMIT 1
      `,
      params: [input.itemId, userId],
    });

    if (rows.length === 0) {
      return { activeBarter: null };
    }

    const barter = rows[0];
    const barterId = barter.id as string;
    const status = barter.status as string;
    const initiatorIds = barter.initiator as string[];
    const partnerIds = barter.partner as string[];
    const offeredItemIds = barter.offeredItem as string[];
    const requestedItemIds = barter.requestedItem as string[];

    const isInitiator = initiatorIds?.includes(userId);
    const role = isInitiator ? 'initiator' : 'partner';

    // The "other item" is the item that's NOT the one we're looking at
    const otherItemId = offeredItemIds?.includes(input.itemId)
      ? requestedItemIds?.[0]
      : offeredItemIds?.[0];

    // The "other user" is the one the current user is trading with
    const otherUserId = isInitiator ? partnerIds?.[0] : initiatorIds?.[0];

    let otherItemTitle = 'Barang';
    let otherItemPhoto: string | null = null;
    let otherUserName = 'Pengguna';

    if (otherItemId) {
      const otherItem = await zite.items.findOne({ id: otherItemId });
      if (otherItem) {
        otherItemTitle = otherItem.title || 'Barang';
        const photos = otherItem.photos as Array<{ url: string }> | null;
        otherItemPhoto = photos?.[0]?.url ?? null;
      }
    }

    if (otherUserId) {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: otherUserId },
        limit: 1,
      });
      if (users[0]) {
        otherUserName = users[0].name || users[0].firstName || users[0].email?.split('@')[0] || 'Pengguna';
      }
    }

    return {
      activeBarter: {
        barterId,
        status,
        role: role as 'initiator' | 'partner',
        otherItemTitle,
        otherItemPhoto,
        otherUserName,
        createdAt: (barter.createdAt as string) || null,
      },
    };
  },
});
