    "src/api/confirmBarterComplete.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Confirm barter completion — both parties must confirm for it to be final',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    confirmed: z.boolean(),
    bothConfirmed: z.boolean(),
    pointsEarned: z.number(),
  }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    if (barter.status !== 'Diterima') {
      throw new ZiteError('Barter belum diterima');
    }

    const isInitiator = context.user.id === initiatorId;
    const updateField = isInitiator ? 'initiatorConfirmed' : 'partnerConfirmed';
    const alreadyConfirmed = isInitiator ? barter.initiatorConfirmed : barter.partnerConfirmed;

    if (alreadyConfirmed) {
      throw new ZiteError('Anda sudah mengonfirmasi');
    }

    await zite.barterHistory.update({ id: input.barterId, record: { [updateField]: true } });

    // Check if both confirmed
    const otherConfirmed = isInitiator ? barter.partnerConfirmed : barter.initiatorConfirmed;
    const bothConfirmed = otherConfirmed === true;

    let pointsEarned = 0;

    if (bothConfirmed && !barter.pointsAwarded) {
      // Both confirmed! Complete the barter
      pointsEarned = 50;

      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          status: 'Selesai',
          completedAt: new Date().toISOString(),
          pointsAwarded: true,
        },
      });

      // Mark items as traded
      const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
      const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
      if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Sudah Ditukar' } });
      if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Sudah Ditukar' } });

      // Award points to both users
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        const existing = await zite.userPoints.findOne({ filters: { user: userId } });
        if (existing) {
          await zite.userPoints.update({
            id: existing.id,
            record: {
              totalPoints: (existing.totalPoints ?? 0) + pointsEarned,
              bartersCompleted: (existing.bartersCompleted ?? 0) + 1,
            },
          });
        }
        await zite.pointHistory.create({
          record: {
            activity: 'Barter Selesai',
            user: userId,
            points: pointsEarned,
            activityType: 'barter_complete',
          },
        });
      }

      // === REFERRAL BONUS: check if either user was referred ===
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        // Find pending referral where this user is the referred person
        const { records: pendingRefs } = await zite.referrals.findAll({
          filters: { referredUser: userId, status: 'Pending' },
          limit: 1,
        });
        if (pendingRefs.length === 0) continue;

        const ref = pendingRefs[0];
        const referrerId = Array.isArray(ref.referrer) ? ref.referrer[0] : ref.referrer;
        if (!referrerId) continue;

        // This is the referred user's first completed barter → award 50 MP to referrer
        const referralBonus = 50;
        await zite.referrals.update({
          id: ref.id,
          record: { status: 'Completed', bonusPoints: referralBonus },
        });

        // Add points to referrer
        const referrerPoints = await zite.userPoints.findOne({ filters: { user: referrerId } });
        if (referrerPoints) {
          await zite.userPoints.update({
            id: referrerPoints.id,
            record: { totalPoints: (referrerPoints.totalPoints ?? 0) + referralBonus },
          });
        }
        await zite.pointHistory.create({
          record: {
            activity: 'Bonus Ajak Teman',
            user: referrerId,
            points: referralBonus,
            activityType: 'referral_bonus',
          },
        });

        // Notify referrer
        await zite.notifications.create({
          record: {
            title: 'Bonus Referral! 🎁',
            body: `Teman yang kamu ajak berhasil menyelesaikan barter pertama! Kamu dapat +${referralBonus} MP.`,
            type: 'Milestone',
            recipient: referrerId,
            read: false,
            linkPath: '/referral',
          },
        });
      }

      // System message
      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `🎉 Barter berhasil diselesaikan! Kedua pihak mendapat +${pointsEarned} poin.`,
          type: 'System',
        },
      });

      // Notify both
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        await zite.notifications.create({
          record: {
            title: 'Barter Selesai! 🎉',
            body: `Selamat! Barter berhasil. Anda mendapat +${pointsEarned} poin.`,
            type: 'Barter',
            recipient: userId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    } else {
      // Notify the other party
      const recipientId = isInitiator ? partnerId : initiatorId;
      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `✅ ${`${context.user.firstName || context.user.email.split("@")[0]}`} telah mengonfirmasi barter selesai. Menunggu konfirmasi pihak lain.`,
          type: 'System',
        },
      });
      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: 'Konfirmasi Barter',
            body: `${`${context.user.firstName || context.user.email.split("@")[0]}`} sudah konfirmasi barter selesai. Giliran Anda!`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    }

    return { confirmed: true, bothConfirmed, pointsEarned };
  },
});
