    "src/api/createBarterOffer.ts": "import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Creates a barter offer — user picks their item to trade for a target item',
  authenticated: true,
  inputSchema: z.object({
    targetItemId: z.string(),
    offeredItemId: z.string(),
    message: z.string().optional(),
  }),
  outputSchema: z.object({
    barterId: z.string(),
  }),
  execute: async ({ input, context }) => {
    // Validate target item exists
    const targetItem = await zite.items.findOne({ id: input.targetItemId });
    if (!targetItem) throw new ZiteError('Barang target tidak ditemukan');

    // Can't barter with yourself
    const ownerIds = Array.isArray(targetItem.owner) ? targetItem.owner : [targetItem.owner];
    if (ownerIds.includes(context.user.id)) {
      throw new ZiteError('Tidak bisa barter dengan barang sendiri');
    }

    // Validate offered item belongs to current user
    const offeredItem = await zite.items.findOne({ id: input.offeredItemId });
    if (!offeredItem) throw new ZiteError('Barang yang ditawarkan tidak ditemukan');
    const offeredOwnerIds = Array.isArray(offeredItem.owner) ? offeredItem.owner : [offeredItem.owner];
    if (!offeredOwnerIds.includes(context.user.id)) {
      throw new ZiteError('Barang ini bukan milik Anda');
    }

    // Create barter history record
    const barter = await zite.barterHistory.create({
      record: {
        title: `${offeredItem.title || 'Barang'} ↔ ${targetItem.title || 'Barang'}`,
        initiator: context.user.id,
        partner: ownerIds[0] || null,
        offeredItem: input.offeredItemId,
        requestedItem: input.targetItemId,
        status: 'Menunggu',
        notes: input.message || null,
        completedAt: null,
        codAddress: null,
        codDetail: null,
        initiatorConfirmed: false,
        partnerConfirmed: false,
        pointsAwarded: false,
        expiresAt: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
      },
    });

    // Send initial system message
    await zite.barterMessages.create({
      record: {
        barter: barter.id,
        sender: context.user.id,
        content: input.message || `Halo! Saya ingin menukar "${offeredItem.title}" dengan "${targetItem.title}" milik Anda.`,
        type: 'Text',
      },
    });

    // Update item statuses
    await zite.items.update({ id: input.targetItemId, record: { status: 'Negosiasi' } });
    await zite.items.update({ id: input.offeredItemId, record: { status: 'Negosiasi' } });

    // Notify the owner
    await zite.notifications.create({
      record: {
        title: 'Penawaran Barter Baru!',
        body: `${`${context.user.firstName || context.user.email.split("@")[0]}`} ingin menukar "${offeredItem.title}" dengan "${targetItem.title}" Anda`,
        type: 'Barter',
        recipient: ownerIds[0] || null,
        read: false,
        linkPath: `/barter/${barter.id}`,
      },
    });

    return { barterId: barter.id };
  },
});
