    "src/api/getBarterHistory.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get barter history for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    history: z.array(z.object({
      id: z.string(),
      title: z.string(),
      partnerName: z.string(),
      offeredItemTitle: z.string(),
      offeredItemPhoto: z.string().nullable(),
      requestedItemTitle: z.string(),
      requestedItemPhoto: z.string().nullable(),
      status: z.string(),
      notes: z.string(),
      createdAt: z.string(),
      completedAt: z.string().nullable(),
      isInitiator: z.boolean(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Find barters where user is initiator or partner
    const [asInitiator, asPartner] = await Promise.all([
      zite.barterHistory.findAll({ filters: { initiator: userId }, limit: 100 }),
      zite.barterHistory.findAll({ filters: { partner: userId }, limit: 100 }),
    ]);

    const all = [
      ...asInitiator.records.map(r => ({ ...r, isInitiator: true })),
      ...asPartner.records.map(r => ({ ...r, isInitiator: false })),
    ];

    // Sort by createdAt desc
    all.sort((a, b) => new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime());

    // Fetch related data
    const history = await Promise.all(
      all.map(async (barter) => {
        const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
        const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;

        const [offered, requested] = await Promise.all([
          offeredId ? zite.items.findOne({ id: offeredId }) : null,
          requestedId ? zite.items.findOne({ id: requestedId }) : null,
        ]);

        // Get partner name
        const partnerId = barter.isInitiator
          ? (Array.isArray(barter.partner) ? barter.partner[0] : barter.partner)
          : (Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator);

        let partnerName = 'Pengguna';
        if (partnerId) {
          const { records: users } = await zite.auth.findAllUsers({
            filters: { id: partnerId },
            limit: 1,
          });
          if (users.length > 0) partnerName = users[0].name || users[0].email;
        }

        return {
          id: barter.id,
          title: barter.title || 'Barter',
          partnerName,
          offeredItemTitle: offered?.title || 'Barang',
          offeredItemPhoto: offered?.photos?.[0]?.url || null,
          requestedItemTitle: requested?.title || 'Barang',
          requestedItemPhoto: requested?.photos?.[0]?.url || null,
          status: barter.status || 'pending',
          notes: barter.notes || '',
          createdAt: barter.createdAt || '',
          completedAt: barter.completedAt || null,
          isInitiator: barter.isInitiator,
        };
      })
    );

    return { history };
  },
});
