    "src/api/getComments.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get public comments for an item',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    comments: z.array(z.object({
      id: z.string(),
      content: z.string(),
      authorName: z.string(),
      authorImage: z.string().nullable(),
      authorId: z.string(),
      createdAt: z.string(),
    })),
  }),
  execute: async ({ input }) => {
    const { records } = await zite.comments.findAll({
      filters: { item: input.itemId },
      limit: 100,
    });

    // Get unique author IDs
    const authorIds = [...new Set(records.map(r => {
      const a = r.author;
      return Array.isArray(a) ? a[0] : a;
    }).filter(Boolean))] as string[];

    const userMap: Record<string, { name: string; image: string | null }> = {};
    if (authorIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: { in: authorIds } },
        limit: 100,
      });
      for (const u of users) {
        userMap[u.id] = { name: u.name || u.firstName || u.email, image: u.image ?? null };
      }
    }

    // Sort by createdAt descending (newest first)
    const sorted = records.sort((a, b) => {
      const da = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const db = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return db - da;
    });

    const comments = sorted.map(r => {
      const authorId = Array.isArray(r.author) ? r.author[0] : r.author;
      const user = authorId ? userMap[authorId] : undefined;
      return {
        id: r.id,
        content: r.content || '',
        authorName: user?.name || 'Anonim',
        authorImage: user?.image ?? null,
        authorId: authorId || '',
        createdAt: r.createdAt || new Date().toISOString(),
      };
    });

    return { comments };
  },
});
",
    "src/api/getDirectMessages.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get direct messages for a conversation between two users about an item',
  authenticated: true,
  inputSchema: z.object({
    otherUserId: z.string(),
    itemId: z.string(),
  }),
  outputSchema: z.object({
    messages: z.array(z.object({
      id: z.string(),
      content: z.string(),
      senderId: z.string(),
      type: z.string(),
      sentAt: z.string().nullable(),
    })),
    otherUser: z.object({
      id: z.string(),
      name: z.string(),
      image: z.string().nullable(),
      isOnline: z.boolean(),
      lastSeen: z.string().nullable(),
    }),
    conversationId: z.string(),
    item: z.object({
      id: z.string(),
      title: z.string(),
      image: z.string().nullable(),
      condition: z.string(),
    }).nullable(),
  }),
  execute: async ({ input, context }) => {
    const ids = [context.user.id, input.otherUserId].sort();
    const conversationId = `${ids[0]}_${ids[1]}_${input.itemId}`;

    const { rows } = await zite.sql({
      query: `SELECT "id", "content", "senderId", "type", "sentAt"
              FROM "DirectMessages"
              WHERE "conversationId" = $1
              ORDER BY "sentAt" ASC
              LIMIT 500`,
      params: [conversationId],
    });

    // Get other user info
    const users = await zite.auth.findAllUsers({ limit: 1, filters: { id: input.otherUserId } });
    const otherUser = users.records[0];

    // Get presence
    const presence = await zite.userPresence.findOne({ filters: { userId: input.otherUserId } });
    const isOnline = presence?.isOnline === true &&
      presence?.lastSeen ? (Date.now() - new Date(presence.lastSeen).getTime() < 5 * 60 * 1000) : false;

    // Get item info
    const itemRecord = await zite.items.findOne({ id: input.itemId });
    const itemInfo = itemRecord ? {
      id: itemRecord.id,
      title: itemRecord.title || '',
      image: itemRecord.photos?.[0]?.url ?? null,
      condition: itemRecord.condition || '',
    } : null;

    // Update my own presence
    await zite.userPresence.bulkCreate({
      records: [{ userId: context.user.id, lastSeen: new Date().toISOString(), isOnline: true, typingIn: null }],
      matchOn: ['userId'],
    });

    // Mark chat notifications for this conversation as read
    const linkPrefix = `/direct-chat?userId=${input.otherUserId}&itemId=${input.itemId}`;
    const { rows: unreadNotifs } = await zite.sql({
      query: `SELECT "id" FROM "Notifications"
              WHERE "type" = 'Chat' AND "read" = false
              AND "recipient" @> to_jsonb(ARRAY[$1])
              AND "linkPath" LIKE $2
              LIMIT 50`,
      params: [context.user.id, `${linkPrefix}%`],
    });
    for (const n of unreadNotifs) {
      await zite.notifications.update({ id: n.id as string, record: { read: true } });
    }

    return {
      messages: rows.map((r: any) => ({
        id: r.id as string,
        content: (r.content as string) || '',
        senderId: (r.senderId as string) || '',
        type: (r.type as string) || 'Text',
        sentAt: (r.sentAt as string) ?? null,
      })),
      otherUser: {
        id: input.otherUserId,
        name: otherUser?.name || 'Pengguna',
        image: otherUser?.image ?? null,
        isOnline,
        lastSeen: presence?.lastSeen ?? null,
      },
      conversationId,
      item: itemInfo,
    };
  },
});
",
    "src/api/getItem.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch a single item by ID and increment its view count',
  authenticated: true,
  inputSchema: z.object({
    id: z.string(),
  }),
  outputSchema: z.object({
    item: z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      photos: z.array(z.object({ url: z.string(), filename: z.string().optional() })),
      condition: z.string(),
      completeness: z.string(),
      defects: z.string(),
      specifications: z.string(),
      estimatedValueMin: z.number().nullable(),
      estimatedValueMax: z.number().nullable(),
      desiredItems: z.string(),
      additionalWants: z.string(),
      barterReason: z.string(),
      barterMethod: z.array(z.string()),
      location: z.string(),
      status: z.string(),
      viewsCount: z.number(),
      likesCount: z.number(),
      liked: z.boolean(),
      createdAt: z.string().nullable(),
      ownerName: z.string(),
      ownerImage: z.string().nullable(),
      ownerPoints: z.number(),
      ownerBarterCount: z.number(),
      ownerMemberSince: z.string(),
      ownerId: z.string(),
    }).nullable(),
  }),
  execute: async ({ input, context }) => {
    const record = await zite.items.findOne({ id: input.id });
    if (!record) return { item: null };

    // Increment views
    const newViews = (record.viewsCount ?? 0) + 1;
    await zite.items.update({ id: input.id, record: { viewsCount: newViews } });

    // Get owner info
    let ownerName = 'Pemilik';
    let ownerImage: string | null = null;
    let ownerPoints = 0;
    let ownerBarterCount = 0;
    let ownerMemberSince = '2024';

    let ownerId = '';

    if (record.owner) {
      ownerId = Array.isArray(record.owner) ? record.owner[0] : record.owner;
      if (ownerId) {
        const { records: users } = await zite.auth.findAllUsers({
          filters: { id: ownerId },
          limit: 1,
        });
        if (users.length > 0) {
          ownerName = users[0].name || users[0].firstName || users[0].email;
          ownerImage = users[0].image ?? null;
          const created = (users[0] as any).createdAt;
          if (created) {
            ownerMemberSince = new Date(created).getFullYear().toString();
          }
        }

        // Get owner points
        const ownerPts = await zite.userPoints.findOne({ filters: { user: ownerId } });
        if (ownerPts) {
          ownerPoints = ownerPts.totalPoints ?? 0;
          ownerBarterCount = ownerPts.bartersCompleted ?? 0;
        }
      }
    }

    // Check if current user liked this item
    const likeRecord = await zite.itemLikes.findOne({
      filters: { user: context.user.id, item: input.id },
    });
    const liked = !!likeRecord;

    return {
      item: {
        id: record.id,
        title: record.title || '',
        description: record.description || '',
        photos: record.photos?.map(p => ({ url: p.url, filename: p.filename })) || [],
        condition: record.condition || '',
        completeness: record.completeness || '',
        defects: record.defects || '',
        specifications: record.specifications || '',
        estimatedValueMin: record.estimatedValueMin ?? null,
        estimatedValueMax: record.estimatedValueMax ?? null,
        desiredItems: record.desiredItems || '',
        additionalWants: record.additionalWants || '',
        barterReason: record.barterReason || '',
        barterMethod: Array.isArray(record.barterMethod) ? record.barterMethod : record.barterMethod ? [record.barterMethod] : [],
        location: record.location || '',
        status: record.status || '',
        viewsCount: newViews,
        likesCount: record.likesCount ?? 0,
        liked,
        createdAt: record.createdAt ?? null,
        ownerName,
        ownerImage,
        ownerPoints,
        ownerBarterCount,
        ownerMemberSince,
        ownerId,
      },
    };
  },
});
",
    "src/api/getItems.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch available barter items with optional search and category filter',
  inputSchema: z.object({
    limit: z.number().optional(),
    search: z.string().optional(),
    categoryId: z.string().optional(),
  }),
  outputSchema: z.object({
    items: z.array(z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      photos: z.array(z.object({ url: z.string(), filename: z.string().optional() })).optional(),
      condition: z.string(),
      estimatedValueMin: z.number().nullable(),
      estimatedValueMax: z.number().nullable(),
      location: z.string(),
      status: z.string(),
      viewsCount: z.number(),
      likesCount: z.number(),
      commentsCount: z.number(),
      createdAt: z.string().nullable(),
      category: z.array(z.string()).nullable(),
      ownerName: z.string(),
      ownerImage: z.string().nullable(),
    })),
  }),
  execute: async ({ input }) => {
    const limit = input.limit || 20;

    // Get all users for owner lookup
    const allUsers = await zite.auth.findAllUsers({ limit: 200 });
    const userMap = new Map(allUsers.records.map(u => [u.id, u]));

    // Helper to get comment counts for a list of item IDs
    async function getCommentCounts(itemIds: string[]): Promise<Record<string, number>> {
      if (itemIds.length === 0) return {};
      const result = await zite.sql({
        query: `SELECT ci."itemsId" as "itemId", COUNT(*) as "cnt" FROM "CommentsItems" ci WHERE ci."itemsId" = ANY($1) GROUP BY ci."itemsId"`,
        params: [itemIds],
      });
      const map: Record<string, number> = {};
      for (const row of result.rows) {
        map[row.itemId as string] = Number(row.cnt ?? 0);
      }
      return map;
    }

    if (input.search || input.categoryId) {
      let query = `SELECT "Items".* FROM "Items"`;
      const params: unknown[] = [];
      let paramIdx = 1;

      if (input.categoryId) {
        query += ` JOIN "CategoriesItems" ON "CategoriesItems"."itemsId" = "Items"."id" AND "CategoriesItems"."categoriesId" = $${paramIdx}`;
        params.push(input.categoryId);
        paramIdx++;
      }

      query += ` WHERE "Items"."status" = 'Tersedia'`;

      if (input.search) {
        query += ` AND (LOWER("Items"."title") LIKE $${paramIdx} OR LOWER("Items"."description") LIKE $${paramIdx})`;
        params.push(`%${input.search.toLowerCase()}%`);
        paramIdx++;
      }

      query += ` ORDER BY "Items"."createdAt" DESC NULLS LAST LIMIT $${paramIdx}`;
      params.push(limit);

      const result = await zite.sql({ query, params });
      const ids = result.rows.map(r => String(r.id || ''));
      const commentCounts = await getCommentCounts(ids);

      return {
        items: result.rows.map((r: Record<string, unknown>) => {
          const ownerIds = Array.isArray(r.owner) ? r.owner as string[] : r.owner ? [r.owner as string] : [];
          const owner = ownerIds[0] ? userMap.get(ownerIds[0]) : null;
          const rid = String(r.id || '');
          return {
            id: rid,
            title: String(r.title || ''),
            description: String(r.description || ''),
            photos: r.photos as { url: string; filename?: string }[] | undefined,
            condition: String(r.condition || ''),
            estimatedValueMin: (r.estimatedValueMin as number) ?? null,
            estimatedValueMax: (r.estimatedValueMax as number) ?? null,
            location: String(r.location || ''),
            status: String(r.status || ''),
            viewsCount: (r.viewsCount as number) ?? 0,
            likesCount: (r.likesCount as number) ?? 0,
            commentsCount: commentCounts[rid] ?? 0,
            createdAt: r.createdAt as string ?? null,
            category: r.category as string[] ?? null,
            ownerName: owner?.name || 'Pengguna',
            ownerImage: owner?.image ?? null,
          };
        }),
      };
    }

    const { records } = await zite.items.findAll({
      filters: { status: 'Tersedia' },
      limit,
    });

    const ids = records.map(r => r.id);
    const commentCounts = await getCommentCounts(ids);

    return {
      items: records.map(r => {
        const ownerIds = Array.isArray(r.owner) ? r.owner : r.owner ? [r.owner] : [];
        const owner = ownerIds[0] ? userMap.get(ownerIds[0]) : null;
        return {
          id: r.id,
          title: r.title || '',
          description: r.description || '',
          photos: r.photos?.map(p => ({ url: p.url, filename: p.filename })),
          condition: r.condition || '',
          estimatedValueMin: r.estimatedValueMin ?? null,
          estimatedValueMax: r.estimatedValueMax ?? null,
          location: r.location || '',
          status: r.status || '',
          viewsCount: r.viewsCount ?? 0,
          likesCount: r.likesCount ?? 0,
          commentsCount: commentCounts[r.id] ?? 0,
          createdAt: r.createdAt ?? null,
          category: r.category ? (Array.isArray(r.category) ? r.category : [r.category]) : null,
          ownerName: owner?.name || 'Pengguna',
          ownerImage: owner?.image ?? null,
        };
      }),
    };
  },
});
",
