    "src/api/getNotifications.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get in-app notifications for the current user',
  authenticated: true,
  inputSchema: z.object({
    limit: z.number().optional(),
    unreadOnly: z.boolean().optional(),
  }),
  outputSchema: z.object({
    notifications: z.array(z.object({
      id: z.string(),
      title: z.string(),
      body: z.string(),
      type: z.string(),
      read: z.boolean(),
      linkPath: z.string().nullable(),
      createdAt: z.string(),
    })),
    unreadCount: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const filters: Record<string, unknown> = { recipient: userId };
    if (input.unreadOnly) {
      filters.read = false;
    }

    const { records } = await zite.notifications.findAll({
      filters,
      limit: input.limit || 50,
    });

    // Sort by createdAt desc
    const sorted = records.sort((a, b) =>
      new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime()
    );

    // Count unread
    const unreadCount = input.unreadOnly
      ? sorted.length
      : records.filter(n => !n.read).length;

    return {
      notifications: sorted.map(n => ({
        id: n.id,
        title: n.title || '',
        body: n.body || '',
        type: n.type || 'system',
        read: !!n.read,
        linkPath: n.linkPath || null,
        createdAt: n.createdAt || '',
      })),
      unreadCount,
    };
  },
});
