    "src/api/getUserStats.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Gets detailed barter statistics for the signed-in user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    bartersByMonth: z.array(z.object({ month: z.string(), count: z.number() })),
    topCategories: z.array(z.object({ category: z.string(), count: z.number() })),
    responseRate: z.number(),
    avgCompletionDays: z.number(),
    totalViews: z.number(),
    totalLikes: z.number(),
    totalBarters: z.number(),
    totalItems: z.number(),
    completionRate: z.number(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Barters per month (last 6 months)
    const bartersByMonth = await zite.sql({
      query: `
        SELECT to_char(b.created_at, 'YYYY-MM') AS month, COUNT(*) AS count
        FROM "BarterHistory" b
        WHERE (b."initiator"->>0 = $1 OR b."partner"->>0 = $1)
          AND b.created_at >= now() - interval '6 months'
        GROUP BY 1 ORDER BY 1 ASC
      `,
      params: [userId],
    });

    // Top categories from user's items
    const topCats = await zite.sql({
      query: `
        SELECT c."name" AS category, COUNT(*) AS count
        FROM "Items" i
        JOIN "CategoriesItems" ci ON ci."itemsId" = i.id
        JOIN "Categories" c ON c.id = ci."categoriesId"
        WHERE i."owner"->>0 = $1
        GROUP BY c."name"
        ORDER BY count DESC
        LIMIT 5
      `,
      params: [userId],
    });

    // Total stats
    const stats = await zite.sql({
      query: `
        SELECT
          COALESCE(SUM("viewsCount"), 0) AS "totalViews",
          COALESCE(SUM("likesCount"), 0) AS "totalLikes",
          COUNT(*) AS "totalItems"
        FROM "Items"
        WHERE "owner"->>0 = $1
      `,
      params: [userId],
    });

    // Barter completion stats
    const barterStats = await zite.sql({
      query: `
        SELECT
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE "status" = 'Selesai') AS completed,
          AVG(EXTRACT(EPOCH FROM ("completedAt"::timestamptz - created_at)) / 86400)
            FILTER (WHERE "status" = 'Selesai' AND "completedAt" IS NOT NULL) AS "avgDays"
        FROM "BarterHistory"
        WHERE "initiator"->>0 = $1 OR "partner"->>0 = $1
      `,
      params: [userId],
    });

    // Response rate: barters responded to / total received
    const responseStats = await zite.sql({
      query: `
        SELECT
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE "status" != 'Menunggu') AS responded
        FROM "BarterHistory"
        WHERE "partner"->>0 = $1
      `,
      params: [userId],
    });

    const totalBarters = Number(barterStats.rows[0]?.total ?? 0);
    const completedBarters = Number(barterStats.rows[0]?.completed ?? 0);
    const totalReceived = Number(responseStats.rows[0]?.total ?? 0);
    const respondedCount = Number(responseStats.rows[0]?.responded ?? 0);

    return {
      bartersByMonth: bartersByMonth.rows.map(r => ({
        month: String(r.month),
        count: Number(r.count),
      })),
      topCategories: topCats.rows.map(r => ({
        category: String(r.category),
        count: Number(r.count),
      })),
      responseRate: totalReceived > 0 ? Math.round((respondedCount / totalReceived) * 100) : 100,
      avgCompletionDays: Number(barterStats.rows[0]?.avgDays ?? 0),
      totalViews: Number(stats.rows[0]?.totalViews ?? 0),
      totalLikes: Number(stats.rows[0]?.totalLikes ?? 0),
      totalBarters,
      totalItems: Number(stats.rows[0]?.totalItems ?? 0),
      completionRate: totalBarters > 0 ? Math.round((completedBarters / totalBarters) * 100) : 0,
    };
  },
});
",
    "src/api/getViolations.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get violation history and minus points summary for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalMinusPoints: z.number(),
    activeViolations: z.number(),
    violations: z.array(z.object({
      id: z.string(),
      label: z.string(),
      violationType: z.string(),
      severity: z.string(),
      minusPoints: z.number(),
      status: z.string(),
      notes: z.string(),
      createdAt: z.string(),
    })),
    bySeverity: z.object({
      berat: z.number(),
      sedang: z.number(),
      ringan: z.number(),
    }),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    const { records } = await zite.violations.findAll({
      filters: { user: userId },
      limit: 100,
    });

    // Sort by date desc
    const sorted = records.sort(
      (a, b) => new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime()
    );

    const active = sorted.filter(v => v.status === 'Aktif' || v.status === 'Sudah Diperingatkan');
    const totalMinus = active.reduce((sum, v) => sum + (v.minusPoints ?? 0), 0);

    const bySeverity = { berat: 0, sedang: 0, ringan: 0 };
    active.forEach(v => {
      const sev = (v.severity || '').toLowerCase();
      if (sev === 'berat') bySeverity.berat++;
      else if (sev === 'sedang') bySeverity.sedang++;
      else if (sev === 'ringan') bySeverity.ringan++;
    });

    return {
      totalMinusPoints: totalMinus,
      activeViolations: active.length,
      violations: sorted.map(v => ({
        id: v.id,
        label: v.label || '',
        violationType: v.violationType || '',
        severity: (v.severity || 'Ringan').toLowerCase(),
        minusPoints: v.minusPoints ?? 0,
        status: v.status || 'active',
        notes: v.notes || '',
        createdAt: v.createdAt || '',
      })),
      bySeverity,
    };
  },
});
