    "src/api/sendDirectMessage.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Send a direct message to another user about an item',
  authenticated: true,
  inputSchema: z.object({
    receiverId: z.string(),
    itemId: z.string(),
    content: z.string().min(1),
    type: z.enum(['Text', 'Photo']).default('Text'),
  }),
  outputSchema: z.object({
    messageId: z.string(),
    conversationId: z.string(),
  }),
  execute: async ({ input, context }) => {
    // Build a deterministic conversationId from the two user ids + item
    const ids = [context.user.id, input.receiverId].sort();
    const conversationId = `${ids[0]}_${ids[1]}_${input.itemId}`;

    const msg = await zite.directMessages.create({
      record: {
        content: input.content,
        senderId: context.user.id,
        receiverId: input.receiverId,
        itemId: input.itemId,
        conversationId,
        type: input.type,
      },
    });

    // Update sender presence
    await zite.userPresence.bulkCreate({
      records: [{ userId: context.user.id, lastSeen: new Date().toISOString(), isOnline: true, typingIn: null }],
      matchOn: ['userId'],
    });

    // Notify receiver
    const { records: senderUsers } = await zite.auth.findAllUsers({ filters: { id: context.user.id }, limit: 1 });
    const senderName = senderUsers[0]?.name || senderUsers[0]?.firstName || senderUsers[0]?.email?.split('@')[0] || 'Seseorang';
    const item = await zite.items.findOne({ id: input.itemId });
    const itemTitle = item?.title || 'Barang';
    const preview = input.type === 'Photo' ? '📷 Foto' : (input.content.length > 60 ? input.content.slice(0, 60) + '…' : input.content);

    await zite.notifications.create({
      record: {
        title: `💬 Pesan dari ${senderName}`,
        body: `[${itemTitle}] ${preview}`,
        type: 'Chat',
        recipient: input.receiverId,
        read: false,
        linkPath: `/direct-chat?userId=${context.user.id}&itemId=${input.itemId}&itemTitle=${encodeURIComponent(itemTitle)}`,
      },
    });

    return { messageId: msg.id, conversationId };
  },
});
