    "src/api/updatePresence.ts": "import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Update user typing status and online presence',
  authenticated: true,
  inputSchema: z.object({
    conversationId: z.string().optional(),
    isTyping: z.boolean().default(false),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    otherTyping: z.boolean(),
    otherOnline: z.boolean(),
    otherLastSeen: z.string().nullable(),
  }),
  execute: async ({ input, context }) => {
    // Update my presence
    await zite.userPresence.bulkCreate({
      records: [{
        userId: context.user.id,
        lastSeen: new Date().toISOString(),
        isOnline: true,
        typingIn: input.isTyping && input.conversationId ? input.conversationId : null,
      }],
      matchOn: ['userId'],
    });

    // If we have a conversationId, check the other user's status
    let otherTyping = false;
    let otherOnline = false;
    let otherLastSeen: string | null = null;

    if (input.conversationId) {
      // Extract other user id from conversationId format: id1_id2_itemId
      const parts = input.conversationId.split('_');
      const otherUserId = parts[0] === context.user.id ? parts[1] : parts[0];

      if (otherUserId) {
        const presence = await zite.userPresence.findOne({ filters: { userId: otherUserId } });
        if (presence) {
          const timeDiff = presence.lastSeen ? Date.now() - new Date(presence.lastSeen).getTime() : Infinity;
          otherOnline = presence.isOnline === true && timeDiff < 5 * 60 * 1000;
          otherLastSeen = presence.lastSeen ?? null;
          otherTyping = presence.typingIn === input.conversationId && timeDiff < 10000;
        }
      }
    }

    return { success: true, otherTyping, otherOnline, otherLastSeen };
  },
});
