    "src/components/barter/BarterItemCard.tsx": "interface Props {
  title: string;
  photo: string | null;
  condition: string;
  label: string;
  valueMin: number | null;
  valueMax: number | null;
}

export default function BarterItemCard({ title, photo, condition, label, valueMin, valueMax }: Props) {
  const fmt = (v: number) => 'Rp' + v.toLocaleString('id-ID');
  const price = valueMin && valueMax && valueMin !== valueMax
    ? `${fmt(valueMin)} – ${fmt(valueMax)}`
    : valueMin ? fmt(valueMin) : valueMax ? fmt(valueMax) : '';

  return (
    <div className="flex-1 min-w-0">
      <p className="text-[10px] text-muted-foreground font-medium mb-1 text-center">{label}</p>
      <div className="rounded-xl border border-border bg-card overflow-hidden">
        <div className="aspect-square w-full bg-muted">
          {photo ? (
            <img src={photo} alt={title} className="w-full h-full object-cover" />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-muted-foreground text-xs">No foto</div>
          )}
        </div>
        <div className="p-2">
          <p className="text-xs font-semibold truncate">{title}</p>
          <p className="text-[10px] text-muted-foreground">{condition}</p>
          {price && <p className="text-[10px] text-primary font-medium mt-0.5">{price}</p>}
        </div>
      </div>
    </div>
  );
}
