    "src/components/barter/CodModal.tsx": "import { useState, useEffect, useRef, useCallback } from 'react';
import { X, MapPin, Loader2, Navigation, Target, ArrowRight } from 'lucide-react';

interface LatLng {
  lat: number;
  lng: number;
}

interface Props {
  currentAddress: string;
  currentDetail: string;
  locationA: LatLng | null;
  locationB: LatLng | null;
  labelA: string;
  labelB: string;
  onClose: () => void;
  onSubmit: (address: string, detail: string) => Promise<void>;
}

function haversineDistance(a: LatLng, b: LatLng): number {
  const R = 6371;
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const sinLat = Math.sin(dLat / 2);
  const sinLng = Math.sin(dLng / 2);
  const h = sinLat * sinLat + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * sinLng * sinLng;
  return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

function getMidpoint(a: LatLng, b: LatLng): LatLng {
  return { lat: (a.lat + b.lat) / 2, lng: (a.lng + b.lng) / 2 };
}

function formatDistance(km: number): string {
  if (km < 1) return `${Math.round(km * 1000)} m`;
  return `${km.toFixed(1)} km`;
}

export default function CodModal({ currentAddress, currentDetail, locationA, locationB, labelA, labelB, onClose, onSubmit }: Props) {
  const [address, setAddress] = useState(currentAddress);
  const [detail, setDetail] = useState(currentDetail);
  const [submitting, setSubmitting] = useState(false);
  const [mapLoading, setMapLoading] = useState(true);
  const [selectedPoint, setSelectedPoint] = useState<LatLng | null>(null);
  const [myLocation, setMyLocation] = useState<LatLng | null>(null);
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<google.maps.Map | null>(null);
  const markersRef = useRef<google.maps.Marker[]>([]);
  const midpointMarkerRef = useRef<google.maps.Marker | null>(null);
  const selectedMarkerRef = useRef<google.maps.Marker | null>(null);

  const hasBothLocations = locationA && locationB;
  const midpoint = hasBothLocations ? getMidpoint(locationA, locationB) : null;
  const totalDistance = hasBothLocations ? haversineDistance(locationA, locationB) : null;
  const distanceFromA = midpoint && locationA ? haversineDistance(locationA, midpoint) : null;
  const distanceFromB = midpoint && locationB ? haversineDistance(locationB, midpoint) : null;

  // Get user's current location
  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        pos => setMyLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => {}
      );
    }
  }, []);

  // Load Google Maps
  useEffect(() => {
    const loadMap = async () => {
      // Check if maps script already loaded
      if (!window.google?.maps) {
        // Load via script tag
        const existing = document.querySelector('script[src*="maps.googleapis.com"]');
        if (!existing) {
          // No API key - use Leaflet/OpenStreetMap fallback instead
          setMapLoading(false);
          return;
        }
      }
      initMap();
    };

    const initMap = () => {
      if (!mapRef.current || !window.google?.maps) return;

      const center = midpoint || myLocation || locationA || locationB || { lat: -6.2, lng: 106.8 };

      const map = new google.maps.Map(mapRef.current, {
        center,
        zoom: hasBothLocations ? 12 : 14,
        disableDefaultUI: true,
        zoomControl: true,
        styles: [
          { featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] },
        ],
      });
      mapInstanceRef.current = map;

      // Add location markers
      if (locationA) {
        const m = new google.maps.Marker({
          position: locationA,
          map,
          icon: { path: google.maps.SymbolPath.CIRCLE, scale: 8, fillColor: '#16a34a', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
          title: labelA,
        });
        markersRef.current.push(m);
      }
      if (locationB) {
        const m = new google.maps.Marker({
          position: locationB,
          map,
          icon: { path: google.maps.SymbolPath.CIRCLE, scale: 8, fillColor: '#2563eb', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
          title: labelB,
        });
        markersRef.current.push(m);
      }

      // Add midpoint marker
      if (midpoint) {
        const mid = new google.maps.Marker({
          position: midpoint,
          map,
          icon: { path: google.maps.SymbolPath.BACKWARD_CLOSED_ARROW, scale: 6, fillColor: '#f59e0b', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 2 },
          title: 'Titik Tengah',
        });
        midpointMarkerRef.current = mid;
      }

      // Fit bounds
      if (hasBothLocations) {
        const bounds = new google.maps.LatLngBounds();
        bounds.extend(locationA);
        bounds.extend(locationB);
        if (midpoint) bounds.extend(midpoint);
        map.fitBounds(bounds, 60);
      }

      // Click to select custom location
      map.addListener('click', (e: google.maps.MapMouseEvent) => {
        if (!e.latLng) return;
        const pos = { lat: e.latLng.lat(), lng: e.latLng.lng() };
        setSelectedPoint(pos);

        if (selectedMarkerRef.current) selectedMarkerRef.current.setMap(null);
        selectedMarkerRef.current = new google.maps.Marker({
          position: pos,
          map,
          icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#dc2626', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 3 },
          title: 'Lokasi COD',
          animation: google.maps.Animation.DROP,
        });
      });

      setMapLoading(false);
    };

    loadMap();

    return () => {
      markersRef.current.forEach(m => m.setMap(null));
      markersRef.current = [];
      midpointMarkerRef.current?.setMap(null);
      selectedMarkerRef.current?.setMap(null);
    };
  }, [midpoint, myLocation, locationA, locationB, hasBothLocations, labelA, labelB]);

  const useMidpoint = useCallback(() => {
    if (!midpoint) return;
    setSelectedPoint(midpoint);
    setAddress(`Titik tengah (${midpoint.lat.toFixed(4)}, ${midpoint.lng.toFixed(4)})`);

    if (mapInstanceRef.current) {
      mapInstanceRef.current.panTo(midpoint);
      mapInstanceRef.current.setZoom(15);
      if (selectedMarkerRef.current) selectedMarkerRef.current.setMap(null);
      selectedMarkerRef.current = new google.maps.Marker({
        position: midpoint,
        map: mapInstanceRef.current,
        icon: { path: google.maps.SymbolPath.CIRCLE, scale: 10, fillColor: '#dc2626', fillOpacity: 1, strokeColor: '#fff', strokeWeight: 3 },
        title: 'Lokasi COD',
        animation: google.maps.Animation.DROP,
      });
    }
  }, [midpoint]);

  const handleSubmit = async () => {
    if (!address.trim()) return;
    setSubmitting(true);
    await onSubmit(address.trim(), detail.trim());
    setSubmitting(false);
  };

  const hasGoogleMaps = typeof window !== 'undefined' && !!window.google?.maps;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end justify-center" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="max-w-[420px] w-full bg-card rounded-t-2xl animate-in slide-in-from-bottom duration-300 max-h-[92vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 pb-2">
          <h3 className="font-bold text-base flex items-center gap-2">
            <MapPin className="w-5 h-5 text-primary" /> Atur Lokasi COD
          </h3>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="overflow-y-auto flex-1 px-4 pb-4">
          {/* Midpoint recommendation */}
          {hasBothLocations && midpoint && (
            <div className="bg-gradient-to-r from-primary/5 via-primary/10 to-primary/5 rounded-xl p-3 mb-3 border border-primary/15">
              <div className="flex items-center gap-2 mb-2">
                <Target className="w-4 h-4 text-primary flex-shrink-0" />
                <p className="text-xs font-bold text-primary">Rekomendasi Titik Tengah</p>
              </div>
              <p className="text-[11px] text-muted-foreground mb-2.5">
                Jarak yang adil — kedua pihak menempuh jarak yang sama.
              </p>

              {/* Distance visualization */}
              <div className="flex items-center gap-2 mb-2.5">
                <div className="flex-1 text-center">
                  <div className="w-6 h-6 rounded-full bg-green-500/15 border-2 border-green-500 flex items-center justify-center mx-auto mb-1">
                    <span className="text-[8px] font-bold text-green-600">A</span>
                  </div>
                  <p className="text-[10px] font-medium text-foreground truncate">{labelA}</p>
                </div>
                <div className="flex-1 flex flex-col items-center">
                  <div className="flex items-center gap-1 w-full">
                    <div className="flex-1 h-px bg-green-400 border-dashed"></div>
                    <div className="w-5 h-5 rounded-full bg-amber-500 flex items-center justify-center shadow-sm">
                      <Target className="w-2.5 h-2.5 text-white" />
                    </div>
                    <div className="flex-1 h-px bg-blue-400 border-dashed"></div>
                  </div>
                  <p className="text-[9px] text-amber-600 font-bold mt-0.5">Titik Tengah</p>
                </div>
                <div className="flex-1 text-center">
                  <div className="w-6 h-6 rounded-full bg-blue-500/15 border-2 border-blue-500 flex items-center justify-center mx-auto mb-1">
                    <span className="text-[8px] font-bold text-blue-600">B</span>
                  </div>
                  <p className="text-[10px] font-medium text-foreground truncate">{labelB}</p>
                </div>
              </div>

              {/* Distance info */}
              <div className="flex gap-2 mb-2.5">
                <div className="flex-1 bg-card rounded-lg px-2 py-1.5 text-center border border-border">
