                  className="w-full h-full border-0"
                  loading="lazy"
                  onLoad={() => setMapLoading(false)}
                />
              ) : locationA ? (
                <iframe
                  title="Map"
                  src={`https://www.openstreetmap.org/export/embed.html?bbox=${locationA.lng - 0.02},${locationA.lat - 0.015},${locationA.lng + 0.02},${locationA.lat + 0.015}&layer=mapnik&marker=${locationA.lat},${locationA.lng}`}
                  className="w-full h-full border-0"
                  loading="lazy"
