          {/* Legend */}
          {hasBothLocations && (
            <div className="flex flex-wrap gap-3 mb-3 text-[10px]">
              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-green-500 inline-block" /> {labelA}</span>
              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-blue-500 inline-block" /> {labelB}</span>
              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded-full bg-amber-500 inline-block" /> Titik Tengah</span>
            </div>
          )}

          {/* Address input */}
          <div className="space-y-3">
            <div>
              <label className="text-sm font-medium">Alamat / Nama Tempat</label>
              <input
                type="text"
                value={address}
                onChange={e => setAddress(e.target.value)}
                placeholder="Contoh: Starbucks Mall Kelapa Gading"
                className="mt-1 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
              />
            </div>
            <div>
              <label className="text-sm font-medium">Detail Tambahan (opsional)</label>
              <input
                type="text"
                value={detail}
                onChange={e => setDetail(e.target.value)}
                placeholder="Contoh: Lantai 2, dekat eskalator"
                className="mt-1 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
              />
            </div>
          </div>

          {/* Tips */}
          <div className="bg-accent/50 rounded-xl p-3 mt-3 border border-primary/10">
            <p className="text-[11px] text-foreground font-medium">💡 Tips Keamanan COD</p>
            <ul className="text-[11px] text-muted-foreground mt-1 space-y-0.5">
              <li>• Pilih tempat umum yang ramai (mall, kafe, stasiun)</li>
              <li>• Bertemu di siang hari</li>
              <li>• Ajak teman/keluarga bila perlu</li>
            </ul>
          </div>
        </div>

        {/* Submit button */}
        <div className="p-4 pt-2 border-t border-border">
          <button
            onClick={handleSubmit}
            disabled={!address.trim() || submitting}
            className="w-full py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
          >
            {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <MapPin className="w-4 h-4" />}
            {submitting ? 'Menyimpan...' : 'Simpan Lokasi COD'}
          </button>
        </div>
      </div>
    </div>
  );
}
