    "src/components/upload/PhotoGrid.tsx": "import { useState, useRef, useCallback } from 'react';
import { ImagePlus, X, Loader2, Camera, Images } from 'lucide-react';
import Webcam from 'react-webcam';

interface Props {
  photos: { url: string }[];
  onAdd: (files: File[]) => void;
  onRemove: (index: number) => void;
  isUploading: boolean;
  lang?: 'id' | 'en';
}

export default function PhotoGrid({ photos, onAdd, onRemove, isUploading, lang = 'id' }: Props) {
  const [showPicker, setShowPicker] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const webcamRef = useRef<Webcam>(null);
  const remaining = 10 - photos.length;

  const handleGallery = () => {
    setShowPicker(false);
    fileRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const arr = Array.from(files).slice(0, remaining);
    onAdd(arr);
    e.target.value = '';
  };

  const capturePhoto = useCallback(() => {
    const screenshot = webcamRef.current?.getScreenshot();
    if (!screenshot) return;
    fetch(screenshot)
      .then(r => r.blob())
      .then(blob => {
        const file = new File([blob], `camera-${Date.now()}.jpg`, { type: 'image/jpeg' });
        onAdd([file]);
      });
  }, [onAdd]);

  const minLabel = lang === 'id' ? 'min. 3' : 'min. 3';
  const maxLabel = lang === 'id' ? 'maks. 10' : 'max. 10';

  return (
    <div>
      <p className="text-sm font-semibold text-foreground mb-1">
        {lang === 'id' ? 'Foto Barang' : 'Item Photos'} <span className="text-destructive">*</span>{' '}
        <span className="text-muted-foreground font-normal">({minLabel}, {maxLabel})</span>
      </p>
      {photos.length < 3 && photos.length > 0 && (
        <p className="text-xs text-destructive mb-2">
          {lang === 'id' ? `Tambahkan ${3 - photos.length} foto lagi (minimal 3)` : `Add ${3 - photos.length} more photo(s) (minimum 3)`}
        </p>
      )}

      <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1">
        {photos.map((p, i) => (
          <div key={i} className="relative w-24 h-24 rounded-xl overflow-hidden flex-shrink-0 border border-border">
            <img src={p.url} alt="" className="w-full h-full object-cover" />
            {i === 0 && (
              <span className="absolute bottom-0 left-0 right-0 bg-primary/80 text-primary-foreground text-[9px] font-bold text-center py-0.5">
                {lang === 'id' ? 'Utama' : 'Main'}
              </span>
            )}
            <button
              onClick={() => onRemove(i)}
              className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/60 flex items-center justify-center"
            >
              <X className="w-3 h-3 text-white" />
            </button>
          </div>
        ))}
        {remaining > 0 && (
          <button
            type="button"
            onClick={() => setShowPicker(true)}
            disabled={isUploading}
            className="w-24 h-24 rounded-xl border-2 border-dashed border-border flex flex-col items-center justify-center cursor-pointer flex-shrink-0 hover:bg-accent/50 transition-colors"
          >
            {isUploading ? (
              <Loader2 className="w-6 h-6 text-muted-foreground animate-spin" />
            ) : (
              <>
                <ImagePlus className="w-6 h-6 text-muted-foreground mb-1" />
                <span className="text-[11px] text-muted-foreground">
                  {photos.length}/{10}
                </span>
              </>
            )}
          </button>
        )}
      </div>

      {/* Hidden file input — accept all image types */}
      <input
        ref={fileRef}
        type="file"
        accept="image/*"
        multiple
        onChange={handleFileChange}
        className="hidden"
      />

      {/* Source picker bottom sheet */}
      {showPicker && (
        <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/40" onClick={() => setShowPicker(false)}>
          <div className="max-w-[420px] w-full bg-card rounded-t-2xl" onClick={e => e.stopPropagation()}>
            <div className="w-10 h-1 rounded-full bg-muted mx-auto mt-3" />
            <p className="text-sm font-bold text-center mt-3">
              {lang === 'id' ? 'Tambah Foto' : 'Add Photo'}
            </p>
            <div className="p-4 grid grid-cols-2 gap-3">
              <button
                onClick={() => { setShowPicker(false); setShowCamera(true); }}
                className="flex flex-col items-center gap-2 py-5 rounded-xl border border-border hover:bg-accent/50 transition-colors"
              >
                <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                  <Camera className="w-6 h-6 text-primary" />
                </div>
                <span className="text-sm font-semibold">{lang === 'id' ? 'Kamera' : 'Camera'}</span>
                <span className="text-[10px] text-muted-foreground">{lang === 'id' ? 'Ambil foto langsung' : 'Take a photo'}</span>
              </button>
              <button
                onClick={handleGallery}
                className="flex flex-col items-center gap-2 py-5 rounded-xl border border-border hover:bg-accent/50 transition-colors"
              >
                <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                  <Images className="w-6 h-6 text-primary" />
                </div>
                <span className="text-sm font-semibold">{lang === 'id' ? 'Galeri' : 'Gallery'}</span>
                <span className="text-[10px] text-muted-foreground">{lang === 'id' ? 'Pilih dari galeri' : 'Choose from gallery'}</span>
              </button>
            </div>
            <div className="px-4 pb-4">
              <button onClick={() => setShowPicker(false)} className="w-full py-3 rounded-xl border border-border text-sm font-semibold text-foreground">
                {lang === 'id' ? 'Batal' : 'Cancel'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Camera overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-50 bg-black flex flex-col">
          <div className="flex items-center justify-between px-4 py-3">
            <button onClick={() => setShowCamera(false)} className="text-white text-sm font-semibold">
              {lang === 'id' ? 'Tutup' : 'Close'}
            </button>
            <span className="text-white/60 text-xs">{photos.length}/10</span>
          </div>
          <div className="flex-1 flex items-center justify-center overflow-hidden">
            <Webcam
              ref={webcamRef}
              audio={false}
              screenshotFormat="image/jpeg"
              videoConstraints={{ facingMode: 'environment', width: 1280, height: 960 }}
              className="w-full h-full object-cover"
            />
          </div>
          <div className="flex items-center justify-center py-6 gap-6">
            <button
              onClick={() => {
                capturePhoto();
                if (photos.length + 1 >= 10) setShowCamera(false);
              }}
              className="w-16 h-16 rounded-full border-4 border-white flex items-center justify-center"
            >
              <div className="w-12 h-12 rounded-full bg-white" />
            </button>
          </div>
          <div className="px-4 pb-6">
            <button
              onClick={() => setShowCamera(false)}
              className="w-full py-3 rounded-xl bg-primary text-primary-foreground text-sm font-semibold"
            >
              {lang === 'id' ? 'Selesai' : 'Done'} ({photos.length} {lang === 'id' ? 'foto' : 'photos'})
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
