    "src/pages/BarterHistoryPage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, ArrowRightLeft, Clock, CheckCircle, XCircle, Loader2 } from 'lucide-react';
import { getBarterHistory, GetBarterHistoryOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { format } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import BottomNav from '../components/BottomNav';

type HistoryItem = GetBarterHistoryOutputType['history'][0];

const STATUS_MAP: Record<string, { label: string; color: string; icon: typeof CheckCircle }> = {
  pending: { label: 'Menunggu', color: 'bg-amber-100 text-amber-700', icon: Clock },
  accepted: { label: 'Diterima', color: 'bg-blue-100 text-blue-700', icon: ArrowRightLeft },
  completed: { label: 'Selesai', color: 'bg-emerald-100 text-emerald-700', icon: CheckCircle },
  cancelled: { label: 'Dibatalkan', color: 'bg-red-100 text-red-600', icon: XCircle },
};

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/aYmFPbU63ZSYCP5WK76Yni/img_5j_3U1FxA70D24aF.jpg';

function BarterCard({ item, onClick }: { item: HistoryItem; onClick: () => void }) {
  const status = STATUS_MAP[item.status] || STATUS_MAP.pending;
  const StatusIcon = status.icon;

  return (
    <div onClick={onClick} className="bg-card rounded-2xl border border-border p-4 cursor-pointer hover:shadow-md transition-shadow">
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full flex items-center gap-1 ${status.color}`}>
            <StatusIcon className="w-3 h-3" /> {status.label}
          </span>
          {item.isInitiator && (
            <span className="text-[9px] font-medium text-muted-foreground bg-muted px-1.5 py-0.5 rounded-full">
              Kamu yang memulai
            </span>
          )}
        </div>
        {item.createdAt && (
          <span className="text-[10px] text-muted-foreground">
            {format(new Date(item.createdAt), 'd MMM yyyy', { locale: idLocale })}
          </span>
        )}
      </div>

      {/* Barter items */}
      <div className="flex items-center gap-2">
        <div className="flex-1 flex items-center gap-2 min-w-0">
          <img
            src={item.offeredItemPhoto || PLACEHOLDER_IMG}
            alt=""
            className="w-12 h-12 rounded-lg object-cover flex-shrink-0"
          />
          <div className="min-w-0">
            <p className="text-[10px] text-muted-foreground">Ditawarkan</p>
            <p className="text-xs font-semibold truncate">{item.offeredItemTitle}</p>
          </div>
        </div>
        <div className="flex-shrink-0">
          <ArrowRightLeft className="w-4 h-4 text-primary" />
        </div>
        <div className="flex-1 flex items-center gap-2 min-w-0">
          <img
            src={item.requestedItemPhoto || PLACEHOLDER_IMG}
            alt=""
            className="w-12 h-12 rounded-lg object-cover flex-shrink-0"
          />
          <div className="min-w-0">
            <p className="text-[10px] text-muted-foreground">Diminta</p>
            <p className="text-xs font-semibold truncate">{item.requestedItemTitle}</p>
          </div>
        </div>
      </div>

      {/* Partner */}
      <div className="mt-3 pt-3 border-t border-border flex items-center justify-between">
        <p className="text-[11px] text-muted-foreground">
          Dengan <span className="font-semibold text-foreground">{item.partnerName}</span>
        </p>
        {item.completedAt && (
          <p className="text-[10px] text-emerald-600">
            Selesai {format(new Date(item.completedAt), 'd MMM', { locale: idLocale })}
          </p>
        )}
      </div>
    </div>
  );
}

export default function BarterHistoryPage() {
  const navigate = useNavigate();
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<string>('all');

  useEffect(() => {
    getBarterHistory({}).then(res => {
      setHistory(res.history);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const filtered = filter === 'all'
    ? history
    : history.filter(h => h.status === filter);

  const FILTERS = [
    { key: 'all', label: 'Semua' },
    { key: 'pending', label: 'Menunggu' },
    { key: 'accepted', label: 'Diterima' },
    { key: 'completed', label: 'Selesai' },
    { key: 'cancelled', label: 'Dibatalkan' },
  ];

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1">
              <ArrowLeft className="w-5 h-5 text-white" />
            </button>
            <h1 className="font-bold text-base text-white flex-1">Riwayat Barter</h1>
            {!loading && (
              <span className="text-white/70 text-xs">{history.length} transaksi</span>
            )}
          </div>
        </div>

        {/* Filters */}
        <div className="px-4 mt-3 overflow-x-auto no-scrollbar">
          <div className="flex gap-2">
            {FILTERS.map(f => (
              <button
                key={f.key}
                onClick={() => setFilter(f.key)}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold whitespace-nowrap transition-colors ${
                  filter === f.key
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-muted-foreground'
                }`}
              >
                {f.label}
              </button>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="px-4 mt-4 space-y-3">
            {[0, 1, 2].map(i => (
              <div key={i} className="rounded-2xl border border-border bg-card p-4">
                <Skeleton className="h-4 w-20 mb-3" />
                <div className="flex items-center gap-2">
                  <Skeleton className="w-12 h-12 rounded-lg" />
                  <Skeleton className="h-3 w-20" />
                  <Skeleton className="w-4 h-4 rounded" />
                  <Skeleton className="w-12 h-12 rounded-lg" />
                  <Skeleton className="h-3 w-20" />
                </div>
              </div>
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="px-4 mt-16 text-center">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
              <ArrowRightLeft className="w-8 h-8 text-muted-foreground" />
            </div>
            <p className="font-semibold text-sm">
              {filter === 'all' ? 'Belum ada riwayat barter' : `Tidak ada barter "${FILTERS.find(f => f.key === filter)?.label}"`}
            </p>
            <p className="text-xs text-muted-foreground mt-1">
              {filter === 'all'
                ? 'Mulai barter dengan pengguna lain dari halaman detail barang'
                : 'Coba filter lain untuk melihat riwayat barter'}
            </p>
            {filter === 'all' && (
              <button
                onClick={() => navigate('/')}
                className="mt-4 px-6 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold"
              >
                Jelajahi Barang
              </button>
            )}
          </div>
        ) : (
          <div className="px-4 mt-4 space-y-3">
            {filtered.map(item => (
              <BarterCard key={item.id} item={item} onClick={() => navigate(`/barter/${item.id}`)} />
            ))}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}
