  const { profile, loading } = useProfile();
  const { lang } = useI18n();
  const [values, setValues] = useState({ instagram: '', whatsapp: '', twitter: '' });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (profile) {
      setValues({
        instagram: (profile as any).instagram || '',
        whatsapp: (profile as any).whatsapp || '',
        twitter: (profile as any).twitter || '',
      });
    }
  }, [profile]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile(values);
      toast.success(lang === 'id' ? 'Akun terhubung disimpan!' : 'Linked accounts saved!');
    } catch {
      toast.error(lang === 'id' ? 'Gagal menyimpan' : 'Failed to save');
    }
    setSaving(false);
  };

  const linkedCount = Object.values(values).filter(v => v.trim()).length;

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">{lang === 'id' ? 'Akun Terhubung' : 'Linked Accounts'}</h1>
          </div>
        </div>

        {/* Trust indicator */}
        <div className="px-4 mt-4">
          <div className="bg-primary/5 border border-primary/20 rounded-2xl p-4 flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
              <Link2 className="w-5 h-5 text-primary" />
            </div>
            <div className="flex-1">
              <p className="text-sm font-bold">{lang === 'id' ? 'Tingkat Kepercayaan' : 'Trust Level'}</p>
              <p className="text-[10px] text-muted-foreground">
                {lang === 'id'
                  ? `${linkedCount}/3 akun terhubung · Semakin banyak akun, semakin dipercaya`
                  : `${linkedCount}/3 accounts linked · More accounts = more trust`}
              </p>
            </div>
            <div className="flex gap-0.5">
              {[0, 1, 2].map(i => (
                <div key={i} className={`w-3 h-3 rounded-full ${i < linkedCount ? 'bg-primary' : 'bg-muted'}`} />
              ))}
            </div>
          </div>
        </div>

        {/* Social accounts */}
        <div className="px-4 mt-4 space-y-3">
          {SOCIALS.map(({ key, label, Icon, placeholder, prefix, color }) => {
            const val = values[key];
            const isLinked = val.trim().length > 0;
            return (
              <div key={key} className="bg-card border border-border rounded-2xl p-4">
                <div className="flex items-center gap-3 mb-3">
                  <div className={`w-9 h-9 rounded-xl ${color} flex items-center justify-center flex-shrink-0`}>
                    <Icon className="w-4 h-4 text-white" />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-bold">{label}</p>
                    {isLinked && (
                      <p className="text-[10px] text-emerald-600 flex items-center gap-0.5">
                        <Check className="w-3 h-3" /> {lang === 'id' ? 'Terhubung' : 'Connected'}
                      </p>
                    )}
                  </div>
                  {isLinked && (
                    <button onClick={() => setValues(prev => ({ ...prev, [key]: '' }))} className="p-1.5 rounded-lg hover:bg-muted transition-colors">
                      <Trash2 className="w-4 h-4 text-muted-foreground" />
                    </button>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-muted-foreground flex-shrink-0">{prefix}</span>
                  <input
                    className="flex-1 bg-muted rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 ring-primary/30"
                    value={val}
                    onChange={e => setValues(prev => ({ ...prev, [key]: e.target.value }))}
                    placeholder={placeholder}
                  />
                </div>
                {isLinked && key !== 'whatsapp' && (
                  <a
                    href={`https://${prefix}${val.replace('@', '')}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="mt-2 text-[11px] text-primary font-medium flex items-center gap-1"
                  >
                    <ExternalLink className="w-3 h-3" /> {lang === 'id' ? 'Buka profil' : 'Open profile'}
                  </a>
                )}
                {isLinked && key === 'whatsapp' && (
                  <a
                    href={`https://wa.me/${val.replace(/[^0-9]/g, '')}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="mt-2 text-[11px] text-primary font-medium flex items-center gap-1"
                  >
                    <ExternalLink className="w-3 h-3" /> {lang === 'id' ? 'Buka chat' : 'Open chat'}
                  </a>
                )}
              </div>
            );
          })}
        </div>

        <div className="px-4 mt-6">
          <button onClick={handleSave} disabled={saving} className="w-full py-3.5 rounded-2xl bg-primary text-primary-foreground font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-50">
            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
            {lang === 'id' ? 'Simpan' : 'Save'}
          </button>
        </div>

        <div className="px-4 mt-4">
          <div className="bg-muted/50 rounded-xl p-3">
            <p className="text-[10px] text-muted-foreground text-center leading-relaxed">
              {lang === 'id'
                ? 'Akun sosmed yang terhubung akan ditampilkan di profil publik kamu untuk meningkatkan kepercayaan pengguna lain saat barter.'
                : 'Linked social accounts will be shown on your public profile to increase trust with other users during barter.'}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
