    "src/pages/MyPublicProfilePage.tsx": "import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Star, Package, ShieldCheck, MapPin, Eye, Edit } from 'lucide-react';
import { useAuth } from 'zitejs/auth';
import { getPublicProfile, GetPublicProfileOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import BadgeChip from '../components/BadgeChip';
import { useI18n } from '../context/I18nContext';

type ProfileData = GetPublicProfileOutputType;

function ItemCard({ item, onTap }: { item: ProfileData['items'][0]; onTap: () => void }) {
  return (
    <button onClick={onTap} className="bg-card border border-border rounded-xl overflow-hidden text-left">
      {item.photo ? (
        <img src={item.photo} alt={item.title} className="w-full aspect-square object-cover" />
      ) : (
        <div className="w-full aspect-square bg-muted flex items-center justify-center">
          <Package className="w-8 h-8 text-muted-foreground" />
        </div>
      )}
      <div className="p-2">
        <p className="text-xs font-semibold truncate">{item.title}</p>
        <p className="text-[10px] text-muted-foreground">{item.condition}</p>
      </div>
    </button>
  );
}

function ReviewCard({ review }: { review: ProfileData['reviews'][0] }) {
  return (
    <div className="bg-card border border-border rounded-xl p-3">
      <div className="flex items-center gap-2">
        {review.reviewerImage ? (
          <img src={review.reviewerImage} alt="" className="w-7 h-7 rounded-full object-cover" />
        ) : (
          <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center text-[10px] font-bold">
            {review.reviewerName[0]?.toUpperCase()}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <p className="text-xs font-semibold truncate">{review.reviewerName}</p>
        </div>
        <div className="flex items-center gap-0.5">
          {Array.from({ length: 5 }).map((_, i) => (
            <Star key={i} className={`w-3 h-3 ${i < review.rating ? 'text-amber-400 fill-amber-400' : 'text-muted-foreground/30'}`} />
          ))}
        </div>
      </div>
      {review.comment && <p className="text-xs text-muted-foreground mt-2">{review.comment}</p>}
    </div>
  );
}

export default function MyPublicProfilePage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { lang } = useI18n();
  const [data, setData] = useState<ProfileData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) return;
    getPublicProfile({ userId: user.id })
      .then(setData)
      .catch(() => setData(null))
      .finally(() => setLoading(false));
  }, [user]);

  if (loading) {
    return (
      <div className="min-h-screen bg-background max-w-[420px] mx-auto">
        <div className="bg-primary px-4 pt-4 pb-6 rounded-b-2xl">
          <div className="flex items-center gap-3 mb-4">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-white/15 flex items-center justify-center">
              <ArrowLeft className="w-4 h-4 text-white" />
            </button>
          </div>
          <div className="flex items-center gap-3">
            <Skeleton className="w-16 h-16 rounded-full bg-white/20" />
            <div className="space-y-2">
              <Skeleton className="h-4 w-32 bg-white/20 rounded" />
              <Skeleton className="h-3 w-20 bg-white/20 rounded" />
            </div>
          </div>
        </div>
        <div className="px-4 mt-4 space-y-3">
          <Skeleton className="h-16 w-full rounded-xl" />
          <Skeleton className="h-32 w-full rounded-xl" />
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <p className="text-muted-foreground">Gagal memuat profil</p>
      </div>
    );
  }

  const initials = (data.name?.[0] || 'U').toUpperCase();

  return (
    <div className="min-h-screen bg-background pb-8">
      <div className="max-w-[420px] mx-auto">
        {/* Preview Banner */}
        <div className="bg-amber-500/10 border-b border-amber-500/20 px-4 py-2 flex items-center gap-2 sticky top-0 z-50 backdrop-blur-sm">
          <Eye className="w-4 h-4 text-amber-600" />
          <p className="text-xs text-amber-700 font-medium flex-1">
            {lang === 'id' ? 'Ini adalah tampilan profil kamu oleh orang lain' : 'This is how others see your profile'}
          </p>
          <button onClick={() => navigate('/edit-profile')} className="text-xs font-semibold text-primary flex items-center gap-1">
            <Edit className="w-3 h-3" /> Edit
          </button>
        </div>

        {/* Header */}
        <div className="bg-primary px-4 pt-4 pb-5 rounded-b-2xl relative overflow-hidden">
          <div className="absolute -right-10 -top-10 w-32 h-32 rounded-full bg-white/5" />
          <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-white/15 flex items-center justify-center mb-4 relative z-10">
            <ArrowLeft className="w-4 h-4 text-white" />
          </button>
          <div className="flex items-center gap-4 relative z-10">
            {data.image ? (
              <img src={data.image} alt={data.name} className="w-16 h-16 rounded-full object-cover border-2 border-white/30" />
            ) : (
              <div className="w-16 h-16 rounded-full bg-white/20 text-white flex items-center justify-center text-xl font-bold border-2 border-white/30">
                {initials}
              </div>
            )}
            <div>
              <p className="text-white font-bold text-lg">{data.name}</p>
              <div className="flex items-center gap-2 mt-1">
                <BadgeChip points={data.totalPoints} size="sm" />
              </div>
              {(data.city || data.memberSince !== '-') && (
                <div className="flex items-center gap-3 mt-1.5">
                  {data.city && (
                    <span className="text-white/60 text-xs flex items-center gap-1">
                      <MapPin className="w-3 h-3" /> {data.city}
                    </span>
                  )}
                  <span className="text-white/60 text-xs flex items-center gap-1">
                    <ShieldCheck className="w-3 h-3" /> Sejak {data.memberSince}
                  </span>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Stats */}
        <div className="px-4 -mt-3 relative z-10">
          <div className="bg-card border border-border rounded-xl flex divide-x divide-border shadow-sm">
            {[
              { label: 'Barang', value: String(data.itemsUploaded) },
              { label: 'Barter', value: String(data.bartersCompleted) },
              { label: 'Rating', value: data.totalReviews > 0 ? String(data.averageRating) : '-' },
            ].map(s => (
              <div key={s.label} className="flex-1 py-2.5 text-center">
                <p className="font-bold text-base leading-none">{s.value}</p>
                <p className="text-[10px] text-muted-foreground mt-0.5">{s.label}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Bio */}
        {data.bio && (
          <div className="px-4 mt-4">
            <p className="text-sm text-muted-foreground">{data.bio}</p>
          </div>
        )}

        {/* Items */}
        <div className="px-4 mt-5">
          <h3 className="font-bold text-sm mb-3">{lang === 'id' ? 'Barang Ditawarkan' : 'Listed Items'} ({data.items.length})</h3>
          {data.items.length > 0 ? (
            <div className="grid grid-cols-2 gap-2">
              {data.items.map(item => (
                <ItemCard key={item.id} item={item} onTap={() => navigate(`/item/${item.id}`)} />
              ))}
            </div>
          ) : (
            <div className="bg-card border border-border rounded-xl p-6 text-center">
              <Package className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
              <p className="text-xs text-muted-foreground">{lang === 'id' ? 'Belum ada barang' : 'No items yet'}</p>
            </div>
          )}
        </div>

        {/* Reviews */}
        <div className="px-4 mt-5">
          <div className="flex items-center justify-between mb-3">
            <h3 className="font-bold text-sm">{lang === 'id' ? 'Ulasan' : 'Reviews'} ({data.totalReviews})</h3>
            {data.totalReviews > 0 && (
              <div className="flex items-center gap-1">
                <Star className="w-4 h-4 text-amber-400 fill-amber-400" />
                <span className="font-bold text-sm">{data.averageRating}</span>
              </div>
            )}
          </div>
          {data.reviews.length > 0 ? (
            <div className="space-y-2">
              {data.reviews.map(r => <ReviewCard key={r.id} review={r} />)}
            </div>
          ) : (
            <div className="bg-card border border-border rounded-xl p-6 text-center">
              <Star className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
              <p className="text-xs text-muted-foreground">{lang === 'id' ? 'Belum ada ulasan' : 'No reviews yet'}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
