import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Shield, Mail, Smartphone, Key, CheckCircle, AlertTriangle, Pencil, X, Loader2, Eye, EyeOff, Lock, Info } from 'lucide-react';
