type EditingField = 'phone' | 'password' | null;

export default function SecurityPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { profile, loading, refresh } = useProfile();
  const [editing, setEditing] = useState<EditingField>(null);
  const [phoneValue, setPhoneValue] = useState('');
  const [saving, setSaving] = useState(false);

  // Password change state
  const [currentPw, setCurrentPw] = useState('');
  const [newPw, setNewPw] = useState('');
  const [confirmPw, setConfirmPw] = useState('');
  const [otpCode, setOtpCode] = useState('');
  const [showCurrentPw, setShowCurrentPw] = useState(false);
  const [showNewPw, setShowNewPw] = useState(false);

  const startEditPhone = () => {
    setPhoneValue(profile?.phone || '');
    setEditing('phone');
  };

  const cancelEdit = () => {
    setEditing(null);
    setPhoneValue('');
    setCurrentPw('');
    setNewPw('');
    setConfirmPw('');
    setOtpCode('');
    setShowCurrentPw(false);
    setShowNewPw(false);
  };

  const savePhone = async () => {
    if (!phoneValue.trim()) {
      toast.error('Nomor telepon tidak boleh kosong');
      return;
    }
    setSaving(true);
    try {
      await updateProfile({ phone: phoneValue.trim() });
      toast.success('Nomor telepon berhasil diperbarui');
      refresh();
      setEditing(null);
    } catch {
      toast.error('Gagal menyimpan');
    }
    setSaving(false);
  };

  const savePassword = async () => {
    if (!currentPw.trim()) { toast.error('Masukkan password lama'); return; }
    if (newPw.length < 6) { toast.error('Password baru minimal 6 karakter'); return; }
    if (newPw !== confirmPw) { toast.error('Konfirmasi password tidak cocok'); return; }
    setSaving(true);
    try {
      await changePassword({ currentPassword: currentPw, newPassword: newPw, otpCode: otpCode || undefined });
      toast.success('Password berhasil diubah!');
      cancelEdit();
    } catch (err: any) {
      toast.error(err?.message || 'Gagal mengubah password');
    }
    setSaving(false);
  };

  // Calculate security score
  const checks = [
    !!user?.emailVerified,
    !!profile?.phone,
    true, // password always set
    !!profile?.address,
  ];
  const score = Math.round((checks.filter(Boolean).length / checks.length) * 100);

  if (loading) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-[420px] mx-auto">
          <div className="bg-primary px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white">Keamanan Akun</h1>
          </div>
          <div className="p-4 space-y-4">
            {[0,1,2,3].map(i => <Skeleton key={i} className="h-16 w-full rounded-xl" />)}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-primary">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5 text-white" /></button>
            <h1 className="font-bold text-base text-white flex-1">Keamanan Akun</h1>
          </div>
        </div>

        {/* Security score */}
        <div className="mx-4 mt-4 bg-card rounded-2xl border border-border p-4">
          <div className="flex items-center gap-3 mb-3">
            <div className={`w-12 h-12 rounded-full flex items-center justify-center ${score >= 75 ? 'bg-emerald-100' : 'bg-amber-100'}`}>
              <Shield className={`w-6 h-6 ${score >= 75 ? 'text-emerald-600' : 'text-amber-600'}`} />
            </div>
            <div>
              <p className="font-bold text-sm">Skor Keamanan</p>
              <p className={`text-2xl font-bold ${score >= 75 ? 'text-emerald-600' : 'text-amber-600'}`}>{score}%</p>
            </div>
          </div>
          <div className="w-full bg-muted rounded-full h-2">
            <div
              className={`rounded-full h-2 transition-all ${score >= 75 ? 'bg-emerald-500' : 'bg-amber-500'}`}
              style={{ width: `${score}%` }}
            />
          </div>
          <p className="text-[10px] text-muted-foreground mt-2">
            {score >= 75
              ? 'Akun kamu cukup aman. Pertahankan!'
              : 'Lengkapi verifikasi untuk meningkatkan keamanan akun.'}
          </p>
        </div>

        {/* Security items */}
        <div className="px-4 mt-4">
          <div className="bg-card rounded-2xl border border-border overflow-hidden divide-y divide-border">
            {/* Email */}
            <div className="px-4 py-4">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                  <Mail className="w-4 h-4 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">Email</p>
                  <p className="text-[11px] text-muted-foreground truncate">{user?.email || '-'}</p>
                </div>
                {user?.emailVerified ? (
                  <span className="flex items-center gap-1 text-[10px] text-emerald-600 font-medium">
                    <CheckCircle className="w-3.5 h-3.5" /> Terverifikasi
                  </span>
                ) : (
                  <span className="flex items-center gap-1 text-[10px] text-amber-600 font-medium">
                    <AlertTriangle className="w-3.5 h-3.5" /> Belum verifikasi
                  </span>
                )}
              </div>
              <p className="text-[10px] text-muted-foreground mt-1.5 ml-12">
                Email dikelola melalui sistem login. Untuk mengubah email, silakan hubungi admin.
              </p>
            </div>

            {/* Phone — editable */}
            <div className="px-4 py-4">
              {editing === 'phone' ? (
                <div>
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                      <Smartphone className="w-4 h-4 text-primary" />
                    </div>
                    <p className="text-sm font-semibold flex-1">Edit Nomor Telepon</p>
                    <button onClick={cancelEdit} className="p-1">
                      <X className="w-4 h-4 text-muted-foreground" />
                    </button>
                  </div>
                  <input
                    type="tel"
                    value={phoneValue}
                    onChange={e => setPhoneValue(e.target.value)}
                    placeholder="08xxxxxxxxxx"
                    className="w-full bg-muted rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
                    autoFocus
                  />
                  <div className="flex gap-2 mt-3">
                    <button onClick={cancelEdit} className="flex-1 py-2.5 rounded-xl border border-border text-sm font-semibold text-foreground">
                      Batal
                    </button>
                    <button onClick={savePhone} disabled={saving} className="flex-1 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold flex items-center justify-center gap-1.5">
                      {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Simpan'}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                    <Smartphone className="w-4 h-4 text-primary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold">Nomor Telepon</p>
                    <p className="text-[11px] text-muted-foreground truncate">{profile?.phone || 'Belum diisi'}</p>
                  </div>
                  <button onClick={startEditPhone} className="flex items-center gap-1 text-[10px] text-primary font-medium px-2 py-1 rounded-lg hover:bg-primary/5 transition-colors">
                    <Pencil className="w-3 h-3" /> Edit
                  </button>
                </div>
              )}
            </div>

            {/* Password — editable */}
            <div className="px-4 py-4">
              {editing === 'password' ? (
                <div>
                  <div className="flex items-center gap-3 mb-3">
                    <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                      <Key className="w-4 h-4 text-primary" />
                    </div>
                    <p className="text-sm font-semibold flex-1">Ganti Password</p>
                    <button onClick={cancelEdit} className="p-1">
                      <X className="w-4 h-4 text-muted-foreground" />
                    </button>
                  </div>

                  <div className="space-y-3">
                    {/* Current password */}
                    <div>
                      <label className="text-[11px] font-medium text-muted-foreground mb-1 block">Password Lama</label>
                      <div className="relative">
                        <input
                          type={showCurrentPw ? 'text' : 'password'}
                          value={currentPw}
                          onChange={e => setCurrentPw(e.target.value)}
                          placeholder="Masukkan password lama"
                          className="w-full bg-muted rounded-xl px-4 py-3 pr-10 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
                          autoFocus
                        />
                        <button type="button" onClick={() => setShowCurrentPw(!showCurrentPw)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                          {showCurrentPw ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                        </button>
                      </div>
                    </div>

                    {/* New password */}
                    <div>
                      <label className="text-[11px] font-medium text-muted-foreground mb-1 block">Password Baru</label>
                      <div className="relative">
                        <input
                          type={showNewPw ? 'text' : 'password'}
                          value={newPw}
                          onChange={e => setNewPw(e.target.value)}
                          placeholder="Minimal 6 karakter"
                          className="w-full bg-muted rounded-xl px-4 py-3 pr-10 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
                        />
                        <button type="button" onClick={() => setShowNewPw(!showNewPw)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                          {showNewPw ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                        </button>
                      </div>
                    </div>

                    {/* Confirm new password */}
                    <div>
                      <label className="text-[11px] font-medium text-muted-foreground mb-1 block">Konfirmasi Password Baru</label>
                      <input
                        type="password"
                        value={confirmPw}
                        onChange={e => setConfirmPw(e.target.value)}
                        placeholder="Ulangi password baru"
                        className="w-full bg-muted rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-primary/30 placeholder:text-muted-foreground"
                      />
                      {confirmPw && newPw !== confirmPw && (
                        <p className="text-[10px] text-destructive mt-1">Password tidak cocok</p>
                      )}
                    </div>

                    {/* OTP field — disabled for now */}
                    <div className="opacity-50">
                      <label className="text-[11px] font-medium text-muted-foreground mb-1 block">Kode OTP</label>
                      <input
                        type="text"
                        value={otpCode}
                        onChange={e => setOtpCode(e.target.value)}
                        placeholder="Akan diaktifkan nanti"
                        className="w-full bg-muted rounded-xl px-4 py-3 text-sm outline-none placeholder:text-muted-foreground cursor-not-allowed"
                        disabled
                      />
                      <div className="flex items-start gap-1.5 mt-1.5">
                        <Info className="w-3 h-3 text-muted-foreground mt-0.5 flex-shrink-0" />
                        <p className="text-[10px] text-muted-foreground">
                          Verifikasi OTP via SMS akan diaktifkan di akhir proyek MUTARI untuk keamanan ekstra saat ganti password.
                        </p>
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-2 mt-4">
                    <button onClick={cancelEdit} className="flex-1 py-2.5 rounded-xl border border-border text-sm font-semibold text-foreground">
                      Batal
                    </button>
                    <button
                      onClick={savePassword}
                      disabled={saving || !currentPw || newPw.length < 6 || newPw !== confirmPw}
                      className="flex-1 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold flex items-center justify-center gap-1.5 disabled:opacity-50"
                    >
                      {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <><Lock className="w-3.5 h-3.5" /> Ubah Password</>}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="flex items-center gap-3">
                  <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                    <Key className="w-4 h-4 text-primary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold">Password</p>
                    <p className="text-[11px] text-muted-foreground">••••••••</p>
                  </div>
                  <button onClick={() => setEditing('password')} className="flex items-center gap-1 text-[10px] text-primary font-medium px-2 py-1 rounded-lg hover:bg-primary/5 transition-colors">
                    <Pencil className="w-3 h-3" /> Ganti
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Tips */}
        <div className="px-4 mt-5">
          <h3 className="font-bold text-sm mb-2">Tips Keamanan</h3>
          <div className="bg-card rounded-2xl border border-border p-4 space-y-2.5">
            {[
              'Jangan bagikan password kepada siapapun.',
              'Lengkapi nomor telepon untuk verifikasi dua langkah.',
              'Pastikan email yang terdaftar masih aktif.',
              'Perbarui alamat agar proses barter COD aman.',
            ].map((tip, i) => (
              <div key={i} className="flex items-start gap-2">
                <span className="text-primary text-xs mt-0.5">•</span>
                <p className="text-xs text-foreground">{tip}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
