    "src/pages/UploadBarang.tsx": "import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Sparkles } from 'lucide-react';
import { useUpload } from 'zitejs/upload';
import { toast } from 'sonner';
import { uploadItem } from 'zitejs/api';
import PhotoGrid from '../components/upload/PhotoGrid';
import SpecRows from '../components/upload/SpecRows';
import LocationAuto from '../components/upload/LocationAuto';
import { useI18n } from '../context/I18nContext';

const KATEGORI = ['Elektronik', 'Fashion', 'Olahraga', 'Otomotif', 'Buku & Hobi', 'Peralatan Rumah', 'Gaming', 'Lainnya'];
const KONDISI = ['Baru', 'Seperti Baru', 'Baik', 'Cukup'];
const KELENGKAPAN = ['Dus / Box', 'Kartu Garansi', 'Nota Pembelian', 'Charger', 'Kabel', 'Tas / Case', 'Buku Manual', 'Aksesori Tambahan'];

export default function UploadBarang() {
  const navigate = useNavigate();
  const { lang } = useI18n();
  // Phone verification skipped — WhatsApp OTP gateway belum terhubung
  // const [phoneVerified, setPhoneVerified] = useState<boolean | null>(null);
  // const [existingPhone, setExistingPhone] = useState('');
  const [photos, setPhotos] = useState<{ url: string; file?: File }[]>([]);
  const [nama, setNama] = useState('');
  const [kategori, setKategori] = useState('');
  const [kondisi, setKondisi] = useState('');
  const [kelengkapan, setKelengkapan] = useState<string[]>([]);
  const [specs, setSpecs] = useState<{ label: string; value: string }[]>([{ label: '', value: '' }]);
  const [kekurangan, setKekurangan] = useState('');
  const [inginDitukar, setInginDitukar] = useState('');
  const [tambahan, setTambahan] = useState('');
  const [deskripsi, setDeskripsi] = useState('');
  const [lokasi, setLokasi] = useState('');
  const [lokasiLoading, setLokasiLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [mode, setMode] = useState<'draft' | 'publish'>('publish');

  const { upload, isUploading } = useUpload();

  // Phone verification skipped for now
  // useEffect(() => {
  //   getProfile({}).then(res => {
  //     setPhoneVerified(res.phoneVerified);
  //     setExistingPhone(res.phone || '');
  //   }).catch(() => setPhoneVerified(false));
  // }, []);

  // Phone verification gate removed — will re-enable when WhatsApp gateway is connected

  const valid = nama.trim() && kategori && kondisi && kekurangan.trim() && deskripsi.length >= 10 && photos.length >= 3;

  const handlePhotoAdd = async (files: File[]) => {
    for (const file of files.slice(0, 10 - photos.length)) {
      try {
        const { url } = await upload(file);
        setPhotos(p => [...p, { url }]);
      } catch {
        toast.error(lang === 'id' ? 'Gagal upload foto' : 'Failed to upload photo');
      }
    }
  };

  const handleSubmit = async (asDraft: boolean) => {
    if (!valid && !asDraft) return;
    setSubmitting(true);
    try {
      const specStr = specs.filter(s => s.label && s.value).map(s => `${s.label}: ${s.value}`).join('\n');
      const result = await uploadItem({
        title: nama,
        kategori,
        kondisi,
        kelengkapan: kelengkapan.join(', '),
        spesifikasi: specStr,
        kekurangan,
        inginDitukar,
        tambahan,
        deskripsi,
        lokasi,
        photos: photos.map(p => p.url),
        status: asDraft ? 'draft' : 'publish',
      });
      const msg = asDraft
        ? 'Disimpan sebagai draft'
        : `Barang berhasil dipublish! +${result.pointsAwarded} poin 🎉`;
      toast.success(msg);
      navigate('/');
    } catch {
      toast.error('Gagal menyimpan barang');
    }
    setSubmitting(false);
  };

  return (
    <div className="min-h-screen bg-background pb-32">
      {/* Header */}
      <div className="sticky top-0 z-30 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
        <button onClick={() => navigate(-1)}>
          <ArrowLeft className="w-5 h-5 text-foreground" />
        </button>
        <h1 className="text-lg font-bold text-foreground">Upload Barang Baru</h1>
      </div>

      <div className="px-4 py-5 space-y-6">
        {/* Foto */}
        <PhotoGrid photos={photos} onAdd={handlePhotoAdd} onRemove={(i) => setPhotos(p => p.filter((_, idx) => idx !== i))} isUploading={isUploading} lang={lang} />

        {/* Nama Barang */}
        <Field label="Nama Barang" required>
          <input
            value={nama}
            onChange={e => setNama(e.target.value)}
            placeholder="Contoh: iPhone 13 Pro Max"
            className="form-input"
          />
        </Field>

        {/* Kategori */}
        <Field label="Kategori" required>
          <div className="relative">
            <select value={kategori} onChange={e => setKategori(e.target.value)} className="form-input appearance-none pr-10">
              <option value="">Pilih kategori</option>
              {KATEGORI.map(k => <option key={k} value={k}>{k}</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-muted-foreground"><path d="M6 9l6 6 6-6"/></svg>
            </div>
          </div>
        </Field>

        {/* Kondisi */}
        <Field label="Kondisi Barang" required>
          <div className="relative">
            <select value={kondisi} onChange={e => setKondisi(e.target.value)} className="form-input appearance-none pr-10">
              <option value="">Pilih kondisi</option>
              {KONDISI.map(k => <option key={k} value={k}>{k}</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-muted-foreground"><path d="M6 9l6 6 6-6"/></svg>
            </div>
          </div>
        </Field>

        {/* Kelengkapan */}
        <Field label="Kelengkapan Barang">
          <div className="flex flex-wrap gap-2">
            {KELENGKAPAN.map(item => {
              const active = kelengkapan.includes(item);
              return (
                <button
                  key={item}
                  type="button"
                  onClick={() => setKelengkapan(prev => active ? prev.filter(k => k !== item) : [...prev, item])}
                  className={`px-3.5 py-2 rounded-full text-sm font-medium border transition-colors ${
                    active ? 'bg-primary text-primary-foreground border-primary' : 'bg-card text-foreground border-border hover:bg-accent'
                  }`}
                >
                  {item}
                </button>
              );
            })}
          </div>
        </Field>

        {/* Spesifikasi */}
        <SpecRows specs={specs} onChange={setSpecs} />

        {/* Kekurangan */}
        <Field label="Kekurangan / Cacat Barang" required>
          <textarea
            value={kekurangan}
            onChange={e => setKekurangan(e.target.value)}
            placeholder="Contoh: baret halus di sisi kanan, baterai 88%"
            rows={3}
            className="form-input resize-none"
          />
        </Field>

        {/* Estimasi AI */}
        <div>
          <p className="text-sm font-semibold text-foreground mb-2">Estimasi AI</p>
          <div className="bg-accent/50 border border-border rounded-xl p-4">
            <div className="flex items-center gap-2 mb-1">
              <Sparkles className="w-4 h-4 text-primary" />
              <p className="text-sm font-semibold text-primary">Perkiraan Nilai Barang</p>
            </div>
            <p className="font-bold text-foreground">Lengkapi kategori & kondisi</p>
            <p className="text-xs text-muted-foreground mt-1">
              Dihitung otomatis oleh Mutari AI dari kategori, kondisi, kelengkapan, dan foto. Kamu tidak perlu mengisi.
            </p>
          </div>
        </div>

        {/* Ingin Ditukar Dengan */}
        <Field label="Ingin Ditukar Dengan">
          <input
            value={inginDitukar}
            onChange={e => setInginDitukar(e.target.value)}
            placeholder="Pisahkan dengan koma, mis: Laptop, Kamera"
            className="form-input"
          />
        </Field>

        {/* Tambahan yang Diinginkan */}
        <Field label="Tambahan yang Diinginkan">
          <input
            value={tambahan}
            onChange={e => setTambahan(e.target.value)}
            placeholder="Contoh: tambah uang Rp500.000 / aksesori"
            className="form-input"
          />
        </Field>

        {/* Deskripsi Lengkap */}
        <Field label="Deskripsi Lengkap" required>
          <textarea
            value={deskripsi}
            onChange={e => setDeskripsi(e.target.value)}
            placeholder="Jelaskan detail barang Anda..."
            rows={5}
            className="form-input resize-none"
          />
          <p className={`text-xs mt-1 ${deskripsi.length < 10 ? 'text-destructive' : 'text-muted-foreground'}`}>
            Wajib diisi, minimal 10 karakter ({deskripsi.length}/10)
          </p>
        </Field>

        {/* Lokasi (auto GPS) */}
        <LocationAuto value={lokasi} onChange={setLokasi} loading={lokasiLoading} onLoadingChange={setLokasiLoading} />
      </div>

      {/* Bottom bar */}
      <div className="fixed bottom-0 left-0 right-0 bg-card border-t border-border p-4 flex gap-3 z-30 max-w-[500px] mx-auto">
        <button
          onClick={() => handleSubmit(true)}
