                                      <div className="flex-1 min-w-0"><span className="text-[11px] font-medium">{v.label}</span><p className="text-[9px] text-orange-600 leading-tight">{v.description}</p></div>
                                      <span className="text-[11px] font-bold text-orange-600 flex-shrink-0">{v.minusPoints} MP</span>
                                    </div>
                                  ))}
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </>);
                      })()}

                      {/* Ringan */}
                      {(() => {
                        const items = VIOLATION_TYPES.filter(v => v.severity === 'ringan');
                        return (<>
                          <button onClick={() => toggleGuide('ringan')} className="w-full flex items-center gap-2 bg-yellow-50 rounded-xl px-3 py-2.5 text-left">
                            <div className="w-7 h-7 rounded-full bg-yellow-100 flex items-center justify-center flex-shrink-0"><span className="w-2.5 h-2.5 rounded-full bg-yellow-500" /></div>
                            <div className="flex-1">
                              <p className="text-[11px] font-bold text-yellow-700">Ringan</p>
                              <p className="text-[9px] text-yellow-600">{items.length} jenis · {items[0]?.minusPoints || -1} MP</p>
                            </div>
                            <ChevronDown className={`w-4 h-4 text-yellow-400 transition-transform ${openGuide === 'ringan' ? 'rotate-180' : ''}`} />
                          </button>
                          <AnimatePresence>
                            {openGuide === 'ringan' && (
                              <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                                <div className="space-y-1 pt-1 pb-1 ml-2">
                                  {items.map(v => (
                                    <div key={v.type} className="flex items-start gap-2 bg-yellow-50/60 rounded-lg px-3 py-2">
