                                    </div>
                                  ))}
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </>);
                      })()}

                      {/* Ambang Batas Sanksi */}
                      <button onClick={() => toggleGuide('threshold')} className="w-full flex items-center gap-2 bg-muted/50 rounded-xl px-3 py-2.5 text-left">
                        <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center flex-shrink-0">
                          <AlertTriangle className="w-3.5 h-3.5 text-muted-foreground" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[11px] font-bold">Ambang Batas Sanksi</p>
                          <p className="text-[9px] text-muted-foreground">Peringatan, tangguh & blokir</p>
                        </div>
                        <ChevronDown className={`w-4 h-4 text-muted-foreground transition-transform ${openGuide === 'threshold' ? 'rotate-180' : ''}`} />
                      </button>
                      <AnimatePresence>
                        {openGuide === 'threshold' && (
                          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                            <div className="space-y-1 pt-1 pb-1 ml-2">
                              {[
                                { threshold: '-20 MP', label: 'Peringatan', desc: 'Akun dalam pengawasan', color: 'bg-yellow-50 text-yellow-700' },
                                { threshold: '-50 MP', label: 'Ditangguhkan', desc: 'Akun ditangguhkan sementara', color: 'bg-orange-50 text-orange-700' },
                                { threshold: '-75 MP', label: 'Diblokir', desc: 'Ban permanen dari platform', color: 'bg-red-50 text-red-700' },
