                                  <span className="text-[11px] font-bold">{t.label}</span>
                                  <span className="text-[9px] opacity-70 ml-auto">{t.desc}</span>
                                </div>
                              ))}
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>

        {/* Riwayat Transaksi — collapsible */}
        <div className="px-4 mt-3">
          <div className="bg-card border border-border rounded-2xl overflow-hidden">
            <button onClick={() => toggleSection('riwayat')} className="w-full p-4 text-left flex items-center gap-3">
              <div className="w-9 h-9 rounded-xl bg-sky-100 flex items-center justify-center flex-shrink-0">
                <Wallet className="w-4.5 h-4.5 text-sky-600" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-bold text-sm">Riwayat Transaksi</p>
                <p className="text-[10px] text-muted-foreground">{history.length} transaksi{violations.length > 0 ? ` · ${violations.length} pelanggaran` : ''}</p>
              </div>
              <ChevronDown className={`w-5 h-5 text-muted-foreground transition-transform duration-200 flex-shrink-0 ${openSection === 'riwayat' ? 'rotate-180' : ''}`} />
            </button>
            <AnimatePresence>
              {openSection === 'riwayat' && (
                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={{ duration: 0.25 }} className="overflow-hidden">
                  <div className="px-4 pb-4 border-t border-border pt-3">
                    {/* Violations */}
                    {!violationsLoading && violations.length > 0 && (
                      <div className="mb-4">
