import UploadServicePage from './pages/UploadServicePage';
import BarterJasaPage from './pages/BarterJasaPage';
import ServiceBarterDetailPage from './pages/ServiceBarterDetailPage';

export default function App() {
  const { user, isLoading } = useAuth();

  // Restore theme from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('mutari-theme');
    if (saved === 'dark') document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, []);

  // Check pending barter reviews on every app open — creates reminder notifications
  // Also update online presence so "Pengguna Online" stat works
  const reviewCheckDone = useRef(false);
  useEffect(() => {
    if (user && !reviewCheckDone.current) {
      reviewCheckDone.current = true;
      checkPendingReviews({}).catch(() => {});
      updatePresence({}).catch(() => {});
    }
  }, [user]);

  if (isLoading) {
    return <MutariLoading label="Memuat MUTARI..." />;
  }

  if (!user) {
    return <LandingPage />;
  }

  return (
    <I18nProvider>
    <SetupGate>
      <UnreadProvider>
      <LocationProvider>
        <BanGate>
        <BrowserRouter>
          <Toaster position="top-center" />
          <PointRewardProvider>
          <LocationGate>
            <BanAwareRoutes />
          </LocationGate>
          </PointRewardProvider>
        </BrowserRouter>
        </BanGate>
      </LocationProvider>
      </UnreadProvider>
    </SetupGate>
    </I18nProvider>
  );
}

function BanAwareRoutes() {
  const { isBanned, bannedReason } = useBanStatus();

  if (isBanned) {
    return (
      <Routes>
        <Route path="/" element={<Beranda />} />
        <Route path="/item/:id" element={<ItemDetail />} />
        <Route path="/search" element={<SearchPage />} />
        <Route path="*" element={<BannedScreen bannedReason={bannedReason} />} />
      </Routes>
    );
  }

  return (
    <Routes>
              <Route path="/" element={<Beranda />} />
              <Route path="/item/:id" element={<ItemDetail />} />
              <Route path="/search" element={<SearchPage />} />
              <Route path="/smart-match" element={<PointGate featureId="smart_match_priority"><SmartMatch /></PointGate>} />
