import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Analisis gambar barang dengan Gemini + cari match barter seimbang',
  authenticated: true,
  inputSchema: z.object({
    imageUrl: z.string().url(),
  }),
  outputSchema: z.object({
    analysis: z.string(),
    estimatedMinPrice: z.number(),
    estimatedMaxPrice: z.number(),
    matches: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
      condition: z.string(),
      location: z.string(),
      estimatedMin: z.number(),
      estimatedMax: z.number(),
      ownerName: z.string(),
    })),
  }),
  execute: async ({ input, context }) => {
    const apiKey = process.env.ZITE_GEMINI_API_KEY;

    // Fetch image → base64
    const imgRes = await fetch(input.imageUrl);
    const imgBuf = await imgRes.arrayBuffer();
    const base64 = Buffer.from(imgBuf).toString('base64');
    const mimeType = imgRes.headers.get('content-type') || 'image/jpeg';

    const prompt = `Analisis gambar barang ini. Jawab dalam format berikut (teks biasa, TANPA markdown):

Kategori: (tebak kategori barang)
Merek: (tebak merek/brand)
Kondisi Fisik: (deskripsikan kondisi)
Estimasi Harga: Rp XXX.XXX - Rp XXX.XXX

Berikan kisaran harga pasar bekas di Indonesia dalam Rupiah. Jawab singkat dan langsung.`;

    const body = {
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: mimeType, data: base64 } },
        ],
      }],
    };

    const callGemini = async (): Promise<Response> => {
      const models = ['gemini-3.6-flash'];
      let lastRes: Response | null = null;
      for (const model of models) {
        lastRes = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
          { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }
        );
        if (lastRes.ok) return lastRes;
        if (lastRes.status !== 429 && lastRes.status !== 503) return lastRes;
      }
      return lastRes!;
    };

    const geminiRes = await callGemini();

    if (!geminiRes.ok) {
      const errText = await geminiRes.text();
      if (geminiRes.status === 429) {
        throw new Error('Kuota AI harian habis. Coba lagi besok atau upgrade ke paket berbayar di Google AI Studio.');
      }
      throw new Error(`Gemini API error: ${geminiRes.status} - ${errText}`);
    }

    const data = await geminiRes.json();
    const text: string = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';

    // Parse price range from Gemini response
    let estimatedMinPrice = 0;
    let estimatedMaxPrice = 0;
    const priceMatch = text.match(/Rp\s*[\d.,]+\s*-\s*Rp\s*[\d.,]+/i);
    if (priceMatch) {
      const nums = priceMatch[0].match(/[\d.]+/g);
      if (nums && nums.length >= 2) {
        estimatedMinPrice = parseInt(nums[0].replace(/\./g, ''), 10) || 0;
        estimatedMaxPrice = parseInt(nums[1].replace(/\./g, ''), 10) || 0;
      }
    }

    // Find matching items from OTHER users with overlapping price range
    const tolerance = 0.4;
    const searchMin = estimatedMinPrice * (1 - tolerance);
    const searchMax = estimatedMaxPrice * (1 + tolerance);

    let matches: {
      id: string; title: string; photo: string; condition: string;
      location: string; estimatedMin: number; estimatedMax: number; ownerName: string;
    }[] = [];

    if (estimatedMinPrice > 0) {
      try {
        const { records } = await zite.items.findAll({
          filters: {
            status: 'Tersedia',
          },
          limit: 50,
        });

        // Filter: exclude own items + match price range
        const userId = context.user.id;
        const filtered = records.filter(r => {
          // Exclude own items
          const owners = Array.isArray(r.owner) ? r.owner : r.owner ? [r.owner] : [];
          if (owners.includes(userId)) return false;
          // Must have price estimates
          if (!r.estimatedValueMin || !r.estimatedValueMax) return false;
          // Price overlap check
          if (r.estimatedValueMin > searchMax) return false;
          if (r.estimatedValueMax < searchMin) return false;
          return true;
        });

        // Sort by closest value
        const targetMid = (estimatedMinPrice + estimatedMaxPrice) / 2;
        filtered.sort((a, b) => {
          const midA = ((a.estimatedValueMin || 0) + (a.estimatedValueMax || 0)) / 2;
          const midB = ((b.estimatedValueMin || 0) + (b.estimatedValueMax || 0)) / 2;
          return Math.abs(midA - targetMid) - Math.abs(midB - targetMid);
        });

        // Get owner names
        const topItems = filtered.slice(0, 5);
        const ownerIds = [...new Set(topItems.flatMap(r => Array.isArray(r.owner) ? r.owner : r.owner ? [r.owner] : []))];
        let ownerMap: Record<string, string> = {};
        if (ownerIds.length > 0) {
          const { records: users } = await zite.auth.findAllUsers({ limit: 50 });
          for (const u of users) {
            ownerMap[u.id] = u.name || u.firstName || 'User';
          }
        }

        matches = topItems.map(r => {
          let photo = '';
          if (r.photos && Array.isArray(r.photos) && r.photos.length > 0) {
            photo = r.photos[0]?.url || '';
          }
          const ownerId = Array.isArray(r.owner) ? r.owner[0] : r.owner || '';
          return {
            id: r.id,
            title: r.title || 'Tanpa judul',
            photo,
            condition: r.condition || '-',
            location: r.location || '-',
            estimatedMin: r.estimatedValueMin || 0,
            estimatedMax: r.estimatedValueMax || 0,
            ownerName: ownerMap[ownerId] || 'User',
          };
        });
      } catch {
        // If match search fails, still return analysis
        matches = [];
      }
    }

    return {
      analysis: text || 'Tidak dapat menganalisis gambar.',
      estimatedMinPrice,
      estimatedMaxPrice,
      matches,
    };
  },
});

