import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Applies a referral/affiliate code for a newly registered user',
  authenticated: true,
  inputSchema: z.object({
    referralCode: z.string().min(1),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const code = input.referralCode.trim().toUpperCase();

    // Extract referrer user id from code (MUTARI-XXXXXXXX)
    if (!code.startsWith('MUTARI-')) {
      return { success: false, message: 'Kode affiliate tidak valid' };
    }

    // Check if this user already has a referral record (already been referred)
    const { records: existing } = await zite.referrals.findAll({
      filters: { referredUser: userId },
      limit: 1,
    });
    if (existing.length > 0) {
      return { success: false, message: 'Kamu sudah pernah menggunakan kode affiliate' };
    }

    // Find the referrer by matching the code pattern
    // Code is MUTARI- + first 8 chars of userId (no dashes, uppercase)
    const codeSlug = code.replace('MUTARI-', '');

    // Search all users to find matching referrer
    const { records: allUsers } = await zite.auth.findAllUsers({ limit: 500 });
    const referrer = allUsers.find(u => {
      const userSlug = u.id.replace(/-/g, '').slice(0, 8).toUpperCase();
      return userSlug === codeSlug;
    });

    if (!referrer) {
      return { success: false, message: 'Kode affiliate tidak ditemukan' };
    }

    // Can't refer yourself
    if (referrer.id === userId) {
      return { success: false, message: 'Tidak bisa menggunakan kode sendiri' };
    }

    // Create referral record (status Pending — bonus given when first barter completes)
    await zite.referrals.create({
      record: {
        referralCode: code,
        referrer: referrer.id,
        referredUser: userId,
        status: 'Pending',
        bonusPoints: 0,
      },
    });

    // Send notification to referrer
    await zite.notifications.create({
      record: {
        title: 'Teman Baru Bergabung! 🎉',
        body: `${context.user.firstName || context.user.email} mendaftar menggunakan kode affiliate kamu! Bonus poin akan diberikan saat mereka menyelesaikan barter pertama.`,
        type: 'Milestone',
        recipient: referrer.id,
        read: false,
        linkPath: '/affiliate',
      },
    });

    return { success: true, message: 'Kode affiliate berhasil diterapkan! Bonus poin akan diberikan setelah barter pertama.' };
  },
});

