import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const BOOST_COST = 100;
const BOOST_HOURS = 24;

export default createEndpoint({
  description: 'Spend 100 MP to boost a listing to the top for 24 hours',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    remainingPoints: z.number(),
    expiresAt: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Verify item belongs to user
    const item = await zite.items.findOne({ id: input.itemId });
    if (!item) throw new Error('Item tidak ditemukan');
    const ownerIds = Array.isArray(item.owner) ? item.owner : item.owner ? [item.owner] : [];
    if (!ownerIds.includes(userId)) throw new Error('Kamu hanya bisa boost barang milikmu sendiri');

    // Check points
    const up = await zite.userPoints.findOne({ filters: { user: userId } });
    if (!up || (up.totalPoints ?? 0) < BOOST_COST) throw new Error(`Poin tidak cukup. Kamu butuh ${BOOST_COST} MP.`);

    // Check if already boosted
    const { records: existing } = await zite.pointRedemptions.findAll({
      filters: { user: userId, type: 'boost', status: 'active' },
      limit: 100,
    });
    const activeBoost = existing.find(r => {
      const itemIds = Array.isArray(r.item) ? r.item : r.item ? [r.item] : [];
      return itemIds.includes(input.itemId) && r.expiresAt && new Date(r.expiresAt) > new Date();
    });
    if (activeBoost) throw new Error('Item ini sudah di-boost dan masih aktif');

    const expiresAt = new Date(Date.now() + BOOST_HOURS * 60 * 60 * 1000);

    // Deduct points
    const newPoints = (up.totalPoints ?? 0) - BOOST_COST;
    await zite.userPoints.update({ id: up.id, record: { totalPoints: newPoints } });

    // Record transaction
    await zite.pointHistory.create({
      record: {
        activity: `Boost Listing: ${item.title || 'Item'}`,
        user: userId,
        points: -BOOST_COST,
        activityType: 'boost_listing',
      },
    });

    // Create redemption
    await zite.pointRedemptions.create({
      record: {
        label: `Boost: ${item.title || 'Item'}`,
        user: userId,
        type: 'boost',
        pointsSpent: BOOST_COST,
        item: input.itemId,
        expiresAt: expiresAt.toISOString(),
        status: 'active',
        recipientUserId: null,
        raffleTickets: null,
      },
    });

    return { success: true, remainingPoints: newPoints, expiresAt: expiresAt.toISOString() };
  },
});

