import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const TICKET_COST = 500;

export default createEndpoint({
  description: 'Spend 500 MP per raffle ticket for the monthly draw',
  authenticated: true,
  inputSchema: z.object({
    ticketCount: z.number().min(1).max(10),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    remainingPoints: z.number(),
    totalTickets: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const totalCost = input.ticketCount * TICKET_COST;

    const up = await zite.userPoints.findOne({ filters: { user: userId } });
    if (!up || (up.totalPoints ?? 0) < totalCost) throw new Error(`Poin tidak cukup. Kamu butuh ${totalCost} MP untuk ${input.ticketCount} tiket.`);

    const newPoints = (up.totalPoints ?? 0) - totalCost;
    await zite.userPoints.update({ id: up.id, record: { totalPoints: newPoints } });

    await zite.pointHistory.create({
      record: {
        activity: `Beli ${input.ticketCount} Tiket Undian`,
        user: userId,
        points: -totalCost,
        activityType: 'raffle_ticket',
      },
    });

    // Get current month raffle period
    const now = new Date();
    const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);

    await zite.pointRedemptions.create({
      record: {
        label: `${input.ticketCount} Tiket Undian - ${now.toLocaleDateString('id-ID', { month: 'long', year: 'numeric' })}`,
        user: userId,
        type: 'raffle',
        pointsSpent: totalCost,
        raffleTickets: input.ticketCount,
        expiresAt: monthEnd.toISOString(),
        status: 'active',
        item: null,
        recipientUserId: null,
      },
    });

    // Count total tickets this month
    const { records: allTickets } = await zite.pointRedemptions.findAll({
      filters: { user: userId, type: 'raffle', status: 'active' },
      limit: 500,
    });
    const totalTickets = allTickets.reduce((sum, t) => sum + (t.raffleTickets ?? 0), 0);

    return { success: true, remainingPoints: newPoints, totalTickets };
  },
});

files.apps/beranda-barter/src/api/cancelBarter:
import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Cancel a barter — if after accepted, canceller forfeits deposit as compensation to the other party',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    reason: z.string().min(1).max(200),
  }),
  outputSchema: z.object({ success: z.boolean(), depositForfeited: z.number(), compensationReceived: z.number(), adminFee: z.number() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    if (barter.status !== 'Menunggu' && barter.status !== 'Diterima') {
      throw new ZiteError('Barter tidak bisa dibatalkan pada status ini');
    }

    if (barter.status === 'Menunggu' && context.user.id !== initiatorId) {
      throw new ZiteError('Hanya pengirim penawaran yang bisa membatalkan pada tahap ini');
    }

    // Cancel the barter
    await zite.barterHistory.update({ id: input.barterId, record: { status: 'Dibatalkan' } });

    // Reset items
    const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
    const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
    if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Tersedia' } });
    if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Tersedia' } });

    let depositForfeited = 0;
    let compensationReceived = 0;
    let adminFee = 0;
    const otherUserId = context.user.id === initiatorId ? partnerId : initiatorId;

    // === BARTER INSURANCE: handle deposits on cancel ===
    if (barter.status === 'Diterima') {
      const { records: deposits } = await zite.barterDeposits.findAll({
        filters: { barter: input.barterId, status: 'Held' },
        limit: 10,
      });

      for (const dep of deposits) {
        const depUserId = Array.isArray(dep.user) ? dep.user[0] : dep.user;
        const depAmount = dep.amount ?? 0;
        if (!depUserId || depAmount <= 0) continue;

        if (depUserId === context.user.id) {
          // Canceller: FORFEIT deposit → goes to other party as compensation
          const isPremium = (dep.resolutionNote ?? '').includes('Premium');
          const fee = isPremium ? Math.ceil(depAmount * 3 / 100) : 0;
          const compensationAmount = depAmount - fee;

          depositForfeited += depAmount;
          adminFee += fee;

          await zite.barterDeposits.update({
            id: dep.id,
            record: { status: 'forfeited', resolutionNote: isPremium ? `Asuransi Penjaminan Barang (Premium) — Hangus karena pembatalan (admin fee ${fee} MP)` : 'Hangus karena pembatalan oleh pemilik deposit' },
          });

          // Give forfeited points (minus admin fee) to the other party
          if (otherUserId && compensationAmount > 0) {
            const otherPts = await zite.userPoints.findOne({ filters: { user: otherUserId } });
            if (otherPts) {
              await zite.userPoints.update({
                id: otherPts.id,
                record: { totalPoints: (otherPts.totalPoints ?? 0) + compensationAmount },
              });
            }
            await zite.pointHistory.create({
              record: {
                activity: isPremium ? `Kompensasi Asuransi Premium (${depAmount} MP - ${fee} MP admin)` : 'Kompensasi Jaminan Barter',
                user: otherUserId,
                points: compensationAmount,
                activityType: 'barter_deposit_compensation',
              },
            });
            compensationReceived += compensationAmount;
          }

          // Record admin fee in point history
          if (fee > 0) {
            await zite.pointHistory.create({
              record: {
                activity: `Biaya admin 3% asuransi premium`,
                user: context.user.id,
                points: -fee,
                activityType: 'premium_insurance_admin_fee',
              },
            });
          }
        } else {
          // Other party: REFUND their deposit
          const isRefundPremium = (dep.resolutionNote ?? '').includes('Premium');
          await zite.barterDeposits.update({
            id: dep.id,
            record: { status: 'Refunded', resolutionNote: isRefundPremium ? 'Asuransi Penjaminan Barang (Premium) — Dikembalikan karena pihak lain membatalkan' : 'Barter dibatalkan oleh pihak lain — deposit dikembalikan' },
          });

          const userPts = await zite.userPoints.findOne({ filters: { user: depUserId } });
          if (userPts) {
            await zite.userPoints.update({
              id: userPts.id,
              record: { totalPoints: (userPts.totalPoints ?? 0) + depAmount },
            });
          }
          await zite.pointHistory.create({
            record: {
              activity: 'Jaminan Barter Dikembalikan',
              user: depUserId,
              points: depAmount,
              activityType: 'barter_deposit_refund',
            },
          });
        }
      }

      // Penalty points for canceller
      const existingPoints = await zite.userPoints.findOne({ filters: { user: context.user.id } });
      if (existingPoints) {
        await zite.userPoints.update({
          id: existingPoints.id,
          record: { totalPoints: Math.max(0, (existingPoints.totalPoints ?? 0) - 5) },
        });
      }
      await zite.pointHistory.create({
        record: {
          activity: 'Membatalkan Barter (setelah diterima)',
          user: context.user.id,
          points: -5,
          activityType: 'barter_cancel_penalty',
        },
      });
    }

    const userName = context.user.firstName || context.user.email.split('@')[0];
    const hasPremium = barter.premiumInsuranceStatus === 'Disetujui';
    const premiumInfo = hasPremium ? `\n🛡️ Asuransi premium hangus (potongan admin 3%: ${adminFee} MP).` : '';
    const depositInfo = depositForfeited > 0 ? `\n🛡️ Jaminan ${depositForfeited} poin yang membatalkan hangus sebagai kompensasi.${premiumInfo}` : '';

    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: `❌ ${userName} membatalkan barter. Alasan: "${input.reason}"${barter.status === 'Diterima' ? ' (-5 poin penalti)' : ''}${depositInfo}`,
        type: 'System',
      },
    });

    // Notify the other party
    if (otherUserId) {
      const adminFeeMsg = adminFee > 0 ? ` (sudah dipotong admin 3%: ${adminFee} MP)` : '';
      const compensationMsg = compensationReceived > 0 ? ` 🛡️ Anda mendapat +${compensationReceived} poin kompensasi${adminFeeMsg}.` : '';
      await zite.notifications.create({
        record: {
          title: 'Barter Dibatalkan',
          body: `${userName} membatalkan barter. Alasan: "${input.reason.slice(0, 60)}"${compensationMsg}`,
          type: 'Barter',
          recipient: otherUserId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { success: true, depositForfeited, compensationReceived, adminFee };
  },
});

