    // Verify current password
    if (profile.mutariPassword !== input.currentPassword) {
      throw new ZiteError('Password lama tidak sesuai');
    }

    if (input.newPassword === input.currentPassword) {
      throw new ZiteError('Password baru harus berbeda dari password lama');
    }

    // TODO: OTP verification will be activated at end of project
    // if (input.otpCode) { verify OTP code here }

    await zite.userProfiles.update({
      id: profile.id,
      record: { mutariPassword: input.newPassword },
    });

    return { success: true };
  },
});

