import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const REVIEW_DEADLINE_DAYS = 7;

export default createEndpoint({
  description: 'Check for completed barters awaiting review and create reminder notifications',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({ remindersCreated: z.number() }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Find completed barters where this user is initiator or partner
    const { rows: pending } = await zite.sql({
      query: `
        SELECT b."id", b."title", b."completedAt",
               b."initiator", b."partner"
        FROM "BarterHistory" b
        WHERE b."status" = 'Selesai'
          AND b."completedAt" IS NOT NULL
          AND (b."initiator" @> to_jsonb(ARRAY[$1])
               OR b."partner" @> to_jsonb(ARRAY[$1]))
          AND NOT EXISTS (
            SELECT 1
            FROM "BarterReviews" br
            JOIN "BarterHistoryBarterReviews" link ON link."barterReviewsId" = br."id"
            WHERE link."barterHistoryId" = b."id"
              AND br."reviewer" @> to_jsonb(ARRAY[$1])
          )
      `,
      params: [userId],
    });

    if (pending.length === 0) return { remindersCreated: 0 };

    // For each pending review, check if we already sent a reminder notification today
    const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD

    let created = 0;
    for (const row of pending) {
      const barterId = row.id as string;
      const barterTitle = (row.title as string) || 'Barter';
      const completedAt = row.completedAt as string;

      // Calculate deadline
      const deadline = new Date(completedAt);
      deadline.setDate(deadline.getDate() + REVIEW_DEADLINE_DAYS);
      const now = new Date();
      if (now > deadline) continue; // expired, skip

      const daysLeft = Math.ceil((deadline.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

      // Check if we already created a review reminder notification for this barter today
      const { rows: existing } = await zite.sql({
        query: `
          SELECT 1 FROM "Notifications"
          WHERE "type" = 'review_reminder'
            AND "recipient" @> to_jsonb(ARRAY[$1])
            AND "linkPath" = $2
            AND created_at::date = $3::date
          LIMIT 1
        `,
        params: [userId, `/barter/${barterId}`, today],
      });

      if (existing.length > 0) continue; // already reminded today

      // Determine partner name
      const initiatorIds = row.initiator as string[];
      const partnerIds = row.partner as string[];
      const otherUserId = initiatorIds?.includes(userId) ? partnerIds?.[0] : initiatorIds?.[0];
      let otherName = 'partner';
      if (otherUserId) {
        const { records } = await zite.auth.findAllUsers({ filters: { id: otherUserId }, limit: 1 });
        if (records[0]) otherName = records[0].name || records[0].firstName || 'partner';
      }

      const urgency = daysLeft <= 2
        ? `⚠️ Sisa ${daysLeft} hari!`
        : `Sisa ${daysLeft} hari`;

      await zite.notifications.create({
        record: {
          title: `⏰ Review barter belum selesai!`,
          body: `Kamu belum mereview "${barterTitle}" dengan ${otherName}. ${urgency} sebelum 20 MP hangus. Review sekarang untuk dapatkan bonus 10 MP!`,
          type: 'review_reminder',
          recipient: userId,
          read: false,
          linkPath: `/barter/${barterId}`,
        },
      });
      created++;
    }

    return { remindersCreated: created };
  },
});

