import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Claim the reward for a completed weekly mission',
  authenticated: true,
  inputSchema: z.object({
    userMissionId: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    pointsEarned: z.number(),
    message: z.string(),
  }),
  execute: async ({ context, input }) => {
    const userId = context.user.id;

    const userMission = await zite.userMissions.findOne({ id: input.userMissionId });
    if (!userMission) throw new Error('Misi tidak ditemukan');

    // Verify ownership
    const owners = Array.isArray(userMission.user) ? userMission.user : [userMission.user];
    if (!owners.includes(userId)) throw new Error('Bukan misi kamu');

    if (userMission.status !== 'completed') {
      throw new Error('Misi belum selesai');
    }
    if (userMission.rewardClaimed) {
      throw new Error('Hadiah sudah diklaim');
    }

    // Get the linked mission for reward points
    const missionId = userMission.mission?.[0];
    if (!missionId) throw new Error('Misi tidak valid');

    const mission = await zite.weeklyMissions.findOne({ id: missionId });
    const rewardPoints = mission?.rewardPoints ?? 0;

    // Award points
    const userPoints = await zite.userPoints.findOne({ filters: { user: userId } });
    if (userPoints) {
      await zite.userPoints.update({
        id: userPoints.id,
        record: { totalPoints: (userPoints.totalPoints ?? 0) + rewardPoints },
      });
    }

    // Log history
    await zite.pointHistory.create({
      record: {
        activity: `Misi Selesai: ${mission?.title ?? 'Misi Mingguan'}`,
        user: userId,
        points: rewardPoints,
        activityType: 'mission_reward',
      },
    });

    // Mark as claimed
    await zite.userMissions.update({
      id: input.userMissionId,
      record: { status: 'claimed', rewardClaimed: true },
    });

    return {
      success: true,
      pointsEarned: rewardPoints,
      message: `+${rewardPoints} poin dari misi "${mission?.title}"! 🎉`,
    };
  },
});

