import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const IMMEDIATE_POINTS = 30; // Langsung cair
const HELD_POINTS = 20; // Ditahan sampai review diberikan
const REVIEW_DEADLINE_DAYS = 7;

function badgeId(points: number): string {
  if (points >= 10000) return 'elite';
  if (points >= 5000) return 'mentor';
  if (points >= 2500) return 'legenda';
  if (points >= 1000) return 'profesional';
  if (points >= 500) return 'terpercaya';
  if (points >= 200) return 'aktif';
  return 'pemula';
}

export default createEndpoint({
  description: 'Confirm barter completion — both parties must confirm. On completion, deposits are refunded. 30 MP given immediately, 20 MP held until review.',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    confirmed: z.boolean(),
    bothConfirmed: z.boolean(),
    pointsEarned: z.number(),
    pointsHeld: z.number(),
    depositRefunded: z.number(),
  }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    if (barter.status !== 'Diterima') {
      throw new ZiteError('Barter belum diterima');
    }

    if (!barter.deliveryMethodApproved) {
      throw new ZiteError('Tentukan metode tukar barang (COD atau Jasa Kirim) dan dapatkan persetujuan kedua pihak sebelum menyelesaikan barter');
    }

    const isInitiator = context.user.id === initiatorId;
    const updateField = isInitiator ? 'initiatorConfirmed' : 'partnerConfirmed';
    const alreadyConfirmed = isInitiator ? barter.initiatorConfirmed : barter.partnerConfirmed;

    if (alreadyConfirmed) {
      throw new ZiteError('Anda sudah mengonfirmasi');
    }

    await zite.barterHistory.update({ id: input.barterId, record: { [updateField]: true } });

    const otherConfirmed = isInitiator ? barter.partnerConfirmed : barter.initiatorConfirmed;
    const bothConfirmed = otherConfirmed === true;

    let pointsEarned = 0;
    let pointsHeld = 0;
    let depositRefunded = 0;

    if (bothConfirmed && !barter.pointsAwarded) {
      pointsEarned = IMMEDIATE_POINTS;
      pointsHeld = HELD_POINTS;

      const reviewDeadline = new Date(Date.now() + REVIEW_DEADLINE_DAYS * 24 * 60 * 60 * 1000);

      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          status: 'Selesai',
          completedAt: new Date().toISOString(),
          pointsAwarded: true,
        },
      });

      // Mark items as traded
      const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
      const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
      if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Sudah Ditukar' } });
      if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Sudah Ditukar' } });

      // === REFUND DEPOSITS ===
      const { records: deposits } = await zite.barterDeposits.findAll({
        filters: { barter: input.barterId, status: 'Held' },
        limit: 10,
      });

      const ADMIN_FEE_PERCENT = 3;

      for (const dep of deposits) {
        const depUserId = Array.isArray(dep.user) ? dep.user[0] : dep.user;
        const depAmount = dep.amount ?? 0;
        if (!depUserId || depAmount <= 0) continue;

        const isPremium = (dep.resolutionNote || '').includes('Premium');

        if (isPremium) {
          const adminFee = Math.ceil(depAmount * ADMIN_FEE_PERCENT / 100);
          const refundAmount = depAmount - adminFee;

          await zite.barterDeposits.update({
            id: dep.id,
            record: {
              status: 'Refunded',
              resolutionNote: `Barter selesai — asuransi premium ${depAmount} MP dikembalikan ${refundAmount} MP (potongan admin ${ADMIN_FEE_PERCENT}% = ${adminFee} MP)`,
            },
          });

          const userPts = await zite.userPoints.findOne({ filters: { user: depUserId } });
          if (userPts) {
            await zite.userPoints.update({
              id: userPts.id,
              record: { totalPoints: (userPts.totalPoints ?? 0) + refundAmount },
            });
          }

          await zite.pointHistory.create({
            record: {
              activity: `Asuransi Premium Dikembalikan (${depAmount} MP - ${ADMIN_FEE_PERCENT}% admin)`,
              user: depUserId,
              points: refundAmount,
              activityType: 'premium_insurance_refund',
            },
          });
          await zite.pointHistory.create({
            record: {
              activity: `Biaya Admin Asuransi Premium (${ADMIN_FEE_PERCENT}% dari ${depAmount} MP)`,
              user: depUserId,
              points: -adminFee,
              activityType: 'admin_fee',
            },
          });

          depositRefunded += refundAmount;
        } else {
          await zite.barterDeposits.update({
            id: dep.id,
            record: { status: 'Refunded', resolutionNote: 'Barter selesai — jaminan dikembalikan penuh' },
          });

          const userPts = await zite.userPoints.findOne({ filters: { user: depUserId } });
          if (userPts) {
            await zite.userPoints.update({
              id: userPts.id,
              record: { totalPoints: (userPts.totalPoints ?? 0) + depAmount },
            });
          }

          await zite.pointHistory.create({
            record: {
              activity: 'Jaminan Barter Dikembalikan',
              user: depUserId,
              points: depAmount,
              activityType: 'barter_deposit_refund',
            },
          });

          depositRefunded += depAmount;
        }
      }

      // Award IMMEDIATE points to both (30 MP), hold 20 MP
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        const existing = await zite.userPoints.findOne({ filters: { user: userId } });
        if (existing) {
          const newTotal = (existing.totalPoints ?? 0) + IMMEDIATE_POINTS;
          await zite.userPoints.update({
            id: existing.id,
            record: {
              totalPoints: newTotal,
              bartersCompleted: (existing.bartersCompleted ?? 0) + 1,
              currentBadge: badgeId(newTotal),
            },
          });
        }
        // Immediate points history
        await zite.pointHistory.create({
          record: {
            activity: `Barter Selesai (langsung cair)`,
            user: userId,
            points: IMMEDIATE_POINTS,
            activityType: 'barter_complete',
          },
        });
        // Held points history (pending)
        await zite.pointHistory.create({
          record: {
            activity: `Bonus Ditahan — Berikan review sebelum ${reviewDeadline.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })} untuk klaim +${HELD_POINTS} MP`,
            user: userId,
            points: 0, // not yet awarded
            activityType: 'review_held',
          },
        });
      }

      // Referral bonus check
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        const { records: pendingRefs } = await zite.referrals.findAll({
          filters: { referredUser: userId, status: 'Pending' },
          limit: 1,
        });
        if (pendingRefs.length === 0) continue;
        const ref = pendingRefs[0];
        const referrerId = Array.isArray(ref.referrer) ? ref.referrer[0] : ref.referrer;
        if (!referrerId) continue;

        const { records: allRefs } = await zite.referrals.findAll({
          filters: { referrer: referrerId, status: 'Completed' },
          limit: 200,
        });
        const completedCount = allRefs.length;
        const { getAffiliateTier } = await import('../lib/affiliate');
        const tier = getAffiliateTier(completedCount);
        const referralBonus = tier.pointsPerReferral;

        await zite.referrals.update({ id: ref.id, record: { status: 'Completed', bonusPoints: referralBonus } });
        const referrerPoints = await zite.userPoints.findOne({ filters: { user: referrerId } });
        if (referrerPoints) {
          await zite.userPoints.update({
            id: referrerPoints.id,
            record: { totalPoints: (referrerPoints.totalPoints ?? 0) + referralBonus },
          });
        }
        await zite.pointHistory.create({
          record: { activity: `Bonus Affiliate (${tier.name})`, user: referrerId, points: referralBonus, activityType: 'referral_bonus' },
        });
        await zite.notifications.create({
          record: {
            title: 'Bonus Affiliate! 🎁',
            body: `Teman yang kamu ajak berhasil menyelesaikan barter pertama! Kamu dapat +${referralBonus} MP (${tier.name}).`,
            type: 'Milestone',
            recipient: referrerId,
            read: false,
            linkPath: '/affiliate',
          },
        });
      }

      // System message — explain held points & deadline
      const hasPremium = deposits.some(d => (d.resolutionNote || '').includes('Premium'));
      let premiumMsg = '';
      if (hasPremium) {
        const premiumDep = deposits.find(d => (d.resolutionNote || '').includes('Premium'));
        const pAmt = premiumDep?.amount ?? 0;
        const aFee = Math.ceil(pAmt * ADMIN_FEE_PERCENT / 100);
        const rAmt = pAmt - aFee;
        premiumMsg = `\n🛡️ Asuransi Premium: ${pAmt} MP dikembalikan ${rAmt} MP per orang (potongan admin ${ADMIN_FEE_PERCENT}% = ${aFee} MP)`;
      }
      const deadlineStr = reviewDeadline.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `🎉 Barter berhasil diselesaikan!\n\n💰 Masing-masing mendapat +${IMMEDIATE_POINTS} MP (langsung cair).\n⏳ +${HELD_POINTS} MP lagi ditahan — berikan review untuk mencairkannya!\n\n📋 Total jika review diberikan: +${IMMEDIATE_POINTS + HELD_POINTS + 10} MP (${IMMEDIATE_POINTS} barter + ${HELD_POINTS} bonus review + 10 menulis review).\n\n⚠️ Batas waktu review: ${deadlineStr} (${REVIEW_DEADLINE_DAYS} hari). Setelah itu, ${HELD_POINTS} MP hangus.\n\n🛡️ Jaminan standar dikembalikan penuh.${premiumMsg}`,
          type: 'System',
        },
      });

      // Notify BOTH parties with clear explanation
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        await zite.notifications.create({
          record: {
            title: '🎉 Barter Selesai! +30 MP Cair',
            body: `Kamu mendapat +${IMMEDIATE_POINTS} MP langsung! ⏳ +${HELD_POINTS} MP lagi menunggu — berikan review sebelum ${deadlineStr} untuk mencairkannya. Jangan sampai hangus!`,
            type: 'Barter',
            recipient: userId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }

      // Schedule reminder notification after 24 hours (as a second notification)
      // We create it now with a note so the user sees it later in their notifications
      const reminderDate = new Date(Date.now() + 24 * 60 * 60 * 1000);
      const reminderDateStr = reminderDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'long' });
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        await zite.notifications.create({
          record: {
            title: '⏰ Jangan lupa review!',
            body: `Kamu masih punya +${HELD_POINTS} MP yang belum dicairkan. Berikan review barter sebelum ${deadlineStr} — atau poin hangus! Bonus tambahan +10 MP untuk menulis review.`,
            type: 'Barter',
            recipient: userId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    } else {
      const recipientId = isInitiator ? partnerId : initiatorId;
      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `✅ ${context.user.firstName || context.user.email.split("@")[0]} telah mengonfirmasi barter selesai. Menunggu konfirmasi pihak lain.`,
          type: 'System',
        },
      });
      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: 'Konfirmasi Barter',
            body: `${context.user.firstName || context.user.email.split("@")[0]} sudah konfirmasi barter selesai. Giliran Anda!`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    }

    return { confirmed: true, bothConfirmed, pointsEarned, pointsHeld, depositRefunded };
  },
});

