import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Create a new community for a city/region',
  authenticated: true,
  inputSchema: z.object({
    name: z.string().min(3).max(60),
    description: z.string().min(10).max(500),
    city: z.string().min(2),
    province: z.string().min(2),
    icon: z.string().optional(),
    rules: z.string().optional(),
    joinMode: z.string().optional(),
  }),
  outputSchema: z.object({
    community: z.object({
      id: z.string(),
      name: z.string(),
    }),
    pointsEarned: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Check if user already created a community in this city
    const { records: existing } = await zite.communities.findAll({
      filters: { creator: userId, city: input.city },
      limit: 1,
    });
    if (existing.length > 0) {
      throw new Error('Kamu sudah membuat komunitas di kota ini');
    }

    // Create community
    const community = await zite.communities.create({
      record: {
        name: input.name,
        description: input.description,
        city: input.city,
        province: input.province,
        icon: input.icon || '🏘️',
        rules: input.rules || 'Barter dengan jujur dan saling menghargai',
        status: 'active',
        memberCount: 1,
        barterCount: 0,
        joinMode: input.joinMode || 'open',
        creator: userId,
        banner: null,
      },
    });

    // Auto-join creator as Ketua
    await zite.communityMembers.create({
      record: {
        label: `${context.user.firstName || 'User'} - Ketua`,
        community: community.id,
        user: userId,
        role: 'ketua',
        status: 'active',
        pointsEarned: 0,
      },
    });

    // Award points to creator
    const bonusPoints = 50;
    const existing2 = await zite.userPoints.findOne({ filters: { user: userId } });
    if (existing2) {
      await zite.userPoints.update({
        id: existing2.id,
        record: { totalPoints: (existing2.totalPoints || 0) + bonusPoints },
      });
    }
    await zite.pointHistory.create({
      record: {
        activity: `Membuat komunitas "${input.name}"`,
        user: userId,
        points: bonusPoints,
        activityType: 'community_create',
      },
    });

    return {
      community: { id: community.id, name: community.name || input.name },
      pointsEarned: bonusPoints,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Create a post in a community feed',
  authenticated: true,
  inputSchema: z.object({
    communityId: z.string(),
    title: z.string().min(3),
    content: z.string().min(5),
    type: z.enum(['announcement', 'discussion', 'event', 'showcase', 'item_share']),
    mediaUrls: z.array(z.string()).optional(),
    sharedItemId: z.string().optional(),
  }),
  outputSchema: z.object({
    post: z.object({ id: z.string(), title: z.string() }),
    pointsEarned: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Check membership
    const { records: membership } = await zite.communityMembers.findAll({
      filters: { community: input.communityId, user: userId, status: 'active' },
      limit: 1,
    });
    if (membership.length === 0) throw new Error('Kamu harus bergabung ke komunitas ini dulu');

    // Only ketua/moderator can post announcements
    if (input.type === 'announcement' && !['ketua', 'moderator', 'Ketua', 'Moderator'].includes(membership[0].role || '')) {
      throw new Error('Hanya Ketua atau Moderator yang bisa membuat pengumuman');
    }

    // For item_share, fetch item info to enrich the post
    let enrichedContent = input.content;
    let enrichedTitle = input.title;
    let mediaForPost = input.mediaUrls?.map(url => ({ url, filename: 'media' })) || null;

    if (input.type === 'item_share' && input.sharedItemId) {
      const item = await zite.items.findOne({ id: input.sharedItemId });
      if (item) {
        enrichedTitle = input.title || `📦 ${item.title}`;
        enrichedContent = input.content || item.description || '';
        // Use item photo if no media provided
        if (!mediaForPost && item.photos && item.photos.length > 0) {
          mediaForPost = item.photos.slice(0, 3).map(p => ({ url: p.url, filename: p.filename || 'photo' }));
        }
        // Append item link marker at end of content
        enrichedContent += `\n\n🔗 /item/${input.sharedItemId}`;
      }
    }

    const post = await zite.communityPosts.create({
      record: {
        title: enrichedTitle,
        content: enrichedContent,
        community: input.communityId,
        author: userId,
        type: input.type === 'item_share' ? 'Showcase' : input.type,
        pinned: false,
        likesCount: 0,
        commentsCount: 0,
        media: mediaForPost,
      },
    });

    // Award points for posting (2 MP per post, event gets 3 MP)
    const pointsEarned = input.type === 'event' ? 3 : 2;
    const memberRecord = membership[0];
    await zite.communityMembers.update({
      id: memberRecord.id,
      record: { pointsEarned: (memberRecord.pointsEarned || 0) + pointsEarned },
    });

    return {
      post: { id: post.id, title: post.title || input.title },
      pointsEarned,
    };
  },
});

