import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { enforceBan } from '../lib/banCheck';

const SERVICE_DEPOSIT = 40;

export default createEndpoint({
  description: 'Create a service barter offer — trade an item for a service. Requires 40 MP deposit.',
  authenticated: true,
  inputSchema: z.object({
    serviceId: z.string(),
    offeredItemId: z.string(),
    message: z.string().optional(),
  }),
  outputSchema: z.object({
    barterId: z.string(),
  }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);

    // Validate service
    const service = await zite.services.findOne({ id: input.serviceId });
    if (!service) throw new ZiteError('Jasa tidak ditemukan');
    if (service.status !== 'Tersedia') throw new ZiteError('Jasa ini sedang tidak tersedia');

    const providerId = Array.isArray(service.provider) ? service.provider[0] : service.provider;
    if (providerId === context.user.id) {
      throw new ZiteError('Tidak bisa menawarkan barter untuk jasa sendiri');
    }

    // Validate offered item
    const item = await zite.items.findOne({ id: input.offeredItemId });
    if (!item) throw new ZiteError('Barang yang ditawarkan tidak ditemukan');
    const ownerIds = Array.isArray(item.owner) ? item.owner : [item.owner];
    if (!ownerIds.includes(context.user.id)) {
      throw new ZiteError('Barang ini bukan milik Anda');
    }
    if (item.status !== 'Tersedia') {
      throw new ZiteError('Barang ini sedang dalam negosiasi atau sudah ditukar');
    }

    // Check deposit — 40 MP for service barter
    const { records: pointRecords } = await zite.userPoints.findAll({
      filters: { user: context.user.id },
      limit: 1,
    });
    const userPoints = pointRecords[0];
    const currentPoints = userPoints?.totalPoints ?? 0;
    if (currentPoints < SERVICE_DEPOSIT) {
      throw new ZiteError(
        `Poin tidak cukup untuk deposit barter jasa. Kamu butuh ${SERVICE_DEPOSIT} MP, tapi hanya punya ${currentPoints} MP. Deposit jasa lebih tinggi karena risiko lebih besar.`
      );
    }

    // Deduct deposit
    if (userPoints) {
      await zite.userPoints.update({
        id: userPoints.id,
        record: { totalPoints: currentPoints - SERVICE_DEPOSIT },
      });
    }

    // Log deposit
    await zite.pointHistory.create({
      record: {
        activity: `Deposit Barter Jasa: ${item.title} ↔ ${service.title}`,
        user: context.user.id,
        points: -SERVICE_DEPOSIT,
        activityType: 'service_deposit',
      },
    });

    const deadlineDays = service.completionDays ?? 7;

    // Create service barter record
    const barter = await zite.serviceBarters.create({
      record: {
        title: `${item.title || 'Barang'} ↔ ${service.title || 'Jasa'}`,
        itemOwner: context.user.id,
        serviceProvider: providerId || null,
        offeredItem: input.offeredItemId,
        requestedService: input.serviceId,
        status: 'Menunggu',
        notes: input.message || null,
        deadlineDays,
        deadlineAt: null,
        startedAt: null,
        completedAt: null,
        itemOwnerConfirmed: false,
        providerConfirmed: false,
        proofUploaded: false,
        completionProof: null,
      },
    });

    // Create deposit record
    await zite.barterDeposits.create({
      record: {
        barter: null,
        user: context.user.id,
        amount: SERVICE_DEPOSIT,
        status: 'Held',
        resolutionNote: `Service barter: ${barter.id}`,
      },
    });

    // Notify service provider
    await zite.notifications.create({
      record: {
        title: '🛠️ Penawaran Barter Jasa!',
        body: `${context.user.firstName || context.user.email.split('@')[0]} ingin menukar "${item.title}" dengan jasa "${service.title}" Anda`,
        type: 'Barter',
        recipient: providerId || null,
        read: false,
        linkPath: `/service-barter/${barter.id}`,
      },
    });

    // Update statuses
    await zite.items.update({ id: input.offeredItemId, record: { status: 'Negosiasi' } });
    await zite.services.update({ id: input.serviceId, record: { status: 'Sedang Dikerjakan' } });

    return { barterId: barter.id };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
