import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Perform daily check-in, awards points and tracks streaks',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    success: z.boolean(),
    alreadyCheckedIn: z.boolean(),
    streakCount: z.number(),
    pointsEarned: z.number(),
    streakBonus: z.boolean(),
    streakBonusPoints: z.number(),
    message: z.string(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;
    const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

    // Check if already checked in today
    const existing = await zite.dailyCheckins.findOne({
      filters: { user: userId, checkinDate: today },
    });

    if (existing) {
      return {
        success: true,
        alreadyCheckedIn: true,
        streakCount: existing.streakCount ?? 1,
        pointsEarned: 0,
        streakBonus: false,
        streakBonusPoints: 0,
        message: 'Kamu sudah check-in hari ini! 🎉',
      };
    }

    // Find yesterday's check-in for streak
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayStr = yesterday.toISOString().split('T')[0];

    const yesterdayCheckin = await zite.dailyCheckins.findOne({
      filters: { user: userId, checkinDate: yesterdayStr },
    });

    const streakCount = yesterdayCheckin ? (yesterdayCheckin.streakCount ?? 0) + 1 : 1;
    const isStreakBonus = streakCount % 7 === 0; // Every 7 days
    const basePoints = 5;
    // Streak multiplier: extra 2 pts per streak day, capped
    const streakExtra = Math.min(streakCount - 1, 6) * 2;
    const streakBonusPoints = isStreakBonus ? 50 : 0;
    const totalPoints = basePoints + streakExtra + streakBonusPoints;

    // Create check-in record
    await zite.dailyCheckins.create({
      record: {
        checkinDate: today,
        user: userId,
        streakCount,
        pointsEarned: totalPoints,
        streakBonus: isStreakBonus,
      },
    });

    // Award points
    const userPoints = await zite.userPoints.findOne({ filters: { user: userId } });
    if (userPoints) {
      const newTotal = (userPoints.totalPoints ?? 0) + totalPoints;
      const newBadge = newTotal >= 10000 ? 'elite' : newTotal >= 5000 ? 'mentor' : newTotal >= 2500 ? 'legenda' : newTotal >= 1000 ? 'profesional' : newTotal >= 500 ? 'terpercaya' : newTotal >= 200 ? 'aktif' : 'pemula';
      await zite.userPoints.update({
        id: userPoints.id,
        record: { totalPoints: newTotal, currentBadge: newBadge },
      });
    }

    // Log to point history
    await zite.pointHistory.create({
      record: {
        activity: isStreakBonus
          ? `Check-in Harian (Streak ${streakCount} hari! 🔥)`
          : `Check-in Harian (Hari ke-${streakCount})`,
        user: userId,
        points: totalPoints,
        activityType: 'daily_checkin',
      },
    });

    // Update daily_checkin mission progress
    const weekStart = getWeekStart();
    const { records: userMissions } = await zite.userMissions.findAll({
      filters: { user: userId, weekStart, status: 'active' },
      limit: 50,
    });
    // Find linked mission record for daily_checkin type
    for (const um of userMissions) {
      if (um.mission && um.mission.length > 0) {
        const missionRecord = await zite.weeklyMissions.findOne({ id: um.mission[0] });
        if (missionRecord?.missionType === 'daily_checkin') {
          const newProgress = Math.min((um.currentProgress ?? 0) + 1, missionRecord.targetCount ?? 5);
          const completed = newProgress >= (missionRecord.targetCount ?? 5);
          await zite.userMissions.update({
            id: um.id,
            record: {
              currentProgress: newProgress,
              status: completed ? 'completed' : 'active',
            },
          });
        }
      }
    }

    let message = `+${totalPoints} poin! `;
    if (isStreakBonus) {
      message += `🔥 Streak ${streakCount} hari! Bonus ekstra +${streakBonusPoints} poin!`;
    } else if (streakCount > 1) {
      message += `🔥 Streak ${streakCount} hari berturut-turut!`;
    } else {
      message += 'Selamat check-in!';
    }

    return {
      success: true,
      alreadyCheckedIn: false,
      streakCount,
      pointsEarned: totalPoints,
      streakBonus: isStreakBonus,
      streakBonusPoints,
      message,
    };
  },
});

function getWeekStart(): string {
  const now = new Date();
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? -6 : 1); // Monday
  const monday = new Date(now.setDate(diff));
  return monday.toISOString().split('T')[0];
}

