import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const PRIZES = [
  { placement: 1, points: 5000, badge: '🏆 Lucky Winner Gold' },
  { placement: 2, points: 2500, badge: '🥈 Lucky Winner Silver' },
  { placement: 3, points: 1000, badge: '🥉 Lucky Winner Bronze' },
];

function getDrawMonth(date: Date) {
  // Draw month is the PREVIOUS month (we draw on the 1st for last month's tickets)
  const prev = new Date(date.getFullYear(), date.getMonth() - 1, 1);
  return `${prev.getFullYear()}-${String(prev.getMonth() + 1).padStart(2, '0')}`;
}

function getCurrentMonth(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
}

export default createEndpoint({
  description: 'Check if a monthly raffle draw is due and perform it (lazy draw on visit)',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    drawn: z.boolean(),
    drawMonth: z.string().optional(),
    winners: z.array(z.object({
      placement: z.number(),
      userName: z.string(),
      prizePoints: z.number(),
      prizeBadge: z.string(),
      ticketsUsed: z.number(),
    })).optional(),
  }),
  execute: async ({ context }) => {
    const now = new Date();

    // Only draw if we're past the 1st of the month (draw for previous month)
    // Check if a draw already exists for the previous month
    const targetMonth = getDrawMonth(now);

    const { records: existingDraws } = await zite.raffleDraws.findAll({
      filters: { drawMonth: targetMonth },
      limit: 1,
    });

    if (existingDraws.length > 0) {
      // Already drawn
      return { drawn: false };
    }

    // Get all raffle tickets for the previous month
    // Tickets have expiresAt set to end of month they were bought in
    const prevMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const prevMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);

    const { records: allTickets } = await zite.pointRedemptions.findAll({
      limit: 2000,
    });

    // Filter to raffle tickets from the target month
    const monthTickets = allTickets.filter(t => {
      const tp = (t.type || '').toLowerCase();
      if (tp !== 'raffle' && tp !== 'raffle ticket') return false;
      if (!t.expiresAt) return false;
      const expDate = new Date(t.expiresAt);
      return expDate >= prevMonthStart && expDate <= new Date(prevMonthEnd.getTime() + 86400000);
    });

    if (monthTickets.length === 0) {
      // No tickets sold — create empty draw marker
      await zite.raffleDraws.create({
        record: {
          drawMonth: targetMonth,
          placement: 0,
          prizePoints: 0,
          prizeBadge: 'Tidak ada peserta',
          ticketsUsed: 0,
          drawnAt: now.toISOString(),
          winner: null,
        },
      });
      return { drawn: true, drawMonth: targetMonth, winners: [] };
    }

    // Build weighted pool: each ticket = 1 entry
    const entries: string[] = [];
    const ticketCountByUser: Record<string, number> = {};
    for (const t of monthTickets) {
      const uid = Array.isArray(t.user) ? t.user[0] : t.user;
      if (!uid) continue;
      const count = t.raffleTickets ?? 1;
      ticketCountByUser[uid] = (ticketCountByUser[uid] || 0) + count;
      for (let i = 0; i < count; i++) entries.push(uid);
    }

    if (entries.length === 0) {
      return { drawn: true, drawMonth: targetMonth, winners: [] };
    }

    // Shuffle and pick winners (no duplicates)
    const shuffled = entries.sort(() => Math.random() - 0.5);
    const pickedUserIds: string[] = [];
    for (const uid of shuffled) {
      if (!pickedUserIds.includes(uid)) {
        pickedUserIds.push(uid);
        if (pickedUserIds.length >= 3) break;
      }
    }

    // Award prizes
    const winners: { placement: number; userName: string; prizePoints: number; prizeBadge: string; ticketsUsed: number }[] = [];

    for (let i = 0; i < pickedUserIds.length; i++) {
      const uid = pickedUserIds[i];
      const prize = PRIZES[i];

      // Get user name
      const { records: users } = await zite.auth.findAllUsers({ filters: { id: uid }, limit: 1 });
      const userName = users[0]?.firstName || users[0]?.name || users[0]?.email || 'User';

      // Award points
      const up = await zite.userPoints.findOne({ filters: { user: uid } });
      if (up) {
        await zite.userPoints.update({
          id: up.id,
          record: { totalPoints: (up.totalPoints ?? 0) + prize.points },
        });
      }

      // Record point history
      await zite.pointHistory.create({
        record: {
          activity: `🎉 Pemenang Undian ${prize.badge}`,
          user: uid,
          points: prize.points,
          activityType: 'raffle_prize',
        },
      });

      // Send notification
      await zite.notifications.create({
        record: {
          title: `🎉 Selamat! Kamu Pemenang Undian!`,
          body: `Kamu memenangkan undian bulanan MUTARI sebagai juara ${prize.placement}! Hadiah: ${prize.points.toLocaleString('id-ID')} MP + ${prize.badge}`,
          type: 'System',
          recipient: uid,
          read: false,
          linkPath: '/point-shop',
        },
      });

      // Save draw result
      await zite.raffleDraws.create({
        record: {
          drawMonth: targetMonth,
          winner: uid,
          placement: prize.placement,
          prizePoints: prize.points,
          prizeBadge: prize.badge,
          ticketsUsed: ticketCountByUser[uid] || 0,
          drawnAt: now.toISOString(),
        },
      });

      winners.push({
        placement: prize.placement,
        userName,
        prizePoints: prize.points,
        prizeBadge: prize.badge,
        ticketsUsed: ticketCountByUser[uid] || 0,
      });
    }

    // Mark used tickets as 'used'
    for (const t of monthTickets) {
      await zite.pointRedemptions.update({
        id: t.id,
        record: { status: 'used' },
      });
    }

    return { drawn: true, drawMonth: targetMonth, winners };
  },
});

