import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Finalizes a challenge: ranks participants, distributes reward points and badges',
  authenticated: true,
  inputSchema: z.object({ challengeId: z.string() }),
  outputSchema: z.object({
    success: z.boolean(),
    winnersCount: z.number(),
    totalPointsDistributed: z.number(),
  }),
  execute: async ({ input }) => {
    const challenge = await zite.challenges.findOne({ id: input.challengeId });
    if (!challenge) throw new ZiteError('Challenge not found', 'NOT_FOUND');
    if (challenge.status !== 'Aktif' && challenge.status !== 'Selesai') {
      throw new ZiteError('Challenge harus berstatus Aktif untuk diselesaikan', 'BAD_REQUEST');
    }

    // Get all participants sorted by progress DESC
    const { rows: participants } = await zite.sql({
      query: `
        SELECT cp.id, cp."progress", cp."user", cp."status",
          u."name" AS "userName", u."email" AS "userEmail"
        FROM "ChallengeParticipants" cp
        JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
        LEFT JOIN "ziteUsers" u ON cp."user" @> to_jsonb(ARRAY[u.id::text])
        WHERE cp2c."challengesId"::text = $1
        ORDER BY cp."progress" DESC NULLS LAST
      `,
      params: [input.challengeId],
    });

    if (participants.length === 0) {
      // Just mark as Selesai
      await zite.challenges.update({ id: input.challengeId, record: { status: 'Selesai' } });
      return { success: true, winnersCount: 0, totalPointsDistributed: 0 };
    }

    let totalPointsDistributed = 0;
    const rewardMap: Record<number, number> = {};
    if (challenge.reward1st) rewardMap[0] = challenge.reward1st;
    if (challenge.reward2nd) rewardMap[1] = challenge.reward2nd;
    if (challenge.reward3rd) rewardMap[2] = challenge.reward3rd;

    const badgeMap: Record<number, string> = {};
    if (challenge.badge1st) badgeMap[0] = challenge.badge1st;

    for (let i = 0; i < participants.length; i++) {
      const p = participants[i] as any;
      const userId = Array.isArray(p.user) ? p.user[0] : p.user;
      if (!userId) continue;

      const rank = i + 1;
      const isWinner = i < 3 && rewardMap[i];
      const rewardPoints = rewardMap[i] ?? challenge.participationReward ?? 0;
      const badge = badgeMap[i] ?? (challenge.badgeParticipant || null);
      const status = i === 0 ? 'Pemenang' : (rewardPoints > 0 ? 'Reward Diterima' : 'Target Tercapai');

      // Update participant rank & status
      await zite.challengeParticipants.update({
        id: p.id,
        record: { rank, status },
      });

      if (rewardPoints > 0) {
        totalPointsDistributed += rewardPoints;

        // Add points to user
        const { records: userPts } = await zite.userPoints.findAll({
          filters: { user: userId },
          limit: 1,
        });

        if (userPts[0]) {
          await zite.userPoints.update({
            id: userPts[0].id,
            record: {
              totalPoints: (userPts[0].totalPoints ?? 0) + rewardPoints,
            },
          });
        } else {
          await zite.userPoints.create({
            record: {
              label: `${p.userEmail ?? 'User'}`,
              user: userId,
              totalPoints: rewardPoints,
              itemsUploaded: 0,
              bartersCompleted: 0,
              likesReceived: 0,
              currentBadge: 'pemula',
            },
          });
        }

        // Record point history
        const activityName = i < 3
          ? `🏆 Juara ${rank} Challenge: ${challenge.title}`
          : `✅ Partisipasi Challenge: ${challenge.title}`;

        await zite.pointHistory.create({
          record: {
            activity: activityName,
            user: userId,
            points: rewardPoints,
            activityType: 'challenge_reward',
          },
        });

        // Send notification
        await zite.notifications.create({
          record: {
            title: i < 3
              ? `🏆 Selamat! Kamu Juara ${rank}!`
              : `🎉 Reward Challenge Diterima`,
            body: i < 3
              ? `Kamu meraih Juara ${rank} di challenge "${challenge.title}" dan mendapat ${rewardPoints.toLocaleString()} poin!`
              : `Terima kasih berpartisipasi di challenge "${challenge.title}". Kamu mendapat ${rewardPoints.toLocaleString()} poin!`,
            type: 'Milestone',
            recipient: userId,
            read: false,
            linkPath: `/challenge/${input.challengeId}`,
          },
        });
      }
    }

    // Mark challenge as Selesai
    await zite.challenges.update({ id: input.challengeId, record: { status: 'Selesai' } });

    return {
      success: true,
      winnersCount: Math.min(participants.length, 3),
      totalPointsDistributed,
    };
  },
});

