import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const pairSchema = z.object({
  myItemId: z.string(),
  myItemTitle: z.string(),
  myItemPhoto: z.string(),
  myItemCondition: z.string(),
  myEstMin: z.number(),
  myEstMax: z.number(),
  theirItemId: z.string(),
  theirItemTitle: z.string(),
  theirItemPhoto: z.string(),
  theirItemCondition: z.string(),
  theirEstMin: z.number(),
  theirEstMax: z.number(),
  theirOwnerName: z.string(),
  theirLocation: z.string(),
  matchScore: z.number(),
  reasons: z.array(z.string()),
});

export default createEndpoint({
  description: 'AI Makro: cocokkan SEMUA barang user dengan SEMUA barang orang lain',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    pairs: z.array(pairSchema),
    myItemCount: z.number(),
    otherItemCount: z.number(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // 1. Get all my available items
    const { records: myItems } = await zite.items.findAll({
      filters: { owner: userId, status: 'Tersedia' },
      limit: 100,
    });

    if (myItems.length === 0) {
      return { pairs: [], myItemCount: 0, otherItemCount: 0 };
    }

    // 2. Get all other users' available items via SQL for efficiency
    const result = await zite.sql({
      query: `
        SELECT i.*, u."name" AS "ownerName"
        FROM "Items" i
        LEFT JOIN "ziteUsers" u ON u.id = i."owner"->>0
        WHERE i."status" = 'Tersedia'
          AND (i."owner"->>0 != $1 OR i."owner"->>0 IS NULL)
        ORDER BY i.created_at DESC
        LIMIT 200
      `,
      params: [userId],
    });

    const otherItems = result.rows;

    const condRank: Record<string, number> = { 'Baru': 4, 'Seperti Baru': 3, 'Baik': 2, 'Cukup': 1 };

    type Pair = z.infer<typeof pairSchema>;
    const allPairs: Pair[] = [];

    // 3. Score every (myItem, otherItem) combination
    for (const my of myItems) {
      const myMin = (my.estimatedValueMin as number) ?? 0;
      const myMax = (my.estimatedValueMax as number) ?? 0;
      const myMid = (myMin + myMax) / 2;
      const myCondRank = condRank[my.condition || ''] ?? 2;
      const myPhoto = (my.photos && Array.isArray(my.photos) && my.photos.length > 0)
        ? (my.photos[0] as { url: string })?.url || '' : '';

      for (const other of otherItems) {
        const oMin = (other.estimatedValueMin as number) ?? 0;
        const oMax = (other.estimatedValueMax as number) ?? 0;
        const oMid = (oMin + oMax) / 2;
        const oCondition = String(other.condition || '');
        const oCondRank = condRank[oCondition] ?? 2;

        let score = 50;
        const reasons: string[] = [];

        // Value similarity (up to 35 pts)
        if (myMid > 0 && oMid > 0) {
          const diff = Math.abs(myMid - oMid);
          const ratio = diff / Math.max(myMid, oMid);
          score += Math.max(0, 35 - ratio * 70);
          if (ratio < 0.1) reasons.push('Nilai sangat seimbang');
          else if (ratio < 0.25) reasons.push('Nilai mendekati');
          else if (ratio < 0.4) reasons.push('Nilai cukup dekat');
        } else {
          // Skip pairs with no price estimate
          continue;
        }

        // Condition match (up to 15 pts)
        const condDiff = Math.abs(myCondRank - oCondRank);
        score += Math.max(0, 15 - condDiff * 5);
        if (condDiff === 0) reasons.push('Kondisi setara');
        else if (oCondRank >= myCondRank) reasons.push('Kondisi sebanding');

        const finalScore = Math.min(99, Math.max(20, Math.round(score)));

        // Only include reasonably good matches
        if (finalScore < 55) continue;

        const photos = other.photos as { url: string }[] | null;
        const oPhoto = photos?.[0]?.url || '';

        allPairs.push({
          myItemId: my.id,
          myItemTitle: my.title || 'Tanpa judul',
          myItemPhoto: myPhoto,
          myItemCondition: my.condition || '-',
          myEstMin: myMin,
          myEstMax: myMax,
          theirItemId: String(other.id),
          theirItemTitle: String(other.title || 'Tanpa judul'),
          theirItemPhoto: oPhoto,
          theirItemCondition: oCondition || '-',
          theirEstMin: oMin,
          theirEstMax: oMax,
          theirOwnerName: String(other.ownerName || 'Pemilik'),
          theirLocation: String(other.location || '-'),
          matchScore: finalScore,
          reasons,
        });
      }
    }

    // Sort by score desc, take top 20
    allPairs.sort((a, b) => b.matchScore - a.matchScore);
    const top = allPairs.slice(0, 20);

    return {
      pairs: top,
      myItemCount: myItems.length,
      otherItemCount: otherItems.length,
    };
  },
});

