import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get deposit/insurance status for a barter',
  authenticated: true,
  inputSchema: z.object({ barterId: z.string() }),
  outputSchema: z.object({
    deposits: z.array(z.object({
      id: z.string(),
      userId: z.string(),
      amount: z.number(),
      status: z.string(),
      resolutionNote: z.string().nullable(),
      createdAt: z.string().nullable(),
    })),
    myDeposit: z.object({
      amount: z.number(),
      status: z.string(),
    }).nullable(),
    totalHeld: z.number(),
    depositRequired: z.number(),
  }),
  execute: async ({ input, context }) => {
    const DEPOSIT_AMOUNT = 20;

    const { records } = await zite.barterDeposits.findAll({
      filters: { barter: input.barterId },
      limit: 10,
    });

    const deposits = records.map(d => ({
      id: d.id,
      userId: Array.isArray(d.user) ? d.user[0] : d.user || '',
      amount: d.amount ?? 0,
      status: d.status ?? 'Held',
      resolutionNote: d.resolutionNote ?? null,
      createdAt: d.createdAt ?? null,
    }));

    const myDeposit = deposits.find(d => d.userId === context.user.id);

    return {
      deposits,
      myDeposit: myDeposit ? { amount: myDeposit.amount, status: myDeposit.status } : null,
      totalHeld: deposits.filter(d => d.status === 'Held').reduce((s, d) => s + d.amount, 0),
      depositRequired: DEPOSIT_AMOUNT,
    };
  },
});

