import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get barter history for the current user (barang + jasa)',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    history: z.array(z.object({
      id: z.string(),
      title: z.string(),
      type: z.enum(['barang', 'jasa']),
      partnerName: z.string(),
      offeredItemTitle: z.string(),
      offeredItemPhoto: z.string().nullable(),
      requestedItemTitle: z.string(),
      requestedItemPhoto: z.string().nullable(),
      status: z.string(),
      notes: z.string(),
      createdAt: z.string(),
      completedAt: z.string().nullable(),
      isInitiator: z.boolean(),
      premiumInsurance: z.object({
        active: z.boolean(),
        amount: z.number(),
        adminFee: z.number(),
        compensationReceived: z.number(),
        myRole: z.enum(['canceller', 'receiver', 'none']),
      }).nullable(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // === BARTER BARANG ===
    const barterRows = await zite.sql({
      query: `
        SELECT b.id, b."title", b."status", b.created_at AS "createdAt", b."completedAt",
          b."notes", b."premiumInsuranceStatus", b."premiumInsuranceAmount",
          b."offeredItem", b."requestedItem", b."initiator", b."partner",
          CASE WHEN b."initiator"->>0 = $1 THEN true ELSE false END AS "isInitiator"
        FROM "BarterHistory" b
        WHERE b."initiator"->>0 = $1 OR b."partner"->>0 = $1
        ORDER BY b.created_at DESC LIMIT 100
      `,
      params: [userId],
    });

    // Collect item IDs
    const itemIds = new Set<string>();
    const userIds = new Set<string>();
    for (const r of barterRows.rows) {
      const offered = parseLinked(r.offeredItem);
      const requested = parseLinked(r.requestedItem);
      if (offered) itemIds.add(offered);
      if (requested) itemIds.add(requested);
      const init = parseLinked(r.initiator);
      const part = parseLinked(r.partner);
      if (init) userIds.add(init);
      if (part) userIds.add(part);
    }

    // === BARTER JASA ===
    const serviceRows = await zite.sql({
      query: `
        SELECT sb.id, sb."title", sb."status", sb.created_at AS "createdAt", sb."completedAt",
          sb."notes", sb."offeredItem", sb."requestedService",
          sb."itemOwner", sb."serviceProvider",
          CASE WHEN sb."itemOwner"->>0 = $1 THEN true ELSE false END AS "isItemOwner"
        FROM "ServiceBarters" sb
        WHERE sb."itemOwner"->>0 = $1 OR sb."serviceProvider"->>0 = $1
        ORDER BY sb.created_at DESC LIMIT 100
      `,
      params: [userId],
    });

    const serviceIds = new Set<string>();
    for (const r of serviceRows.rows) {
      const offered = parseLinked(r.offeredItem);
      if (offered) itemIds.add(offered);
      const svc = parseLinked(r.requestedService);
      if (svc) serviceIds.add(svc);
      const owner = parseLinked(r.itemOwner);
      const prov = parseLinked(r.serviceProvider);
      if (owner) userIds.add(owner);
      if (prov) userIds.add(prov);
    }

    // Batch fetch items
    const itemMap = new Map<string, { title: string; photo: string | null }>();
    if (itemIds.size > 0) {
      const itemRes = await zite.sql({
        query: `SELECT id, "title", "photos" FROM "Items" WHERE id = ANY($1)`,
        params: [Array.from(itemIds)],
      });
      for (const r of itemRes.rows) {
        const photos = r.photos as any;
        const photo = Array.isArray(photos) && photos.length > 0 ? (photos[0]?.url || null) : null;
        itemMap.set(String(r.id), { title: String(r.title || 'Barang'), photo });
      }
    }

    // Batch fetch services
    const svcMap = new Map<string, { title: string; photo: string | null }>();
    if (serviceIds.size > 0) {
      const svcRes = await zite.sql({
        query: `SELECT id, "title", "portfolio" FROM "Services" WHERE id = ANY($1)`,
        params: [Array.from(serviceIds)],
      });
      for (const r of svcRes.rows) {
        const port = r.portfolio as any;
        const photo = Array.isArray(port) && port.length > 0 ? (port[0]?.url || null) : null;
        svcMap.set(String(r.id), { title: String(r.title || 'Jasa'), photo });
      }
    }

    // Batch fetch users
    const userMap = new Map<string, string>();
    if (userIds.size > 0) {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: { in: Array.from(userIds) } },
        limit: 200,
      });
      for (const u of users) {
        userMap.set(u.id, u.name || u.email);
      }
    }

    // Build history from barter barang
    const history: any[] = [];

    for (const r of barterRows.rows) {
      const isInit = Boolean(r.isInitiator);
      const partnerId = isInit ? parseLinked(r.partner) : parseLinked(r.initiator);
      const offeredId = parseLinked(r.offeredItem);
      const requestedId = parseLinked(r.requestedItem);
      const offered = offeredId ? itemMap.get(offeredId) : null;
      const requested = requestedId ? itemMap.get(requestedId) : null;

      // Premium insurance
      let premiumInsurance: {
        active: boolean;
        amount: number;
        adminFee: number;
        compensationReceived: number;
        myRole: 'canceller' | 'receiver' | 'none';
      } | null = null;
      if (String(r.premiumInsuranceStatus) === 'Disetujui' && String(r.status) === 'Dibatalkan') {
        const amount = Number(r.premiumInsuranceAmount ?? 0);
        const adminFee = Math.ceil(amount * 3 / 100);
        premiumInsurance = {
          active: true,
          amount,
          adminFee,
          compensationReceived: amount - adminFee,
          myRole: 'none',
        };
      }

      history.push({
        id: String(r.id),
        title: String(r.title || 'Barter'),
        type: 'barang' as const,
        partnerName: partnerId ? (userMap.get(partnerId) || 'Pengguna') : 'Pengguna',
        offeredItemTitle: offered?.title || 'Barang',
        offeredItemPhoto: offered?.photo || null,
        requestedItemTitle: requested?.title || 'Barang',
        requestedItemPhoto: requested?.photo || null,
        status: String(r.status || 'Menunggu'),
        notes: String(r.notes || ''),
        createdAt: String(r.createdAt || ''),
        completedAt: r.completedAt ? String(r.completedAt) : null,
        isInitiator: isInit,
        premiumInsurance,
      });
    }

    // Build history from service barters
    for (const r of serviceRows.rows) {
      const isItemOwner = Boolean(r.isItemOwner);
      const partnerId = isItemOwner ? parseLinked(r.serviceProvider) : parseLinked(r.itemOwner);
      const offeredId = parseLinked(r.offeredItem);
      const serviceId = parseLinked(r.requestedService);
      const offered = offeredId ? itemMap.get(offeredId) : null;
      const svc = serviceId ? svcMap.get(serviceId) : null;

      // Map service barter status to standard display status
      const rawStatus = String(r.status || 'Menunggu');
      let displayStatus = rawStatus;
      if (rawStatus === 'Dalam Pengerjaan' || rawStatus === 'Menunggu Bukti') displayStatus = 'Diterima';

      history.push({
        id: String(r.id),
        title: String(r.title || 'Barter Jasa'),
        type: 'jasa' as const,
        partnerName: partnerId ? (userMap.get(partnerId) || 'Pengguna') : 'Pengguna',
        offeredItemTitle: offered?.title || 'Barang',
        offeredItemPhoto: offered?.photo || null,
        requestedItemTitle: svc?.title || 'Jasa',
        requestedItemPhoto: svc?.photo || null,
        status: displayStatus,
        notes: String(r.notes || ''),
        createdAt: String(r.createdAt || ''),
        completedAt: r.completedAt ? String(r.completedAt) : null,
        isInitiator: isItemOwner,
        premiumInsurance: null,
      });
    }

    // Sort all by createdAt desc
    history.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    return { history };
  },
});

function parseLinked(val: unknown): string | null {
  if (!val) return null;
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      if (Array.isArray(parsed)) return parsed[0] || null;
    } catch { return val; }
  }
  if (Array.isArray(val)) return (val as string[])[0] || null;
  return String(val);
}

