import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Gets challenge detail with leaderboard',
  authenticated: true,
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({ challenge: z.any() }),
  execute: async ({ input, context }) => {
    const challenge = await zite.challenges.findOne({ id: input.id });
    if (!challenge) throw new Error('Challenge not found');

    // Auto-update progress if challenge is active
    if (challenge.status === 'Aktif' && challenge.type !== 'Custom Target') {
      try {
        const startDate = challenge.startDate ?? challenge.createdAt ?? '2020-01-01';
        const endDate = challenge.endDate ?? new Date().toISOString();

        // Get participants
        const { rows: parts } = await zite.sql({
          query: `
            SELECT cp.id, cp."user"->>0 AS "userId"
            FROM "ChallengeParticipants" cp
            JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
            WHERE cp2c."challengesId"::text = $1
          `,
          params: [input.id],
        });
        const userIds = parts.map((p: any) => p.userId).filter(Boolean);

        if (userIds.length > 0) {
          let progressMap = new Map<string, number>();

          if (challenge.type === 'Barter Terbanyak') {
            const { rows } = await zite.sql({
              query: `SELECT uid, COUNT(*) AS cnt FROM (
                SELECT bh."initiator"->>0 AS uid FROM "BarterHistory" bh
                WHERE bh."status" = 'Selesai' AND bh."completedAt" >= $1 AND bh."completedAt" <= $2 AND bh."initiator"->>0 = ANY($3::text[])
                UNION ALL
                SELECT bh."partner"->>0 AS uid FROM "BarterHistory" bh
                WHERE bh."status" = 'Selesai' AND bh."completedAt" >= $1 AND bh."completedAt" <= $2 AND bh."partner"->>0 = ANY($3::text[])
              ) sub GROUP BY uid`,
              params: [startDate, endDate, userIds],
            });
            for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          } else if (challenge.type === 'Upload Terbanyak') {
            const { rows } = await zite.sql({
              query: `SELECT i."owner"->>0 AS uid, COUNT(*) AS cnt FROM "Items" i
                WHERE i.created_at >= $1::timestamptz AND i.created_at <= $2::timestamptz AND i."owner"->>0 = ANY($3::text[])
                GROUP BY i."owner"->>0`,
              params: [startDate, endDate, userIds],
            });
            for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          } else if (challenge.type === 'Rating Tertinggi') {
            const { rows } = await zite.sql({
              query: `SELECT br."reviewee"->>0 AS uid, ROUND(AVG(br."rating")::numeric, 2) AS avg_rating FROM "BarterReviews" br
                WHERE br.created_at >= $1::timestamptz AND br.created_at <= $2::timestamptz AND br."reviewee"->>0 = ANY($3::text[])
                GROUP BY br."reviewee"->>0`,
              params: [startDate, endDate, userIds],
            });
            for (const r of rows) progressMap.set(String(r.uid), Number(r.avg_rating));
          } else if (challenge.type === 'Referral Race') {
            const { rows } = await zite.sql({
              query: `SELECT r."referrer"->>0 AS uid, COUNT(*) AS cnt FROM "Referrals" r
                WHERE r."status" = 'Completed' AND r.created_at >= $1::timestamptz AND r.created_at <= $2::timestamptz AND r."referrer"->>0 = ANY($3::text[])
                GROUP BY r."referrer"->>0`,
              params: [startDate, endDate, userIds],
            });
            for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          }

          // Update changed progress silently
          for (const p of parts) {
            const uid = String((p as any).userId);
            const newProg = progressMap.get(uid) ?? 0;
            await zite.challengeParticipants.update({ id: (p as any).id, record: { progress: newProg } });
          }
        }
      } catch { /* progress update is best-effort, don't block detail view */ }
    }

    // Get leaderboard (top 20 participants)
    const { rows: leaderboard } = await zite.sql({
      query: `
        SELECT 
          cp.id, cp."progress", cp."rank", cp."status", cp."friendsInvited",
          cp."user", cp."joinedAt",
          u."name" AS "userName", u."image" AS "userImage", u."email" AS "userEmail"
        FROM "ChallengeParticipants" cp
        JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
        LEFT JOIN "ziteUsers" u ON cp."user" @> to_jsonb(ARRAY[u.id::text])
        WHERE cp2c."challengesId"::text = $1
        ORDER BY cp."progress" DESC NULLS LAST
        LIMIT 20
      `,
      params: [input.id],
    });

    // Check if current user joined
    const { rows: myParticipation } = await zite.sql({
      query: `
        SELECT cp.id, cp."progress", cp."rank", cp."status"
        FROM "ChallengeParticipants" cp
        JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
        WHERE cp2c."challengesId"::text = $1 AND cp."user" @> to_jsonb(ARRAY[$2::text])
        LIMIT 1
      `,
      params: [input.id, context.user.id],
    });

    // Calculate actual rank from leaderboard position
    const myLeaderboardIdx = leaderboard.findIndex((r: any) => {
      const uid = Array.isArray(r.user) ? r.user[0] : (typeof r.user === 'string' ? r.user : null);
      return uid === context.user.id;
    });
    const actualRank = myLeaderboardIdx >= 0 ? myLeaderboardIdx + 1 : null;
    const oldRank = (myParticipation[0] as any)?.rank ?? null;

    // If rank changed and user is a participant, update rank and notify
    if (myParticipation.length > 0 && actualRank !== null && oldRank !== null && actualRank !== oldRank) {
      await zite.challengeParticipants.update({
        id: (myParticipation[0] as any).id,
        record: { rank: actualRank },
      });

      if (actualRank < oldRank) {
        // Rank improved — notify
        await zite.notifications.create({
          record: {
            title: '📈 Peringkat Naik!',
            body: `Kamu naik ke peringkat #${actualRank} di challenge "${challenge.title}"!`,
            type: 'System',
            recipient: context.user.id,
            read: false,
            linkPath: `/challenge/${challenge.id}`,
          },
        });
      }
    } else if (myParticipation.length > 0 && actualRank !== null && oldRank === null) {
      // First time getting ranked
      await zite.challengeParticipants.update({
        id: (myParticipation[0] as any).id,
        record: { rank: actualRank },
      });
    }

    const daysLeft = challenge.endDate ? Math.max(0, Math.ceil((new Date(challenge.endDate).getTime() - Date.now()) / 86400000)) : null;

    return {
      challenge: {
        id: challenge.id,
        title: challenge.title,
        description: challenge.description,
        type: challenge.type,
        icon: challenge.icon,
        bannerImage: challenge.bannerImage?.[0]?.url ?? null,
        status: challenge.status,
        startDate: challenge.startDate,
        endDate: challenge.endDate,
        daysLeft,
        minTarget: challenge.minTarget,
        reward1st: challenge.reward1st,
        reward2nd: challenge.reward2nd,
        reward3rd: challenge.reward3rd,
        participationReward: challenge.participationReward,
        badge1st: challenge.badge1st,
        badgeParticipant: challenge.badgeParticipant,
        joined: (myParticipation.length ?? 0) > 0,
        myProgress: (myParticipation[0] as any)?.progress ?? 0,
        myRank: actualRank ?? (myParticipation[0] as any)?.rank ?? null,
        leaderboard: leaderboard.map((r: any, i: number) => ({
          rank: i + 1,
          userName: r.userName ?? r.userEmail?.split('@')[0] ?? 'User',
          userImage: r.userImage,
          progress: r.progress ?? 0,
          status: r.status,
        })),
      },
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Gets active and upcoming challenges for users',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    challenges: z.array(z.any()),
  }),
  execute: async ({ context }) => {
    const now = new Date().toISOString();

    // Get challenges that are Aktif or Akan Datang and Publik
    const { records } = await zite.challenges.findAll({
      filters: {
        status: { in: ['Aktif', 'Akan Datang'] },
        visibility: 'Publik',
      },
      limit: 50,
    });

    // Get participant counts + whether current user has joined
    const challengeIds = records.map(c => c.id);
    if (challengeIds.length === 0) return { challenges: [] };

    const { rows: participantData } = await zite.sql({
      query: `
        SELECT 
          cp2c."challengesId"::text AS "challengeId",
          COUNT(*) AS "participantCount",
          COUNT(CASE WHEN cp."user" @> to_jsonb(ARRAY[$1::text]) THEN 1 END) AS "joined"
        FROM "ChallengeParticipants" cp
        JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
        WHERE cp2c."challengesId"::text = ANY($2::text[])
        GROUP BY cp2c."challengesId"
      `,
      params: [context.user.id, challengeIds],
    });

    const pMap = new Map(participantData.map((r: any) => [r.challengeId, r]));

    const challenges = records.map(c => {
      const p = pMap.get(c.id);
      const daysLeft = c.endDate ? Math.max(0, Math.ceil((new Date(c.endDate).getTime() - Date.now()) / 86400000)) : null;
      return {
        id: c.id,
        title: c.title,
        description: c.description,
        type: c.type,
        icon: c.icon,
        bannerImage: c.bannerImage?.[0]?.url ?? null,
        status: c.status,
        startDate: c.startDate,
        endDate: c.endDate,
        daysLeft,
        minTarget: c.minTarget,
        reward1st: c.reward1st,
        participationReward: c.participationReward,
        participantCount: Number(p?.participantCount ?? 0),
        joined: Number(p?.joined ?? 0) > 0,
      };
    });

    return { challenges };
  },
});

