import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get daily check-in status and streak info for current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    checkedInToday: z.boolean(),
    currentStreak: z.number(),
    weekDays: z.array(z.object({
      day: z.string(),
      date: z.string(),
      checkedIn: z.boolean(),
      isToday: z.boolean(),
    })),
    totalCheckins: z.number(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];

    // Get this week's check-ins (Mon-Sun)
    const dayOfWeek = today.getDay();
    const mondayOffset = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
    const monday = new Date(today);
    monday.setDate(today.getDate() + mondayOffset);

    const dayNames = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'];
    const weekDates: string[] = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      weekDates.push(d.toISOString().split('T')[0]);
    }

    // Fetch all check-ins for this week
    const { records: weekCheckins } = await zite.dailyCheckins.findAll({
      filters: { user: userId },
      limit: 100,
    });

    const checkinDates = new Set(weekCheckins.map(c => c.checkinDate));
    const checkedInToday = checkinDates.has(todayStr);

    // Calculate current streak
    let currentStreak = 0;
    const checkDate = new Date(today);
    // If not checked in today, start from yesterday
    if (!checkedInToday) {
      checkDate.setDate(checkDate.getDate() - 1);
    }
    for (let i = 0; i < 365; i++) {
      const dateStr = checkDate.toISOString().split('T')[0];
      const found = weekCheckins.find(c => c.checkinDate === dateStr);
      if (found) {
        currentStreak = found.streakCount ?? (currentStreak + 1);
        break;
      } else {
        break;
      }
    }

    // If checked in today, use today's streak
    if (checkedInToday) {
      const todayRecord = weekCheckins.find(c => c.checkinDate === todayStr);
      if (todayRecord) currentStreak = todayRecord.streakCount ?? 1;
    }

    const weekDays = weekDates.map((date, i) => ({
      day: dayNames[i],
      date,
      checkedIn: checkinDates.has(date),
      isToday: date === todayStr,
    }));

    return {
      checkedInToday,
      currentStreak,
      weekDays,
      totalCheckins: weekCheckins.length,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get public comments for an item',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    comments: z.array(z.object({
      id: z.string(),
      content: z.string(),
      authorName: z.string(),
      authorImage: z.string().nullable(),
      authorId: z.string(),
      createdAt: z.string(),
    })),
  }),
  execute: async ({ input }) => {
    const { records } = await zite.comments.findAll({
      filters: { item: input.itemId },
      limit: 100,
    });

    // Get unique author IDs
    const authorIds = [...new Set(records.map(r => {
      const a = r.author;
      return Array.isArray(a) ? a[0] : a;
    }).filter(Boolean))] as string[];

    const userMap: Record<string, { name: string; image: string | null }> = {};
    if (authorIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: { in: authorIds } },
        limit: 100,
      });
      for (const u of users) {
        userMap[u.id] = { name: u.name || u.firstName || u.email, image: u.image ?? null };
      }
    }

    // Sort by createdAt descending (newest first)
    const sorted = records.sort((a, b) => {
      const da = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const db = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return db - da;
    });

    const comments = sorted.map(r => {
      const authorId = Array.isArray(r.author) ? r.author[0] : r.author;
      const user = authorId ? userMap[authorId] : undefined;
      return {
        id: r.id,
        content: r.content || '',
        authorName: (r as any).authorName || user?.name || 'Anonim',
        authorImage: user?.image ?? null,
        authorId: authorId || '',
        createdAt: r.createdAt || new Date().toISOString(),
      };
    });

    return { comments };
  },
});

