import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch list of communities with optional city/search filter',
  authenticated: true,
  inputSchema: z.object({
    search: z.string().optional(),
    city: z.string().optional(),
    limit: z.number().optional(),
    offset: z.number().optional(),
  }),
  outputSchema: z.object({
    communities: z.array(z.object({
      id: z.string(),
      name: z.string(),
      description: z.string(),
      city: z.string(),
      province: z.string(),
      banner: z.array(z.object({ url: z.string() })).nullable(),
      icon: z.string().nullable(),
      status: z.string(),
      memberCount: z.number(),
      barterCount: z.number(),
      joinMode: z.string(),
      createdAt: z.string().nullable(),
      creatorName: z.string(),
      creatorImage: z.string().nullable(),
      isMember: z.boolean(),
      isCreator: z.boolean(),
      myRole: z.string().nullable(),
    })),
    total: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const limit = input.limit || 20;

    // Build filters
    const filters: Record<string, unknown> = { status: 'active' };
    if (input.city) filters.city = { contains: input.city };

    const { records } = await zite.communities.findAll({ filters, limit, offset: input.offset || 0 });

    // Get user's memberships
    const { records: myMemberships } = await zite.communityMembers.findAll({
      filters: { user: userId, status: 'active' },
      limit: 500,
    });
    const membershipMap = new Map<string, string>();
    for (const m of myMemberships) {
      const cIds = Array.isArray(m.community) ? m.community : m.community ? [m.community] : [];
      for (const cId of cIds) membershipMap.set(cId, m.role || 'member');
    }

    // Get creator info
    const creatorIds = [...new Set(records.flatMap(r => {
      const c = r.creator;
      return Array.isArray(c) ? c : c ? [c] : [];
    }))];
    const creators = creatorIds.length > 0
      ? (await zite.auth.findAllUsers({ filters: { id: { in: creatorIds } }, limit: 100 })).records
      : [];
    const creatorMap = new Map(creators.map(u => [u.id, u]));

    let filtered = records;
    if (input.search) {
      const s = input.search.toLowerCase();
      filtered = records.filter(r => r.name?.toLowerCase().includes(s) || r.city?.toLowerCase().includes(s));
    }

    return {
      communities: filtered.map(c => {
        const cId = Array.isArray(c.creator) ? c.creator[0] : c.creator;
        const creator = cId ? creatorMap.get(cId) : undefined;
        return {
          id: c.id,
          name: c.name || '',
          description: c.description || '',
          city: c.city || '',
          province: c.province || '',
          banner: c.banner?.map(b => ({ url: b.url })) || null,
          icon: c.icon || null,
          status: c.status || 'active',
          memberCount: c.memberCount || 0,
          barterCount: c.barterCount || 0,
          joinMode: c.joinMode || 'open',
          createdAt: c.createdAt || null,
          creatorName: creator?.name || 'MUTARI User',
          creatorImage: creator?.image || null,
          isMember: membershipMap.has(c.id),
          isCreator: cId === userId,
          myRole: membershipMap.get(c.id) || null,
        };
      }),
      total: filtered.length,
    };
  },
});

