import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get full details of a community including posts and members',
  authenticated: true,
  inputSchema: z.object({ communityId: z.string() }),
  outputSchema: z.object({
    community: z.object({
      id: z.string(),
      name: z.string(),
      description: z.string(),
      city: z.string(),
      province: z.string(),
      banner: z.array(z.object({ url: z.string() })).nullable(),
      icon: z.string().nullable(),
      rules: z.string(),
      status: z.string(),
      memberCount: z.number(),
      barterCount: z.number(),
      joinMode: z.string(),
      createdAt: z.string().nullable(),
      creatorId: z.string(),
      creatorName: z.string(),
      creatorImage: z.string().nullable(),
    }),
    myMembership: z.object({
      isMember: z.boolean(),
      role: z.string().nullable(),
      status: z.string().nullable(),
    }),
    members: z.array(z.object({
      id: z.string(),
      userId: z.string(),
      name: z.string(),
      image: z.string().nullable(),
      role: z.string(),
      pointsEarned: z.number(),
      joinedAt: z.string().nullable(),
    })),
    posts: z.array(z.object({
      id: z.string(),
      title: z.string(),
      content: z.string(),
      type: z.string(),
      authorId: z.string(),
      authorName: z.string(),
      authorImage: z.string().nullable(),
      pinned: z.boolean(),
      likesCount: z.number(),
      commentsCount: z.number(),
      media: z.array(z.object({ url: z.string() })).nullable(),
      createdAt: z.string().nullable(),
    })),
    leaderboard: z.array(z.object({
      userId: z.string(),
      name: z.string(),
      image: z.string().nullable(),
      points: z.number(),
      role: z.string(),
    })),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const community = await zite.communities.findOne({ id: input.communityId });
    if (!community) throw new Error('Komunitas tidak ditemukan');

    // Members
    const { records: members } = await zite.communityMembers.findAll({
      filters: { community: input.communityId, status: 'active' },
      limit: 100,
    });

    const memberUserIds = members.flatMap(m => {
      const u = m.user;
      return Array.isArray(u) ? u : u ? [u] : [];
    });
    const creatorId = Array.isArray(community.creator) ? community.creator[0] : community.creator || '';
    const allUserIds = [...new Set([...memberUserIds, creatorId].filter(Boolean))];
    const users = allUserIds.length > 0
      ? (await zite.auth.findAllUsers({ filters: { id: { in: allUserIds } }, limit: 200 })).records
      : [];
    const userMap = new Map(users.map(u => [u.id, u]));

    const myMembership = members.find(m => {
      const uIds = Array.isArray(m.user) ? m.user : m.user ? [m.user] : [];
      return uIds.includes(userId);
    });

    // Posts
    const { records: posts } = await zite.communityPosts.findAll({
      filters: { community: input.communityId },
      limit: 50,
    });
    const postAuthorIds = posts.flatMap(p => {
      const a = p.author;
      return Array.isArray(a) ? a : a ? [a] : [];
    });
    const extraAuthors = postAuthorIds.filter(id => !userMap.has(id));
    if (extraAuthors.length > 0) {
      const { records: extra } = await zite.auth.findAllUsers({ filters: { id: { in: extraAuthors } }, limit: 100 });
      extra.forEach(u => userMap.set(u.id, u));
    }

    const creator = userMap.get(creatorId);

    // Leaderboard (top members by points)
    const leaderboard = members
      .sort((a, b) => (b.pointsEarned || 0) - (a.pointsEarned || 0))
      .slice(0, 10)
      .map(m => {
        const uId = Array.isArray(m.user) ? m.user[0] : m.user || '';
        const u = userMap.get(uId);
        return {
          userId: uId,
          name: u?.name || 'User',
          image: u?.image || null,
          points: m.pointsEarned || 0,
          role: m.role || 'member',
        };
      });

    return {
      community: {
        id: community.id,
        name: community.name || '',
        description: community.description || '',
        city: community.city || '',
        province: community.province || '',
        banner: community.banner?.map(b => ({ url: b.url })) || null,
        icon: community.icon || null,
        rules: community.rules || '',
        status: community.status || 'active',
        memberCount: community.memberCount || 0,
        barterCount: community.barterCount || 0,
        joinMode: community.joinMode || 'open',
        createdAt: community.createdAt || null,
        creatorId,
        creatorName: creator?.name || 'MUTARI User',
        creatorImage: creator?.image || null,
      },
      myMembership: {
        isMember: !!myMembership,
        role: myMembership?.role || null,
        status: myMembership?.status || null,
      },
      members: members.map(m => {
        const uId = Array.isArray(m.user) ? m.user[0] : m.user || '';
        const u = userMap.get(uId);
        return {
          id: m.id,
          userId: uId,
          name: u?.name || 'User',
          image: u?.image || null,
          role: m.role || 'member',
          pointsEarned: m.pointsEarned || 0,
          joinedAt: m.joinedAt || null,
        };
      }),
      posts: posts
        .sort((a, b) => {
          if (a.pinned && !b.pinned) return -1;
          if (!a.pinned && b.pinned) return 1;
          return (b.createdAt || '').localeCompare(a.createdAt || '');
        })
        .map(p => {
          const aId = Array.isArray(p.author) ? p.author[0] : p.author || '';
          const u = userMap.get(aId);
          return {
            id: p.id,
            title: p.title || '',
            content: p.content || '',
            type: p.type || 'discussion',
            authorId: aId,
            authorName: u?.name || 'User',
            authorImage: u?.image || null,
            pinned: p.pinned || false,
            likesCount: p.likesCount || 0,
            commentsCount: p.commentsCount || 0,
            media: p.media?.map(m => ({ url: m.url })) || null,
            createdAt: p.createdAt || null,
          };
        }),
      leaderboard,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get live community statistics for the beranda',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    bartersToday: z.number(),
    newItemsToday: z.number(),
    activeUsers: z.number(),
    totalBarters: z.number(),
    totalUsers: z.number(),
    storiesActive: z.number(),
    likesToday: z.number(),
    viewsToday: z.number(),
  }),
  execute: async () => {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);
    const todayISO = todayStart.toISOString();
    const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();

    const result = await zite.sql({
      query: `
        SELECT
          (SELECT COUNT(*) FROM "BarterHistory" WHERE "status" = 'Selesai' AND created_at >= $1) AS "bartersToday",
          (SELECT COUNT(*) FROM "Items" WHERE created_at >= $1) AS "newItemsToday",
          (SELECT COUNT(*) FROM "UserPresence" WHERE "lastSeen" >= $2) AS "activeUsers",
          (SELECT COUNT(*) FROM "BarterHistory" WHERE "status" = 'Selesai') AS "totalBarters",
          (SELECT COUNT(*) FROM "UserProfiles") AS "totalUsers",
          (SELECT COUNT(*) FROM "BarterStories" WHERE created_at >= $2) AS "storiesActive",
          (SELECT COUNT(*) FROM "ItemLikes" WHERE created_at >= $1) AS "likesToday",
          (SELECT COALESCE(SUM("viewsCount"), 0) FROM "Items") AS "viewsToday"
      `,
      params: [todayISO, twentyFourHoursAgo],
    });

    const row = result.rows[0] || {};
    return {
      bartersToday: Number(row.bartersToday || 0),
      newItemsToday: Number(row.newItemsToday || 0),
      activeUsers: Number(row.activeUsers || 0),
      totalBarters: Number(row.totalBarters || 0),
      totalUsers: Number(row.totalUsers || 0),
      storiesActive: Number(row.storiesActive || 0),
      likesToday: Number(row.likesToday || 0),
      viewsToday: Number(row.viewsToday || 0),
    };
  },
});

