import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get follow status, follower count, and following count for a user',
  authenticated: true,
  inputSchema: z.object({
    targetUserId: z.string(),
  }),
  outputSchema: z.object({
    isFollowing: z.boolean(),
    followersCount: z.number(),
    followingCount: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Check if current user follows target
    const { records: followRecords } = await zite.follows.findAll({
      filters: { follower: userId, followingUserId: input.targetUserId },
      limit: 1,
    });
    const isFollowing = followRecords.length > 0;

    // Count followers of target (people who follow targetUserId)
    const { records: followers } = await zite.follows.findAll({
      filters: { followingUserId: input.targetUserId },
      limit: 2000,
    });

    // Count following of target (people targetUserId follows)
    const { records: following } = await zite.follows.findAll({
      filters: { follower: input.targetUserId },
      limit: 2000,
    });

    return {
      isFollowing,
      followersCount: followers.length,
      followingCount: following.length,
    };
  },
});

