import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch available barter items with optional search and category filter, prioritized by owner points',
  inputSchema: z.object({
    limit: z.number().optional(),
    search: z.string().optional(),
    categoryId: z.string().optional(),
  }),
  outputSchema: z.object({
    items: z.array(z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      photos: z.array(z.object({ url: z.string(), filename: z.string().optional() })).optional(),
      condition: z.string(),
      estimatedValueMin: z.number().nullable(),
      estimatedValueMax: z.number().nullable(),
      location: z.string(),
      status: z.string(),
      viewsCount: z.number(),
      likesCount: z.number(),
      commentsCount: z.number(),
      createdAt: z.string().nullable(),
      category: z.array(z.string()).nullable(),
      ownerName: z.string(),
      ownerImage: z.string().nullable(),
      ownerPoints: z.number(),
      ownerBadgeId: z.string(),
      ownerAwardCount: z.number(),
      isBoosted: z.boolean(),
      isHighlighted: z.boolean(),
    })),
  }),
  execute: async ({ input }) => {
    const limit = input.limit || 20;

    const allUsers = await zite.auth.findAllUsers({ limit: 200 });
    const userMap = new Map(allUsers.records.map(u => [u.id, u]));

    // Fetch active boosts & highlights
    const now = new Date();
    const { records: activeRedemptions } = await zite.pointRedemptions.findAll({
      filters: { status: { in: ['active', 'Active'] } },
      limit: 500,
    });
    const boostedItemIds = new Set<string>();
    const highlightedItemIds = new Set<string>();
    for (const r of activeRedemptions) {
      if (!r.expiresAt || new Date(r.expiresAt) <= now) continue;
      const itemId = Array.isArray(r.item) ? r.item[0] : r.item;
      if (!itemId) continue;
      const rType = (r.type || '').toLowerCase();
      if (rType === 'boost' || rType === 'boost listing') boostedItemIds.add(itemId);
      if (rType === 'highlight' || rType === 'highlight frame') highlightedItemIds.add(itemId);
    }

    // Build base query with UserPoints JOIN for priority sorting
    let query = `
      SELECT i.*, 
        COALESCE(up."totalPoints", 0) AS "ownerTotalPoints",
        COALESCE(up."bartersCompleted", 0) AS "ownerBartersCompleted",
        COALESCE(up."itemsUploaded", 0) AS "ownerItemsUploaded",
        COALESCE(up."likesReceived", 0) AS "ownerLikesReceived",
        CASE
          WHEN COALESCE(up."totalPoints", 0) >= 10000 THEN 'elite'
          WHEN COALESCE(up."totalPoints", 0) >= 5000 THEN 'mentor'
          WHEN COALESCE(up."totalPoints", 0) >= 2500 THEN 'legenda'
          WHEN COALESCE(up."totalPoints", 0) >= 1000 THEN 'profesional'
          WHEN COALESCE(up."totalPoints", 0) >= 500 THEN 'terpercaya'
          WHEN COALESCE(up."totalPoints", 0) >= 200 THEN 'aktif'
          ELSE 'pemula'
        END AS "ownerBadge"
      FROM "Items" i
      LEFT JOIN "UserPoints" up ON up."user"->>0 = i."owner"->>0
    `;
    const params: unknown[] = [];
    let paramIdx = 1;

    if (input.categoryId) {
      query += ` JOIN "CategoriesItems" ON "CategoriesItems"."itemsId" = i."id" AND "CategoriesItems"."categoriesId" = $${paramIdx}`;
      params.push(input.categoryId);
      paramIdx++;
    }

    query += ` WHERE i."status" = 'Tersedia'`;

    if (input.search) {
      query += ` AND (LOWER(i."title") LIKE $${paramIdx} OR LOWER(i."description") LIKE $${paramIdx})`;
      params.push(`%${input.search.toLowerCase()}%`);
      paramIdx++;
    }

    // Sort by owner points DESC first (high-point users' items appear on top), then by recency
    query += ` ORDER BY COALESCE(up."totalPoints", 0) DESC, i."createdAt" DESC NULLS LAST LIMIT $${paramIdx}`;
    params.push(limit);

    const result = await zite.sql({ query, params });
    const ids = result.rows.map(r => String(r.id || ''));

    // Get comment counts
    const commentResult = ids.length > 0
      ? await zite.sql({
          query: `SELECT ci."itemsId" as "itemId", COUNT(*) as "cnt" FROM "CommentsItems" ci WHERE ci."itemsId" = ANY($1) GROUP BY ci."itemsId"`,
          params: [ids],
        })
      : { rows: [] };
    const commentCounts: Record<string, number> = {};
    for (const row of commentResult.rows) {
      commentCounts[row.itemId as string] = Number(row.cnt ?? 0);
    }

    // Build items with boost/highlight flags
    const mapped = result.rows.map((r: Record<string, unknown>) => {
      const ownerIds = Array.isArray(r.owner) ? r.owner as string[] : r.owner ? [r.owner as string] : [];
      const owner = ownerIds[0] ? userMap.get(ownerIds[0]) : null;
      const rid = String(r.id || '');
      const ownerPoints = Number(r.ownerTotalPoints ?? 0);
      const ownerBarters = Number(r.ownerBartersCompleted ?? 0);
      const ownerUploads = Number(r.ownerItemsUploaded ?? 0);
      const ownerLikes = Number(r.ownerLikesReceived ?? 0);
      // Quick award count estimate from UserPoints data
      let ownerAwardCount = 0;
      if (ownerBarters >= 1) ownerAwardCount++;
      if (ownerBarters >= 10) ownerAwardCount++;
      if (ownerBarters >= 50) ownerAwardCount++;
      if (ownerBarters >= 100) ownerAwardCount++;
      if (ownerUploads >= 5) ownerAwardCount++;
      if (ownerUploads >= 25) ownerAwardCount++;
      if (ownerUploads >= 100) ownerAwardCount++;
      if (ownerLikes >= 50) ownerAwardCount++;
      if (ownerLikes >= 200) ownerAwardCount++;
      if (ownerLikes >= 500) ownerAwardCount++;
      return {
        id: rid,
        title: String(r.title || ''),
        description: String(r.description || ''),
        photos: r.photos as { url: string; filename?: string }[] | undefined,
        condition: String(r.condition || ''),
        estimatedValueMin: (r.estimatedValueMin as number) ?? null,
        estimatedValueMax: (r.estimatedValueMax as number) ?? null,
        location: String(r.location || ''),
        status: String(r.status || ''),
        viewsCount: (r.viewsCount as number) ?? 0,
        likesCount: (r.likesCount as number) ?? 0,
        commentsCount: commentCounts[rid] ?? 0,
        createdAt: r.createdAt as string ?? null,
        category: r.category as string[] ?? null,
        ownerName: owner?.name || 'Pengguna',
        ownerImage: owner?.image ?? null,
        ownerPoints,
        ownerBadgeId: String(r.ownerBadge || 'pemula'),
        ownerAwardCount,
        isBoosted: boostedItemIds.has(rid),
        isHighlighted: highlightedItemIds.has(rid),
      };
    });

    // Boosted items go first
    mapped.sort((a, b) => {
      if (a.isBoosted && !b.isBoosted) return -1;
      if (!a.isBoosted && b.isBoosted) return 1;
      return 0;
    });

    return { items: mapped };
  },
});

