import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Run smart match detection — finds mutual matches where someone has what you want AND wants what you have',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string().optional(),
  }),
  outputSchema: z.object({
    alerts: z.array(z.object({
      id: z.string(),
      myItemId: z.string(),
      myItemTitle: z.string(),
      myItemPhoto: z.string(),
      theirItemId: z.string(),
      theirItemTitle: z.string(),
      theirItemPhoto: z.string(),
      theirOwnerId: z.string(),
      theirOwnerName: z.string(),
      theirOwnerImage: z.string().nullable(),
      matchReason: z.string(),
      matchScore: z.number(),
    })),
  }),
  execute: async ({ context, input }) => {
    const userId = context.user.id;

    // Get my items
    const { records: myItems } = await zite.items.findAll({
      filters: { owner: userId, status: 'Tersedia' },
      limit: 50,
    });

    if (myItems.length === 0) return { alerts: [] };

    // Get all other available items
    const { records: otherItems } = await zite.items.findAll({
      filters: { status: 'Tersedia' },
      limit: 500,
    });

    const othersItems = otherItems.filter(i => {
      const ownerIds = Array.isArray(i.owner) ? i.owner : [i.owner];
      return !ownerIds.includes(userId);
    });

    if (othersItems.length === 0) return { alerts: [] };

    // Collect owner IDs for name lookup
    const ownerIds = new Set<string>();
    for (const item of othersItems) {
      const ids = Array.isArray(item.owner) ? item.owner : [item.owner];
      ids.forEach(id => id && ownerIds.add(id));
    }

    const { records: users } = await zite.auth.findAllUsers({ limit: 200 });
    const userMap = new Map(users.map(u => [u.id, u]));

    type Alert = {
      id: string; myItemId: string; myItemTitle: string; myItemPhoto: string;
      theirItemId: string; theirItemTitle: string; theirItemPhoto: string;
      theirOwnerId: string; theirOwnerName: string; theirOwnerImage: string | null;
      matchReason: string; matchScore: number;
    };

    const alerts: Alert[] = [];
    const seen = new Set<string>();

    for (const myItem of myItems) {
      if (input.itemId && myItem.id !== input.itemId) continue;

      const myWants = (myItem.desiredItems || '').toLowerCase();
      const myAdditional = (myItem.additionalWants || '').toLowerCase();
      const myTitle = (myItem.title || '').toLowerCase();
      const myDesc = (myItem.description || '').toLowerCase();
      const myCategory = Array.isArray(myItem.category) ? myItem.category : myItem.category ? [myItem.category] : [];

      for (const theirItem of othersItems) {
        const pairKey = [myItem.id, theirItem.id].sort().join('-');
        if (seen.has(pairKey)) continue;

        const theirWants = (theirItem.desiredItems || '').toLowerCase();
        const theirAdditional = (theirItem.additionalWants || '').toLowerCase();
        const theirTitle = (theirItem.title || '').toLowerCase();
        const theirDesc = (theirItem.description || '').toLowerCase();
        const theirCategory = Array.isArray(theirItem.category) ? theirItem.category : theirItem.category ? [theirItem.category] : [];

        // Check mutual match:
        // 1. Does their item match what I want?
        const iWantTheirs = textMatch(myWants + ' ' + myAdditional, theirTitle, theirDesc, theirCategory);
        // 2. Do they want what I have?
        const theyWantMine = textMatch(theirWants + ' ' + theirAdditional, myTitle, myDesc, myCategory);

        if (iWantTheirs > 0 && theyWantMine > 0) {
          const score = Math.min(Math.round((iWantTheirs + theyWantMine) / 2), 100);
          seen.add(pairKey);

          const theirOwnerIds = Array.isArray(theirItem.owner) ? theirItem.owner : [theirItem.owner];
          const ownerId = theirOwnerIds[0] || '';
          const ownerUser = userMap.get(ownerId);

          let reason = '';
          if (iWantTheirs >= 70 && theyWantMine >= 70) {
            reason = `Cocok banget! Kamu cari "${extractMatch(myWants, theirTitle)}" & mereka butuh "${extractMatch(theirWants, myTitle)}"`;
          } else if (iWantTheirs >= 40 || theyWantMine >= 40) {
            reason = `Kemungkinan cocok — barang kalian saling melengkapi`;
          } else {
            reason = `Potensi match berdasarkan kategori & kebutuhan`;
          }

          alerts.push({
            id: pairKey,
            myItemId: myItem.id,
            myItemTitle: myItem.title || '',
            myItemPhoto: myItem.photos?.[0]?.url || '',
            theirItemId: theirItem.id,
            theirItemTitle: theirItem.title || '',
            theirItemPhoto: theirItem.photos?.[0]?.url || '',
            theirOwnerId: ownerId,
            theirOwnerName: ownerUser?.name || 'Pengguna',
            theirOwnerImage: ownerUser?.image ?? null,
            matchReason: reason,
            matchScore: score,
          });
        }
      }
    }

    // Sort by score descending
    alerts.sort((a, b) => b.matchScore - a.matchScore);

    return { alerts: alerts.slice(0, 20) };
  },
});

function textMatch(wantText: string, title: string, desc: string, categories: string[]): number {
  if (!wantText.trim()) return 0;

  const wantWords = wantText
    .replace(/[^a-zA-Z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2)
    .map(w => w.toLowerCase());

  if (wantWords.length === 0) return 0;

  const targetText = `${title} ${desc} ${categories.join(' ')}`.toLowerCase();
  let matchCount = 0;

  for (const word of wantWords) {
    if (targetText.includes(word)) matchCount++;
  }

  const ratio = matchCount / wantWords.length;
  return Math.round(ratio * 100);
}

function extractMatch(wants: string, title: string): string {
  const wantWords = wants.split(/\s+/).filter(w => w.length > 2);
  const titleWords = title.split(/\s+/);
  for (const tw of titleWords) {
    if (wantWords.some(w => tw.toLowerCase().includes(w.toLowerCase()))) {
      return tw;
    }
  }
  return title.split(' ').slice(0, 2).join(' ');
}

