import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get the list of users the current user follows and who follows them (private, only for own account)',
  authenticated: true,
  inputSchema: z.object({
    tab: z.enum(['following', 'followers']).default('following'),
  }),
  outputSchema: z.object({
    following: z.array(z.object({
      id: z.string(),
      name: z.string(),
      image: z.string().nullable(),
      city: z.string(),
      totalPoints: z.number(),
    })),
    followers: z.array(z.object({
      id: z.string(),
      name: z.string(),
      image: z.string().nullable(),
      city: z.string(),
      totalPoints: z.number(),
    })),
    followingCount: z.number(),
    followersCount: z.number(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // People I follow
    const { records: followingRecords } = await zite.follows.findAll({
      filters: { follower: userId },
      limit: 500,
    });

    // People who follow me
    const { records: followerRecords } = await zite.follows.findAll({
      filters: { followingUserId: userId },
      limit: 500,
    });

    const followingUserIds = followingRecords.map(r => r.followingUserId).filter(Boolean) as string[];
    const followerUserIds = followerRecords.map(r => {
      const ids = Array.isArray(r.follower) ? r.follower : [r.follower];
      return ids[0] || '';
    }).filter(Boolean);

    // Fetch all relevant user data
    const allIds = [...new Set([...followingUserIds, ...followerUserIds])];
    const userMap = new Map<string, { name: string; image: string | null }>();

    if (allIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({ limit: 200 });
      for (const u of users) {
        userMap.set(u.id, { name: u.name || u.email, image: u.image ?? null });
      }
    }

    // Fetch profiles for city info
    const profileMap = new Map<string, { city: string; totalPoints: number }>();
    if (allIds.length > 0) {
      const { records: profiles } = await zite.userProfiles.findAll({ limit: 500 });
      for (const p of profiles) {
        const pUserIds = Array.isArray(p.user) ? p.user : p.user ? [p.user] : [];
        for (const uid of pUserIds) {
          profileMap.set(uid, { city: p.city || '', totalPoints: 0 });
        }
      }
      const { records: pointRecords } = await zite.userPoints.findAll({ limit: 500 });
      for (const pt of pointRecords) {
        const ptUserIds = Array.isArray(pt.user) ? pt.user : pt.user ? [pt.user] : [];
        for (const uid of ptUserIds) {
          const existing = profileMap.get(uid);
          if (existing) existing.totalPoints = pt.totalPoints ?? 0;
          else profileMap.set(uid, { city: '', totalPoints: pt.totalPoints ?? 0 });
        }
      }
    }

    const mapUser = (uid: string) => {
      const u = userMap.get(uid);
      const p = profileMap.get(uid);
      return {
        id: uid,
        name: u?.name || 'Pengguna',
        image: u?.image ?? null,
        city: p?.city || '',
        totalPoints: p?.totalPoints || 0,
      };
    };

    return {
      following: followingUserIds.map(mapUser),
      followers: followerUserIds.map(mapUser),
      followingCount: followingUserIds.length,
      followersCount: followerUserIds.length,
    };
  },
});

