import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch items uploaded by the signed-in user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    items: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string().nullable(),
      condition: z.string(),
      location: z.string(),
      status: z.string(),
      viewsCount: z.number(),
      likesCount: z.number(),
      commentsCount: z.number(),
      estimatedValueMin: z.number().nullable(),
      estimatedValueMax: z.number().nullable(),
      createdAt: z.string().nullable(),
    })),
  }),
  execute: async ({ context }) => {
    const { records } = await zite.items.findAll({
      filters: { owner: context.user.id },
      limit: 100,
    });

    // Get comment counts
    const ids = records.map(r => r.id);
    let commentCounts: Record<string, number> = {};
    if (ids.length > 0) {
      const result = await zite.sql({
        query: `SELECT ci."itemsId" as "itemId", COUNT(*) as "cnt" FROM "CommentsItems" ci WHERE ci."itemsId" = ANY($1) GROUP BY ci."itemsId"`,
        params: [ids],
      });
      for (const row of result.rows) {
        commentCounts[row.itemId as string] = Number(row.cnt ?? 0);
      }
    }

    return {
      items: records.map(r => ({
        id: r.id,
        title: r.title || 'Tanpa judul',
        photo: r.photos?.[0]?.url || null,
        condition: r.condition || '',
        location: r.location || '',
        status: r.status || 'Tersedia',
        viewsCount: r.viewsCount ?? 0,
        likesCount: r.likesCount ?? 0,
        commentsCount: commentCounts[r.id] ?? 0,
        estimatedValueMin: r.estimatedValueMin ?? null,
        estimatedValueMax: r.estimatedValueMax ?? null,
        createdAt: r.createdAt ?? null,
      })),
    };
  },
});

