import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Gets pending/active barters that need user attention',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    pending: z.array(z.object({
      id: z.string(),
      title: z.string(),
      status: z.string(),
      partnerName: z.string(),
      partnerImage: z.string().nullable(),
      offeredItemTitle: z.string(),
      offeredItemPhoto: z.string().nullable(),
      requestedItemTitle: z.string(),
      requestedItemPhoto: z.string().nullable(),
      createdAt: z.string().nullable(),
      expiresAt: z.string().nullable(),
      myRole: z.enum(['initiator', 'partner']),
      needsMyAction: z.boolean(),
      actionLabel: z.string(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Use SQL to get pending barters efficiently
    const result = await zite.sql({
      query: `
        SELECT
          b.id,
          COALESCE(b."title", 'Barter') AS title,
          COALESCE(b."status", 'Menunggu') AS status,
          b.created_at AS "createdAt",
          b."expiresAt",
          b."initiatorConfirmed",
          b."partnerConfirmed",
          b."codApproved",
          b."codAddress",
          b."deliveryMethod",
          b."deliveryMethodApproved",
          b."initiator"->>0 AS "initiatorId",
          b."partner"->>0 AS "partnerId",
          b."offeredItem"->>0 AS "offeredItemId",
          b."requestedItem"->>0 AS "requestedItemId"
        FROM "BarterHistory" b
        WHERE (b."initiator"->>0 = $1 OR b."partner"->>0 = $1)
          AND b."status" IN ('Menunggu', 'Diterima')
        ORDER BY b.created_at DESC
        LIMIT 5
      `,
      params: [userId],
    });

    if (result.rows.length === 0) return { pending: [] };

    // Collect all user/item IDs to batch-fetch
    const userIds = new Set<string>();
    const itemIds = new Set<string>();
    for (const r of result.rows) {
      if (r.initiatorId) userIds.add(String(r.initiatorId));
      if (r.partnerId) userIds.add(String(r.partnerId));
      if (r.offeredItemId) itemIds.add(String(r.offeredItemId));
      if (r.requestedItemId) itemIds.add(String(r.requestedItemId));
    }

    // Batch fetch users and items
    const [usersResult, ...itemResults] = await Promise.all([
      zite.auth.findAllUsers({ limit: 50 }),
      ...[...itemIds].map(id => zite.items.findOne({ id })),
    ]);

    const userMap = new Map(usersResult.records.map(u => [u.id, u]));
    const itemMap = new Map<string, { title?: string; photos?: { url: string }[] }>();
    const itemIdArr = [...itemIds];
    itemResults.forEach((item, i) => {
      if (item) itemMap.set(itemIdArr[i], item);
    });

    const pending = result.rows.map(r => {
      const isInitiator = String(r.initiatorId) === userId;
      const partnerId = isInitiator ? String(r.partnerId) : String(r.initiatorId);
      const partner = userMap.get(partnerId);

      const offered = r.offeredItemId ? itemMap.get(String(r.offeredItemId)) : null;
      const requested = r.requestedItemId ? itemMap.get(String(r.requestedItemId)) : null;

      const status = String(r.status);
      const initiatorConfirmed = r.initiatorConfirmed === true;
      const partnerConfirmed = r.partnerConfirmed === true;
      const codApproved = r.codApproved === true;
      const codAddress = r.codAddress ? String(r.codAddress) : null;
      const deliveryMethod = r.deliveryMethod ? String(r.deliveryMethod) : null;
      const deliveryMethodApproved = r.deliveryMethodApproved === true;

      // Determine if user needs to take action
      let needsMyAction = false;
      let actionLabel = '';

      if (status === 'Menunggu' && !isInitiator) {
        needsMyAction = true;
        actionLabel = 'Perlu respon kamu';
      } else if (status === 'Menunggu' && isInitiator) {
        actionLabel = 'Menunggu respon';
      } else if (status === 'Diterima') {
        if (!deliveryMethod) {
          needsMyAction = true;
          actionLabel = 'Pilih metode tukar';
        } else if (!deliveryMethodApproved) {
          needsMyAction = true;
          actionLabel = 'Setujui metode tukar';
        } else if ((isInitiator && !initiatorConfirmed) || (!isInitiator && !partnerConfirmed)) {
          needsMyAction = true;
          actionLabel = 'Konfirmasi selesai';
        } else {
          actionLabel = 'Menunggu konfirmasi partner';
        }
      }

      return {
        id: String(r.id),
        title: String(r.title),
        status,
        partnerName: partner?.name || partner?.email || 'Pengguna',
        partnerImage: partner?.image ?? null,
        offeredItemTitle: offered?.title || 'Barang',
        offeredItemPhoto: offered?.photos?.[0]?.url || null,
        requestedItemTitle: requested?.title || 'Barang',
        requestedItemPhoto: requested?.photos?.[0]?.url || null,
        createdAt: r.createdAt ? String(r.createdAt) : null,
        expiresAt: r.expiresAt ? String(r.expiresAt) : null,
        myRole: isInitiator ? 'initiator' as const : 'partner' as const,
        needsMyAction,
        actionLabel,
      };
    });

    return { pending };
  },
});

