import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get point shop data: user balance, active boosts/highlights, raffle tickets, and user items for spending',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalPoints: z.number(),
    activeBoosts: z.array(z.object({
      itemId: z.string(),
      itemTitle: z.string(),
      expiresAt: z.string(),
    })),
    activeHighlights: z.array(z.object({
      itemId: z.string(),
      itemTitle: z.string(),
      expiresAt: z.string(),
    })),
    raffleTicketsThisMonth: z.number(),
    myItems: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
    })),
    recentRedemptions: z.array(z.object({
      id: z.string(),
      type: z.string(),
      label: z.string(),
      pointsSpent: z.number(),
      createdAt: z.string(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    const up = await zite.userPoints.findOne({ filters: { user: userId } });
    const totalPoints = up?.totalPoints ?? 0;

    // Active boosts & highlights
    const { records: redemptions } = await zite.pointRedemptions.findAll({
      filters: { user: userId },
      limit: 200,
    });

    const now = new Date();
    const activeBoosts = redemptions
      .filter(r => r.type === 'boost' && r.status === 'active' && r.expiresAt && new Date(r.expiresAt) > now)
      .map(r => ({
        itemId: (Array.isArray(r.item) ? r.item[0] : r.item) || '',
        itemTitle: r.label?.replace('Boost: ', '') || '',
        expiresAt: r.expiresAt || '',
      }));

    const activeHighlights = redemptions
      .filter(r => r.type === 'highlight' && r.status === 'active' && r.expiresAt && new Date(r.expiresAt) > now)
      .map(r => ({
        itemId: (Array.isArray(r.item) ? r.item[0] : r.item) || '',
        itemTitle: r.label?.replace('Highlight: ', '') || '',
        expiresAt: r.expiresAt || '',
      }));

    const raffleTicketsThisMonth = redemptions
      .filter(r => r.type === 'raffle' && r.status === 'active')
      .reduce((sum, r) => sum + (r.raffleTickets ?? 0), 0);

    // User's items for boost/highlight selection
    const { records: items } = await zite.items.findAll({
      filters: { owner: userId, status: 'Tersedia' },
      limit: 50,
    });

    const myItems = items.map(i => ({
      id: i.id,
      title: i.title || 'Item',
      photo: i.photos?.[0]?.url || '',
    }));

    // Recent redemptions
    const sorted = redemptions.sort((a, b) =>
      new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime()
    );

    const recentRedemptions = sorted.slice(0, 10).map(r => ({
      id: r.id,
      type: r.type || '',
      label: r.label || '',
      pointsSpent: r.pointsSpent ?? 0,
      createdAt: r.createdAt || '',
    }));

    return {
      totalPoints,
      activeBoosts,
      activeHighlights,
      raffleTicketsThisMonth,
      myItems,
      recentRedemptions,
    };
  },
});

