import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

// Admin app id — internal users of this app are admins
const ADMIN_APP_ID = 'qbzjbuw5jn';

async function isAdmin(userId: string): Promise<boolean> {
  try {
    const { records } = await zite.auth.findAllUsers({
      appIds: [ADMIN_APP_ID],
      filters: { id: userId },
      limit: 1,
    });
    return records.length > 0;
  } catch {
    return false;
  }
}

export default createEndpoint({
  description: 'Get public profile data for any user by ID, respecting privacy settings (admin bypasses)',
  authenticated: true,
  inputSchema: z.object({ userId: z.string() }),
  outputSchema: z.object({
    name: z.string(),
    image: z.string().nullable(),
    memberSince: z.string(),
    totalPoints: z.number(),
    bartersCompleted: z.number(),
    itemsUploaded: z.number(),
    likesReceived: z.number(),
    averageRating: z.number(),
    totalReviews: z.number(),
    bio: z.string(),
    city: z.string(),
    province: z.string(),
    phoneVerified: z.boolean(),
    addressVerified: z.boolean(),
    currentBadge: z.string(),
    instagram: z.string(),
    twitter: z.string(),
    items: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
      condition: z.string(),
      status: z.string(),
    })),
    reviews: z.array(z.object({
      id: z.string(),
      rating: z.number(),
      comment: z.string(),
      reviewerName: z.string(),
      reviewerImage: z.string().nullable(),
      createdAt: z.string().nullable(),
    })),
    privacyRestricted: z.boolean(),
    restrictedFields: z.array(z.string()),
    awardCount: z.number(),
    topAwardTier: z.string(),
    awardEmojis: z.array(z.string()),
  }),
  execute: async ({ input, context }) => {
    const { records: users } = await zite.auth.findAllUsers({
      filters: { id: input.userId },
      limit: 1,
    });
    const u = users[0];
    if (!u) {
      return {
        name: 'Pengguna', image: null, memberSince: '-', totalPoints: 0,
        bartersCompleted: 0, itemsUploaded: 0, likesReceived: 0,
        averageRating: 0, totalReviews: 0,
        bio: '', city: '', province: '', phoneVerified: false, addressVerified: false,
        currentBadge: '', instagram: '', twitter: '',
        items: [], reviews: [],
        privacyRestricted: false, restrictedFields: [],
        awardCount: 0, topAwardTier: 'none', awardEmojis: [],
      };
    }

    const name = u.name || u.firstName || u.email;
    const image = u.image ?? null;
    const memberSince = (u as any).createdAt ? new Date((u as any).createdAt).getFullYear().toString() : '-';

    // Check if viewer is admin or viewing own profile
    const isSelf = context.user.id === input.userId;
    const viewerIsAdmin = !isSelf && await isAdmin(context.user.id);
    const bypassPrivacy = isSelf || viewerIsAdmin;

    // Get target user's privacy settings
    const profile = await zite.userProfiles.findOne({ filters: { user: input.userId } });
    const profileVisibility = (profile as any)?.profileVisibility || 'public';
    const itemsVisibility = (profile as any)?.itemsVisibility || 'public';
    const showLocation = (profile as any)?.showLocation ?? true;
    const showBarterHistory = (profile as any)?.showBarterHistory ?? true;

    // Check if viewer follows the target (for "followers" visibility)
    let isFollower = false;
    if (!bypassPrivacy && (profileVisibility === 'followers' || itemsVisibility === 'followers')) {
      const { records: follows } = await zite.follows.findAll({
        filters: { follower: context.user.id, followingUserId: input.userId },
        limit: 1,
      });
      isFollower = follows.length > 0;
    }

    const canSeeProfile = bypassPrivacy || profileVisibility === 'public' || (profileVisibility === 'followers' && isFollower);
    const canSeeItems = bypassPrivacy || itemsVisibility === 'public' || (itemsVisibility === 'followers' && isFollower);
    const canSeeLocation = bypassPrivacy || showLocation;
    const canSeeBarterHistory = bypassPrivacy || showBarterHistory;

    const restrictedFields: string[] = [];
    if (!canSeeProfile) restrictedFields.push('profile');
    if (!canSeeItems) restrictedFields.push('items');
    if (!canSeeLocation) restrictedFields.push('location');
    if (!canSeeBarterHistory) restrictedFields.push('barterHistory');

    // Points
    const pts = await zite.userPoints.findOne({ filters: { user: input.userId } });
    const totalPoints = pts?.totalPoints ?? 0;
    const bartersCompleted = canSeeBarterHistory ? (pts?.bartersCompleted ?? 0) : 0;
    const itemsUploaded = pts?.itemsUploaded ?? 0;
    const likesReceived = pts?.likesReceived ?? 0;

    // Recalculate badge from points
    function calcBadge(p: number): string {
      if (p >= 10000) return 'elite';
      if (p >= 5000) return 'mentor';
      if (p >= 2500) return 'legenda';
      if (p >= 1000) return 'profesional';
      if (p >= 500) return 'terpercaya';
      if (p >= 200) return 'aktif';
      return 'pemula';
    }
    const currentBadge = calcBadge(totalPoints);

    const bio = canSeeProfile ? (profile?.bio || '') : '';
    const city = canSeeLocation ? (profile?.city || '') : '';
    const province = canSeeLocation ? (profile?.province || '') : '';
    const phoneVerified = profile?.phoneVerified ?? false;
    const addressVerified = profile?.addressVerified ?? false;
    const instagram = canSeeProfile ? (profile?.instagram || '') : '';
    const twitter = canSeeProfile ? (profile?.twitter || '') : '';

    // Reviews
    let reviews: { id: string; rating: number; comment: string; reviewerName: string; reviewerImage: string | null; createdAt: string | null }[] = [];
    let totalReviews = 0;
    let averageRating = 0;

    if (canSeeProfile) {
      const { records: reviewRecords } = await zite.barterReviews.findAll({
        filters: { reviewee: input.userId },
        limit: 50,
      });

      const allUsers = await zite.auth.findAllUsers({ limit: 200 });
      const userMap = new Map(allUsers.records.map(usr => [usr.id, usr]));

      reviews = reviewRecords.map(r => {
        const reviewerIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
        const reviewer = userMap.get(reviewerIds[0] || '');
        return {
          id: r.id,
          rating: r.rating ?? 0,
          comment: r.comment || '',
          reviewerName: reviewer?.name || 'Pengguna',
          reviewerImage: reviewer?.image ?? null,
          createdAt: r.createdAt ?? null,
        };
      });

      totalReviews = reviews.length;
      averageRating = totalReviews > 0
        ? Math.round((reviews.reduce((s, r) => s + r.rating, 0) / totalReviews) * 10) / 10
        : 0;
    }

    // Items
    let items: { id: string; title: string; photo: string; condition: string; status: string }[] = [];
    if (canSeeItems) {
      const { records: itemRecords } = await zite.items.findAll({
        filters: { owner: input.userId },
        limit: 50,
      });

      items = itemRecords.map(i => ({
        id: i.id,
        title: i.title || '',
        photo: i.photos?.[0]?.url || '',
        condition: i.condition || '',
        status: i.status || 'Tersedia',
      }));
    }

    // Compute lightweight award summary for public profile
    let awardCount = 0;
    let topAwardTier = 'none';
    const awardEmojis: string[] = [];
    const tierRank: Record<string, number> = { diamond: 5, platinum: 4, gold: 3, silver: 2, bronze: 1 };

    // Barter awards
    if (bartersCompleted >= 1) { awardCount++; awardEmojis.push('🤝'); topAwardTier = 'bronze'; }
    if (bartersCompleted >= 10) { awardCount++; awardEmojis.push('🏅'); topAwardTier = 'silver'; }
    if (bartersCompleted >= 50) { awardCount++; awardEmojis.push('🏆'); topAwardTier = 'gold'; }
    if (bartersCompleted >= 100) { awardCount++; topAwardTier = 'platinum'; }
    // Upload awards
    if (itemsUploaded >= 5) { awardCount++; awardEmojis.push('📦'); }
    if (itemsUploaded >= 25) awardCount++;
    if (itemsUploaded >= 100) awardCount++;
    // Likes awards
    if (likesReceived >= 50) { awardCount++; awardEmojis.push('❤️'); }
    if (likesReceived >= 200) awardCount++;
    if (likesReceived >= 500) awardCount++;
    // Trust awards
    if (phoneVerified && addressVerified) { awardCount++; awardEmojis.push('✅'); }
    if (totalReviews >= 5 && averageRating >= 4.9) { awardCount++; awardEmojis.push('⭐'); if ((tierRank[topAwardTier] || 0) < 3) topAwardTier = 'gold'; }
    if (bartersCompleted >= 10) {
      const { rows: vRows } = await zite.sql({ query: `SELECT COUNT(*) as cnt FROM "Violations" WHERE "user" @> to_jsonb(ARRAY[$1]) AND "status" = 'Aktif'`, params: [input.userId] });
      if (((vRows[0]?.cnt as number) || 0) === 0) { awardCount++; awardEmojis.push('🛡️'); }
    }

    return {
      name, image, memberSince, totalPoints, bartersCompleted, itemsUploaded,
      likesReceived, averageRating, totalReviews, bio, city, province,
      phoneVerified, addressVerified, currentBadge, instagram, twitter,
      items, reviews,
      privacyRestricted: restrictedFields.length > 0,
      restrictedFields,
      awardCount,
      topAwardTier,
      awardEmojis: awardEmojis.slice(0, 5),
    };
  },
});

