import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get raffle draw results for recent months and current month ticket count',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    currentMonthTickets: z.number(),
    totalParticipants: z.number(),
    totalTicketsThisMonth: z.number(),
    nextDrawDate: z.string(),
    recentDraws: z.array(z.object({
      drawMonth: z.string(),
      monthLabel: z.string(),
      winners: z.array(z.object({
        placement: z.number(),
        userName: z.string(),
        prizePoints: z.number(),
        prizeBadge: z.string(),
        ticketsUsed: z.number(),
      })),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;
    const now = new Date();
    const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

    // Get user's current month tickets
    const currentMonthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
    const currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);

    const { records: myTickets } = await zite.pointRedemptions.findAll({
      filters: { user: userId },
      limit: 500,
    });
    const myRaffleTickets = myTickets.filter(t => {
      const tp = (t.type || '').toLowerCase();
      const st = (t.status || '').toLowerCase();
      return (tp === 'raffle' || tp === 'raffle ticket') && (st === 'active');
    });
    const currentMonthTickets = myRaffleTickets
      .filter(t => {
        if (!t.expiresAt) return false;
        const exp = new Date(t.expiresAt);
        return exp >= currentMonthStart && exp <= new Date(currentMonthEnd.getTime() + 86400000);
      })
      .reduce((sum, t) => sum + (t.raffleTickets ?? 0), 0);

    // Count all participants & tickets this month
    const { records: allCurrentTickets } = await zite.pointRedemptions.findAll({
      limit: 2000,
    });
    const thisMonthTickets = allCurrentTickets.filter(t => {
      const tp = (t.type || '').toLowerCase();
      const st = (t.status || '').toLowerCase();
      if (!(tp === 'raffle' || tp === 'raffle ticket') || !(st === 'active')) return false;
      if (!t.expiresAt) return false;
      const exp = new Date(t.expiresAt);
      return exp >= currentMonthStart && exp <= new Date(currentMonthEnd.getTime() + 86400000);
    });
    const participantSet = new Set(thisMonthTickets.map(t => (Array.isArray(t.user) ? t.user[0] : t.user)));
    const totalTicketsThisMonth = thisMonthTickets.reduce((sum, t) => sum + (t.raffleTickets ?? 0), 0);

    // Next draw date = 1st of next month
    const nextDraw = new Date(now.getFullYear(), now.getMonth() + 1, 1);

    // Get recent draws (last 3 months)
    const { records: draws } = await zite.raffleDraws.findAll({
      limit: 20,
    });

    // Group by drawMonth
    const grouped: Record<string, typeof draws> = {};
    for (const d of draws) {
      if (!d.drawMonth || d.placement === 0) continue;
      if (!grouped[d.drawMonth]) grouped[d.drawMonth] = [];
      grouped[d.drawMonth].push(d);
    }

    // Build recent draws with user names
    const recentDraws: { drawMonth: string; monthLabel: string; winners: { placement: number; userName: string; prizePoints: number; prizeBadge: string; ticketsUsed: number }[] }[] = [];

    const sortedMonths = Object.keys(grouped).sort().reverse().slice(0, 3);
    for (const month of sortedMonths) {
      const [y, m] = month.split('-');
      const monthDate = new Date(Number(y), Number(m) - 1, 1);
      const monthLabel = monthDate.toLocaleDateString('id-ID', { month: 'long', year: 'numeric' });

      const entries = grouped[month].sort((a, b) => (a.placement ?? 99) - (b.placement ?? 99));
      const winners: typeof recentDraws[0]['winners'] = [];

      for (const e of entries) {
        const uid = Array.isArray(e.winner) ? e.winner[0] : e.winner;
        let userName = 'User';
        if (uid) {
          const { records: users } = await zite.auth.findAllUsers({ filters: { id: uid }, limit: 1 });
          userName = users[0]?.firstName || users[0]?.name || users[0]?.email || 'User';
        }
        winners.push({
          placement: e.placement ?? 0,
          userName,
          prizePoints: e.prizePoints ?? 0,
          prizeBadge: e.prizeBadge ?? '',
          ticketsUsed: e.ticketsUsed ?? 0,
        });
      }

      recentDraws.push({ drawMonth: month, monthLabel, winners });
    }

    return {
      currentMonthTickets,
      totalParticipants: participantSet.size,
      totalTicketsThisMonth,
      nextDrawDate: nextDraw.toISOString(),
      recentDraws,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getAffiliateTier, getNextAffiliateTier, getAffiliateProgress, AFFILIATE_TIERS } from '../lib/affiliate';

export default createEndpoint({
  description: 'Gets the current user referral/affiliate program data with tier info',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    referralCode: z.string(),
    totalReferred: z.number(),
    completedReferrals: z.number(),
    totalBonusPoints: z.number(),
    // Tier info
    currentTier: z.object({
      id: z.string(),
      name: z.string(),
      emoji: z.string(),
      pointsPerReferral: z.number(),
      boostSlots: z.number(),
      boostDurationDays: z.number(),
    }),
    nextTier: z.object({
      id: z.string(),
      name: z.string(),
      emoji: z.string(),
      pointsPerReferral: z.number(),
      boostSlots: z.number(),
      remaining: z.number(),
    }).nullable(),
    progressPercent: z.number(),
    boostsUsedThisMonth: z.number(),
    boostsRemaining: z.number(),
    referrals: z.array(z.object({
      id: z.string(),
      referredName: z.string(),
      referredImage: z.string().nullable(),
      status: z.string(),
      bonusPoints: z.number(),
      createdAt: z.string(),
    })),
    allTiers: z.array(z.object({
      id: z.string(),
      name: z.string(),
      emoji: z.string(),
      minReferrals: z.number(),
      pointsPerReferral: z.number(),
      boostSlots: z.number(),
      boostDurationDays: z.number(),
      description: z.string(),
      unlocked: z.boolean(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    const codeBase = userId.replace(/-/g, '').slice(0, 8).toUpperCase();
    const referralCode = `MUTARI-${codeBase}`;

    const { records } = await zite.referrals.findAll({
      filters: { referrer: userId },
      limit: 200,
    });

    const completedReferrals = records.filter(r => r.status === 'Completed').length;
    const totalBonusPoints = records.reduce((sum, r) => sum + (r.bonusPoints || 0), 0);

    // Tier calculation
    const tier = getAffiliateTier(completedReferrals);
    const nextTier = getNextAffiliateTier(completedReferrals);
    const { percent, remaining } = getAffiliateProgress(completedReferrals);

    // Count boosts used this month (from point history with activityType 'affiliate_boost')
    const now = new Date();
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
    const { records: boostRecords } = await zite.pointHistory.findAll({
      filters: { user: userId, activityType: 'affiliate_boost' },
      limit: 100,
    });
    const boostsUsedThisMonth = boostRecords.filter(b => (b.earnedAt || '') >= monthStart).length;
    const boostsRemaining = Math.max(0, tier.boostSlots - boostsUsedThisMonth);

    // Get referred user details
    const referredUserIds = records
      .map(r => Array.isArray(r.referredUser) ? r.referredUser[0] : r.referredUser)
      .filter(Boolean) as string[];

    let userMap: Record<string, { name: string; image: string | null }> = {};
    if (referredUserIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({
        filters: { id: { in: referredUserIds } },
        limit: 200,
      });
      for (const u of users) {
        userMap[u.id] = { name: u.name || u.email, image: u.image };
      }
    }

    const referrals = records.map(r => {
      const refUserId = Array.isArray(r.referredUser) ? r.referredUser[0] : r.referredUser;
      const u = refUserId ? userMap[refUserId] : undefined;
      return {
        id: r.id,
        referredName: u?.name || 'Pengguna',
        referredImage: u?.image || null,
        status: r.status || 'Pending',
        bonusPoints: r.bonusPoints || 0,
        createdAt: r.createdAt || new Date().toISOString(),
      };
    });

    return {
      referralCode,
      totalReferred: records.length,
      completedReferrals,
      totalBonusPoints,
      currentTier: {
        id: tier.id,
        name: tier.name,
        emoji: tier.emoji,
        pointsPerReferral: tier.pointsPerReferral,
        boostSlots: tier.boostSlots,
        boostDurationDays: tier.boostDurationDays,
      },
      nextTier: nextTier ? {
        id: nextTier.id,
        name: nextTier.name,
        emoji: nextTier.emoji,
        pointsPerReferral: nextTier.pointsPerReferral,
        boostSlots: nextTier.boostSlots,
        remaining,
      } : null,
      progressPercent: percent,
      boostsUsedThisMonth,
      boostsRemaining,
      referrals,
      allTiers: AFFILIATE_TIERS.map(t => ({
        id: t.id,
        name: t.name,
        emoji: t.emoji,
        minReferrals: t.minReferrals,
        pointsPerReferral: t.pointsPerReferral,
        boostSlots: t.boostSlots,
        boostDurationDays: t.boostDurationDays,
        description: t.description,
        unlocked: completedReferrals >= t.minReferrals,
      })),
    };
  },
});

