import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get details of a service barter',
  authenticated: true,
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({
    barter: z.object({
      id: z.string(),
      title: z.string(),
      status: z.string(),
      notes: z.string().nullable(),
      deadlineDays: z.number().nullable(),
      deadlineAt: z.string().nullable(),
      startedAt: z.string().nullable(),
      completedAt: z.string().nullable(),
      itemOwnerConfirmed: z.boolean(),
      providerConfirmed: z.boolean(),
      proofUploaded: z.boolean(),
      proofPhotos: z.array(z.object({ url: z.string() })),
      createdAt: z.string().nullable(),
      item: z.object({
        id: z.string(),
        title: z.string(),
        photo: z.string().nullable(),
      }),
      service: z.object({
        id: z.string(),
        title: z.string(),
        photo: z.string().nullable(),
      }),
      itemOwnerId: z.string(),
      itemOwnerName: z.string(),
      itemOwnerImage: z.string().nullable(),
      providerId: z.string(),
      providerName: z.string(),
      providerImage: z.string().nullable(),
      isItemOwner: z.boolean(),
      isProvider: z.boolean(),
    }),
  }),
  execute: async ({ input, context }) => {
    const b = await zite.serviceBarters.findOne({ id: input.id });
    if (!b) throw new ZiteError('Barter jasa tidak ditemukan');

    const itemOwnerId = Array.isArray(b.itemOwner) ? b.itemOwner[0] : b.itemOwner || '';
    const providerId = Array.isArray(b.serviceProvider) ? b.serviceProvider[0] : b.serviceProvider || '';

    if (itemOwnerId !== context.user.id && providerId !== context.user.id) {
      throw new ZiteError('Anda tidak memiliki akses ke barter ini');
    }

    const itemId = Array.isArray(b.offeredItem) ? b.offeredItem[0] : b.offeredItem || '';
    const serviceId = Array.isArray(b.requestedService) ? b.requestedService[0] : b.requestedService || '';

    let itemTitle = '', itemPhoto: string | null = null;
    if (itemId) {
      const item = await zite.items.findOne({ id: itemId });
      if (item) {
        itemTitle = item.title || '';
        itemPhoto = item.photos?.[0]?.url ?? null;
      }
    }

    let serviceTitle = '', servicePhoto: string | null = null;
    if (serviceId) {
      const svc = await zite.services.findOne({ id: serviceId });
      if (svc) {
        serviceTitle = svc.title || '';
        servicePhoto = svc.portfolio?.[0]?.url ?? null;
      }
    }

    const userIds = [itemOwnerId, providerId].filter(Boolean) as string[];
    const userMap = new Map<string, { name: string; image: string | null }>();
    if (userIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({ filters: { id: { in: userIds } }, limit: 10 });
      users.forEach(u => userMap.set(u.id, { name: u.name || u.email, image: u.image }));
    }

    const ownerInfo = userMap.get(itemOwnerId);
    const provInfo = userMap.get(providerId);

    return {
      barter: {
        id: b.id,
        title: b.title || '',
        status: b.status || 'Menunggu',
        notes: b.notes ?? null,
        deadlineDays: b.deadlineDays ?? null,
        deadlineAt: b.deadlineAt ?? null,
        startedAt: b.startedAt ?? null,
        completedAt: b.completedAt ?? null,
        itemOwnerConfirmed: b.itemOwnerConfirmed ?? false,
        providerConfirmed: b.providerConfirmed ?? false,
        proofUploaded: b.proofUploaded ?? false,
        proofPhotos: (b.completionProof || []).map(p => ({ url: p.url })),
        createdAt: b.createdAt ?? null,
        item: { id: itemId, title: itemTitle, photo: itemPhoto },
        service: { id: serviceId, title: serviceTitle, photo: servicePhoto },
        itemOwnerId,
        itemOwnerName: ownerInfo?.name || 'Pengguna',
        itemOwnerImage: ownerInfo?.image ?? null,
        providerId,
        providerName: provInfo?.name || 'Penyedia Jasa',
        providerImage: provInfo?.image ?? null,
        isItemOwner: itemOwnerId === context.user.id,
        isProvider: providerId === context.user.id,
      },
    };
  },
});

