import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch a single service by ID and increment views',
  authenticated: false,
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({
    service: z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      portfolio: z.array(z.object({ url: z.string(), name: z.string() })),
      categoryId: z.string(),
      categoryName: z.string(),
      categoryIcon: z.string(),
      status: z.string(),
      desiredItems: z.string(),
      location: z.string(),
      estimatedHours: z.number().nullable(),
      completionDays: z.number().nullable(),
      likesCount: z.number(),
      viewsCount: z.number(),
      providerId: z.string(),
      providerName: z.string(),
      providerImage: z.string().nullable(),
      providerPoints: z.number(),
      providerBarterCount: z.number(),
      createdAt: z.string().nullable(),
    }),
  }),
  execute: async ({ input }) => {
    const r = await zite.services.findOne({ id: input.id });
    if (!r) throw new ZiteError('Jasa tidak ditemukan');

    // Increment views
    await zite.services.update({ id: r.id, record: { viewsCount: (r.viewsCount ?? 0) + 1 } });

    const catId = Array.isArray(r.category) ? r.category[0] : r.category || '';
    let catName = '', catIcon = '🔧';
    if (catId) {
      const cat = await zite.serviceCategories.findOne({ id: catId });
      if (cat) { catName = cat.name || ''; catIcon = cat.icon || '🔧'; }
    }

    const pId = Array.isArray(r.provider) ? r.provider[0] : r.provider || '';
    let provName = 'Pengguna', provImage: string | null = null;
    let provPoints = 0, provBarterCount = 0;
    if (pId) {
      const { records: users } = await zite.auth.findAllUsers({ filters: { id: pId }, limit: 1 });
      if (users[0]) { provName = users[0].name || users[0].email; provImage = users[0].image; }
      const { records: pts } = await zite.userPoints.findAll({ filters: { user: pId }, limit: 1 });
      if (pts[0]) { provPoints = pts[0].totalPoints ?? 0; provBarterCount = pts[0].bartersCompleted ?? 0; }
    }

    return {
      service: {
        id: r.id,
        title: r.title || '',
        description: r.description || '',
        portfolio: (r.portfolio || []).map(p => ({ url: p.url, name: '' })),
        categoryId: catId,
        categoryName: catName,
        categoryIcon: catIcon,
        status: r.status || 'Tersedia',
        desiredItems: r.desiredItems || '',
        location: r.location || '',
        estimatedHours: r.estimatedHours ?? null,
        completionDays: r.completionDays ?? null,
        likesCount: r.likesCount ?? 0,
        viewsCount: (r.viewsCount ?? 0) + 1,
        providerId: pId,
        providerName: provName,
        providerImage: provImage,
        providerPoints: provPoints,
        providerBarterCount: provBarterCount,
        createdAt: r.createdAt ?? null,
      },
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Fetch available services with optional search and category filter',
  authenticated: false,
  inputSchema: z.object({
    limit: z.number().optional(),
    search: z.string().optional(),
    categoryId: z.string().optional(),
  }),
  outputSchema: z.object({
    services: z.array(z.object({
      id: z.string(),
      title: z.string(),
      description: z.string(),
      portfolio: z.array(z.object({ url: z.string() })),
      categoryId: z.string(),
      categoryName: z.string(),
      categoryIcon: z.string(),
      status: z.string(),
      desiredItems: z.string(),
      location: z.string(),
      estimatedHours: z.number().nullable(),
      completionDays: z.number().nullable(),
      likesCount: z.number(),
      viewsCount: z.number(),
      providerId: z.string(),
      providerName: z.string(),
      providerImage: z.string().nullable(),
      createdAt: z.string().nullable(),
    })),
  }),
  execute: async ({ input }) => {
    const lim = input.limit || 30;

    const filters: Record<string, unknown> = { status: 'Tersedia' };
    if (input.categoryId) filters.category = input.categoryId;

    const { records } = await zite.services.findAll({ filters, limit: lim });

    // Get categories
    const catIds = [...new Set(records.map(r => {
      const c = r.category;
      return Array.isArray(c) ? c[0] : c;
    }).filter(Boolean))];
    const catMap = new Map<string, { name: string; icon: string }>();
    if (catIds.length > 0) {
      const { records: cats } = await zite.serviceCategories.findAll({ limit: 20 });
      cats.forEach(c => catMap.set(c.id, { name: c.name || '', icon: c.icon || '🔧' }));
    }

    // Get providers
    const providerIds = [...new Set(records.map(r => {
      const p = r.provider;
      return Array.isArray(p) ? p[0] : p;
    }).filter(Boolean))] as string[];
    const providerMap = new Map<string, { name: string; image: string | null }>();
    if (providerIds.length > 0) {
      const { records: users } = await zite.auth.findAllUsers({ filters: { id: { in: providerIds } }, limit: 50 });
      users.forEach(u => providerMap.set(u.id, { name: u.name || u.email, image: u.image }));
    }

    let services = records.map(r => {
      const catId = Array.isArray(r.category) ? r.category[0] : r.category || '';
      const cat = catMap.get(catId);
      const pId = Array.isArray(r.provider) ? r.provider[0] : r.provider || '';
      const prov = providerMap.get(pId);
      return {
        id: r.id,
        title: r.title || '',
        description: r.description || '',
        portfolio: (r.portfolio || []).map(p => ({ url: p.url })),
        categoryId: catId,
        categoryName: cat?.name || '',
        categoryIcon: cat?.icon || '🔧',
        status: r.status || 'Tersedia',
        desiredItems: r.desiredItems || '',
        location: r.location || '',
        estimatedHours: r.estimatedHours ?? null,
        completionDays: r.completionDays ?? null,
        likesCount: r.likesCount ?? 0,
        viewsCount: r.viewsCount ?? 0,
        providerId: pId,
        providerName: prov?.name || 'Pengguna',
        providerImage: prov?.image ?? null,
        createdAt: r.createdAt ?? null,
      };
    });

    if (input.search) {
      const q = input.search.toLowerCase();
      services = services.filter(s =>
        s.title.toLowerCase().includes(q) ||
        s.description.toLowerCase().includes(q) ||
        s.categoryName.toLowerCase().includes(q)
      );
    }

    return { services };
  },
});

