import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Find best barter matches for a given item using value, category, location, and condition scoring',
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    item: z.object({
      id: z.string(),
      title: z.string(),
      img: z.string(),
      priceRange: z.string(),
      condition: z.string(),
      location: z.string(),
    }).nullable(),
    matches: z.array(z.object({
      id: z.string(),
      title: z.string(),
      img: z.string(),
      matchScore: z.number(),
      priceRange: z.string(),
      condition: z.string(),
      location: z.string(),
      ownerName: z.string(),
      ownerInitial: z.string(),
      reasons: z.array(z.string()),
    })),
  }),
  execute: async ({ input }) => {
    const source = await zite.items.findOne({ id: input.itemId });
    if (!source) return { item: null, matches: [] };

    const srcImg = source.photos?.[0]?.url || '';
    const srcMin = source.estimatedValueMin ?? 0;
    const srcMax = source.estimatedValueMax ?? 0;
    const srcMid = (srcMin + srcMax) / 2 || 0;
    const srcLat = source.latitude ?? 0;
    const srcLon = source.longitude ?? 0;

    const fmt = (v: number) => 'Rp' + v.toLocaleString('id-ID');
    const fmtRange = (min: number | undefined, max: number | undefined) => {
      const a = min ?? 0;
      const b = max ?? 0;
      if (a && b && a !== b) return `${fmt(a)} – ${fmt(b)}`;
      if (a) return fmt(a);
      if (b) return fmt(b);
      return '-';
    };

    // Get source category ids
    const srcCatIds: string[] = [];
    if (source.category) {
      const cats = Array.isArray(source.category) ? source.category : [source.category];
      srcCatIds.push(...cats);
    }

    // Fetch other available items (excluding this one)
    const result = await zite.sql({
      query: `
        SELECT i.*, u."name" AS "ownerName"
        FROM "Items" i
        LEFT JOIN "ziteUsers" u ON u.id = i."owner"->>0
        WHERE i."status" = 'Tersedia' AND i.id != $1
        ORDER BY i.created_at DESC
        LIMIT 50
      `,
      params: [input.itemId],
    });

    // Score each candidate
    const scored = result.rows.map((r: Record<string, unknown>) => {
      const cMin = (r.estimatedValueMin as number) ?? 0;
      const cMax = (r.estimatedValueMax as number) ?? 0;
      const cMid = (cMin + cMax) / 2 || 0;
      const cLat = (r.latitude as number) ?? 0;
      const cLon = (r.longitude as number) ?? 0;
      const cCondition = String(r.condition || '');
      const cLocation = String(r.location || '');
      const cLikes = (r.likesCount as number) ?? 0;
      const cViews = (r.viewsCount as number) ?? 0;
      const photos = r.photos as { url: string }[] | null;
      const img = photos?.[0]?.url || '';

      let score = 50; // base
      const reasons: string[] = [];

      // 1. Value similarity (up to 30 pts)
      if (srcMid > 0 && cMid > 0) {
        const diff = Math.abs(srcMid - cMid);
        const ratio = diff / Math.max(srcMid, cMid);
        const valScore = Math.max(0, 30 - ratio * 60);
        score += valScore;
        if (ratio < 0.15) reasons.push('Nilai hampir seimbang');
        else if (ratio < 0.3) reasons.push('Nilai mendekati');
        else if (cMid > srcMid) reasons.push('Nilai sedikit lebih tinggi');
      }

      // 2. Condition match (up to 15 pts)
      const condRank: Record<string, number> = { 'Baru': 4, 'Seperti Baru': 3, 'Baik': 2, 'Cukup': 1 };
      const srcCR = condRank[source.condition || ''] ?? 2;
      const cCR = condRank[cCondition] ?? 2;
      const condDiff = Math.abs(srcCR - cCR);
      score += Math.max(0, 15 - condDiff * 5);
      if (condDiff === 0) reasons.push('Kondisi sama-sama ' + (cCondition || 'baik').toLowerCase());
      else if (cCR >= 3) reasons.push('Kondisi sangat baik');
      else if (cCR >= 2) reasons.push('Kondisi baik');

      // 3. Location proximity (up to 15 pts)
      let distKm = 0;
      if (srcLat && srcLon && cLat && cLon) {
        const R = 6371;
        const dLat = (cLat - srcLat) * Math.PI / 180;
        const dLon = (cLon - srcLon) * Math.PI / 180;
        const a = Math.sin(dLat / 2) ** 2 + Math.cos(srcLat * Math.PI / 180) * Math.cos(cLat * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
        distKm = R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        const locScore = distKm < 2 ? 15 : distKm < 5 ? 10 : distKm < 10 ? 5 : 0;
        score += locScore;
        if (distKm < 3) reasons.push('Lokasi dekat');
      } else {
        score += 5; // neutral
      }

      // 4. Popularity bonus (up to 10 pts)
      if (cLikes > 5) { score += 5; reasons.push('Banyak diminati'); }
      else if (cLikes > 2) score += 3;
      if (cViews > 20) { score += 5; reasons.push('Item populer'); }
      else if (cViews > 5) score += 2;

      // Ensure no reason-less results
      if (reasons.length === 0) reasons.push('Tersedia untuk ditukar');

      // Clamp score
      const finalScore = Math.min(99, Math.max(30, Math.round(score)));

      const ownerName = String(r.ownerName || 'Pemilik');

      return {
        id: String(r.id),
        title: String(r.title || ''),
        img,
        matchScore: finalScore,
        priceRange: fmtRange(cMin || undefined, cMax || undefined),
        condition: cCondition || 'Baik',
        location: distKm > 0 ? `${distKm.toFixed(1)} km` : (cLocation || 'Sekitar Anda'),
        ownerName,
        ownerInitial: ownerName.charAt(0).toUpperCase(),
        reasons,
      };
    });

    // Sort by score desc, take top 10
    scored.sort((a, b) => b.matchScore - a.matchScore);
    const top = scored.slice(0, 10);

    return {
      item: {
        id: source.id,
        title: source.title || '',
        img: srcImg,
        priceRange: fmtRange(srcMin || undefined, srcMax || undefined),
        condition: source.condition || 'Baik',
        location: source.location || '',
      },
      matches: top,
    };
  },
});

