import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get storefront data for a user — their shop page with banner, bio, featured items, all items, and reviews',
  authenticated: true,
  inputSchema: z.object({ userId: z.string() }),
  outputSchema: z.object({
    name: z.string(),
    image: z.string().nullable(),
    storeName: z.string(),
    storeTagline: z.string(),
    storeBanner: z.string(),
    bio: z.string(),
    city: z.string(),
    province: z.string(),
    memberSince: z.string(),
    totalPoints: z.number(),
    bartersCompleted: z.number(),
    itemsUploaded: z.number(),
    likesReceived: z.number(),
    averageRating: z.number(),
    totalReviews: z.number(),
    phoneVerified: z.boolean(),
    addressVerified: z.boolean(),
    instagram: z.string(),
    twitter: z.string(),
    isOwn: z.boolean(),
    featuredItems: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
      condition: z.string(),
      status: z.string(),
      likesCount: z.number(),
    })),
    allItems: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
      condition: z.string(),
      status: z.string(),
      likesCount: z.number(),
    })),
    reviews: z.array(z.object({
      id: z.string(),
      rating: z.number(),
      comment: z.string(),
      reviewerName: z.string(),
      reviewerImage: z.string().nullable(),
      createdAt: z.string().nullable(),
    })),
  }),
  execute: async ({ input, context }) => {
    const isOwn = context.user.id === input.userId;

    const { records: users } = await zite.auth.findAllUsers({
      filters: { id: input.userId },
      limit: 1,
    });
    const u = users[0];
    if (!u) {
      return {
        name: 'Pengguna', image: null, storeName: '', storeTagline: '', storeBanner: '',
        bio: '', city: '', province: '', memberSince: '-', totalPoints: 0,
        bartersCompleted: 0, itemsUploaded: 0, likesReceived: 0,
        averageRating: 0, totalReviews: 0, phoneVerified: false, addressVerified: false,
        instagram: '', twitter: '', isOwn,
        featuredItems: [], allItems: [], reviews: [],
      };
    }

    const name = u.name || u.firstName || u.email;
    const image = u.image ?? null;
    const memberSince = (u as any).createdAt ? new Date((u as any).createdAt).toLocaleDateString('id-ID', { month: 'long', year: 'numeric' }) : '-';

    const profile = await zite.userProfiles.findOne({ filters: { user: input.userId } });
    const pts = await zite.userPoints.findOne({ filters: { user: input.userId } });

    const storeName = profile?.storeName || '';
    const storeTagline = profile?.storeTagline || '';
    const storeBanner = profile?.storeBanner || '';
    const bio = profile?.bio || '';
    const city = profile?.city || '';
    const province = profile?.province || '';
    const instagram = profile?.instagram || '';
    const twitter = profile?.twitter || '';
    const phoneVerified = profile?.phoneVerified ?? false;
    const addressVerified = profile?.addressVerified ?? false;

    const totalPoints = pts?.totalPoints ?? 0;
    const bartersCompleted = pts?.bartersCompleted ?? 0;
    const itemsUploaded = pts?.itemsUploaded ?? 0;
    const likesReceived = pts?.likesReceived ?? 0;

    // All items
    const { records: itemRecords } = await zite.items.findAll({
      filters: { owner: input.userId },
      limit: 100,
    });

    const mapItem = (i: typeof itemRecords[0]) => ({
      id: i.id,
      title: i.title || '',
      photo: i.photos?.[0]?.url || '',
      condition: i.condition || '',
      status: i.status || 'Tersedia',
      likesCount: i.likesCount ?? 0,
    });

    const allItems = itemRecords.map(mapItem);

    // Featured items
    const featuredIds = (profile?.featuredItems || '').split(',').map(s => s.trim()).filter(Boolean);
    const featuredItems = featuredIds.length > 0
      ? featuredIds.map(fid => allItems.find(it => it.id === fid)).filter(Boolean) as typeof allItems
      : allItems.filter(i => i.status === 'Tersedia').slice(0, 4);

    // Reviews
    const { records: reviewRecords } = await zite.barterReviews.findAll({
      filters: { reviewee: input.userId },
      limit: 20,
    });
    const allUsers = await zite.auth.findAllUsers({ limit: 200 });
    const userMap = new Map(allUsers.records.map(usr => [usr.id, usr]));
    const reviews = reviewRecords.map(r => {
      const reviewerIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      const reviewer = userMap.get(reviewerIds[0] || '');
      return {
        id: r.id,
        rating: r.rating ?? 0,
        comment: r.comment || '',
        reviewerName: reviewer?.name || 'Pengguna',
        reviewerImage: reviewer?.image ?? null,
        createdAt: r.createdAt ?? null,
      };
    });

    const totalReviews = reviews.length;
    const averageRating = totalReviews > 0
      ? Math.round((reviews.reduce((s, r) => s + r.rating, 0) / totalReviews) * 10) / 10
      : 0;

    return {
      name, image, storeName, storeTagline, storeBanner, bio, city, province,
      memberSince, totalPoints, bartersCompleted, itemsUploaded, likesReceived,
      averageRating, totalReviews, phoneVerified, addressVerified,
      instagram, twitter, isOwn, featuredItems, allItems, reviews,
    };
  },
});

