import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get active stories (less than 24 hours old)',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    stories: z.array(z.object({
      id: z.string(),
      caption: z.string(),
      mediaUrl: z.string().nullable(),
      authorId: z.string(),
      authorName: z.string(),
      authorImage: z.string().nullable(),
      type: z.string(),
      itemId: z.string().nullable(),
      location: z.string().nullable(),
      viewsCount: z.number(),
      createdAt: z.string(),
      expiresAt: z.string(),
      viewed: z.boolean(),
    })),
    myStory: z.object({
      id: z.string(),
      mediaUrl: z.string().nullable(),
      caption: z.string(),
      viewsCount: z.number(),
      createdAt: z.string(),
    }).nullable(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Get stories that haven't expired (created within last 24h)
    const now = new Date();
    const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

    const result = await zite.sql({
      query: `
        SELECT
          s."caption",
          s."media",
          s."type",
          s."location",
          COALESCE(s."viewsCount", 0) AS "viewsCount",
          s.created_at AS "createdAt",
          s."expiresAt",
          s.id,
          s."author"
        FROM "BarterStories" s
        WHERE s.created_at >= $1
        ORDER BY s.created_at DESC
      `,
      params: [twentyFourHoursAgo.toISOString()],
    });

    // Collect author IDs
    const authorIds = new Set<string>();
    for (const row of result.rows) {
      if (row.author) {
        try {
          const arr = typeof row.author === 'string' ? JSON.parse(row.author) : row.author;
          if (Array.isArray(arr) && arr[0]) authorIds.add(String(arr[0]));
        } catch { /* ignore */ }
      }
    }

    // Fetch user info
    const userMap = new Map<string, { name: string; image: string | null }>();
    if (authorIds.size > 0) {
      const { records } = await zite.auth.findAllUsers({
        filters: { id: { in: Array.from(authorIds) } },
        limit: 100,
      });
      for (const u of records) {
        userMap.set(u.id, { name: u.name || u.email, image: u.image });
      }
    }

    let myStory: any = null;

    const stories = result.rows.map(row => {
      let authorId = '';
      if (row.author) {
        try {
          const arr = typeof row.author === 'string' ? JSON.parse(row.author) : row.author;
          if (Array.isArray(arr) && arr[0]) authorId = String(arr[0]);
        } catch { /* ignore */ }
      }

      let mediaUrl: string | null = null;
      if (row.media) {
        try {
          const arr = typeof row.media === 'string' ? JSON.parse(row.media) : row.media;
          if (Array.isArray(arr) && arr[0]) mediaUrl = arr[0]?.url || null;
        } catch { /* ignore */ }
      }

      const user = userMap.get(authorId);
      const story = {
        id: String(row.id),
        caption: String(row.caption || ''),
        mediaUrl,
        authorId,
        authorName: user?.name || 'User',
        authorImage: user?.image || null,
        type: String(row.type || 'showcase'),
        itemId: null as string | null,
        location: row.location ? String(row.location) : null,
        viewsCount: Number(row.viewsCount || 0),
        createdAt: String(row.createdAt),
        expiresAt: String(row.expiresAt || ''),
        viewed: false, // simplified - could track per-user views later
      };

      if (authorId === userId && !myStory) {
        myStory = {
          id: story.id,
          mediaUrl: story.mediaUrl,
          caption: story.caption,
          viewsCount: story.viewsCount,
          createdAt: story.createdAt,
        };
      }

      return story;
    });

    return { stories, myStory };
  },
});

