import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mengambil riwayat chat support untuk pengguna yang sedang login',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    messages: z.array(z.object({
      id: z.string(),
      content: z.string(),
      senderRole: z.string(),
      read: z.boolean(),
      createdAt: z.string(),
      subject: z.string(),
    })),
  }),
  execute: async ({ context }) => {
    const { records } = await zite.supportMessages.findAll({
      filters: { user: context.user.id },
      limit: 100,
    });

    // Mark admin messages as read
    const unread = records.filter(m => m.senderRole === 'admin' && !m.read);
    for (const m of unread) {
      await zite.supportMessages.update({ id: m.id, record: { read: true } });
    }

    // Sort by sentAt ascending
    const sorted = records.sort(
      (a, b) => new Date(a.sentAt || '').getTime() - new Date(b.sentAt || '').getTime()
    );

    return {
      messages: sorted.map(m => ({
        id: m.id,
        content: m.content || '',
        senderRole: m.senderRole || 'user',
        read: m.read ?? false,
        createdAt: m.sentAt || '',
        subject: m.subject || '',
      })),
    };
  },
});

