import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Gets top barterers ranked by completed barters, synced from live barter history',
  authenticated: false,
  inputSchema: z.object({}),
  outputSchema: z.object({
    users: z.array(z.object({
      id: z.string(),
      name: z.string(),
      image: z.string().nullable(),
      bartersCompleted: z.number(),
      totalPoints: z.number(),
    })),
  }),
  execute: async () => {
    // Query live barter completions from BarterHistory directly
    // Count completed barters where user is initiator or partner
    const { rows } = await zite.sql({
      query: `
        WITH initiator_counts AS (
          SELECT bh."initiator"->>0 AS uid, COUNT(*) AS cnt
          FROM "BarterHistory" bh
          WHERE bh."status" = 'Selesai'
          GROUP BY bh."initiator"->>0
        ),
        partner_counts AS (
          SELECT bh."partner"->>0 AS uid, COUNT(*) AS cnt
          FROM "BarterHistory" bh
          WHERE bh."status" = 'Selesai'
          GROUP BY bh."partner"->>0
        ),
        combined AS (
          SELECT uid, SUM(cnt) AS "bartersCompleted"
          FROM (
            SELECT uid, cnt FROM initiator_counts
            UNION ALL
            SELECT uid, cnt FROM partner_counts
          ) sub
          WHERE uid IS NOT NULL
          GROUP BY uid
        )
        SELECT c.uid, c."bartersCompleted",
               COALESCE(up."totalPoints", 0) AS "totalPoints"
        FROM combined c
        LEFT JOIN LATERAL (
          SELECT "totalPoints"
          FROM "UserPoints"
          WHERE "user"->>0 = c.uid
          LIMIT 1
        ) up ON true
        ORDER BY c."bartersCompleted" DESC, "totalPoints" DESC
        LIMIT 10
      `,
    });

    if (rows.length === 0) {
      // Fallback: try UserPoints table
      const { rows: fallbackRows } = await zite.sql({
        query: `
          SELECT "user"->>0 AS uid, "bartersCompleted", "totalPoints"
          FROM "UserPoints"
          WHERE "bartersCompleted" > 0
          ORDER BY "bartersCompleted" DESC, "totalPoints" DESC
          LIMIT 10
        `,
      });

      if (fallbackRows.length === 0) return { users: [] };

      const fbIds = fallbackRows.map(r => r.uid as string).filter(Boolean);
      const { records: fbAuthUsers } = await zite.auth.findAllUsers({
        filters: { id: { in: fbIds } },
        limit: 10,
      });
      const fbMap = Object.fromEntries(fbAuthUsers.map(u => [u.id, u]));

      return {
        users: fallbackRows
          .map(r => {
            const uid = r.uid as string;
            const u = fbMap[uid];
            if (!u) return null;
            return {
              id: uid,
              name: u.name || u.email?.split('@')[0] || 'User',
              image: u.image || null,
              bartersCompleted: Number(r.bartersCompleted) || 0,
              totalPoints: Number(r.totalPoints) || 0,
            };
          })
          .filter(Boolean) as any[],
      };
    }

    const userIds = rows.map(r => r.uid as string).filter(Boolean);
    const { records: authUsers } = await zite.auth.findAllUsers({
      filters: { id: { in: userIds } },
      limit: 10,
    });
    const userMap = Object.fromEntries(authUsers.map(u => [u.id, u]));

    const users = rows
      .map(r => {
        const uid = r.uid as string;
        const u = userMap[uid];
        if (!u) return null;
        return {
          id: uid,
          name: u.name || u.email?.split('@')[0] || 'User',
          image: u.image || null,
          bartersCompleted: Number(r.bartersCompleted) || 0,
          totalPoints: Number(r.totalPoints) || 0,
        };
      })
      .filter(Boolean) as { id: string; name: string; image: string | null; bartersCompleted: number; totalPoints: number }[];

    return { users };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get trending items based on views, likes, and wishlist activity, with owner points for premium display',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    trending: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string().nullable(),
      category: z.string().nullable(),
      location: z.string().nullable(),
      views: z.number(),
      likes: z.number(),
      wishlistCount: z.number(),
      score: z.number(),
      condition: z.string().nullable(),
      ownerPoints: z.number(),
      ownerBadgeId: z.string(),
      ownerName: z.string(),
      ownerImage: z.string().nullable(),
    })),
    topCategories: z.array(z.object({
      name: z.string(),
      icon: z.string(),
      count: z.number(),
    })),
  }),
  execute: async () => {
    const allUsers = await zite.auth.findAllUsers({ limit: 200 });
    const userMap = new Map(allUsers.records.map(u => [u.id, u]));

    const trendingResult = await zite.sql({
      query: `
        SELECT
          i.id,
          COALESCE(i."title", 'Tanpa Judul') AS title,
          i."photos",
          i."location",
          i."condition",
          i."owner",
          COALESCE(i."viewsCount", 0) AS views,
          COALESCE(i."likesCount", 0) AS likes,
          COUNT(DISTINCT w."wishlistId") AS "wishlistCount",
          (COALESCE(i."viewsCount", 0) + COALESCE(i."likesCount", 0) * 3 + COUNT(DISTINCT w."wishlistId") * 5) AS score,
          COALESCE(up."totalPoints", 0) AS "ownerTotalPoints",
          CASE
            WHEN COALESCE(up."totalPoints", 0) >= 10000 THEN 'elite'
            WHEN COALESCE(up."totalPoints", 0) >= 5000 THEN 'mentor'
            WHEN COALESCE(up."totalPoints", 0) >= 2500 THEN 'legenda'
            WHEN COALESCE(up."totalPoints", 0) >= 1000 THEN 'profesional'
            WHEN COALESCE(up."totalPoints", 0) >= 500 THEN 'terpercaya'
            WHEN COALESCE(up."totalPoints", 0) >= 200 THEN 'aktif'
            ELSE 'pemula'
          END AS "ownerBadge"
        FROM "Items" i
        LEFT JOIN "ItemsWishlist" w ON w."itemsId" = i.id
        LEFT JOIN "UserPoints" up ON up."user"->>0 = i."owner"->>0
        WHERE i."status" = 'Tersedia'
        GROUP BY i.id, up."totalPoints"
        ORDER BY COALESCE(up."totalPoints", 0) DESC, score DESC, i.created_at DESC
        LIMIT 10
      `,
    });

    const catResult = await zite.sql({
      query: `
        SELECT
          c."name",
          COALESCE(c."icon", '📦') AS icon,
          COUNT(DISTINCT ci."itemsId") AS count
        FROM "Categories" c
        LEFT JOIN "CategoriesItems" ci ON ci."categoriesId" = c.id
        LEFT JOIN "Items" i ON i.id = ci."itemsId" AND i."status" = 'Tersedia'
        GROUP BY c.id
        ORDER BY count DESC
        LIMIT 5
      `,
    });

    const trending = trendingResult.rows.map(r => {
      let photo: string | null = null;
      if (r.photos) {
        try {
          const arr = typeof r.photos === 'string' ? JSON.parse(r.photos) : r.photos;
          if (Array.isArray(arr) && arr.length > 0) {
            photo = arr[0]?.url || null;
          }
        } catch { /* ignore */ }
      }

      const ownerIds = Array.isArray(r.owner) ? r.owner as string[] : r.owner ? [r.owner as string] : [];
      const owner = ownerIds[0] ? userMap.get(ownerIds[0]) : null;

      return {
        id: String(r.id),
        title: String(r.title),
        photo,
        category: null as string | null,
        location: r.location ? String(r.location) : null,
        views: Number(r.views || 0),
        likes: Number(r.likes || 0),
        wishlistCount: Number(r.wishlistCount || 0),
        score: Number(r.score || 0),
        condition: r.condition ? String(r.condition) : null,
        ownerPoints: Number(r.ownerTotalPoints ?? 0),
        ownerBadgeId: String(r.ownerBadge || 'pemula'),
        ownerName: owner?.name || 'Pengguna',
        ownerImage: owner?.image ?? null,
      };
    });

    if (trending.length > 0) {
      const catLinks = await zite.sql({
        query: `
          SELECT ci."itemsId", c."name"
          FROM "CategoriesItems" ci
          JOIN "Categories" c ON c.id = ci."categoriesId"
          WHERE ci."itemsId" = ANY($1::uuid[])
        `,
        params: [trending.map(t => t.id)],
      });
      const catMap = new Map<string, string>();
      for (const row of catLinks.rows) {
        catMap.set(String(row.itemsId), String(row.name));
      }
      for (const item of trending) {
        item.category = catMap.get(item.id) || null;
      }
    }

    return {
      trending,
      topCategories: catResult.rows.map(r => ({
        name: String(r.name),
        icon: String(r.icon),
        count: Number(r.count || 0),
      })),
    };
  },
});

