import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const awardSchema = z.object({
  id: z.string(),
  programId: z.string(),
  programName: z.string(),
  emoji: z.string(),
  name: z.string(),
  description: z.string(),
  tier: z.string(),
  earnedAt: z.string().nullable(),
});

export default createEndpoint({
  description: 'Compute all program awards earned by a user — public data',
  authenticated: true,
  inputSchema: z.object({ userId: z.string() }),
  outputSchema: z.object({
    awards: z.array(awardSchema),
    totalAwards: z.number(),
    topTier: z.string(),
  }),
  execute: async ({ input }) => {
    const userId = input.userId;
    const earned: { id: string; programId: string; programName: string; emoji: string; name: string; description: string; tier: string; earnedAt: string | null }[] = [];

    // Helper
    const add = (id: string, pid: string, pn: string, emoji: string, name: string, desc: string, tier: string, date?: string) => {
      earned.push({ id, programId: pid, programName: pn, emoji, name, description: desc, tier, earnedAt: date || null });
    };

    // 1. BARTER awards — from UserPoints.bartersCompleted
    const pts = await zite.userPoints.findOne({ filters: { user: userId } });
    const barters = pts?.bartersCompleted ?? 0;
    const uploads = pts?.itemsUploaded ?? 0;
    const likes = pts?.likesReceived ?? 0;

    if (barters >= 1) add('first_barter', 'barter', 'Barter', '🤝', 'Barterer Pertama', 'Menyelesaikan barter pertama', 'bronze');
    if (barters >= 10) add('barter_10', 'barter', 'Barter', '🏅', '10x Barterer', 'Menyelesaikan 10 barter', 'silver');
    if (barters >= 50) add('barter_50', 'barter', 'Barter', '🏆', '50x Barterer', 'Menyelesaikan 50 barter', 'gold');
    if (barters >= 100) add('barter_100', 'barter', 'Barter', '💯', '100x Barterer', 'Menyelesaikan 100 barter', 'platinum');

    // 2. UPLOAD awards
    if (uploads >= 5) add('upload_5', 'upload', 'Upload', '📦', 'Kurator', 'Mengupload 5 barang', 'bronze');
    if (uploads >= 25) add('upload_25', 'upload', 'Upload', '📦', 'Super Kurator', 'Mengupload 25 barang', 'silver');
    if (uploads >= 100) add('upload_100', 'upload', 'Upload', '📦', 'Master Kurator', 'Mengupload 100 barang', 'gold');

    // 3. POPULARITY awards — likes received
    if (likes >= 50) add('likes_50', 'popularity', 'Popularitas', '❤️', 'Favorit', 'Menerima 50 likes', 'bronze');
    if (likes >= 200) add('likes_200', 'popularity', 'Popularitas', '🌟', 'Superstar', 'Menerima 200 likes', 'silver');
    if (likes >= 500) add('likes_500', 'popularity', 'Popularitas', '💥', 'Viral', 'Menerima 500 likes', 'gold');

    // 4. STREAK awards — max streak from DailyCheckins
    const { rows: streakRows } = await zite.sql({
      query: `SELECT MAX("streakCount") as "maxStreak" FROM "DailyCheckins" WHERE "user" @> to_jsonb(ARRAY[$1])`,
      params: [userId],
    });
    const maxStreak = (streakRows[0]?.maxStreak as number) || 0;
    if (maxStreak >= 7) add('streak_7', 'checkin', 'Check-in', '🔥', 'Streak 7 Hari', 'Check-in 7 hari berturut-turut', 'bronze');
    if (maxStreak >= 30) add('streak_30', 'checkin', 'Check-in', '🔥', 'Streak 30 Hari', 'Check-in 30 hari berturut-turut', 'silver');
    if (maxStreak >= 100) add('streak_100', 'checkin', 'Check-in', '🔥', 'Streak 100 Hari', 'Check-in 100 hari berturut-turut', 'gold');

    // 5. REFERRAL awards
    const { rows: refRows } = await zite.sql({
      query: `SELECT COUNT(*) as cnt FROM "Referrals" WHERE "referrer" @> to_jsonb(ARRAY[$1]) AND "status" = 'Completed'`,
      params: [userId],
    });
    const refCount = (refRows[0]?.cnt as number) || 0;
    if (refCount >= 1) add('referral_1', 'referral', 'Referral', '🎯', 'Pengajak', 'Berhasil mereferensikan 1 user', 'bronze');
    if (refCount >= 5) add('referral_5', 'referral', 'Referral', '🎯', 'Top Referrer', 'Berhasil mereferensikan 5 user', 'silver');
    if (refCount >= 20) add('referral_20', 'referral', 'Referral', '🎯', 'Master Referrer', 'Berhasil mereferensikan 20 user', 'gold');

    // 6. CHALLENGE awards
    const { rows: chalRows } = await zite.sql({
      query: `SELECT COUNT(*) FILTER (WHERE "status" IN ('Target Tercapai', 'Pemenang', 'Reward Diterima')) as completed,
              COUNT(*) FILTER (WHERE "status" = 'Pemenang') as won
              FROM "ChallengeParticipants" WHERE "user" @> to_jsonb(ARRAY[$1])`,
      params: [userId],
    });
    const chalCompleted = (chalRows[0]?.completed as number) || 0;
    const chalWon = (chalRows[0]?.won as number) || 0;
