    if (((violRows[0]?.cnt as number) || 0) === 0 && barters >= 10) {
      add('clean_record', 'trust', 'Kepercayaan', '🛡️', 'Rekor Bersih', '0 pelanggaran dengan 10+ barter', 'silver');
    }

    // Full verification
    const profile = await zite.userProfiles.findOne({ filters: { user: userId } });
    if (profile?.phoneVerified && profile?.addressVerified) {
      add('verified_full', 'trust', 'Kepercayaan', '✅', 'Terverifikasi Penuh', 'Telepon & alamat terverifikasi', 'bronze');
    }

    // 12. GIFT POINTS award
    const { rows: giftRows } = await zite.sql({
      query: `SELECT COUNT(DISTINCT "activityType") as cnt FROM "PointHistory" WHERE "user" @> to_jsonb(ARRAY[$1]) AND "activityType" = 'gift_sent'`,
      params: [userId],
