    // Count how many distinct gift_sent entries (approximation)
    const { rows: giftCount } = await zite.sql({
      query: `SELECT COUNT(*) as cnt FROM "PointHistory" WHERE "user" @> to_jsonb(ARRAY[$1]) AND "activityType" = 'gift_sent'`,
      params: [userId],
    });
    if (((giftCount[0]?.cnt as number) || 0) >= 5) {
      add('generous_giver', 'gift', 'Gift', '🎁', 'Dermawan', 'Mengirim gift points ke 5+ user', 'silver');
