    // Determine top tier
    const tierOrder: Record<string, number> = { diamond: 5, platinum: 4, gold: 3, silver: 2, bronze: 1 };
    const topTier = earned.length > 0
      ? earned.reduce((best, a) => (tierOrder[a.tier] || 0) > (tierOrder[best.tier] || 0) ? a : best).tier
      : 'none';

    // Sort by tier descending
    earned.sort((a, b) => (tierOrder[b.tier] || 0) - (tierOrder[a.tier] || 0));

    return {
      awards: earned,
      totalAwards: earned.length,
      topTier,
    };
  },
});

