import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get violation history and minus points summary for the current user',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    totalMinusPoints: z.number(),
    activeViolations: z.number(),
    pendingReports: z.number(),
    violations: z.array(z.object({
      id: z.string(),
      label: z.string(),
      violationType: z.string(),
      severity: z.string(),
      minusPoints: z.number(),
      status: z.string(),
      notes: z.string(),
      adminNotes: z.string(),
      createdAt: z.string(),
    })),
    bySeverity: z.object({
      berat: z.number(),
      sedang: z.number(),
      ringan: z.number(),
    }),
    // Reports this user filed (as reporter)
    myReports: z.array(z.object({
      id: z.string(),
      label: z.string(),
      status: z.string(),
      createdAt: z.string(),
    })),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;

    // Violations against this user
    const { records } = await zite.violations.findAll({
      filters: { user: userId },
      limit: 100,
    });

    const sorted = records.sort(
      (a, b) => new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime()
    );

    // Only count confirmed (Aktif / Sudah Diperingatkan) for point totals
    const active = sorted.filter(v => v.status === 'Aktif' || v.status === 'Sudah Diperingatkan');
    const totalMinus = active.reduce((sum, v) => sum + (v.minusPoints ?? 0), 0);
    const pendingCount = sorted.filter(v => v.status === 'Menunggu Review').length;

    const bySeverity = { berat: 0, sedang: 0, ringan: 0 };
    active.forEach(v => {
      const sev = (v.severity || '').toLowerCase();
      if (sev === 'berat' || sev === 'paling berat') bySeverity.berat++;
      else if (sev === 'sedang') bySeverity.sedang++;
      else if (sev === 'ringan') bySeverity.ringan++;
    });

    // Reports filed BY this user
    const { records: myReportsRaw } = await zite.violations.findAll({
      filters: { reportedBy: userId },
      limit: 50,
    });

    const myReports = myReportsRaw
      .sort((a, b) => new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime())
      .map(r => ({
        id: r.id,
        label: r.label || '',
        status: r.status || 'Menunggu Review',
        createdAt: r.createdAt || '',
      }));

    return {
      totalMinusPoints: totalMinus,
      activeViolations: active.length,
      pendingReports: pendingCount,
      violations: sorted.map(v => ({
        id: v.id,
        label: v.label || '',
        violationType: v.violationType || '',
        severity: (v.severity || 'Ringan').toLowerCase(),
        minusPoints: v.minusPoints ?? 0,
        status: v.status || 'Menunggu Review',
        notes: v.notes || '',
        adminNotes: (v as any).adminNotes || '',
        createdAt: v.createdAt || '',
      })),
      bySeverity,
      myReports,
    };
  },
});

