import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Get weekly missions and user progress for the current week',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    missions: z.array(z.object({
      id: z.string(),
      userMissionId: z.string().optional(),
      title: z.string(),
      description: z.string(),
      icon: z.string(),
      missionType: z.string(),
      targetCount: z.number(),
      rewardPoints: z.number(),
      currentProgress: z.number(),
      status: z.string(),
    })),
    weekStart: z.string(),
    weekEnd: z.string(),
  }),
  execute: async ({ context }) => {
    const userId = context.user.id;
    const weekStart = getWeekStart();
    const weekEnd = getWeekEnd();

    // Get all active missions
    const { records: allMissions } = await zite.weeklyMissions.findAll({
      filters: { active: true },
      limit: 50,
    });

    // Get or create user missions for this week
    const { records: existingUserMissions } = await zite.userMissions.findAll({
      filters: { user: userId, weekStart },
      limit: 50,
    });

    const missions: Array<{
      id: string; userMissionId: string; title: string; description: string;
      icon: string; missionType: string; targetCount: number; rewardPoints: number;
      currentProgress: number; status: string;
    }> = [];
    for (const mission of allMissions) {
      let userMission = existingUserMissions.find(um =>
        um.mission && um.mission.includes(mission.id)
      );

      // Auto-create user mission for this week if not exists
      if (!userMission) {
        // Calculate initial progress based on type
        const initialProgress = await calculateProgress(userId, mission.missionType ?? '', weekStart);
        const completed = initialProgress >= (mission.targetCount ?? 1);

        userMission = await zite.userMissions.create({
          record: {
            label: `${mission.title} - Week ${weekStart}`,
            user: userId,
            mission: [mission.id],
            currentProgress: initialProgress,
            status: completed ? 'completed' : 'active',
            weekStart,
            rewardClaimed: false,
          },
        });
      }

      missions.push({
        id: mission.id,
        userMissionId: userMission.id,
        title: mission.title ?? '',
        description: mission.description ?? '',
        icon: mission.icon ?? '🎯',
        missionType: mission.missionType ?? '',
        targetCount: mission.targetCount ?? 1,
        rewardPoints: mission.rewardPoints ?? 0,
        currentProgress: userMission.currentProgress ?? 0,
        status: userMission.status ?? 'active',
      });
    }

    return { missions, weekStart, weekEnd };
  },
});

async function calculateProgress(userId: string, missionType: string, weekStart: string): Promise<number> {
  // For newly created missions, check what the user has already done this week
  // This is a basic approximation; real-time tracking happens in the respective endpoints
  switch (missionType) {
    case 'daily_checkin': {
      const { records } = await zite.dailyCheckins.findAll({
        filters: { user: userId },
        limit: 7,
      });
      return records.filter(r => r.checkinDate && r.checkinDate >= weekStart).length;
    }
    default:
      return 0;
  }
}

function getWeekStart(): string {
  const now = new Date();
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? -6 : 1);
  const monday = new Date(now);
  monday.setDate(diff);
  return monday.toISOString().split('T')[0];
}

function getWeekEnd(): string {
  const now = new Date();
  const day = now.getDay();
  const diff = now.getDate() - day + (day === 0 ? 0 : 7);
  const sunday = new Date(now);
  sunday.setDate(diff);
  return sunday.toISOString().split('T')[0];
}

import { z } from 'zod';
