import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const HIGHLIGHT_COST = 200;
const HIGHLIGHT_DAYS = 7;

export default createEndpoint({
  description: 'Spend 200 MP to add a gold highlight frame on a listing for 7 days',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    remainingPoints: z.number(),
    expiresAt: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    const item = await zite.items.findOne({ id: input.itemId });
    if (!item) throw new Error('Item tidak ditemukan');
    const ownerIds = Array.isArray(item.owner) ? item.owner : item.owner ? [item.owner] : [];
    if (!ownerIds.includes(userId)) throw new Error('Kamu hanya bisa highlight barang milikmu sendiri');

    const up = await zite.userPoints.findOne({ filters: { user: userId } });
    if (!up || (up.totalPoints ?? 0) < HIGHLIGHT_COST) throw new Error(`Poin tidak cukup. Kamu butuh ${HIGHLIGHT_COST} MP.`);

    // Check existing active highlight
    const { records: existing } = await zite.pointRedemptions.findAll({
      filters: { user: userId, type: 'highlight', status: 'active' },
      limit: 100,
    });
    const activeHighlight = existing.find(r => {
      const itemIds = Array.isArray(r.item) ? r.item : r.item ? [r.item] : [];
      return itemIds.includes(input.itemId) && r.expiresAt && new Date(r.expiresAt) > new Date();
    });
    if (activeHighlight) throw new Error('Item ini sudah memiliki highlight frame aktif');

    const expiresAt = new Date(Date.now() + HIGHLIGHT_DAYS * 24 * 60 * 60 * 1000);
    const newPoints = (up.totalPoints ?? 0) - HIGHLIGHT_COST;
    await zite.userPoints.update({ id: up.id, record: { totalPoints: newPoints } });

    await zite.pointHistory.create({
      record: {
        activity: `Highlight Frame: ${item.title || 'Item'}`,
        user: userId,
        points: -HIGHLIGHT_COST,
        activityType: 'highlight_frame',
      },
    });

    await zite.pointRedemptions.create({
      record: {
        label: `Highlight: ${item.title || 'Item'}`,
        user: userId,
        type: 'highlight',
        pointsSpent: HIGHLIGHT_COST,
        item: input.itemId,
        expiresAt: expiresAt.toISOString(),
        status: 'active',
        recipientUserId: null,
        raffleTickets: null,
      },
    });

    return { success: true, remainingPoints: newPoints, expiresAt: expiresAt.toISOString() };
  },
});

