import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Join a challenge as a participant',
  authenticated: true,
  inputSchema: z.object({ challengeId: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const challenge = await zite.challenges.findOne({ id: input.challengeId });
    if (!challenge) throw new ZiteError('Challenge not found', 'NOT_FOUND');
    if (challenge.status !== 'Aktif') throw new ZiteError('Challenge belum aktif atau sudah selesai', 'BAD_REQUEST');

    // Check if already joined
    const { rows } = await zite.sql({
      query: `
        SELECT cp.id FROM "ChallengeParticipants" cp
        JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
        WHERE cp2c."challengesId"::text = $1 AND cp."user" @> to_jsonb(ARRAY[$2::text])
        LIMIT 1
      `,
      params: [input.challengeId, context.user.id],
    });

    if (rows.length > 0) throw new ZiteError('Kamu sudah mengikuti challenge ini', 'BAD_REQUEST');

    await zite.challengeParticipants.create({
      record: {
        label: `${context.user.email} - ${challenge.title}`,
        challenge: input.challengeId,
        user: context.user.id,
        progress: 0,
        rank: null,
        status: 'Bergabung',
        friendsInvited: 0,
        friendsActive: 0,
        multiplier: 1,
        totalPointsEarned: 0,
        invitedBy: null,
      },
    });

    return { success: true };
  },
});

