import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Join or leave a community',
  authenticated: true,
  inputSchema: z.object({
    communityId: z.string(),
    action: z.enum(['join', 'leave']),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    message: z.string(),
    pointsEarned: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    const community = await zite.communities.findOne({ id: input.communityId });
    if (!community) throw new Error('Komunitas tidak ditemukan');

    const { records: existing } = await zite.communityMembers.findAll({
      filters: { community: input.communityId, user: userId },
      limit: 1,
    });

    if (input.action === 'join') {
      if (existing.length > 0 && existing[0].status === 'active') {
        throw new Error('Kamu sudah bergabung di komunitas ini');
      }

      const isCreator = (Array.isArray(community.creator) ? community.creator[0] : community.creator) === userId;
      if (isCreator) throw new Error('Kamu adalah pembuat komunitas ini');

      if (existing.length > 0) {
        await zite.communityMembers.update({
          id: existing[0].id,
          record: { status: 'active', role: 'member' },
        });
      } else {
        await zite.communityMembers.create({
          record: {
            label: `${context.user.firstName || 'User'} - Anggota`,
            community: input.communityId,
            user: userId,
            role: 'member',
            status: community.joinMode === 'request' ? 'pending' : 'active',
            pointsEarned: 0,
          },
        });
      }

      // Update member count
      await zite.communities.update({
        id: input.communityId,
        record: { memberCount: (community.memberCount || 0) + 1 },
      });

      // Award bonus points to community creator
      const creatorId = Array.isArray(community.creator) ? community.creator[0] : community.creator;
      if (creatorId) {
        const creatorPoints = await zite.userPoints.findOne({ filters: { user: creatorId } });
        if (creatorPoints) {
          await zite.userPoints.update({
            id: creatorPoints.id,
            record: { totalPoints: (creatorPoints.totalPoints || 0) + 10 },
          });
        }
        await zite.pointHistory.create({
          record: {
            activity: `Anggota baru bergabung di "${community.name}"`,
            user: creatorId,
            points: 10,
            activityType: 'community_member_bonus',
          },
        });
      }

      const status = community.joinMode === 'request' ? 'Permintaan bergabung terkirim' : 'Berhasil bergabung!';
      return { success: true, message: status, pointsEarned: 0 };
    } else {
      // Leave
      if (existing.length === 0) throw new Error('Kamu bukan anggota komunitas ini');
      const isCreator = (Array.isArray(community.creator) ? community.creator[0] : community.creator) === userId;
      if (isCreator) throw new Error('Ketua komunitas tidak bisa keluar. Transfer kepemilikan terlebih dahulu.');

      await zite.communityMembers.update({ id: existing[0].id, record: { status: 'banned' } });
      await zite.communities.update({
        id: input.communityId,
        record: { memberCount: Math.max(0, (community.memberCount || 0) - 1) },
      });

      return { success: true, message: 'Kamu telah keluar dari komunitas', pointsEarned: 0 };
    }
  },
});

