import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Manage community members — promote, demote, or kick (Ketua/Mod only)',
  authenticated: true,
  inputSchema: z.object({
    communityId: z.string(),
    memberId: z.string(), // communityMember record id
    action: z.enum(['promote_mod', 'demote', 'kick']),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Check caller's role
    const { records: callerMembership } = await zite.communityMembers.findAll({
      filters: { community: input.communityId, user: userId, status: 'active' },
      limit: 1,
    });
    if (callerMembership.length === 0) throw new Error('Kamu bukan anggota komunitas ini');

    const callerRole = callerMembership[0].role;
    const isKetua = callerRole === 'Ketua';
    const isMod = callerRole === 'Moderator';

    // Get target member
    const target = await zite.communityMembers.findOne({ id: input.memberId });
    if (!target) throw new Error('Anggota tidak ditemukan');

    const targetRole = target.role || 'Anggota';

    switch (input.action) {
      case 'promote_mod': {
        if (!isKetua) throw new Error('Hanya Ketua yang bisa mempromosikan Moderator');
        if (targetRole === 'Ketua') throw new Error('Tidak bisa mengubah role Ketua');
        if (targetRole === 'Moderator') throw new Error('Sudah menjadi Moderator');
        await zite.communityMembers.update({ id: input.memberId, record: { role: 'Moderator' } });
        return { success: true, message: 'Berhasil dipromosikan menjadi Moderator' };
      }
      case 'demote': {
        if (!isKetua) throw new Error('Hanya Ketua yang bisa menurunkan role');
        if (targetRole === 'Ketua') throw new Error('Tidak bisa menurunkan Ketua');
        if (targetRole === 'Anggota' || targetRole === 'member') throw new Error('Sudah menjadi Anggota biasa');
        await zite.communityMembers.update({ id: input.memberId, record: { role: 'Anggota' } });
        return { success: true, message: 'Role diturunkan menjadi Anggota' };
      }
      case 'kick': {
        if (!isKetua && !isMod) throw new Error('Hanya Ketua atau Moderator yang bisa mengeluarkan anggota');
        if (targetRole === 'Ketua') throw new Error('Tidak bisa mengeluarkan Ketua');
        if (isMod && targetRole === 'Moderator') throw new Error('Moderator tidak bisa mengeluarkan Moderator lain');
        await zite.communityMembers.update({ id: input.memberId, record: { status: 'Diblokir' } });
        // Decrement member count
        const community = await zite.communities.findOne({ id: input.communityId });
        if (community) {
          await zite.communities.update({ id: input.communityId, record: { memberCount: Math.max(0, (community.memberCount || 1) - 1) } });
        }
        return { success: true, message: 'Anggota berhasil dikeluarkan' };
      }
      default:
        throw new Error('Aksi tidak valid');
    }
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Manage community posts — pin/unpin or delete (Ketua/Mod only)',
  authenticated: true,
  inputSchema: z.object({
    communityId: z.string(),
    postId: z.string(),
    action: z.enum(['pin', 'unpin', 'delete']),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Check caller's role
    const { records: callerMembership } = await zite.communityMembers.findAll({
      filters: { community: input.communityId, user: userId, status: 'active' },
      limit: 1,
    });
    if (callerMembership.length === 0) throw new Error('Kamu bukan anggota komunitas ini');

    const callerRole = callerMembership[0].role;
    const isKetua = callerRole === 'Ketua';
    const isMod = callerRole === 'Moderator';

    if (!isKetua && !isMod) throw new Error('Hanya Ketua atau Moderator yang bisa mengelola post');

    const post = await zite.communityPosts.findOne({ id: input.postId });
    if (!post) throw new Error('Post tidak ditemukan');

    switch (input.action) {
      case 'pin': {
        if (!isKetua) throw new Error('Hanya Ketua yang bisa menyematkan post');
        await zite.communityPosts.update({ id: input.postId, record: { pinned: true } });
        return { success: true, message: 'Post berhasil disematkan' };
      }
      case 'unpin': {
        if (!isKetua) throw new Error('Hanya Ketua yang bisa melepas sematan');
        await zite.communityPosts.update({ id: input.postId, record: { pinned: false } });
        return { success: true, message: 'Sematan post dilepas' };
      }
      case 'delete': {
        // Mod can delete regular member posts; Ketua can delete any
        const authorId = Array.isArray(post.author) ? post.author[0] : post.author || '';
        if (isMod && !isKetua) {
          // Check if author is Ketua — mod can't delete Ketua's posts
          const { records: authorMembership } = await zite.communityMembers.findAll({
            filters: { community: input.communityId, user: authorId, status: 'active' },
            limit: 1,
          });
          if (authorMembership.length > 0 && authorMembership[0].role === 'Ketua') {
            throw new Error('Moderator tidak bisa menghapus post Ketua');
          }
        }
        await zite.communityPosts.delete({ id: input.postId });
        return { success: true, message: 'Post berhasil dihapus' };
      }
      default:
        throw new Error('Aksi tidak valid');
    }
  },
});

