import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Mark one or all notifications as read',
  authenticated: true,
  inputSchema: z.object({
    notificationId: z.string().optional(),
    markAll: z.boolean().optional(),
    markAllType: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), updated: z.number() }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    if (input.markAllType) {
      const { rows } = await zite.sql({
        query: `UPDATE "Notifications" SET "read" = true
                WHERE "type" = $1 AND "read" = false
                AND "recipient" @> to_jsonb(ARRAY[$2])
                RETURNING "id"`,
        params: [input.markAllType, userId],
      });
      return { success: true, updated: rows.length };
    }

    if (input.markAll) {
      const { records } = await zite.notifications.findAll({
        filters: { recipient: userId, read: false },
        limit: 200,
      });
      for (const n of records) {
        await zite.notifications.update({ id: n.id, record: { read: true } });
      }
      return { success: true, updated: records.length };
    }

    if (input.notificationId) {
      await zite.notifications.update({ id: input.notificationId, record: { read: true } });
      return { success: true, updated: 1 };
    }

    return { success: true, updated: 0 };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'AI Mikro: cari 1 barang milik user yang paling cocok untuk ditukar dengan barang target',
  authenticated: true,
  inputSchema: z.object({
    targetItemId: z.string(),
  }),
  outputSchema: z.object({
    found: z.boolean(),
    targetTitle: z.string(),
    targetEstMin: z.number(),
    targetEstMax: z.number(),
    myItem: z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
      condition: z.string(),
      estimatedMin: z.number(),
      estimatedMax: z.number(),
      matchScore: z.number(),
      reasons: z.array(z.string()),
    }).nullable(),
    aiExplanation: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // 1. Get the target item (the item user wants to barter with)
    const target = await zite.items.findOne({ id: input.targetItemId });
    if (!target) {
      return { found: false, targetTitle: '', targetEstMin: 0, targetEstMax: 0, myItem: null, aiExplanation: 'Barang tidak ditemukan.' };
    }

    const targetMin = (target.estimatedValueMin as number) ?? 0;
    const targetMax = (target.estimatedValueMax as number) ?? 0;
    const targetMid = (targetMin + targetMax) / 2;

    // 2. Get ALL my items that are available
    const { records: myItems } = await zite.items.findAll({
      filters: { owner: userId, status: 'Tersedia' },
      limit: 100,
    });

    if (myItems.length === 0) {
      return {
        found: false,
        targetTitle: target.title || '',
        targetEstMin: targetMin,
        targetEstMax: targetMax,
        myItem: null,
        aiExplanation: 'Kamu belum punya barang yang dipublish. Upload barang dulu untuk mulai barter!',
      };
    }

    // 3. Score each of my items against the target
    const condRank: Record<string, number> = { 'Baru': 4, 'Seperti Baru': 3, 'Baik': 2, 'Cukup': 1 };
    const targetCondRank = condRank[target.condition || ''] ?? 2;

    const scored = myItems.map(item => {
      let score = 50;
      const reasons: string[] = [];

      const myMin = (item.estimatedValueMin as number) ?? 0;
      const myMax = (item.estimatedValueMax as number) ?? 0;
      const myMid = (myMin + myMax) / 2;

      // Value similarity (up to 35 pts)
      if (targetMid > 0 && myMid > 0) {
        const diff = Math.abs(targetMid - myMid);
        const ratio = diff / Math.max(targetMid, myMid);
        const valScore = Math.max(0, 35 - ratio * 70);
        score += valScore;
        if (ratio < 0.1) reasons.push('Nilai sangat seimbang');
        else if (ratio < 0.25) reasons.push('Nilai mendekati seimbang');
        else if (ratio < 0.4) reasons.push('Nilai cukup seimbang');
      } else if (myMin === 0 && myMax === 0) {
        // No estimate yet — neutral score
        reasons.push('Estimasi harga belum tersedia');
      }

      // Condition similarity (up to 15 pts)
      const myCondRank = condRank[item.condition || ''] ?? 2;
      const condDiff = Math.abs(targetCondRank - myCondRank);
      score += Math.max(0, 15 - condDiff * 5);
      if (condDiff === 0) reasons.push('Kondisi setara');
      else if (myCondRank >= targetCondRank) reasons.push('Kondisi barangmu sama atau lebih baik');

      // Clamp
      const finalScore = Math.min(99, Math.max(20, Math.round(score)));

      let photo = '';
      if (item.photos && Array.isArray(item.photos) && item.photos.length > 0) {
        photo = (item.photos[0] as { url: string })?.url || '';
      }

      return {
        id: item.id,
        title: item.title || 'Tanpa judul',
        photo,
        condition: item.condition || '-',
        estimatedMin: myMin,
        estimatedMax: myMax,
        matchScore: finalScore,
        reasons,
      };
    });

    // Sort by score desc → pick the best one
    scored.sort((a, b) => b.matchScore - a.matchScore);
    const best = scored[0];

    // 4. Generate AI explanation using Gemini (if available)
    let aiExplanation = '';
    const apiKey = process.env.ZITE_GEMINI_API_KEY;

    if (apiKey && best) {
      try {
        const prompt = `Kamu adalah AI asisten barter bernama MUTARI. Pengguna ingin menukar barang orang lain dengan barang miliknya.

Barang yang diinginkan: "${target.title}" (kondisi: ${target.condition}, estimasi harga: Rp${targetMin.toLocaleString('id-ID')} - Rp${targetMax.toLocaleString('id-ID')})

Barang milik pengguna yang paling cocok: "${best.title}" (kondisi: ${best.condition}, estimasi harga: Rp${best.estimatedMin.toLocaleString('id-ID')} - Rp${best.estimatedMax.toLocaleString('id-ID')}, skor kecocokan: ${best.matchScore}%)

Berikan penjelasan singkat (2-3 kalimat) dalam bahasa Indonesia mengapa barang ini cocok untuk ditukar. Sebutkan perbandingan nilai dan kondisi. Jangan pakai markdown.`;

        const models = ['gemini-3.6-flash'];
        let aiRes: Response | null = null;
        for (const model of models) {
          aiRes = await fetch(
            `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }] }),
            }
          );
          if (aiRes.ok || (aiRes.status !== 429 && aiRes.status !== 503)) break;
        }

        if (aiRes?.ok) {
          const d = await aiRes.json();
          aiExplanation = d?.candidates?.[0]?.content?.parts?.[0]?.text || '';
        }
      } catch {
        // Fallback to static explanation
      }
    }

    // Fallback explanation
    if (!aiExplanation && best) {
      const fmt = (v: number) => 'Rp' + v.toLocaleString('id-ID');
      if (best.matchScore >= 80) {
        aiExplanation = `"${best.title}" sangat cocok untuk ditukar dengan "${target.title}". Nilai dan kondisi kedua barang seimbang, sehingga peluang barter berhasil sangat tinggi.`;
      } else if (best.matchScore >= 60) {
        aiExplanation = `"${best.title}" cukup cocok untuk ditukar. Estimasi harga barangmu ${fmt(best.estimatedMin)}-${fmt(best.estimatedMax)} mendekati harga ${target.title} ${fmt(targetMin)}-${fmt(targetMax)}.`;
      } else {
        aiExplanation = `"${best.title}" adalah pilihan terbaik dari barang-barangmu, meski ada perbedaan nilai. Kamu bisa coba tawarkan dan negosiasi dengan pemilik.`;
      }
    }

    return {
      found: true,
      targetTitle: target.title || '',
      targetEstMin: targetMin,
      targetEstMax: targetMax,
      myItem: best || null,
      aiExplanation,
    };
  },
});

