import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Sends notifications to all users when a new challenge starts',
  authenticated: true,
  inputSchema: z.object({ challengeId: z.string() }),
  outputSchema: z.object({ notified: z.number() }),
  execute: async ({ input }) => {
    const challenge = await zite.challenges.findOne({ id: input.challengeId });
    if (!challenge) throw new ZiteError('Challenge not found', 'NOT_FOUND');

    // Get all app users
    const { records: users } = await zite.auth.findAllUsers({
      appIds: ['exc3bfzedf'],
      limit: 500,
    });

    if (users.length === 0) return { notified: 0 };

    // Create notifications in batches of 100
    let notified = 0;
    const batches: any[][] = [];
    for (let i = 0; i < users.length; i += 100) {
      batches.push(users.slice(i, i + 100));
    }

    for (const batch of batches) {
      const records = batch.map(u => ({
        title: `🔥 Challenge Baru: ${challenge.title}`,
        body: challenge.description
          ? `${challenge.description.slice(0, 100)}${challenge.description.length > 100 ? '...' : ''}`
          : 'Ada challenge baru di MUTARI! Yuk ikutan dan menangkan hadiah.',
        type: 'System' as const,
        recipient: u.id,
        read: false,
        linkPath: `/challenge/${challenge.id}`,
      }));

      await zite.notifications.bulkCreate({ records });
      notified += batch.length;
    }

    return { notified };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { enforceBan } from '../lib/banCheck';

export default createEndpoint({
  description: 'Post a comment on an item',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
    content: z.string().min(1).max(500),
  }),
  outputSchema: z.object({
    id: z.string(),
    content: z.string(),
    authorName: z.string(),
    authorImage: z.string().nullable(),
    authorId: z.string(),
    createdAt: z.string(),
  }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);
    const record = await zite.comments.create({
      record: {
        label: `${context.user.id}-${input.itemId}`,
        author: context.user.id,
        item: input.itemId,
        content: input.content,
      },
    });

    const { records: users } = await zite.auth.findAllUsers({
      filters: { id: context.user.id },
      limit: 1,
    });
    const user = users[0];

    // Notify item owner about new comment
    const item = await zite.items.findOne({ id: input.itemId });
    if (item) {
      const ownerId = Array.isArray(item.owner) ? item.owner[0] : item.owner;
      if (ownerId && ownerId !== context.user.id) {
        const commenterName = user?.name || user?.firstName || user?.email?.split('@')[0] || 'Seseorang';
        await zite.notifications.create({
          record: {
            title: `💬 Komentar baru di "${item.title || 'Barang'}"`,
            body: `${commenterName}: ${input.content.length > 80 ? input.content.slice(0, 80) + '…' : input.content}`,
            type: 'Comment',
            recipient: ownerId,
            read: false,
            linkPath: `/item/${input.itemId}`,
          },
        });
      }
    }

    return {
      id: record.id,
      content: input.content,
      authorName: user?.name || user?.firstName || user?.email || 'Anonim',
      authorImage: user?.image ?? null,
      authorId: context.user.id,
      createdAt: record.createdAt || new Date().toISOString(),
    };
  },
});

