import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Propose premium insurance for high-value barter — minimum 60 points, requires other party approval',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    amount: z.number().min(60, 'Minimal asuransi premium adalah 60 poin'),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    if (barter.status !== 'Diterima') {
      throw new ZiteError('Asuransi premium hanya bisa diusulkan setelah barter diterima');
    }

    if (barter.premiumInsuranceStatus === 'Disetujui') {
      throw new ZiteError('Asuransi premium sudah aktif untuk barter ini');
    }

    if (barter.premiumInsuranceStatus === 'Diusulkan') {
      throw new ZiteError('Sudah ada usulan asuransi premium yang menunggu persetujuan');
    }

    // Check proposer has enough points
    const userPoints = await zite.userPoints.findOne({ filters: { user: context.user.id } });
    if (!userPoints || (userPoints.totalPoints ?? 0) < input.amount) {
      throw new ZiteError(`Poin Anda tidak cukup. Dibutuhkan minimal ${input.amount} MP.`);
    }

    // Update barter with premium insurance proposal
    await zite.barterHistory.update({
      id: input.barterId,
      record: {
        premiumInsuranceAmount: input.amount,
        premiumInsuranceStatus: 'Diusulkan',
        premiumInsuranceProposedBy: context.user.id,
      },
    });

    const userName = context.user.firstName || context.user.email.split('@')[0];
    const otherUserId = context.user.id === initiatorId ? partnerId : initiatorId;

    // System message
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: `🛡️ ${userName} mengusulkan Asuransi Penjaminan Barang sebesar ${input.amount} MP per orang.\n\n📋 Tujuan: Melindungi kedua pihak dari risiko ketidaksesuaian barang bernilai tinggi. Jika salah satu pihak melanggar perjanjian, seluruh poin asuransi premium hangus dan diberikan sebagai kompensasi ke pihak lain.\n\n💰 Biaya admin: ${Math.ceil(input.amount * 3 / 100)} MP (3%) akan dipotong otomatis saat pengembalian jika barter selesai dengan baik.\n\n⏳ Menunggu persetujuan pihak lain...`,
        type: 'System',
      },
    });

    // Notify other party
    if (otherUserId) {
      await zite.notifications.create({
        record: {
          title: '🛡️ Usulan Asuransi Premium',
          body: `${userName} mengusulkan asuransi penjaminan barang ${input.amount} MP untuk barter ini. Setuju?`,
          type: 'Barter',
          recipient: otherUserId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { success: true };
  },
});

