import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const VIOLATION_POINTS: Record<string, number> = {
  multi_nego_ghost: -35,
  cherry_picker: -30,
  cod_egois: -28,
  upgrade_hunter: -27,
  fake_listing: -25,
  fake_proof: -50,
  no_show: -15,
  not_delivered: -30,
  bad_quality: -20,
  late_delivery: -20,
  abusive: -10,
  item_mismatch: -10,
  cancel_after_cod_set: -8,
  cancel_after_deal: -7,
  ghosting: -3,
  expired_repeated: -2,
  slow_response: -1,
  incomplete_listing: -1,
  last_minute_change: -1,
  other: -5,
};

const VIOLATION_SEVERITY: Record<string, string> = {
  multi_nego_ghost: 'paling_berat',
  cherry_picker: 'paling_berat',
  cod_egois: 'paling_berat',
  upgrade_hunter: 'paling_berat',
  fake_proof: 'paling_berat',
  fake_listing: 'berat',
  not_delivered: 'berat',
  no_show: 'berat',
  item_mismatch: 'berat',
  bad_quality: 'sedang',
  late_delivery: 'sedang',
  cancel_after_cod_set: 'sedang',
  cancel_after_deal: 'sedang',
  ghosting: 'sedang',
  expired_repeated: 'sedang',
  abusive: 'ringan',
  slow_response: 'ringan',
  incomplete_listing: 'ringan',
  last_minute_change: 'ringan',
  other: 'sedang',
};

const VIOLATION_LABELS: Record<string, string> = {
  multi_nego_ghost: 'Multi-Negosiasi Ghost',
  cherry_picker: 'Cherry-Picker',
  cod_egois: 'COD Egois',
  upgrade_hunter: 'Upgrade Hunter',
  fake_listing: 'Fake Listing',
  fake_proof: 'Bukti Palsu / Penipuan',
  no_show: 'Tidak Hadir COD',
  not_delivered: 'Jasa Tidak Dikerjakan',
  bad_quality: 'Hasil Tidak Sesuai Perjanjian',
  late_delivery: 'Melewati Deadline',
  abusive: 'Komunikasi Kasar',
  item_mismatch: 'Barang Tidak Sesuai',
  cancel_after_cod_set: 'Batal Setelah COD Di-set',
  cancel_after_deal: 'Batal Sepihak Setelah Deal',
  ghosting: 'Ghosting Negosiasi',
  expired_repeated: 'Barter Expired Berulang',
  slow_response: 'Respons Lambat Berulang',
  incomplete_listing: 'Listing Tidak Lengkap',
  last_minute_change: 'Ubah Syarat di Menit Terakhir',
  other: 'Lainnya',
};

export default createEndpoint({
  description: 'Report a violation against a user — creates a pending report for admin review (no auto-enforcement)',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
    violationType: z.string(),
    barterId: z.string().optional(),
    notes: z.string().optional(),
    evidenceUrls: z.array(z.string()).optional(),
    reportedUserName: z.string().optional(),
    reportedUserPhone: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    violation: z.object({
      id: z.string(),
      type: z.string(),
      severity: z.string(),
      minusPoints: z.number(),
      status: z.string(),
    }),
  }),
  execute: async ({ input, context }) => {
    // Prevent self-report
    if (input.userId === context.user.id) {
      throw new ZiteError('Tidak bisa melaporkan diri sendiri');
    }

    // Require kronologi/notes
    if (!input.notes || !input.notes.trim()) {
      throw new ZiteError('Kronologi / keterangan wajib diisi untuk melaporkan pelanggaran');
    }

    const minusPoints = VIOLATION_POINTS[input.violationType] ?? -5;
    const severity = VIOLATION_SEVERITY[input.violationType] ?? 'sedang';
    const label = VIOLATION_LABELS[input.violationType] ?? input.violationType;

    // Build detailed notes with reporter info
    const detailParts: string[] = [];
    if (input.reportedUserName) detailParts.push(`Nama terlapor: ${input.reportedUserName}`);
    if (input.reportedUserPhone) detailParts.push(`No. HP terlapor: ${input.reportedUserPhone}`);
    if (input.notes) detailParts.push(`Keterangan: ${input.notes}`);
    if (input.barterId) detailParts.push(`Barter ID: ${input.barterId}`);
    detailParts.push(`Dilaporkan oleh: ${context.user.firstName || context.user.email}`);
    const fullNotes = detailParts.join('\n');

    // Build evidence attachments
    const evidenceAttachments = (input.evidenceUrls || []).map((url, i) => ({
      url,
      filename: `bukti-${i + 1}.jpg`,
    }));

    // Resolve barterId — only set the linked_record `barter` field if the ID
    // belongs to the Barter History table. Service Barter IDs would cause
    // "Invalid linked record IDs" errors, so we skip them and store the ref in notes.
    let validBarterLink: string | null = null;
    if (input.barterId) {
      try {
        const barterRecord = await zite.barterHistory.findOne({ id: input.barterId });
        if (barterRecord) validBarterLink = input.barterId;
      } catch {
        // Not a valid Barter History ID (e.g. it's a Service Barter ID) — skip
      }
    }

    // ─── CREATE with "Menunggu Review" status ───
    // Points will NOT be deducted until admin approves the report
    const violation = await zite.violations.create({
      record: {
        label,
        user: input.userId,
        violationType: label,
        severity: severity === 'paling_berat' ? 'Paling Berat' : severity === 'berat' ? 'Berat' : severity === 'sedang' ? 'Sedang' : 'Ringan',
        minusPoints,
        barter: validBarterLink,
        reportedBy: context.user.id,
        notes: fullNotes,
        status: 'Menunggu Review',
        evidence: evidenceAttachments.length > 0 ? evidenceAttachments : null,
      } as any,
    });

    // Notify the reported user that a report was filed (but no action yet)
    await zite.notifications.create({
      record: {
        title: '📋 Laporan Masuk',
        body: `Ada laporan "${label}" terhadap akun kamu. Laporan ini sedang ditinjau oleh admin MUTARI. Belum ada sanksi yang diterapkan.`,
        type: 'System',
        recipient: input.userId,
        read: false,
        linkPath: '/wallet',
      },
    });

    // Notify the reporter that their report is being reviewed
    await zite.notifications.create({
      record: {
        title: '📋 Laporan Dikirim',
        body: `Laporan "${label}" kamu sedang ditinjau oleh admin MUTARI. Kami akan memberi tahu hasilnya. ⚠️ Laporan palsu dapat dikenakan sanksi.`,
        type: 'System',
        recipient: context.user.id,
        read: false,
        linkPath: '/wallet',
      },
    });

    return {
      success: true,
      violation: {
        id: violation.id,
        type: input.violationType,
        severity,
        minusPoints,
        status: 'Menunggu Review',
      },
    };
  },
});

