import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { enforceBan } from '../lib/banCheck';

const DEPOSIT_AMOUNT = 20;

export default createEndpoint({
  description: 'Accept or reject a barter offer — accepting holds deposit points from both parties as insurance',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    action: z.enum(['accept', 'reject']),
  }),
  outputSchema: z.object({ success: z.boolean(), status: z.string(), depositHeld: z.number() }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== partnerId) {
      throw new ZiteError('Hanya penerima yang bisa merespons');
    }
    if (barter.status !== 'Menunggu') {
      throw new ZiteError('Penawaran sudah direspons');
    }

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const newStatus = input.action === 'accept' ? 'Diterima' : 'Dibatalkan';

    if (input.action === 'accept') {
      // === BARTER INSURANCE: hold deposits from both parties ===
      for (const userId of [initiatorId, partnerId]) {
        if (!userId) continue;
        // Check user has enough points
        const userPoints = await zite.userPoints.findOne({ filters: { user: userId } });
        const currentPoints = userPoints?.totalPoints ?? 0;
        if (currentPoints < DEPOSIT_AMOUNT) {
          // If either party doesn't have enough, still proceed but with 0 deposit
          await zite.barterDeposits.create({
            record: {
              label: `Deposit ${userId} → Barter`,
              barter: input.barterId,
              user: userId,
              amount: 0,
              status: 'Held',
              resolutionNote: 'Poin tidak cukup untuk deposit',
            },
          });
          continue;
        }

        // Deduct points
        await zite.userPoints.update({
          id: userPoints!.id,
          record: { totalPoints: currentPoints - DEPOSIT_AMOUNT },
        });

        // Record deposit
        await zite.barterDeposits.create({
          record: {
            label: `Deposit ${userId} → Barter`,
            barter: input.barterId,
            user: userId,
            amount: DEPOSIT_AMOUNT,
            status: 'Held',
            resolutionNote: null,
          },
        });

        // Point history
        await zite.pointHistory.create({
          record: {
            activity: 'Jaminan Barter (ditahan)',
            user: userId,
            points: -DEPOSIT_AMOUNT,
            activityType: 'barter_deposit_hold',
          },
        });
      }
    }

    await zite.barterHistory.update({ id: input.barterId, record: { status: newStatus } });

    if (input.action === 'reject') {
      const offeredId = Array.isArray(barter.offeredItem) ? barter.offeredItem[0] : barter.offeredItem;
      const requestedId = Array.isArray(barter.requestedItem) ? barter.requestedItem[0] : barter.requestedItem;
      if (offeredId) await zite.items.update({ id: offeredId, record: { status: 'Tersedia' } });
      if (requestedId) await zite.items.update({ id: requestedId, record: { status: 'Tersedia' } });
    }

    // System message
    const depositMsg = input.action === 'accept' ? `\n🛡️ Jaminan ${DEPOSIT_AMOUNT} poin ditahan dari kedua pihak sebagai asuransi barter.` : '';
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: input.action === 'accept'
          ? `✅ Penawaran diterima! Silakan tentukan lokasi COD.${depositMsg}`
          : '❌ Penawaran ditolak.',
        type: 'System',
      },
    });

    // Notify initiator
    if (initiatorId) {
      await zite.notifications.create({
        record: {
          title: input.action === 'accept' ? 'Penawaran Diterima! 🎉' : 'Penawaran Ditolak',
          body: input.action === 'accept'
            ? `${context.user.firstName || context.user.email.split("@")[0]} menerima penawaran barter Anda. 🛡️ ${DEPOSIT_AMOUNT} poin jaminan ditahan.`
            : `${context.user.firstName || context.user.email.split("@")[0]} menolak penawaran barter Anda`,
          type: 'Barter',
          recipient: initiatorId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { success: true, status: newStatus, depositHeld: input.action === 'accept' ? DEPOSIT_AMOUNT : 0 };
  },
});

