import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Approve or reject a proposed delivery method (COD or shipping)',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    action: z.enum(['approve', 'reject']),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Only the other party (not the proposer) can approve/reject
    if (barter.deliveryMethodProposedBy === context.user.id) {
      throw new ZiteError('Anda yang mengusulkan — tunggu persetujuan pihak lain');
    }

    if (!barter.deliveryMethod) {
      throw new ZiteError('Tidak ada usulan metode pengiriman');
    }

    const userName = context.user.firstName || context.user.email.split('@')[0];
    const recipientId = context.user.id === initiatorId ? partnerId : initiatorId;
    const isCod = barter.deliveryMethod === 'COD (Ketemu Langsung)';
    const methodLabel = isCod ? `COD: ${barter.codAddress?.split('[')[0]?.trim() || barter.codAddress}` : `Jasa Kirim: ${barter.shippingService || ''}`;

    if (input.action === 'approve') {
      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          deliveryMethodApproved: true,
          ...(isCod ? { codApproved: true } : {}),
        },
      });

      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `✅ ${userName} menyetujui metode tukar barang: ${methodLabel}\n\n🎯 Kedua pihak sudah sepakat! Silakan lanjutkan proses tukar barang, lalu tekan "Selesai Barter" jika sudah selesai.`,
          type: 'System',
        },
      });

      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: `✅ Metode Tukar Disetujui`,
            body: `${userName} menyetujui ${isCod ? 'lokasi COD' : `pengiriman via ${barter.shippingService}`}`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    } else {
      // Reject: clear delivery method
      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          deliveryMethod: null,
          deliveryMethodProposedBy: null,
          deliveryMethodApproved: false,
          shippingService: null,
          codAddress: null,
          codDetail: null,
          codProposedBy: null,
          codApproved: false,
        },
      });

      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `❌ ${userName} menolak usulan: ${methodLabel}.\nSilakan usulkan metode tukar barang yang baru.`,
          type: 'System',
        },
      });

      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: `❌ Metode Tukar Ditolak`,
            body: `${userName} menolak ${isCod ? 'lokasi COD' : `pengiriman via ${barter.shippingService}`}. Usulkan metode baru.`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    }

    return { success: true };
  },
});

