import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Accept or reject a premium insurance proposal — if accepted, points are held from both parties',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    action: z.enum(['accept', 'reject']),
  }),
  outputSchema: z.object({ success: z.boolean(), status: z.string(), amountHeld: z.number() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    if (barter.status !== 'Diterima') {
      throw new ZiteError('Barter tidak dalam status aktif');
    }

    if (barter.premiumInsuranceStatus !== 'Diusulkan') {
      throw new ZiteError('Tidak ada usulan asuransi premium yang menunggu');
    }

    // Only the OTHER party (not the proposer) can respond
    if (context.user.id === barter.premiumInsuranceProposedBy) {
      throw new ZiteError('Anda yang mengusulkan — tunggu persetujuan pihak lain');
    }

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    const amount = barter.premiumInsuranceAmount ?? 60;
    const proposerId = barter.premiumInsuranceProposedBy || '';
    const userName = context.user.firstName || context.user.email.split('@')[0];

    if (input.action === 'reject') {
      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          premiumInsuranceStatus: 'Ditolak',
        },
      });

      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `❌ ${userName} menolak usulan asuransi premium ${amount} MP. Barter tetap berjalan dengan jaminan standar.`,
          type: 'System',
        },
      });

      if (proposerId) {
        await zite.notifications.create({
          record: {
            title: 'Asuransi Premium Ditolak',
            body: `${userName} menolak usulan asuransi premium ${amount} MP. Barter tetap berjalan dengan jaminan standar.`,
            type: 'Barter',
            recipient: proposerId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }

      return { success: true, status: 'rejected', amountHeld: 0 };
    }

    // === ACCEPT: hold premium insurance points from both parties ===
    let totalHeld = 0;

    for (const userId of [initiatorId, partnerId]) {
      if (!userId) continue;

      const userPoints = await zite.userPoints.findOne({ filters: { user: userId } });
      const currentPoints = userPoints?.totalPoints ?? 0;

      if (currentPoints < amount) {
        // Not enough points — reject automatically
        await zite.barterHistory.update({
          id: input.barterId,
          record: { premiumInsuranceStatus: 'Ditolak' },
        });

        const shortUser = userId === context.user.id ? 'Anda' : 'pihak lain';
        await zite.barterMessages.create({
          record: {
            barter: input.barterId,
            sender: context.user.id,
            content: `⚠️ Asuransi premium gagal diaktifkan — ${shortUser} tidak memiliki cukup poin (butuh ${amount} MP).`,
            type: 'System',
          },
        });

        throw new ZiteError(`Poin ${shortUser} tidak cukup untuk asuransi premium (butuh ${amount} MP, tersedia ${currentPoints} MP)`);
      }
    }

    // Both have enough — deduct and create deposits
    for (const userId of [initiatorId, partnerId]) {
      if (!userId) continue;

      const userPoints = await zite.userPoints.findOne({ filters: { user: userId } });
      if (!userPoints) continue;

      // Deduct
      await zite.userPoints.update({
        id: userPoints.id,
        record: { totalPoints: (userPoints.totalPoints ?? 0) - amount },
      });

      // Create premium deposit record
      await zite.barterDeposits.create({
        record: {
          label: `Premium Insurance ${userId} → Barter`,
          barter: input.barterId,
          user: userId,
          amount,
          status: 'Held',
          resolutionNote: 'Asuransi Penjaminan Barang (Premium)',
        },
      });

      // Point history
      await zite.pointHistory.create({
        record: {
          activity: `Asuransi Penjaminan Barang (ditahan)`,
          user: userId,
          points: -amount,
          activityType: 'premium_insurance_hold',
        },
      });

      totalHeld += amount;
    }

    // Update barter status
    await zite.barterHistory.update({
      id: input.barterId,
      record: { premiumInsuranceStatus: 'Disetujui' },
    });

    // System message
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: `✅ Asuransi Penjaminan Barang AKTIF!\n\n🛡️ ${amount} MP ditahan dari kedua pihak sebagai jaminan tambahan.\n📋 Total penjaminan: ${totalHeld} MP\n💰 Biaya admin: 3% (${Math.ceil(amount * 3 / 100)} MP per orang) akan dipotong saat pengembalian.\n\n💡 Tujuan: Melindungi barter barang bernilai tinggi. Jika barter selesai dengan baik, poin dikembalikan (dikurangi biaya admin 3%). Jika ada pelanggaran, poin pihak yang melanggar hangus sebagai kompensasi.`,
        type: 'System',
      },
    });

    // Notify proposer
    if (proposerId) {
      await zite.notifications.create({
        record: {
          title: '✅ Asuransi Premium Disetujui!',
          body: `${userName} menyetujui asuransi premium ${amount} MP. Total ${totalHeld} MP ditahan sebagai jaminan.`,
          type: 'Barter',
          recipient: proposerId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { success: true, status: 'accepted', amountHeld: totalHeld };
  },
});

