import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Accept, reject, or upload proof for a service barter',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    action: z.enum(['accept', 'reject', 'upload_proof', 'confirm_complete']),
    proofUrls: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    status: z.string(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const b = await zite.serviceBarters.findOne({ id: input.barterId });
    if (!b) throw new ZiteError('Barter jasa tidak ditemukan');

    const itemOwnerId = Array.isArray(b.itemOwner) ? b.itemOwner[0] : b.itemOwner || '';
    const providerId = Array.isArray(b.serviceProvider) ? b.serviceProvider[0] : b.serviceProvider || '';
    const SERVICE_DEPOSIT = 40;

    if (input.action === 'accept') {
      if (providerId !== context.user.id) throw new ZiteError('Hanya penyedia jasa yang bisa menerima');
      if (b.status !== 'Menunggu') throw new ZiteError('Barter ini sudah direspon');

      const deadlineDays = b.deadlineDays ?? 7;
      const deadlineAt = new Date(Date.now() + deadlineDays * 24 * 60 * 60 * 1000).toISOString();

      await zite.serviceBarters.update({
        id: b.id,
        record: {
          status: 'Dalam Pengerjaan',
          startedAt: new Date().toISOString(),
          deadlineAt,
        },
      });

      await zite.notifications.create({
        record: {
          title: '✅ Penawaran Jasa Diterima!',
          body: `Jasa "${b.title}" telah diterima. Deadline: ${deadlineDays} hari.`,
          type: 'Barter',
          recipient: itemOwnerId,
          read: false,
          linkPath: `/service-barter/${b.id}`,
        },
      });

      return { success: true, status: 'Dalam Pengerjaan', message: `Diterima! Deadline ${deadlineDays} hari dari sekarang.` };
    }

    if (input.action === 'reject') {
      if (providerId !== context.user.id) throw new ZiteError('Hanya penyedia jasa yang bisa menolak');
      if (b.status !== 'Menunggu') throw new ZiteError('Barter ini sudah direspon');

      await zite.serviceBarters.update({ id: b.id, record: { status: 'Dibatalkan' } });

      // Refund deposit to item owner
      const { records: pts } = await zite.userPoints.findAll({ filters: { user: itemOwnerId }, limit: 1 });
      if (pts[0]) {
        await zite.userPoints.update({ id: pts[0].id, record: { totalPoints: (pts[0].totalPoints ?? 0) + SERVICE_DEPOSIT } });
        await zite.pointHistory.create({
          record: { activity: `Refund deposit barter jasa (ditolak)`, user: itemOwnerId, points: SERVICE_DEPOSIT, activityType: 'service_refund' },
        });
      }

      // Restore item & service status
      const itemId = Array.isArray(b.offeredItem) ? b.offeredItem[0] : b.offeredItem;
      const svcId = Array.isArray(b.requestedService) ? b.requestedService[0] : b.requestedService;
      if (itemId) await zite.items.update({ id: itemId, record: { status: 'Tersedia' } });
      if (svcId) await zite.services.update({ id: svcId, record: { status: 'Tersedia' } });

      await zite.notifications.create({
        record: {
          title: '❌ Penawaran Jasa Ditolak',
          body: `Penawaran "${b.title}" ditolak. Deposit 40 MP dikembalikan.`,
          type: 'Barter',
          recipient: itemOwnerId,
          read: false,
          linkPath: `/service-barter/${b.id}`,
        },
      });

      return { success: true, status: 'Dibatalkan', message: 'Ditolak. Deposit dikembalikan ke penawar.' };
    }

    if (input.action === 'upload_proof') {
      if (providerId !== context.user.id) throw new ZiteError('Hanya penyedia jasa yang bisa upload bukti');
      if (b.status !== 'Dalam Pengerjaan') throw new ZiteError('Jasa belum dalam pengerjaan');
      if (!input.proofUrls || input.proofUrls.length === 0) throw new ZiteError('Harus upload minimal 1 bukti foto/video');

      const proofAttachments = input.proofUrls.map(url => ({ url }));
      await zite.serviceBarters.update({
        id: b.id,
        record: {
          completionProof: proofAttachments,
          proofUploaded: true,
          status: 'Menunggu Bukti',
        },
      });

      await zite.notifications.create({
        record: {
          title: '📸 Bukti Jasa Diupload!',
          body: `Penyedia jasa telah mengupload bukti penyelesaian "${b.title}". Silakan cek dan konfirmasi.`,
          type: 'Barter',
          recipient: itemOwnerId,
          read: false,
          linkPath: `/service-barter/${b.id}`,
        },
      });

      return { success: true, status: 'Menunggu Bukti', message: 'Bukti berhasil diupload. Menunggu konfirmasi pemilik barang.' };
    }

    if (input.action === 'confirm_complete') {
      // Only item owner can confirm (after proof uploaded)
      if (itemOwnerId !== context.user.id) throw new ZiteError('Hanya pemilik barang yang bisa konfirmasi selesai');
      if (!b.proofUploaded) throw new ZiteError('Penyedia jasa belum upload bukti penyelesaian');
      if (b.status !== 'Menunggu Bukti') throw new ZiteError('Status barter tidak valid untuk konfirmasi');

      await zite.serviceBarters.update({
        id: b.id,
        record: {
          status: 'Selesai',
          itemOwnerConfirmed: true,
          providerConfirmed: true,
          completedAt: new Date().toISOString(),
        },
      });

      // Award points — +50 MP to both parties
      const BARTER_REWARD = 50;
      for (const uid of [itemOwnerId, providerId]) {
        if (!uid) continue;
        const { records: pts } = await zite.userPoints.findAll({ filters: { user: uid }, limit: 1 });
        if (pts[0]) {
          await zite.userPoints.update({
            id: pts[0].id,
            record: {
              totalPoints: (pts[0].totalPoints ?? 0) + BARTER_REWARD,
              bartersCompleted: (pts[0].bartersCompleted ?? 0) + 1,
            },
          });
          await zite.pointHistory.create({
            record: { activity: `Barter jasa selesai: ${b.title}`, user: uid, points: BARTER_REWARD, activityType: 'service_barter' },
          });
        }
      }

      // Refund deposit
      const { records: ownerPts } = await zite.userPoints.findAll({ filters: { user: itemOwnerId }, limit: 1 });
      if (ownerPts[0]) {
        await zite.userPoints.update({
          id: ownerPts[0].id,
          record: { totalPoints: (ownerPts[0].totalPoints ?? 0) + SERVICE_DEPOSIT },
        });
        await zite.pointHistory.create({
          record: { activity: `Refund deposit barter jasa (selesai)`, user: itemOwnerId, points: SERVICE_DEPOSIT, activityType: 'service_refund' },
        });
      }

      // Restore item & service status
      const itemId = Array.isArray(b.offeredItem) ? b.offeredItem[0] : b.offeredItem;
      const svcId = Array.isArray(b.requestedService) ? b.requestedService[0] : b.requestedService;
      if (itemId) await zite.items.update({ id: itemId, record: { status: 'Sudah Ditukar' } });
      if (svcId) await zite.services.update({ id: svcId, record: { status: 'Tersedia' } });

      await zite.notifications.create({
        record: {
          title: '🎉 Barter Jasa Selesai!',
          body: `"${b.title}" telah selesai! +${BARTER_REWARD} MP & deposit dikembalikan.`,
          type: 'Barter',
          recipient: providerId,
          read: false,
          linkPath: `/service-barter/${b.id}`,
        },
      });

      return { success: true, status: 'Selesai', message: `Selesai! +${BARTER_REWARD} MP & deposit ${SERVICE_DEPOSIT} MP dikembalikan.` };
    }

    throw new ZiteError('Aksi tidak valid');
  },
});

