import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const SHIPPING_SERVICES = ['JNE', 'J&T Express', 'SiCepat', 'AnterAja', 'Ninja Xpress', 'Pos Indonesia', 'Grab Express', 'GoSend', 'Lainnya'];

export default createEndpoint({
  description: 'Propose a delivery method (COD or shipping service) for a barter — requires other party approval',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    method: z.enum(['cod', 'shipping']),
    // COD fields
    address: z.string().optional(),
    detail: z.string().optional(),
    // Shipping fields
    shippingService: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    if (barter.status !== 'Diterima') {
      throw new ZiteError('Barter harus dalam status Diterima');
    }

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;
    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    const userName = context.user.firstName || context.user.email.split('@')[0];
    const recipientId = context.user.id === initiatorId ? partnerId : initiatorId;

    if (input.method === 'cod') {
      if (!input.address || input.address.trim().length === 0) {
        throw new ZiteError('Alamat COD harus diisi');
      }

      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          deliveryMethod: 'cod',
          deliveryMethodProposedBy: context.user.id,
          deliveryMethodApproved: false,
          codAddress: input.address,
          codDetail: input.detail || null,
          codProposedBy: context.user.id,
          codApproved: false,
          shippingService: null,
        },
      });

      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `📍 ${userName} mengusulkan tukar barang via COD (Ketemu Langsung)\n📌 Lokasi: ${input.address}${input.detail ? `\n📝 Detail: ${input.detail}` : ''}\n\n⏳ Menunggu persetujuan pihak lain...`,
          type: 'COD Proposal',
        },
      });

      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: '📍 Usulan COD (Ketemu Langsung)',
            body: `${userName} mengusulkan lokasi COD: ${input.address.slice(0, 60)}`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    } else {
      // Shipping
      if (!input.shippingService || input.shippingService.trim().length === 0) {
        throw new ZiteError('Pilih jasa kirim');
      }

      await zite.barterHistory.update({
        id: input.barterId,
        record: {
          deliveryMethod: 'Jasa Kirim',
          deliveryMethodProposedBy: context.user.id,
          deliveryMethodApproved: false,
          shippingService: input.shippingService,
          // Clear COD fields
          codAddress: null,
          codDetail: null,
          codProposedBy: null,
          codApproved: false,
        },
      });

      await zite.barterMessages.create({
        record: {
          barter: input.barterId,
          sender: context.user.id,
          content: `🚚 ${userName} mengusulkan tukar barang via Jasa Kirim\n📦 Kurir: ${input.shippingService}\n\n⏳ Menunggu persetujuan pihak lain...`,
          type: 'System',
        },
      });

      if (recipientId) {
        await zite.notifications.create({
          record: {
            title: '🚚 Usulan Jasa Kirim',
            body: `${userName} mengusulkan pengiriman via ${input.shippingService}`,
            type: 'Barter',
            recipient: recipientId,
            read: false,
            linkPath: `/barter/${input.barterId}`,
          },
        });
      }
    }

    return { success: true };
  },
});

