import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const REVIEW_BONUS = 10; // Bonus menulis review
const HELD_POINTS = 20; // Poin yang ditahan, dicairkan saat review
const REVIEW_DEADLINE_DAYS = 7;

function badgeId(points: number): string {
  if (points >= 10000) return 'elite';
  if (points >= 5000) return 'mentor';
  if (points >= 2500) return 'legenda';
  if (points >= 1000) return 'profesional';
  if (points >= 500) return 'terpercaya';
  if (points >= 200) return 'aktif';
  return 'pemula';
}

export default createEndpoint({
  description: 'Submit a review and rating for the other party after barter is completed. Releases held 20 MP + gives 10 MP bonus.',
  authenticated: true,
  inputSchema: z.object({
    barterId: z.string(),
    rating: z.number().min(1).max(5),
    comment: z.string().min(1).max(500),
    aspect: z.enum([
      'barang_sesuai', 'komunikasi_baik', 'tepat_waktu', 'ramah',
      'tidak_sesuai', 'tidak_responsif',
    ]),
  }),
  outputSchema: z.object({ reviewId: z.string(), bonusPoints: z.number(), heldPointsReleased: z.number() }),
  execute: async ({ input, context }) => {
    const barter = await zite.barterHistory.findOne({ id: input.barterId });
    if (!barter) throw new ZiteError('Barter tidak ditemukan');

    if (barter.status !== 'Selesai') {
      throw new ZiteError('Hanya bisa review setelah barter selesai');
    }

    const initiatorId = Array.isArray(barter.initiator) ? barter.initiator[0] : barter.initiator;
    const partnerId = Array.isArray(barter.partner) ? barter.partner[0] : barter.partner;

    if (context.user.id !== initiatorId && context.user.id !== partnerId) {
      throw new ZiteError('Anda tidak punya akses');
    }

    // Check deadline — 7 days from completedAt
    const completedAt = barter.completedAt ? new Date(barter.completedAt) : null;
    const reviewDeadline = completedAt
      ? new Date(completedAt.getTime() + REVIEW_DEADLINE_DAYS * 24 * 60 * 60 * 1000)
      : null;
    const isExpired = reviewDeadline ? new Date() > reviewDeadline : false;

    if (isExpired) {
      throw new ZiteError(`Batas waktu review sudah lewat. ${HELD_POINTS} MP hangus dan tidak bisa diklaim lagi.`);
    }

    // Determine reviewee
    const revieweeId = context.user.id === initiatorId ? partnerId : initiatorId;
    if (!revieweeId) throw new ZiteError('Partner tidak ditemukan');

    // Check if already reviewed
    const { records: existing } = await zite.barterReviews.findAll({
      filters: { reviewer: context.user.id },
      limit: 100,
    });
    const alreadyReviewed = existing.some(r => {
      const barterIds = Array.isArray(r.barter) ? r.barter : r.barter ? [r.barter] : [];
      return barterIds.includes(input.barterId);
    });
    if (alreadyReviewed) {
      throw new ZiteError('Anda sudah memberikan review untuk barter ini');
    }

    // Map aspect value to label
    const aspectMap: Record<string, string> = {
      barang_sesuai: 'Barang Sesuai Deskripsi',
      komunikasi_baik: 'Komunikasi Baik',
      tepat_waktu: 'Tepat Waktu COD',
      ramah: 'Ramah & Sopan',
      tidak_sesuai: 'Barang Tidak Sesuai',
      tidak_responsif: 'Tidak Responsif',
    };

    const review = await zite.barterReviews.create({
      record: {
        barter: input.barterId,
        reviewer: context.user.id,
        reviewee: revieweeId,
        rating: input.rating,
        comment: input.comment,
        aspect: aspectMap[input.aspect] || input.aspect,
      },
    });

    // Release held points (20 MP) + review bonus (10 MP)
    const totalBonus = REVIEW_BONUS + HELD_POINTS;
    const existingPoints = await zite.userPoints.findOne({ filters: { user: context.user.id } });
    if (existingPoints) {
      const newTotal = (existingPoints.totalPoints ?? 0) + totalBonus;
      await zite.userPoints.update({
        id: existingPoints.id,
        record: { totalPoints: newTotal, currentBadge: badgeId(newTotal) },
      });
    }

    // Point history: review bonus
    await zite.pointHistory.create({
      record: {
        activity: 'Menulis Review Barter',
        user: context.user.id,
        points: REVIEW_BONUS,
        activityType: 'review_submitted',
      },
    });

    // Point history: held points released
    await zite.pointHistory.create({
      record: {
        activity: 'Bonus Barter Dicairkan (review diberikan)',
        user: context.user.id,
        points: HELD_POINTS,
        activityType: 'review_held_released',
      },
    });

    // System message in barter chat
    const stars = '⭐'.repeat(input.rating);
    await zite.barterMessages.create({
      record: {
        barter: input.barterId,
        sender: context.user.id,
        content: `${stars} Review diberikan: "${input.comment}"\n\n✅ +${HELD_POINTS} MP bonus dicairkan + ${REVIEW_BONUS} MP menulis review = +${totalBonus} MP total`,
        type: 'System',
      },
    });

    // Notify reviewee
    await zite.notifications.create({
      record: {
        title: `Anda mendapat rating ${input.rating}⭐`,
        body: `"${input.comment.slice(0, 80)}"`,
        type: 'Barter',
        recipient: revieweeId,
        read: false,
        linkPath: `/barter/${input.barterId}`,
      },
    });

    // Check if the reviewee hasn't reviewed yet — send them a reminder
    const otherReviewed = existing.some(r => {
      const rIds = Array.isArray(r.reviewer) ? r.reviewer : r.reviewer ? [r.reviewer] : [];
      const bIds = Array.isArray(r.barter) ? r.barter : r.barter ? [r.barter] : [];
      return rIds.includes(revieweeId) && bIds.includes(input.barterId);
    });

    if (!otherReviewed) {
      const deadlineStr = reviewDeadline
        ? reviewDeadline.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })
        : '';
      await zite.notifications.create({
        record: {
          title: '💡 Partner sudah review, giliranmu!',
          body: `Partner barter kamu sudah memberikan review. Berikan review juga sebelum ${deadlineStr} untuk klaim +${HELD_POINTS} MP bonus + ${REVIEW_BONUS} MP!`,
          type: 'Barter',
          recipient: revieweeId,
          read: false,
          linkPath: `/barter/${input.barterId}`,
        },
      });
    }

    return { reviewId: review.id, bonusPoints: REVIEW_BONUS, heldPointsReleased: HELD_POINTS };
  },
});

