import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const SUPER_LIKE_COST = 50;

export default createEndpoint({
  description: 'Spend 50 MP to send a super interest notification to an item owner',
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    remainingPoints: z.number(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    const item = await zite.items.findOne({ id: input.itemId });
    if (!item) throw new Error('Item tidak ditemukan');
    const ownerIds = Array.isArray(item.owner) ? item.owner : item.owner ? [item.owner] : [];
    if (ownerIds.includes(userId)) throw new Error('Kamu tidak bisa Super Like barang sendiri');

    const up = await zite.userPoints.findOne({ filters: { user: userId } });
    if (!up || (up.totalPoints ?? 0) < SUPER_LIKE_COST) throw new Error(`Poin tidak cukup. Kamu butuh ${SUPER_LIKE_COST} MP.`);

    // Deduct points
    const newPoints = (up.totalPoints ?? 0) - SUPER_LIKE_COST;
    await zite.userPoints.update({ id: up.id, record: { totalPoints: newPoints } });

    await zite.pointHistory.create({
      record: {
        activity: `Super Like: ${item.title || 'Item'}`,
        user: userId,
        points: -SUPER_LIKE_COST,
        activityType: 'super_like',
      },
    });

    await zite.pointRedemptions.create({
      record: {
        label: `Super Like: ${item.title || 'Item'}`,
        user: userId,
        type: 'super_like',
        pointsSpent: SUPER_LIKE_COST,
        item: input.itemId,
        status: 'used',
        recipientUserId: null,
        raffleTickets: null,
        expiresAt: null,
      },
    });

    // Send priority notification to owner
    if (ownerIds[0]) {
      await zite.notifications.create({
        record: {
          title: '⚡ Super Like!',
          body: `${context.user.firstName || context.user.email} sangat tertarik dengan "${item.title}"!`,
          type: 'Like',
          recipient: ownerIds[0],
          read: false,
          linkPath: `/item/${input.itemId}`,
        },
      });
    }

    return { success: true, remainingPoints: newPoints };
  },
});

