import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { enforceBan } from '../lib/banCheck';

export default createEndpoint({
  description: 'Follow or unfollow another user',
  authenticated: true,
  inputSchema: z.object({
    targetUserId: z.string(),
  }),
  outputSchema: z.object({
    following: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);
    const userId = context.user.id;
    if (input.targetUserId === userId) {
      throw new Error('Tidak bisa follow diri sendiri');
    }

    // Check if already following
    const { records } = await zite.follows.findAll({
      filters: { follower: userId, followingUserId: input.targetUserId },
      limit: 1,
    });

    if (records.length > 0) {
      // Unfollow
      await zite.follows.delete({ id: records[0].id });
      return { following: false, message: 'Berhenti mengikuti' };
    }

    // Follow
    await zite.follows.create({
      record: {
        label: `${userId} → ${input.targetUserId}`,
        follower: userId,
        followingUserId: input.targetUserId,
      },
    });

    // Notify the target user
    const followerUsers = await zite.auth.findAllUsers({ filters: { id: userId }, limit: 1 });
    const followerName = followerUsers.records[0]?.name || 'Seseorang';

    await zite.notifications.create({
      record: {
        title: '👤 Pengikut Baru!',
        body: `${followerName} mulai mengikuti kamu`,
        type: 'System',
        recipient: input.targetUserId,
        read: false,
        linkPath: `/user/${userId}`,
      },
    });

    return { following: true, message: 'Mulai mengikuti' };
  },
});

