import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Updates progress for all participants of active challenges based on challenge type',
  authenticated: true,
  inputSchema: z.object({ challengeId: z.string().optional() }),
  outputSchema: z.object({ updated: z.number() }),
  execute: async ({ input }) => {
    // Get active challenges (or a specific one)
    const filters: any = { status: 'Aktif' };
    if (input.challengeId) filters.id = input.challengeId;

    const { records: challenges } = await zite.challenges.findAll({ filters, limit: 50 });
    if (challenges.length === 0) return { updated: 0 };

    let totalUpdated = 0;

    for (const challenge of challenges) {
      const startDate = challenge.startDate ?? challenge.createdAt ?? '2020-01-01';
      const endDate = challenge.endDate ?? new Date().toISOString();

      // Get all participants with their user IDs
      const { rows: participants } = await zite.sql({
        query: `
          SELECT cp.id, cp."user"->>0 AS "userId", cp."progress"
          FROM "ChallengeParticipants" cp
          JOIN "ChallengeParticipantsChallenges" cp2c ON cp2c."challengeParticipantsId" = cp.id
          WHERE cp2c."challengesId"::text = $1
        `,
        params: [challenge.id],
      });

      if (participants.length === 0) continue;
      const userIds = participants.map((p: any) => p.userId).filter(Boolean);
      if (userIds.length === 0) continue;

      let progressMap: Map<string, number> = new Map();

      switch (challenge.type) {
        case 'Barter Terbanyak': {
          // Count completed barters (as initiator or partner) within challenge period
          const { rows } = await zite.sql({
            query: `
              SELECT uid, COUNT(*) AS cnt
              FROM (
                SELECT bh."initiator"->>0 AS uid
                FROM "BarterHistory" bh
                WHERE bh."status" = 'Selesai'
                  AND bh."completedAt" >= $1 AND bh."completedAt" <= $2
                  AND bh."initiator"->>0 = ANY($3::text[])
                UNION ALL
                SELECT bh."partner"->>0 AS uid
                FROM "BarterHistory" bh
                WHERE bh."status" = 'Selesai'
                  AND bh."completedAt" >= $1 AND bh."completedAt" <= $2
                  AND bh."partner"->>0 = ANY($3::text[])
              ) sub
              GROUP BY uid
            `,
            params: [startDate, endDate, userIds],
          });
          for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          break;
        }

        case 'Upload Terbanyak': {
          // Count items uploaded during challenge period
          const { rows } = await zite.sql({
            query: `
              SELECT i."owner"->>0 AS uid, COUNT(*) AS cnt
              FROM "Items" i
              WHERE i.created_at >= $1::timestamptz AND i.created_at <= $2::timestamptz
                AND i."owner"->>0 = ANY($3::text[])
              GROUP BY i."owner"->>0
            `,
            params: [startDate, endDate, userIds],
          });
          for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          break;
        }

        case 'Rating Tertinggi': {
          // Average rating received during challenge period
          const { rows } = await zite.sql({
            query: `
              SELECT br."reviewee"->>0 AS uid, ROUND(AVG(br."rating")::numeric, 2) AS avg_rating
              FROM "BarterReviews" br
              WHERE br.created_at >= $1::timestamptz AND br.created_at <= $2::timestamptz
                AND br."reviewee"->>0 = ANY($3::text[])
              GROUP BY br."reviewee"->>0
            `,
            params: [startDate, endDate, userIds],
          });
          for (const r of rows) progressMap.set(String(r.uid), Number(r.avg_rating));
          break;
        }

        case 'Kategori Spesifik': {
          // Count barters completed in a specific category
          const catFilter = challenge.categoryFilter ?? '';
          const { rows } = await zite.sql({
            query: `
              SELECT uid, COUNT(*) AS cnt
              FROM (
                SELECT bh."initiator"->>0 AS uid
                FROM "BarterHistory" bh
                JOIN "BarterHistoryItems" bhi ON bhi."barterHistoryId" = bh.id
                JOIN "Items" i ON i.id = bhi."itemsId"
                JOIN "CategoriesItems" ci ON ci."itemsId" = i.id
                JOIN "Categories" c ON c.id = ci."categoriesId"
                WHERE bh."status" = 'Selesai'
                  AND bh."completedAt" >= $1 AND bh."completedAt" <= $2
                  AND bh."initiator"->>0 = ANY($3::text[])
                  AND c."name" = $4
                UNION ALL
                SELECT bh."partner"->>0 AS uid
                FROM "BarterHistory" bh
                JOIN "BarterHistoryItems" bhi ON bhi."barterHistoryId" = bh.id
                JOIN "Items" i ON i.id = bhi."itemsId"
                JOIN "CategoriesItems" ci ON ci."itemsId" = i.id
                JOIN "Categories" c ON c.id = ci."categoriesId"
                WHERE bh."status" = 'Selesai'
                  AND bh."completedAt" >= $1 AND bh."completedAt" <= $2
                  AND bh."partner"->>0 = ANY($3::text[])
                  AND c."name" = $4
              ) sub
              GROUP BY uid
            `,
            params: [startDate, endDate, userIds, catFilter],
          });
          for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          break;
        }

        case 'Referral Race': {
          // Count completed referrals during challenge period
          const { rows } = await zite.sql({
            query: `
              SELECT r."referrer"->>0 AS uid, COUNT(*) AS cnt
              FROM "Referrals" r
              WHERE r."status" = 'Completed'
                AND r.created_at >= $1::timestamptz AND r.created_at <= $2::timestamptz
                AND r."referrer"->>0 = ANY($3::text[])
              GROUP BY r."referrer"->>0
            `,
            params: [startDate, endDate, userIds],
          });
          for (const r of rows) progressMap.set(String(r.uid), Number(r.cnt));
          break;
        }

        default:
          // Custom Target — skip auto-tracking, keep manual progress
          continue;
      }

      // Update participant records with new progress
      for (const p of participants) {
        const userId = String((p as any).userId);
        const newProgress = progressMap.get(userId) ?? 0;
        const oldProgress = Number((p as any).progress ?? 0);

        if (newProgress !== oldProgress) {
          await zite.challengeParticipants.update({
            id: (p as any).id,
            record: { progress: newProgress },
          });
          totalUpdated++;
        }
      }
    }

    return { updated: totalUpdated };
  },
});

