import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Update community settings (rules, description, joinMode, icon) — only Ketua can update',
  authenticated: true,
  inputSchema: z.object({
    communityId: z.string(),
    name: z.string().min(2).optional(),
    description: z.string().optional(),
    rules: z.string().optional(),
    joinMode: z.enum(['Terbuka', 'Perlu Persetujuan']).optional(),
    icon: z.string().optional(),
  }),
  outputSchema: z.object({
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;

    // Verify user is Ketua
    const { records: membership } = await zite.communityMembers.findAll({
      filters: { community: input.communityId, user: userId, status: 'active' },
      limit: 1,
    });
    if (membership.length === 0 || membership[0].role !== 'Ketua') {
      throw new Error('Hanya Ketua komunitas yang bisa mengubah pengaturan');
    }

    const update: Record<string, unknown> = {};
    if (input.name !== undefined) update.name = input.name;
    if (input.description !== undefined) update.description = input.description;
    if (input.rules !== undefined) update.rules = input.rules;
    if (input.joinMode !== undefined) update.joinMode = input.joinMode;
    if (input.icon !== undefined) update.icon = input.icon;

    if (Object.keys(update).length === 0) {
      return { success: true, message: 'Tidak ada perubahan' };
    }

    await zite.communities.update({
      id: input.communityId,
      record: update as any,
    });

    return { success: true, message: 'Pengaturan komunitas berhasil diperbarui' };
  },
});

