import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Updates privacy settings for the signed-in user',
  authenticated: true,
  inputSchema: z.object({
    profileVisibility: z.enum(['public', 'followers', 'private']).optional(),
    itemsVisibility: z.enum(['public', 'followers', 'private']).optional(),
    messagingPrivacy: z.enum(['everyone', 'followers', 'nobody']).optional(),
    showOnlineStatus: z.boolean().optional(),
    showLocation: z.boolean().optional(),
    showBarterHistory: z.boolean().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const profile = await zite.userProfiles.findOne({
      filters: { user: context.user.id },
    });

    if (!profile) {
      throw new Error('Profile not found');
    }

    const updates: Record<string, any> = {};
    if (input.profileVisibility !== undefined) updates.profileVisibility = input.profileVisibility;
    if (input.itemsVisibility !== undefined) updates.itemsVisibility = input.itemsVisibility;
    if (input.messagingPrivacy !== undefined) updates.messagingPrivacy = input.messagingPrivacy;
    if (input.showOnlineStatus !== undefined) updates.showOnlineStatus = input.showOnlineStatus;
    if (input.showLocation !== undefined) updates.showLocation = input.showLocation;
    if (input.showBarterHistory !== undefined) updates.showBarterHistory = input.showBarterHistory;

    if (Object.keys(updates).length > 0) {
      await zite.userProfiles.update({ id: profile.id, record: updates as any });
    }

    return { success: true };
  },
});

