import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { enforceBan } from '../lib/banCheck';

async function estimateWithGemini(photoUrl: string, title: string, kondisi: string, kategori: string): Promise<{ min: number; max: number }> {
  const apiKey = process.env.ZITE_GEMINI_API_KEY;
  if (!apiKey) return { min: 0, max: 0 };

  try {
    const imgRes = await fetch(photoUrl);
    const imgBuf = await imgRes.arrayBuffer();
    const base64 = Buffer.from(imgBuf).toString('base64');
    const mimeType = imgRes.headers.get('content-type') || 'image/jpeg';

    const prompt = `Kamu adalah penilai harga barang bekas Indonesia. Analisis foto ini.
Nama barang: ${title}
Kategori: ${kategori}
Kondisi: ${kondisi}

Jawab HANYA dalam format ini (angka saja tanpa teks lain):
MIN: [angka rupiah tanpa titik]
MAX: [angka rupiah tanpa titik]

Contoh:
MIN: 500000
MAX: 800000`;

    const body = {
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: mimeType, data: base64 } },
        ],
      }],
    };

    // Try multiple models in case one is rate-limited or deprecated
    const models = ['gemini-3.6-flash'];
    let res: Response | null = null;
    for (const model of models) {
      res = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
        { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }
      );
      if (res.ok) break;
      // If 429 (quota), try next model
      if (res.status === 429 || res.status === 503) continue;
      return { min: 0, max: 0 };
    }

    if (!res || !res.ok) return { min: 0, max: 0 };

    const data = await res.json();
    const text: string = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';

    const minMatch = text.match(/MIN:\s*(\d+)/i);
    const maxMatch = text.match(/MAX:\s*(\d+)/i);
    const min = minMatch ? parseInt(minMatch[1], 10) : 0;
    const max = maxMatch ? parseInt(maxMatch[1], 10) : 0;

    return { min: min || 0, max: max || 0 };
  } catch {
    return { min: 0, max: 0 };
  }
}

// Badge thresholds
function badgeId(points: number): string {
  if (points >= 10000) return 'elite';
  if (points >= 5000) return 'mentor';
  if (points >= 2500) return 'legenda';
  if (points >= 1000) return 'profesional';
  if (points >= 500) return 'terpercaya';
  if (points >= 200) return 'aktif';
  return 'pemula';
}

const BADGE_NAMES: Record<string, { name: string; emoji: string }> = {
  pemula: { name: 'MUTARI Pemula', emoji: '🌱' },
  aktif: { name: 'Barter Aktif', emoji: '🤝' },
  terpercaya: { name: 'Mitra Terpercaya', emoji: '⭐' },
  profesional: { name: 'Barter Profesional', emoji: '🛡️' },
  legenda: { name: 'Legenda MUTARI', emoji: '👑' },
  mentor: { name: 'Mentor MUTARI', emoji: '🎓' },
  elite: { name: 'Elite MUTARI', emoji: '💎' },
};

async function notifyBadgeUpgrade(userId: string, oldBadge: string, newTotal: number) {
  const newBadge = badgeId(newTotal);
  if (newBadge === oldBadge) return;
  const info = BADGE_NAMES[newBadge];
  if (!info) return;
  await zite.notifications.create({
    record: {
      title: `${info.emoji} Badge Baru: ${info.name}!`,
      body: `Selamat! Kamu telah mencapai level ${info.name} dengan ${newTotal} MP. Terus tingkatkan reputasimu!`,
      type: 'badge',
      recipient: userId,
      read: false,
      linkPath: '/wallet',
    },
  });
  await zite.pointHistory.create({
    record: { activity: `Naik level: ${info.emoji} ${info.name}`, user: userId, points: 0, activityType: 'badge' },
  });
}

export default createEndpoint({
  description: 'Upload a new barter item listing and award points',
  authenticated: true,
  inputSchema: z.object({
    title: z.string().min(1),
    kategori: z.string().min(1),
    kondisi: z.string().min(1),
    kelengkapan: z.string().optional(),
    spesifikasi: z.string().optional(),
    kekurangan: z.string().optional(),
    inginDitukar: z.string().optional(),
    tambahan: z.string().optional(),
    deskripsi: z.string().min(10),
    lokasi: z.string().optional(),
    photos: z.array(z.string()).min(1),
    status: z.enum(['draft', 'publish']),
  }),
  outputSchema: z.object({
    id: z.string(),
    success: z.boolean(),
    pointsAwarded: z.number(),
  }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);
    const userId = context.user.id;

    // AI: estimate value from photo when publishing
    let estimatedMin = 0;
    let estimatedMax = 0;
    if (input.status === 'publish' && input.photos.length > 0) {
      const est = await estimateWithGemini(input.photos[0], input.title, input.kondisi, input.kategori);
      estimatedMin = est.min;
      estimatedMax = est.max;
    }

    // Create the item
    const record = await zite.items.create({
      record: {
        title: input.title,
        description: input.deskripsi,
        photos: input.photos.map(url => ({ url })),
        condition: input.kondisi,
        completeness: input.kelengkapan || null,
        defects: input.kekurangan || null,
        desiredItems: input.inginDitukar || null,
        location: input.lokasi || null,
        status: input.status === 'publish' ? 'Tersedia' : 'Negosiasi',
        owner: userId,
        specifications: input.spesifikasi || null,
        additionalWants: input.tambahan || null,
        barterReason: null,
        barterMethod: null,
        estimatedValueMin: estimatedMin || null,
        estimatedValueMax: estimatedMax || null,
      },
    });

    // Award points for upload
    const pointsForUpload = 20;

    // Upsert user points
    let userPoints = await zite.userPoints.findOne({ filters: { user: userId } });

    if (!userPoints) {
      // First time — create with join bonus + upload bonus
      const total = 10 + pointsForUpload;
      userPoints = await zite.userPoints.create({
        record: {
          label: context.user.email || 'User',
          user: userId,
          totalPoints: total,
          itemsUploaded: 1,
          bartersCompleted: 0,
          likesReceived: 0,
          currentBadge: badgeId(total),
        },
      });
      await zite.pointHistory.create({
        record: { activity: 'Bergabung di MUTARI', user: userId, points: 10, activityType: 'join' },
      });
    } else {
      const oldBadge = userPoints.currentBadge || 'pemula';
      const newTotal = (userPoints.totalPoints ?? 0) + pointsForUpload;
      const newUploads = (userPoints.itemsUploaded ?? 0) + 1;
      await zite.userPoints.update({
        id: userPoints.id,
        record: {
          totalPoints: newTotal,
          itemsUploaded: newUploads,
          currentBadge: badgeId(newTotal),
        },
      });
      await notifyBadgeUpgrade(userId, oldBadge, newTotal);
    }

    // Log history
    await zite.pointHistory.create({
      record: {
        activity: `Upload barang: ${input.title}`,
        user: userId,
        points: pointsForUpload,
        activityType: 'upload',
      },
    });

    // Bonus for milestones
    const totalUploads = (userPoints?.itemsUploaded ?? 0) + 1;
    let bonusPoints = 0;
    let bonusLabel = '';
    if (totalUploads === 5) { bonusPoints = 30; bonusLabel = 'Milestone: Upload 5 barang'; }
    if (totalUploads === 10) { bonusPoints = 50; bonusLabel = 'Milestone: Upload 10 barang'; }
    if (totalUploads === 25) { bonusPoints = 100; bonusLabel = 'Milestone: Upload 25 barang'; }

    if (bonusPoints > 0) {
      const latest = await zite.userPoints.findOne({ filters: { user: userId } });
      if (latest) {
        const oldBadge = latest.currentBadge || 'pemula';
        const newTotal = (latest.totalPoints ?? 0) + bonusPoints;
        await zite.userPoints.update({
          id: latest.id,
          record: { totalPoints: newTotal, currentBadge: badgeId(newTotal) },
        });
        await notifyBadgeUpgrade(userId, oldBadge, newTotal);
      }
      await zite.pointHistory.create({
        record: { activity: bonusLabel, user: userId, points: bonusPoints, activityType: 'milestone' },
      });
    }

    // Notify followers about new item upload
    try {
      const { records: followerRecords } = await zite.follows.findAll({
        filters: { followingUserId: userId },
        limit: 500,
      });
      if (followerRecords.length > 0) {
        const uploaderName = context.user.firstName || context.user.email || 'Pengguna';
        const notifs = followerRecords.map(f => {
          const followerIds = Array.isArray(f.follower) ? f.follower : [f.follower];
          return {
            title: '📦 Barang Baru!',
            body: `${uploaderName} baru upload "${input.title}"`,
            type: 'System' as const,
            recipient: followerIds[0] || '',
            read: false as const,
            linkPath: `/item/${record.id}`,
          };
        }).filter(n => n.recipient);
        for (let i = 0; i < notifs.length; i += 100) {
          await zite.notifications.bulkCreate({ records: notifs.slice(i, i + 100) });
        }
      }
    } catch {
      // Don't fail the upload if notification fails
    }

    // Smart Match Alert — find mutual matches for the newly uploaded item
    try {
      const { records: allOtherItems } = await zite.items.findAll({
        filters: { status: 'Tersedia' },
        limit: 300,
      });
      const othersItems = allOtherItems.filter(i => {
        const ownerIds = Array.isArray(i.owner) ? i.owner : [i.owner];
        return !ownerIds.includes(userId);
      });

      const myWants = (input.inginDitukar || '').toLowerCase() + ' ' + (input.tambahan || '').toLowerCase();
      const myTitle = input.title.toLowerCase();
      const myCategory = input.kategori.toLowerCase();

      for (const theirItem of othersItems) {
        const theirTitle = (theirItem.title || '').toLowerCase();
        const theirDesc = (theirItem.description || '').toLowerCase();
        const theirWants = (theirItem.desiredItems || '').toLowerCase() + ' ' + (theirItem.additionalWants || '').toLowerCase();

        // I want theirs?
        const iWant = myWants.split(/\s+/).filter(w => w.length > 2).some(w => (theirTitle + ' ' + theirDesc).includes(w));
        // They want mine?
        const theyWant = theirWants.split(/\s+/).filter(w => w.length > 2).some(w => (myTitle + ' ' + myCategory).includes(w));

        if (iWant && theyWant) {
          const theirOwnerIds = Array.isArray(theirItem.owner) ? theirItem.owner : [theirItem.owner];
          const theirOwnerId = theirOwnerIds[0] || '';
          const uploaderName = context.user.firstName || context.user.email || 'Pengguna';

          // Notify the other user
          if (theirOwnerId) {
            await zite.notifications.create({
              record: {
                title: '🎯 Match Alert!',
                body: `${uploaderName} punya "${input.title}" yang mungkin kamu cari & butuh barang yang kamu punya!`,
                type: 'System',
                recipient: theirOwnerId,
                read: false,
                linkPath: `/item/${record.id}`,
              },
            });
          }
          // Notify me too
          await zite.notifications.create({
            record: {
              title: '🎯 Match Alert!',
              body: `"${theirItem.title}" cocok dengan yang kamu cari & pemiliknya butuh barang yang kamu punya!`,
              type: 'System',
              recipient: userId,
              read: false,
              linkPath: `/item/${theirItem.id}`,
            },
          });
          break; // Only notify for the best match to avoid spam
        }
      }
    } catch {
      // Don't fail the upload if match alert fails
    }

    return { id: record.id, success: true, pointsAwarded: pointsForUpload + bonusPoints };
  },
});

