import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { enforceBan } from '../lib/banCheck';

export default createEndpoint({
  description: 'Upload a new service listing',
  authenticated: true,
  inputSchema: z.object({
    title: z.string().min(3),
    description: z.string().min(10),
    categoryId: z.string(),
    desiredItems: z.string().optional(),
    location: z.string().optional(),
    latitude: z.number().optional(),
    longitude: z.number().optional(),
    estimatedHours: z.number().optional(),
    completionDays: z.number().min(1).max(30).optional(),
    portfolio: z.array(z.string()).optional(),
  }),
  outputSchema: z.object({
    id: z.string(),
    success: z.boolean(),
  }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);

    const cat = await zite.serviceCategories.findOne({ id: input.categoryId });
    if (!cat) throw new ZiteError('Kategori jasa tidak ditemukan');

    const portfolioAttachments = (input.portfolio || []).map(url => ({ url }));

    const service = await zite.services.create({
      record: {
        title: input.title,
        description: input.description,
        category: input.categoryId,
        desiredItems: input.desiredItems || null,
        location: input.location || null,
        latitude: input.latitude ?? null,
        longitude: input.longitude ?? null,
        estimatedHours: input.estimatedHours ?? null,
        completionDays: input.completionDays ?? 7,
        status: 'Tersedia',
        likesCount: 0,
        viewsCount: 0,
        provider: context.user.id,
        portfolio: portfolioAttachments.length > 0 ? portfolioAttachments : null,
      },
    });

    return { id: service.id, success: true };
  },
});

