import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Increment view count for a story',
  authenticated: true,
  inputSchema: z.object({
    storyId: z.string(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const story = await zite.barterStories.findOne({ id: input.storyId });
    if (story) {
      await zite.barterStories.update({
        id: input.storyId,
        record: { viewsCount: (story.viewsCount || 0) + 1 },
      });
    }
    return { success: true };
  },
});

