import { MutariInline } from './MutariSpinner';
import { useState, useEffect } from 'react';
import { MapPin, Navigation, CheckCircle2 } from 'lucide-react';
import { Dialog, DialogContent } from '@project/components/ui/dialog';
import { Button } from '@project/components/ui/button';
import { toast } from 'sonner';
import { updateProfile } from 'zitejs/api';

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  onComplete: () => void;
}

interface LocationData {
  kabupaten: string;
  kecamatan: string;
  desa: string;
}

export default function AddressAutoPopup({ open, onOpenChange, onComplete }: Props) {
  const [detecting, setDetecting] = useState(false);
  const [detected, setDetected] = useState(false);
  const [loc, setLoc] = useState<LocationData>({ kabupaten: '', kecamatan: '', desa: '' });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (open && !detected && !detecting) {
      handleDetect();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const handleDetect = async () => {
    if (!navigator.geolocation) {
      setError('GPS tidak tersedia di perangkat ini');
      return;
    }
    setDetecting(true);
    setError('');

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&accept-language=id&zoom=18&addressdetails=1`
          );
          const data = await res.json();
          const addr = data.address || {};

          const kabupaten = addr.city || addr.county || addr.city_district || addr.municipality || '';
          const kecamatan = addr.suburb || addr.city_district || addr.town || addr.district || '';
          const desa = addr.village || addr.hamlet || addr.neighbourhood || addr.quarter || '';

          setLoc({ kabupaten, kecamatan, desa });
          setDetected(true);
        } catch {
          setError('Gagal mendapatkan data lokasi. Coba lagi.');
        }
        setDetecting(false);
      },
      (err) => {
        if (err.code === 1) {
          setError('Izin lokasi ditolak. Aktifkan GPS di pengaturan perangkat.');
        } else {
          setError('Gagal mendeteksi lokasi. Pastikan GPS aktif.');
        }
        setDetecting(false);
      },
      { enableHighAccuracy: true, timeout: 15000 }
    );
  };

  const handleSave = async () => {
    if (!loc.kabupaten) {
      toast.error('Kabupaten belum terdeteksi');
      return;
    }
    setSaving(true);
    try {
      await updateProfile({
        city: loc.kabupaten,
        address: [loc.desa, loc.kecamatan, loc.kabupaten].filter(Boolean).join(', '),
        province: '',
      });
      toast.success('Alamat berhasil disimpan!');
      onComplete();
      onOpenChange(false);
    } catch {
      toast.error('Gagal menyimpan alamat');
    }
    setSaving(false);
  };

  const isComplete = !!loc.kabupaten;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[380px] rounded-2xl p-0 overflow-hidden">
        {/* Header */}
        <div className="bg-primary/10 px-5 pt-6 pb-4 text-center">
          <div className="mx-auto w-14 h-14 rounded-full bg-primary/15 flex items-center justify-center mb-3">
            <MapPin className="w-7 h-7 text-primary" />
          </div>
          <h3 className="text-lg font-bold text-foreground">Isi Alamat Otomatis</h3>
          <p className="text-xs text-muted-foreground mt-1 leading-relaxed">
            Lokasi terdeteksi dari GPS perangkatmu
          </p>
        </div>

        <div className="px-5 pb-5 pt-3 space-y-4">
          {/* Detecting state */}
          {detecting && (
            <div className="flex items-center gap-3 py-6 justify-center">
              <MutariInline size={20} />
              <span className="text-sm text-muted-foreground">Mendeteksi lokasi...</span>
            </div>
          )}

          {/* Error */}
          {error && !detecting && (
            <div className="bg-destructive/10 border border-destructive/20 rounded-xl px-4 py-3 text-center">
              <p className="text-sm text-destructive">{error}</p>
              <button
                onClick={handleDetect}
                className="mt-2 text-xs font-semibold text-primary underline"
              >
                Coba Lagi
              </button>
            </div>
          )}

          {/* Detected fields */}
          {detected && !detecting && (
            <>
              <LocationField label="Kabupaten / Kota" value={loc.kabupaten} />
              <LocationField label="Kecamatan / Kelurahan" value={loc.kecamatan} />
              <LocationField label="Desa" value={loc.desa} />

              {isComplete && (
                <div className="flex items-center gap-2 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 rounded-xl px-3 py-2.5">
                  <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
                  <p className="text-xs text-emerald-700 dark:text-emerald-400 font-medium">Lokasi berhasil terdeteksi</p>
                </div>
              )}

              {/* Re-detect button */}
              <button
                onClick={handleDetect}
                className="w-full flex items-center justify-center gap-2 text-xs text-primary font-semibold py-2"
              >
                <Navigation className="w-3.5 h-3.5" />
                Deteksi Ulang Lokasi
              </button>
            </>
          )}

          {/* Actions */}
          <div className="flex flex-col gap-2 pt-1">
            <Button
              onClick={handleSave}
              disabled={saving || !isComplete || detecting}
              className="w-full gap-2"
            >
              {saving ? <MutariInline size={16} /> : <CheckCircle2 className="w-4 h-4" />}
              {saving ? 'Menyimpan...' : 'Simpan & Lanjutkan Barter'}
            </Button>
            <Button
              variant="ghost"
              onClick={() => onOpenChange(false)}
              className="w-full text-muted-foreground text-xs"
            >
              Nanti Saja
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function LocationField({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <label className="text-[11px] font-semibold text-muted-foreground mb-1 block uppercase tracking-wide">{label}</label>
      <div className="bg-muted/60 rounded-xl px-3.5 py-3 flex items-center gap-2">
        <MapPin className="w-3.5 h-3.5 text-primary flex-shrink-0" />
        <span className="text-sm text-foreground font-medium">
          {value || <span className="text-muted-foreground italic">Tidak terdeteksi</span>}
        </span>
      </div>
    </div>
  );
}

