import { useState, useEffect } from 'react';
import { getUserAwards, GetUserAwardsOutputType } from 'zitejs/api';

type AwardItem = GetUserAwardsOutputType['awards'][0];

const TIER_DOT: Record<string, string> = {
  diamond: 'bg-cyan-400 ring-cyan-200',
  platinum: 'bg-purple-400 ring-purple-200',
  gold: 'bg-amber-400 ring-amber-200',
  silver: 'bg-gray-400 ring-gray-200',
  bronze: 'bg-orange-400 ring-orange-200',
};

/** Tiny award emoji row — max 3 emojis + count badge. For item cards. */
export function AwardPinsRow({ awards, maxShow = 3 }: { awards: AwardItem[]; maxShow?: number }) {
  if (!awards || awards.length === 0) return null;
  const visible = awards.slice(0, maxShow);
  const remaining = awards.length - maxShow;

  return (
    <div className="inline-flex items-center gap-0.5">
      {visible.map(a => (
        <span key={a.id} className="text-[10px]" title={a.name}>{a.emoji}</span>
      ))}
      {remaining > 0 && (
        <span className="text-[8px] font-bold text-muted-foreground bg-muted rounded-full px-1 leading-none py-0.5">
          +{remaining}
        </span>
      )}
    </div>
  );
}

/** Small awards indicator badge — shows count + top tier dot */
export function AwardCountBadge({ totalAwards, topTier }: { totalAwards: number; topTier: string }) {
  if (totalAwards === 0) return null;
  const dot = TIER_DOT[topTier] || TIER_DOT.bronze;

  return (
    <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-amber-50 border border-amber-200 text-[9px] font-bold text-amber-700">
      <span className={`w-1.5 h-1.5 rounded-full ring-1 ${dot}`} />
      🏆 {totalAwards}
    </span>
  );
}

/** Hook to fetch awards for a user (caches in state) */
export function useUserAwards(userId: string | null) {
  const [awards, setAwards] = useState<AwardItem[]>([]);
  const [totalAwards, setTotalAwards] = useState(0);
  const [topTier, setTopTier] = useState('none');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!userId) return;
    setLoading(true);
    getUserAwards({ userId })
      .then(data => {
        setAwards(data.awards);
        setTotalAwards(data.totalAwards);
        setTopTier(data.topTier);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [userId]);

  return { awards, totalAwards, topTier, loading };
}

/** Compact awards row for profile headers — shows emojis + "X penghargaan" */
