import { useState, useEffect } from 'react';
import { getUserAwards, GetUserAwardsOutputType } from 'zitejs/api';
import { Trophy, ChevronRight, Award } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { useNavigate } from 'react-router-dom';

type AwardData = GetUserAwardsOutputType['awards'][0];

const TIER_STYLES: Record<string, { bg: string; border: string; text: string; label: string }> = {
  diamond: { bg: 'bg-gradient-to-r from-cyan-50 to-blue-50', border: 'border-cyan-300', text: 'text-cyan-800', label: '💎 Diamond' },
  platinum: { bg: 'bg-gradient-to-r from-purple-50 to-fuchsia-50', border: 'border-purple-300', text: 'text-purple-800', label: '🔮 Platinum' },
  gold: { bg: 'bg-gradient-to-r from-amber-50 to-yellow-50', border: 'border-amber-300', text: 'text-amber-800', label: '🥇 Gold' },
  silver: { bg: 'bg-gradient-to-r from-gray-50 to-slate-50', border: 'border-gray-300', text: 'text-gray-700', label: '🥈 Silver' },
  bronze: { bg: 'bg-gradient-to-r from-orange-50 to-amber-50', border: 'border-orange-300', text: 'text-orange-800', label: '🥉 Bronze' },
};

function AwardPin({ award }: { award: AwardData }) {
  const tier = TIER_STYLES[award.tier] || TIER_STYLES.bronze;
  return (
    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-xl border ${tier.bg} ${tier.border}`}>
      <span className="text-base">{award.emoji}</span>
      <div className="min-w-0">
        <p className={`text-[10px] font-bold leading-tight ${tier.text}`}>{award.name}</p>
        <p className="text-[8px] text-muted-foreground leading-tight">{award.programName}</p>
      </div>
    </div>
  );
}

function AwardCard({ award }: { award: AwardData }) {
  const tier = TIER_STYLES[award.tier] || TIER_STYLES.bronze;
  return (
    <div className={`rounded-2xl border p-3 ${tier.bg} ${tier.border} transition-all hover:shadow-md`}>
      <div className="flex items-start gap-2.5">
        <div className="text-2xl flex-shrink-0 mt-0.5">{award.emoji}</div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <p className={`font-bold text-xs ${tier.text}`}>{award.name}</p>
            <span className={`text-[8px] px-1.5 py-0.5 rounded-full font-bold ${tier.bg} ${tier.border} border ${tier.text}`}>
              {TIER_STYLES[award.tier]?.label.split(' ')[1] || award.tier}
            </span>
          </div>
          <p className="text-[10px] text-muted-foreground mt-0.5">{award.description}</p>
          <p className="text-[9px] text-muted-foreground/70 mt-1">Program: {award.programName}</p>
        </div>
      </div>
    </div>
  );
}

interface AwardsShowcaseProps {
  userId: string;
  compact?: boolean;
  showTitle?: boolean;
  maxVisible?: number;
}

export default function AwardsShowcase({ userId, compact = false, showTitle = true, maxVisible }: AwardsShowcaseProps) {
  const [data, setData] = useState<GetUserAwardsOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    getUserAwards({ userId })
      .then(setData)
      .catch(() => setData(null))
      .finally(() => setLoading(false));
  }, [userId]);

  if (loading) {
    return (
      <div className="px-4 mt-4">
        {showTitle && <Skeleton className="h-4 w-32 mb-3" />}
        <div className="flex gap-2 flex-wrap">
          {[1, 2, 3].map(i => <Skeleton key={i} className="h-10 w-28 rounded-xl" />)}
        </div>
      </div>
    );
  }

  if (!data || data.totalAwards === 0) {
    if (compact) return null;
    return (
      <div className="px-4 mt-4">
        {showTitle && <h3 className="font-bold text-sm mb-3 flex items-center gap-2"><Trophy className="w-4 h-4 text-amber-500" /> Penghargaan Program</h3>}
        <div className="bg-card border border-border rounded-2xl p-5 text-center shadow-sm">
          <Award className="w-8 h-8 text-muted-foreground/40 mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">Belum ada penghargaan</p>
          <p className="text-[10px] text-muted-foreground/60 mt-1">Ikuti challenge, misi, dan aktif barter untuk mendapat penghargaan!</p>
        </div>
      </div>
    );
  }

  // Group by program
  const byProgram = new Map<string, AwardData[]>();
  data.awards.forEach(a => {
    const list = byProgram.get(a.programId) || [];
    list.push(a);
    byProgram.set(a.programId, list);
  });

  const limit = maxVisible || (compact ? 6 : undefined);
  const visibleAwards = limit ? data.awards.slice(0, limit) : data.awards;
  const hasMore = limit ? data.awards.length > limit : false;

  if (compact) {
    return (
      <div className="px-4 mt-3">
        {showTitle && (
          <div className="flex items-center justify-between mb-2">
            <h3 className="font-bold text-sm flex items-center gap-1.5">
              <Trophy className="w-3.5 h-3.5 text-amber-500" />
              Penghargaan ({data.totalAwards})
            </h3>
            {data.totalAwards > 0 && (
              <button onClick={() => navigate('/achievements')} className="text-[11px] text-primary font-semibold flex items-center gap-0.5">
                Semua <ChevronRight className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        )}
        <div className="flex gap-1.5 flex-wrap">
          {visibleAwards.map(a => <AwardPin key={a.id} award={a} />)}
          {hasMore && (
            <button onClick={() => navigate('/achievements')} className="inline-flex items-center px-2.5 py-1.5 rounded-xl border border-dashed border-muted-foreground/30 text-[10px] text-muted-foreground font-semibold hover:border-primary hover:text-primary transition-colors">
              +{data.totalAwards - (limit || 0)} lagi
            </button>
          )}
        </div>
      </div>
    );
  }

  // Full expanded view — grouped by program
  return (
    <div className="px-4 mt-4">
      {showTitle && (
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-bold text-sm flex items-center gap-2">
            <Trophy className="w-4 h-4 text-amber-500" />
            Penghargaan Program ({data.totalAwards})
          </h3>
          {!expanded && data.awards.length > 4 && (
            <button onClick={() => setExpanded(true)} className="text-[11px] text-primary font-semibold flex items-center gap-0.5">
              Tampilkan semua <ChevronRight className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      )}

      {/* Summary ribbon */}
      <div className="bg-gradient-to-r from-amber-50 via-yellow-50 to-orange-50 border border-amber-200 rounded-2xl p-3 mb-3 flex items-center gap-3">
        <div className="text-2xl">🏆</div>
        <div className="flex-1">
          <p className="font-bold text-sm text-amber-800">{data.totalAwards} Penghargaan</p>
          <p className="text-[10px] text-amber-700/70">Tier tertinggi: {TIER_STYLES[data.topTier]?.label || data.topTier}</p>
        </div>
        <div className="flex gap-0.5">
          {data.awards.slice(0, 5).map(a => (
            <span key={a.id} className="text-lg">{a.emoji}</span>
          ))}
        </div>
      </div>

      {/* Award cards grouped by program */}
      {expanded ? (
        <div className="space-y-4">
          {Array.from(byProgram.entries()).map(([pid, awards]) => (
            <div key={pid}>
              <p className="text-[11px] font-bold text-muted-foreground uppercase tracking-wider mb-2">{awards[0].programName}</p>
              <div className="space-y-2">
                {awards.map(a => <AwardCard key={a.id} award={a} />)}
              </div>
            </div>
          ))}
          <button onClick={() => setExpanded(false)} className="w-full text-center text-xs text-primary font-semibold py-2">
            Sembunyikan
          </button>
        </div>
      ) : (
        <div className="space-y-2">
          {data.awards.slice(0, 4).map(a => <AwardCard key={a.id} award={a} />)}
          {data.awards.length > 4 && (
            <button onClick={() => setExpanded(true)} className="w-full bg-card border border-border rounded-2xl p-3 text-center hover:bg-muted/50 transition-colors shadow-sm">
              <p className="text-xs text-primary font-semibold">Lihat {data.awards.length - 4} penghargaan lagi →</p>
            </button>
          )}
        </div>
      )}
    </div>
  );
}

// Exported sub-component for inline usage
export { AwardPin, AwardCard };

