import { getBadge, type MutariBadge } from '../lib/badges';

/**
 * BadgeAvatar — Avatar with gradient ring border + glow + emoji indicator.
 */

/* Gradient border colors per tier */
const GRADIENT_CSS: Record<string, string> = {
  pemula:     'linear-gradient(135deg, #34d399, #6ee7b7, #a7f3d0)',
  aktif:      'linear-gradient(135deg, #3b82f6, #60a5fa, #93c5fd)',
  terpercaya: 'linear-gradient(135deg, #f59e0b, #fbbf24, #fcd34d)',
  profesional:'linear-gradient(135deg, #a855f7, #7c3aed, #3b82f6, #a855f7)',
  legenda:    'conic-gradient(from 0deg, #d97706, #eab308, #facc15, #fde047, #facc15, #eab308, #d97706)',
  mentor:     'conic-gradient(from 0deg, #14b8a6, #0d9488, #14b8a6)',
  elite:      'linear-gradient(135deg, #f43f5e, #ec4899, #d946ef, #f43f5e)',
};

const GLOW_SHADOW: Record<string, string> = {
  pemula:     '0 0 8px 2px rgba(52,211,153,0.4), 0 0 18px 4px rgba(52,211,153,0.15)',
  aktif:      '0 0 8px 2px rgba(96,165,250,0.4), 0 0 18px 4px rgba(96,165,250,0.15)',
  terpercaya: '0 0 8px 2px rgba(251,191,36,0.45), 0 0 18px 4px rgba(251,191,36,0.18)',
  profesional:'0 0 8px 2px rgba(192,132,252,0.45), 0 0 18px 4px rgba(192,132,252,0.18)',
  legenda:    '0 0 10px 3px rgba(250,204,21,0.5), 0 0 22px 6px rgba(250,204,21,0.2)',
  mentor:     '0 0 10px 3px rgba(20,184,166,0.5), 0 0 22px 6px rgba(20,184,166,0.2)',
  elite:      '0 0 12px 4px rgba(244,63,94,0.5), 0 0 24px 8px rgba(236,72,153,0.2)',
};

const RING_BG: Record<string, string> = {
  pemula: 'bg-emerald-100 text-emerald-700',
  aktif: 'bg-blue-100 text-blue-700',
  terpercaya: 'bg-amber-100 text-amber-700',
  profesional: 'bg-purple-100 text-purple-700',
  legenda: 'bg-gradient-to-br from-amber-200 to-yellow-100 text-amber-800',
  mentor: 'bg-gradient-to-br from-teal-200 to-cyan-100 text-teal-800',
  elite: 'bg-gradient-to-br from-rose-200 to-pink-100 text-rose-800',
};

/* Ring thickness in px per size */
const RING_PX: Record<string, number> = {
  xs: 2, sm: 2.5, md: 3, lg: 3.5, xl: 4,
};

const SIZE_MAP = {
  xs: { outer: 'w-8 h-8',   avatar: 'w-6 h-6',   emoji: 'w-3.5 h-3.5 text-[7px] -bottom-0.5 -right-0.5', text: 'text-[9px]' },
  sm: { outer: 'w-10 h-10', avatar: 'w-8 h-8',    emoji: 'w-4 h-4 text-[8px] -bottom-0.5 -right-0.5',     text: 'text-[10px]' },
  md: { outer: 'w-[50px] h-[50px]', avatar: 'w-[42px] h-[42px]', emoji: 'w-5 h-5 text-[10px] -bottom-0.5 -right-0.5', text: 'text-xs' },
  lg: { outer: 'w-[62px] h-[62px]', avatar: 'w-[52px] h-[52px]', emoji: 'w-6 h-6 text-[12px] -bottom-0.5 -right-0.5', text: 'text-sm' },
  xl: { outer: 'w-[86px] h-[86px]', avatar: 'w-[74px] h-[74px]', emoji: 'w-7 h-7 text-[14px] -bottom-0.5 -right-0.5', text: 'text-base' },
};

interface BadgeAvatarProps {
  src?: string | null;
  initials?: string;
  points?: number;
  badge?: MutariBadge;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
  onClick?: () => void;
  showBadge?: boolean;
  glow?: boolean;
}

export default function BadgeAvatar({
  src,
  initials = 'U',
  points = 0,
  badge: badgeOverride,
  size = 'md',
  className = '',
  onClick,
  showBadge = true,
  glow = true,
}: BadgeAvatarProps) {
  const badge = badgeOverride ?? getBadge(points);
  const s = SIZE_MAP[size];
  const emojiBg = RING_BG[badge.id] || 'bg-muted text-foreground';
  const gradientBg = GRADIENT_CSS[badge.id] || 'linear-gradient(135deg, #94a3b8, #cbd5e1, #e2e8f0)';
  const glowShadow = glow ? (GLOW_SHADOW[badge.id] || 'none') : 'none';
  const isLegenda = badge.id === 'legenda';
  const isElite = badge.id === 'elite';
  const isMentor = badge.id === 'mentor';
  const hasSpinRing = isElite || isMentor;

  // Mentor: slow single-color spin (8s), Elite: faster multi-color spin (6s)
  const spinAnim = isElite
    ? 'eliteRingSpin 6s linear infinite'
    : isMentor
    ? 'mentorRingSpin 8s linear infinite'
    : undefined;

  const Wrapper = onClick ? 'button' : 'div';

  return (
    <Wrapper onClick={onClick} className={`relative inline-flex flex-shrink-0 ${className}`}>
      {/* Gradient ring container */}
      <div
        className={`${s.outer} rounded-full flex items-center justify-center overflow-hidden`}
        style={{
          background: gradientBg,
          boxShadow: glowShadow,
          padding: `${RING_PX[size]}px`,
          position: 'relative',
          ...(spinAnim ? { animation: spinAnim } : {}),
        }}
      >
        {/* Shimmer sweep overlay for legenda */}
        {isLegenda && (
          <div
            className="absolute inset-0 rounded-full pointer-events-none"
            style={{
              background: 'linear-gradient(105deg, transparent 30%, rgba(255,255,255,0.55) 45%, rgba(255,255,255,0.7) 50%, rgba(255,255,255,0.55) 55%, transparent 70%)',
              backgroundSize: '250% 100%',
              animation: 'badgeShimmer 2.5s ease-in-out infinite',
            }}
          />
        )}
        {/* Legenda pulsing glow overlay */}
        {isLegenda && (
          <div
            className="absolute inset-[-3px] rounded-full pointer-events-none"
            style={{
              background: 'transparent',
              boxShadow: '0 0 12px 3px rgba(250,204,21,0.45)',
              animation: 'legendaPulse 2s ease-in-out infinite',
            }}
          />
        )}
        {/* Inner background gap (ring-offset effect) */}
        <div
          className="w-full h-full rounded-full flex items-center justify-center relative"
          style={{
            background: 'hsl(var(--background))',
            padding: '1.5px',
            ...(hasSpinRing ? { animation: spinAnim, animationDirection: 'reverse' } : {}),
          }}
        >
          {src ? (
            <img src={src} alt="" className="w-full h-full rounded-full object-cover" />
          ) : (
            <div className={`w-full h-full rounded-full ${emojiBg} flex items-center justify-center ${s.text} font-bold`}>
              {initials}
            </div>
          )}
        </div>
      </div>

      {showBadge && (
        <span
          className={`absolute ${s.emoji} rounded-full flex items-center justify-center shadow-sm border border-background leading-none ${emojiBg}`}
          title={badge.name}
        >
          {badge.emoji}
        </span>
      )}
    </Wrapper>
  );
}

import { getBadge, type MutariBadge } from '../lib/badges';

interface Props {
  points: number;
  size?: 'sm' | 'md' | 'lg';
  showName?: boolean;
  badge?: MutariBadge;
}

export default function BadgeChip({ points, size = 'sm', showName = true, badge: overrideBadge }: Props) {
  const badge = overrideBadge || getBadge(points);

  const sizeClasses = {
    sm: 'text-[9px] px-1.5 py-0.5 gap-0.5',
    md: 'text-[11px] px-2 py-1 gap-1',
    lg: 'text-sm px-3 py-1.5 gap-1.5',
  };

  return (
    <span className={`inline-flex items-center rounded-full font-semibold border ${badge.color} ${badge.textColor} ${badge.borderColor} ${sizeClasses[size]}`}>
      <span>{badge.emoji}</span>
      {showName && <span>{badge.name}</span>}
    </span>
  );
}

