import { useState, useEffect, createContext, useContext, type ReactNode } from 'react';
import { getProfile } from 'zitejs/api';
import { useAuth, logout } from 'zitejs/auth';
import { ShieldBan, LogOut, Home, AlertTriangle } from 'lucide-react';

interface BanContextType {
  isBanned: boolean;
  bannedReason: string;
}

const BanContext = createContext<BanContextType>({ isBanned: false, bannedReason: '' });

export function useBanStatus() {
  return useContext(BanContext);
}

export default function BanGate({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [isBanned, setIsBanned] = useState(false);
  const [bannedReason, setBannedReason] = useState('');
  const [checked, setChecked] = useState(false);

  useEffect(() => {
    if (!user) { setChecked(true); return; }
    getProfile({}).then(res => {
      setIsBanned(res.banned);
      setBannedReason(res.bannedReason || '');
      setChecked(true);
    }).catch(() => setChecked(true));
  }, [user]);

  if (!checked) return null;

  return (
    <BanContext.Provider value={{ isBanned, bannedReason }}>
      {children}
    </BanContext.Provider>
  );
}

/**
 * Full-screen banned overlay shown on non-beranda pages
 */
export function BannedScreen({ bannedReason }: { bannedReason: string }) {
  return (
