          <div className="rounded-xl bg-destructive/5 border border-destructive/20 p-4 text-left">
            <p className="text-xs font-semibold text-destructive flex items-center gap-1.5 mb-1">
              <AlertTriangle size={14} /> Alasan Pembatasan
            </p>
            <p className="text-sm text-destructive/80">{bannedReason}</p>
          </div>
        )}

        <div className="rounded-xl bg-muted p-4 text-left space-y-2">
          <p className="text-xs font-semibold text-muted-foreground">Yang bisa kamu lakukan:</p>
          <div className="flex items-center gap-2 text-sm text-foreground">
            <Home size={14} className="text-primary shrink-0" />
            <span>Melihat beranda dan browse barang</span>
          </div>
          <p className="text-xs font-semibold text-muted-foreground mt-2">Yang tidak bisa kamu lakukan:</p>
          <ul className="text-xs text-muted-foreground space-y-1 ml-5 list-disc">
