type ItemType = GetItemsOutputType['items'][0];

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: ItemType): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/aYmFPbU63ZSYCP5WK76Yni/img_5j_3U1FxA70D24aF.jpg';

function ListItem({ item, onClick }: { item: ItemType; onClick: () => void }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  return (
    <div onClick={onClick} className="rounded-2xl border border-border bg-card p-3 flex gap-3.5 cursor-pointer shadow-sm hover:shadow-md transition-shadow">
      <div className="relative flex-shrink-0">
        <img src={imgUrl} alt={item.title} className="w-[100px] h-[85px] rounded-xl object-cover" />
        <div className="absolute top-1.5 left-1.5 bg-black/50 backdrop-blur-sm rounded-full px-1.5 py-0.5 flex items-center gap-0.5 text-[9px] text-white font-medium">
          <Clock className="w-2.5 h-2.5" /> {item.condition || 'Baru'}
        </div>
      </div>
      <div className="flex-1 min-w-0 flex flex-col justify-between">
