import { useState } from 'react';
import { Home, Search, Plus, MessageCircle, User, Bell, Star, Package, Users, Wrench } from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useUnread } from '../context/UnreadContext';
import { useI18n } from '../context/I18nContext';
import { useProfile } from '../hooks/useProfile';
import AddressAutoPopup from './AddressAutoPopup';

export default function BottomNav() {
  const navigate = useNavigate();
  const location = useLocation();
  const { unreadChats, unreadNotifications } = useUnread();
  const { t } = useI18n();
  const { profile, refresh } = useProfile();
  const [showAddressPopup, setShowAddressPopup] = useState(false);

  const addressComplete = !!(profile?.address && profile?.city);

  const handleBarterClick = () => {
    if (!addressComplete) {
      setShowAddressPopup(true);
    } else {
      navigate('/upload');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const tabs = [
    { icon: Home, label: t('nav.home'), path: '/' },
    { icon: Search, label: t('nav.search'), path: '/search' },
    { icon: Plus, label: t('nav.barter'), path: '/upload', center: true },
    { icon: MessageCircle, label: t('nav.chat'), path: '/chat', badgeKey: 'chat' as const },
    { icon: User, label: t('nav.profile'), path: '/profile' },
  ];

  const sidebarExtra = [
    { icon: Bell, label: 'Notifikasi', path: '/notifications', badge: unreadNotifications },
    { icon: Star, label: 'Wishlist', path: '/wishlist' },
    { icon: Package, label: 'Barang Saya', path: '/my-items' },
    { icon: Users, label: 'Komunitas', path: '/community' },
    { icon: Wrench, label: 'Jasa', path: '/services' },
  ];

  const goTo = (path: string) => {
    navigate(path);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <>
      <AddressAutoPopup
        open={showAddressPopup}
        onOpenChange={setShowAddressPopup}
        onComplete={() => {
          refresh();
          navigate('/upload');
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }}
      />

      {/* ─── Desktop Sidebar (lg+) ─── */}
      <aside className="hidden lg:flex fixed top-0 left-0 bottom-0 w-[220px] xl:w-[240px] bg-card border-r border-border z-50 flex-col py-5 px-3">
        {/* Logo */}
        <button onClick={() => goTo('/')} className="flex items-center gap-2 px-3 mb-6">
          <img
            src="https://images.fillout.com/orgid-821712/flowpublicid-exc3bfzedf/widgetid-default/c4U5MKmRLfd25oi9xTWroJ/pasted-image-1787356702680-whjg5y1j.png"
            alt="MUTARI"
            className="h-6 object-contain"
          />
        </button>

        {/* Barter CTA */}
        <button
          onClick={handleBarterClick}
          className="flex items-center gap-3 px-4 py-3 mb-4 rounded-xl bg-primary text-primary-foreground font-bold text-sm shadow-md shadow-primary/20 hover:opacity-90 transition-opacity"
        >
          <Plus className="w-5 h-5" />
          {t('nav.barter')}
        </button>

        {/* Main nav */}
        <nav className="flex-1 space-y-1">
          {tabs.filter(t => !t.center).map((tab) => {
            const active = location.pathname === tab.path;
            const badge = tab.badgeKey === 'chat' ? unreadChats : 0;
            return (
              <button
                key={tab.label}
                onClick={() => goTo(tab.path)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-colors ${
                  active
                    ? 'bg-primary/10 text-primary font-semibold'
                    : 'text-muted-foreground hover:bg-accent hover:text-foreground'
                }`}
              >
                <div className="relative">
                  <tab.icon className="w-5 h-5" />
                  {badge > 0 && (
                    <span className="absolute -top-1.5 -right-2 min-w-[16px] h-4 px-1 flex items-center justify-center rounded-full bg-destructive text-destructive-foreground text-[9px] font-bold leading-none">
                      {badge > 99 ? '99+' : badge}
                    </span>
                  )}
                </div>
                {tab.label}
              </button>
            );
          })}

          <div className="h-px bg-border my-3" />

          {sidebarExtra.map((item) => {
            const active = location.pathname === item.path;
            const badge = item.badge || 0;
            return (
              <button
                key={item.label}
                onClick={() => goTo(item.path)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-colors ${
                  active
                    ? 'bg-primary/10 text-primary font-semibold'
                    : 'text-muted-foreground hover:bg-accent hover:text-foreground'
                }`}
              >
                <div className="relative">
                  <item.icon className="w-5 h-5" />
                  {badge > 0 && (
                    <span className="absolute -top-1.5 -right-2 min-w-[16px] h-4 px-1 flex items-center justify-center rounded-full bg-destructive text-destructive-foreground text-[9px] font-bold leading-none">
                      {badge > 99 ? '99+' : badge}
                    </span>
                  )}
                </div>
                {item.label}
              </button>
            );
          })}
        </nav>

        {/* User info at bottom */}
        <button onClick={() => goTo('/profile')} className="flex items-center gap-2.5 px-3 py-2 mt-2 rounded-xl hover:bg-accent transition-colors">
          {profile?.image ? (
            <img src={profile.image} alt="" className="w-8 h-8 rounded-full object-cover" />
          ) : (
            <div className="w-8 h-8 rounded-full bg-primary/15 flex items-center justify-center text-xs font-bold text-primary">
              {(profile?.displayName?.[0] || 'U').toUpperCase()}
            </div>
          )}
          <div className="flex-1 min-w-0 text-left">
            <p className="text-xs font-semibold text-foreground truncate">{profile?.displayName || 'Pengguna'}</p>
            <p className="text-[10px] text-muted-foreground truncate">{profile?.city || 'Atur profil'}</p>
          </div>
        </button>
      </aside>

      {/* ─── Mobile Bottom Nav (<lg) ─── */}
      <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-card/95 backdrop-blur-md border-t border-border z-50">
        <div className="max-w-[420px] mx-auto flex items-center justify-around px-2 pb-[env(safe-area-inset-bottom)] pt-1">
          {tabs.map((tab) => {
            const active = location.pathname === tab.path;
            const badge = tab.badgeKey === 'chat' ? unreadChats : 0;

            if (tab.center) {
              return (
                <button key={tab.label} onClick={handleBarterClick} data-tour="tour-upload" className="flex flex-col items-center -mt-5">
                  <div className="w-13 h-13 rounded-full bg-primary flex items-center justify-center shadow-lg shadow-primary/30">
                    <Plus className="w-6 h-6 text-primary-foreground" />
                  </div>
                  <span className="text-[10px] font-semibold text-foreground mt-0.5">{tab.label}</span>
                </button>
              );
            }
            return (
              <button key={tab.label} onClick={() => goTo(tab.path)} data-tour={tab.badgeKey === 'chat' ? 'tour-chat' : undefined} className="relative flex flex-col items-center gap-0.5 min-w-[48px] py-1.5">
                <div className="relative">
                  <tab.icon className={`w-5 h-5 ${active ? 'text-primary' : 'text-muted-foreground'}`} />
                  {badge > 0 && (
                    <span className="absolute -top-1.5 -right-2.5 min-w-[16px] h-4 px-1 flex items-center justify-center rounded-full bg-destructive text-destructive-foreground text-[9px] font-bold leading-none">
                      {badge > 99 ? '99+' : badge}
                    </span>
                  )}
                </div>
                <span className={`text-[10px] ${active ? 'text-primary font-semibold' : 'text-muted-foreground'}`}>
                  {tab.label}
                </span>
              </button>
            );
          })}
        </div>
      </nav>
    </>
  );
}

