import { useEffect, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface Particle {
  id: number;
  x: number;
  y: number;
  color: string;
  size: number;
  rotation: number;
  delay: number;
  shape: 'circle' | 'rect' | 'star' | 'diamond';
  driftX: number;
}

const COLORS = [
  '#FFD700', '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4',
  '#FFEAA7', '#DDA0DD', '#98D8C8', '#F7DC6F', '#BB8FCE',
  '#FF9FF3', '#54A0FF', '#5F27CD', '#01A3A4', '#F368E0',
];

const SHAPES: Particle['shape'][] = ['circle', 'rect', 'star', 'diamond'];

function randomBetween(a: number, b: number) {
  return Math.random() * (b - a) + a;
}

function createParticles(count: number): Particle[] {
  return Array.from({ length: count }, (_, i) => ({
    id: i,
    x: randomBetween(5, 95),
    y: randomBetween(-10, 30),
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
    size: randomBetween(4, 10),
    rotation: randomBetween(0, 360),
    delay: randomBetween(0, 0.6),
    shape: SHAPES[Math.floor(Math.random() * SHAPES.length)],
    driftX: randomBetween(-40, 40),
  }));
}

function ParticleShape({ p }: { p: Particle }) {
  if (p.shape === 'star') {
    return (
      <svg width={p.size * 2} height={p.size * 2} viewBox="0 0 24 24" fill={p.color}>
        <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />
      </svg>
    );
  }
  if (p.shape === 'diamond') {
    return (
      <div
        style={{
          width: p.size,
          height: p.size,
          backgroundColor: p.color,
          transform: 'rotate(45deg)',
        }}
      />
    );
  }
  if (p.shape === 'rect') {
    return (
      <div
        style={{
          width: p.size * 1.8,
          height: p.size * 0.6,
          backgroundColor: p.color,
          borderRadius: 1,
        }}
      />
    );
  }
  return (
    <div
      style={{
        width: p.size,
        height: p.size,
        backgroundColor: p.color,
        borderRadius: '50%',
      }}
    />
  );
}

interface ConfettiProps {
  active: boolean;
  count?: number;
  duration?: number;
}

export default function Confetti({ active, count = 50, duration = 3000 }: ConfettiProps) {
  const [particles, setParticles] = useState<Particle[]>([]);
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (active) {
      setParticles(createParticles(count));
      setShow(true);
      const t = setTimeout(() => setShow(false), duration);
      return () => clearTimeout(t);
    }
  }, [active, count, duration]);

  return (
    <AnimatePresence>
      {show && (
        <div className="fixed inset-0 pointer-events-none z-[9999] overflow-hidden">
          {particles.map((p) => (
            <motion.div
              key={p.id}
              initial={{
                left: `${p.x}%`,
                top: `${p.y}%`,
                opacity: 1,
                rotate: 0,
                scale: 0,
              }}
              animate={{
                top: '110%',
                left: `${p.x + p.driftX}%`,
                opacity: [1, 1, 0.8, 0],
                rotate: p.rotation + randomBetween(180, 720),
                scale: [0, 1.2, 1, 0.6],
              }}
              exit={{ opacity: 0 }}
              transition={{
                duration: randomBetween(1.8, 3.2),
                delay: p.delay,
                ease: [0.25, 0.46, 0.45, 0.94],
              }}
              className="absolute"
            >
              <ParticleShape p={p} />
            </motion.div>
          ))}
        </div>
      )}
    </AnimatePresence>
  );
}

/** Smaller sparkle burst — used inline near point badges/numbers */
export function PointSparkle({ active }: { active: boolean }) {
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (active) {
      setShow(true);
      const t = setTimeout(() => setShow(false), 1600);
      return () => clearTimeout(t);
    }
  }, [active]);

  const sparks = Array.from({ length: 8 }, (_, i) => {
    const angle = (i / 8) * 360;
    const rad = (angle * Math.PI) / 180;
    const dist = randomBetween(18, 32);
    return { id: i, tx: Math.cos(rad) * dist, ty: Math.sin(rad) * dist, angle };
  });

  return (
    <AnimatePresence>
      {show && (
        <span className="absolute inset-0 pointer-events-none">
          {sparks.map((s) => (
            <motion.span
              key={s.id}
              initial={{ opacity: 1, x: 0, y: 0, scale: 0 }}
              animate={{ opacity: [1, 1, 0], x: s.tx, y: s.ty, scale: [0, 1.2, 0] }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.8, ease: 'easeOut' }}
              className="absolute left-1/2 top-1/2 w-1.5 h-1.5 rounded-full"
              style={{ backgroundColor: COLORS[s.id % COLORS.length] }}
            />
          ))}
          {/* Center glow */}
          <motion.span
            initial={{ opacity: 0, scale: 0 }}
            animate={{ opacity: [0, 0.6, 0], scale: [0.5, 1.5, 2] }}
            transition={{ duration: 0.6 }}
