import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Flame, Check, Gift, ChevronRight, Sparkles } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { getCheckinStatus, dailyCheckin, GetCheckinStatusOutputType } from 'zitejs/api';
import Confetti from './Confetti';

export default function DailyCheckin() {
  const navigate = useNavigate();
  const [data, setData] = useState<GetCheckinStatusOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [checking, setChecking] = useState(false);
  const [showReward, setShowReward] = useState(false);
  const [rewardMsg, setRewardMsg] = useState('');
  const [rewardPts, setRewardPts] = useState(0);
  const [showConfetti, setShowConfetti] = useState(false);

  useEffect(() => {
    getCheckinStatus({}).then(setData).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const handleCheckin = async () => {
    if (checking || data?.checkedInToday) return;
    setChecking(true);
    try {
      const res = await dailyCheckin({});
      setRewardMsg(res.message);
      setRewardPts(res.pointsEarned);
      setShowReward(true);
      if (res.streakBonus) setShowConfetti(true);
      const updated = await getCheckinStatus({});
      setData(updated);
      setTimeout(() => setShowReward(false), 4000);
      setTimeout(() => setShowConfetti(false), 3000);
    } catch {
      // ignore
    } finally {
      setChecking(false);
    }
  };

  if (loading || !data) {
    return (
      <div className="mx-4 mb-1">
        <div className="rounded-xl bg-card shadow-sm px-3 py-2.5 flex items-center gap-3">
          <div className="w-7 h-7 rounded-full bg-muted animate-pulse flex-shrink-0" />
          <div className="flex-1 space-y-1">
            <div className="h-3 w-28 rounded bg-muted animate-pulse" />
            <div className="h-2 w-40 rounded bg-muted animate-pulse" />
          </div>
          <div className="w-16 h-7 rounded-full bg-muted animate-pulse" />
        </div>
      </div>
    );
  }

  const streakDayInWeek = data.currentStreak % 7;
  const nextBonusIn = streakDayInWeek === 0 && data.currentStreak > 0 ? 7 : 7 - streakDayInWeek;

  return (
    <>
      {showConfetti && <Confetti active={showConfetti} />}
      <div className="mx-4 mb-1">
        <div className="rounded-xl bg-card shadow-sm overflow-hidden">
          {/* Main row */}
          <div className="flex items-center gap-2.5 px-3 py-2.5">
            <div className="w-9 h-9 rounded-lg bg-primary flex items-center justify-center flex-shrink-0 shadow-sm">
              <Flame className="w-4.5 h-4.5 text-primary-foreground" />
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-1.5">
                <span className="text-xs font-bold text-foreground">Check-in</span>
                {data.currentStreak > 0 && (
                  <span className="text-[9px] text-primary font-semibold bg-primary/10 px-1.5 py-0.5 rounded-full">
                    🔥{data.currentStreak}d
                  </span>
                )}
              </div>
              <div className="flex items-center gap-[3px] mt-1">
                {data.weekDays.map((d, i) => (
                  <div
                    key={i}
                    className={`w-[20px] h-[20px] rounded-full flex items-center justify-center text-[8px] font-bold transition-all ${
                      d.checkedIn
                        ? 'bg-primary text-primary-foreground shadow-sm'
                        : d.isToday
                        ? 'border-[1.5px] border-primary text-primary bg-primary/5'
                        : 'bg-muted text-muted-foreground'
                    }`}
                  >
                    {d.checkedIn ? <Check className="w-2.5 h-2.5" /> : d.day.charAt(0)}
                  </div>
                ))}
              </div>
            </div>

            <button
              onClick={handleCheckin}
              disabled={data.checkedInToday || checking}
              className={`px-3.5 py-2 rounded-xl text-[11px] font-bold transition-all flex-shrink-0 ${
                data.checkedInToday
                  ? 'bg-muted text-muted-foreground'
                  : 'bg-primary text-primary-foreground shadow-sm active:scale-95'
              }`}
            >
              {checking ? (
                <span className="w-3 h-3 border-2 border-primary-foreground border-t-transparent rounded-full animate-spin inline-block" />
              ) : data.checkedInToday ? (
                <span className="flex items-center gap-0.5"><Check className="w-3 h-3" />Hadir</span>
              ) : (
                <span className="flex items-center gap-0.5"><Sparkles className="w-3 h-3" />Hadir!</span>
              )}
            </button>
          </div>

          {/* Mission link */}
          <button
            onClick={() => navigate('/missions')}
            className="w-full flex items-center justify-between px-3 py-1.5 bg-muted/30 border-t border-border/40 hover:bg-muted/50 transition-colors"
          >
            <div className="flex items-center gap-1.5">
              <Gift className="w-3 h-3 text-primary" />
              <span className="text-[10px] font-medium text-foreground">Misi Mingguan</span>
              {data.currentStreak > 0 && (
                <span className="text-[9px] text-muted-foreground">• Bonus {nextBonusIn}d lagi</span>
              )}
            </div>
            <ChevronRight className="w-3 h-3 text-muted-foreground" />
          </button>
        </div>

        {/* Reward popup */}
        <AnimatePresence>
          {showReward && (
            <motion.div
              initial={{ opacity: 0, y: 20, scale: 0.9 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -20, scale: 0.9 }}
              className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-2xl bg-primary text-primary-foreground shadow-2xl"
            >
              <div className="text-center">
                <p className="text-lg font-bold">+{rewardPts} Poin! 🎉</p>
                <p className="text-xs opacity-90">{rewardMsg}</p>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </>
  );
}

