import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Camera, Search, ArrowRightLeft, UserCircle, ChevronRight, X, Sparkles } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useProfile } from '../hooks/useProfile';
import { getMyItems } from 'zitejs/api';

interface Step {
  id: string;
  icon: React.ReactNode;
  title: string;
  desc: string;
  action: string;
  route: string;
  done: boolean;
}

export default function OnboardingCard() {
  const navigate = useNavigate();
  const { profile } = useProfile();
  const [dismissed, setDismissed] = useState(false);
  const [hasItems, setHasItems] = useState<boolean | null>(null);

  useEffect(() => {
    const d = localStorage.getItem('mutari-onboarding-dismissed');
    if (d === 'true') setDismissed(true);
  }, []);

  useEffect(() => {
    getMyItems({})
      .then(res => setHasItems((res.items?.length ?? 0) > 0))
      .catch(() => setHasItems(false));
  }, []);

  if (dismissed || hasItems === null) return null;

  const profileDone = !!(profile?.firstName || profile?.image);
  const addressDone = !!(profile?.address && profile?.city);
  const uploadDone = hasItems;

  const steps: Step[] = [
    {
      id: 'profile',
      icon: <UserCircle className="w-5 h-5" />,
      title: 'Lengkapi profil',
      desc: 'Tambah foto & nama agar dipercaya',
      action: 'Atur Profil',
      route: '/edit-profile',
      done: profileDone,
    },
    {
      id: 'upload',
      icon: <Camera className="w-5 h-5" />,
      title: 'Upload barang pertama',
      desc: 'Foto & deskripsi barangmu',
      action: 'Upload Sekarang',
      route: '/upload',
      done: uploadDone,
    },
    {
      id: 'explore',
      icon: <Search className="w-5 h-5" />,
      title: 'Jelajahi barang',
      desc: 'Cari barang yang kamu inginkan',
      action: 'Mulai Cari',
      route: '/search',
      done: false, // always available
    },
  ];

  const completedCount = steps.filter(s => s.done).length;
  const allDone = completedCount >= 2; // profile + upload done = hide card

  if (allDone) return null;

  const handleDismiss = () => {
    setDismissed(true);
    localStorage.setItem('mutari-onboarding-dismissed', 'true');
  };

  return (
    <AnimatePresence>
      {!dismissed && (
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, height: 0, marginTop: 0, marginBottom: 0 }}
          className="mx-4 mt-2 mb-1"
        >
          <div className="relative overflow-hidden rounded-2xl bg-card shadow-sm">
            {/* Decorative */}
