import { useState, useEffect, useCallback, useRef } from 'react';
import { X, ChevronRight, ChevronLeft, PartyPopper } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

const STORAGE_KEY = 'mutari_onboarding_done';

interface TourStep {
  target: string; // data-tour attribute value
  title: string;
  description: string;
  icon: string;
}

const STEPS: TourStep[] = [
  {
    target: 'tour-upload',
    title: 'Upload Barang',
    description: 'Foto & upload barang yang mau kamu tukarkan. Tambahkan deskripsi dan kondisi barang agar lebih menarik!',
