    description: 'Gabung komunitas barter berdasarkan minat. Temukan orang-orang dengan hobi yang sama!',
    icon: '👥',
  },
  {
    target: 'tour-challenge',
    title: 'Tantangan & Misi',
    description: 'Ikuti tantangan seru dan selesaikan misi mingguan untuk dapat poin bonus & badge eksklusif!',
    icon: '🏆',
  },
];

function SpotlightOverlay({ rect }: { rect: DOMRect | null }) {
  if (!rect) return <div className="fixed inset-0 bg-black/60 z-[998]" />;

  const padding = 8;
  const r = 14;
  const x = rect.left - padding;
  const y = rect.top - padding;
  const w = rect.width + padding * 2;
  const h = rect.height + padding * 2;

  return (
    <svg className="fixed inset-0 w-full h-full z-[998]" style={{ pointerEvents: 'none' }}>
      <defs>
        <mask id="tour-mask">
          <rect x="0" y="0" width="100%" height="100%" fill="white" />
          <rect x={x} y={y} width={w} height={h} rx={r} ry={r} fill="black" />
        </mask>
      </defs>
      <rect x="0" y="0" width="100%" height="100%" fill="rgba(0,0,0,0.6)" mask="url(#tour-mask)" />
      {/* Glow ring around spotlight */}
      <rect
        x={x - 2} y={y - 2} width={w + 4} height={h + 4}
        rx={r + 2} ry={r + 2}
        fill="none" stroke="hsl(var(--primary))" strokeWidth="2" opacity="0.6"
      />
    </svg>
  );
}

export default function OnboardingTour() {
  const [active, setActive] = useState(false);
  const [step, setStep] = useState(0);
  const [targetRect, setTargetRect] = useState<DOMRect | null>(null);
  const [done, setDone] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout>>();

  // Check if onboarding already done
  useEffect(() => {
    const v = localStorage.getItem(STORAGE_KEY);
    if (v) {
      setDone(true);
    } else {
      // Delay start so page elements render
      timerRef.current = setTimeout(() => setActive(true), 1200);
    }
    return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, []);

  const measureTarget = useCallback((stepIdx: number) => {
    const s = STEPS[stepIdx];
    if (!s) return;
    const el = document.querySelector(`[data-tour="${s.target}"]`);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      // Delay measurement to account for scroll
      setTimeout(() => {
        setTargetRect(el.getBoundingClientRect());
      }, 350);
    } else {
      setTargetRect(null);
    }
  }, []);

  useEffect(() => {
    if (!active) return;
    measureTarget(step);
  }, [active, step, measureTarget]);

  // Re-measure on scroll/resize
  useEffect(() => {
    if (!active) return;
    const handler = () => measureTarget(step);
    window.addEventListener('resize', handler);
    window.addEventListener('scroll', handler, true);
    return () => {
      window.removeEventListener('resize', handler);
      window.removeEventListener('scroll', handler, true);
    };
  }, [active, step, measureTarget]);

  const finish = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, '1');
    setActive(false);
    setDone(true);
  }, []);

  const next = useCallback(() => {
    if (step < STEPS.length - 1) setStep(s => s + 1);
    else finish();
  }, [step, finish]);

  const prev = useCallback(() => {
    if (step > 0) setStep(s => s - 1);
  }, [step]);

  if (done || !active) return null;

  const currentStep = STEPS[step];
  const isLast = step === STEPS.length - 1;

  // Tooltip is now always a centered bottom-sheet style on mobile, or centered card on desktop
  // No more absolute positioning relative to target — avoids all clipping issues

  return (
    <>
      {/* Clickable overlay to block interactions */}
      <div className="fixed inset-0 z-[997]" onClick={(e) => e.stopPropagation()} />

      <SpotlightOverlay rect={targetRect} />

      <AnimatePresence mode="wait">
        <motion.div
          key={step}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{ duration: 0.25 }}
          className="fixed z-[999] inset-x-4 bottom-[calc(5rem+env(safe-area-inset-bottom))] lg:bottom-auto lg:top-1/2 lg:left-1/2 lg:right-auto lg:w-[380px] lg:-translate-x-1/2 lg:-translate-y-1/2"
        >
          <div className="bg-card rounded-2xl shadow-2xl border border-border overflow-hidden">
            {/* Header */}
            <div className="bg-gradient-to-r from-primary/15 to-primary/5 px-4 pt-4 pb-3 flex items-start justify-between">
              <div className="flex items-center gap-2.5">
                <span className="text-2xl">{currentStep.icon}</span>
                <div>
                  <p className="text-xs text-muted-foreground font-medium">
                    Langkah {step + 1} dari {STEPS.length}
                  </p>
                  <h3 className="text-sm font-bold text-foreground">{currentStep.title}</h3>
                </div>
              </div>
              <button
                onClick={finish}
                className="w-7 h-7 rounded-full bg-muted/80 flex items-center justify-center text-muted-foreground hover:bg-muted transition-colors flex-shrink-0"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>

            {/* Body */}
            <div className="px-4 py-3">
              <p className="text-[13px] text-muted-foreground leading-relaxed">
                {currentStep.description}
              </p>
            </div>

            {/* Progress dots */}
            <div className="flex justify-center gap-1.5 pb-2">
              {STEPS.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full transition-all duration-300 ${
                    i === step ? 'w-5 bg-primary' : i < step ? 'w-1.5 bg-primary/40' : 'w-1.5 bg-muted-foreground/20'
                  }`}
                />
              ))}
            </div>

            {/* Actions */}
            <div className="px-4 pb-4 flex items-center gap-2">
              {step > 0 && (
                <button
                  onClick={prev}
                  className="flex items-center gap-1 px-3 py-2 rounded-xl text-xs font-semibold text-muted-foreground hover:bg-muted transition-colors"
                >
                  <ChevronLeft className="w-3.5 h-3.5" />
                  Kembali
                </button>
              )}
              {step === 0 && (
                <button
                  onClick={finish}
                  className="px-3 py-2 rounded-xl text-xs font-semibold text-muted-foreground hover:bg-muted transition-colors"
                >
                  Lewati
                </button>
              )}
              <button
                onClick={next}
                className="flex-1 flex items-center justify-center gap-1.5 px-4 py-2.5 rounded-xl bg-primary text-primary-foreground text-xs font-bold shadow-md shadow-primary/20 hover:opacity-90 transition-opacity"
              >
                {isLast ? (
                  <>
                    <PartyPopper className="w-4 h-4" />
                    Mulai Barter!
                  </>
                ) : (
                  <>
                    Lanjut
                    <ChevronRight className="w-3.5 h-3.5" />
                  </>
                )}
              </button>
            </div>
          </div>
        </motion.div>
      </AnimatePresence>
    </>
  );
}

