import { MutariInline } from './MutariSpinner';
import { useState, useRef, useEffect } from 'react';
import { Smartphone, ShieldCheck, ArrowLeft, RefreshCw } from 'lucide-react';
import { sendPhoneOtp, verifyPhoneOtp } from 'zitejs/api';
import { toast } from 'sonner';

interface Props {
  phone?: string;
  onVerified: () => void;
  onBack: () => void;
}

export default function PhoneVerification({ phone: initialPhone, onVerified, onBack }: Props) {
  const [step, setStep] = useState<'input' | 'otp'>('input');
  const [phone, setPhone] = useState(initialPhone || '');
  const [sending, setSending] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [countdown, setCountdown] = useState(0);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  // Countdown timer for resend
  useEffect(() => {
    if (countdown <= 0) return;
    const t = setTimeout(() => setCountdown(c => c - 1), 1000);
    return () => clearTimeout(t);
  }, [countdown]);

  const handleSendOtp = async () => {
    const cleaned = phone.replace(/\s/g, '');
    if (cleaned.length < 8) {
      toast.error('Masukkan nomor HP yang valid');
      return;
    }
    setSending(true);
    try {
      const res = await sendPhoneOtp({ phone: cleaned });
      toast.success(res.message);
      setStep('otp');
      setCountdown(60);
      setTimeout(() => inputRefs.current[0]?.focus(), 100);
    } catch {
      toast.error('Gagal mengirim kode');
    }
    setSending(false);
  };

  const handleOtpChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;
    const newOtp = [...otp];
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);

    // Auto-advance
    if (value && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }

    // Auto-submit when all filled
    if (newOtp.every(d => d !== '') && value) {
      submitOtp(newOtp.join(''));
    }
  };

  const handleKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const submitOtp = async (code: string) => {
    setVerifying(true);
    try {
      const res = await verifyPhoneOtp({ code });
      if (res.verified) {
        toast.success(res.message);
        onVerified();
      } else {
        toast.error(res.message);
        setOtp(['', '', '', '', '', '']);
        inputRefs.current[0]?.focus();
      }
    } catch {
      toast.error('Gagal verifikasi');
      setOtp(['', '', '', '', '', '']);
    }
    setVerifying(false);
  };

  const handleResend = () => {
    setOtp(['', '', '', '', '', '']);
    handleSendOtp();
  };

  return (
    <div className="min-h-screen bg-background flex items-center justify-center px-6">
      <div className="max-w-[380px] w-full">
        {/* Back */}
        <button onClick={onBack} className="flex items-center gap-1.5 text-sm text-muted-foreground mb-6">
          <ArrowLeft className="w-4 h-4" /> Kembali
        </button>

        {/* Icon */}
        <div className="text-center mb-8">
          <div className="mx-auto w-20 h-20 rounded-2xl bg-primary/10 flex items-center justify-center mb-4">
            {step === 'input' ? (
              <Smartphone className="w-10 h-10 text-primary" />
            ) : (
              <ShieldCheck className="w-10 h-10 text-primary" />
            )}
          </div>
          <h1 className="text-xl font-bold text-foreground">
            {step === 'input' ? 'Verifikasi Nomor HP' : 'Masukkan Kode OTP'}
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            {step === 'input'
              ? 'Nomor HP wajib diverifikasi sebelum posting barang untuk keamanan transaksi barter.'
