import { Sparkles, MapPin, CheckCircle, Crown, Shield, Star, GraduationCap, Gem } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { getBadge, BADGES } from '../lib/badges';

type ItemType = GetItemsOutputType['items'][0];

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function MatchBadge({ percent }: { percent: number }) {
  return (
    <div className="bg-card/90 backdrop-blur-sm rounded-full px-2.5 py-1 flex items-center gap-1 text-[11px] font-bold shadow-sm">
      <Sparkles className="w-3.5 h-3.5 text-primary" /> {percent}%
    </div>
  );
}

function estimateMatch(item: ItemType): number {
  let score = 70;
  if (item.photos && item.photos.length > 0) score += 5;
  if (item.photos && item.photos.length > 2) score += 5;
  if (item.location) score += 3;
  if (item.description && item.description.length > 50) score += 4;
  if (item.viewsCount > 5) score += 3;
  if (item.likesCount > 2) score += 5;
  if (item.condition === 'Baru' || item.condition === 'Seperti Baru') score += 5;
  return Math.min(99, score);
}

function getCardStyle(badgeId: string) {
  switch (badgeId) {
    case 'elite':
      return { border: 'border-2 border-rose-400 ring-2 ring-rose-200/50', glow: 'shadow-[0_0_14px_3px_rgba(244,63,94,0.25)]', label: { text: 'Elite', icon: Gem, bg: 'bg-gradient-to-r from-rose-500 via-pink-500 to-fuchsia-500 text-white' } };
    case 'mentor':
      return { border: 'border-2 border-teal-400 ring-2 ring-teal-200/50', glow: 'shadow-[0_0_12px_2px_rgba(20,184,166,0.25)]', label: { text: 'Mentor', icon: GraduationCap, bg: 'bg-gradient-to-r from-teal-500 to-cyan-500 text-white' } };
    case 'legenda':
      return { border: 'border-2 border-amber-400 ring-2 ring-amber-200/50', glow: 'shadow-[0_0_12px_2px_rgba(250,204,21,0.25)]', label: { text: 'Legenda', icon: Crown, bg: 'bg-gradient-to-r from-amber-500 to-yellow-400 text-white' } };
    case 'profesional':
      return { border: 'border-2 border-purple-400 ring-2 ring-purple-200/40', glow: 'shadow-[0_0_10px_2px_rgba(168,85,247,0.2)]', label: { text: 'Pro', icon: Shield, bg: 'bg-gradient-to-r from-purple-500 to-indigo-500 text-white' } };
    case 'terpercaya':
      return { border: 'border-2 border-amber-300 ring-1 ring-amber-100/40', glow: 'shadow-[0_0_8px_1px_rgba(251,191,36,0.15)]', label: { text: 'Trusted', icon: Star, bg: 'bg-gradient-to-r from-amber-400 to-orange-400 text-white' } };
    default:
      return null;
  }
}

function SmallCard({ item, onClick }: { item: ItemType; onClick: () => void }) {
