          {/* Decorative circles */}
          <div className="absolute -top-4 -right-4 w-20 h-20 rounded-full bg-white/10" />
          <div className="absolute -bottom-6 -left-6 w-24 h-24 rounded-full bg-white/5" />

          {/* Close button */}
          <button
            onClick={dismiss}
            className="absolute top-2.5 right-2.5 w-6 h-6 rounded-full bg-white/20 flex items-center justify-center z-10 active:bg-white/30"
          >
            <X className="w-3.5 h-3.5 text-white" />
          </button>

          <div className="relative p-4 flex items-center gap-3">
            {/* Icon area */}
            <div className="flex-shrink-0 w-12 h-12 rounded-xl bg-white/15 flex items-center justify-center backdrop-blur-sm">
              <Camera className="w-6 h-6 text-white" />
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0 pr-4">
              <div className="flex items-center gap-1.5 mb-0.5">
                <Sparkles className="w-3.5 h-3.5 text-yellow-300" />
                <span className="text-[10px] font-semibold text-yellow-300 uppercase tracking-wide">Mulai Barter</span>
              </div>
              <p className="text-white font-bold text-sm leading-tight">
                Upload barang pertamamu!
              </p>
              <p className="text-white/70 text-[11px] mt-0.5 leading-snug">
                Foto & upload — AI bantu analisis nilainya ✨
              </p>
            </div>
          </div>

          {/* CTA button */}
          <div className="px-4 pb-3.5">
            <button
              onClick={() => { dismiss(); navigate('/upload'); }}
              className="w-full py-2.5 rounded-xl bg-white text-primary text-sm font-bold flex items-center justify-center gap-2 active:scale-[0.98] transition-transform"
            >
              Upload Sekarang
              <ArrowRight className="w-4 h-4" />
            </button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

