import { useState, useRef, useCallback } from 'react';
import { motion, useMotionValue, useTransform, animate } from 'framer-motion';
import { ArrowDown, Loader2 } from 'lucide-react';

interface PullToRefreshProps {
  onRefresh: () => Promise<void>;
  children: React.ReactNode;
}

const THRESHOLD = 80;
const MAX_PULL = 120;

export default function PullToRefresh({ onRefresh, children }: PullToRefreshProps) {
  const [refreshing, setRefreshing] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const startY = useRef(0);
  const pulling = useRef(false);
  const y = useMotionValue(0);

  const indicatorOpacity = useTransform(y, [0, 40, THRESHOLD], [0, 0.6, 1]);
  const indicatorScale = useTransform(y, [0, THRESHOLD], [0.5, 1]);
  const rotate = useTransform(y, [0, THRESHOLD], [0, 180]);

  const isAtTop = useCallback(() => {
    const el = containerRef.current;
    if (!el) return false;
    // Walk up to find the scroll parent
    let node: HTMLElement | null = el;
    while (node) {
      if (node.scrollTop > 5) return false;
      node = node.parentElement;
    }
    return window.scrollY <= 5;
  }, []);

  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    if (refreshing) return;
    if (isAtTop()) {
      startY.current = e.touches[0].clientY;
      pulling.current = true;
    }
  }, [refreshing, isAtTop]);

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (!pulling.current || refreshing) return;
    const diff = e.touches[0].clientY - startY.current;
    if (diff < 0) {
      y.set(0);
      return;
    }
    // Apply resistance
    const dampened = Math.min(diff * 0.45, MAX_PULL);
    y.set(dampened);
  }, [refreshing, y]);

  const handleTouchEnd = useCallback(async () => {
    if (!pulling.current) return;
    pulling.current = false;

    if (y.get() >= THRESHOLD && !refreshing) {
      // Snap to threshold and refresh
      animate(y, 50, { type: 'spring', stiffness: 300, damping: 30 });
      setRefreshing(true);
      try {
        await onRefresh();
      } finally {
        setRefreshing(false);
        animate(y, 0, { type: 'spring', stiffness: 300, damping: 30 });
      }
    } else {
      animate(y, 0, { type: 'spring', stiffness: 400, damping: 30 });
    }
  }, [y, refreshing, onRefresh]);

  return (
    <div
      ref={containerRef}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      className="relative"
    >
      {/* Pull indicator */}
      <motion.div
        style={{ opacity: indicatorOpacity, scale: indicatorScale }}
        className="absolute left-1/2 -translate-x-1/2 top-0 z-30 pointer-events-none"
      >
        <motion.div style={{ y }} className="flex flex-col items-center pt-2 pb-1">
          <div className="w-10 h-10 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center shadow-lg backdrop-blur-sm">
            {refreshing ? (
              <Loader2 className="w-5 h-5 text-primary animate-spin" />
            ) : (
              <motion.div style={{ rotate }}>
                <ArrowDown className="w-5 h-5 text-primary" />
              </motion.div>
            )}
          </div>
          <span className="text-[10px] font-semibold text-primary mt-1">
            {refreshing ? 'Memuat...' : 'Tarik untuk refresh'}
          </span>
        </motion.div>
      </motion.div>

      {/* Content */}
      <motion.div style={{ y }}>
        {children}
      </motion.div>
    </div>
  );
}

