import { Clock, MapPin, Eye, Heart, CheckCircle, MessageCircle, Crown, Shield, Star, GraduationCap, Gem, Rocket, Sparkles } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getItems, GetItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { getBadge, BADGES } from '../lib/badges';
import { useRefresh } from '../context/RefreshContext';

type ItemType = GetItemsOutputType['items'][0];

function formatCurrency(val: number | null): string {
  if (!val) return '';
  return 'Rp' + val.toLocaleString('id-ID');
}

function priceRange(item: ItemType): string {
  const min = formatCurrency(item.estimatedValueMin);
  const max = formatCurrency(item.estimatedValueMax);
  if (min && max && min !== max) return `${min} – ${max}`;
  return min || max || '-';
}

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

function getCardStyle(badgeId: string) {
  switch (badgeId) {
    case 'elite':
      return { border: 'border-2 border-rose-400 ring-2 ring-rose-200/50', glow: 'shadow-[0_0_14px_3px_rgba(244,63,94,0.25)]', label: { text: 'Elite', icon: Gem, bg: 'bg-gradient-to-r from-rose-500 via-pink-500 to-fuchsia-500 text-white' } };
    case 'mentor':
      return { border: 'border-2 border-teal-400 ring-2 ring-teal-200/50', glow: 'shadow-[0_0_12px_2px_rgba(20,184,166,0.25)]', label: { text: 'Mentor', icon: GraduationCap, bg: 'bg-gradient-to-r from-teal-500 to-cyan-500 text-white' } };
    case 'legenda':
      return { border: 'border-2 border-amber-400 ring-2 ring-amber-200/50', glow: 'shadow-[0_0_12px_2px_rgba(250,204,21,0.25)]', label: { text: 'Legenda', icon: Crown, bg: 'bg-gradient-to-r from-amber-500 to-yellow-400 text-white' } };
    case 'profesional':
      return { border: 'border-2 border-purple-400 ring-2 ring-purple-200/40', glow: 'shadow-[0_0_10px_2px_rgba(168,85,247,0.2)]', label: { text: 'Pro', icon: Shield, bg: 'bg-gradient-to-r from-purple-500 to-indigo-500 text-white' } };
    case 'terpercaya':
      return { border: 'border-2 border-amber-300 ring-1 ring-amber-100/40', glow: 'shadow-[0_0_8px_1px_rgba(251,191,36,0.15)]', label: { text: 'Trusted', icon: Star, bg: 'bg-gradient-to-r from-amber-400 to-orange-400 text-white' } };
    default:
      return null;
  }
}

function ItemCard({ item, onClick, overrideTier }: { item: ItemType; onClick: () => void; overrideTier?: string | null }) {
  const imgUrl = item.photos?.[0]?.url || PLACEHOLDER_IMG;
  const effectiveBadgeId = overrideTier || 'pemula';
  const style = getCardStyle(effectiveBadgeId);
  const isPremium = !!style;
  const isBoosted = 'isBoosted' in item && (item as any).isBoosted;
  const isHighlighted = 'isHighlighted' in item && (item as any).isHighlighted;
  const ownerAwardCount = (item as any).ownerAwardCount || 0;

  return (
    <div
      onClick={onClick}
      className={`rounded-2xl overflow-hidden bg-card cursor-pointer transition-all duration-200 ${
        isHighlighted
          ? 'border-2 border-amber-400 ring-2 ring-amber-200/50 shadow-[0_0_12px_2px_rgba(250,204,21,0.3)] hover:scale-[1.02]'
          : isPremium
          ? `${style.border} ${style.glow} hover:scale-[1.02]`
          : 'border border-border shadow-sm hover:shadow-md'
      }`}
    >
      <div className="relative">
        <img src={imgUrl} alt={item.title} className="w-full h-36 sm:h-48 object-cover" />
        <div className="absolute top-2 left-2 bg-black/50 backdrop-blur-sm rounded-full px-2.5 py-0.5 flex items-center gap-1 text-[10px] text-white font-medium">
          <Clock className="w-3 h-3" /> {item.condition || 'Baru'}
        </div>
        {isBoosted && (
          <div className="absolute top-2 right-2 bg-sky-500 text-white px-2 py-0.5 rounded-full flex items-center gap-1 text-[9px] font-bold shadow-sm">
            <Rocket className="w-3 h-3" /> Boosted
          </div>
        )}
        {!isBoosted && isHighlighted && (
          <div className="absolute top-2 right-2 bg-gradient-to-r from-amber-500 to-yellow-400 text-white px-2 py-0.5 rounded-full flex items-center gap-1 text-[9px] font-bold shadow-sm">
            <Sparkles className="w-3 h-3" /> Highlight
          </div>
        )}
        {!isBoosted && !isHighlighted && style?.label && (
          <div className={`absolute top-2 right-0 ${style.label.bg} px-2 py-0.5 rounded-l-full flex items-center gap-1 text-[9px] font-bold shadow-sm`}>
            <style.label.icon className="w-3 h-3" />
            {style.label.text}
          </div>
        )}
      </div>
      <div className="p-3">
        <p className="text-sm font-bold truncate">{item.title}</p>
        <p className="text-xs text-primary font-semibold mt-1">{priceRange(item)}</p>
        {item.location && (
          <p className="text-[10px] text-muted-foreground mt-1.5 flex items-center gap-0.5">
            <MapPin className="w-3 h-3 flex-shrink-0" /> {item.location}
          </p>
        )}
        <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-1">
          <span className="flex items-center gap-0.5"><Eye className="w-3 h-3" /> {item.viewsCount}</span>
          <span className="flex items-center gap-0.5"><Heart className="w-3 h-3" /> {item.likesCount}</span>
          <span className="flex items-center gap-0.5"><MessageCircle className="w-3 h-3" /> {item.commentsCount}</span>
        </div>
        <div className="flex items-center gap-1.5 mt-2.5 pt-2.5 border-t border-border">
          {item.ownerImage ? (
            <img src={item.ownerImage} alt={item.ownerName} className="w-6 h-6 rounded-full object-cover flex-shrink-0 border border-border" />
          ) : (
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground text-[9px] flex items-center justify-center font-bold flex-shrink-0">
              {(item.ownerName || 'P').charAt(0).toUpperCase()}
            </div>
          )}
          <span className="text-[11px] font-semibold truncate flex-1">{item.ownerName || 'Pengguna'}</span>
          {ownerAwardCount > 0 && (
            <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded-full bg-amber-50 border border-amber-200 text-[8px] font-bold text-amber-700 flex-shrink-0">
              🏆 {ownerAwardCount}
            </span>
          )}
          {isPremium ? (
            <span className="text-[9px] font-bold">{BADGES.find(b => b.id === effectiveBadgeId)?.emoji || '⭐'}</span>
          ) : (
            <CheckCircle className="w-3.5 h-3.5 text-primary flex-shrink-0" />
          )}
          <span className="text-[9px] text-emerald-600 font-medium flex-shrink-0">● Tersedia</span>
        </div>
      </div>
    </div>
  );
}

export default function Rekomendasi() {
  const navigate = useNavigate();
  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);
  const { tick } = useRefresh();

  useEffect(() => {
    getItems({ limit: 6 }).then(res => {
      setItems(res.items);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [tick]);

  return (
    <div className="px-4 py-4">
      <div className="flex items-center justify-between mb-4">
        <p className="font-bold text-[15px] text-foreground">Rekomendasi untukmu</p>
        <button onClick={() => navigate('/search')} className="text-xs text-primary font-semibold">Lihat Semua</button>
      </div>
      {loading ? (
        <div className="grid grid-cols-2 gap-3 mutari-item-grid">
          {[0, 1].map(i => (
            <div key={i} className="rounded-2xl overflow-hidden border border-border bg-card">
              <Skeleton className="w-full h-36" />
              <div className="p-3 space-y-2">
                <Skeleton className="h-4 w-3/4" />
                <Skeleton className="h-3 w-1/2" />
              </div>
            </div>
          ))}
        </div>
      ) : items.length === 0 ? (
        <p className="text-sm text-muted-foreground text-center py-8">Belum ada barang tersedia</p>
      ) : (
        <div className="grid grid-cols-2 gap-3 mutari-item-grid">
          {items.map((item) => {
            const ownerBadge = getBadge(item.ownerPoints || 0);
            const overrideTier = ownerBadge.id !== 'pemula' && ownerBadge.id !== 'aktif' ? ownerBadge.id : null;
            return (
              <ItemCard key={item.id} item={item} overrideTier={overrideTier} onClick={() => navigate(`/item/${item.id}`)} />
            );
          })}
        </div>
      )}
    </div>
  );
}

