                <div className="w-full h-full flex items-center justify-center bg-primary/10 text-primary font-bold text-lg">
                  {group.authorName[0]?.toUpperCase()}
                </div>
              )}
            </div>
          </div>
        </div>
        {storyCount > 1 && (
          <div className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] px-1 rounded-full bg-primary text-primary-foreground flex items-center justify-center shadow-md border-2 border-background">
            <span className="text-[9px] font-bold">{storyCount}</span>
          </div>
        )}
      </div>
      <span className="text-[10px] text-foreground truncate w-full text-center leading-tight">
        {group.isMe ? 'Kamu' : group.authorName.split(' ')[0]}
      </span>
    </button>
  );
}

function AddStoryButton({ userImage, onAdd }: { userImage: string | null; onAdd: () => void }) {
  return (
    <button onClick={onAdd} className="flex-shrink-0 flex flex-col items-center gap-1 w-[68px]">
      <div className="relative">
        <div className="w-[57px] h-[57px] rounded-full overflow-hidden bg-muted border-2 border-dashed border-primary/30">
          {userImage ? (
            <img src={userImage} alt="" className="w-full h-full object-cover opacity-60" />
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-primary/5" />
          )}
        </div>
        <div className="absolute -bottom-0.5 -right-0.5 w-5 h-5 rounded-full bg-primary text-primary-foreground flex items-center justify-center shadow-md">
          <Plus className="w-3 h-3" strokeWidth={3} />
        </div>
      </div>
      <span className="text-[10px] text-primary font-semibold">Story</span>
    </button>
  );
}

export default function StoriesBar() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [groups, setGroups] = useState<GroupedStory[]>([]);
  const [loading, setLoading] = useState(true);
  const [hasMyStory, setHasMyStory] = useState(false);

  useEffect(() => {
    getStories({})
      .then(d => {
        // Group stories by author
        const map = new Map<string, GroupedStory>();
        for (const s of d.stories) {
          const existing = map.get(s.authorId);
          if (existing) {
            existing.stories.push(s);
            if (!s.viewed) existing.hasUnviewed = true;
          } else {
            map.set(s.authorId, {
              authorId: s.authorId,
              authorName: s.authorName,
              authorImage: s.authorImage,
              stories: [s],
              isMe: s.authorId === user?.id,
              hasUnviewed: !s.viewed,
            });
          }
        }
        // Sort: my story first, then by recency
        const arr = Array.from(map.values());
        arr.sort((a, b) => {
          if (a.isMe) return -1;
          if (b.isMe) return 1;
          return 0;
        });
        setGroups(arr);
        setHasMyStory(!!d.myStory);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [user?.id]);

  if (loading) {
    return (
      <div className="px-4 py-3">
        <div className="flex gap-3 overflow-hidden">
          {[0,1,2,3,4,5].map(i => (
            <div key={i} className="flex-shrink-0 flex flex-col items-center gap-1">
              <div className="w-[57px] h-[57px] rounded-full bg-muted animate-pulse" />
              <div className="w-10 h-2 rounded bg-muted animate-pulse" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="px-4 py-2">
      <div className="flex gap-2.5 overflow-x-auto pb-1 scrollbar-hide">
        {/* Add story button — always show if user has no story */}
        {!hasMyStory && (
          <AddStoryButton
            userImage={user?.image || null}
            onAdd={() => navigate('/create-story')}
          />
        )}

        {/* Story groups */}
        {groups.map(g => (
          <StoryAvatar
            key={g.authorId}
            group={g}
            onClick={() => {
              if (g.isMe && !g.stories.length) {
                navigate('/create-story');
              } else {
                navigate(`/story/${g.authorId}`, { state: { stories: g.stories } });
              }
            }}
          />
        ))}

        {/* If no stories at all, show placeholder */}
        {groups.length === 0 && hasMyStory && null}
        {groups.length === 0 && !hasMyStory && (
          <div className="flex items-center px-3">
            <p className="text-xs text-muted-foreground">Belum ada story. Jadilah yang pertama! 🎉</p>
          </div>
        )}
      </div>
    </div>
  );
}

