import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { TrendingUp, Eye, Heart, Bookmark, Flame, ChevronRight, Crown, Shield, Star, GraduationCap, Gem } from 'lucide-react';
import { getTrending, GetTrendingOutputType } from 'zitejs/api';
import { getBadge, BADGES } from '../lib/badges';
import { useRefresh } from '../context/RefreshContext';

type TrendingItem = GetTrendingOutputType['trending'][0];
type TopCategory = GetTrendingOutputType['topCategories'][0];

function ScoreBadge({ score }: { score: number }) {
  const heat = score >= 50 ? 'bg-red-500/15 text-red-600' : score >= 20 ? 'bg-orange-500/15 text-orange-600' : 'bg-amber-500/15 text-amber-600';
  return (
    <span className={`inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded-full text-[9px] font-bold ${heat}`}>
      <Flame className="w-2.5 h-2.5" /> {score}
    </span>
  );
}

function getCardStyle(badgeId: string) {
  switch (badgeId) {
    case 'elite':
      return { border: 'ring-2 ring-rose-400/60', glow: 'shadow-[0_0_10px_2px_rgba(244,63,94,0.2)]', label: { text: 'Elite', icon: Gem, bg: 'bg-gradient-to-r from-rose-500 via-pink-500 to-fuchsia-500 text-white' } };
    case 'mentor':
      return { border: 'ring-2 ring-teal-400/60', glow: 'shadow-[0_0_8px_2px_rgba(20,184,166,0.2)]', label: { text: 'Mentor', icon: GraduationCap, bg: 'bg-gradient-to-r from-teal-500 to-cyan-500 text-white' } };
    case 'legenda':
      return { border: 'ring-2 ring-amber-400/60', glow: 'shadow-[0_0_8px_2px_rgba(250,204,21,0.2)]', label: { text: 'Legenda', icon: Crown, bg: 'bg-gradient-to-r from-amber-500 to-yellow-400 text-white' } };
    case 'profesional':
      return { border: 'ring-2 ring-purple-400/50', glow: 'shadow-[0_0_6px_2px_rgba(168,85,247,0.15)]', label: { text: 'Pro', icon: Shield, bg: 'bg-gradient-to-r from-purple-500 to-indigo-500 text-white' } };
    case 'terpercaya':
      return { border: 'ring-1.5 ring-amber-300/50', glow: 'shadow-[0_0_5px_1px_rgba(251,191,36,0.12)]', label: { text: 'Trusted', icon: Star, bg: 'bg-gradient-to-r from-amber-400 to-orange-400 text-white' } };
    default:
      return null;
  }
}

function TrendingCard({ item, rank, onClick }: { item: TrendingItem; rank: number; onClick: () => void }) {
  const badge = getBadge(item.ownerPoints);
  const effectiveBadgeId = item.ownerBadgeId && item.ownerBadgeId !== 'pemula' ? item.ownerBadgeId : badge.id;
  const style = getCardStyle(effectiveBadgeId);
  const isPremium = !!style;

  return (
    <button onClick={onClick} className="flex-shrink-0 w-[140px] group">
      <div className={`relative rounded-2xl overflow-hidden bg-muted aspect-[4/5] mb-2 transition-all duration-200 ${
        isPremium ? `${style.border} ${style.glow} group-hover:scale-[1.03]` : ''
      }`}>
        {item.photo ? (
          <img src={item.photo} alt={item.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" loading="lazy" />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-3xl">📦</div>
        )}
        {/* Rank badge */}
        <div className={`absolute top-2 left-2 w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold text-white shadow ${
          rank === 1 ? 'bg-gradient-to-br from-amber-400 to-amber-600' :
          rank === 2 ? 'bg-gradient-to-br from-gray-300 to-gray-500' :
          rank === 3 ? 'bg-gradient-to-br from-amber-600 to-amber-800' :
          'bg-primary/80'
        }`}>
          {rank}
        </div>
        {/* Score */}
        <div className="absolute top-2 right-2">
          <ScoreBadge score={item.score} />
        </div>
        {/* Premium label */}
        {style?.label && (
          <div className={`absolute bottom-10 right-0 ${style.label.bg} px-1.5 py-0.5 rounded-l-full flex items-center gap-0.5 text-[7px] font-bold shadow-sm`}>
            <style.label.icon className="w-2.5 h-2.5" />
            {style.label.text}
          </div>
        )}
        {/* Bottom gradient overlay with stats */}
        <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/70 to-transparent p-2 pt-6">
          <div className="flex items-center gap-2 text-white/90 text-[9px]">
            <span className="flex items-center gap-0.5"><Eye className="w-2.5 h-2.5" />{item.views}</span>
            <span className="flex items-center gap-0.5"><Heart className="w-2.5 h-2.5" />{item.likes}</span>
            <span className="flex items-center gap-0.5"><Bookmark className="w-2.5 h-2.5" />{item.wishlistCount}</span>
          </div>
        </div>
      </div>
      <p className="text-xs font-semibold text-foreground truncate text-left leading-tight">{item.title}</p>
      {/* Owner row with badge */}
      <div className="flex items-center gap-1 mt-0.5">
        {item.ownerImage ? (
          <img src={item.ownerImage} alt={item.ownerName} className="w-3.5 h-3.5 rounded-full object-cover" />
        ) : (
          <div className="w-3.5 h-3.5 rounded-full bg-primary text-primary-foreground text-[6px] flex items-center justify-center font-bold">
            {(item.ownerName || 'P').charAt(0).toUpperCase()}
          </div>
        )}
        <span className="text-[10px] text-muted-foreground truncate">{item.ownerName}</span>
        {isPremium && <span className="text-[9px]">{BADGES.find(b => b.id === effectiveBadgeId)?.emoji || badge.emoji}</span>}
      </div>
      {item.category && (
        <p className="text-[10px] text-muted-foreground truncate text-left mt-0.5">{item.category}</p>
      )}
      {item.location && (
        <p className="text-[10px] text-muted-foreground truncate text-left">📍 {item.location}</p>
      )}
    </button>
  );
}

function TopCategoryChip({ cat }: { cat: TopCategory }) {
  return (
    <div className="flex-shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-primary/10 border border-primary/20">
      <span className="text-sm">{cat.icon}</span>
      <span className="text-[11px] font-semibold text-primary whitespace-nowrap">{cat.name}</span>
      <span className="text-[9px] text-primary/60 font-medium">{cat.count}</span>
    </div>
  );
}

export default function TrendingItems() {
  const navigate = useNavigate();
  const [trending, setTrending] = useState<TrendingItem[]>([]);
  const [topCategories, setTopCategories] = useState<TopCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const { tick } = useRefresh();

  useEffect(() => {
    getTrending({})
      .then(d => {
        setTrending(d.trending);
        setTopCategories(d.topCategories);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [tick]);

  if (loading) {
    return (
      <div className="px-4 py-4">
        <div className="flex items-center gap-2 mb-3">
          <TrendingUp className="w-4 h-4 text-red-500" />
          <h3 className="font-bold text-sm">Trending & Paling Dicari</h3>
        </div>
        <div className="flex gap-2 mb-3 overflow-hidden">
          {[0,1,2,3].map(i => (
            <div key={i} className="flex-shrink-0 w-24 h-7 rounded-full bg-muted animate-pulse" />
          ))}
        </div>
        <div className="flex gap-3 overflow-hidden">
          {[0,1,2].map(i => (
            <div key={i} className="flex-shrink-0 w-[140px]">
              <div className="aspect-[4/5] rounded-2xl bg-muted animate-pulse mb-2" />
              <div className="h-3 w-24 bg-muted rounded animate-pulse" />
              <div className="h-2 w-16 bg-muted rounded animate-pulse mt-1" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (trending.length === 0) return null;

  return (
    <div className="px-4 py-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-2.5">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-xl bg-red-500/10 flex items-center justify-center">
            <TrendingUp className="w-4 h-4 text-red-500" />
          </div>
          <div>
            <h3 className="font-bold text-sm leading-tight">Trending & Paling Dicari</h3>
            <p className="text-[10px] text-muted-foreground">Barang populer di area kamu</p>
          </div>
        </div>
        <button onClick={() => navigate('/search')} className="flex items-center gap-0.5 text-[11px] text-primary font-semibold">
          Semua <ChevronRight className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Top categories */}
      {topCategories.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide mb-1">
          {topCategories.map(cat => (
            <TopCategoryChip key={cat.name} cat={cat} />
          ))}
        </div>
      )}

      {/* Trending cards */}
      <div className="flex gap-3 overflow-x-auto pb-2 pt-1 scrollbar-hide">
        {trending.map((item, i) => (
          <TrendingCard
            key={item.id}
            item={item}
            rank={i + 1}
            onClick={() => navigate(`/item/${item.id}`)}
          />
        ))}
      </div>
    </div>
  );
}

