];

interface ChatInputProps {
  onSend: (content: string, type: 'Text' | 'Photo') => Promise<void>;
  sending: boolean;
  isTyping: boolean;
  onTypingChange: (typing: boolean) => void;
}

export default function ChatInput({ onSend, sending, isTyping, onTypingChange }: ChatInputProps) {
  const [text, setText] = useState('');
  const [showAttach, setShowAttach] = useState(false);
  const [showQuick, setShowQuick] = useState(true);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const cameraRef = useRef<HTMLInputElement>(null);
  const typingTimer = useRef<ReturnType<typeof setTimeout>>();
  const { upload } = useUpload();
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFocus = () => {
    setTimeout(() => {
      inputRef.current?.scrollIntoView({ block: 'end', behavior: 'smooth' });
    }, 300);
  };

  const handleTextChange = (val: string) => {
    setText(val);
    onTypingChange(true);
    clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(() => onTypingChange(false), 2000);
  };

  const handleSendText = async () => {
    if (!text.trim()) return;
    const content = text.trim();
    setText('');
    onTypingChange(false);
    setShowQuick(false);
    await onSend(content, 'Text');
  };

  const handleQuickReply = async (msg: string) => {
    setShowQuick(false);
    await onSend(msg, 'Text');
  };

  const handleFileSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setShowAttach(false);
    setUploading(true);
    try {
      const { url } = await upload(file);
      setPreviewUrl(url);
    } catch {
      // silently fail
    }
    setUploading(false);
    e.target.value = '';
  };

  const handleSendPhoto = async () => {
    if (!previewUrl) return;
    const url = previewUrl;
    setPreviewUrl(null);
    await onSend(url, 'Photo');
  };

  return (
    <div ref={containerRef}>
      {/* Typing indicator */}
      {isTyping && (
        <div className="px-4 py-1.5">
          <div className="flex items-center gap-1.5">
            <div className="flex gap-0.5">
              <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:0ms]" />
              <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:150ms]" />
              <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:300ms]" />
            </div>
            <span className="text-[11px] text-muted-foreground italic">Sedang mengetik...</span>
          </div>
        </div>
      )}

      {/* Quick reply suggestions */}
      {showQuick && (
        <div className="px-4 py-2 flex gap-1.5 overflow-x-auto no-scrollbar">
          {QUICK_REPLIES.map(q => (
            <button
              key={q}
              onClick={() => handleQuickReply(q)}
              disabled={sending}
              className="flex-shrink-0 px-3 py-1.5 rounded-full bg-accent border border-primary/15 text-primary text-xs font-medium active:scale-95 transition disabled:opacity-50 whitespace-nowrap"
            >
              {q}
            </button>
          ))}
        </div>
      )}

      {/* Photo preview */}
      {previewUrl && (
        <div className="px-4 py-2">
          <div className="relative inline-block">
            <img src={previewUrl} alt="Preview" className="w-28 h-28 rounded-xl object-cover border border-border" />
            <button onClick={() => setPreviewUrl(null)} className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-destructive text-white flex items-center justify-center">
              <X className="w-3 h-3" />
            </button>
            <button
              onClick={handleSendPhoto}
              disabled={sending}
              className="absolute bottom-1.5 right-1.5 p-1.5 rounded-full bg-primary text-primary-foreground active:scale-90 transition"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}

      {/* Attachment overlay */}
      {showAttach && (
        <div className="px-4 py-2 flex gap-2">
          <button
            onClick={() => { cameraRef.current?.click(); }}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-accent border border-primary/15 text-sm font-medium active:scale-95 transition"
          >
            <Camera className="w-4 h-4 text-primary" /> Kamera
          </button>
          <button
            onClick={() => { fileRef.current?.click(); }}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-accent border border-primary/15 text-sm font-medium active:scale-95 transition"
          >
            <ImageIcon className="w-4 h-4 text-primary" /> Galeri
          </button>
        </div>
      )}

      {/* Text input row */}
      <div className="flex items-center gap-2 px-4 py-2.5">
        <button
          onClick={() => setShowAttach(prev => !prev)}
          className={`p-2 rounded-full transition active:scale-90 ${showAttach ? 'bg-primary text-primary-foreground' : 'bg-muted text-foreground'}`}
        >
          {uploading ? <MutariInline size={16} /> : <Plus className="w-4 h-4" />}
        </button>
        <input
          ref={inputRef}
          type="text"
          value={text}
          onChange={e => handleTextChange(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleSendText()}
          onFocus={handleFocus}
          placeholder="Tulis pesan..."
          className="flex-1 bg-muted rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
          enterKeyHint="send"
          autoComplete="off"
        />
        <button
          onClick={handleSendText}
          disabled={!text.trim() || sending}
          className="p-2 rounded-full bg-primary text-primary-foreground disabled:opacity-40 active:scale-90 transition"
        >
          <Send className="w-4 h-4" />
        </button>
      </div>

      {/* Hidden file inputs */}
      <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleFileSelected} />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFileSelected} />
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useState, useEffect, useCallback } from 'react';
import { X, MapPin, Target, PenLine, ChevronRight, ExternalLink, Coffee, Building2, Train, ShoppingBag, Star, Zap, CheckCircle2 } from 'lucide-react';
import InteractiveMap from './InteractiveMap';

interface LatLng {
  lat: number;
  lng: number;
}

interface Props {
  currentAddress: string;
  currentDetail: string;
  locationA: LatLng | null;
  locationB: LatLng | null;
  labelA: string;
  labelB: string;
  onClose: () => void;
  onSubmit: (address: string, detail: string) => Promise<void>;
}

function haversineDistance(a: LatLng, b: LatLng): number {
  const R = 6371;
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const sinLat = Math.sin(dLat / 2);
  const sinLng = Math.sin(dLng / 2);
  const h = sinLat * sinLat + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * sinLng * sinLng;
  return R * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

function getMidpoint(a: LatLng, b: LatLng): LatLng {
  return { lat: (a.lat + b.lat) / 2, lng: (a.lng + b.lng) / 2 };
}

function formatDistance(km: number): string {
  if (km < 1) return `${Math.round(km * 1000)} m`;
  return `${km.toFixed(1)} km`;
}

interface RecommendedPlace {
  pos: LatLng;
  name: string;
  type: string;
  distKm: number;
}

type CodMode = 'choose' | 'manual' | 'auto';

export default function CodModal({ currentAddress, currentDetail, locationA, locationB, labelA, labelB, onClose, onSubmit }: Props) {
  const [mode, setMode] = useState<CodMode>('choose');
  const [address, setAddress] = useState(currentAddress);
  const [detail, setDetail] = useState(currentDetail);
  const [submitting, setSubmitting] = useState(false);
  const [selectedPoint, setSelectedPoint] = useState<LatLng | null>(null);
  const [reverseGeoLoading, setReverseGeoLoading] = useState(false);

  // GPS location (used as fallback when item coords are missing)
  const [gpsLocation, setGpsLocation] = useState<LatLng | null>(null);
  const [gpsLoading, setGpsLoading] = useState(false);

  // Manual mode: recommendation places
  const [recommendations, setRecommendations] = useState<RecommendedPlace[]>([]);
  const [recsLoading, setRecsLoading] = useState(false);
  const [selectedRecIdx, setSelectedRecIdx] = useState<number | null>(null);

  // Auto mode states
  const [autoSearching, setAutoSearching] = useState(false);
  const [autoResult, setAutoResult] = useState<{ place: RecommendedPlace; addressStr: string } | null>(null);
  const [autoError, setAutoError] = useState('');

  const hasBothLocations = !!(locationA && locationB);
  const midpoint = hasBothLocations ? getMidpoint(locationA!, locationB!) : null;
  const totalDistance = hasBothLocations ? haversineDistance(locationA!, locationB!) : null;
  const distanceFromA = midpoint && locationA ? haversineDistance(locationA, midpoint) : null;
  const distanceFromB = midpoint && locationB ? haversineDistance(locationB, midpoint) : null;

  // Request GPS on mount — always try to get user's location as fallback
  useEffect(() => {
    if (!navigator.geolocation) return;
    setGpsLoading(true);
    navigator.geolocation.getCurrentPosition(
      pos => {
        setGpsLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setGpsLoading(false);
      },
      () => setGpsLoading(false),
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  // Determine best center for the map:
  // Priority: midpoint > locationA > locationB > GPS > Jakarta default
  const getBestCenter = useCallback((): LatLng => {
    if (midpoint) return midpoint;
    if (locationA && locationB) return getMidpoint(locationA, locationB);
    if (locationA) return locationA;
    if (locationB) return locationB;
    if (gpsLocation) return gpsLocation;
    return { lat: -6.2, lng: 106.8 };
  }, [midpoint, locationA, locationB, gpsLocation]);

  // Reverse geocode
  const reverseGeocode = useCallback(async (point: LatLng): Promise<string> => {
    setReverseGeoLoading(true);
    let result = `Lokasi (${point.lat.toFixed(5)}, ${point.lng.toFixed(5)})`;
    try {
      const res = await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${point.lat}&lon=${point.lng}&format=json&accept-language=id`);
      const data = await res.json();
      if (data.display_name) {
        result = data.display_name.split(',').slice(0, 3).join(',').trim();
      }
    } catch { /* use fallback */ }
    setReverseGeoLoading(false);
    return result;
  }, []);

  // Fetch nearby places
  const fetchNearbyPlaces = useCallback(async (center: LatLng): Promise<RecommendedPlace[]> => {
    const queries = ['mall', 'cafe', 'stasiun', 'masjid', 'minimarket'];
    const radius = 0.02;
    const allPlaces: RecommendedPlace[] = [];

    const results = await Promise.allSettled(
      queries.map(async (q) => {
        const res = await fetch(
          `https://nominatim.openstreetmap.org/search?q=${q}&format=json&limit=3&accept-language=id&viewbox=${center.lng - radius},${center.lat + radius},${center.lng + radius},${center.lat - radius}&bounded=1`
        );
        return { query: q, data: await res.json() };
      })
    );

    for (const r of results) {
      if (r.status !== 'fulfilled' || !Array.isArray(r.value.data)) continue;
      const q = r.value.query;
      for (const place of r.value.data) {
        if (!place.lat || !place.lon) continue;
        const pos = { lat: parseFloat(place.lat), lng: parseFloat(place.lon) };
        const dist = haversineDistance(center, pos);
        if (dist > 5) continue;
        const typeLabel = q === 'mall' ? 'Mall/Pusat Belanja'
          : q === 'cafe' ? 'Kafe/Restoran'
          : q === 'stasiun' ? 'Stasiun/Terminal'
          : q === 'masjid' ? 'Tempat Ibadah'
          : 'Minimarket';
        allPlaces.push({ pos, name: (place.display_name as string).split(',').slice(0, 2).join(',').trim(), type: typeLabel, distKm: dist });
      }
    }

    const seen = new Set<string>();
    return allPlaces
      .filter(p => { if (seen.has(p.name)) return false; seen.add(p.name); return true; })
      .sort((a, b) => a.distKm - b.distKm)
      .slice(0, 8);
  }, []);

  // ===== MANUAL MODE =====
  const handleEnterManual = () => {
    setMode('manual');
    const center = getBestCenter();
    setRecsLoading(true);
    fetchNearbyPlaces(center).then(places => {
      setRecommendations(places);
      setRecsLoading(false);
    }).catch(() => setRecsLoading(false));
  };

  const handleMapSelect = useCallback(async (point: LatLng) => {
    setSelectedPoint(point);
    setSelectedRecIdx(null);
    const addr = await reverseGeocode(point);
    setAddress(addr);
    setDetail('');
  }, [reverseGeocode]);

  const handleSelectRec = (idx: number) => {
    const rec = recommendations[idx];
    setSelectedRecIdx(idx);
    setSelectedPoint(rec.pos);
    setAddress(rec.name);
    setDetail(rec.type);
  };

  // ===== AUTO MODE =====
  const handleAutoMode = async () => {
    setMode('auto');
    setAutoSearching(true);
    setAutoError('');
    setAutoResult(null);

    try {
      // Use midpoint if both locations available, otherwise use GPS or best center
      const center = getBestCenter();

      const places = await fetchNearbyPlaces(center);

      if (places.length > 0) {
        const best = places[0];
        setAutoResult({ place: best, addressStr: best.name });
        setSelectedPoint(best.pos);
        setAddress(best.name);
        setDetail(best.type);
      } else {
        const addr = await reverseGeocode(center);
        const fallback: RecommendedPlace = { pos: center, name: addr, type: 'Titik Tengah', distKm: 0 };
        setAutoResult({ place: fallback, addressStr: addr });
        setSelectedPoint(center);
        setAddress(addr);
        setDetail('Lokasi otomatis');
      }
    } catch {
      setAutoError('Gagal mencari lokasi. Coba lagi atau pilih manual.');
    }
    setAutoSearching(false);
  };

  const handleAutoSubmit = async () => {
    if (!autoResult) return;
    setSubmitting(true);
    const fullAddress = `${autoResult.addressStr.trim()} [${autoResult.place.pos.lat.toFixed(6)},${autoResult.place.pos.lng.toFixed(6)}]`;
    await onSubmit(fullAddress, detail.trim());
    setSubmitting(false);
  };

  const handleManualSubmit = async () => {
    if (!address.trim() || !selectedPoint) return;
    setSubmitting(true);
    const fullAddress = `${address.trim()} [${selectedPoint.lat.toFixed(6)},${selectedPoint.lng.toFixed(6)}]`;
    await onSubmit(fullAddress, detail.trim());
    setSubmitting(false);
  };

  const openInGoogleMaps = (point: LatLng) => {
    window.open(`https://www.google.com/maps?q=${point.lat},${point.lng}`, '_blank');
  };

  // Map markers
  const getMarkers = () => {
    const markers: { pos: LatLng; label: string; color: 'green' | 'blue' | 'red' | 'amber' }[] = [];
    if (locationA) markers.push({ pos: locationA, label: labelA, color: 'green' });
    if (locationB) markers.push({ pos: locationB, label: labelB, color: 'blue' });
    if (midpoint) markers.push({ pos: midpoint, label: 'Titik Tengah', color: 'amber' });
    // If no item locations, show GPS
    if (!locationA && !locationB && gpsLocation) {
      markers.push({ pos: gpsLocation, label: 'Lokasi Anda (GPS)', color: 'green' });
    }
    return markers;
  };

  // Check if we have at least some location data to work with
  const hasAnyLocation = !!(locationA || locationB || gpsLocation);
  const isReady = hasAnyLocation || !gpsLoading;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end justify-center" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="max-w-[420px] w-full bg-card rounded-t-2xl animate-in slide-in-from-bottom duration-300 max-h-[92vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 pb-2">
          <h3 className="font-bold text-base flex items-center gap-2">
            <MapPin className="w-5 h-5 text-primary" /> Atur Lokasi COD
          </h3>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="overflow-y-auto flex-1 px-4 pb-4">

          {/* ===== CHOOSE MODE ===== */}
          {mode === 'choose' && (
            <div className="space-y-3 mt-1">
              <p className="text-xs text-muted-foreground">Pilih cara menentukan lokasi COD:</p>

              {/* GPS loading indicator */}
              {gpsLoading && !hasAnyLocation && (
                <div className="flex items-center gap-2 py-2 justify-center">
                  <MutariInline size={16} />
                  <p className="text-xs text-muted-foreground">Mendapatkan lokasi GPS...</p>
                </div>
              )}

              {/* Option 1: Auto - 1 klik */}
              <button
                onClick={handleAutoMode}
                disabled={!isReady || (!hasAnyLocation && !gpsLoading)}
                className="w-full text-left bg-gradient-to-r from-primary/5 via-primary/10 to-primary/5 rounded-xl p-4 border border-primary/20 hover:border-primary/40 transition disabled:opacity-40 disabled:cursor-not-allowed group"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-primary/15 flex items-center justify-center flex-shrink-0">
                    <Zap className="w-5 h-5 text-primary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-bold text-foreground">⚡ Otomatis 1-Klik</p>
                    <p className="text-[11px] text-muted-foreground mt-0.5">
                      Langsung carikan tempat publik terbaik{hasBothLocations ? ' di titik tengah' : ' di sekitar lokasi'} — tanpa isi apapun
                    </p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-muted-foreground group-hover:text-primary transition flex-shrink-0" />
                </div>

                {hasBothLocations && totalDistance !== null && (
                  <div className="mt-3 flex gap-2">
                    <DistanceBox label={labelA} dist={formatDistance(distanceFromA!)} color="text-green-600" />
                    <DistanceBox label={labelB} dist={formatDistance(distanceFromB!)} color="text-blue-600" />
                    <DistanceBox label="Total" dist={formatDistance(totalDistance)} color="text-foreground" />
                  </div>
                )}
                {!hasBothLocations && hasAnyLocation && (
                  <p className="text-[10px] text-amber-600 mt-2">📍 Menggunakan {gpsLocation && !locationA && !locationB ? 'GPS Anda' : 'lokasi yang tersedia'} sebagai acuan</p>
                )}
              </button>

              {/* Option 2: Manual — klik peta + rekomendasi */}
              <button
                onClick={handleEnterManual}
                disabled={!isReady || (!hasAnyLocation && !gpsLoading)}
                className="w-full text-left bg-card rounded-xl p-4 border border-border hover:border-primary/30 transition group disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                    <PenLine className="w-5 h-5 text-muted-foreground" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-bold text-foreground">Pilih Manual di Peta</p>
                    <p className="text-[11px] text-muted-foreground mt-0.5">
                      Klik peta atau pilih rekomendasi — alamat otomatis terisi
                    </p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-muted-foreground group-hover:text-primary transition flex-shrink-0" />
                </div>
              </button>

              <CodTips />
            </div>
          )}

          {/* ===== AUTO MODE ===== */}
          {mode === 'auto' && (
            <div className="space-y-3 mt-1">
              <button onClick={() => { setMode('choose'); setAutoResult(null); setAutoError(''); }} className="text-xs text-primary font-medium hover:underline">
                ← Kembali ke pilihan
              </button>

              {hasBothLocations && (
                <MidpointViz labelA={labelA} labelB={labelB} distA={distanceFromA!} distB={distanceFromB!} totalDist={totalDistance!} />
              )}

              {autoSearching && (
                <div className="py-10 flex flex-col items-center gap-3">
                  <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center">
                    <MutariInline size={28} />
                  </div>
                  <p className="text-sm font-semibold text-foreground">Mencari tempat terbaik...</p>
                  <p className="text-xs text-muted-foreground text-center">
                    {hasBothLocations ? 'Menghitung titik tengah & mencari tempat publik terdekat' : 'Mencari tempat publik di sekitar lokasi...'}
                  </p>
                </div>
              )}

              {!autoSearching && autoResult && (
                <div className="space-y-3">
                  <div className="bg-green-50 dark:bg-green-950/20 rounded-xl p-4 border border-green-200 dark:border-green-800">
                    <div className="flex items-center gap-2 mb-2">
                      <CheckCircle2 className="w-5 h-5 text-green-600" />
                      <p className="text-sm font-bold text-green-700 dark:text-green-400">Lokasi Ditemukan!</p>
                    </div>
                    <div className="space-y-1.5 ml-7">
                      <p className="text-sm font-semibold text-foreground">{autoResult.addressStr}</p>
                      <p className="text-xs text-muted-foreground">{autoResult.place.type}</p>
                      {autoResult.place.distKm > 0 && (
                        <p className="text-[11px] text-muted-foreground">
                          {formatDistance(autoResult.place.distKm)} dari {hasBothLocations ? 'titik tengah' : 'lokasi acuan'}
                        </p>
                      )}
                    </div>
                  </div>

                  <InteractiveMap
                    center={autoResult.place.pos}
                    zoom={15}
                    markers={[
                      ...getMarkers(),
                    ]}
                    selectedPoint={autoResult.place.pos}
                    clickable={false}
                    height={200}
                  />

                  <button
                    onClick={() => openInGoogleMaps(autoResult.place.pos)}
                    className="w-full flex items-center justify-center gap-2 py-2 text-xs font-medium text-primary bg-primary/5 rounded-xl border border-primary/15 hover:bg-primary/10 transition"
                  >
                    <ExternalLink className="w-3.5 h-3.5" /> Buka di Google Maps
                  </button>
                </div>
              )}

              {!autoSearching && autoError && (
                <div className="py-8 text-center space-y-3">
                  <p className="text-sm text-destructive font-medium">{autoError}</p>
                  <button onClick={handleAutoMode} className="text-xs text-primary font-semibold px-4 py-2 rounded-xl bg-primary/10">
                    Coba Lagi
                  </button>
                </div>
              )}
            </div>
          )}

          {/* ===== MANUAL MODE ===== */}
          {mode === 'manual' && (
            <div className="space-y-3 mt-1">
              <button onClick={() => { setMode('choose'); setSelectedPoint(null); setAddress(currentAddress); setRecommendations([]); setSelectedRecIdx(null); }} className="text-xs text-primary font-medium hover:underline">
                ← Kembali ke pilihan
              </button>

              {hasBothLocations && (
                <MidpointViz labelA={labelA} labelB={labelB} distA={distanceFromA!} distB={distanceFromB!} totalDist={totalDistance!} />
              )}

              <InteractiveMap
                center={getBestCenter()}
                zoom={hasBothLocations ? 13 : 14}
                markers={getMarkers()}
                selectedPoint={selectedPoint}
                onSelect={handleMapSelect}
                clickable={true}
                height={240}
              />

              {selectedPoint && (
                <div className="bg-green-50 dark:bg-green-950/20 rounded-xl p-3 border border-green-200 dark:border-green-800">
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 rounded-full bg-red-500 flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className="text-[11px] font-semibold text-foreground">
                        {reverseGeoLoading ? 'Mencari alamat...' : address || 'Menunggu...'}
                      </p>
                      <p className="text-[10px] text-muted-foreground">
                        {selectedPoint.lat.toFixed(5)}, {selectedPoint.lng.toFixed(5)}
                      </p>
                    </div>
                    <button onClick={() => openInGoogleMaps(selectedPoint)} className="text-[10px] text-primary font-medium flex items-center gap-0.5 px-2 py-1 rounded-lg bg-primary/10 flex-shrink-0">
                      <ExternalLink className="w-3 h-3" /> Maps
                    </button>
                  </div>
                </div>
              )}

              {!selectedPoint && (
                <div className="bg-amber-50 dark:bg-amber-950/20 rounded-xl p-3 border border-amber-200 dark:border-amber-800 text-center">
                  <p className="text-xs text-amber-700 dark:text-amber-400 font-medium">👆 Klik di peta untuk pilih lokasi COD</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5">Atau pilih dari rekomendasi di bawah</p>
                </div>
              )}

              {/* Recommendations */}
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Star className="w-3.5 h-3.5 text-amber-500" />
                  <p className="text-xs font-bold text-foreground">Rekomendasi Tempat Publik</p>
                </div>

                {recsLoading && (
                  <div className="flex items-center gap-2 py-3 justify-center">
                    <MutariInline size={16} />
                    <p className="text-xs text-muted-foreground">Mencari tempat publik terdekat...</p>
                  </div>
                )}

                {!recsLoading && recommendations.length > 0 && (
                  <div className="space-y-1.5 max-h-[200px] overflow-y-auto">
                    {recommendations.map((rec, i) => (
                      <RecCard key={i} rec={rec} selected={selectedRecIdx === i} onSelect={() => handleSelectRec(i)} />
                    ))}
                  </div>
                )}

                {!recsLoading && recommendations.length === 0 && (
                  <p className="text-[11px] text-muted-foreground text-center py-2">
                    Tidak ditemukan tempat publik di sekitar. Klik peta untuk pilih lokasi.
                  </p>
                )}
              </div>

              {selectedPoint && (
                <div>
                  <label className="text-sm font-medium">Detail Tambahan (opsional)</label>
                  <input
                    type="text"
                    value={detail}
                    onChange={e => setDetail(e.target.value)}
                    placeholder="Contoh: Lantai 2, dekat eskalator"
                    className="mt-1 w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
                  />
                </div>
              )}
            </div>
          )}
        </div>

        {/* Submit buttons */}
        {mode === 'manual' && selectedPoint && (
          <div className="p-4 pt-2 border-t border-border space-y-2">
            <button
              onClick={handleManualSubmit}
              disabled={!address.trim() || submitting || reverseGeoLoading}
              className="w-full py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
            >
              {submitting ? <MutariInline size={16} /> : <MapPin className="w-4 h-4" />}
              {submitting ? 'Menyimpan...' : 'Usulkan Lokasi COD'}
            </button>
            <p className="text-[10px] text-muted-foreground text-center">
              Pihak lain akan mendapat notifikasi & bisa memperbarui lokasi jika perlu
            </p>
          </div>
        )}

        {mode === 'auto' && autoResult && !autoSearching && (
          <div className="p-4 pt-2 border-t border-border space-y-2">
            <button
              onClick={handleAutoSubmit}
              disabled={submitting}
              className="w-full py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
            >
              {submitting ? <MutariInline size={16} /> : <CheckCircle2 className="w-4 h-4" />}
              {submitting ? 'Menyimpan...' : 'Setuju & Usulkan Lokasi Ini'}
            </button>
            <p className="text-[10px] text-muted-foreground text-center">
              Pihak lain akan mendapat notifikasi & bisa memperbarui lokasi jika perlu
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

/* ======== Sub-components ======== */

function RecCard({ rec, selected, onSelect }: { rec: RecommendedPlace; selected: boolean; onSelect: () => void }) {
  const icon = rec.type.includes('Kafe') ? <Coffee className="w-3.5 h-3.5 text-orange-600" />
    : rec.type.includes('Mall') ? <ShoppingBag className="w-3.5 h-3.5 text-purple-600" />
    : rec.type.includes('Stasiun') ? <Train className="w-3.5 h-3.5 text-blue-600" />
    : rec.type.includes('Ibadah') ? <Building2 className="w-3.5 h-3.5 text-emerald-600" />
    : <MapPin className="w-3.5 h-3.5 text-red-500" />;

  return (
    <button
      onClick={onSelect}
      className={`w-full text-left rounded-xl p-2.5 border transition flex items-center gap-2.5 ${selected
        ? 'border-primary bg-primary/5'
        : 'border-border bg-card hover:border-primary/30'
      }`}
    >
      <div className={`w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0 ${selected ? 'bg-primary/15' : 'bg-muted'}`}>
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-[11px] font-semibold text-foreground truncate">{rec.name}</p>
        <p className="text-[10px] text-muted-foreground">{rec.type}</p>
      </div>
      <div className="text-right flex-shrink-0">
        <p className="text-[10px] font-bold text-primary">{formatDistance(rec.distKm)}</p>
        <p className="text-[9px] text-muted-foreground">dari tengah</p>
      </div>
    </button>
  );
}

function DistanceBox({ label, dist, color }: { label: string; dist: string; color: string }) {
  return (
    <div className="flex-1 bg-card rounded-lg px-2 py-1.5 text-center border border-border">
      <p className="text-[9px] text-muted-foreground truncate">{label}</p>
      <p className={`text-[11px] font-bold ${color}`}>{dist}</p>
    </div>
  );
}

function MidpointViz({ labelA, labelB, distA, distB, totalDist }: { labelA: string; labelB: string; distA: number; distB: number; totalDist: number }) {
  return (
    <div className="bg-gradient-to-r from-primary/5 via-primary/10 to-primary/5 rounded-xl p-3 border border-primary/15">
      <div className="flex items-center gap-2 mb-2.5">
        <Target className="w-4 h-4 text-primary flex-shrink-0" />
        <p className="text-xs font-bold text-primary">Titik Tengah MUTARI</p>
      </div>
      <div className="flex items-center gap-2 mb-2">
        <div className="flex-1 text-center">
          <div className="w-6 h-6 rounded-full bg-green-500/15 border-2 border-green-500 flex items-center justify-center mx-auto mb-0.5">
            <span className="text-[8px] font-bold text-green-600">A</span>
          </div>
          <p className="text-[9px] font-medium text-foreground truncate">{labelA}</p>
          <p className="text-[9px] text-green-600 font-bold">{formatDistance(distA)}</p>
        </div>
        <div className="flex-1 flex flex-col items-center">
          <div className="flex items-center gap-1 w-full">
            <div className="flex-1 border-t border-dashed border-green-400"></div>
            <div className="w-5 h-5 rounded-full bg-amber-500 flex items-center justify-center shadow-sm">
              <Target className="w-2.5 h-2.5 text-white" />
            </div>
            <div className="flex-1 border-t border-dashed border-blue-400"></div>
          </div>
          <p className="text-[8px] text-amber-600 font-bold mt-0.5">COD</p>
        </div>
        <div className="flex-1 text-center">
          <div className="w-6 h-6 rounded-full bg-blue-500/15 border-2 border-blue-500 flex items-center justify-center mx-auto mb-0.5">
            <span className="text-[8px] font-bold text-blue-600">B</span>
          </div>
          <p className="text-[9px] font-medium text-foreground truncate">{labelB}</p>
          <p className="text-[9px] text-blue-600 font-bold">{formatDistance(distB)}</p>
        </div>
      </div>
      <div className="bg-card rounded-lg px-2 py-1 text-center border border-border">
        <p className="text-[9px] text-muted-foreground">Total Jarak</p>
        <p className="text-[11px] font-bold text-foreground">{formatDistance(totalDist)}</p>
      </div>
    </div>
  );
}

function CodTips() {
  return (
    <div className="bg-accent/50 rounded-xl p-3 border border-primary/10">
      <p className="text-[11px] text-foreground font-medium">💡 Tips Keamanan COD</p>
      <ul className="text-[11px] text-muted-foreground mt-1 space-y-0.5">
        <li>• Pilih tempat umum yang ramai (mall, kafe, stasiun)</li>
        <li>• Bertemu di siang hari</li>
        <li>• Ajak teman/keluarga bila perlu</li>
        <li>• Kedua pihak bisa usulkan & ubah lokasi sampai setuju</li>
      </ul>
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useState } from 'react';
import { X, CheckCircle2, AlertTriangle, Users, ArrowRight } from 'lucide-react';

interface Props {
  onClose: () => void;
  onConfirm: () => Promise<void>;
  myConfirmed?: boolean;
  otherConfirmed?: boolean;
  otherName?: string;
}

export default function ConfirmModal({ onClose, onConfirm, myConfirmed, otherConfirmed, otherName }: Props) {
  const [confirming, setConfirming] = useState(false);

  const handleConfirm = async () => {
    setConfirming(true);
    await onConfirm();
    setConfirming(false);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center px-6" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="max-w-[360px] w-full bg-card rounded-2xl p-5 animate-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-bold text-base">Konfirmasi Barter Selesai</h3>
          <button onClick={onClose} className="p-1 rounded-lg hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Dual confirmation status */}
        <div className="bg-muted/50 rounded-xl p-3 mb-4 border border-border">
          <div className="flex items-center gap-2 mb-2">
            <Users className="w-4 h-4 text-primary" />
            <p className="text-xs font-bold">Status Konfirmasi Kedua Pihak</p>
          </div>
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <div className={`w-5 h-5 rounded-full flex items-center justify-center ${myConfirmed ? 'bg-green-500' : 'bg-muted border-2 border-border'}`}>
                {myConfirmed && <CheckCircle2 className="w-3 h-3 text-white" />}
              </div>
              <span className={`text-xs ${myConfirmed ? 'text-green-600 font-semibold' : 'text-muted-foreground'}`}>
                Anda {myConfirmed ? '— sudah konfirmasi ✓' : '— belum konfirmasi'}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <div className={`w-5 h-5 rounded-full flex items-center justify-center ${otherConfirmed ? 'bg-green-500' : 'bg-muted border-2 border-border'}`}>
                {otherConfirmed && <CheckCircle2 className="w-3 h-3 text-white" />}
              </div>
              <span className={`text-xs ${otherConfirmed ? 'text-green-600 font-semibold' : 'text-muted-foreground'}`}>
                {otherName || 'Pihak lain'} {otherConfirmed ? '— sudah konfirmasi ✓' : '— belum konfirmasi'}
              </span>
            </div>
          </div>
          <div className="mt-2 pt-2 border-t border-border">
            <p className="text-[10px] text-muted-foreground flex items-center gap-1">
              <ArrowRight className="w-3 h-3" /> Barter selesai jika <strong>kedua pihak</strong> sudah konfirmasi
            </p>
          </div>
        </div>

        <div className="flex items-start gap-3 bg-yellow-50 dark:bg-yellow-950/20 p-3 rounded-xl border border-yellow-200 dark:border-yellow-800 mb-4">
          <AlertTriangle className="w-5 h-5 text-yellow-600 flex-shrink-0 mt-0.5" />
          <div>
            <p className="text-xs text-yellow-700 dark:text-yellow-400 font-medium">Pastikan barter sudah benar-benar selesai</p>
            <p className="text-[11px] text-yellow-600 dark:text-yellow-500 mt-1">
