        </div>
      </div>
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useEffect, useRef, useState, useCallback } from 'react';

interface LatLng {
  lat: number;
  lng: number;
}

interface MarkerConfig {
  pos: LatLng;
  label: string;
  color: 'green' | 'blue' | 'red' | 'amber';
  draggable?: boolean;
}

interface Props {
  center: LatLng;
  zoom?: number;
  markers?: MarkerConfig[];
  selectedPoint?: LatLng | null;
  onSelect?: (point: LatLng) => void;
  height?: number;
  clickable?: boolean;
}

const COLOR_MAP: Record<string, string> = {
  green: '#22c55e',
  blue: '#3b82f6',
  red: '#ef4444',
  amber: '#f59e0b',
};

let leafletLoaded = false;
let leafletLoadPromise: Promise<void> | null = null;

function loadLeaflet(): Promise<void> {
  if (leafletLoaded) return Promise.resolve();
  if (leafletLoadPromise) return leafletLoadPromise;

  leafletLoadPromise = new Promise<void>((resolve, reject) => {
    // CSS
    if (!document.querySelector('link[href*="leaflet"]')) {
      const css = document.createElement('link');
      css.rel = 'stylesheet';
      css.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      document.head.appendChild(css);
    }
    // JS
    if ((window as any).L) {
      leafletLoaded = true;
      resolve();
      return;
    }
    const script = document.createElement('script');
    script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    script.onload = () => { leafletLoaded = true; resolve(); };
    script.onerror = () => reject(new Error('Failed to load Leaflet'));
    document.head.appendChild(script);
  });
  return leafletLoadPromise;
}

function createIcon(color: string, size: number = 12) {
  const L = (window as any).L;
  return L.divIcon({
    className: '',
    html: `<div style="width:${size}px;height:${size}px;border-radius:50%;background:${color};border:2.5px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,0.3);"></div>`,
    iconSize: [size, size],
    iconAnchor: [size / 2, size / 2],
  });
}

function createSelectedIcon() {
  const L = (window as any).L;
  return L.divIcon({
    className: '',
    html: `<div style="width:18px;height:18px;border-radius:50%;background:#ef4444;border:3px solid #fff;box-shadow:0 2px 8px rgba(239,68,68,0.5);animation:pulse 1.5s infinite;">
      <style>@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(239,68,68,0.4)}50%{box-shadow:0 0 0 8px rgba(239,68,68,0)}}</style>
    </div>`,
    iconSize: [18, 18],
    iconAnchor: [9, 9],
  });
}

export default function InteractiveMap({ center, zoom = 13, markers = [], selectedPoint, onSelect, height = 220, clickable = true }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const selectedMarkerRef = useRef<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const handleSelect = useCallback((latlng: LatLng) => {
    if (!onSelect) return;
    onSelect(latlng);
    const L = (window as any).L;
    if (!L || !mapRef.current) return;
    if (selectedMarkerRef.current) {
      selectedMarkerRef.current.setLatLng([latlng.lat, latlng.lng]);
    } else {
      selectedMarkerRef.current = L.marker([latlng.lat, latlng.lng], {
        icon: createSelectedIcon(),
        draggable: true,
        zIndexOffset: 1000,
      }).addTo(mapRef.current)
        .bindTooltip('Lokasi COD (geser untuk pindah)', { direction: 'top', offset: [0, -12] });
      selectedMarkerRef.current.on('dragend', (e: any) => {
        const pos = e.target.getLatLng();
        onSelect({ lat: pos.lat, lng: pos.lng });
      });
    }
  }, [onSelect]);

  useEffect(() => {
    let cancelled = false;
    loadLeaflet().then(() => {
      if (cancelled || !containerRef.current) return;
      const L = (window as any).L;

      // Destroy previous map if re-rendering
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        selectedMarkerRef.current = null;
      }

      const map = L.map(containerRef.current, {
        center: [center.lat, center.lng],
        zoom,
        zoomControl: true,
        attributionControl: false,
      });

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 19,
      }).addTo(map);

      // Add markers
      const bounds: any[] = [];
      markers.forEach(m => {
        const marker = L.marker([m.pos.lat, m.pos.lng], {
          icon: createIcon(COLOR_MAP[m.color] || COLOR_MAP.red, m.color === 'amber' ? 14 : 12),
          draggable: false,
        }).addTo(map);
        marker.bindTooltip(m.label, { direction: 'top', offset: [0, -8], className: 'leaflet-tooltip-custom' });
        bounds.push([m.pos.lat, m.pos.lng]);
      });

      // Add selected point
      if (selectedPoint) {
        selectedMarkerRef.current = L.marker([selectedPoint.lat, selectedPoint.lng], {
          icon: createSelectedIcon(),
          draggable: !!onSelect,
          zIndexOffset: 1000,
        }).addTo(map)
          .bindTooltip('Lokasi COD (geser untuk pindah)', { direction: 'top', offset: [0, -12] });
        if (onSelect) {
          selectedMarkerRef.current.on('dragend', (e: any) => {
            const pos = e.target.getLatLng();
            onSelect({ lat: pos.lat, lng: pos.lng });
          });
        }
        bounds.push([selectedPoint.lat, selectedPoint.lng]);
      }

      // Fit bounds
      if (bounds.length > 1) {
        map.fitBounds(bounds, { padding: [30, 30], maxZoom: 15 });
      }

      // Click handler
      if (clickable && onSelect) {
        map.on('click', (e: any) => {
          handleSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
        });
      }

      mapRef.current = map;
      setLoading(false);

      // Force resize after render
      setTimeout(() => map.invalidateSize(), 100);
    }).catch(() => {
      if (!cancelled) setError('Gagal memuat peta');
      setLoading(false);
    });

    return () => {
      cancelled = true;
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        selectedMarkerRef.current = null;
      }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [center.lat, center.lng, zoom]);

  // Update markers when they change (without recreating map)
  // This is handled by the initial effect for simplicity

  return (
    <div className="relative rounded-xl overflow-hidden border border-border" style={{ height }}>
      <div ref={containerRef} className="w-full h-full" style={{ zIndex: 1 }} />
      {loading && (
        <div className="absolute inset-0 bg-muted flex items-center justify-center z-10">
          <MutariInline size={20} className="text-muted-foreground" />
        </div>
      )}
      {error && (
        <div className="absolute inset-0 bg-muted flex items-center justify-center z-10">
          <p className="text-xs text-destructive">{error}</p>
        </div>
      )}
      {clickable && onSelect && !loading && (
        <div className="absolute bottom-2 left-2 bg-card/90 backdrop-blur-sm rounded-lg px-2 py-1 text-[9px] text-muted-foreground shadow border border-border z-[500]">
          👆 Klik peta untuk pilih lokasi · Geser pin untuk pindah
        </div>
      )}
      {/* Legend */}
      {markers.length > 0 && !loading && (
        <div className="absolute top-2 right-2 bg-card/90 backdrop-blur-sm rounded-lg px-2 py-1.5 shadow border border-border z-[500]">
          {markers.map((m, i) => (
            <div key={i} className="flex items-center gap-1.5 text-[9px] leading-relaxed">
              <span className="w-2.5 h-2.5 rounded-full inline-block flex-shrink-0" style={{ backgroundColor: COLOR_MAP[m.color] || COLOR_MAP.red }} />
              <span className="text-foreground">{m.label}</span>
            </div>
          ))}
          {selectedPoint && (
            <div className="flex items-center gap-1.5 text-[9px] leading-relaxed">
              <span className="w-2.5 h-2.5 rounded-full inline-block flex-shrink-0 bg-red-500" />
              <span className="text-foreground font-semibold">Lokasi COD</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

