import { MutariInline } from '../MutariSpinner';
import { useState, useRef } from 'react';
import { X, Camera, ImageIcon, AlertTriangle, Upload, Trash2 } from 'lucide-react';
import { useUpload } from 'zitejs/upload';
import { reportViolation } from 'zitejs/api';
import { toast } from 'sonner';
import { VIOLATION_TYPES, severityColor, type ViolationDef } from '../../lib/violations';

interface ReportModalProps {
  onClose: () => void;
  reportedUserId: string;
  reportedUserName: string;
  barterId?: string;
}

const SEVERITY_ORDER = ['paling_berat', 'berat', 'sedang', 'ringan'] as const;
const SEVERITY_LABELS: Record<string, string> = {
  paling_berat: '🔴 Paling Berat',
  berat: '🟠 Berat',
  sedang: '🟡 Sedang',
  ringan: '🟢 Ringan',
};

export default function ReportModal({ onClose, reportedUserId, reportedUserName, barterId }: ReportModalProps) {
  const [step, setStep] = useState<'type' | 'detail'>('type');
  const [selected, setSelected] = useState<ViolationDef | null>(null);
  const [notes, setNotes] = useState('');
  const [phone, setPhone] = useState('');
  const [evidenceUrls, setEvidenceUrls] = useState<string[]>([]);
  const [uploading, setUploading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const cameraRef = useRef<HTMLInputElement>(null);
  const { upload } = useUpload();

  const handleFileSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    setUploading(true);
    try {
      for (let i = 0; i < Math.min(files.length, 5 - evidenceUrls.length); i++) {
        const { url } = await upload(files[i]);
        setEvidenceUrls(prev => [...prev, url]);
      }
    } catch {
      toast.error('Gagal mengunggah foto');
    }
    setUploading(false);
    e.target.value = '';
  };

  const removeEvidence = (idx: number) => {
    setEvidenceUrls(prev => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = async () => {
    if (!selected) return;
    setSubmitting(true);
    try {
      await reportViolation({
        userId: reportedUserId,
        violationType: selected.type,
        barterId,
        notes: notes.trim() || undefined,
        evidenceUrls: evidenceUrls.length > 0 ? evidenceUrls : undefined,
        reportedUserName,
        reportedUserPhone: phone.trim() || undefined,
      });
      toast.success('Laporan berhasil dikirim dan sedang menunggu review admin. Kami akan memberi tahu hasilnya.');
      onClose();
    } catch (err: any) {
      toast.error(err?.message || 'Gagal mengirim laporan');
    }
    setSubmitting(false);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4" onClick={onClose}>
      <div
        className="w-full max-w-[420px] bg-card rounded-2xl max-h-[85vh] flex flex-col animate-in slide-in-from-bottom duration-300"
        onClick={e => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-border">
          <div className="flex items-center gap-2">
            <AlertTriangle className="w-5 h-5 text-destructive" />
            <h2 className="font-bold text-base">Laporkan Pengguna</h2>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-full hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Info terlapor */}
        <div className="px-5 py-3 bg-destructive/5 border-b border-border">
          <p className="text-xs text-muted-foreground">Anda melaporkan:</p>
          <p className="font-semibold text-sm mt-0.5">{reportedUserName}</p>
          {barterId && (
            <p className="text-[11px] text-muted-foreground mt-0.5">Terkait barter #{barterId.slice(0, 8)}</p>
          )}
        </div>

        <div className="flex-1 overflow-y-auto">
          {step === 'type' ? (
            <StepSelectType
              selected={selected}
              onSelect={(v) => { setSelected(v); setStep('detail'); }}
            />
          ) : (
            <StepDetail
              selected={selected!}
              notes={notes}
              onNotesChange={setNotes}
              phone={phone}
              onPhoneChange={setPhone}
              evidenceUrls={evidenceUrls}
              onRemoveEvidence={removeEvidence}
              uploading={uploading}
              onPickGallery={() => fileRef.current?.click()}
              onPickCamera={() => cameraRef.current?.click()}
              onBack={() => setStep('type')}
            />
          )}
        </div>

        {/* Footer */}
        {step === 'detail' && (
          <div className="px-5 py-4 border-t border-border space-y-2">
            <p className="text-[10px] text-muted-foreground text-center">
              ⚠️ Laporan akan ditinjau oleh admin sebelum sanksi diterapkan. Laporan palsu dapat dikenakan sanksi -10 MP kepada pelapor.
            </p>
            <button
              onClick={handleSubmit}
              disabled={submitting || !selected || !notes.trim()}
              className="w-full py-3 rounded-2xl bg-destructive text-white font-semibold text-sm disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-2"
            >
              {submitting ? <MutariInline size={16} /> : <AlertTriangle className="w-4 h-4" />}
              {submitting ? 'Mengirim...' : 'Kirim Laporan'}
            </button>
          </div>
        )}

        {/* Hidden inputs */}
        <input ref={fileRef} type="file" accept="image/*" multiple className="hidden" onChange={handleFileSelected} />
        <input ref={cameraRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFileSelected} />
      </div>
    </div>
  );
}

/* Step 1: Select violation type */
function StepSelectType({ selected, onSelect }: { selected: ViolationDef | null; onSelect: (v: ViolationDef) => void }) {
  return (
    <div className="px-5 py-3 space-y-4">
      <p className="text-xs text-muted-foreground font-medium">Pilih jenis pelanggaran:</p>
      {SEVERITY_ORDER.map(sev => {
        const items = VIOLATION_TYPES.filter(v => v.severity === sev);
        if (items.length === 0) return null;
        return (
          <div key={sev}>
            <p className="text-xs font-bold mb-1.5">{SEVERITY_LABELS[sev]}</p>
            <div className="space-y-1.5">
              {items.map(v => {
                const colors = severityColor(sev);
                const isSelected = selected?.type === v.type;
                return (
                  <button
                    key={v.type}
                    onClick={() => onSelect(v)}
                    className={`w-full text-left px-3 py-2.5 rounded-xl border transition active:scale-[0.99] ${
                      isSelected
                        ? `${colors.bg} ${colors.border} ${colors.text} border-2`
                        : 'bg-card border-border hover:bg-muted/50'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <span className="text-base">{v.emoji}</span>
                      <div className="flex-1 min-w-0">
                        <p className="font-semibold text-xs">{v.label}</p>
                        <p className="text-[10px] text-muted-foreground mt-0.5 line-clamp-2">{v.description}</p>
                      </div>
                      <span className="text-[10px] font-bold text-destructive flex-shrink-0">{v.minusPoints} MP</span>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* Step 2: Details + Evidence */
function StepDetail({
  selected, notes, onNotesChange, phone, onPhoneChange,
  evidenceUrls, onRemoveEvidence, uploading,
