      <div>
        <button onClick={onBack} className="text-xs text-primary font-medium mb-2 hover:underline">← Ubah jenis pelanggaran</button>
        <div className={`px-3 py-2.5 rounded-xl border ${colors.bg} ${colors.border}`}>
          <div className="flex items-center gap-2">
            <span className="text-base">{selected.emoji}</span>
            <span className="font-semibold text-xs">{selected.label}</span>
