      </div>

      {/* Evidence / bukti */}
      <div>
        <label className="text-xs font-semibold text-foreground block mb-1.5">
          Bukti Foto / Screenshot <span className="text-muted-foreground font-normal">(maks 5)</span>
        </label>

        {/* Preview grid */}
        {evidenceUrls.length > 0 && (
          <div className="flex gap-2 flex-wrap mb-2">
            {evidenceUrls.map((url, i) => (
              <div key={i} className="relative w-20 h-20 rounded-xl overflow-hidden border border-border">
                <img src={url} alt={`Bukti ${i + 1}`} className="w-full h-full object-cover" />
                <button
                  onClick={() => onRemoveEvidence(i)}
                  className="absolute top-0.5 right-0.5 w-5 h-5 rounded-full bg-destructive text-white flex items-center justify-center"
                >
                  <Trash2 className="w-3 h-3" />
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Upload buttons */}
        {evidenceUrls.length < 5 && (
          <div className="flex gap-2">
            <button
              onClick={onPickCamera}
              disabled={uploading}
              className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-muted border border-border text-xs font-medium active:scale-95 transition disabled:opacity-50"
            >
              {uploading ? <MutariInline size={14} /> : <Camera className="w-3.5 h-3.5" />}
              Kamera
            </button>
            <button
              onClick={onPickGallery}
              disabled={uploading}
              className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-muted border border-border text-xs font-medium active:scale-95 transition disabled:opacity-50"
            >
              {uploading ? <MutariInline size={14} /> : <ImageIcon className="w-3.5 h-3.5" />}
              Galeri
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useState } from 'react';
import { X, Star, MessageSquare } from 'lucide-react';

const ASPECTS = [
  { value: 'barang_sesuai' as const, label: '✅ Barang Sesuai Deskripsi', positive: true },
  { value: 'komunikasi_baik' as const, label: '💬 Komunikasi Baik', positive: true },
  { value: 'tepat_waktu' as const, label: '⏰ Tepat Waktu COD', positive: true },
  { value: 'ramah' as const, label: '🤝 Ramah & Sopan', positive: true },
  { value: 'tidak_sesuai' as const, label: '⚠️ Barang Tidak Sesuai', positive: false },
  { value: 'tidak_responsif' as const, label: '😶 Tidak Responsif', positive: false },
];

type AspectValue = typeof ASPECTS[number]['value'];

interface Props {
  partnerName: string;
  onClose: () => void;
  onSubmit: (rating: number, comment: string, aspect: AspectValue) => Promise<void>;
}

export default function ReviewModal({ partnerName, onClose, onSubmit }: Props) {
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [comment, setComment] = useState('');
  const [aspect, setAspect] = useState<AspectValue | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (!rating || !comment.trim() || !aspect) return;
    setSubmitting(true);
    await onSubmit(rating, comment.trim(), aspect);
    setSubmitting(false);
  };

  const displayRating = hoverRating || rating;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end justify-center">
      <div className="max-w-[420px] w-full bg-card rounded-t-2xl p-5 animate-in slide-in-from-bottom duration-300 max-h-[85vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <h3 className="font-bold text-base flex items-center gap-2">
            <MessageSquare className="w-5 h-5 text-primary" /> Beri Rating & Review
          </h3>
          <button onClick={onClose} className="p-1 rounded-lg hover:bg-muted transition">
            <X className="w-5 h-5" />
          </button>
        </div>

        <p className="text-xs text-muted-foreground mb-4">
          Berikan penilaian jujur untuk <span className="font-semibold text-foreground">{partnerName}</span>. Review ini menjaga reputasi komunitas Mutari.
        </p>

        {/* Star Rating */}
        <div className="text-center mb-5">
          <p className="text-sm font-medium mb-2">Rating keseluruhan</p>
          <div className="flex items-center justify-center gap-1.5">
            {[1, 2, 3, 4, 5].map(star => (
              <button
                key={star}
                onMouseEnter={() => setHoverRating(star)}
                onMouseLeave={() => setHoverRating(0)}
                onClick={() => setRating(star)}
                className="p-0.5 transition-transform hover:scale-110 active:scale-95"
              >
                <Star
                  className={`w-9 h-9 transition-colors ${
                    star <= displayRating
                      ? 'text-yellow-400 fill-yellow-400'
                      : 'text-border'
                  }`}
                />
              </button>
            ))}
          </div>
          {displayRating > 0 && (
            <p className="text-xs text-muted-foreground mt-1">
              {displayRating === 1 ? 'Sangat Buruk' : displayRating === 2 ? 'Kurang' : displayRating === 3 ? 'Cukup' : displayRating === 4 ? 'Baik' : 'Sangat Baik'}
            </p>
          )}
        </div>

        {/* Aspect chips */}
        <p className="text-sm font-medium mb-2">Apa yang paling menonjol?</p>
        <div className="flex flex-wrap gap-2 mb-4">
          {ASPECTS.map(a => (
            <button
              key={a.value}
              onClick={() => setAspect(a.value)}
              className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-all active:scale-95 ${
                aspect === a.value
                  ? a.positive
                    ? 'bg-primary/10 border-primary text-primary'
                    : 'bg-destructive/10 border-destructive text-destructive'
                  : 'border-border text-muted-foreground hover:bg-muted/50'
              }`}
            >
              {a.label}
            </button>
          ))}
        </div>

        {/* Comment */}
        <p className="text-sm font-medium mb-2">Komentar</p>
        <textarea
          value={comment}
          onChange={e => setComment(e.target.value)}
          placeholder="Ceritakan pengalamanmu barter dengan orang ini..."
          maxLength={500}
          className="w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm resize-none h-24 focus:outline-none focus:ring-1 focus:ring-primary"
        />
        <p className="text-[10px] text-muted-foreground text-right mt-1">{comment.length}/500</p>

        {/* Warning */}
        <div className="bg-accent/50 rounded-xl p-3 mt-2 border border-primary/10">
          <p className="text-[11px] text-foreground font-medium">⚖️ Review yang adil dan jujur</p>
          <p className="text-[11px] text-muted-foreground mt-1">
            Review Anda bersifat permanen dan memengaruhi reputasi pengguna. Berikan penilaian berdasarkan pengalaman nyata. +10 poin untuk setiap review.
          </p>
        </div>

        <button
          onClick={handleSubmit}
          disabled={!rating || !comment.trim() || !aspect || submitting}
          className="w-full mt-4 py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
        >
          {submitting ? <MutariInline size={16} /> : null}
          {submitting ? 'Mengirim...' : `Kirim Review ${rating > 0 ? '⭐'.repeat(rating) : ''}`}
        </button>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Truck, X, Package } from 'lucide-react';
import { MutariInline } from '../MutariSpinner';

const SHIPPING_SERVICES = [
  { name: 'JNE', icon: '📦' },
  { name: 'J&T Express', icon: '🚚' },
  { name: 'SiCepat', icon: '⚡' },
  { name: 'AnterAja', icon: '📫' },
  { name: 'Ninja Xpress', icon: '🥷' },
  { name: 'Pos Indonesia', icon: '🏤' },
  { name: 'Grab Express', icon: '🟢' },
  { name: 'GoSend', icon: '🔵' },
];

interface Props {
  onClose: () => void;
  onSubmit: (service: string) => Promise<void>;
}

export default function ShippingModal({ onClose, onSubmit }: Props) {
  const [selected, setSelected] = useState('');
  const [custom, setCustom] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const finalService = selected === 'Lainnya' ? custom.trim() : selected;
  const isValid = finalService.length > 0;

  const handleSubmit = async () => {
    if (!isValid) return;
    setSubmitting(true);
    try {
      await onSubmit(finalService);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-card rounded-t-2xl sm:rounded-2xl w-full max-w-[420px] max-h-[85vh] overflow-y-auto border border-border shadow-xl">
        {/* Header */}
        <div className="sticky top-0 bg-card border-b border-border px-4 py-3 flex items-center justify-between rounded-t-2xl z-10">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-full bg-orange-100 dark:bg-orange-900/30 flex items-center justify-center">
              <Truck className="w-4 h-4 text-orange-600" />
            </div>
            <h2 className="font-bold text-sm">Pilih Jasa Kirim</h2>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-muted transition">
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="p-4 space-y-3">
          <p className="text-[11px] text-muted-foreground">
            Pilih jasa kirim yang akan digunakan kedua pihak. Pihak lain harus menyetujui sebelum bisa melanjutkan.
          </p>

          <div className="grid grid-cols-2 gap-2">
            {SHIPPING_SERVICES.map(s => (
              <button
                key={s.name}
                onClick={() => { setSelected(s.name); setCustom(''); }}
                className={`flex items-center gap-2 p-3 rounded-xl border text-left transition active:scale-[0.97] ${
                  selected === s.name
                    ? 'border-primary bg-primary/5 ring-1 ring-primary/30'
                    : 'border-border bg-card hover:border-primary/30'
                }`}
              >
                <span className="text-lg">{s.icon}</span>
                <span className="text-xs font-semibold truncate">{s.name}</span>
              </button>
            ))}
            <button
              onClick={() => setSelected('Lainnya')}
              className={`flex items-center gap-2 p-3 rounded-xl border text-left transition active:scale-[0.97] ${
                selected === 'Lainnya'
                  ? 'border-primary bg-primary/5 ring-1 ring-primary/30'
                  : 'border-border bg-card hover:border-primary/30'
              }`}
            >
              <Package className="w-5 h-5 text-muted-foreground" />
              <span className="text-xs font-semibold">Lainnya</span>
            </button>
          </div>

          {selected === 'Lainnya' && (
            <input
              type="text"
              value={custom}
              onChange={e => setCustom(e.target.value)}
              placeholder="Nama jasa kirim..."
              className="w-full px-4 py-2.5 rounded-xl border border-border bg-background text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition"
              autoFocus
            />
          )}

          {selected && (
            <div className="bg-accent/50 rounded-xl p-3 border border-primary/10">
              <p className="text-[11px] text-muted-foreground">
                📋 Kedua pihak menggunakan <strong className="text-foreground">{finalService || '...'}</strong> untuk mengirim barang masing-masing.
              </p>
            </div>
          )}

          <button
            onClick={handleSubmit}
            disabled={!isValid || submitting}
            className="w-full py-3 rounded-xl bg-orange-600 hover:bg-orange-700 text-white font-semibold text-sm disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-2"
          >
            {submitting ? (
              <MutariInline size={16} />
            ) : (
              <>
                <Truck className="w-4 h-4" />
                Usulkan {finalService || 'Jasa Kirim'}
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

