import { MutariInline } from '../MutariSpinner';
import { useState } from 'react';
import { Sparkles, ShieldCheck, TrendingUp, ArrowRightLeft, CheckCircle, Lightbulb, ArrowRight, Package, SearchX } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { matchMyItem, MatchMyItemOutputType, createBarterOffer } from 'zitejs/api';
import { toast } from 'sonner';
import { cleanError } from '../../lib/errorMsg';

interface Props {
  matchPercent: number;
  condition: string;
  priceRange: string;
  distance: string;
  itemId: string;
  title?: string;
  estimatedValueMin?: number | null;
  estimatedValueMax?: number | null;
  likesCount?: number;
  viewsCount?: number;
}

type MatchResult = MatchMyItemOutputType;

export default function AIAnalysis(props: Props) {
  const { condition, priceRange, distance, itemId } = props;
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<MatchResult | null>(null);
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleAiMikro = async () => {
    if (!itemId) return;
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const res = await matchMyItem({ targetItemId: itemId });
      setResult(res);
    } catch {
      setError('Gagal menganalisis. Coba lagi nanti.');
    }
    setLoading(false);
  };

  return (
    <div className="mx-4 mt-3 bg-card rounded-2xl border border-border overflow-hidden">
      {/* Header */}
      <div className="bg-accent px-4 py-3 flex items-center gap-3">
        <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
          <Sparkles className="w-5 h-5 text-primary" />
        </div>
        <div className="flex-1">
          <p className="font-bold text-sm">AI Mikro</p>
          <p className="text-[10px] text-muted-foreground">Cocokkan barangmu dengan barang ini</p>
        </div>
      </div>

      <div className="p-4">
        {/* Info barang target */}
        <div className="space-y-2.5 mb-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <ShieldCheck className="w-3.5 h-3.5 text-primary" />
              <span>Kondisi</span>
            </div>
            <span className="text-xs font-bold">{condition || '-'}</span>
          </div>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <TrendingUp className="w-3.5 h-3.5 text-primary" />
              <span>Estimasi Nilai</span>
            </div>
            <span className="text-xs font-bold">{priceRange}</span>
          </div>
        </div>

        {/* CTA Button */}
        {!result && (
          <button
            onClick={handleAiMikro}
            disabled={loading}
            className="w-full bg-primary text-primary-foreground rounded-xl py-3.5 flex items-center justify-center gap-2 font-semibold text-sm disabled:opacity-60 active:scale-[0.98] transition-transform"
          >
            {loading ? (
              <>
                <MutariInline size={16} />
                Menganalisis barangmu...
              </>
            ) : (
              <>
                <Sparkles className="w-4 h-4" />
                Cari Barangku yang Cocok
              </>
            )}
          </button>
        )}

        {error && (
          <p className="text-sm text-destructive mt-3 text-center">{error}</p>
        )}

        {/* Result */}
        {result && (
          <div className="space-y-4">
            {result.myItem ? (
              <>
                {/* Match card */}
                <div className="border-2 border-primary/30 bg-primary/5 rounded-xl p-4">
                  <div className="flex items-center gap-2 mb-3">
                    <ArrowRightLeft className="w-4 h-4 text-primary" />
                    <span className="text-sm font-bold text-primary">Barangmu yang Paling Cocok</span>
                  </div>

                  <div className="flex items-center gap-3">
                    {result.myItem.photo ? (
                      <img src={result.myItem.photo} alt="" className="w-16 h-16 rounded-xl object-cover flex-shrink-0" />
                    ) : (
                      <div className="w-16 h-16 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                        <Package className="w-6 h-6 text-muted-foreground" />
                      </div>
                    )}
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-bold text-foreground truncate">{result.myItem.title}</p>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {result.myItem.condition} · Rp{result.myItem.estimatedMin.toLocaleString('id-ID')} - Rp{result.myItem.estimatedMax.toLocaleString('id-ID')}
                      </p>
                    </div>
                    {/* Score badge */}
                    <div className={`flex-shrink-0 w-12 h-12 rounded-full flex flex-col items-center justify-center ${
                      result.myItem.matchScore >= 75 ? 'bg-emerald-100 dark:bg-emerald-900/30' :
                      result.myItem.matchScore >= 50 ? 'bg-amber-100 dark:bg-amber-900/30' :
                      'bg-red-100 dark:bg-red-900/30'
                    }`}>
                      <span className={`text-sm font-bold ${
                        result.myItem.matchScore >= 75 ? 'text-emerald-700 dark:text-emerald-400' :
                        result.myItem.matchScore >= 50 ? 'text-amber-700 dark:text-amber-400' :
                        'text-red-700 dark:text-red-400'
                      }`}>{result.myItem.matchScore}%</span>
                    </div>
                  </div>

                  {/* Reasons */}
                  {result.myItem.reasons.length > 0 && (
                    <div className="mt-3 flex flex-wrap gap-1.5">
                      {result.myItem.reasons.map((r, i) => (
                        <span key={i} className="text-[10px] bg-primary/10 text-primary px-2 py-1 rounded-full font-medium">
                          {r}
                        </span>
                      ))}
                    </div>
                  )}
                </div>

                {/* AI Explanation */}
                {result.aiExplanation && (
                  <div className="border-t border-border pt-4">
                    <div className="flex items-center gap-2 mb-2">
                      <Lightbulb className="w-4 h-4 text-primary" />
                      <span className="font-semibold text-sm">Analisis AI</span>
                    </div>
                    <p className="text-xs text-muted-foreground leading-relaxed">{result.aiExplanation}</p>
                  </div>
                )}

                {/* Action buttons */}
                <div className="flex gap-2">
                  <button
                    onClick={async () => {
                      if (!result.myItem) return;
                      setSubmitting(true);
                      try {
                        const res = await createBarterOffer({
                          targetItemId: itemId,
                          offeredItemId: result.myItem.id,
                        });
                        toast.success('Penawaran barter terkirim!');
                        navigate(`/barter/${res.barterId}`);
                      } catch (e: any) {
                        toast.error(cleanError(e, 'Gagal mengirim penawaran'));
                      }
                      setSubmitting(false);
                    }}
                    disabled={submitting}
                    className="flex-1 bg-primary text-primary-foreground rounded-xl py-3 flex items-center justify-center gap-2 font-semibold text-sm active:scale-[0.98] transition-transform disabled:opacity-60"
                  >
                    {submitting ? (
                      <>
                        <MutariInline size={16} />
                        Mengirim...
                      </>
                    ) : (
                      <>
                        <ArrowRightLeft className="w-4 h-4" />
                        Tukar Sekarang
                      </>
                    )}
                  </button>
                  <button
                    onClick={handleAiMikro}
                    className="px-4 py-3 rounded-xl border border-border text-foreground text-sm font-medium"
                  >
                    Ulang
                  </button>
                </div>
              </>
            ) : (
              /* No items found */
              <div className="text-center py-6">
                <div className="w-16 h-16 mx-auto rounded-full bg-amber-50 dark:bg-amber-900/20 flex items-center justify-center mb-3">
                  <SearchX className="w-8 h-8 text-amber-500" />
                </div>
                <p className="text-sm font-bold text-foreground mb-1.5">Tidak Ada Pasangan yang Sepadan</p>
                <p className="text-xs text-muted-foreground leading-relaxed mb-2 max-w-[280px] mx-auto">
                  Saat ini belum ada barang lain yang setara nilainya dengan barang ini. Kamu bisa upload barang milikmu agar AI bisa mencocokkan di lain waktu.
                </p>
                {result.aiExplanation && (
                  <div className="bg-muted/50 rounded-lg p-3 mb-4 mx-2">
                    <div className="flex items-center gap-1.5 justify-center mb-1">
                      <Lightbulb className="w-3.5 h-3.5 text-primary" />
                      <span className="text-[10px] font-semibold text-primary">Saran AI</span>
                    </div>
                    <p className="text-[11px] text-muted-foreground leading-relaxed">{result.aiExplanation}</p>
                  </div>
                )}
                <div className="flex gap-2 justify-center">
                  <button
                    onClick={() => navigate('/upload')}
                    className="bg-primary text-primary-foreground rounded-xl px-5 py-3 font-semibold text-sm inline-flex items-center gap-2"
                  >
                    <ArrowRight className="w-4 h-4" />
                    Upload Barang
                  </button>
                  <button
                    onClick={handleAiMikro}
                    className="px-4 py-3 rounded-xl border border-border text-foreground text-sm font-medium"
                  >
                    Coba Lagi
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useState, useEffect } from 'react';
import { useAuth } from 'zitejs/auth';
import { MessageCircle, Send  } from 'lucide-react';
import { getComments, postComment, GetCommentsOutputType } from 'zitejs/api';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';

type Comment = GetCommentsOutputType['comments'][0];

export default function CommentSection({ itemId }: { itemId: string }) {
  const { user } = useAuth();
  const [comments, setComments] = useState<Comment[]>([]);
  const [loading, setLoading] = useState(true);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);

  useEffect(() => {
    getComments({ itemId })
      .then(r => setComments(r.comments))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [itemId]);

  const handleSend = async () => {
    if (!text.trim() || sending) return;
    setSending(true);
    try {
      const c = await postComment({ itemId, content: text.trim() });
      setComments(prev => [c, ...prev]);
      setText('');
    } catch {
      toast.error('Gagal mengirim komentar');
    }
    setSending(false);
  };

  return (
    <div className="px-4 mt-2 mb-4">
      <div className="flex items-center gap-2 mb-3">
        <MessageCircle className="w-4 h-4 text-primary" />
        <p className="font-bold text-sm text-foreground">
          Komentar {comments.length > 0 && <span className="text-muted-foreground font-normal">({comments.length})</span>}
        </p>
      </div>

      {/* Input */}
      <div className="flex gap-2 mb-4">
        {user?.image ? (
          <img src={user.image} alt="" className="w-8 h-8 rounded-full object-cover flex-shrink-0 border border-border" />
        ) : (
          <div className="w-8 h-8 rounded-full bg-primary/10 text-primary flex items-center justify-center flex-shrink-0 text-xs font-bold border border-border">
            {(user?.firstName?.[0] || user?.email?.[0] || 'U').toUpperCase()}
          </div>
        )}
        <div className="flex-1 flex gap-2">
          <input
            value={text}
            onChange={e => setText(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
            placeholder="Tulis komentar..."
            maxLength={500}
            className="flex-1 border border-border rounded-full px-4 py-2 text-sm bg-card text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-colors"
          />
          <button
            onClick={handleSend}
            disabled={!text.trim() || sending}
            className="w-9 h-9 rounded-full bg-primary text-primary-foreground flex items-center justify-center flex-shrink-0 disabled:opacity-40 transition-opacity"
          >
            {sending ? <MutariInline size={16} /> : <Send className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Comments list */}
      {loading ? (
        <div className="flex items-center justify-center py-6">
          <MutariInline size={20} className="text-muted-foreground" />
        </div>
      ) : comments.length === 0 ? (
        <div className="text-center py-6">
          <MessageCircle className="w-8 h-8 text-muted-foreground/30 mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">Belum ada komentar. Jadilah yang pertama!</p>
        </div>
      ) : (
        <div className="space-y-3">
          {comments.map(c => (
            <div key={c.id} className="flex gap-2.5">
              {c.authorImage ? (
                <img src={c.authorImage} alt="" className="w-8 h-8 rounded-full object-cover flex-shrink-0 border border-border" />
              ) : (
                <div className="w-8 h-8 rounded-full bg-muted text-foreground flex items-center justify-center flex-shrink-0 text-xs font-bold">
                  {c.authorName[0]?.toUpperCase() || 'A'}
                </div>
              )}
              <div className="flex-1 min-w-0">
                <div className="flex items-baseline gap-2">
                  <span className="text-xs font-semibold text-foreground">{c.authorName}</span>
                  <span className="text-[10px] text-muted-foreground">
                    {formatDistanceToNow(new Date(c.createdAt), { addSuffix: true, locale: idLocale })}
                  </span>
                </div>
                <p className="text-sm text-foreground mt-0.5 break-words">{c.content}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Bookmark, BookmarkCheck, MessageCircle, Sparkles, Repeat, ArrowRight, X, Clock, MessageSquare, ScanSearch, ArrowRightLeft, Zap } from 'lucide-react';
import { toggleWishlist, getWishlist, checkItemBarter, CheckItemBarterOutputType, analyzeWithGemini, AnalyzeWithGeminiOutputType, superLikeItem } from 'zitejs/api';
import { useAuth, loginWithRedirect } from 'zitejs/auth';
import { toast } from 'sonner';

interface Props {
  itemId: string;
  itemTitle?: string;
  ownerName?: string;
  ownerId?: string;
  itemPhoto?: string;
}

type ActiveBarter = NonNullable<CheckItemBarterOutputType['activeBarter']>;

export default function DetailBottomBar({ itemId, itemTitle, ownerName, ownerId, itemPhoto }: Props) {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [saved, setSaved] = useState(false);
  const [saving, setSaving] = useState(false);
  const [checkedInitial, setCheckedInitial] = useState(false);
  const [activeBarter, setActiveBarter] = useState<ActiveBarter | null>(null);
  const [showNegoSheet, setShowNegoSheet] = useState(false);
  const [showAiSheet, setShowAiSheet] = useState(false);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiData, setAiData] = useState<AnalyzeWithGeminiOutputType | null>(null);
  const [superLiking, setSuperLiking] = useState(false);
  const [superLiked, setSuperLiked] = useState(false);

  // Check if item is already in wishlist on mount
  useEffect(() => {
    if (!user) return;
    getWishlist({}).then(res => {
      const isSaved = res.items.some(i => i.itemId === itemId);
      setSaved(isSaved);
      setCheckedInitial(true);
    }).catch(() => setCheckedInitial(true));
  }, [user, itemId]);

  // Check active barter for this item
  useEffect(() => {
    if (!user) return;
    checkItemBarter({ itemId }).then(res => {
      setActiveBarter(res.activeBarter ?? null);
    }).catch(() => {});
  }, [user, itemId]);

  const requireAuth = (action: () => void) => {
    if (!user) {
      loginWithRedirect();
      return;
    }
    action();
  };

  const handleSave = async () => {
    requireAuth(async () => {
      setSaving(true);
      try {
        const res = await toggleWishlist({ itemId });
        setSaved(res.saved);
        toast.success(res.saved ? 'Tersimpan di wishlist' : 'Dihapus dari wishlist');
      } catch {
        toast.error('Gagal menyimpan');
      }
      setSaving(false);
    });
  };

  const handleChat = () => {
    requireAuth(() => {
      if (ownerId) {
        navigate(`/direct-chat?userId=${ownerId}&itemId=${itemId}&itemTitle=${encodeURIComponent(itemTitle || 'Barang')}`);
      } else {
        navigate('/chat', { state: { fromItem: itemId, itemTitle, ownerName } });
      }
    });
  };

  const handleBarter = () => {
    requireAuth(() => {
      if (activeBarter) {
        // Show negotiation sheet
        setShowNegoSheet(true);
      } else {
        navigate(`/barter-offer?targetItemId=${itemId}&targetTitle=${encodeURIComponent(itemTitle || 'Barang')}`);
      }
    });
  };

  // Don't show bottom bar for own items
  const isOwnItem = user && ownerId && user.id === ownerId;
  if (isOwnItem) return null;

  const statusLabel = activeBarter?.status === 'Menunggu' ? 'Menunggu Respon' : 'Sedang Negosiasi';
  const statusColor = activeBarter?.status === 'Menunggu' ? 'text-amber-600 bg-amber-50' : 'text-blue-600 bg-blue-50';

  const handleSuperLike = async () => {
    requireAuth(async () => {
      if (superLiked) return;
      setSuperLiking(true);
      try {
        await superLikeItem({ itemId });
        setSuperLiked(true);
        toast.success('⚡ Super Like terkirim! Pemilik akan menerima notifikasi prioritas.');
      } catch (e: any) {
        const msg = e?.message || '';
        if (msg.toLowerCase().includes('poin tidak cukup') || msg.toLowerCase().includes('butuh')) {
          toast.error('Poin tidak mencukupi, kunjungi wallet anda', {
            action: {
              label: 'Ke Wallet',
              onClick: () => navigate('/wallet'),
            },
          });
        } else if (msg.toLowerCase().includes('barang sendiri')) {
          toast.error('Tidak bisa Super Like barang sendiri');
        } else {
          toast.error('Gagal mengirim Super Like');
        }
      }
      setSuperLiking(false);
    });
  };

  const handleAiCheck = async () => {
    if (!itemPhoto) {
      toast.error('Barang ini tidak memiliki foto');
      return;
    }
    setShowAiSheet(true);
    if (aiData) return; // already loaded
    setAiLoading(true);
    try {
      const res = await analyzeWithGemini({ imageUrl: itemPhoto });
      setAiData(res);
    } catch {
      toast.error('Gagal menganalisis dengan AI');
    }
    setAiLoading(false);
  };

  return (
    <>
      <div className="fixed bottom-0 left-0 right-0 bg-card/95 backdrop-blur-md border-t border-border z-50">
        <div className="max-w-[420px] mx-auto px-3 py-2.5 flex gap-2">
          {/* Save */}
          <button
            onClick={handleSave}
            disabled={saving}
            className={`flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl border transition-all active:scale-95 ${
              saved ? 'bg-primary/10 border-primary/30' : 'border-border bg-card hover:bg-muted/50'
            }`}
          >
            {saving ? (
              <MutariInline size={20} />
            ) : saved ? (
              <BookmarkCheck className="w-5 h-5 text-primary" />
            ) : (
              <Bookmark className="w-5 h-5 text-foreground" />
            )}
            <span className={`text-[10px] ${saved ? 'text-primary font-semibold' : 'text-foreground'}`}>
              {saved ? 'Tersimpan' : 'Simpan'}
            </span>
          </button>

          {/* Chat */}
          <button
            onClick={handleChat}
            className="flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl border border-border bg-card hover:bg-muted/50 transition-all active:scale-95"
          >
            <MessageCircle className="w-5 h-5 text-foreground" />
            <span className="text-[10px] text-foreground">Chat</span>
          </button>

          {/* Super Like */}
          <button
            onClick={handleSuperLike}
            disabled={superLiking || superLiked}
            className={`flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl border transition-all active:scale-95 ${
              superLiked
                ? 'bg-amber-500/15 border-amber-400/40'
                : 'border-amber-300/50 bg-card hover:bg-amber-50'
            }`}
          >
            {superLiking ? (
              <MutariInline size={20} />
            ) : (
              <Zap className={`w-5 h-5 ${superLiked ? 'text-amber-500 fill-amber-500' : 'text-amber-500'}`} />
            )}
            <span className={`text-[10px] ${superLiked ? 'text-amber-600 font-semibold' : 'text-amber-600'}`}>
              {superLiked ? 'Terkirim' : 'Super'}
            </span>
          </button>

          {/* AI */}
          <button
            onClick={() => requireAuth(() => handleAiCheck())}
            className="flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl bg-accent border border-primary/20 hover:bg-accent/80 transition-all active:scale-95"
          >
            {aiLoading ? (
              <MutariInline size={20} />
            ) : (
              <Sparkles className="w-5 h-5 text-primary" />
            )}
            <span className="text-[10px] text-primary font-semibold">AI</span>
          </button>

          {/* Barter */}
          <button
            onClick={handleBarter}
            className={`flex-1 flex flex-col items-center gap-0.5 py-2.5 rounded-xl transition-all active:scale-95 relative ${
              activeBarter
                ? 'bg-amber-500 hover:bg-amber-500/90'
                : 'bg-primary hover:bg-primary/90'
            }`}
          >
            {activeBarter && (
              <span className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-destructive border-2 border-card animate-pulse" />
            )}
            <Repeat className="w-5 h-5 text-primary-foreground" />
            <span className="text-[10px] text-primary-foreground font-semibold">
              {activeBarter ? 'Nego' : 'Barter'}
            </span>
          </button>
        </div>
      </div>

      {/* Negotiation Sheet */}
      {showNegoSheet && activeBarter && (
        <div className="fixed inset-0 z-[60] flex items-end justify-center">
          {/* Backdrop */}
          <div className="absolute inset-0 bg-black/50" onClick={() => setShowNegoSheet(false)} />

          {/* Sheet */}
          <div className="relative w-full max-w-[420px] bg-card rounded-t-2xl border-t border-border animate-in slide-in-from-bottom duration-300 pb-[env(safe-area-inset-bottom)]">
            {/* Handle */}
            <div className="flex justify-center pt-3 pb-1">
              <div className="w-10 h-1 rounded-full bg-border" />
            </div>

            {/* Header */}
            <div className="px-4 pb-3 flex items-center justify-between">
              <h3 className="font-bold text-base">Negosiasi Aktif</h3>
              <button onClick={() => setShowNegoSheet(false)} className="p-1.5 rounded-full hover:bg-muted">
                <X className="w-4 h-4 text-muted-foreground" />
              </button>
            </div>

            {/* Status badge */}
            <div className="px-4 pb-3">
              <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold ${statusColor}`}>
                <Clock className="w-3.5 h-3.5" />
                {statusLabel}
              </div>
            </div>

            {/* Barter info card */}
            <div className="mx-4 mb-3 p-3 rounded-xl border border-border bg-muted/30">
              <p className="text-xs text-muted-foreground mb-2">Sedang ditukar dengan:</p>
              <div className="flex items-center gap-3">
                {activeBarter.otherItemPhoto ? (
                  <img src={activeBarter.otherItemPhoto} alt="" className="w-14 h-14 rounded-lg object-cover flex-shrink-0" />
                ) : (
                  <div className="w-14 h-14 rounded-lg bg-muted flex items-center justify-center flex-shrink-0">
                    <Repeat className="w-5 h-5 text-muted-foreground" />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <p className="font-semibold text-sm truncate">{activeBarter.otherItemTitle}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {activeBarter.role === 'initiator' ? 'Kamu yang mengajukan' : `Diajukan oleh ${activeBarter.otherUserName}`}
                  </p>
                </div>
              </div>
            </div>

            {/* Action buttons */}
            <div className="px-4 pb-4 space-y-2">
              {/* Go to negotiation */}
              <button
                onClick={() => {
                  setShowNegoSheet(false);
                  navigate(`/barter/${activeBarter.barterId}`);
                }}
                className="w-full flex items-center justify-between px-4 py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm active:scale-[0.98] transition"
              >
                <div className="flex items-center gap-2">
                  <MessageSquare className="w-4 h-4" />
                  <span>Lanjutkan Negosiasi</span>
                </div>
                <ArrowRight className="w-4 h-4" />
              </button>

              {/* Cancel barter (only if user is initiator and status is Menunggu) */}
              {activeBarter.role === 'initiator' && activeBarter.status === 'Menunggu' && (
                <button
                  onClick={() => {
                    setShowNegoSheet(false);
                    navigate(`/barter/${activeBarter.barterId}`);
                  }}
                  className="w-full flex items-center justify-center gap-2 px-4 py-3 rounded-xl border border-destructive/30 text-destructive text-sm font-medium hover:bg-destructive/5 active:scale-[0.98] transition"
                >
                  <X className="w-4 h-4" />
                  <span>Batalkan Penawaran</span>
                </button>
              )}

              {/* Close */}
              <button
                onClick={() => setShowNegoSheet(false)}
                className="w-full py-2.5 text-sm text-muted-foreground font-medium"
              >
                Tutup
              </button>
            </div>
          </div>
        </div>
      )}
      {/* AI Mikro Sheet */}
      {showAiSheet && (
        <div className="fixed inset-0 z-[60] flex items-end justify-center">
          <div className="absolute inset-0 bg-black/50" onClick={() => setShowAiSheet(false)} />
          <div className="relative w-full max-w-[420px] bg-card rounded-t-2xl border-t border-border animate-in slide-in-from-bottom duration-300 pb-[env(safe-area-inset-bottom)] max-h-[80vh] overflow-y-auto">
            <div className="sticky top-0 bg-card z-10">
              <div className="flex justify-center pt-3 pb-1">
                <div className="w-10 h-1 rounded-full bg-border" />
              </div>
              <div className="px-4 pb-3 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <ScanSearch className="w-5 h-5 text-primary" />
                  <h3 className="font-bold text-base">AI Mikro — Analisis Gemini</h3>
                </div>
                <button onClick={() => setShowAiSheet(false)} className="p-1.5 rounded-full hover:bg-muted">
                  <X className="w-4 h-4 text-muted-foreground" />
                </button>
              </div>
            </div>

            {aiLoading ? (
              <div className="flex flex-col items-center gap-3 py-12">
                <MutariInline size={32} />
                <p className="text-sm text-muted-foreground">Menganalisis foto dengan Gemini...</p>
              </div>
            ) : aiData ? (
              <div className="px-4 pb-4 space-y-4">
                {/* Analisis */}
                <div className="bg-primary/5 border border-primary/30 rounded-xl p-4">
                  <div className="flex items-center gap-2 mb-2">
                    <Sparkles className="w-4 h-4 text-primary" />
                    <p className="text-sm font-bold text-primary">Hasil Analisis</p>
                  </div>
                  <p className="text-sm text-foreground whitespace-pre-wrap leading-relaxed">{aiData.analysis}</p>
                </div>

                {/* Kisaran Harga */}
                {aiData.estimatedMinPrice > 0 && (
                  <div className="bg-accent/60 border border-border rounded-xl p-4">
                    <p className="text-xs font-semibold text-muted-foreground mb-1">Kisaran Harga AI</p>
                    <p className="text-lg font-bold text-foreground">
                      Rp {aiData.estimatedMinPrice.toLocaleString('id-ID')} — Rp {aiData.estimatedMaxPrice.toLocaleString('id-ID')}
                    </p>
                  </div>
                )}

                {/* Match Barter */}
                {aiData.matches.length > 0 && (
                  <div>
                    <div className="flex items-center gap-2 mb-3">
                      <ArrowRightLeft className="w-4 h-4 text-primary" />
                      <p className="text-sm font-bold text-foreground">Pasangan Barter Ditemukan! 🎉</p>
                      <span className="text-[10px] bg-green-500/10 text-green-600 px-2 py-0.5 rounded-full font-semibold">
                        {aiData.matches.length} cocok
                      </span>
                    </div>
                    <p className="text-xs text-muted-foreground mb-3">Barang berikut memiliki nilai yang sepadan untuk ditukar:</p>
                    <div className="space-y-2">
                      {aiData.matches.map(m => (
                        <div key={m.id} className="bg-card border border-border rounded-xl overflow-hidden shadow-sm">
                          <button
                            onClick={() => { setShowAiSheet(false); navigate(`/item/${m.id}`); }}
                            className="w-full flex items-center gap-3 p-3 text-left hover:bg-muted/50 transition-colors"
                          >
                            {m.photo ? (
                              <img src={m.photo} alt="" className="w-14 h-14 rounded-lg object-cover flex-shrink-0" />
                            ) : (
                              <div className="w-14 h-14 rounded-lg bg-muted flex-shrink-0" />
                            )}
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-semibold text-foreground truncate">{m.title}</p>
                              <p className="text-xs text-muted-foreground">{m.condition} · {m.location}</p>
                              <p className="text-xs font-semibold text-primary mt-0.5">
                                Rp {m.estimatedMin.toLocaleString('id-ID')} - Rp {m.estimatedMax.toLocaleString('id-ID')}
                              </p>
                            </div>
                            <span className="text-[10px] bg-green-500/10 text-green-600 px-2 py-1 rounded-full font-semibold flex-shrink-0">
                              Match
                            </span>
                          </button>
                          <div className="px-3 pb-3">
                            <button
                              onClick={() => {
                                setShowAiSheet(false);
                                navigate(`/barter-offer?targetItemId=${m.id}&targetTitle=${encodeURIComponent(m.title)}`);
                              }}
                              className="w-full flex items-center justify-center gap-2 py-2.5 rounded-lg bg-primary text-primary-foreground font-semibold text-sm active:scale-[0.98] transition-transform"
                            >
                              <Repeat className="w-4 h-4" />
                              Tukar Sekarang
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {aiData.matches.length === 0 && aiData.estimatedMinPrice > 0 && (
                  <div className="text-center py-5 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-200 dark:border-amber-800/30">
                    <div className="w-12 h-12 mx-auto rounded-full bg-amber-100 dark:bg-amber-900/30 flex items-center justify-center mb-2">
                      <ArrowRightLeft className="w-6 h-6 text-amber-500" />
                    </div>
                    <p className="text-sm font-bold text-foreground mb-1">Tidak Ada Pasangan yang Sepadan</p>
                    <p className="text-xs text-muted-foreground max-w-[260px] mx-auto leading-relaxed">
                      Belum ada barang lain yang setara nilainya untuk ditukar saat ini.
                    </p>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex flex-col items-center gap-3 py-12">
                <p className="text-sm text-muted-foreground">Gagal memuat analisis</p>
              </div>
            )}
          </div>
        </div>
      )}
    </>
  );
}

import { useState } from 'react';
import { ArrowLeft, Share2, Heart, Eye, Clock, Search as ZoomIn, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { formatRelativeDate } from './utils';

interface Props {
  images: string[];
  views: number;
  likes: number;
