import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowRightLeft, AlertCircle, Clock, ChevronRight } from 'lucide-react';
import { getPendingBarters } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

export default function ActiveBarterStatus() {
  const navigate = useNavigate();
  const [totalActive, setTotalActive] = useState(0);
  const [needsAction, setNeedsAction] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getPendingBarters({})
      .then(res => {
        setTotalActive(res.pending.length);
        setNeedsAction(res.pending.filter(b => b.needsMyAction).length);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="px-4 py-1">
        <Skeleton className="h-[72px] rounded-2xl" />
      </div>
    );
  }

  if (totalActive === 0) return null;

  const hasUrgent = needsAction > 0;

  return (
    <div className="px-4 py-1">
      <button
        onClick={() => navigate('/barter-history')}
        className={`w-full rounded-2xl p-4 text-left flex items-center gap-3 shadow-sm hover:shadow-md transition-shadow border ${
          hasUrgent
            ? 'bg-amber-50 dark:bg-amber-500/5 border-amber-200 dark:border-amber-500/20'
            : 'bg-card border-border'
        }`}
      >
        <div className={`w-11 h-11 rounded-xl flex items-center justify-center flex-shrink-0 ${
          hasUrgent
            ? 'bg-amber-100 dark:bg-amber-500/15'
            : 'bg-primary/10'
        }`}>
          <ArrowRightLeft className={`w-5 h-5 ${
            hasUrgent ? 'text-amber-600 dark:text-amber-400' : 'text-primary'
          }`} strokeWidth={1.75} />
        </div>

        <div className="flex-1 min-w-0">
          <p className="font-bold text-sm text-foreground">
            {totalActive} Barter Aktif
          </p>
          <div className="flex items-center gap-1.5 mt-0.5">
            {hasUrgent ? (
              <>
                <AlertCircle className="w-3 h-3 text-amber-600 dark:text-amber-400" />
                <span className="text-[11px] font-semibold text-amber-700 dark:text-amber-300">
                  {needsAction} perlu respon kamu
                </span>
              </>
            ) : (
              <>
                <Clock className="w-3 h-3 text-muted-foreground" />
                <span className="text-[11px] text-muted-foreground">
                  Semua menunggu partner
                </span>
              </>
            )}
          </div>
        </div>

        <ChevronRight className={`w-4 h-4 flex-shrink-0 ${
          hasUrgent ? 'text-amber-600 dark:text-amber-400' : 'text-muted-foreground'
        }`} />
      </button>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Star, ChevronRight, MessageSquareQuote } from 'lucide-react';
import { useAuth } from 'zitejs/auth';
import { getUserReviews, GetUserReviewsOutputType } from 'zitejs/api';
import { formatDistanceToNow } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import { Skeleton } from '@project/components/ui/skeleton';

type Review = GetUserReviewsOutputType['reviews'][0];

function Stars({ rating }: { rating: number }) {
  return (
    <div className="flex gap-0.5">
      {[1, 2, 3, 4, 5].map(i => (
        <Star
          key={i}
          className={`w-3 h-3 ${i <= rating ? 'text-amber-400 fill-amber-400' : 'text-muted-foreground/30'}`}
        />
      ))}
    </div>
  );
}

function ReviewCard({ review }: { review: Review }) {
  const timeAgo = review.createdAt
    ? formatDistanceToNow(new Date(review.createdAt), { addSuffix: true, locale: idLocale })
    : '';

  return (
    <div className="bg-card border border-border rounded-2xl p-3.5 shadow-sm">
      {/* Reviewer info */}
      <div className="flex items-center gap-2.5 mb-2">
        <div className="w-8 h-8 rounded-full overflow-hidden bg-muted flex-shrink-0">
          {review.reviewerImage ? (
            <img src={review.reviewerImage} alt="" className="w-full h-full object-cover" />
          ) : (
            <div className="w-full h-full bg-primary/15 flex items-center justify-center text-[11px] font-bold text-primary">
              {review.reviewerName.charAt(0).toUpperCase()}
            </div>
          )}
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-xs font-semibold text-foreground truncate">{review.reviewerName}</p>
          <div className="flex items-center gap-2">
            <Stars rating={review.rating} />
            <span className="text-[10px] text-muted-foreground">{timeAgo}</span>
          </div>
        </div>
      </div>

      {/* Comment */}
      {review.comment && (
        <p className="text-xs text-muted-foreground leading-relaxed line-clamp-2">
          "{review.comment}"
        </p>
      )}

      {/* Aspect badge */}
      {review.aspect && (
        <span className="inline-block mt-2 px-2 py-0.5 rounded-full bg-primary/10 text-primary text-[10px] font-medium">
          {review.aspect}
        </span>
      )}
    </div>
  );
}

export default function RecentReviews() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [reviews, setReviews] = useState<Review[]>([]);
  const [total, setTotal] = useState(0);
  const [avg, setAvg] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user) return;
    getUserReviews({ userId: user.id })
      .then(res => {
        // Sort by date desc, take latest 3
        const sorted = [...res.reviews].sort((a, b) =>
          new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime()
        );
        setReviews(sorted.slice(0, 1));
        setTotal(res.totalReviews);
        setAvg(res.averageRating);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [user]);

  if (loading) {
    return (
      <div className="px-4 py-3">
        <div className="flex items-center gap-2 mb-3">
          <Skeleton className="w-8 h-8 rounded-xl" />
          <Skeleton className="h-4 w-28" />
        </div>
        <Skeleton className="h-24 rounded-2xl" />
      </div>
    );
  }

  if (total === 0) return null;

  return (
    <div className="px-4 py-3">
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-xl bg-amber-100 dark:bg-amber-500/15 flex items-center justify-center">
            <MessageSquareQuote className="w-4 h-4 text-amber-600 dark:text-amber-400" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-foreground">Review Terbaru</h3>
            <p className="text-[10px] text-muted-foreground">
              ⭐ {avg}/5 dari {total} review
            </p>
          </div>
        </div>
        <button
          onClick={() => navigate('/my-public-profile')}
          className="flex items-center gap-0.5 text-[11px] text-primary font-semibold"
        >
          Semua
          <ChevronRight className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Review cards */}
      <div className="space-y-2">
        {reviews.map(r => (
          <ReviewCard key={r.id} review={r} />
        ))}
      </div>
    </div>
  );
}

