import { useState, useRef, useCallback } from 'react';
import Webcam from 'react-webcam';
import { Camera, X, Check, RotateCcw, Trash2, ChevronLeft } from 'lucide-react';

interface Props {
  maxPhotos: number;
  onConfirm: (files: File[]) => void;
  onClose: () => void;
  lang?: 'id' | 'en';
}

export default function LiveCamera({ maxPhotos, onConfirm, onClose, lang = 'id' }: Props) {
  const webcamRef = useRef<Webcam>(null);
  const [facingMode, setFacingMode] = useState<'environment' | 'user'>('environment');
  const [captures, setCaptures] = useState<{ dataUrl: string }[]>([]);
  const [previewIdx, setPreviewIdx] = useState<number | null>(null);

  const remaining = maxPhotos - captures.length;

  const takePhoto = useCallback(() => {
    if (remaining <= 0) return;
    const src = webcamRef.current?.getScreenshot();
    if (src) {
      setCaptures(prev => [...prev, { dataUrl: src }]);
    }
  }, [remaining]);

  const removeCapture = (idx: number) => {
    setCaptures(prev => prev.filter((_, i) => i !== idx));
    setPreviewIdx(null);
  };

  const flipCamera = () => {
    setFacingMode(prev => prev === 'environment' ? 'user' : 'environment');
  };

  const handleConfirm = async () => {
    const files: File[] = [];
    for (let i = 0; i < captures.length; i++) {
      const res = await fetch(captures[i].dataUrl);
      const blob = await res.blob();
      files.push(new File([blob], `camera-${Date.now()}-${i}.jpg`, { type: 'image/jpeg' }));
    }
    onConfirm(files);
  };

  // Full-screen preview of a single capture
  if (previewIdx !== null && captures[previewIdx]) {
    return (
      <div className="fixed inset-0 z-[60] bg-black flex flex-col">
        <div className="flex items-center justify-between p-4">
          <button onClick={() => setPreviewIdx(null)} className="text-white">
            <ChevronLeft className="w-6 h-6" />
          </button>
          <span className="text-white text-sm font-medium">
            {lang === 'id' ? `Foto ${previewIdx + 1}` : `Photo ${previewIdx + 1}`}
          </span>
          <button onClick={() => removeCapture(previewIdx)} className="text-red-400">
            <Trash2 className="w-5 h-5" />
          </button>
        </div>
        <div className="flex-1 flex items-center justify-center p-4">
          <img src={captures[previewIdx].dataUrl} alt="" className="max-w-full max-h-full rounded-xl object-contain" />
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[60] bg-black flex flex-col">
      {/* Top bar */}
      <div className="flex items-center justify-between p-4 relative z-10">
        <button onClick={onClose} className="w-10 h-10 rounded-full bg-black/50 flex items-center justify-center">
          <X className="w-5 h-5 text-white" />
        </button>
        <div className="text-white text-sm font-medium">
          {captures.length}/{maxPhotos} {lang === 'id' ? 'foto' : 'photos'}
        </div>
        <button onClick={flipCamera} className="w-10 h-10 rounded-full bg-black/50 flex items-center justify-center">
          <RotateCcw className="w-5 h-5 text-white" />
        </button>
      </div>

      {/* Camera viewfinder */}
      <div className="flex-1 relative overflow-hidden">
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          screenshotQuality={0.85}
          videoConstraints={{ facingMode, width: { ideal: 1280 }, height: { ideal: 960 } }}
          className="w-full h-full object-cover"
        />
      </div>

      {/* Bottom controls */}
      <div className="bg-black/80 pb-safe">
        {/* Thumbnail strip */}
        {captures.length > 0 && (
          <div className="flex gap-2 px-4 pt-3 overflow-x-auto no-scrollbar">
            {captures.map((c, i) => (
              <button
                key={i}
                onClick={() => setPreviewIdx(i)}
                className="relative w-14 h-14 rounded-lg overflow-hidden flex-shrink-0 border-2 border-white/30"
              >
                <img src={c.dataUrl} alt="" className="w-full h-full object-cover" />
                <span className="absolute bottom-0 left-0 right-0 bg-black/60 text-white text-[8px] text-center py-0.5 font-bold">
                  {i + 1}
                </span>
              </button>
            ))}
          </div>
        )}

        {/* Shutter + confirm */}
        <div className="flex items-center justify-center gap-8 py-4 px-4">
          {/* Confirm button (left) */}
          <div className="w-16 flex justify-center">
            {captures.length > 0 && (
              <button
                onClick={handleConfirm}
                className="flex flex-col items-center gap-1"
              >
                <div className="w-12 h-12 rounded-full bg-emerald-500 flex items-center justify-center">
                  <Check className="w-6 h-6 text-white" />
                </div>
                <span className="text-[10px] text-emerald-400 font-semibold">
                  {lang === 'id' ? 'Selesai' : 'Done'}
                </span>
              </button>
            )}
          </div>

          {/* Shutter button (center) */}
          <button
            onClick={takePhoto}
            disabled={remaining <= 0}
            className="w-[72px] h-[72px] rounded-full border-4 border-white flex items-center justify-center disabled:opacity-30 active:scale-90 transition-transform"
          >
            <div className="w-[60px] h-[60px] rounded-full bg-white flex items-center justify-center">
              <Camera className="w-7 h-7 text-black" />
            </div>
          </button>

          {/* Counter (right) */}
          <div className="w-16 flex justify-center">
            {remaining > 0 ? (
              <span className="text-xs text-white/60">
                {lang === 'id' ? `sisa ${remaining}` : `${remaining} left`}
              </span>
            ) : (
              <span className="text-xs text-amber-400 font-semibold">
                {lang === 'id' ? 'Penuh' : 'Full'}
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import { MutariInline } from '../MutariSpinner';
import { useEffect, useCallback } from 'react';
import { MapPin, RefreshCw } from 'lucide-react';

interface Props {
  value: string;
  onChange: (v: string) => void;
  loading: boolean;
  onLoadingChange: (v: boolean) => void;
}

export default function LocationAuto({ value, onChange, loading, onLoadingChange }: Props) {
  const detect = useCallback(async () => {
    if (!navigator.geolocation) {
      onChange('Lokasi tidak tersedia');
      return;
    }
    onLoadingChange(true);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&accept-language=id`
          );
          const data = await res.json();
          const addr = data.address || {};
          const parts = [
            addr.suburb || addr.village || addr.town || addr.city_district,
            addr.city || addr.county,
            addr.state,
          ].filter(Boolean);
          onChange(parts.join(', '));
        } catch {
          onChange(`${latitude.toFixed(4)}, ${longitude.toFixed(4)}`);
        }
        onLoadingChange(false);
      },
      () => {
        onChange('Gagal mendeteksi lokasi');
        onLoadingChange(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, [onChange, onLoadingChange]);

  useEffect(() => {
    detect();
  }, [detect]);

  return (
    <div>
      <p className="text-sm font-semibold text-foreground mb-2">Lokasi</p>
      <div className="form-input flex items-center gap-3 bg-muted/50">
        {loading ? (
          <MutariInline size={16} className="flex-shrink-0" />
        ) : (
          <MapPin className="w-4 h-4 text-primary flex-shrink-0" />
        )}
        <span className={`flex-1 text-sm ${value ? 'text-foreground' : 'text-muted-foreground'}`}>
          {loading ? 'Mendeteksi lokasi...' : value || 'Menunggu GPS...'}
        </span>
        {!loading && (
          <button type="button" onClick={detect} className="text-primary">
            <RefreshCw className="w-4 h-4" />
          </button>
        )}
      </div>
      <p className="text-[11px] text-muted-foreground mt-1">Otomatis terdeteksi dari GPS perangkatmu</p>
    </div>
  );
}

