import { Plus } from 'lucide-react';

interface Spec { label: string; value: string }

interface Props {
  specs: Spec[];
  onChange: (specs: Spec[]) => void;
}

export default function SpecRows({ specs, onChange }: Props) {
  const update = (i: number, field: 'label' | 'value', val: string) => {
    const next = [...specs];
    next[i] = { ...next[i], [field]: val };
    onChange(next);
  };

  return (
    <div>
      <p className="text-sm font-semibold text-foreground mb-2">Spesifikasi</p>
      <div className="space-y-2">
        {specs.map((s, i) => (
          <div key={i} className="flex gap-2">
            <input
              value={s.label}
              onChange={e => update(i, 'label', e.target.value)}
              placeholder="Label (mis. Kapasitas)"
              className="form-input flex-1"
            />
            <input
              value={s.value}
              onChange={e => update(i, 'value', e.target.value)}
              placeholder="Nilai (mis. 256GB)"
              className="form-input flex-1"
            />
          </div>
        ))}
      </div>
      <button
        type="button"
        onClick={() => onChange([...specs, { label: '', value: '' }])}
        className="flex items-center gap-1.5 text-sm font-semibold text-primary mt-2"
      >
        <Plus className="w-4 h-4" /> Tambah spesifikasi
      </button>
    </div>
  );
}

