import { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';

interface LocationData {
  kecamatan: string;
  kabupaten: string;
  lat: number;
  lng: number;
}

interface LocationContextType {
  location: LocationData | null;
  loading: boolean;
  error: string | null;
  radius: number;
  setRadius: (r: number) => void;
  detectLocation: () => void;
  granted: boolean;
}

const STORAGE_KEY = 'mutari-location';

function loadCached(): { location: LocationData; granted: true } | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed.lat === 'number') {
      return { location: parsed as LocationData, granted: true };
    }
  } catch { /* ignore */ }
  return null;
}

const LocationContext = createContext<LocationContextType | null>(null);

export function useLocation() {
  const ctx = useContext(LocationContext);
  if (!ctx) throw new Error('useLocation must be inside LocationProvider');
  return ctx;
}

export function LocationProvider({ children }: { children: ReactNode }) {
  const cached = loadCached();
  const [location, setLocation] = useState<LocationData | null>(cached?.location ?? null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [radius, setRadius] = useState(10);
  const [granted, setGranted] = useState(cached?.granted ?? false);

  const detectLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setError('GPS tidak didukung di perangkat ini');
      return;
    }
    setLoading(true);
    setError(null);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&accept-language=id`
          );
          const data = await res.json();
          const addr = data.address || {};
          const loc: LocationData = {
            kecamatan: addr.suburb || addr.village || addr.town || addr.city_district || '',
            kabupaten: addr.city || addr.county || addr.state || '',
            lat: latitude,
            lng: longitude,
          };
          setLocation(loc);
          setGranted(true);
          localStorage.setItem(STORAGE_KEY, JSON.stringify(loc));
        } catch {
          const loc: LocationData = {
            kecamatan: '',
            kabupaten: `${latitude.toFixed(4)}, ${longitude.toFixed(4)}`,
            lat: latitude,
            lng: longitude,
          };
          setLocation(loc);
          setGranted(true);
          localStorage.setItem(STORAGE_KEY, JSON.stringify(loc));
        }
        setLoading(false);
      },
      () => {
        setError('Izin lokasi ditolak. Aktifkan GPS di pengaturan perangkat kamu.');
        setGranted(false);
        localStorage.removeItem(STORAGE_KEY);
        setLoading(false);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  // On mount: if we have a cached location, still refresh in the background but don't block
  useEffect(() => {
    if (!granted) {
      // No cache — need to detect before showing app
      detectLocation();
    } else {
      // Have cache — silently refresh location in background
      detectLocation();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <LocationContext.Provider value={{ location, loading, error, radius, setRadius, detectLocation, granted }}>
      {children}
    </LocationContext.Provider>
  );
}

