import { createContext, useContext, useState, useCallback, useEffect } from 'react';

interface RefreshContextValue {
  /** Increments silently — components re-fetch without remounting */
  tick: number;
  /** Call to trigger a silent refresh of all subscribed components */
  refresh: () => void;
}

const RefreshContext = createContext<RefreshContextValue>({ tick: 0, refresh: () => {} });

export function useRefresh() {
  return useContext(RefreshContext);
}

export function RefreshProvider({ children }: { children: React.ReactNode }) {
  const [tick, setTick] = useState(0);

  const refresh = useCallback(() => {
    setTick(t => t + 1);
  }, []);

  // Auto-refresh every 90s (silent, no flash)
  useEffect(() => {
    const id = setInterval(refresh, 90_000);
    const onVisibility = () => {
      if (document.visibilityState === 'visible') refresh();
    };
    document.addEventListener('visibilitychange', onVisibility);
    return () => {
      clearInterval(id);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [refresh]);

  return (
    <RefreshContext.Provider value={{ tick, refresh }}>
      {children}
    </RefreshContext.Provider>
  );
}

