import { useCallback, useSyncExternalStore } from 'react';

const STORAGE_KEY = 'mutari-recently-viewed';
const MAX_ITEMS = 20;

export interface RecentItem {
  id: string;
  title: string;
  photo: string | null;
  category?: string;
  location?: string;
  viewedAt: number;
}

// Simple pub-sub so multiple components stay in sync within the same tab
let listeners: Array<() => void> = [];
function emitChange() {
  listeners.forEach(l => l());
}

function getSnapshot(): RecentItem[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

let cachedItems: RecentItem[] = getSnapshot();

function subscribe(cb: () => void) {
  listeners.push(cb);
  return () => {
    listeners = listeners.filter(l => l !== cb);
  };
}

function getSnapshotCached() {
  return cachedItems;
}

export function useRecentlyViewed() {
  const items = useSyncExternalStore(subscribe, getSnapshotCached);

  const addItem = useCallback((item: Omit<RecentItem, 'viewedAt'>) => {
    const current = getSnapshot();
    // Remove duplicate
    const filtered = current.filter(i => i.id !== item.id);
    const updated: RecentItem[] = [
      { ...item, viewedAt: Date.now() },
      ...filtered,
    ].slice(0, MAX_ITEMS);

    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    cachedItems = updated;
    emitChange();
  }, []);

  const clearAll = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY);
    cachedItems = [];
    emitChange();
  }, []);

  return { items, addItem, clearAll };
}

