@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/* Form input base style */
.form-input {
  @apply w-full border border-border rounded-xl px-4 py-3 text-sm text-foreground bg-card placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-colors;
}

/* Hide scrollbar for horizontal scroll sections */
.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}

/* ===== RESPONSIVE DESKTOP SUPPORT =====
   On desktop (lg+), the sidebar nav is visible and content
   shifts right. The container widens to fill available space. */

/* Widen the mobile container on larger screens */
@media (min-width: 640px) {
  .max-w-\[420px\] {
    max-width: 100% !important;
  }
}

/* On lg+, offset content for the sidebar */
@media (min-width: 1024px) {
  .mutari-main {
    margin-left: 220px;
  }
}
@media (min-width: 1280px) {
  .mutari-main {
    margin-left: 240px;
  }
}

/* Item grids: more columns on bigger screens */
@media (min-width: 640px) {
  .mutari-item-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  }
}
@media (min-width: 1024px) {
  .mutari-item-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  }
}
@media (min-width: 1440px) {
  .mutari-item-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
  }
}

/* Badge shimmer sweep — holographic shine effect */
@keyframes badgeShimmer {
  0%   { background-position: 250% 0; }
  100% { background-position: -50% 0; }
}

/* Elite MUTARI — smooth gradient ring rotation */
@keyframes eliteRingSpin {
  0%   { filter: hue-rotate(0deg); transform: rotate(0deg); }
  100% { filter: hue-rotate(360deg); transform: rotate(360deg); }
}

/* Mentor MUTARI — slow single-color ring rotation */
@keyframes mentorRingSpin {
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Legenda MUTARI — pulsing golden glow */
@keyframes legendaPulse {
  0%, 100% { opacity: 0.4; transform: scale(1); }
  50%      { opacity: 0.9; transform: scale(1.04); }
}

