// MUTARI Affiliate Tier System
export interface AffiliateTier {
  id: string;
  name: string;
  emoji: string;
  minReferrals: number;
  maxReferrals: number | null;
  pointsPerReferral: number;
  boostSlots: number; // free listing boosts per month
  boostDurationDays: number;
  color: string;
  bgGradient: string;
  borderColor: string;
  description: string;
}

export const AFFILIATE_TIERS: AffiliateTier[] = [
  {
    id: 'bronze',
    name: 'Bronze Affiliate',
    emoji: '🥉',
    minReferrals: 0,
    maxReferrals: 4,
    pointsPerReferral: 50,
    boostSlots: 0,
    boostDurationDays: 0,
    color: 'text-amber-700',
    bgGradient: 'from-amber-100 to-orange-50',
    borderColor: 'border-amber-300',
    description: 'Mulai perjalanan affiliate! Ajak teman dan kumpulkan poin.',
  },
  {
    id: 'silver',
    name: 'Silver Affiliate',
    emoji: '🥈',
    minReferrals: 5,
    maxReferrals: 14,
    pointsPerReferral: 75,
    boostSlots: 2,
    boostDurationDays: 3,
    color: 'text-slate-600',
    bgGradient: 'from-slate-100 to-gray-50',
    borderColor: 'border-slate-400',
    description: 'Bonus poin lebih besar + 2 boost listing gratis per bulan!',
  },
  {
    id: 'gold',
    name: 'Gold Affiliate',
    emoji: '🏆',
    minReferrals: 15,
    maxReferrals: null,
    pointsPerReferral: 100,
    boostSlots: 5,
    boostDurationDays: 7,
    color: 'text-yellow-700',
    bgGradient: 'from-yellow-100 to-amber-50',
    borderColor: 'border-yellow-400',
    description: 'Reward terbaik! 100 poin per referral + 5 boost listing gratis per bulan.',
  },
];

export function getAffiliateTier(completedReferrals: number): AffiliateTier {
  for (let i = AFFILIATE_TIERS.length - 1; i >= 0; i--) {
    if (completedReferrals >= AFFILIATE_TIERS[i].minReferrals) return AFFILIATE_TIERS[i];
  }
  return AFFILIATE_TIERS[0];
}

export function getNextAffiliateTier(completedReferrals: number): AffiliateTier | null {
  const current = getAffiliateTier(completedReferrals);
  const idx = AFFILIATE_TIERS.indexOf(current);
  return idx < AFFILIATE_TIERS.length - 1 ? AFFILIATE_TIERS[idx + 1] : null;
}

export function getAffiliateProgress(completedReferrals: number): { percent: number; remaining: number } {
  const next = getNextAffiliateTier(completedReferrals);
  if (!next) return { percent: 100, remaining: 0 };
  const current = getAffiliateTier(completedReferrals);
  const start = current.minReferrals;
  const end = next.minReferrals;
  const progress = completedReferrals - start;
  const total = end - start;
  return {
    percent: Math.min(100, Math.round((progress / total) * 100)),
    remaining: end - completedReferrals,
  };
}

