  return PROGRAM_AWARDS.find(a => a.id === id);
}

export function getAwardsByProgram(programId: string): ProgramAward[] {
  return PROGRAM_AWARDS.filter(a => a.programId === programId);
}

export const TIER_ORDER: Record<string, number> = {
