import { zite } from 'zitejs/db';

/**
 * Checks if a user is banned. Throws error if banned.
 * Call this at the start of any endpoint that banned users should not access.
 */
export async function enforceBan(userId: string): Promise<void> {
  const profile = await zite.userProfiles.findOne({ filters: { user: userId } });
  if (profile?.banned) {
    throw new Error('Akun kamu sedang dibatasi. Kamu tidak bisa menggunakan fitur ini.');
  }
}

