/**
 * Extract a clean, user-friendly error message from a caught error.
 * ZiteError messages sometimes include JSON or technical details —
 * this strips them down to just the human-readable part.
 */
export function cleanError(e: unknown, fallback = 'Terjadi kesalahan'): string {
  if (!e) return fallback;
  const raw = (e as any)?.message || String(e);

  // Try to parse if it looks like JSON: { "message": "..." }
  try {
    if (raw.includes('{')) {
      const parsed = JSON.parse(raw);
      if (parsed?.message) return parsed.message;
      if (parsed?.error) return parsed.error;
    }
  } catch { /* not JSON, continue */ }

  // Strip common technical prefixes like "ZiteError: ", "Error: ", status codes
  let clean = raw
    .replace(/^(ZiteError|Error|HTTPError|BadRequestError|UnauthorizedError):\s*/i, '')
    .replace(/^\d{3}\s*[-:]\s*/, '') // "400 - ..." or "400: ..."
    .replace(/\s*\(status\s*\d+\)/gi, '') // "(status 400)"
    .trim();

  // If still has curly braces / looks like code, return fallback
  if (clean.includes('{') || clean.includes('stack') || clean.length > 200) {
    return fallback;
  }

  return clean || fallback;
}

