/** Check if a user with given points can access a feature */
export function canAccessFeature(points: number, featureId: string): boolean {
  for (const tier of FEATURE_TIERS) {
    if (tier.features.some(f => f.id === featureId)) {
      return points >= tier.minPoints;
    }
  }
  return true; // unknown feature = allow
}

/** Get the tier that contains a feature */
export function getFeatureTier(featureId: string): FeatureTier | null {
  return FEATURE_TIERS.find(t => t.features.some(f => f.id === featureId)) ?? null;
}

/** Get all unlocked features for a given point total */
export function getUnlockedFeatures(points: number): UnlockFeature[] {
  return FEATURE_TIERS
    .filter(t => points >= t.minPoints)
    .flatMap(t => t.features);
}

/** Get the next tier the user hasn't reached yet */
export function getNextFeatureTier(points: number): FeatureTier | null {
  return FEATURE_TIERS.find(t => points < t.minPoints) ?? null;
}

