import { ArrowLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { BADGES, TIPS, getBadge, getNextBadge, getProgressToNext } from '../lib/badges';
import BadgeCard from '../components/achievements/BadgeCard';
import AchievementTimeline from '../components/achievements/AchievementTimeline';
import { useUserPoints } from '../hooks/useUserPoints';
import { Skeleton } from '@project/components/ui/skeleton';
import { useAuth } from 'zitejs/auth';
import AwardsShowcase from '../components/AwardsShowcase';

export default function AchievementsPage() {
  const navigate = useNavigate();
  const { totalPoints: points, history, loading } = useUserPoints();
  const { user } = useAuth();
  const current = getBadge(points);
  const next = getNextBadge(points);
  const progress = getProgressToNext(points);
  const currentIdx = BADGES.indexOf(current);

  const motivational = next
    ? `Hanya ${progress.remaining} poin lagi untuk menjadi "${next.name}". Terus barter dengan bertanggung jawab!`
    : 'Kamu sudah mencapai level tertinggi! Pertahankan reputasi luar biasamu. 🏆';

  return (
    <div className="min-h-screen bg-background mutari-main pb-10">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0">
              <ArrowLeft className="w-4 h-4 text-foreground" />
            </button>
            <h1 className="font-bold text-base text-foreground flex-1">Pencapaian</h1>
        </div>

        {/* Current badge hero */}
        <div className="bg-primary px-4 pt-2 pb-8 relative overflow-hidden">
          <div className="absolute -right-10 -top-6 w-32 h-32 rounded-full bg-white/5" />
          <div className="text-center relative z-10">
            {loading ? (
              <div className="space-y-3 py-4">
                <Skeleton className="h-12 w-12 rounded-full mx-auto bg-white/20" />
                <Skeleton className="h-5 w-36 mx-auto bg-white/20" />
                <Skeleton className="h-3 w-48 mx-auto bg-white/20" />
              </div>
            ) : (
              <>
                <div className="text-5xl mb-2">{current.emoji}</div>
                <h2 className="text-white font-bold text-xl">{current.name}</h2>
                <p className="text-white/70 text-xs mt-1 max-w-[260px] mx-auto">{current.description}</p>
                <div className="mt-4 bg-white/10 rounded-2xl p-4">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-white font-bold text-2xl">{points}</span>
                    <span className="text-white/60 text-xs">Total Poin</span>
                  </div>
                  <div className="w-full bg-white/20 rounded-full h-2.5 mt-2">
                    <div
                      className="bg-white rounded-full h-2.5 transition-all duration-700"
                      style={{ width: `${progress.percent}%` }}
                    />
                  </div>
                  {next && (
                    <div className="flex items-center justify-between mt-2">
                      <span className="text-white/50 text-[10px]">{current.emoji} {current.minPoints}</span>
                      <span className="text-white/50 text-[10px]">{next.emoji} {next.minPoints}</span>
                    </div>
                  )}
                </div>
                <div className="mt-3 bg-white/10 rounded-xl px-3 py-2.5">
                  <p className="text-white/80 text-[11px] leading-relaxed">💡 {motivational}</p>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Badge levels */}
        <div className="px-4 mt-5">
          <h3 className="font-bold text-sm mb-3">Level Badge MUTARI</h3>
          <div className="space-y-3">
            {BADGES.map((b, i) => (
              <BadgeCard
                key={b.id}
                badge={b}
                isUnlocked={i <= currentIdx}
                isCurrent={i === currentIdx}
                userPoints={points}
              />
            ))}
          </div>
        </div>

        {/* Penghargaan Program — semua penghargaan dari berbagai program */}
        {user && <AwardsShowcase userId={user.id} />}

        {/* Achievement history */}
        <div className="px-4 mt-6">
          <h3 className="font-bold text-sm mb-3">Riwayat Pencapaian</h3>
          {loading ? (
            <div className="bg-card rounded-2xl border border-border p-4 space-y-3 shadow-sm">
              {[0, 1, 2].map(i => (
                <div key={i} className="flex items-center gap-3">
                  <Skeleton className="w-8 h-8 rounded-full" />
                  <div className="flex-1 space-y-1">
                    <Skeleton className="h-3 w-3/4" />
                    <Skeleton className="h-2 w-1/3" />
                  </div>
                </div>
              ))}
            </div>
          ) : history.length === 0 ? (
            <div className="bg-card rounded-2xl border border-border p-6 text-center shadow-sm">
              <p className="text-muted-foreground text-sm">Belum ada riwayat pencapaian.</p>
              <p className="text-muted-foreground text-xs mt-1">Mulai upload barang untuk mendapatkan poin!</p>
            </div>
          ) : (
            <AchievementTimeline
              history={history.map(h => ({
                label: h.activity,
                points: h.points,
                date: h.earnedAt,
              }))}
            />
          )}
        </div>

        {/* Tips */}
        <div className="px-4 mt-6 mb-8">
          <h3 className="font-bold text-sm mb-3">💡 Tips Mendapatkan Poin</h3>
          <div className="bg-card rounded-2xl border border-border divide-y divide-border overflow-hidden shadow-sm">
            {TIPS.map((tip, i) => (
              <div key={i} className="px-4 py-3 flex items-start gap-2.5">
                <span className="text-primary font-bold text-sm mt-0.5">{i + 1}.</span>
                <p className="text-xs text-foreground leading-relaxed">{tip}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

