import { MutariInline } from '../components/MutariSpinner';
import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, MapPin, CheckCircle, Navigation, RefreshCw } from 'lucide-react';
import { toast } from 'sonner';
import { useProfile } from '../hooks/useProfile';
import { updateProfile } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

export default function AddressPage() {
  const navigate = useNavigate();
  const { profile, loading } = useProfile();

  const [kabupaten, setKabupaten] = useState('');
  const [kecamatan, setKecamatan] = useState('');
  const [desa, setDesa] = useState('');
  const [detecting, setDetecting] = useState(false);
  const [detected, setDetected] = useState(false);
  const [saving, setSaving] = useState(false);
  const [gpsError, setGpsError] = useState('');

  useEffect(() => {
    if (profile) {
      // Parse existing address into fields if available
      if (profile.city) {
        setKabupaten(profile.city);
        setDetected(true);
      }
      if (profile.address) {
        const parts = profile.address.split(', ');
        if (parts.length >= 3) {
          setDesa(parts[0]);
          setKecamatan(parts[1]);
        } else if (parts.length === 2) {
          setKecamatan(parts[0]);
        }
        if (profile.city) setDetected(true);
      }
    }
  }, [profile]);

  const handleDetect = useCallback(async () => {
    if (!navigator.geolocation) {
      setGpsError('GPS tidak tersedia di perangkat ini');
      return;
    }
    setDetecting(true);
    setGpsError('');

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude, longitude } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&accept-language=id&zoom=18&addressdetails=1`
          );
          const data = await res.json();
          const addr = data.address || {};

          setKabupaten(addr.city || addr.county || addr.city_district || addr.municipality || '');
          setKecamatan(addr.suburb || addr.city_district || addr.town || addr.district || '');
          setDesa(addr.village || addr.hamlet || addr.neighbourhood || addr.quarter || '');
          setDetected(true);
        } catch {
          setGpsError('Gagal mendapatkan data lokasi. Coba lagi.');
        }
        setDetecting(false);
      },
      (err) => {
        if (err.code === 1) {
          setGpsError('Izin lokasi ditolak. Aktifkan GPS di pengaturan perangkat.');
        } else {
          setGpsError('Gagal mendeteksi lokasi. Pastikan GPS aktif.');
        }
        setDetecting(false);
      },
      { enableHighAccuracy: true, timeout: 15000 }
    );
  }, []);

  // Auto-detect on mount if no existing address
  useEffect(() => {
    if (!loading && profile && !profile.city) {
      handleDetect();
    }
  }, [loading, profile, handleDetect]);

  const handleSave = async () => {
    if (!kabupaten) {
      toast.error('Kabupaten belum terdeteksi');
      return;
    }
    setSaving(true);
    try {
      await updateProfile({
        city: kabupaten,
        address: [desa, kecamatan, kabupaten].filter(Boolean).join(', '),
        province: '',
      });
      toast.success('Alamat berhasil disimpan');
      navigate(-1);
    } catch {
      toast.error('Gagal menyimpan alamat');
    }
    setSaving(false);
  };

  const isComplete = !!kabupaten;

  if (loading) {
    return (
      <div className="min-h-screen bg-background mutari-main">
        <div className="max-w-[420px] mx-auto">
          <div className="bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground">Alamat Saya</h1>
          </div>
