              >
                {f.label}
                {!loading && (f.key === 'all' ? history.length : (counts[f.key] || 0)) > 0 && (
                  <span className={`text-[9px] px-1 py-px rounded-full ${filter === f.key ? 'bg-white/20' : 'bg-foreground/10'}`}>
