const SERVICE_DEPOSIT = 40;

function extractErrorMessage(err: any): string {
  const raw = err?.message || err?.error || '';
  if (typeof raw !== 'string') return 'Gagal membuat penawaran';
  const jsonMatch = raw.match(/:\s*(\{.*\})\s*$/);
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[1]);
      if (parsed?.message) return parsed.message;
    } catch { /* ignore */ }
  }
  try {
    const parsed = JSON.parse(raw);
    if (parsed?.message) return parsed.message;
  } catch { /* ignore */ }
  const clean = raw.split('\n')[0].replace(/\s*at\s+.*/g, '').trim();
  return clean && clean.length <= 200 ? clean : 'Gagal membuat penawaran';
}

