  const [submitting, setSubmitting] = useState(false);
  const [userPoints, setUserPoints] = useState<number | null>(null);

  const isOwnService = !!(user && service?.providerId === user.id);
  const insufficientPoints = userPoints !== null && userPoints < SERVICE_DEPOSIT;

  useEffect(() => {
    if (!serviceId) return;
    Promise.all([
      getServiceDetail({ id: serviceId }),
      getMyItems({}),
      getUserPoints({}),
    ]).then(([svc, items, points]) => {
      setService(svc.service);
      setMyItems((items.items || []).filter((i: any) => i.status === 'Tersedia'));
      setUserPoints(points.totalPoints);
    }).catch(() => navigate('/services')).finally(() => setLoading(false));
  }, [serviceId]);

  const handleSubmit = async () => {
    if (!selectedItemId) return toast.error('Pilih barang yang ingin ditukarkan');
    if (!serviceId) return;
    if (insufficientPoints) return;

    setSubmitting(true);
    try {
      const result = await createServiceBarter({
        serviceId,
        offeredItemId: selectedItemId,
        message: message.trim() || undefined,
      });
      toast.success('Penawaran barter jasa berhasil dikirim! 🛠️');
      navigate(`/service-barter/${result.barterId}`);
    } catch (err: any) {
      toast.error(extractErrorMessage(err));
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!service) return null;

  const selectedItem = myItems.find(i => i.id === selectedItemId);
  const pointsShort = insufficientPoints ? SERVICE_DEPOSIT - (userPoints ?? 0) : 0;

  return (
    <div className="min-h-screen bg-background pb-24 lg:pl-[220px] xl:lg:pl-[240px]">
      <div className="sticky top-0 z-40 bg-primary text-primary-foreground">
        <div className="max-w-[420px] lg:max-w-3xl mx-auto flex items-center gap-3 px-4 py-3">
          <button onClick={() => navigate(-1)} className="p-1 -ml-1"><ArrowLeft className="w-5 h-5" /></button>
          <h1 className="text-lg font-bold">Tukar Barang → Jasa</h1>
        </div>
      </div>

      <div className="max-w-[420px] lg:max-w-3xl mx-auto px-4 mt-4 space-y-4">
        {/* Insufficient Points Banner */}
        {insufficientPoints && (
          <div className="p-4 bg-destructive/10 border border-destructive/30 rounded-xl">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 rounded-full bg-destructive/15 flex items-center justify-center flex-shrink-0">
                <AlertTriangle className="w-5 h-5 text-destructive" />
              </div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-destructive">Poin Tidak Mencukupi</p>
                <p className="text-xs text-destructive/80 mt-1">
                  Barter jasa membutuhkan deposit <strong>{SERVICE_DEPOSIT} MP</strong>, tetapi saldo kamu hanya <strong>{userPoints} MP</strong>.
                  Kamu perlu <strong>{pointsShort} MP</strong> lagi untuk melakukan barter jasa.
                </p>
                <div className="flex gap-2 mt-3">
                  <button
                    onClick={() => navigate('/missions')}
                    className="px-3 py-1.5 bg-primary text-primary-foreground rounded-lg text-xs font-semibold hover:opacity-90 transition flex items-center gap-1"
                  >
                    <Coins className="w-3.5 h-3.5" /> Selesaikan Misi
                  </button>
                  <button
                    onClick={() => navigate('/wallet')}
                    className="px-3 py-1.5 bg-muted text-foreground rounded-lg text-xs font-medium hover:bg-accent transition"
                  >
                    Lihat Saldo
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Point Balance Chip */}
        {userPoints !== null && !insufficientPoints && (
          <div className="flex items-center gap-2 px-3 py-2 bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200 dark:border-emerald-800 rounded-xl">
            <Coins className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
            <span className="text-xs text-emerald-700 dark:text-emerald-300 font-medium">
              Saldo kamu: <strong>{userPoints} MP</strong> — deposit {SERVICE_DEPOSIT} MP akan ditahan sementara
            </span>
          </div>
        )}

        {/* Service Target */}
        <div className="p-4 bg-card rounded-xl border border-border">
          <p className="text-xs font-medium text-muted-foreground mb-2">🛠️ JASA YANG DIMINTA</p>
          <div className="flex items-center gap-3">
            {service.portfolio?.[0]?.url ? (
              <img src={service.portfolio[0].url} alt="" className="w-16 h-16 rounded-lg object-cover" />
            ) : (
              <div className="w-16 h-16 rounded-lg bg-primary/10 flex items-center justify-center text-2xl">{service.categoryIcon}</div>
            )}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-foreground truncate">{service.title}</p>
              <p className="text-xs text-muted-foreground">oleh {service.providerName}</p>
              <p className="text-xs text-muted-foreground mt-0.5">⏱️ Deadline: {service.completionDays || 7} hari</p>
            </div>
