        </div>

        {/* Own service warning */}
        {isOwnService ? (
          <div className="text-center py-10 space-y-3">
            <div className="w-14 h-14 rounded-full bg-amber-100 dark:bg-amber-950/40 flex items-center justify-center mx-auto">
              <ShieldAlert className="w-7 h-7 text-amber-600" />
            </div>
            <p className="text-sm font-semibold text-foreground">Ini jasa milik kamu sendiri</p>
            <p className="text-xs text-muted-foreground max-w-[260px] mx-auto">
              Kamu tidak bisa mengajukan penawaran barter untuk jasa yang kamu buat sendiri. Cari jasa dari pengguna lain ya!
            </p>
            <button
              onClick={() => navigate('/services')}
              className="mt-2 px-5 py-2.5 bg-primary text-primary-foreground rounded-xl text-sm font-semibold hover:opacity-90 transition"
            >
              Jelajahi Jasa Lain
            </button>
          </div>
        ) : (
          <>
            {/* Deposit Warning */}
            <div className="p-3 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-xl flex gap-2">
              <Info className="w-4 h-4 text-amber-600 mt-0.5 flex-shrink-0" />
              <div className="text-xs text-amber-700 dark:text-amber-300">
                <p className="font-semibold">Deposit 40 MP diperlukan</p>
                <p className="mt-0.5">Deposit akan ditahan dan dikembalikan setelah jasa selesai. Lebih tinggi dari barter barang (20 MP) karena risiko lebih besar.</p>
              </div>
            </div>

            {/* Arrow */}
            <div className="flex justify-center">
              <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
                <Repeat className="w-5 h-5 text-primary" />
              </div>
            </div>

            {/* Select Your Item */}
            <div>
              <p className="text-sm font-semibold text-foreground mb-2 flex items-center gap-1">
                <Package className="w-4 h-4" /> Pilih Barang untuk Ditukar
              </p>
              {myItems.length === 0 ? (
                <div className="text-center py-8 bg-card rounded-xl border border-border">
                  <Package className="w-10 h-10 text-muted-foreground/30 mx-auto mb-2" />
                  <p className="text-sm text-muted-foreground">Belum ada barang tersedia</p>
                  <button onClick={() => navigate('/upload')} className="mt-2 text-xs text-primary font-semibold">Upload Barang Dulu</button>
                </div>
              ) : (
                <div className="space-y-2 max-h-[300px] overflow-y-auto">
                  {myItems.map(item => {
                    const photo = item.photos?.[0]?.url;
                    const selected = selectedItemId === item.id;
                    return (
                      <button
                        key={item.id}
                        onClick={() => setSelectedItemId(item.id)}
                        disabled={insufficientPoints}
                        className={`w-full flex items-center gap-3 p-3 rounded-xl border text-left transition ${
                          insufficientPoints ? 'opacity-50 cursor-not-allowed border-border bg-muted' :
                          selected ? 'border-primary bg-primary/5 ring-2 ring-primary/20' : 'border-border bg-card hover:border-primary/30'
                        }`}
                      >
                        {photo ? (
                          <img src={photo} alt="" className="w-14 h-14 rounded-lg object-cover flex-shrink-0" />
                        ) : (
                          <div className="w-14 h-14 rounded-lg bg-muted flex items-center justify-center text-xl flex-shrink-0">📦</div>
                        )}
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-foreground truncate">{item.title}</p>
                          <p className="text-xs text-muted-foreground">{item.condition} • {item.location || 'Tanpa lokasi'}</p>
                        </div>
                        {selected && <div className="w-5 h-5 rounded-full bg-primary flex items-center justify-center text-primary-foreground text-xs">✓</div>}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Message */}
            <div>
              <label className="text-sm font-semibold text-foreground">Pesan (opsional)</label>
              <textarea value={message} onChange={e => setMessage(e.target.value)} placeholder="Tulis pesan untuk penyedia jasa..." rows={3} className="mt-1 w-full px-3 py-2.5 bg-muted rounded-xl text-sm border-none outline-none focus:ring-2 focus:ring-primary/30 resize-none" disabled={insufficientPoints} />
            </div>

            {/* Summary */}
            {selectedItem && !insufficientPoints && (
              <div className="p-4 bg-primary/5 rounded-xl border border-primary/20">
                <p className="text-xs font-semibold text-primary mb-2">📋 Ringkasan Barter</p>
                <p className="text-sm text-foreground">
                  <strong>{selectedItem.title}</strong> → <strong>{service.title}</strong>
                </p>
                <p className="text-xs text-muted-foreground mt-1">Deposit: 40 MP • Deadline: {service.completionDays || 7} hari</p>
              </div>
            )}

            {/* Submit */}
            <button
              onClick={handleSubmit}
              disabled={submitting || !selectedItemId || insufficientPoints}
              className="w-full py-3.5 bg-primary text-primary-foreground rounded-xl font-bold text-sm shadow-md shadow-primary/20 disabled:opacity-50 hover:opacity-90 transition"
            >
              {insufficientPoints
                ? `⚠️ Poin Tidak Cukup (butuh ${pointsShort} MP lagi)`
                : submitting
                ? 'Memproses...'
                : '🛠️ Kirim Penawaran Barter Jasa (-40 MP)'}
            </button>
          </>
        )}
      </div>

      <BottomNav />
    </div>
  );
}

