import { MutariInline } from '../components/MutariSpinner';
import { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, MapPin, CheckCircle2, AlertTriangle, Clock, XCircle, Star, Flag, ArrowRight, Users, Navigation, Shield, ShieldCheck, ShieldAlert, Truck, Package, ArrowLeftRight, Loader2, ChevronDown, ChevronUp } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { getBarterDetail, getBarterMessages, sendBarterMessage, respondBarterOffer, setDeliveryMethod, confirmBarterComplete, cancelBarter, submitBarterReview, respondCodProposal, proposePremiumInsurance, respondPremiumInsurance } from 'zitejs/api';
import type { GetBarterDetailOutputType, GetBarterMessagesOutputType } from 'zitejs/api';
import { useAuth } from 'zitejs/auth';
import { toast } from 'sonner';
import { usePointReward } from '../context/PointRewardContext';
import { useUserPoints } from '../hooks/useUserPoints';
import BarterItemCard from '../components/barter/BarterItemCard';
import CodModal from '../components/barter/CodModal';
