import ReviewModal from '../components/barter/ReviewModal';
import CancelModal from '../components/barter/CancelModal';
import ChatInput from '../components/barter/ChatInput';
import ReportModal from '../components/barter/ReportModal';
import { cleanError } from '../lib/errorMsg';
import PremiumInsuranceModal from '../components/barter/PremiumInsuranceModal';
import ShippingModal from '../components/barter/ShippingModal';

type BarterType = GetBarterDetailOutputType['barter'];
type MessageType = GetBarterMessagesOutputType['messages'][0];


export default function BarterNegotiationPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { showPointReward } = usePointReward();
  const { totalPoints: myTotalPoints } = useUserPoints();
  const [barter, setBarter] = useState<BarterType | null>(null);
  const [messages, setMessages] = useState<MessageType[]>([]);
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [otherTyping, setOtherTyping] = useState(false);
  const [showCod, setShowCod] = useState(false);
  const [showShipping, setShowShipping] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const [showCancel, setShowCancel] = useState(false);
  const [showReport, setShowReport] = useState(false);
  const [showPremiumInsurance, setShowPremiumInsurance] = useState(false);
  const [respondingPremium, setRespondingPremium] = useState(false);
  const [responding, setResponding] = useState(false);
  const [showItems, setShowItems] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatScrollRef = useRef<HTMLDivElement>(null);
  const prevMsgCount = useRef(0);
  const shouldAutoScroll = useRef(true);

  const [respondingCod, setRespondingCod] = useState(false);

  const loadData = useCallback(async () => {
    if (!id) return;
    try {
      const [bd, bm] = await Promise.all([
        getBarterDetail({ barterId: id }),
        getBarterMessages({ barterId: id }),
      ]);
      setBarter(bd.barter);
      setMessages(bm.messages);
    } catch { /* ignore */ }
    setLoading(false);
  }, [id]);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!id) return;
    const iv = setInterval(async () => {
      try {
        const [bd, bm] = await Promise.all([
          getBarterDetail({ barterId: id }),
          getBarterMessages({ barterId: id }),
        ]);
        setBarter(bd.barter);
        setMessages(bm.messages);
      } catch { /* ignore */ }
    }, 4000);
    return () => clearInterval(iv);
  }, [id]);

  useEffect(() => {
    const el = chatScrollRef.current;
    const isFirstLoad = prevMsgCount.current === 0;
    const hasNewMessages = messages.length > prevMsgCount.current;
    const nearBottom = !el || (el.scrollHeight - el.scrollTop - el.clientHeight < 200);

    if (isFirstLoad || shouldAutoScroll.current || (hasNewMessages && nearBottom)) {
      chatEndRef.current?.scrollIntoView({ behavior: isFirstLoad ? 'instant' : 'smooth' });
    }
    prevMsgCount.current = messages.length;
    shouldAutoScroll.current = false;
  }, [messages]);

  const handleSend = async (content: string, type: 'Text' | 'Photo') => {
    if (!id) return;
    setSending(true);
    shouldAutoScroll.current = true;
    try {
      await sendBarterMessage({ barterId: id, content, type });
      await loadData();
    } catch {
      toast.error('Gagal mengirim pesan');
    }
    setSending(false);
  };

  const handleRespond = async (action: 'accept' | 'reject') => {
    if (!id) return;
    setResponding(true);
    try {
      await respondBarterOffer({ barterId: id, action });
      toast.success(action === 'accept' ? 'Penawaran diterima!' : 'Penawaran ditolak');
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal merespons'));
    }
    setResponding(false);
  };

  const handleCodRespond = async (action: 'approve' | 'reject') => {
    if (!id) return;
    setRespondingCod(true);
    try {
      await respondCodProposal({ barterId: id, action });
      toast.success(action === 'approve' ? 'Lokasi COD disetujui!' : 'Lokasi COD ditolak — usulkan lokasi baru');
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal merespons'));
    }
    setRespondingCod(false);
  };

  const handleCodSubmit = async (address: string, detail: string) => {
    if (!id) return;
    try {
      await setDeliveryMethod({ barterId: id, method: 'cod', address, detail: detail || undefined });
      toast.success('Usulan COD terkirim — menunggu persetujuan');
      setShowCod(false);
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal'));
    }
  };

  const handleShippingSubmit = async (service: string) => {
    if (!id) return;
    try {
      await setDeliveryMethod({ barterId: id, method: 'shipping', shippingService: service });
      toast.success('Usulan jasa kirim terkirim — menunggu persetujuan');
      setShowShipping(false);
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal'));
    }
  };

  const handleConfirmComplete = async () => {
    if (!id) return;
    try {
      const res = await confirmBarterComplete({ barterId: id });
      if (res.bothConfirmed) {
        const refundMsg = res.depositRefunded > 0 ? ` 🛡️ Jaminan ${res.depositRefunded} poin dikembalikan.` : '';
        toast.success(`🎉 Barter selesai! +${res.pointsEarned} poin cair.${refundMsg} ⏳ +${res.pointsHeld} poin lagi menunggu review kamu!`);
        showPointReward(res.pointsEarned, 'Barter selesai! 🤝');
      } else {
        toast.success('Konfirmasi dikirim. Menunggu pihak lain.');
      }
      setShowConfirm(false);
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal mengonfirmasi'));
    }
  };

  const handleCancel = async (reason: string) => {
    if (!id) return;
    try {
      await cancelBarter({ barterId: id, reason });
      toast.success('Barter dibatalkan');
      setShowCancel(false);
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal membatalkan'));
    }
  };

  const handleReview = async (rating: number, comment: string, aspect: string) => {
    if (!id) return;
    try {
      const res = await submitBarterReview({ barterId: id, rating, comment, aspect: aspect as any });
      const totalPts = res.bonusPoints + res.heldPointsReleased;
      toast.success(`Review terkirim! +${totalPts} poin dicairkan (${res.heldPointsReleased} bonus barter + ${res.bonusPoints} review)`);
      showPointReward(totalPts, 'Review terkirim! ⭐');
      setShowReview(false);
      setTimeout(() => navigate('/'), 1500);
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal mengirim review'));
    }
  };

  const handleProposePremium = async (amount: number) => {
    if (!id) return;
    try {
      await proposePremiumInsurance({ barterId: id, amount });
      toast.success('Usulan asuransi premium terkirim!');
      setShowPremiumInsurance(false);
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal mengusulkan asuransi'));
    }
  };

  const handleRespondPremium = async (action: 'accept' | 'reject') => {
    if (!id) return;
    setRespondingPremium(true);
    try {
      const res = await respondPremiumInsurance({ barterId: id, action });
      if (action === 'accept') {
        toast.success(`Asuransi premium aktif! ${res.amountHeld} MP ditahan.`);
      } else {
        toast.success('Usulan asuransi premium ditolak.');
      }
      await loadData();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal merespons'));
    }
    setRespondingPremium(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background mutari-main">
        <div className="max-w-[420px] mx-auto">
          <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border px-4 py-3 flex items-center gap-3">
            <Skeleton className="w-8 h-8 rounded-xl" />
            <div className="flex-1 space-y-1.5">
              <Skeleton className="h-4 w-32" />
              <Skeleton className="h-3 w-20" />
            </div>
          </div>
          <div className="p-4 flex items-center gap-3">
            <Skeleton className="w-20 h-20 rounded-xl" />
            <div className="flex-shrink-0"><Skeleton className="w-5 h-5 rounded-full" /></div>
            <Skeleton className="w-20 h-20 rounded-xl" />
          </div>
          <div className="px-4 space-y-3 mt-2">
            <div className="flex justify-end"><Skeleton className="h-10 w-48 rounded-2xl" /></div>
            <div className="flex justify-start"><Skeleton className="h-10 w-40 rounded-2xl" /></div>
            <div className="flex justify-end"><Skeleton className="h-14 w-52 rounded-2xl" /></div>
            <div className="flex justify-start"><Skeleton className="h-10 w-36 rounded-2xl" /></div>
          </div>
          <div className="fixed bottom-0 left-0 right-0 bg-card border-t border-border p-3">
            <div className="max-w-[420px] mx-auto flex gap-2">
              <Skeleton className="flex-1 h-10 rounded-full" />
              <Skeleton className="w-10 h-10 rounded-full" />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!barter) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <p className="text-muted-foreground">Barter tidak ditemukan</p>
      </div>
    );
  }

  const myConfirmed = barter.myRole === 'initiator' ? barter.initiatorConfirmed : barter.partnerConfirmed;
  const otherConfirmed = barter.myRole === 'initiator' ? barter.partnerConfirmed : barter.initiatorConfirmed;
  const isWaiting = barter.status === 'Menunggu' && barter.myRole === 'partner';
  const isWaitingInitiator = barter.status === 'Menunggu' && barter.myRole === 'initiator';
  const isAccepted = barter.status === 'Diterima';
  const isComplete = barter.status === 'Selesai';
  const isCancelled = barter.status === 'Dibatalkan';
  const otherName = barter.myRole === 'initiator' ? barter.partner.name : barter.initiator.name;
  const canCancel = barter.status === 'Menunggu' || barter.status === 'Diterima';

  return (
    <div className="h-[100dvh] bg-background flex flex-col">
      <div className="max-w-[420px] mx-auto w-full flex flex-col flex-1 min-h-0">
        {/* ─── Header ─── */}
        <div className="flex-shrink-0 z-30 bg-card border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
