            <div className="flex-1 min-w-0">
              <h1 className="font-bold text-sm truncate">Negosiasi Barter</h1>
              <p className="text-[11px] text-muted-foreground truncate">dengan {otherName}</p>
            </div>
            <StatusBadge status={barter.status} />
            <button onClick={() => setShowReport(true)} className="p-1.5 rounded-xl hover:bg-destructive/10 transition active:scale-95" title="Laporkan">
              <Flag className="w-4 h-4 text-destructive/70" />
            </button>
          </div>
        </div>

        {/* ─── Compact Items + Status Strip ─── */}
        <div className="flex-shrink-0 border-b border-border bg-card">
          {/* Collapsed: inline thumbnail row */}
          <button
            onClick={() => setShowItems(p => !p)}
            className="w-full flex items-center gap-2.5 px-3 py-2 active:bg-muted/50 transition"
          >
            <div className="w-10 h-10 rounded-lg bg-muted overflow-hidden flex-shrink-0">
              {barter.offeredItem?.photo
                ? <img src={barter.offeredItem.photo} alt="" className="w-full h-full object-cover" />
                : <div className="w-full h-full flex items-center justify-center text-[8px] text-muted-foreground">—</div>}
            </div>
            <ArrowLeftRight className="w-3 h-3 text-muted-foreground flex-shrink-0" />
            <div className="w-10 h-10 rounded-lg bg-muted overflow-hidden flex-shrink-0">
              {barter.requestedItem?.photo
                ? <img src={barter.requestedItem.photo} alt="" className="w-full h-full object-cover" />
                : <div className="w-full h-full flex items-center justify-center text-[8px] text-muted-foreground">—</div>}
            </div>
            <div className="flex-1 min-w-0 text-left">
              <p className="text-[11px] font-semibold truncate">{barter.offeredItem?.title} ↔ {barter.requestedItem?.title}</p>
              <p className="text-[10px] text-muted-foreground truncate">{barter.offeredItem?.condition} • {barter.requestedItem?.condition}</p>
            </div>
            {showItems ? <ChevronUp className="w-4 h-4 text-muted-foreground flex-shrink-0" /> : <ChevronDown className="w-4 h-4 text-muted-foreground flex-shrink-0" />}
          </button>

          {/* Expanded: full item cards */}
          {showItems && (
            <div className="px-3 pb-3 pt-0">
              <div className="flex items-stretch gap-2">
                <BarterItemCard
                  title={barter.offeredItem?.title || ''}
                  photo={barter.offeredItem?.photo || null}
                  condition={barter.offeredItem?.condition || ''}
                  label={barter.myRole === 'initiator' ? 'Barangmu' : 'Barang mereka'}
                  valueMin={barter.offeredItem?.estimatedValueMin ?? null}
                  valueMax={barter.offeredItem?.estimatedValueMax ?? null}
                  itemId={barter.offeredItem?.id}
                />
                <div className="flex-shrink-0 flex items-center justify-center">
                  <div className="w-7 h-7 rounded-full bg-primary/10 flex items-center justify-center">
                    <ArrowLeftRight className="w-3 h-3 text-primary" />
                  </div>
                </div>
                <BarterItemCard
                  title={barter.requestedItem?.title || ''}
                  photo={barter.requestedItem?.photo || null}
                  condition={barter.requestedItem?.condition || ''}
                  label={barter.myRole === 'initiator' ? 'Barang mereka' : 'Barangmu'}
                  valueMin={barter.requestedItem?.estimatedValueMin ?? null}
                  valueMax={barter.requestedItem?.estimatedValueMax ?? null}
                  itemId={barter.requestedItem?.id}
                />
              </div>
            </div>
          )}
        </div>

        {/* ─── Status Banners ─── */}
        <div className="flex-shrink-0">
          {/* Expiry countdown */}
          {barter.status === 'Menunggu' && barter.expiresAt && (
            <ExpiryBanner expiresAt={barter.expiresAt} />
          )}

          {/* Deposit / Jaminan Poin Banner */}
          {barter.deposit && (barter.deposit.myStatus || barter.deposit.otherStatus) && (
            <DepositBanner deposit={barter.deposit} status={barter.status} otherName={otherName} />
          )}

          {/* Pre-accept deposit info */}
          {barter.status === 'Menunggu' && !barter.deposit?.myStatus && (
            <div className="px-3 py-1.5 bg-amber-50/80 dark:bg-amber-950/20 border-b border-amber-100 dark:border-amber-900 flex items-center gap-2">
              <Shield className="w-3.5 h-3.5 text-amber-600 flex-shrink-0" />
              <p className="text-[10px] text-amber-700 dark:text-amber-400">
                <span className="font-bold">Jaminan:</span> {barter.deposit?.depositPerPerson ?? 20} MP ditahan jika diterima. Melanggar = kehilangan poin.
              </p>
            </div>
          )}

          {/* Premium Insurance Banner — active */}
          {barter.premiumInsurance && barter.premiumInsurance.status === 'accepted' && isAccepted && (
            <div className="px-3 py-1.5 bg-amber-50/60 dark:bg-amber-950/20 border-b border-amber-100 dark:border-amber-900 flex items-center gap-2">
              <ShieldCheck className="w-3.5 h-3.5 text-amber-600 flex-shrink-0" />
              <p className="text-[10px] text-amber-700 dark:text-amber-400 flex-1 truncate">
                🛡️ <span className="font-bold">Asuransi Aktif</span> — {barter.premiumInsurance.myPremiumAmount}+{barter.premiumInsurance.otherPremiumAmount} MP ditahan
              </p>
              <span className="text-xs font-bold text-amber-700 dark:text-amber-400">{barter.premiumInsurance.totalPremiumHeld} MP</span>
            </div>
          )}

          {/* Premium Insurance Proposal — waiting for me */}
          {barter.premiumInsurance && barter.premiumInsurance.status === 'proposed' && barter.premiumInsurance.proposedBy !== user?.id && isAccepted && (
            <div className="px-3 py-2 bg-amber-50 dark:bg-amber-950/20 border-b border-amber-100 dark:border-amber-900">
              <p className="text-[11px] text-amber-700 dark:text-amber-400 mb-1.5">
                🛡️ <strong>{otherName}</strong> mengusulkan asuransi <strong>{barter.premiumInsurance.amount} MP</strong>/orang
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() => handleRespondPremium('accept')}
                  disabled={respondingPremium}
                  className="flex-1 py-1.5 rounded-lg bg-amber-600 text-white font-semibold text-[11px] disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-1"
                >
                  {respondingPremium ? <MutariInline size={12} /> : <CheckCircle2 className="w-3 h-3" />}
                  Setuju
                </button>
                <button
                  onClick={() => handleRespondPremium('reject')}
                  disabled={respondingPremium}
                  className="flex-1 py-1.5 rounded-lg border border-destructive/40 text-destructive font-semibold text-[11px] disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-1"
                >
                  {respondingPremium ? <MutariInline size={12} /> : <XCircle className="w-3 h-3" />}
                  Tolak
                </button>
              </div>
            </div>
          )}

          {/* Premium Insurance Proposal — I proposed */}
          {barter.premiumInsurance && barter.premiumInsurance.status === 'proposed' && barter.premiumInsurance.proposedBy === user?.id && isAccepted && (
            <div className="px-3 py-1.5 bg-amber-50/60 dark:bg-amber-950/20 border-b border-amber-100 dark:border-amber-900 flex items-center gap-2">
              <Shield className="w-3.5 h-3.5 text-amber-600 flex-shrink-0 animate-pulse" />
              <p className="text-[10px] text-amber-700 dark:text-amber-400 truncate">
                Usulan asuransi <strong>{barter.premiumInsurance.amount} MP</strong> — menunggu {otherName}...
              </p>
            </div>
          )}

          {/* COD Location banner */}
          {barter.deliveryMethod === 'cod' && barter.codAddress && (
            <CodBanner
              barter={barter}
              isAccepted={isAccepted}
              otherName={otherName}
              userId={user?.id}
              respondingCod={respondingCod}
              onShowCod={() => setShowCod(true)}
              onCodRespond={handleCodRespond}
            />
          )}

          {/* Shipping method banner */}
          {barter.deliveryMethod === 'shipping' && barter.shippingService && (
            <ShippingBanner
              barter={barter}
              isAccepted={isAccepted}
              otherName={otherName}
              userId={user?.id}
              respondingCod={respondingCod}
              onShowShipping={() => setShowShipping(true)}
              onCodRespond={handleCodRespond}
            />
          )}

          {/* Confirmation status */}
          {isAccepted && (myConfirmed || otherConfirmed) && (
            <div className="px-3 py-2 bg-green-50/80 dark:bg-green-950/20 border-b border-green-100 dark:border-green-900">
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-1.5">
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center ${myConfirmed ? 'bg-green-500' : 'bg-muted border border-border'}`}>
                    {myConfirmed && <CheckCircle2 className="w-3 h-3 text-white" />}
                  </div>
                  <span className={`text-[10px] font-semibold ${myConfirmed ? 'text-green-700 dark:text-green-400' : 'text-muted-foreground'}`}>Anda</span>
                </div>
                <div className="flex items-center gap-1.5">
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center ${otherConfirmed ? 'bg-green-500' : 'bg-muted border border-border'}`}>
                    {otherConfirmed && <CheckCircle2 className="w-3 h-3 text-white" />}
                  </div>
                  <span className={`text-[10px] font-semibold truncate ${otherConfirmed ? 'text-green-700 dark:text-green-400' : 'text-muted-foreground'}`}>{otherName}</span>
                </div>
                <p className="text-[10px] text-green-600 dark:text-green-500 font-medium ml-auto flex-shrink-0">
                  {myConfirmed && otherConfirmed ? '🎉 Selesai!' : myConfirmed ? 'Menunggu...' : 'Giliran Anda!'}
                </p>
              </div>
            </div>
          )}

          {/* Waiting — initiator side */}
          {isWaitingInitiator && (
            <div className="px-3 py-2 bg-blue-50/80 dark:bg-blue-950/20 border-b border-blue-100 dark:border-blue-900 flex items-center gap-2">
              <Loader2 className="w-4 h-4 text-blue-600 animate-spin flex-shrink-0" />
              <div className="flex-1 min-w-0">
                <p className="text-[11px] font-bold text-blue-700 dark:text-blue-400 truncate">
                  Menunggu respon dari {otherName}…
                </p>
                <p className="text-[10px] text-blue-600 dark:text-blue-500 truncate">
                  Penawaran sudah terkirim. {otherName} akan menerima atau menolak.
                </p>
              </div>
            </div>
          )}

          {/* Accept/Reject bar for partner */}
          {isWaiting && (
            <div className="px-3 py-2.5 bg-yellow-50/80 dark:bg-yellow-950/20 border-b border-yellow-100 dark:border-yellow-900">
              <div className="flex items-center gap-2 mb-2">
                <AlertTriangle className="w-3.5 h-3.5 text-yellow-600 flex-shrink-0" />
                <p className="text-[11px] text-yellow-700 dark:text-yellow-400 font-bold flex-1">Penawaran masuk — {barter.deposit?.depositPerPerson ?? 20} MP jaminan jika diterima</p>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={() => handleRespond('accept')}
                  disabled={responding}
                  className="flex-1 py-2 rounded-xl bg-primary text-primary-foreground font-semibold text-xs disabled:opacity-50 active:scale-[0.98] transition"
                >
                  {responding ? <MutariInline size={14} /> : '✓ Terima'}
                </button>
                <button
                  onClick={() => handleRespond('reject')}
                  disabled={responding}
                  className="flex-1 py-2 rounded-xl border border-destructive/40 text-destructive font-semibold text-xs disabled:opacity-50 active:scale-[0.98] transition"
                >
                  ✕ Tolak
                </button>
              </div>
            </div>
          )}

          {/* Post-acceptance: delivery method picker */}
          {isAccepted && !barter.deliveryMethod && !myConfirmed && !otherConfirmed && (
            <div className="px-3 py-2 bg-primary/5 border-b border-primary/10">
              <p className="text-[11px] font-bold text-primary mb-2 flex items-center gap-1.5">
                <CheckCircle2 className="w-3.5 h-3.5" /> Diterima! Pilih metode tukar:
              </p>
              <div className="flex gap-2">
                <button onClick={() => setShowCod(true)} className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl bg-card border border-blue-200 dark:border-blue-800 text-xs font-semibold active:scale-[0.98] transition">
                  <Navigation className="w-3.5 h-3.5 text-blue-600" /> 📍 COD
                </button>
                <button onClick={() => setShowShipping(true)} className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl bg-card border border-orange-200 dark:border-orange-800 text-xs font-semibold active:scale-[0.98] transition">
                  <Truck className="w-3.5 h-3.5 text-orange-600" /> 🚚 Kirim
                </button>
                {(!barter.premiumInsurance?.status || barter.premiumInsurance.status === 'rejected') && (
                  <button onClick={() => setShowPremiumInsurance(true)} className="flex-1 flex items-center justify-center gap-1.5 py-2 rounded-xl bg-card border border-amber-200 dark:border-amber-800 text-xs font-semibold active:scale-[0.98] transition">
                    <Shield className="w-3.5 h-3.5 text-amber-600" /> 🛡️
                  </button>
                )}
              </div>
            </div>
          )}
        </div>

        {/* ─── Chat Messages ─── */}
        <div ref={chatScrollRef} className="flex-1 overflow-y-auto px-4 py-3 space-y-2 overscroll-contain">
          {messages.map(msg => {
            const isMe = msg.senderId === user?.id;
            const isSystem = msg.type === 'System' || msg.type === 'COD Proposal';
            if (isSystem) {
              return (
                <div key={msg.id} className="flex justify-center py-1">
                  <div className="bg-muted/50 px-3.5 py-1.5 rounded-full max-w-[85%]">
                    <p className="text-[11px] text-muted-foreground text-center">{msg.content}</p>
                  </div>
                </div>
              );
            }
            return (
              <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[75%] px-3.5 py-2.5 rounded-2xl ${
                  isMe
                    ? 'bg-primary text-primary-foreground rounded-br-md'
                    : 'bg-card border border-border rounded-bl-md shadow-sm'
                }`}>
                  {msg.type === 'Photo' ? (
                    <img src={msg.content} alt="Foto" className="rounded-xl max-w-full max-h-48 object-cover cursor-pointer" onClick={() => window.open(msg.content, '_blank')} />
                  ) : (
                    <p className="text-sm whitespace-pre-wrap leading-relaxed">{msg.content}</p>
                  )}
                  <p className={`text-[10px] mt-1 ${isMe ? 'text-primary-foreground/60' : 'text-muted-foreground'}`}>
                    {msg.sentAt ? new Date(msg.sentAt).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : ''}
                  </p>
                </div>
              </div>
            );
          })}
          {/* Big CTA inside chat area */}
          {isAccepted && !myConfirmed && barter.deliveryMethodApproved && (
            <div className="px-4 py-3">
              <button
                onClick={() => setShowConfirm(true)}
                className="w-full py-3.5 rounded-2xl bg-green-600 hover:bg-green-700 text-white font-bold text-base flex items-center justify-center gap-2.5 active:scale-[0.98] transition shadow-lg shadow-green-600/25"
              >
                <CheckCircle2 className="w-5 h-5" /> Selesaikan Barter
              </button>
            </div>
          )}
          {isAccepted && !myConfirmed && !barter.deliveryMethodApproved && (
            <div className="px-4 py-2">
              <div className="w-full py-3 rounded-2xl bg-muted border border-border text-center">
                <p className="text-xs text-muted-foreground font-medium">⏳ Setujui metode tukar terlebih dahulu</p>
              </div>
            </div>
          )}
          {canCancel && (
            <div className="flex justify-center pb-2">
              <button
                onClick={() => setShowCancel(true)}
                className="flex items-center gap-1.5 px-4 py-1.5 rounded-full text-destructive/70 text-xs font-medium active:scale-95 transition"
              >
                <XCircle className="w-3.5 h-3.5" /> Batalkan Barter
              </button>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        {/* ─── Bottom Action Bar ─── */}
        {!isComplete && !isCancelled && (
          <div className="flex-shrink-0 bg-card border-t border-border pb-[env(safe-area-inset-bottom)]">
            <ChatInput onSend={handleSend} sending={sending} isTyping={otherTyping} onTypingChange={() => {}} />
          </div>
        )}

        {/* Complete status + review */}
        {isComplete && (
          <div className="flex-shrink-0 bg-card border-t border-border px-4 py-4">
            <div className="flex items-center justify-center gap-2 text-green-600">
              <CheckCircle2 className="w-5 h-5" />
              <p className="font-bold text-sm">Barter Selesai! 🎉</p>
            </div>
            <p className="text-xs text-muted-foreground mt-1 text-center">Kedua pihak telah mengonfirmasi</p>

            {!barter.myReviewSubmitted ? (
              <>
                <div className="mt-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800/30 rounded-2xl p-3">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-base">⏳</span>
                    <p className="text-xs font-bold text-amber-700 dark:text-amber-400">+{barter.heldPoints} MP menunggu dicairkan!</p>
                  </div>
                  <p className="text-[11px] text-amber-600 dark:text-amber-500 leading-relaxed">
                    Berikan review untuk mencairkan bonus +{barter.heldPoints} MP + 10 MP menulis review.
                    {barter.reviewDeadline && !barter.reviewDeadlineExpired && (
                      <> Batas waktu: <strong>{new Date(barter.reviewDeadline).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })}</strong>.</>
                    )}
                    {barter.reviewDeadlineExpired && (
                      <span className="text-destructive font-semibold"> ⚠️ Batas waktu sudah lewat — poin hangus.</span>
                    )}
                  </p>
                </div>
                {!barter.reviewDeadlineExpired && (
                  <button
                    onClick={() => setShowReview(true)}
                    className="w-full mt-3 py-2.5 rounded-xl bg-primary text-primary-foreground font-semibold text-sm flex items-center justify-center gap-2 active:scale-[0.98] transition animate-pulse"
                  >
                    <Star className="w-4 h-4" /> Beri Review & Klaim +{barter.heldPoints + 10} Poin
                  </button>
                )}
              </>
            ) : (
              <div className="mt-3 bg-accent/50 rounded-2xl p-3 border border-primary/10 text-center">
                <p className="text-xs text-primary font-medium">✅ Anda sudah memberikan review</p>
                {!barter.otherReviewSubmitted && (
                  <p className="text-[11px] text-muted-foreground mt-1">Menunggu review dari {otherName}</p>
                )}
              </div>
            )}
          </div>
        )}

        {/* Cancelled */}
        {isCancelled && (
          <div className="flex-shrink-0 bg-card border-t border-border px-4 py-4 text-center">
            <div className="flex items-center justify-center gap-2 text-destructive">
              <XCircle className="w-5 h-5" />
              <p className="font-bold text-sm">
                {barter.isExpired ? 'Penawaran Kedaluwarsa' : 'Barter Dibatalkan'}
              </p>
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              {barter.isExpired ? 'Tidak ada respon dalam 3 hari' : 'Salah satu pihak membatalkan barter ini'}
            </p>
          </div>
        )}
      </div>

      {/* ─── Modals ─── */}
      {showCod && (
        <CodModal
          currentAddress={barter.codAddress || ''}
          currentDetail={barter.codDetail || ''}
          locationA={barter.offeredItem?.latitude != null && barter.offeredItem?.longitude != null
            ? { lat: barter.offeredItem.latitude, lng: barter.offeredItem.longitude } : null}
          locationB={barter.requestedItem?.latitude != null && barter.requestedItem?.longitude != null
            ? { lat: barter.requestedItem.latitude, lng: barter.requestedItem.longitude } : null}
          labelA={barter.myRole === 'initiator' ? 'Lokasi Anda' : otherName}
          labelB={barter.myRole === 'initiator' ? otherName : 'Lokasi Anda'}
          onClose={() => setShowCod(false)}
          onSubmit={handleCodSubmit}
        />
      )}
      {showConfirm && (
        <ConfirmModal
          onClose={() => setShowConfirm(false)}
          onConfirm={handleConfirmComplete}
          myConfirmed={myConfirmed}
          otherConfirmed={otherConfirmed}
          otherName={otherName}
        />
      )}
      {showReview && (
        <ReviewModal partnerName={otherName} onClose={() => setShowReview(false)} onSubmit={handleReview} />
      )}
      {showCancel && (
        <CancelModal
          isAfterAccepted={isAccepted}
          onClose={() => setShowCancel(false)}
          onSubmit={handleCancel}
          depositAmount={barter.deposit?.depositPerPerson}
          premiumInsurance={barter.premiumInsurance}
        />
      )}
      {showReport && (
        <ReportModal
          onClose={() => setShowReport(false)}
          reportedUserId={barter.myRole === 'initiator' ? barter.partner.id : barter.initiator.id}
          reportedUserName={otherName}
          barterId={id}
        />
      )}
      {showPremiumInsurance && (
        <PremiumInsuranceModal
          onClose={() => setShowPremiumInsurance(false)}
          onSubmit={handleProposePremium}
          myPoints={myTotalPoints}
        />
      )}
      {showShipping && (
        <ShippingModal
          onClose={() => setShowShipping(false)}
          onSubmit={handleShippingSubmit}
        />
      )}
    </div>
  );
}

/* ─── Sub-components ─── */

function ActionChip({ icon, label, onClick, color }: { icon: React.ReactNode; label: string; onClick: () => void; color: 'primary' | 'orange' | 'green' | 'amber' }) {
  const colors = {
    primary: 'bg-primary/5 border-primary/20 text-primary',
    orange: 'bg-orange-50 dark:bg-orange-950/20 border-orange-200 dark:border-orange-800 text-orange-700 dark:text-orange-400',
    green: 'bg-green-50 dark:bg-green-950/20 border-green-200 dark:border-green-800 text-green-700 dark:text-green-400',
    amber: 'bg-amber-50 dark:bg-amber-950/20 border-amber-200 dark:border-amber-800 text-amber-700 dark:text-amber-400',
  };
  return (
    <button
      onClick={onClick}
      className={`flex-shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full border text-[11px] font-semibold active:scale-95 transition whitespace-nowrap ${colors[color]}`}
    >
      {icon} {label}
    </button>
  );
}

function ExpiryBanner({ expiresAt }: { expiresAt: string }) {
  const [timeLeft, setTimeLeft] = useState('');

  useEffect(() => {
    const update = () => {
      const diff = new Date(expiresAt).getTime() - Date.now();
      if (diff <= 0) {
        setTimeLeft('Kedaluwarsa');
        return;
      }
      const hours = Math.floor(diff / (1000 * 60 * 60));
      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      if (hours >= 24) {
        const days = Math.floor(hours / 24);
        setTimeLeft(`${days} hari ${hours % 24} jam`);
      } else {
        setTimeLeft(`${hours} jam ${minutes} menit`);
      }
    };
    update();
    const iv = setInterval(update, 60000);
    return () => clearInterval(iv);
  }, [expiresAt]);

  const isUrgent = new Date(expiresAt).getTime() - Date.now() < 24 * 60 * 60 * 1000;

  return (
    <div className={`px-3 py-1.5 border-b flex items-center gap-2 ${
      isUrgent
        ? 'bg-red-50/80 dark:bg-red-950/20 border-red-100 dark:border-red-900'
        : 'bg-yellow-50/60 dark:bg-yellow-950/20 border-yellow-100 dark:border-yellow-900'
    }`}>
      <Clock className={`w-3.5 h-3.5 flex-shrink-0 ${isUrgent ? 'text-red-500' : 'text-yellow-600'}`} />
      <p className={`text-[10px] font-medium ${isUrgent ? 'text-red-700 dark:text-red-400' : 'text-yellow-700 dark:text-yellow-400'}`}>
        Batas respon: <span className="font-bold">{timeLeft}</span>
      </p>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, { bg: string; text: string }> = {
    Menunggu: { bg: 'bg-yellow-100 dark:bg-yellow-900/30', text: 'text-yellow-700 dark:text-yellow-400' },
    Diterima: { bg: 'bg-blue-100 dark:bg-blue-900/30', text: 'text-blue-700 dark:text-blue-400' },
    Selesai: { bg: 'bg-green-100 dark:bg-green-900/30', text: 'text-green-700 dark:text-green-400' },
    Dibatalkan: { bg: 'bg-red-100 dark:bg-red-900/30', text: 'text-red-700 dark:text-red-400' },
  };
  const s = map[status] || map.Menunggu;
  return (
    <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-semibold ${s.bg} ${s.text}`}>
      {status}
    </span>
  );
}

function CodBanner({ barter, isAccepted, otherName, userId, respondingCod, onShowCod, onCodRespond }: {
  barter: BarterType; isAccepted: boolean; otherName: string; userId?: string; respondingCod: boolean;
  onShowCod: () => void; onCodRespond: (a: 'approve' | 'reject') => void;
}) {
  const approved = barter.deliveryMethodApproved;

  // Compact: approved or waiting for other
  if (approved || (barter.deliveryMethodProposedBy === userId)) {
    return (
      <div className={`px-3 py-1.5 border-b flex items-center gap-2 ${approved ? 'bg-green-50/60 dark:bg-green-950/20 border-green-100 dark:border-green-900' : 'bg-accent/30 border-primary/10'}`}>
        <MapPin className={`w-3.5 h-3.5 flex-shrink-0 ${approved ? 'text-green-600' : 'text-primary'}`} />
        <p className={`text-[10px] flex-1 truncate ${approved ? 'text-green-700 dark:text-green-400' : 'text-foreground'}`}>
          {approved ? '✅ COD:' : '📍 COD:'} <span className="font-semibold">{barter.codAddress?.split('[')[0]?.trim()}</span>
        </p>
        {!approved && <span className="text-[9px] text-amber-600 flex-shrink-0 animate-pulse">Menunggu...</span>}
        {isAccepted && approved && (
          <button onClick={onShowCod} className="text-[9px] text-primary font-semibold px-2 py-0.5 rounded-full bg-primary/10 flex-shrink-0">Ubah</button>
        )}
        {barter.codAddress?.match(/\[(-?\d+\.\d+),(-?\d+\.\d+)\]/) && (
          <button
            onClick={() => {
              const m = barter.codAddress!.match(/\[(-?\d+\.\d+),(-?\d+\.\d+)\]/);
              if (m) window.open(`https://www.google.com/maps?q=${m[1]},${m[2]}`, '_blank');
            }}
            className="text-[9px] text-primary font-medium flex-shrink-0"
          >
            🗺️ Maps
          </button>
        )}
      </div>
    );
  }

  // Need to approve/reject
  if (barter.deliveryMethodProposedBy && barter.deliveryMethodProposedBy !== userId) {
    return (
      <div className="px-3 py-2 bg-blue-50/60 dark:bg-blue-950/20 border-b border-blue-100 dark:border-blue-900">
        <div className="flex items-center gap-2 mb-1.5">
          <MapPin className="w-3.5 h-3.5 text-blue-600 flex-shrink-0" />
          <p className="text-[10px] text-blue-700 dark:text-blue-400 flex-1 truncate">
            📍 {otherName} usulkan COD: <strong>{barter.codAddress?.split('[')[0]?.trim()}</strong>
          </p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => onCodRespond('approve')} disabled={respondingCod} className="flex-1 py-1.5 rounded-lg bg-green-600 text-white font-semibold text-[11px] disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-1">
            {respondingCod ? <MutariInline size={12} /> : <CheckCircle2 className="w-3 h-3" />} Setuju
          </button>
          <button onClick={() => onCodRespond('reject')} disabled={respondingCod} className="flex-1 py-1.5 rounded-lg border border-destructive/40 text-destructive font-semibold text-[11px] disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-1">
            {respondingCod ? <MutariInline size={12} /> : <XCircle className="w-3 h-3" />} Tolak
          </button>
        </div>
      </div>
    );
  }

  return null;
}

function ShippingBanner({ barter, isAccepted, otherName, userId, respondingCod, onShowShipping, onCodRespond }: {
  barter: BarterType; isAccepted: boolean; otherName: string; userId?: string; respondingCod: boolean;
  onShowShipping: () => void; onCodRespond: (a: 'approve' | 'reject') => void;
