        <div className="flex gap-2">
          <button onClick={() => onCodRespond('approve')} disabled={respondingCod} className="flex-1 py-1.5 rounded-lg bg-green-600 text-white font-semibold text-[11px] disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-1">
            {respondingCod ? <MutariInline size={12} /> : <CheckCircle2 className="w-3 h-3" />} Setuju
          </button>
          <button onClick={() => onCodRespond('reject')} disabled={respondingCod} className="flex-1 py-1.5 rounded-lg border border-destructive/40 text-destructive font-semibold text-[11px] disabled:opacity-50 active:scale-[0.98] transition flex items-center justify-center gap-1">
            {respondingCod ? <MutariInline size={12} /> : <XCircle className="w-3 h-3" />} Tolak
          </button>
        </div>
      </div>
    );
  }

  return null;
}

function DepositBanner({ deposit, status, otherName }: {
  deposit: { myAmount: number; myStatus: string | null; otherAmount: number; otherStatus: string | null; totalHeld: number; depositPerPerson: number };
  status: string;
  otherName: string;
}) {
  const isHeld = deposit.myStatus === 'Held';
  const isRefunded = deposit.myStatus === 'Refunded';
  const isForfeited = deposit.myStatus === 'forfeited';
  const otherForfeited = deposit.otherStatus === 'forfeited';

  if (isHeld && (status === 'Diterima')) {
    return (
      <div className="px-3 py-1.5 bg-emerald-50/60 dark:bg-emerald-950/20 border-b border-emerald-100 dark:border-emerald-900 flex items-center gap-2">
        <ShieldCheck className="w-3.5 h-3.5 text-emerald-600 flex-shrink-0" />
        <p className="text-[10px] text-emerald-700 dark:text-emerald-400 flex-1 truncate">
          🛡️ <span className="font-bold">Jaminan Aktif</span> — {deposit.myAmount}+{deposit.otherAmount} MP ditahan
        </p>
        <span className="text-[11px] font-bold text-emerald-700 dark:text-emerald-400 flex-shrink-0">{deposit.totalHeld} MP</span>
      </div>
    );
  }

  if (isRefunded && status === 'Selesai') {
    return (
      <div className="px-3 py-1.5 bg-green-50/60 dark:bg-green-950/20 border-b border-green-100 dark:border-green-900 flex items-center gap-2">
        <ShieldCheck className="w-3.5 h-3.5 text-green-600 flex-shrink-0" />
        <p className="text-[10px] text-green-700 dark:text-green-400">
          ✅ <strong>Jaminan Dikembalikan:</strong> {deposit.myAmount} MP
        </p>
      </div>
    );
  }

  if (isForfeited && status === 'Dibatalkan') {
    return (
      <div className="px-3 py-1.5 bg-red-50/60 dark:bg-red-950/20 border-b border-red-100 dark:border-red-900 flex items-center gap-2">
        <ShieldAlert className="w-3.5 h-3.5 text-red-600 flex-shrink-0" />
        <p className="text-[10px] text-red-700 dark:text-red-400">
          ⚠️ <strong>Jaminan Hangus:</strong> {deposit.myAmount} MP diberikan ke {otherName}
        </p>
      </div>
    );
  }

  if (isRefunded && otherForfeited && status === 'Dibatalkan') {
    return (
      <div className="px-3 py-1.5 bg-blue-50/60 dark:bg-blue-950/20 border-b border-blue-100 dark:border-blue-900 flex items-center gap-2">
        <ShieldCheck className="w-3.5 h-3.5 text-blue-600 flex-shrink-0" />
        <p className="text-[10px] text-blue-700 dark:text-blue-400">
          🛡️ <strong>Kompensasi:</strong> Jaminan + {deposit.otherAmount} MP dari {otherName}
        </p>
      </div>
    );
  }

  return null;
}

