import { MutariInline } from '../components/MutariSpinner';
import { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, Check  } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { getMyItems, createBarterOffer } from 'zitejs/api';
import type { GetMyItemsOutputType } from 'zitejs/api';
import { toast } from 'sonner';
import { cleanError } from '../lib/errorMsg';

type ItemType = GetMyItemsOutputType['items'][0];

export default function BarterOfferPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const targetItemId = params.get('targetItemId') || '';
  const targetTitle = params.get('targetTitle') || 'Barang';
  const preselectedOfferId = params.get('offeredItemId') || '';

  const [items, setItems] = useState<ItemType[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState<string | null>(preselectedOfferId || null);
  const [message, setMessage] = useState('');
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    getMyItems({}).then(res => {
      setItems(res.items.filter(i => i.status === 'Tersedia'));
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const handleSubmit = async () => {
    if (!selectedId) return;
    setSubmitting(true);
    try {
      const res = await createBarterOffer({
        targetItemId,
        offeredItemId: selectedId,
        message: message || undefined,
      });
      toast.success('Penawaran barter terkirim!');
      navigate(`/barter/${res.barterId}`);
    } catch (e: unknown) {
      toast.error(cleanError(e, 'Gagal mengirim penawaran'));
    }
    setSubmitting(false);
  };

  const fmt = (v: number | null) => v ? 'Rp' + v.toLocaleString('id-ID') : '';

  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8 mutari-main">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <div className="flex-1 min-w-0">
              <h1 className="font-bold text-base">Ajukan Barter</h1>
              <p className="text-xs text-muted-foreground truncate">Untuk: {targetTitle}</p>
            </div>
          </div>
        </div>

        {/* Info */}
        <div className="px-4 pt-4 pb-2">
          <div className="bg-accent/50 rounded-xl p-3 border border-primary/10">
            <p className="text-sm text-foreground font-medium">Pilih barang milikmu yang ingin ditukar</p>
            <p className="text-xs text-muted-foreground mt-1">Barang yang sudah dalam negosiasi tidak bisa dipilih</p>
          </div>
        </div>

        {/* My items */}
        {loading ? (
          <div className="px-4 mt-4 grid grid-cols-2 gap-3 mutari-item-grid">
            {[0, 1, 2, 3].map(i => (
              <div key={i} className="rounded-2xl border border-border bg-card overflow-hidden">
                <Skeleton className="w-full aspect-square" />
                <div className="p-2.5 space-y-1.5">
                  <Skeleton className="h-4 w-3/4" />
                  <Skeleton className="h-3 w-1/2" />
                </div>
              </div>
            ))}
          </div>
        ) : items.length === 0 ? (
          <div className="px-4 py-16 text-center">
            <p className="text-muted-foreground text-sm">Kamu belum punya barang yang tersedia</p>
            <button onClick={() => navigate('/upload')} className="mt-3 text-primary text-sm font-medium">
              + Upload Barang
            </button>
          </div>
        ) : (
          <div className="px-4 py-3 space-y-2">
            {items.map(item => (
              <button
                key={item.id}
                onClick={() => setSelectedId(item.id)}
                className={`w-full flex items-center gap-3 p-3 rounded-xl border transition-all active:scale-[0.98] ${
                  selectedId === item.id
                    ? 'border-primary bg-primary/5 ring-1 ring-primary/30'
                    : 'border-border bg-card hover:bg-muted/30'
                }`}
              >
                <div className="w-16 h-16 rounded-lg overflow-hidden bg-muted flex-shrink-0">
                  {item.photo ? (
                    <img src={item.photo} alt={item.title} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-muted-foreground text-xs">No foto</div>
                  )}
                </div>
                <div className="flex-1 text-left min-w-0">
                  <p className="font-semibold text-sm truncate">{item.title}</p>
                  <p className="text-xs text-muted-foreground">{item.condition} • {item.location || 'Lokasi belum diset'}</p>
                  {(item.estimatedValueMin || item.estimatedValueMax) && (
                    <p className="text-xs text-primary font-medium mt-0.5">
                      {fmt(item.estimatedValueMin)}{item.estimatedValueMin && item.estimatedValueMax ? ' – ' : ''}{item.estimatedValueMax && item.estimatedValueMin !== item.estimatedValueMax ? fmt(item.estimatedValueMax) : ''}
                    </p>
                  )}
                </div>
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 transition ${
                  selectedId === item.id ? 'border-primary bg-primary' : 'border-border'
                }`}>
                  {selectedId === item.id && <Check className="w-3.5 h-3.5 text-primary-foreground" />}
                </div>
              </button>
            ))}
          </div>
        )}

        {/* Message input */}
        {selectedId && (
          <div className="px-4 py-3">
            <label className="text-sm font-medium text-foreground">Pesan untuk pemilik (opsional)</label>
            <textarea
              value={message}
              onChange={e => setMessage(e.target.value)}
              placeholder="Contoh: Saya tertarik menukar karena..."
              className="mt-2 w-full rounded-xl border border-border bg-card px-3 py-2.5 text-sm resize-none h-20 focus:outline-none focus:ring-1 focus:ring-primary"
            />
          </div>
        )}

        {/* Submit bar */}
        <div className="fixed bottom-0 left-0 right-0 bg-card/95 backdrop-blur-md border-t border-border z-50">
          <div className="max-w-[420px] mx-auto px-4 py-3">
            <button
              onClick={handleSubmit}
              disabled={!selectedId || submitting}
              className="w-full py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2 active:scale-[0.98] transition"
            >
              {submitting ? <MutariInline size={16} /> : null}
              {submitting ? 'Mengirim...' : 'Kirim Penawaran Barter'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

