import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { getChallengeDetail, joinChallenge } from 'zitejs/api';
import { ArrowLeft, Trophy, Users, Clock, Target, Medal, Crown, Award, Share2 } from 'lucide-react';
import { Button } from '@project/components/ui/button';
import { toast } from 'sonner';
import { cleanError } from '../lib/errorMsg';

export default function ChallengeDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [challenge, setChallenge] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [joining, setJoining] = useState(false);

  const load = () => {
    if (!id) return;
    getChallengeDetail({ id }).then(r => setChallenge(r.challenge)).catch(() => toast.error('Gagal memuat challenge')).finally(() => setLoading(false));
  };

  useEffect(load, [id]);

  const handleJoin = async () => {
    if (!id) return;
    setJoining(true);
    try {
      await joinChallenge({ challengeId: id });
      toast.success('🎉 Berhasil bergabung!');
      load();
    } catch (e: any) {
      toast.error(cleanError(e, 'Gagal bergabung'));
    } finally {
      setJoining(false);
    }
  };

  if (loading) return <div className="min-h-screen bg-background mutari-main flex items-center justify-center text-muted-foreground text-sm">Memuat...</div>;
  if (!challenge) return <div className="min-h-screen bg-background flex items-center justify-center text-muted-foreground text-sm">Challenge tidak ditemukan</div>;

  const handleShare = (ch: any) => {
    const url = `${window.location.origin}/challenge/${ch.id}`;
    const text = `🔥 Yuk ikutan MUTARI Challenge: ${ch.title}!\n${ch.description ?? ''}\n🏆 Hadiah: ${ch.reward1st?.toLocaleString() ?? '???'} poin\n\nGabung sekarang 👇\n${url}`;

    if (navigator.share) {
      navigator.share({ title: `MUTARI Challenge: ${ch.title}`, text, url }).catch(() => {});
    } else {
      const waUrl = `https://wa.me/?text=${encodeURIComponent(text)}`;
      window.open(waUrl, '_blank');
    }
  };

  const c = challenge;

  return (
    <div className="min-h-screen bg-background pb-28">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background/80 backdrop-blur-md border-b border-border px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5" /></button>
          <h1 className="font-bold text-sm truncate flex-1">{c.title}</h1>
          <button onClick={() => handleShare(c)} className="p-1.5 rounded-full hover:bg-muted transition-colors">
            <Share2 className="w-4 h-4" />
          </button>
          <StatusBadge status={c.status} />
        </div>

        {/* Banner */}
        {c.bannerImage && (
          <div className="h-40 bg-muted">
            <img src={c.bannerImage} alt="" className="w-full h-full object-cover" />
          </div>
        )}

        {/* Info */}
        <div className="p-4 space-y-4">
          <div className="flex items-start gap-3">
            <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-amber-500 to-orange-500 flex items-center justify-center text-xl flex-shrink-0">
              {c.icon || '🏆'}
            </div>
            <div>
              <h2 className="font-bold text-lg leading-tight">{c.title}</h2>
              <p className="text-muted-foreground text-xs mt-0.5">{c.type}</p>
            </div>
          </div>

          <p className="text-sm text-muted-foreground">{c.description}</p>

          {/* Stats row */}
          <div className="grid grid-cols-3 gap-2">
            <StatBox icon={<Users className="w-4 h-4 text-blue-500" />} label="Peserta" value={c.leaderboard?.length ?? 0} />
            <StatBox icon={<Clock className="w-4 h-4 text-orange-500" />} label="Sisa" value={c.daysLeft !== null ? `${c.daysLeft}h` : '-'} />
            <StatBox icon={<Target className="w-4 h-4 text-green-500" />} label="Target" value={c.minTarget ?? '-'} />
          </div>

          {/* Rewards */}
          <div className="bg-gradient-to-r from-amber-50 to-orange-50 dark:from-amber-950/30 dark:to-orange-950/30 rounded-xl p-3 space-y-2">
            <h3 className="text-xs font-semibold text-amber-800 dark:text-amber-300">🎁 Hadiah</h3>
            <div className="space-y-1.5">
              {c.reward1st && <RewardRow icon={<Crown className="w-4 h-4 text-yellow-500" />} label="Juara 1" value={`${c.reward1st.toLocaleString()} poin`} />}
              {c.reward2nd && <RewardRow icon={<Medal className="w-4 h-4 text-gray-400" />} label="Juara 2" value={`${c.reward2nd.toLocaleString()} poin`} />}
              {c.reward3rd && <RewardRow icon={<Award className="w-4 h-4 text-amber-700" />} label="Juara 3" value={`${c.reward3rd.toLocaleString()} poin`} />}
              {c.participationReward && <RewardRow icon={<Trophy className="w-4 h-4 text-blue-500" />} label="Partisipasi" value={`${c.participationReward.toLocaleString()} poin`} />}
            </div>
          </div>

          {/* My progress */}
          {c.joined && (
            <div className="bg-green-50 dark:bg-green-950/30 rounded-xl p-3">
              <h3 className="text-xs font-semibold text-green-700 dark:text-green-400 mb-2">📊 Progress Kamu</h3>
              <div className="flex items-center justify-between">
                <span className="text-sm font-bold">{c.myProgress ?? 0}</span>
                {c.myRank && <span className="text-xs text-muted-foreground">Peringkat #{c.myRank}</span>}
              </div>
              {c.minTarget && (
                <div className="mt-2">
                  <div className="h-2 bg-green-200 dark:bg-green-900 rounded-full overflow-hidden">
                    <div className="h-full bg-green-500 rounded-full transition-all" style={{ width: `${Math.min(100, ((c.myProgress ?? 0) / c.minTarget) * 100)}%` }} />
                  </div>
                  <p className="text-[10px] text-muted-foreground mt-1">{c.myProgress ?? 0} / {c.minTarget}</p>
                </div>
              )}
            </div>
          )}

          {/* Leaderboard */}
          <div>
            <h3 className="text-sm font-semibold mb-2">🏅 Leaderboard</h3>
            {(!c.leaderboard || c.leaderboard.length === 0) ? (
              <p className="text-xs text-muted-foreground text-center py-4">Belum ada peserta</p>
            ) : (
              <div className="space-y-1.5">
                {c.leaderboard.map((p: any, i: number) => (
                  <LeaderboardRow key={i} rank={p.rank} name={p.userName} progress={p.progress} image={p.userImage} />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Bottom CTA */}
        {c.status === 'Aktif' && (
          <div className="fixed bottom-0 left-0 right-0 bg-background border-t border-border p-4 z-50">
            <div className="max-w-[420px] mx-auto flex gap-2">
              {!c.joined ? (
                <Button onClick={handleJoin} disabled={joining} className="flex-1 bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white font-semibold h-12 rounded-xl text-sm">
                  {joining ? 'Bergabung...' : '🔥 Ikut Challenge Sekarang!'}
                </Button>
              ) : (
                <Button onClick={() => handleShare(c)} variant="outline" className="flex-1 h-12 rounded-xl text-sm font-semibold gap-2">
                  <Share2 className="w-4 h-4" /> Ajak Teman Ikut Challenge
                </Button>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    'Aktif': 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
    'Akan Datang': 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400',
    'Selesai': 'bg-gray-100 text-gray-600',
  };
  return <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors[status] ?? 'bg-muted text-muted-foreground'}`}>{status}</span>;
}

function StatBox({ icon, label, value }: { icon: React.ReactNode; label: string; value: string | number }) {
  return (
    <div className="bg-muted/50 rounded-lg p-2.5 text-center">
      <div className="flex justify-center mb-1">{icon}</div>
      <p className="font-bold text-sm">{value}</p>
      <p className="text-[10px] text-muted-foreground">{label}</p>
    </div>
  );
}

function RewardRow({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-center gap-2 text-sm">
      {icon}
      <span className="text-muted-foreground text-xs flex-1">{label}</span>
      <span className="font-semibold text-xs">{value}</span>
    </div>
  );
}

function LeaderboardRow({ rank, name, progress, image }: { rank: number; name: string; progress: number; image?: string }) {
  const medals = ['', '🥇', '🥈', '🥉'];
  return (
    <div className="flex items-center gap-2.5 bg-card rounded-lg px-3 py-2 border border-border">
      <span className="text-sm font-bold w-6 text-center">{medals[rank] || `#${rank}`}</span>
      <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center text-xs font-bold overflow-hidden flex-shrink-0">
        {image ? <img src={image} alt="" className="w-full h-full object-cover" /> : name[0]?.toUpperCase()}
      </div>
      <span className="text-sm flex-1 truncate">{name}</span>
      <span className="text-xs font-semibold text-amber-600 dark:text-amber-400">{progress}</span>
    </div>
  );
}

