import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getChallenges } from 'zitejs/api';
import { ArrowLeft, Trophy, Users, Clock, ChevronRight, Flame, Target, Star } from 'lucide-react';
import BottomNav from '../components/BottomNav';

type Challenge = {
  id: string;
  title: string;
  description: string;
  type: string;
  icon: string | null;
  bannerImage: string | null;
  status: string;
  startDate: string | null;
  endDate: string | null;
  daysLeft: number | null;
  minTarget: number | null;
  reward1st: number | null;
  participationReward: number | null;
  participantCount: number;
  joined: boolean;
};

const typeIcon: Record<string, typeof Trophy> = {
  'Barter Terbanyak': Target,
  'Upload Terbanyak': Star,
  'Rating Tertinggi': Star,
  'Referral Race': Users,
};

export default function ChallengesPage() {
  const navigate = useNavigate();
  const [challenges, setChallenges] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getChallenges({}).then(r => setChallenges(r.challenges ?? [])).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const active = challenges.filter(c => c.status === 'Aktif');
  const upcoming = challenges.filter(c => c.status === 'Akan Datang');

  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8 mutari-main">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="p-1"><ArrowLeft className="w-5 h-5" /></button>
          <div className="flex items-center gap-2">
            <Flame className="w-5 h-5 text-orange-500" />
            <h1 className="font-bold text-lg">MUTARI Challenge</h1>
          </div>
        </div>

        {loading ? (
          <div className="p-8 text-center text-muted-foreground text-sm">Memuat challenge...</div>
        ) : challenges.length === 0 ? (
          <div className="p-12 text-center">
            <Trophy className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
            <p className="text-muted-foreground text-sm">Belum ada challenge aktif saat ini</p>
            <p className="text-muted-foreground/60 text-xs mt-1">Nantikan challenge seru dari MUTARI!</p>
          </div>
        ) : (
          <div className="p-4 space-y-6">
            {active.length > 0 && <ChallengeSection title="🔥 Challenge Aktif" items={active} navigate={navigate} />}
            {upcoming.length > 0 && <ChallengeSection title="📅 Akan Datang" items={upcoming} navigate={navigate} />}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}

function ChallengeSection({ title, items, navigate }: { title: string; items: Challenge[]; navigate: any }) {
  return (
    <div>
      <h2 className="text-sm font-semibold text-foreground mb-3">{title}</h2>
      <div className="space-y-3">
        {items.map(c => <ChallengeCard key={c.id} challenge={c} onClick={() => navigate(`/challenge/${c.id}`)} />)}
      </div>
    </div>
  );
}

function ChallengeCard({ challenge: c, onClick }: { challenge: Challenge; onClick: () => void }) {
  const IconComp = typeIcon[c.type ?? ''] ?? Trophy;

  return (
    <div onClick={onClick} className="bg-card rounded-xl border border-border overflow-hidden cursor-pointer active:scale-[0.98] transition-transform">
      {c.bannerImage && (
        <div className="h-28 bg-muted">
          <img src={c.bannerImage} alt="" className="w-full h-full object-cover" />
        </div>
      )}
      <div className="p-3">
        <div className="flex items-start gap-2.5">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-500 to-orange-500 flex items-center justify-center flex-shrink-0 text-lg">
            {c.icon || '🏆'}
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-0.5">
              <h3 className="font-semibold text-sm truncate">{c.title}</h3>
              {c.joined && (
                <span className="bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 text-[9px] font-bold px-1.5 py-0.5 rounded-full flex-shrink-0">
                  JOINED
                </span>
              )}
            </div>
            <p className="text-muted-foreground text-xs line-clamp-2 mb-2">{c.description}</p>

            <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
              <span className="flex items-center gap-1">
                <Users className="w-3 h-3" /> {c.participantCount}
              </span>
              {c.daysLeft !== null && (
                <span className="flex items-center gap-1">
                  <Clock className="w-3 h-3" /> {c.status === 'Akan Datang' ? 'Mulai' : ''} {c.daysLeft}h
                </span>
              )}
              {c.reward1st && (
                <span className="flex items-center gap-1 text-amber-600 dark:text-amber-400 font-medium">
                  <Trophy className="w-3 h-3" /> {c.reward1st.toLocaleString()} pts
                </span>
              )}
            </div>
          </div>
          <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0 mt-1" />
        </div>
      </div>
    </div>
  );
}

