import { useState, useEffect, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, MessageCircle, Repeat, Package, Clock } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { getActiveChats, markNotificationRead } from 'zitejs/api';
import type { GetActiveChatsOutputType } from 'zitejs/api';
import { formatDistanceToNow } from 'date-fns';
import { id as localeId } from 'date-fns/locale';
import BottomNav from '../components/BottomNav';
import { useUnread } from '../context/UnreadContext';

type ChatItem = GetActiveChatsOutputType['chats'][0];

export default function ChatPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [chats, setChats] = useState<ChatItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'barter' | 'direct'>('barter');
  const [barterSub, setBarterSub] = useState<'active' | 'history'>('active');
  const autoTabDone = useRef(false);
  const { refresh: refreshUnread } = useUnread();

  // Mark all chat notifications as read when page opens
  useEffect(() => {
    markNotificationRead({ markAllType: 'Chat' }).then(() => refreshUnread()).catch(() => {});
  }, [refreshUnread]);

  useEffect(() => {
    getActiveChats({}).then(res => {
      setChats(res.chats);
      setLoading(false);

      // Auto-select tab with unread messages
      if (!autoTabDone.current) {
        autoTabDone.current = true;
        const paramTab = searchParams.get('tab');
        if (paramTab === 'direct' || paramTab === 'barter') {
          setTab(paramTab);
        } else {
          const unreadBarter = res.chats.filter(c => c.chatType === 'barter' && c.unread > 0).length;
          const unreadDirect = res.chats.filter(c => c.chatType === 'direct' && c.unread > 0).length;
          if (unreadDirect > 0 && unreadBarter === 0) {
            setTab('direct');
          } else {
            setTab('barter');
          }
        }
      }
    }).catch(() => setLoading(false));
  }, [searchParams]);

  const filtered = tab === 'direct'
    ? chats.filter(c => c.chatType === 'direct')
    : chats.filter(c => {
        if (c.chatType !== 'barter') return false;
        const isActive = c.status === 'Menunggu' || c.status === 'Diterima';
        return barterSub === 'active' ? isActive : !isActive;
      });

  const barterActiveCount = chats.filter(c => c.chatType === 'barter' && (c.status === 'Menunggu' || c.status === 'Diterima')).length;
  const barterHistoryCount = chats.filter(c => c.chatType === 'barter' && c.status !== 'Menunggu' && c.status !== 'Diterima').length;

  return (
    <div className="min-h-screen bg-background pb-20 lg:pb-8 mutari-main">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate('/')} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
              <ArrowLeft className="w-5 h-5" />
            </button>
            <h1 className="font-bold text-lg">Chat</h1>
          </div>
          {/* Tabs */}
          <div className="flex gap-1 px-4 pb-2">
            {([
              { key: 'barter' as const, label: 'Pesan Negosiasi', icon: Repeat },
              { key: 'direct' as const, label: 'Pesan Pribadi', icon: MessageCircle },
            ]).map(t => {
              const unreadCount = chats.filter(c => c.chatType === t.key && c.unread > 0).length;
              const active = tab === t.key;
              return (
                <button
                  key={t.key}
                  onClick={() => setTab(t.key)}
                  className={`flex items-center gap-1.5 px-3.5 py-1.5 rounded-full text-xs font-medium transition ${
                    active
                      ? 'bg-primary text-primary-foreground'
                      : 'bg-muted text-muted-foreground hover:bg-muted/80'
                  }`}
                >
                  <t.icon className="w-3.5 h-3.5" />
                  {t.label}
                  {unreadCount > 0 && (
                    <span className={`min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded-full text-[9px] font-bold ${
                      active ? 'bg-primary-foreground/20 text-primary-foreground' : 'bg-destructive text-destructive-foreground'
                    }`}>
                      {unreadCount}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
          {/* Barter sub-tabs */}
          {tab === 'barter' && (
            <div className="flex gap-1 px-4 pb-2">
              <button
                onClick={() => setBarterSub('active')}
                className={`flex items-center gap-1 px-3 py-1 rounded-full text-[11px] font-medium transition ${
                  barterSub === 'active'
                    ? 'bg-primary/10 text-primary'
                    : 'bg-muted/60 text-muted-foreground hover:bg-muted'
                }`}
              >
                <Repeat className="w-3 h-3" />
                Aktif ({barterActiveCount})
              </button>
              <button
                onClick={() => setBarterSub('history')}
                className={`flex items-center gap-1 px-3 py-1 rounded-full text-[11px] font-medium transition ${
                  barterSub === 'history'
                    ? 'bg-primary/10 text-primary'
                    : 'bg-muted/60 text-muted-foreground hover:bg-muted'
                }`}
              >
                <Clock className="w-3 h-3" />
                Riwayat ({barterHistoryCount})
              </button>
            </div>
          )}
        </div>

        {loading ? (
          <div className="divide-y divide-border">
            {[0, 1, 2, 3].map(i => (
              <div key={i} className="px-4 py-3 flex items-center gap-3">
                <Skeleton className="w-12 h-12 rounded-lg" />
                <div className="flex-1 space-y-2">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-3 w-48" />
                </div>
              </div>
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
            <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mb-4">
              <MessageCircle className="w-8 h-8 text-muted-foreground" />
            </div>
            <p className="text-muted-foreground text-sm font-medium">
              {tab === 'barter' && barterSub === 'history' ? 'Belum ada riwayat negosiasi' : 'Belum ada percakapan'}
            </p>
            <p className="text-muted-foreground text-xs mt-1">
              {tab === 'barter' && barterSub === 'history' ? 'Chat negosiasi yang selesai akan muncul di sini' : 'Mulai chat dari halaman detail barang'}
            </p>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {filtered.map(chat => (
              <ChatRow key={chat.id} chat={chat} navigate={navigate} />
            ))}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}

function ChatRow({ chat, navigate }: { chat: ChatItem; navigate: ReturnType<typeof useNavigate> }) {
  const handleClick = () => {
    if (chat.chatType === 'direct') {
      navigate(`/direct-chat?userId=${chat.otherUserId}&itemId=${chat.itemId || ''}&itemTitle=${encodeURIComponent(chat.itemTitle || chat.title)}`);
    } else {
      navigate(`/barter/${chat.id}`);
    }
  };

  const hasUnread = chat.unread > 0;

  return (
    <button
      onClick={handleClick}
      className={`w-full flex items-center gap-3 px-4 py-3 transition active:bg-muted/50 text-left ${
        hasUnread ? 'bg-primary/[0.04] hover:bg-primary/[0.07]' : 'hover:bg-muted/30'
      }`}
    >
      {/* Photo / Avatar */}
      {chat.chatType === 'direct' ? (
        <div className="flex-shrink-0 relative w-12 h-12">
          {chat.itemPhoto ? (
            <img src={chat.itemPhoto} className="w-12 h-12 rounded-lg object-cover border border-border" />
          ) : (
            <div className="w-12 h-12 rounded-lg bg-primary/10 flex items-center justify-center border border-border">
              <Package className="w-5 h-5 text-primary" />
            </div>
          )}
          {/* User avatar overlay */}
          {chat.otherUserImage ? (
            <img src={chat.otherUserImage} className="w-6 h-6 rounded-full object-cover border-2 border-card absolute -bottom-1 -right-1" />
          ) : (
            <div className="w-6 h-6 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-[9px] font-bold border-2 border-card absolute -bottom-1 -right-1">
              {chat.otherUserName[0]?.toUpperCase() || 'P'}
            </div>
          )}
        </div>
      ) : (
        <div className="flex-shrink-0 relative w-12 h-12">
          <div className="w-10 h-10 rounded-lg overflow-hidden bg-muted absolute top-0 left-0 border-2 border-card">
            {chat.offeredItemPhoto ? (
              <img src={chat.offeredItemPhoto} className="w-full h-full object-cover" />
            ) : (
              <div className="w-full h-full bg-primary/10 flex items-center justify-center text-primary text-xs font-bold">B</div>
            )}
          </div>
          <div className="w-10 h-10 rounded-lg overflow-hidden bg-muted absolute bottom-0 right-0 border-2 border-card">
            {chat.requestedItemPhoto ? (
              <img src={chat.requestedItemPhoto} className="w-full h-full object-cover" />
            ) : (
              <div className="w-full h-full bg-accent flex items-center justify-center text-primary text-xs font-bold">B</div>
            )}
          </div>
        </div>
      )}

      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between">
          <p className={`text-sm truncate ${hasUnread ? 'font-bold text-foreground' : 'font-semibold text-foreground'}`}>
            {chat.otherUserName}
          </p>
          <div className="flex items-center gap-1.5 flex-shrink-0 ml-2">
            {hasUnread && (
              <span className="min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded-full bg-destructive text-destructive-foreground text-[9px] font-bold">
                {chat.unread > 99 ? '99+' : chat.unread}
              </span>
            )}
            {chat.lastMessageAt && (
              <span className={`text-[10px] ${hasUnread ? 'text-primary font-semibold' : 'text-muted-foreground'}`}>
                {formatDistanceToNow(new Date(chat.lastMessageAt), { addSuffix: true, locale: localeId })}
              </span>
            )}
          </div>
        </div>
        <p className={`text-xs truncate mt-0.5 ${hasUnread ? 'text-foreground font-medium' : 'text-muted-foreground'}`}>
          {chat.lastMessage || chat.title}
        </p>
        <div className="flex items-center gap-1.5 mt-1">
          {chat.chatType === 'barter' ? (
            <span className={`inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[9px] font-semibold ${
              chat.status === 'Menunggu' || chat.status === 'Diterima'
                ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400'
                : chat.status === 'Selesai'
                  ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400'
                  : 'bg-muted text-muted-foreground'
            }`}>
              <Repeat className="w-2.5 h-2.5" /> {chat.status}
            </span>
          ) : chat.itemTitle ? (
            <span className="inline-block px-1.5 py-0.5 rounded text-[9px] font-medium bg-accent text-primary truncate max-w-[180px]">
              {chat.itemTitle}
            </span>
          ) : null}
        </div>
      </div>
    </button>
  );
}

