import { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getCommunityDetail, joinCommunity, createCommunityPost, updateCommunitySettings, getMyItems, manageCommunityMember, manageCommunityPost } from 'zitejs/api';
import {
  ArrowLeft, Users, MapPin, Crown, Shield, MessageSquare, Trophy, Heart,
  Pin, Plus, Send, Megaphone, Calendar, Star, Settings, Package,
  ExternalLink, Share2, TrendingUp, Globe, Lock, Copy, Check,
  MoreVertical, Trash2, PinOff, UserMinus, ChevronUp, ChevronDown, AlertTriangle,
} from 'lucide-react';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';
import BottomNav from '../components/BottomNav';

type CommunityDetail = Awaited<ReturnType<typeof getCommunityDetail>>;

const ITEM_LINK_RE = /\u{1F517}\s*\/item\/([a-zA-Z0-9_-]+)/u;
const URL_RE = /(https?:\/\/[^\s<>"',)]+)/g;
const BARE_ITEM_RE = /\/item\/([a-zA-Z0-9_-]+)/;

export default function CommunityDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [data, setData] = useState<CommunityDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'feed' | 'members' | 'leaderboard' | 'settings'>('feed');
  const [showPostForm, setShowPostForm] = useState(false);
  const [joining, setJoining] = useState(false);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try { setData(await getCommunityDetail({ communityId: id })); } catch { toast.error('Gagal memuat komunitas'); }
    setLoading(false);
  }, [id]);

  useEffect(() => { load(); }, [load]);

  const handleJoin = async () => {
    if (!id) return;
    setJoining(true);
    try { const r = await joinCommunity({ communityId: id, action: 'join' }); toast.success(r.message); load(); } catch (e: any) { toast.error(e?.message || 'Gagal'); }
    setJoining(false);
  };

  const handleLeave = async () => {
    if (!id) return;
    try { const r = await joinCommunity({ communityId: id, action: 'leave' }); toast.success(r.message); load(); } catch (e: any) { toast.error(e?.message || 'Gagal'); }
  };

  if (loading || !data) {
    return (
      <div className="min-h-screen bg-background lg:pl-[220px] xl:pl-[240px] flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-2 border-primary border-t-transparent rounded-full" />
      </div>
    );
  }

  const { community: c, myMembership, members, posts, leaderboard } = data;
  const isKetua = myMembership.role === 'ketua' || myMembership.role === 'Ketua';
  const isMod = myMembership.role === 'moderator' || myMembership.role === 'Moderator';
  const isAdmin = isKetua || isMod;

  const tabs = [
    { id: 'feed' as const, label: 'Feed', icon: MessageSquare, count: posts.length },
    { id: 'members' as const, label: 'Anggota', icon: Users, count: c.memberCount },
    { id: 'leaderboard' as const, label: 'Peringkat', icon: Trophy, count: undefined },
    ...(isKetua ? [{ id: 'settings' as const, label: 'Pengaturan', icon: Settings, count: undefined }] : []),
  ];

  return (
    <div className="min-h-screen bg-background lg:pl-[220px] xl:pl-[240px]">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-card/95 backdrop-blur-md border-b border-border">
        <div className="max-w-2xl mx-auto px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="p-1.5 rounded-full hover:bg-accent"><ArrowLeft className="w-5 h-5" /></button>
          <div className="flex-1 min-w-0">
            <h1 className="text-lg font-bold text-foreground truncate">{c.name}</h1>
            <p className="text-xs text-muted-foreground">{c.memberCount} anggota &bull; {c.city}</p>
          </div>
          {isKetua && (
            <button onClick={() => setActiveTab('settings')} className="p-2 rounded-full hover:bg-accent transition-colors" title="Pengaturan Komunitas">
              <Settings className="w-5 h-5 text-foreground" />
            </button>
          )}
          {isAdmin && (
            <span className={`flex items-center gap-1 text-xs px-2 py-1 rounded-full font-medium ${isKetua ? 'bg-amber-500/10 text-amber-600' : 'bg-blue-500/10 text-blue-600'}`}>
              {isKetua ? <Crown className="w-3 h-3" /> : <Shield className="w-3 h-3" />}
              {isKetua ? 'Ketua' : 'Mod'}
            </span>
          )}
        </div>
      </div>

      <div className="max-w-2xl mx-auto px-4 pb-24">
        {/* Hero */}
        <div className="mt-4 bg-card rounded-2xl border border-border overflow-hidden">
          <div className="h-20 bg-gradient-to-br from-primary/20 via-primary/10 to-accent/20 relative">
            <div className="absolute -bottom-7 left-4">
              <div className="w-14 h-14 rounded-xl bg-card border-2 border-card flex items-center justify-center text-3xl shadow-lg">{c.icon || '\u{1F3D8}\uFE0F'}</div>
            </div>
          </div>
          <div className="pt-10 px-4 pb-4">
            <p className="text-sm text-muted-foreground">{c.description}</p>
            <div className="flex items-center gap-3 mt-2">
              <span className="flex items-center gap-1 text-xs text-muted-foreground"><MapPin className="w-3 h-3" /> {c.city}, {c.province}</span>
              <span className="flex items-center gap-1 text-xs text-muted-foreground">
                {c.joinMode === 'open' || c.joinMode === 'Terbuka' ? <><Globe className="w-3 h-3" /> Terbuka</> : <><Lock className="w-3 h-3" /> Persetujuan</>}
              </span>
            </div>
            <div className="flex gap-4 mt-4 pt-3 border-t border-border">
              <StatPill icon={'\u{1F465}'} label="Anggota" value={c.memberCount} />
              <StatPill icon={'\u{1F504}'} label="Barter" value={c.barterCount} />
              <StatPill icon={'\u{1F4DD}'} label="Post" value={posts.length} />
            </div>
            <div className="flex items-center gap-2 mt-3 pt-3 border-t border-border">
              {c.creatorImage ? <img src={c.creatorImage} className="w-6 h-6 rounded-full object-cover" alt="" /> : <div className="w-6 h-6 rounded-full bg-primary/15 flex items-center justify-center text-[10px] font-bold text-primary">{c.creatorName[0]}</div>}
              <span className="text-xs text-muted-foreground">Dibuat oleh <strong className="text-foreground">{c.creatorName}</strong></span>
              <Crown className="w-3 h-3 text-amber-500" />
              {c.createdAt && <span className="text-[10px] text-muted-foreground ml-auto">{formatDistanceToNow(new Date(c.createdAt), { locale: idLocale, addSuffix: true })}</span>}
            </div>
            {!myMembership.isMember ? (
              <button onClick={handleJoin} disabled={joining} className="mt-4 w-full py-2.5 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50 flex items-center justify-center gap-2">
                {joining ? <div className="w-4 h-4 border-2 border-primary-foreground border-t-transparent rounded-full animate-spin" /> : '\u{1F64C}'} {joining ? 'Bergabung...' : 'Gabung Komunitas'}
              </button>
            ) : !isKetua ? (
              <button onClick={handleLeave} className="mt-4 w-full py-2.5 rounded-xl bg-muted text-muted-foreground font-medium text-sm">Keluar Komunitas</button>
            ) : null}
          </div>
        </div>

        {c.rules && (
          <div className="mt-3 p-3 rounded-xl bg-muted/50 border border-border/50">
            <p className="text-xs font-medium text-muted-foreground mb-1">{'\u{1F4CB}'} Aturan Komunitas</p>
            <p className="text-xs text-foreground whitespace-pre-wrap">{c.rules}</p>
          </div>
        )}

        {/* Role capabilities info */}
        {isAdmin && (
          <div className="mt-3 p-3 rounded-xl bg-amber-500/5 border border-amber-500/15">
            <p className="text-xs font-semibold text-foreground mb-1.5 flex items-center gap-1.5">
              {isKetua ? <Crown className="w-3.5 h-3.5 text-amber-500" /> : <Shield className="w-3.5 h-3.5 text-blue-500" />}
              Hak Akses {isKetua ? 'Ketua' : 'Moderator'}
            </p>
            <div className="grid grid-cols-1 gap-1 text-[10px] text-muted-foreground">
              {isKetua && (
                <>
                  <span>{'\u2705'} Edit pengaturan & aturan komunitas</span>
                  <span>{'\u2705'} Promosikan anggota jadi Moderator</span>
                  <span>{'\u2705'} Turunkan role Moderator</span>
                  <span>{'\u2705'} Sematkan & lepas sematan post</span>
                  <span>{'\u2705'} Hapus post siapa saja</span>
                  <span>{'\u2705'} Keluarkan anggota & moderator</span>
                  <span>{'\u2705'} Buat pengumuman resmi</span>
                </>
              )}
              {isMod && !isKetua && (
                <>
                  <span>{'\u2705'} Hapus post anggota biasa</span>
                  <span>{'\u2705'} Keluarkan anggota biasa</span>
                  <span>{'\u2705'} Buat pengumuman</span>
                  <span>{'\u274C'} Tidak bisa edit pengaturan komunitas</span>
                  <span>{'\u274C'} Tidak bisa ubah role anggota</span>
                  <span>{'\u274C'} Tidak bisa sematkan post</span>
                </>
              )}
            </div>
          </div>
        )}

        {/* Points info */}
        <div className="mt-3 p-3 rounded-xl bg-primary/5 border border-primary/10">
          <p className="text-xs font-semibold text-foreground mb-1">{'\u{1F4B0}'} Poin Komunitas (MP)</p>
          <div className="grid grid-cols-2 gap-1.5 text-[10px] text-muted-foreground">
            <span>{'\u2022'} Posting diskusi/share: <strong className="text-foreground">+2 MP</strong></span>
            <span>{'\u2022'} Buat event barter: <strong className="text-foreground">+3 MP</strong></span>
            <span>{'\u2022'} Barter selesai via komunitas: <strong className="text-emerald-600">+3 MP bonus</strong></span>
            <span>{'\u2022'} Anggota baru bergabung (Ketua): <strong className="text-foreground">+10 MP</strong></span>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-1 mt-4 bg-muted rounded-xl p-1">
          {tabs.map(t => (
            <button key={t.id} onClick={() => setActiveTab(t.id)} className={`flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-lg text-xs font-medium transition-colors ${activeTab === t.id ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground'}`}>
              <t.icon className="w-3.5 h-3.5" /> {t.label}
              {t.count !== undefined && <span className="text-[10px] opacity-60">({t.count})</span>}
            </button>
          ))}
        </div>

        {activeTab === 'feed' && <FeedTab posts={posts} isMember={myMembership.isMember} isKetua={isKetua} isMod={isMod} communityId={id!} onRefresh={load} showPostForm={showPostForm} setShowPostForm={setShowPostForm} />}
        {activeTab === 'members' && <MembersTab members={members} isKetua={isKetua} isMod={isMod} communityId={id!} onRefresh={load} />}
        {activeTab === 'leaderboard' && <LeaderboardTab leaderboard={leaderboard} />}
        {activeTab === 'settings' && isKetua && <SettingsTab community={c} onRefresh={load} />}
      </div>

      {myMembership.isMember && activeTab === 'feed' && (
        <button
          onClick={() => {
            if (showPostForm) {
              document.getElementById('community-post-form')?.scrollIntoView({ behavior: 'smooth' });
            } else {
              setShowPostForm(true);
              setTimeout(() => document.getElementById('community-post-form')?.scrollIntoView({ behavior: 'smooth' }), 100);
            }
          }}
          className="fixed bottom-20 right-4 lg:bottom-6 lg:right-8 w-14 h-14 rounded-full bg-primary text-primary-foreground flex items-center justify-center shadow-lg shadow-primary/30 z-40"
        >
          <Plus className="w-6 h-6" />
        </button>
      )}
      <BottomNav />
    </div>
  );
}

function StatPill({ icon, label, value }: { icon: string; label: string; value: number }) {
  return (
    <div className="flex-1 text-center">
      <p className="text-lg font-bold text-foreground">{value}</p>
      <p className="text-[10px] text-muted-foreground">{icon} {label}</p>
    </div>
  );
}

function PostContent({ content, navigate }: { content: string; navigate: ReturnType<typeof useNavigate> }) {
  const itemLinkMatch = content.match(ITEM_LINK_RE);
  const textClean = content.replace(ITEM_LINK_RE, '').trim();

  const renderLinkedText = (text: string) => {
    const parts = text.split(URL_RE);
    return parts.map((part, i) => {
      if (URL_RE.test(part)) {
        const internalMatch = part.match(BARE_ITEM_RE);
        if (internalMatch) {
          return (
            <button key={i} onClick={() => navigate('/item/' + internalMatch[1])} className="text-primary underline underline-offset-2 hover:text-primary/80 inline">
              {'\u{1F517}'} Lihat Barang
            </button>
          );
        }
        return (
          <a key={i} href={part} target="_blank" rel="noopener noreferrer" className="text-primary underline underline-offset-2 hover:text-primary/80 break-all">
            {part.length > 50 ? part.slice(0, 47) + '...' : part}
          </a>
        );
      }
      const subParts = part.split(/(\/item\/[a-zA-Z0-9_-]+)/);
      return subParts.map((sub, j) => {
        const bareMatch = sub.match(BARE_ITEM_RE);
        if (bareMatch) {
          return (
            <button key={i + '-' + j} onClick={() => navigate('/item/' + bareMatch[1])} className="text-primary underline underline-offset-2 hover:text-primary/80 inline">
              {'\u{1F517}'} Lihat Barang
            </button>
          );
        }
        return <span key={i + '-' + j}>{sub}</span>;
      });
    });
  };

  return (
    <div className="mt-1">
      <p className="text-sm text-muted-foreground whitespace-pre-wrap">{renderLinkedText(textClean)}</p>
      {itemLinkMatch && (
        <button onClick={() => navigate('/item/' + itemLinkMatch[1])} className="mt-2 w-full flex items-center gap-2 bg-emerald-500/10 border border-emerald-500/20 rounded-xl p-2.5 text-left hover:bg-emerald-500/15 transition-colors">
          <div className="w-8 h-8 rounded-lg bg-emerald-500/20 flex items-center justify-center"><ExternalLink className="w-4 h-4 text-emerald-600" /></div>
          <div className="flex-1 min-w-0">
            <p className="text-xs font-semibold text-emerald-700 dark:text-emerald-400">Lihat Barang</p>
            <p className="text-[10px] text-emerald-600/70">Klik untuk melihat detail barang ini</p>
          </div>
          <ExternalLink className="w-3.5 h-3.5 text-emerald-500 flex-shrink-0" />
        </button>
      )}
    </div>
  );
}

/* ─── Post action menu for admin/mod ─── */
function PostActionMenu({ postId, communityId, pinned, isKetua, isMod, onRefresh }: {
  postId: string; communityId: string; pinned: boolean; isKetua: boolean; isMod: boolean; onRefresh: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [acting, setActing] = useState(false);

  const doAction = async (action: 'pin' | 'unpin' | 'delete') => {
    setActing(true);
    try {
      const r = await manageCommunityPost({ communityId, postId, action });
      toast.success(r.message);
      onRefresh();
    } catch (e: any) { toast.error(e?.message || 'Gagal'); }
    setActing(false);
    setOpen(false);
  };

  if (!isKetua && !isMod) return null;

  return (
    <div className="relative">
      <button onClick={() => setOpen(!open)} className="p-1.5 rounded-full hover:bg-muted transition-colors" disabled={acting}>
        <MoreVertical className="w-4 h-4 text-muted-foreground" />
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-30" onClick={() => setOpen(false)} />
          <div className="absolute right-0 top-8 z-40 bg-card rounded-xl border border-border shadow-lg py-1 min-w-[160px]">
            {isKetua && (
              <button onClick={() => doAction(pinned ? 'unpin' : 'pin')} className="w-full flex items-center gap-2 px-3 py-2 text-xs hover:bg-muted transition-colors text-foreground">
                {pinned ? <PinOff className="w-3.5 h-3.5" /> : <Pin className="w-3.5 h-3.5" />}
                {pinned ? 'Lepas Sematan' : 'Sematkan Post'}
              </button>
            )}
            <button onClick={() => doAction('delete')} className="w-full flex items-center gap-2 px-3 py-2 text-xs hover:bg-destructive/10 transition-colors text-destructive">
              <Trash2 className="w-3.5 h-3.5" /> Hapus Post
            </button>
          </div>
        </>
      )}
    </div>
  );
}

function FeedTab({ posts, isMember, isKetua, isMod, communityId, onRefresh, showPostForm, setShowPostForm }: {
  posts: CommunityDetail['posts']; isMember: boolean; isKetua: boolean; isMod: boolean; communityId: string; onRefresh: () => void; showPostForm: boolean; setShowPostForm: (v: boolean) => void;
}) {
  const navigate = useNavigate();
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [postType, setPostType] = useState<'discussion' | 'announcement' | 'event' | 'showcase' | 'item_share'>('discussion');
  const [posting, setPosting] = useState(false);
  const [showItemPicker, setShowItemPicker] = useState(false);
  const [myItems, setMyItems] = useState<{ id: string; title: string; photo: string }[]>([]);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);
  const [loadingItems, setLoadingItems] = useState(false);

  const loadMyItems = async () => {
    setLoadingItems(true);
    try {
      const res = await getMyItems({});
      setMyItems(res.items.map(i => ({ id: i.id, title: i.title, photo: (i as any).photos?.[0]?.url || '' })));
    } catch {}
    setLoadingItems(false);
  };

  const handleShareItem = () => {
    setPostType('item_share');
    setShowItemPicker(true);
    setShowPostForm(true);
    loadMyItems();
  };

  const selectItem = (item: { id: string; title: string; photo: string }) => {
    setSelectedItemId(item.id);
    setTitle('\u{1F4E6} ' + item.title);
    setContent('Cek barang ini, mungkin ada yang tertarik barter! \u{1F447}\n\n' + window.location.origin + '/item/' + item.id);
    setShowItemPicker(false);
  };

  const handlePost = async () => {
    if (!title || !content || posting) return;
    setPosting(true);
    try {
      const res = await createCommunityPost({ communityId, title, content, type: postType, ...(postType === 'item_share' && selectedItemId ? { sharedItemId: selectedItemId } : {}) });
      toast.success('Post berhasil! +' + res.pointsEarned + ' MP');
      setTitle(''); setContent(''); setShowPostForm(false); setSelectedItemId(null); setPostType('discussion');
      onRefresh();
    } catch (e: any) { toast.error(e?.message || 'Gagal'); }
    setPosting(false);
  };

  const typeConfig: Record<string, { icon: typeof Megaphone; color: string; label: string }> = {
    announcement: { icon: Megaphone, color: 'text-red-500', label: 'Pengumuman' },
    discussion: { icon: MessageSquare, color: 'text-blue-500', label: 'Diskusi' },
    event: { icon: Calendar, color: 'text-purple-500', label: 'Event Barter' },
    showcase: { icon: Star, color: 'text-amber-500', label: 'Showcase' },
    item_share: { icon: Package, color: 'text-emerald-500', label: 'Bagikan Barang' },
    Showcase: { icon: Star, color: 'text-amber-500', label: 'Showcase' },
  };

  return (
    <div className="mt-4 space-y-3">
      {isMember && !showPostForm && (
        <div className="flex gap-2">
          <button onClick={handleShareItem} className="flex-1 flex items-center gap-2 bg-emerald-500/10 hover:bg-emerald-500/15 border border-emerald-500/20 rounded-2xl p-3 transition-colors">
            <div className="w-9 h-9 rounded-lg bg-emerald-500/20 flex items-center justify-center"><Package className="w-4 h-4 text-emerald-600" /></div>
            <div className="flex-1 text-left min-w-0">
              <p className="text-xs font-semibold text-emerald-700 dark:text-emerald-400">Bagikan Barang</p>
              <p className="text-[10px] text-emerald-600/70 truncate">Share dari daftar upload-mu</p>
            </div>
          </button>
          <button onClick={() => { setPostType('discussion'); setShowPostForm(true); }} className="flex-1 flex items-center gap-2 bg-blue-500/10 hover:bg-blue-500/15 border border-blue-500/20 rounded-2xl p-3 transition-colors">
            <div className="w-9 h-9 rounded-lg bg-blue-500/20 flex items-center justify-center"><MessageSquare className="w-4 h-4 text-blue-600" /></div>
            <div className="flex-1 text-left min-w-0">
              <p className="text-xs font-semibold text-blue-700 dark:text-blue-400">Tulis Diskusi</p>
              <p className="text-[10px] text-blue-600/70 truncate">Tanya atau ngobrol</p>
            </div>
          </button>
        </div>
      )}

      {showPostForm && isMember && (
        <div id="community-post-form" className="bg-card rounded-2xl border border-primary/20 p-4">
          <h3 className="text-sm font-semibold mb-3">Buat Post</h3>
          {showItemPicker && (
            <div className="mb-3 bg-muted/50 rounded-xl p-3">
              <p className="text-xs font-semibold text-muted-foreground mb-2">{'\u{1F4E6}'} Pilih barang:</p>
              {loadingItems ? (
                <div className="flex items-center justify-center py-4"><div className="w-5 h-5 border-2 border-primary border-t-transparent rounded-full animate-spin" /></div>
              ) : myItems.length === 0 ? (
                <p className="text-xs text-muted-foreground text-center py-3">Belum ada barang yang di-upload</p>
              ) : (
                <div className="space-y-1.5 max-h-48 overflow-y-auto">
                  {myItems.map(item => (
                    <button key={item.id} onClick={() => selectItem(item)} className={`w-full flex items-center gap-2.5 p-2 rounded-lg text-left transition-colors ${selectedItemId === item.id ? 'bg-primary/10 border border-primary/30' : 'hover:bg-muted'}`}>
                      {item.photo ? <img src={item.photo} alt="" className="w-10 h-10 rounded-lg object-cover" /> : <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center"><Package className="w-4 h-4 text-muted-foreground" /></div>}
                      <span className="text-xs font-medium truncate flex-1">{item.title}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          <div className="flex flex-wrap gap-2 mb-3">
            {Object.entries(typeConfig).filter(([k]) => k !== 'Showcase').map(([key, cfg]) => {
              if (key === 'announcement' && !isKetua && !isMod) return null;
              return (
                <button key={key} onClick={() => setPostType(key as any)} className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${postType === key ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>
                  <cfg.icon className="w-3 h-3" /> {cfg.label}
                </button>
              );
            })}
          </div>
          <input value={title} onChange={e => setTitle(e.target.value)} placeholder="Judul..." className="w-full px-3 py-2 rounded-xl bg-muted text-sm mb-2 focus:outline-none focus:ring-2 focus:ring-primary/30" />
          <textarea value={content} onChange={e => setContent(e.target.value)} placeholder="Tulis sesuatu... (link akan otomatis bisa diklik)" rows={4} className="w-full px-3 py-2 rounded-xl bg-muted text-sm resize-none focus:outline-none focus:ring-2 focus:ring-primary/30" />
          <p className="text-[10px] text-muted-foreground mt-1 mb-2">{'\u{1F4A1}'} Tip: Paste link barang agar anggota bisa klik. Setiap post +2 MP, barter selesai dari komunitas +3 MP bonus!</p>
          <div className="flex gap-2 mt-2">
            <button onClick={() => { setShowPostForm(false); setShowItemPicker(false); }} className="flex-1 py-2 rounded-xl bg-muted text-sm font-medium text-muted-foreground">Batal</button>
            <button onClick={handlePost} disabled={!title || !content || posting} className="flex-1 py-2 rounded-xl bg-primary text-primary-foreground text-sm font-semibold disabled:opacity-40 flex items-center justify-center gap-1">
              <Send className="w-3.5 h-3.5" /> {posting ? 'Posting...' : 'Kirim'}
            </button>
          </div>
        </div>
      )}

      {posts.length === 0 ? (
        <div className="text-center py-12 bg-card rounded-2xl border border-border">
          <div className="w-16 h-16 mx-auto rounded-full bg-muted flex items-center justify-center mb-3"><MessageSquare className="w-7 h-7 text-muted-foreground/40" /></div>
          <p className="text-sm font-medium text-foreground">Belum ada post</p>
          <p className="text-xs text-muted-foreground mt-1">Jadilah yang pertama memulai percakapan! {'\u{1F389}'}</p>
          {isMember && <button onClick={() => setShowPostForm(true)} className="mt-3 px-4 py-2 rounded-xl bg-primary/10 text-primary text-xs font-semibold">Tulis Post Pertama</button>}
        </div>
      ) : posts.map(p => {
        const cfg = typeConfig[p.type] || typeConfig.discussion;
        return (
          <div key={p.id} className={`bg-card rounded-2xl border p-4 ${p.pinned ? 'border-amber-500/30 bg-amber-500/5' : 'border-border'}`}>
            {p.pinned && <div className="flex items-center gap-1 text-[10px] text-amber-600 font-medium mb-2"><Pin className="w-3 h-3" /> Disematkan</div>}
            <div className="flex items-center gap-2 mb-2">
              <button onClick={() => navigate('/user/' + p.authorId)} className="shrink-0">
                {p.authorImage ? <img src={p.authorImage} className="w-8 h-8 rounded-full object-cover" alt="" /> : <div className="w-8 h-8 rounded-full bg-primary/15 flex items-center justify-center text-xs font-bold text-primary">{p.authorName[0]}</div>}
              </button>
              <div className="flex-1 min-w-0">
                <button onClick={() => navigate('/user/' + p.authorId)} className="text-sm font-semibold text-foreground truncate block hover:underline">{p.authorName}</button>
                <p className="text-[10px] text-muted-foreground">{p.createdAt ? formatDistanceToNow(new Date(p.createdAt), { locale: idLocale, addSuffix: true }) : ''}</p>
              </div>
              <span className={`flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-muted font-medium ${cfg.color}`}><cfg.icon className="w-3 h-3" /> {cfg.label}</span>
              {/* Admin/mod action menu */}
              <PostActionMenu postId={p.id} communityId={communityId} pinned={p.pinned} isKetua={isKetua} isMod={isMod} onRefresh={onRefresh} />
            </div>
            <h4 className="font-semibold text-sm text-foreground">{p.title}</h4>
            <PostContent content={p.content} navigate={navigate} />
            {p.media && p.media.length > 0 && (
              <div className="mt-2 flex gap-2 overflow-x-auto">{p.media.map((m, i) => <img key={i} src={m.url} className="h-32 rounded-xl object-cover" alt="" />)}</div>
            )}
            <div className="flex items-center gap-4 mt-3 pt-2 border-t border-border">
              <span className="flex items-center gap-1 text-xs text-muted-foreground"><Heart className="w-3.5 h-3.5" /> {p.likesCount}</span>
              <span className="flex items-center gap-1 text-xs text-muted-foreground"><MessageSquare className="w-3.5 h-3.5" /> {p.commentsCount}</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ─── Member action menu for Ketua/Mod ─── */
function MemberActionMenu({ memberId, memberRole, communityId, isKetua, isMod, onRefresh }: {
  memberId: string; memberRole: string; communityId: string; isKetua: boolean; isMod: boolean; onRefresh: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [acting, setActing] = useState(false);

  const isTargetKetua = memberRole === 'Ketua' || memberRole === 'ketua';
  const isTargetMod = memberRole === 'Moderator' || memberRole === 'moderator';
  const isTargetMember = !isTargetKetua && !isTargetMod;

  // Don't show menu on Ketua or if not admin
  if (isTargetKetua) return null;
  if (!isKetua && !isMod) return null;
  // Mod can only kick regular members
  if (isMod && !isKetua && isTargetMod) return null;

  const doAction = async (action: 'promote_mod' | 'demote' | 'kick') => {
    setActing(true);
    try {
      const r = await manageCommunityMember({ communityId, memberId, action });
      toast.success(r.message);
      onRefresh();
    } catch (e: any) { toast.error(e?.message || 'Gagal'); }
    setActing(false);
    setOpen(false);
  };

  return (
    <div className="relative">
      <button onClick={() => setOpen(!open)} className="p-1.5 rounded-full hover:bg-muted transition-colors" disabled={acting}>
        <MoreVertical className="w-4 h-4 text-muted-foreground" />
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-30" onClick={() => setOpen(false)} />
          <div className="absolute right-0 top-8 z-40 bg-card rounded-xl border border-border shadow-lg py-1 min-w-[180px]">
            {isKetua && isTargetMember && (
              <button onClick={() => doAction('promote_mod')} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-muted transition-colors text-foreground">
                <ChevronUp className="w-3.5 h-3.5 text-blue-500" /> Promosikan jadi Moderator
              </button>
            )}
            {isKetua && isTargetMod && (
              <button onClick={() => doAction('demote')} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-muted transition-colors text-foreground">
                <ChevronDown className="w-3.5 h-3.5 text-amber-500" /> Turunkan jadi Anggota
              </button>
            )}
            <button onClick={() => doAction('kick')} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-destructive/10 transition-colors text-destructive">
              <UserMinus className="w-3.5 h-3.5" /> Keluarkan dari Komunitas
            </button>
          </div>
        </>
      )}
    </div>
  );
}

function MembersTab({ members, isKetua, isMod, communityId, onRefresh }: {
  members: CommunityDetail['members']; isKetua: boolean; isMod: boolean; communityId: string; onRefresh: () => void;
}) {
  const navigate = useNavigate();
  const ro: Record<string, number> = { ketua: 0, Ketua: 0, moderator: 1, Moderator: 1, member: 2, Anggota: 2 };
  const sorted = [...members].sort((a, b) => (ro[a.role] ?? 2) - (ro[b.role] ?? 2));
  const rc: Record<string, { label: string; color: string; icon: typeof Crown }> = {
    ketua: { label: 'Ketua', color: 'text-amber-500', icon: Crown }, Ketua: { label: 'Ketua', color: 'text-amber-500', icon: Crown },
    moderator: { label: 'Moderator', color: 'text-blue-500', icon: Shield }, Moderator: { label: 'Moderator', color: 'text-blue-500', icon: Shield },
    member: { label: 'Anggota', color: 'text-muted-foreground', icon: Users }, Anggota: { label: 'Anggota', color: 'text-muted-foreground', icon: Users },
  };

  // Role count summary
  const ketuaCount = sorted.filter(m => m.role === 'Ketua' || m.role === 'ketua').length;
  const modCount = sorted.filter(m => m.role === 'Moderator' || m.role === 'moderator').length;
  const memberCount = sorted.length - ketuaCount - modCount;

  return (
    <div className="mt-4 space-y-2">
      {/* Role summary */}
      <div className="flex items-center gap-3 mb-2">
        <span className="flex items-center gap-1 text-[10px] text-amber-600 bg-amber-500/10 px-2 py-1 rounded-full"><Crown className="w-3 h-3" /> {ketuaCount} Ketua</span>
        <span className="flex items-center gap-1 text-[10px] text-blue-600 bg-blue-500/10 px-2 py-1 rounded-full"><Shield className="w-3 h-3" /> {modCount} Moderator</span>
        <span className="flex items-center gap-1 text-[10px] text-muted-foreground bg-muted px-2 py-1 rounded-full"><Users className="w-3 h-3" /> {memberCount} Anggota</span>
      </div>

      {(isKetua || isMod) && (
        <div className="flex items-center gap-1.5 p-2 rounded-lg bg-muted/50 mb-1">
          <AlertTriangle className="w-3 h-3 text-amber-500 shrink-0" />
          <p className="text-[10px] text-muted-foreground">
            {isKetua ? 'Sebagai Ketua, kamu bisa kelola role & anggota via menu ⋮' : 'Sebagai Moderator, kamu bisa mengeluarkan anggota biasa'}
          </p>
        </div>
      )}

      {sorted.map(m => { const cfg = rc[m.role] || rc.member; return (
        <div key={m.id} className="w-full flex items-center gap-3 bg-card rounded-xl border border-border p-3 hover:border-primary/20 transition-colors">
          <button onClick={() => navigate('/user/' + m.userId)} className="shrink-0">
            {m.image ? <img src={m.image} className="w-10 h-10 rounded-full object-cover" alt="" /> : <div className="w-10 h-10 rounded-full bg-primary/15 flex items-center justify-center text-sm font-bold text-primary">{m.name[0]}</div>}
          </button>
          <button onClick={() => navigate('/user/' + m.userId)} className="flex-1 min-w-0 text-left">
            <p className="text-sm font-semibold text-foreground truncate">{m.name}</p>
            <p className="text-[10px] text-muted-foreground">Bergabung {m.joinedAt ? formatDistanceToNow(new Date(m.joinedAt), { locale: idLocale, addSuffix: true }) : ''}</p>
          </button>
          <div className="text-right flex items-center gap-2">
            <div>
              <span className={`flex items-center gap-1 text-xs font-medium ${cfg.color}`}><cfg.icon className="w-3 h-3" /> {cfg.label}</span>
              {m.pointsEarned > 0 && <p className="text-[10px] text-muted-foreground mt-0.5">{m.pointsEarned} MP</p>}
            </div>
            <MemberActionMenu memberId={m.id} memberRole={m.role} communityId={communityId} isKetua={isKetua} isMod={isMod} onRefresh={onRefresh} />
          </div>
        </div>
      ); })}
    </div>
  );
}

function LeaderboardTab({ leaderboard }: { leaderboard: CommunityDetail['leaderboard'] }) {
  const navigate = useNavigate();
  const medals = ['\u{1F947}', '\u{1F948}', '\u{1F949}'];
