function SettingsTab({ community, onRefresh }: { community: CommunityDetail['community']; onRefresh: () => void }) {
  const [name, setName] = useState(community.name);
  const [desc, setDesc] = useState(community.description);
  const [rules, setRules] = useState(community.rules);
  const [joinMode, setJoinMode] = useState(community.joinMode);
  const [icon, setIcon] = useState(community.icon || '\u{1F3D8}\uFE0F');
  const [saving, setSaving] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleSave = async () => {
    setSaving(true);
    try { const r = await updateCommunitySettings({ communityId: community.id, name, description: desc, rules, joinMode: joinMode as any, icon }); toast.success(r.message); onRefresh(); } catch (e: any) { toast.error(e?.message || 'Gagal menyimpan'); }
    setSaving(false);
  };

  const shareLink = window.location.origin + '/community/' + community.id;
  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareLink).then(() => { setCopied(true); toast.success('Link komunitas disalin!'); setTimeout(() => setCopied(false), 2000); });
  };

  const ICONS = ['\u{1F3D8}\uFE0F', '\u{1F3E0}', '\u{1F306}', '\u{1F3D9}\uFE0F', '\u{1F333}', '\u{1F3AF}', '\u{1F504}', '\u{1F91D}', '\u{1F3A8}', '\u{1F4DA}', '\u{1F3AE}', '\u26BD', '\u{1F3CB}\uFE0F', '\u{1F3B8}', '\u{1F373}', '\u{1F6E0}\uFE0F', '\u{1F4BB}', '\u{1F30D}', '\u{1F4F1}', '\u{1F3B5}', '\u{1F697}', '\u{1F476}', '\u{1F457}', '\u{1F392}'];

  return (
