        </div>
        <div className="mb-3">
          <label className="text-xs font-medium text-muted-foreground mb-1 block">Deskripsi</label>
          <textarea value={desc} onChange={e => setDesc(e.target.value)} rows={3} className="w-full px-3 py-2.5 rounded-xl bg-muted text-sm resize-none focus:outline-none focus:ring-2 focus:ring-primary/30" />
        </div>
        <div className="mb-3">
          <label className="text-xs font-medium text-muted-foreground mb-1 block">{'\u{1F4CB}'} Aturan Komunitas</label>
          <textarea value={rules} onChange={e => setRules(e.target.value)} rows={5} placeholder={'Tuliskan aturan komunitas...\n1. Barang harus layak pakai\n2. Dilarang spam\n3. Barter dengan jujur'} className="w-full px-3 py-2.5 rounded-xl bg-muted text-sm resize-none focus:outline-none focus:ring-2 focus:ring-primary/30" />
        </div>
        <div className="mb-4">
          <label className="text-xs font-medium text-muted-foreground mb-1.5 block">Mode Bergabung</label>
          <div className="flex gap-2">
            <button onClick={() => setJoinMode('Terbuka')} className={`flex-1 py-2.5 rounded-xl text-xs font-medium transition-colors ${joinMode === 'Terbuka' || joinMode === 'open' ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{'\u{1F310}'} Terbuka</button>
            <button onClick={() => setJoinMode('Perlu Persetujuan')} className={`flex-1 py-2.5 rounded-xl text-xs font-medium transition-colors ${joinMode === 'Perlu Persetujuan' ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{'\u{1F512}'} Perlu Persetujuan</button>
          </div>
        </div>
        <button onClick={handleSave} disabled={saving} className="w-full py-3 rounded-xl bg-primary text-primary-foreground font-semibold text-sm disabled:opacity-50">
          {saving ? 'Menyimpan...' : '\u{1F4BE} Simpan Pengaturan'}
        </button>
      </div>
    </div>
  );
}

