import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getCommunities } from 'zitejs/api';
import { ArrowLeft, Plus, Search, Users, MapPin, Crown, ChevronRight, Sparkles, Globe, Lock, TrendingUp, Flame } from 'lucide-react';
import BottomNav from '../components/BottomNav';

type Community = {
  id: string;
  name: string;
  description: string;
  city: string;
  province: string;
  banner: { url: string }[] | null;
  icon: string | null;
  memberCount: number;
  barterCount: number;
  creatorName: string;
  creatorImage: string | null;
  isMember: boolean;
  isCreator: boolean;
  myRole: string | null;
  joinMode: string;
};

const CATEGORIES = [
  { key: 'semua', label: 'Semua', emoji: '\u{1F30D}' },
  { key: 'populer', label: 'Populer', emoji: '\u{1F525}' },
  { key: 'saya', label: 'Komunitasku', emoji: '\u2B50' },
];

export default function CommunityListPage() {
  const navigate = useNavigate();
  const [communities, setCommunities] = useState<Community[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [tab, setTab] = useState('semua');

  useEffect(() => { load(); }, []);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getCommunities({});
      setCommunities(res.communities as Community[]);
    } catch {}
    setLoading(false);
  };

  const myCommunities = communities.filter(c => c.isMember || c.isCreator);

  const filtered = communities.filter(c => {
    const matchSearch = !search || c.name.toLowerCase().includes(search.toLowerCase()) || c.city.toLowerCase().includes(search.toLowerCase());
    if (tab === 'saya') return matchSearch && (c.isMember || c.isCreator);
    return matchSearch;
  }).sort((a, b) => {
    if (tab === 'populer') return b.memberCount - a.memberCount;
    return 0;
  });

  return (
    <div className="min-h-screen bg-background lg:pl-[220px] xl:pl-[240px]">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-card/95 backdrop-blur-md border-b border-border">
        <div className="max-w-2xl mx-auto px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="p-1.5 rounded-full hover:bg-accent"><ArrowLeft className="w-5 h-5" /></button>
          <div className="flex-1">
            <h1 className="text-lg font-bold text-foreground">Komunitas</h1>
            <p className="text-xs text-muted-foreground">{communities.length} komunitas aktif</p>
          </div>
          <button onClick={() => navigate('/community/create')} className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-primary text-primary-foreground text-sm font-semibold">
            <Plus className="w-4 h-4" /> Buat
          </button>
        </div>
      </div>

      <div className="max-w-2xl mx-auto px-4 pb-24">
        {/* Search */}
        <div className="mt-4 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Cari komunitas atau kota..."
            className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-muted border-0 text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>

        {/* Category pills */}
        <div className="flex gap-2 mt-4 overflow-x-auto no-scrollbar">
          {CATEGORIES.map(cat => (
            <button
              key={cat.key}
              onClick={() => setTab(cat.key)}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-colors whitespace-nowrap flex items-center gap-1.5 ${tab === cat.key ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}
            >
              <span>{cat.emoji}</span> {cat.label}
              {cat.key === 'saya' && <span className="text-xs opacity-70">({myCommunities.length})</span>}
            </button>
          ))}
        </div>

        {/* Create CTA */}
        {tab !== 'saya' && (
          <button
            onClick={() => navigate('/community/create')}
            className="mt-4 w-full p-4 rounded-2xl bg-gradient-to-br from-primary/10 to-primary/5 border border-primary/20 flex items-center gap-3"
          >
            <div className="w-12 h-12 rounded-xl bg-primary/15 flex items-center justify-center">
              <Sparkles className="w-6 h-6 text-primary" />
            </div>
            <div className="flex-1 text-left">
              <p className="text-sm font-semibold text-foreground">Buat Komunitas Baru!</p>
              <p className="text-xs text-muted-foreground mt-0.5">Dapatkan badge Ketua, +50 MP & hak istimewa</p>
            </div>
            <ChevronRight className="w-5 h-5 text-primary" />
          </button>
        )}

        {/* Tips for making community popular */}
        {tab === 'semua' && !search && communities.length > 0 && (
          <div className="mt-3 p-3 rounded-xl bg-amber-500/5 border border-amber-500/15">
            <div className="flex items-center gap-1.5 mb-1.5">
              <Flame className="w-3.5 h-3.5 text-amber-500" />
              <p className="text-xs font-semibold text-amber-700 dark:text-amber-400">Tips Komunitas Ramai</p>
            </div>
            <ul className="text-[10px] text-muted-foreground space-y-0.5">
              <li>{'\u2022'} Bagikan barang upload-mu ke komunitas lewat tombol "Bagikan Barang"</li>
              <li>{'\u2022'} Ajak teman se-kota gabung & buat event barter lokal</li>
              <li>{'\u2022'} Aktif posting diskusi & share barang menarik</li>
            </ul>
          </div>
        )}

        {/* List */}
        {loading ? (
          <div className="flex flex-col gap-3 mt-4">
            {[1, 2, 3].map(i => (
              <div key={i} className="animate-pulse bg-card rounded-2xl p-4 border border-border">
                <div className="flex gap-3">
                  <div className="w-12 h-12 rounded-xl bg-muted" />
                  <div className="flex-1">
                    <div className="h-4 w-2/3 bg-muted rounded mb-2" />
                    <div className="h-3 w-1/3 bg-muted rounded mb-2" />
                    <div className="h-3 w-full bg-muted rounded" />
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <Users className="w-12 h-12 text-muted-foreground/40 mx-auto mb-3" />
            <p className="text-sm text-muted-foreground">{tab === 'saya' ? 'Kamu belum bergabung komunitas' : 'Belum ada komunitas'}</p>
            <button onClick={() => tab === 'saya' ? setTab('semua') : navigate('/community/create')} className="mt-3 text-sm text-primary font-semibold">
              {tab === 'saya' ? 'Lihat semua komunitas \u2192' : 'Buat komunitas pertama \u2192'}
            </button>
          </div>
        ) : (
          <div className="flex flex-col gap-3 mt-4">
            {filtered.map(c => (
              <CommunityCard key={c.id} community={c} onClick={() => navigate('/community/' + c.id)} />
            ))}
          </div>
        )}
      </div>
      <BottomNav />
    </div>
  );
}

function CommunityCard({ community: c, onClick }: { community: Community; onClick: () => void }) {
  return (
    <button onClick={onClick} className="w-full text-left bg-card rounded-2xl border border-border p-4 hover:border-primary/30 transition-colors">
      <div className="flex items-start gap-3">
        <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center text-2xl shrink-0">
          {c.icon || '\u{1F3D8}\uFE0F'}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-foreground truncate">{c.name}</h3>
            {c.isCreator && <Crown className="w-4 h-4 text-amber-500 shrink-0" />}
            {c.isMember && !c.isCreator && <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-primary/10 text-primary font-medium shrink-0">Anggota</span>}
          </div>
          <div className="flex items-center gap-2 mt-0.5">
            <span className="flex items-center gap-1 text-xs text-muted-foreground"><MapPin className="w-3 h-3" /> {c.city}, {c.province}</span>
            <span className="flex items-center gap-0.5 text-[10px] text-muted-foreground">
              {c.joinMode === 'open' || c.joinMode === 'Terbuka' ? <Globe className="w-2.5 h-2.5" /> : <Lock className="w-2.5 h-2.5" />}
            </span>
          </div>
          <p className="text-xs text-muted-foreground mt-1 line-clamp-2">{c.description}</p>
          <div className="flex items-center gap-4 mt-2">
            <span className="flex items-center gap-1 text-xs text-muted-foreground">
              <Users className="w-3 h-3" /> {c.memberCount} anggota
            </span>
            <span className="text-xs text-muted-foreground">{'\u{1F504}'} {c.barterCount} barter</span>
            {c.memberCount >= 5 && (
              <span className="flex items-center gap-0.5 text-[10px] text-amber-600 font-medium">
                <TrendingUp className="w-3 h-3" /> Aktif
              </span>
            )}
          </div>
        </div>
      </div>
    </button>
  );
}

