const ICON_CATEGORIES = [
  { label: 'Umum', icons: ['\u{1F3D8}\uFE0F', '\u{1F3D9}\uFE0F', '\u{1F306}', '\u{1F3E0}', '\u{1F333}', '\u{1F30D}', '\u{1F91D}', '\u{1F3AF}'] },
  { label: 'Hobi', icons: ['\u{1F3AE}', '\u{1F3B8}', '\u{1F3A8}', '\u{1F4DA}', '\u{1F3B5}', '\u{1F3AC}', '\u{1F4F7}', '\u{1F9E9}'] },
  { label: 'Kategori', icons: ['\u{1F4BB}', '\u{1F4F1}', '\u{1F457}', '\u{1F697}', '\u26BD', '\u{1F3CB}\uFE0F', '\u{1F476}', '\u{1F373}'] },
  { label: 'Lainnya', icons: ['\u{1F525}', '\u{1F48E}', '\u26A1', '\u{1F680}', '\u{1F31F}', '\u{1F504}', '\u{1F6E0}\uFE0F', '\u{1F392}'] },
];

const SUGGESTED_NAMES = [
  'Barter Elektronik', 'Tukar Fashion', 'Komunitas Barter Buku',
  'Swap Gaming & Hobi', 'Barter Otomotif', 'Peralatan Rumah Tangga',
];

export default function CreateCommunityPage() {
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [city, setCity] = useState('');
  const [province, setProvince] = useState('');
  const [icon, setIcon] = useState('\u{1F3D8}\uFE0F');
  const [rules, setRules] = useState('1. Barang harus layak pakai\n2. Dilarang spam\n3. Barter dengan jujur dan saling menghargai');
  const [joinMode, setJoinMode] = useState('open');
  const [loading, setLoading] = useState(false);

  const valid = name.length >= 3 && description.length >= 10 && city.length >= 2 && province.length >= 2;

  const handleSubmit = async () => {
    if (!valid || loading) return;
    setLoading(true);
    try {
      const res = await createCommunity({ name, description, city, province, icon, rules, joinMode });
      toast.success('Komunitas "' + res.community.name + '" berhasil dibuat! +' + res.pointsEarned + ' MP \u{1F389}');
      navigate('/community/' + res.community.id);
    } catch (e: any) {
      toast.error(e?.message || 'Gagal membuat komunitas');
