    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-background lg:pl-[220px] xl:pl-[240px]">
      <div className="sticky top-0 z-40 bg-card/95 backdrop-blur-md border-b border-border">
        <div className="max-w-2xl mx-auto px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="p-1.5 rounded-full hover:bg-accent"><ArrowLeft className="w-5 h-5" /></button>
          <h1 className="text-lg font-bold text-foreground">Buat Komunitas</h1>
        </div>
      </div>

      <div className="max-w-2xl mx-auto px-4 pb-24">
        {/* Benefits */}
        <div className="mt-4 p-4 rounded-2xl bg-gradient-to-br from-amber-500/10 to-primary/10 border border-amber-500/20">
          <div className="flex items-center gap-2 mb-3">
            <Crown className="w-5 h-5 text-amber-500" />
            <h3 className="font-semibold text-sm text-foreground">Keuntungan Ketua Komunitas</h3>
          </div>
          <div className="grid grid-cols-2 gap-2">
            {[
              { icon: Gift, text: '+50 MP langsung', color: 'text-emerald-600' },
              { icon: Crown, text: 'Badge Ketua', color: 'text-amber-600' },
              { icon: Users, text: '+10 MP/anggota baru', color: 'text-blue-600' },
              { icon: Megaphone, text: 'Bisa buat pengumuman', color: 'text-red-500' },
              { icon: Flame, text: 'Posting +2 MP, event +3 MP', color: 'text-orange-500' },
              { icon: BarChart3, text: 'Bonus +3 MP barter selesai', color: 'text-purple-500' },
            ].map((b, i) => (
              <div key={i} className="flex items-center gap-2 text-xs text-muted-foreground">
                <b.icon className={`w-3.5 h-3.5 ${b.color} shrink-0`} />
                <span>{b.text}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Tips */}
        <div className="mt-3 p-3 rounded-xl bg-blue-500/5 border border-blue-500/15">
          <p className="text-xs font-semibold text-blue-700 dark:text-blue-400 mb-1">{'\u{1F4A1}'} Tips agar komunitas ramai:</p>
          <ul className="text-[10px] text-muted-foreground space-y-0.5">
            <li>{'\u2022'} Pilih nama spesifik yang jelas, misal "Barter Elektronik Bandung"</li>
            <li>{'\u2022'} Bagikan link komunitas ke teman dan grup chat</li>
            <li>{'\u2022'} Aktif posting barang dan buat diskusi menarik</li>
            <li>{'\u2022'} Buat event barter untuk mengundang anggota baru</li>
          </ul>
        </div>

        {/* Form */}
        <div className="mt-6 space-y-5">
          {/* Icon picker */}
          <div>
            <label className="block text-sm font-medium text-foreground mb-2">Ikon Komunitas</label>
            {ICON_CATEGORIES.map(cat => (
              <div key={cat.label} className="mb-2">
                <p className="text-[10px] text-muted-foreground mb-1">{cat.label}</p>
                <div className="flex flex-wrap gap-2">
                  {cat.icons.map(i => (
                    <button
                      key={i}
                      onClick={() => setIcon(i)}
                      className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl transition-all ${icon === i ? 'bg-primary/15 ring-2 ring-primary scale-110' : 'bg-muted hover:bg-accent'}`}
                    >
                      {i}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          {/* Name with suggestions */}
          <div>
            <label className="block text-sm font-medium text-foreground mb-1.5">Nama Komunitas</label>
            <input value={name} onChange={e => setName(e.target.value)} placeholder="Contoh: Barter Elektronik Bandung" maxLength={60} className="w-full px-4 py-2.5 rounded-xl bg-muted text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30" />
            {name.length < 3 && (
              <div className="flex flex-wrap gap-1.5 mt-2">
                {SUGGESTED_NAMES.map(s => (
                  <button key={s} onClick={() => setName(s)} className="px-2.5 py-1 rounded-full bg-muted text-[10px] text-muted-foreground hover:bg-accent transition-colors">
                    {s}
                  </button>
                ))}
              </div>
            )}
            {name.length > 0 && <p className="text-[10px] text-muted-foreground text-right mt-0.5">{name.length}/60</p>}
