          <Field label="Deskripsi" value={description} onChange={setDescription} placeholder="Ceritakan tentang komunitas ini — apa yang bisa anggota lakukan di sini?" multiline maxLength={500} />
          <Field label="Kota/Kabupaten" value={city} onChange={setCity} placeholder="Contoh: Bandung" />

          <div>
