                  <p className="text-sm font-medium">{m.l}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">{m.d}</p>
                </button>
              ))}
            </div>
          </div>

          <Field label="Aturan Komunitas" value={rules} onChange={setRules} placeholder="Aturan untuk anggota..." multiline />
        </div>

        <button
          onClick={handleSubmit}
          disabled={!valid || loading}
          className="mt-6 w-full py-3.5 rounded-xl bg-primary text-primary-foreground font-bold text-sm disabled:opacity-40 transition-opacity flex items-center justify-center gap-2"
        >
          {loading ? <div className="w-4 h-4 border-2 border-primary-foreground border-t-transparent rounded-full animate-spin" /> : <Sparkles className="w-4 h-4" />}
          {loading ? 'Membuat...' : 'Buat Komunitas (+50 MP)'}
        </button>
      </div>
      <BottomNav />
    </div>
  );
}

function Field({ label, value, onChange, placeholder, multiline, maxLength }: {
  label: string; value: string; onChange: (v: string) => void; placeholder: string; multiline?: boolean; maxLength?: number;
}) {
  const cls = "w-full px-4 py-2.5 rounded-xl bg-muted text-sm placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/30";
  return (
    <div>
      <label className="block text-sm font-medium text-foreground mb-1.5">{label}</label>
      {multiline ? (
        <textarea value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} maxLength={maxLength} rows={3} className={cls + ' resize-none'} />
      ) : (
        <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} maxLength={maxLength} className={cls} />
      )}
      {maxLength && <p className="text-[10px] text-muted-foreground text-right mt-0.5">{value.length}/{maxLength}</p>}
    </div>
  );
}

