import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Camera, MapPin, Send, Sparkles } from 'lucide-react';
import { toast } from 'sonner';
import { useUpload } from 'zitejs/upload';
import { createStory } from 'zitejs/api';
import { useLocation as useLocationCtx } from '../context/LocationContext';
import { MutariInline } from '../components/MutariSpinner';

const STORY_TYPES = [
  { value: 'barter_baru', label: '🆕 Barter Baru', color: 'bg-emerald-500/15 text-emerald-600 border-emerald-500/30' },
  { value: 'dicari', label: '🔍 Dicari', color: 'bg-orange-500/15 text-orange-600 border-orange-500/30' },
  { value: 'promo', label: '🏷️ Promo', color: 'bg-blue-500/15 text-blue-600 border-blue-500/30' },
  { value: 'showcase', label: '✨ Showcase', color: 'bg-purple-500/15 text-purple-600 border-purple-500/30' },
];

export default function CreateStoryPage() {
  const navigate = useNavigate();
  const { upload, isUploading } = useUpload();
  const { location: locData } = useLocationCtx();
  const locationLabel = locData ? `${locData.kecamatan}, ${locData.kabupaten}` : null;

  const [mediaUrl, setMediaUrl] = useState<string | null>(null);
  const [caption, setCaption] = useState('');
  const [type, setType] = useState('showcase');
  const [posting, setPosting] = useState(false);

  const handlePhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const { url } = await upload(file);
      setMediaUrl(url);
    } catch {
      toast.error('Gagal upload foto');
    }
  };

  const handlePost = async () => {
    if (!mediaUrl) {
      toast.error('Pilih foto dulu ya');
      return;
    }
    setPosting(true);
    try {
      await createStory({
        caption,
        mediaUrl,
        type: type as any,
        location: locationLabel || undefined,
      });
      toast.success('Story berhasil diposting! 🎉');
      navigate('/', { replace: true });
    } catch {
      toast.error('Gagal posting story');
    }
    setPosting(false);
  };

  return (
    <div className="min-h-screen bg-black text-white mutari-main flex flex-col">
      <div className="max-w-[420px] mx-auto w-full flex-1 flex flex-col">
        {/* Header */}
        <div className="px-4 py-3 flex items-center justify-between">
          <button onClick={() => navigate(-1)} className="p-1">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <h1 className="font-bold text-sm">Buat Story</h1>
          <div className="w-7" />
        </div>

        {/* Photo area */}
        <div className="flex-1 flex items-center justify-center px-4 py-4">
          {mediaUrl ? (
            <div className="relative w-full max-w-[360px] aspect-[9/16] rounded-3xl overflow-hidden">
              <img src={mediaUrl} alt="" className="w-full h-full object-cover" />
              {/* Re-pick */}
              <label className="absolute top-3 right-3 w-10 h-10 rounded-full bg-black/50 backdrop-blur flex items-center justify-center cursor-pointer">
                <Camera className="w-5 h-5" />
                <input type="file" accept="image/*" className="sr-only" onChange={handlePhoto} disabled={isUploading} />
              </label>
              {/* Caption overlay */}
              <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/80 to-transparent p-4 pt-12">
                {locationLabel && (
                  <div className="flex items-center gap-1 text-white/70 text-[10px] mb-2">
                    <MapPin className="w-3 h-3" /> {locationLabel}
                  </div>
                )}
                <input
                  value={caption}
                  onChange={e => setCaption(e.target.value)}
                  placeholder="Tulis caption..."
                  maxLength={200}
                  className="w-full bg-transparent border-b border-white/20 text-sm py-1.5 placeholder:text-white/40 focus:outline-none focus:border-white/50"
                />
                <p className="text-[9px] text-white/40 text-right mt-0.5">{caption.length}/200</p>
              </div>
            </div>
          ) : (
            <label className="w-full max-w-[360px] aspect-[9/16] rounded-3xl border-2 border-dashed border-white/20 flex flex-col items-center justify-center gap-3 cursor-pointer hover:border-white/40 transition-colors">
              {isUploading ? (
                <MutariInline size={32} />
              ) : (
                <>
                  <div className="w-16 h-16 rounded-2xl bg-white/10 flex items-center justify-center">
                    <Camera className="w-8 h-8 text-white/60" />
                  </div>
                  <p className="text-sm text-white/60">Tap untuk pilih foto</p>
                  <p className="text-[10px] text-white/30">Story hilang dalam 24 jam</p>
                </>
              )}
              <input type="file" accept="image/*" className="sr-only" onChange={handlePhoto} disabled={isUploading} />
            </label>
          )}
        </div>

        {/* Type selector */}
        <div className="px-4 pb-3">
          <p className="text-[10px] text-white/40 mb-2 font-semibold uppercase tracking-wide">Tipe Story</p>
          <div className="flex gap-2 overflow-x-auto scrollbar-hide">
            {STORY_TYPES.map(t => (
              <button
                key={t.value}
                onClick={() => setType(t.value)}
                className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-semibold border transition-all ${
                  type === t.value ? t.color : 'bg-white/5 text-white/40 border-white/10'
                }`}
              >
                {t.label}
              </button>
            ))}
          </div>
        </div>

        {/* Post button */}
        <div className="px-4 pb-6">
          <button
            onClick={handlePost}
            disabled={!mediaUrl || posting}
            className="w-full py-3.5 rounded-2xl bg-primary text-primary-foreground font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-40 transition-opacity"
          >
            {posting ? <MutariInline size={16} /> : <Sparkles className="w-4 h-4" />}
            {posting ? 'Memposting...' : 'Posting Story'}
          </button>
        </div>
      </div>
    </div>
  );
}

