import { MutariInline } from '../components/MutariSpinner';
import { useState, useEffect, useRef, useCallback } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Send, Plus, Camera, ImageIcon, X, Circle, Package } from 'lucide-react';
import { Skeleton } from '@project/components/ui/skeleton';
import { getDirectMessages, sendDirectMessage, updatePresence } from 'zitejs/api';
import type { GetDirectMessagesOutputType } from 'zitejs/api';
import { useAuth } from 'zitejs/auth';
import { useUpload } from 'zitejs/upload';
import { formatDistanceToNow } from 'date-fns';
import { id as localeId } from 'date-fns/locale';

type Msg = GetDirectMessagesOutputType['messages'][0];
type OtherUser = GetDirectMessagesOutputType['otherUser'];
type ItemInfo = GetDirectMessagesOutputType['item'];

export default function DirectChatPage() {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const otherUserId = params.get('userId') || '';
  const itemId = params.get('itemId') || '';
  const itemTitle = params.get('itemTitle') || 'Barang';

  const [messages, setMessages] = useState<Msg[]>([]);
  const [otherUser, setOtherUser] = useState<OtherUser | null>(null);
  const [itemInfo, setItemInfo] = useState<ItemInfo>(null);
  const [conversationId, setConversationId] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false); // only for photo upload
  const [otherTyping, setOtherTyping] = useState(false);
  const [text, setText] = useState('');
  const chatEndRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const typingTimer = useRef<ReturnType<typeof setTimeout>>();
  const prevMsgCount = useRef(0);
  const shouldAutoScroll = useRef(true);

  const isNearBottom = () => {
    const el = scrollContainerRef.current;
    if (!el) return true;
    return el.scrollHeight - el.scrollTop - el.clientHeight < 120;
  };

  const loadMessages = useCallback(async () => {
    if (!otherUserId || !itemId) return;
    try {
      const res = await getDirectMessages({ otherUserId, itemId });
      setMessages(res.messages);
      setOtherUser(res.otherUser);
      setItemInfo(res.item);
      setConversationId(res.conversationId);
    } catch { /* */ }
    setLoading(false);
  }, [otherUserId, itemId]);

  useEffect(() => { loadMessages(); }, [loadMessages]);

  // Poll messages & presence every 3s
  useEffect(() => {
    if (!otherUserId || !itemId) return;
    const iv = setInterval(async () => {
      try {
        const [res, presRes] = await Promise.all([
          getDirectMessages({ otherUserId, itemId }),
          conversationId ? updatePresence({ conversationId, isTyping: false }) : null,
        ]);
        setMessages(res.messages);
        setOtherUser(res.otherUser);
        setItemInfo(res.item);
        if (presRes) {
          setOtherTyping(presRes.otherTyping);
        }
      } catch { /* */ }
    }, 3000);
    return () => clearInterval(iv);
  }, [otherUserId, itemId, conversationId]);

  useEffect(() => {
    if (shouldAutoScroll.current || messages.length !== prevMsgCount.current) {
      if (shouldAutoScroll.current || isNearBottom()) {
        chatEndRef.current?.scrollIntoView({ behavior: prevMsgCount.current === 0 ? 'instant' : 'smooth' });
      }
    }
    prevMsgCount.current = messages.length;
    shouldAutoScroll.current = false;
  }, [messages]);

  const handleTyping = (val: string) => {
    setText(val);
    if (conversationId) {
      updatePresence({ conversationId, isTyping: true }).catch(() => {});
      clearTimeout(typingTimer.current);
      typingTimer.current = setTimeout(() => {
        updatePresence({ conversationId, isTyping: false }).catch(() => {});
      }, 2000);
    }
  };

  const handleSend = async () => {
    if (!text.trim() || sending) return;
    const content = text.trim();
    setText('');
    shouldAutoScroll.current = true;

    // Optimistic: show message immediately
    const tempId = `temp-${Date.now()}`;
    const optimisticMsg: Msg = {
      id: tempId,
      senderId: user?.id || '',
      content,
      type: 'Text',
      sentAt: new Date().toISOString(),
    };
    setMessages(prev => [...prev, optimisticMsg]);

    try {
      await sendDirectMessage({ receiverId: otherUserId, itemId, content, type: 'Text' });
      // Background refresh to get real ID & sync
      getDirectMessages({ otherUserId, itemId }).then(res => {
        setMessages(res.messages);
        setOtherUser(res.otherUser);
        setItemInfo(res.item);
      }).catch(() => {});
    } catch {
      // Remove optimistic message on failure
      setMessages(prev => prev.filter(m => m.id !== tempId));
    }
  };

  if (loading) return <ChatSkeleton />;

  return (
    <div className="h-[100dvh] bg-background flex flex-col">
      <div className="max-w-[420px] mx-auto w-full flex flex-col flex-1 min-h-0">
        {/* Header */}
        <ChatHeader
          otherUser={otherUser}
          itemTitle={itemTitle}
          onBack={() => navigate(-1)}
        />

        {/* Item context bar with product image */}
        <div
          className="px-4 py-2.5 bg-accent/30 border-b border-primary/10 flex items-center gap-3 cursor-pointer active:bg-accent/50 transition"
          onClick={() => navigate(`/item/${itemId}`)}
        >
          {itemInfo?.image ? (
            <img src={itemInfo.image} alt="" className="w-11 h-11 rounded-lg object-cover flex-shrink-0 border border-border" />
          ) : (
            <div className="w-11 h-11 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0 border border-border">
              <Package className="w-5 h-5 text-primary" />
            </div>
          )}
          <div className="flex-1 min-w-0">
            <p className="text-xs font-semibold text-foreground truncate">{itemInfo?.title || itemTitle}</p>
            {itemInfo?.condition && (
              <p className="text-[10px] text-muted-foreground">Kondisi: {itemInfo.condition}</p>
            )}
          </div>
          <ArrowLeft className="w-4 h-4 text-muted-foreground rotate-180 flex-shrink-0" />
        </div>

        {/* Messages */}
        <div ref={scrollContainerRef} className="flex-1 overflow-y-auto px-4 py-3 space-y-2 overscroll-contain">
          {messages.length === 0 && (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center mb-3">
                <Send className="w-6 h-6 text-primary" />
              </div>
              <p className="text-sm font-medium text-foreground">Mulai percakapan</p>
              <p className="text-xs text-muted-foreground mt-1">Tanyakan tentang barang atau langsung nego</p>
            </div>
          )}
          {messages.map(msg => {
            const isMe = msg.senderId === user?.id;
            return (
              <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[75%] px-3 py-2 rounded-2xl ${
                  isMe
                    ? 'bg-primary text-primary-foreground rounded-br-md'
                    : 'bg-card border border-border rounded-bl-md'
                }`}>
                  {msg.type === 'Photo' ? (
                    <img src={msg.content} alt="Foto" className="rounded-lg max-w-full max-h-48 object-cover cursor-pointer" onClick={() => window.open(msg.content, '_blank')} />
                  ) : (
                    <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                  )}
                  <p className={`text-[10px] mt-1 ${isMe ? 'text-primary-foreground/60' : 'text-muted-foreground'}`}>
                    {msg.sentAt ? new Date(msg.sentAt).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : ''}
                  </p>
                </div>
              </div>
            );
          })}

          {/* Typing indicator */}
          {otherTyping && (
            <div className="flex justify-start">
              <div className="bg-card border border-border rounded-2xl rounded-bl-md px-4 py-2.5">
                <div className="flex items-center gap-1.5">
                  <div className="flex gap-0.5">
                    <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:0ms]" />
                    <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:150ms]" />
                    <span className="w-1.5 h-1.5 rounded-full bg-muted-foreground/50 animate-bounce [animation-delay:300ms]" />
                  </div>
                  <span className="text-[11px] text-muted-foreground italic">Mengetik...</span>
                </div>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        {/* Quick replies for empty chat */}
        {messages.length === 0 && <QuickReplies onSelect={(q) => { setText(q); }} />}

        {/* Input */}
        <ChatInputBar
          text={text}
          onTextChange={handleTyping}
          onSend={handleSend}
          onSendPhoto={async (url) => {
            shouldAutoScroll.current = true;
            // Optimistic photo
            const tempId = `temp-photo-${Date.now()}`;
            const optimisticMsg: Msg = {
              id: tempId,
              senderId: user?.id || '',
              content: url,
              type: 'Photo',
              sentAt: new Date().toISOString(),
            };
            setMessages(prev => [...prev, optimisticMsg]);
            try {
              await sendDirectMessage({ receiverId: otherUserId, itemId, content: url, type: 'Photo' });
              getDirectMessages({ otherUserId, itemId }).then(res => {
                setMessages(res.messages);
              }).catch(() => {});
            } catch {
              setMessages(prev => prev.filter(m => m.id !== tempId));
            }
          }}
          sending={sending}
        />
      </div>
    </div>
  );
}

function ChatHeader({ otherUser, itemTitle, onBack }: { otherUser: OtherUser | null; itemTitle: string; onBack: () => void }) {
  const lastSeenText = otherUser?.lastSeen
    ? formatDistanceToNow(new Date(otherUser.lastSeen), { addSuffix: true, locale: localeId })
    : null;

  return (
    <div className="flex-shrink-0 z-30 bg-card/95 backdrop-blur-md border-b border-border">
      <div className="flex items-center gap-3 px-4 py-3">
        <button onClick={onBack} className="p-1.5 rounded-xl hover:bg-muted transition active:scale-95">
          <ArrowLeft className="w-5 h-5" />
        </button>
        {/* Avatar */}
        <div className="relative flex-shrink-0">
          <div className="w-10 h-10 rounded-full overflow-hidden bg-muted">
            {otherUser?.image ? (
              <img src={otherUser.image} alt="" className="w-full h-full object-cover" />
            ) : (
              <div className="w-full h-full bg-primary/10 flex items-center justify-center text-primary font-bold text-sm">
                {otherUser?.name?.[0]?.toUpperCase() || 'P'}
              </div>
            )}
          </div>
          {/* Online dot */}
          {otherUser?.isOnline && (
            <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full bg-green-500 border-2 border-card" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <h1 className="font-bold text-sm truncate">{otherUser?.name || 'Pengguna'}</h1>
          <div className="flex items-center gap-1.5">
            {otherUser?.isOnline ? (
              <>
                <Circle className="w-2 h-2 fill-green-500 text-green-500" />
                <span className="text-[11px] text-green-600 dark:text-green-400 font-medium">Online</span>
              </>
            ) : (
              <span className="text-[11px] text-muted-foreground">
                {lastSeenText ? `Terakhir online ${lastSeenText}` : 'Offline'}
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function QuickReplies({ onSelect }: { onSelect: (q: string) => void }) {
  const quickies = [
    'Apakah barang masih tersedia?',
    'Bisa tukar tambah?',
    'Kondisi barangnya bagaimana?',
    'Bisa COD di mana?',
    'Saya tertarik, yuk deal!',
  ];
  return (
    <div className="px-4 py-2 flex gap-1.5 overflow-x-auto no-scrollbar">
      {quickies.map(q => (
        <button
          key={q}
          onClick={() => onSelect(q)}
          className="flex-shrink-0 px-3 py-1.5 rounded-full bg-accent border border-primary/15 text-primary text-xs font-medium active:scale-95 transition whitespace-nowrap"
        >
          {q}
        </button>
      ))}
    </div>
  );
}

function ChatInputBar({ text, onTextChange, onSend, onSendPhoto, sending }: {
  text: string;
  onTextChange: (v: string) => void;
  onSend: () => void;
  onSendPhoto: (url: string) => void;
  sending: boolean;
}) {
  const [showAttach, setShowAttach] = useState(false);
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const cameraRef = useRef<HTMLInputElement>(null);
  const { upload } = useUpload();
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFocus = () => {
    // On mobile, delay to let keyboard fully open, then scroll input into view
    setTimeout(() => {
      inputRef.current?.scrollIntoView({ block: 'end', behavior: 'smooth' });
    }, 300);
  };

  const handleFileSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setShowAttach(false);
    setUploading(true);
    try {
      const { url } = await upload(file);
      onSendPhoto(url);
    } catch { /* */ }
    setUploading(false);
    e.target.value = '';
  };

  return (
    <div className="bg-card/95 backdrop-blur-md border-t border-border pb-[env(safe-area-inset-bottom)]">
      {showAttach && (
        <div className="px-4 py-2 flex gap-2">
          <button onClick={() => cameraRef.current?.click()} className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-accent border border-primary/15 text-sm font-medium active:scale-95 transition">
            <Camera className="w-4 h-4 text-primary" /> Kamera
          </button>
          <button onClick={() => fileRef.current?.click()} className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-accent border border-primary/15 text-sm font-medium active:scale-95 transition">
            <ImageIcon className="w-4 h-4 text-primary" /> Galeri
          </button>
        </div>
      )}
      <div className="flex items-center gap-2 px-4 py-2.5">
        <button
          onClick={() => setShowAttach(prev => !prev)}
          className={`p-2 rounded-full transition active:scale-90 ${showAttach ? 'bg-primary text-primary-foreground' : 'bg-muted text-foreground'}`}
        >
          {uploading ? <MutariInline size={16} /> : showAttach ? <X className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
        </button>
        <input
          ref={inputRef}
          type="text"
          value={text}
          onChange={e => onTextChange(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && onSend()}
          onFocus={handleFocus}
          placeholder="Tulis pesan..."
          className="flex-1 bg-muted rounded-full px-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
          enterKeyHint="send"
          autoComplete="off"
        />
        <button
          onClick={onSend}
          disabled={!text.trim() || sending}
          className="p-2 rounded-full bg-primary text-primary-foreground disabled:opacity-40 active:scale-90 transition"
        >
          <Send className="w-4 h-4" />
        </button>
      </div>
      <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleFileSelected} />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={handleFileSelected} />
    </div>
  );
}

function ChatSkeleton() {
  return (
    <div className="min-h-screen bg-background mutari-main">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-30 bg-card/95 backdrop-blur-md border-b border-border px-4 py-3 flex items-center gap-3">
          <Skeleton className="w-8 h-8 rounded-xl" />
          <Skeleton className="w-10 h-10 rounded-full" />
