import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Camera, ImagePlus, Store, Sparkles, X, Package } from 'lucide-react';
import { toast } from 'sonner';
import { useAuth } from 'zitejs/auth';
import { useUpload } from 'zitejs/upload';
import { getStorefront, updateProfile, getMyItems, GetMyItemsOutputType } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Skeleton } from '@project/components/ui/skeleton';
import { MutariInline } from '../components/MutariSpinner';

type MyItem = GetMyItemsOutputType['items'][0];

export default function EditStorefrontPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { upload, isUploading } = useUpload();

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [storeName, setStoreName] = useState('');
  const [storeTagline, setStoreTagline] = useState('');
  const [storeBanner, setStoreBanner] = useState('');
  const [bio, setBio] = useState('');
  const [featuredIds, setFeaturedIds] = useState<string[]>([]);
  const [myItems, setMyItems] = useState<MyItem[]>([]);

  useEffect(() => {
    if (!user) return;
    Promise.all([
      getStorefront({ userId: user.id }),
      getMyItems({}),
    ]).then(([sf, items]) => {
      setStoreName(sf.storeName || '');
      setStoreTagline(sf.storeTagline || '');
      setStoreBanner(sf.storeBanner || '');
      setBio(sf.bio || '');
      const fIds = sf.featuredItems.map(i => i.id);
      setFeaturedIds(fIds);
      setMyItems(items.items);
    }).catch(() => toast.error('Gagal memuat data'))
      .finally(() => setLoading(false));
  }, [user]);

  const handleBannerUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const { url } = await upload(file);
      setStoreBanner(url);
      toast.success('Banner diupload!');
    } catch {
      toast.error('Gagal upload banner');
    }
  };

  const toggleFeatured = (itemId: string) => {
    setFeaturedIds(prev =>
      prev.includes(itemId)
        ? prev.filter(id => id !== itemId)
        : prev.length >= 6
          ? (toast.error('Maksimal 6 barang unggulan'), prev)
          : [...prev, itemId]
    );
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile({
        storeName: storeName || undefined,
        storeTagline: storeTagline || undefined,
        storeBanner: storeBanner || undefined,
        bio,
        featuredItems: featuredIds.join(','),
      });
      toast.success('Storefront berhasil diperbarui!');
      navigate(-1);
    } catch {
      toast.error('Gagal menyimpan');
    }
    setSaving(false);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background mutari-main max-w-[420px] mx-auto p-4">
        <Skeleton className="h-8 w-40 rounded mb-6" />
        <Skeleton className="h-40 w-full rounded-2xl mb-4" />
        <Skeleton className="h-10 w-full rounded-xl mb-3" />
        <Skeleton className="h-10 w-full rounded-xl mb-3" />
        <Skeleton className="h-24 w-full rounded-xl" />
      </div>
    );
  }

  const availableItems = myItems.filter(i => i.status === 'Tersedia');

  return (
    <div className="min-h-screen bg-background pb-8">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background/95 backdrop-blur-sm border-b border-border px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center">
            <ArrowLeft className="w-4 h-4" />
          </button>
          <div className="flex-1">
            <h1 className="font-bold text-base">Edit Storefront</h1>
            <p className="text-[10px] text-muted-foreground">Atur tampilan toko personal kamu</p>
          </div>
          <Button onClick={handleSave} disabled={saving} size="sm" className="gap-1.5">
            {saving ? <MutariInline size={14} /> : <Store className="w-3.5 h-3.5" />}
            Simpan
          </Button>
        </div>

        {/* Banner */}
        <div className="px-4 mt-4">
          <label className="text-xs font-semibold text-muted-foreground mb-2 block">Banner Toko</label>
          <div className="relative w-full h-40 rounded-2xl overflow-hidden bg-muted border-2 border-dashed border-border">
            {storeBanner ? (
              <>
                <img src={storeBanner} alt="" className="w-full h-full object-cover" />
                <button
                  onClick={() => setStoreBanner('')}
                  className="absolute top-2 right-2 w-7 h-7 rounded-full bg-black/50 flex items-center justify-center"
                >
                  <X className="w-3.5 h-3.5 text-white" />
                </button>
              </>
            ) : (
              <label className="w-full h-full flex flex-col items-center justify-center gap-2 cursor-pointer">
                <ImagePlus className="w-8 h-8 text-muted-foreground" />
                <span className="text-xs text-muted-foreground">Upload banner (rasio 16:9)</span>
                <input type="file" accept="image/*" onChange={handleBannerUpload} className="hidden" />
              </label>
            )}
            {isUploading && (
              <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                <MutariInline size={24} />
              </div>
            )}
          </div>
        </div>

        {/* Store Info */}
        <div className="px-4 mt-5 space-y-4">
          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Tagline</label>
            <Input
              value={storeTagline}
              onChange={e => setStoreTagline(e.target.value)}
              placeholder="Contoh: Barter barang berkualitas di Jakarta"
              maxLength={80}
            />
            <p className="text-[10px] text-muted-foreground mt-1">{storeTagline.length}/80 karakter</p>
          </div>
          <div>
            <label className="text-xs font-semibold text-muted-foreground mb-1.5 block">Bio</label>
            <textarea
              value={bio}
              onChange={e => setBio(e.target.value)}
              placeholder="Ceritakan tentang kamu dan barang-barang yang kamu tawarkan..."
              maxLength={300}
              className="w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm resize-none h-24 focus:outline-none focus:ring-2 focus:ring-primary/20"
            />
            <p className="text-[10px] text-muted-foreground mt-1">{bio.length}/300 karakter</p>
          </div>
        </div>

        {/* Featured Items Picker */}
        <div className="px-4 mt-6">
          <div className="flex items-center gap-2 mb-3">
            <Sparkles className="w-4 h-4 text-amber-500" />
            <h3 className="font-bold text-sm">Barang Unggulan</h3>
            <span className="text-[10px] text-muted-foreground ml-auto">{featuredIds.length}/6 dipilih</span>
          </div>
          <p className="text-xs text-muted-foreground mb-3">Pilih hingga 6 barang untuk ditampilkan sebagai unggulan di tokomu</p>

          {availableItems.length > 0 ? (
            <div className="grid grid-cols-3 gap-2">
              {availableItems.map(item => {
                const isFeatured = featuredIds.includes(item.id);
                return (
                  <button
                    key={item.id}
                    onClick={() => toggleFeatured(item.id)}
                    className={`relative rounded-xl overflow-hidden border-2 transition-all ${
                      isFeatured ? 'border-amber-400 shadow-md shadow-amber-400/20' : 'border-border'
                    }`}
                  >
                    {item.photo ? (
                      <img src={item.photo} alt={item.title} className="w-full aspect-square object-cover" />
                    ) : (
                      <div className="w-full aspect-square bg-muted flex items-center justify-center">
                        <Package className="w-6 h-6 text-muted-foreground" />
                      </div>
                    )}
                    {isFeatured && (
                      <div className="absolute inset-0 bg-amber-400/20 flex items-center justify-center">
                        <div className="w-7 h-7 rounded-full bg-amber-400 flex items-center justify-center shadow">
                          <Sparkles className="w-4 h-4 text-amber-900" />
                        </div>
                      </div>
                    )}
                    <p className="text-[9px] font-medium truncate px-1.5 py-1">{item.title}</p>
                  </button>
                );
              })}
            </div>
          ) : (
            <div className="bg-card border border-border rounded-xl p-6 text-center">
              <Package className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
              <p className="text-xs text-muted-foreground">Belum ada barang tersedia untuk dijadikan unggulan</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

