import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Lock, Unlock, ChevronRight, Sparkles, Crown, Shield, GraduationCap, Gem, Star } from 'lucide-react';
import { motion } from 'framer-motion';
import { useUserPoints } from '../hooks/useUserPoints';
import { FEATURE_TIERS, type FeatureTier } from '../lib/featureUnlock';
import { Skeleton } from '@project/components/ui/skeleton';
import BottomNav from '../components/BottomNav';

const TIER_ICONS: Record<string, React.ElementType> = {
  tier_500: Star,
  tier_1000: Shield,
  tier_2500: Crown,
  tier_5000: GraduationCap,
  tier_10000: Gem,
};

function TierCard({ tier, userPoints, index }: { tier: FeatureTier; userPoints: number; index: number }) {
  const navigate = useNavigate();
  const unlocked = userPoints >= tier.minPoints;
  const Icon = TIER_ICONS[tier.id] || Sparkles;
  const progress = unlocked ? 100 : Math.min(99, Math.round((userPoints / tier.minPoints) * 100));

  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.08, duration: 0.4 }}
      className="relative"
    >
      {/* Connector line */}
      {index > 0 && (
        <div className="absolute -top-6 left-6 w-0.5 h-6 bg-gradient-to-b from-border to-transparent" />
      )}

      <div className={`rounded-2xl border overflow-hidden transition-all ${
        unlocked
          ? `${tier.borderColor} bg-card shadow-lg`
          : 'border-border/50 bg-muted/30'
      }`}>
        {/* Header */}
        <div className={`px-4 py-3 flex items-center gap-3 ${
          unlocked
            ? `bg-gradient-to-r ${tier.gradient} text-white`
            : 'bg-muted/50'
        }`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
            unlocked ? 'bg-white/20 backdrop-blur-sm' : 'bg-background border border-border'
          }`}>
            {unlocked ? (
              <span className="text-xl">{tier.emoji}</span>
            ) : (
              <Lock className="w-5 h-5 text-muted-foreground" />
            )}
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <p className={`font-bold text-sm ${unlocked ? 'text-white' : 'text-foreground'}`}>
                {tier.tierName}
              </p>
              {unlocked && <Unlock className="w-3.5 h-3.5 text-white/80" />}
            </div>
            <p className={`text-[11px] ${unlocked ? 'text-white/75' : 'text-muted-foreground'}`}>
              {tier.minPoints.toLocaleString('id-ID')}+ poin diperlukan
            </p>
          </div>
          <Icon className={`w-6 h-6 ${unlocked ? 'text-white/60' : 'text-muted-foreground/40'}`} />
        </div>

        {/* Progress bar (only for locked tiers) */}
        {!unlocked && (
          <div className="px-4 pt-3">
            <div className="flex items-center justify-between text-[10px] mb-1.5">
              <span className="text-muted-foreground">Progres kamu</span>
              <span className="font-semibold text-foreground">{userPoints.toLocaleString('id-ID')} / {tier.minPoints.toLocaleString('id-ID')}</span>
            </div>
            <div className="h-2 rounded-full bg-muted overflow-hidden">
              <motion.div
                className={`h-full rounded-full bg-gradient-to-r ${tier.gradient}`}
                initial={{ width: 0 }}
                animate={{ width: `${progress}%` }}
                transition={{ delay: index * 0.08 + 0.3, duration: 0.6 }}
              />
            </div>
            <p className="text-[10px] text-muted-foreground mt-1.5 mb-2">
              Kurang <span className="font-bold text-foreground">{(tier.minPoints - userPoints).toLocaleString('id-ID')}</span> poin lagi
            </p>
          </div>
        )}

        {/* Features */}
        <div className="px-4 pb-3 pt-2">
          <div className="space-y-2">
            {tier.features.map((feature) => (
              <button
                key={feature.id}
                onClick={() => unlocked && feature.route && navigate(feature.route)}
                disabled={!unlocked || !feature.route}
                className={`w-full text-left flex items-start gap-2.5 p-2.5 rounded-xl transition-colors ${
                  unlocked
                    ? 'bg-background hover:bg-muted/50 cursor-pointer'
                    : 'bg-muted/20 opacity-60'
                }`}
              >
                <span className="text-lg flex-shrink-0 mt-0.5">{feature.icon}</span>
                <div className="flex-1 min-w-0">
                  <p className={`text-xs font-bold ${unlocked ? 'text-foreground' : 'text-muted-foreground'}`}>
                    {feature.name}
                  </p>
                  <p className="text-[10px] text-muted-foreground leading-relaxed mt-0.5">
                    {feature.description}
                  </p>
                </div>
                {unlocked && feature.route && (
                  <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0 mt-1" />
                )}
                {!unlocked && (
                  <Lock className="w-3.5 h-3.5 text-muted-foreground/50 flex-shrink-0 mt-1" />
                )}
              </button>
            ))}
          </div>
        </div>
      </div>
    </motion.div>
  );
}

export default function ExclusiveFeaturesPage() {
  const navigate = useNavigate();
  const { totalPoints, loading } = useUserPoints();

  const unlockedCount = FEATURE_TIERS.filter(t => totalPoints >= t.minPoints).length;
  const totalFeatures = FEATURE_TIERS.reduce((sum, t) => sum + t.features.length, 0);
  const unlockedFeatures = FEATURE_TIERS.filter(t => totalPoints >= t.minPoints).reduce((sum, t) => sum + t.features.length, 0);

  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8 mutari-main">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background/80 backdrop-blur-lg px-4 py-3 flex items-center gap-3 border-b border-border">
          <button onClick={() => navigate(-1)} className="p-1">
            <ArrowLeft className="w-5 h-5 text-foreground" />
          </button>
          <div className="flex-1">
            <h1 className="font-bold text-[15px]">Fitur Eksklusif</h1>
            <p className="text-[10px] text-muted-foreground">Unlock fitur premium dengan poin kamu</p>
          </div>
          <Sparkles className="w-5 h-5 text-primary" />
        </div>

        {loading ? (
          <div className="p-4 space-y-4">
            <Skeleton className="h-24 rounded-2xl" />
            <Skeleton className="h-64 rounded-2xl" />
            <Skeleton className="h-64 rounded-2xl" />
          </div>
        ) : (
          <>
            {/* Stats summary */}
            <div className="px-4 pt-4">
              <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="rounded-2xl bg-gradient-to-br from-primary to-primary/80 text-primary-foreground p-4"
              >
                <div className="flex items-center justify-between">
                  <div>
