import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Users, UserCheck, UserMinus, MapPin, Search } from 'lucide-react';
import { getMyFollows, toggleFollow, GetMyFollowsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import BadgeChip from '../components/BadgeChip';
import BottomNav from '../components/BottomNav';

type FollowUser = GetMyFollowsOutputType['following'][0];

export default function FollowListPage() {
  const navigate = useNavigate();
  const [data, setData] = useState<GetMyFollowsOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState<'following' | 'followers'>('following');
  const [search, setSearch] = useState('');
  const [unfollowingId, setUnfollowingId] = useState<string | null>(null);

  useEffect(() => {
    getMyFollows({ tab: 'following' }).then(setData).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const handleUnfollow = async (userId: string) => {
    setUnfollowingId(userId);
    try {
      await toggleFollow({ targetUserId: userId });
      // Remove from local state
      setData(prev => prev ? {
        ...prev,
        following: prev.following.filter(u => u.id !== userId),
        followingCount: prev.followingCount - 1,
      } : prev);
    } catch {
      // ignore
    } finally {
      setUnfollowingId(null);
    }
  };

  const list = tab === 'following' ? data?.following : data?.followers;
  const filtered = list?.filter(u =>
    u.name.toLowerCase().includes(search.toLowerCase()) ||
    u.city.toLowerCase().includes(search.toLowerCase())
  ) ?? [];

  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8 mutari-main">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1">
              <ArrowLeft className="w-5 h-5 text-foreground" />
            </button>
            <h1 className="text-lg font-bold text-foreground flex-1">Daftar Teman</h1>
            <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-primary/10">
              <Users className="w-3.5 h-3.5 text-primary" />
              <span className="text-xs font-bold text-primary">{data?.followingCount ?? 0}</span>
            </div>
          </div>

          {/* Tabs */}
          <div className="flex px-4 gap-1">
            <button
              onClick={() => setTab('following')}
              className={`flex-1 py-2.5 text-xs font-bold text-center border-b-2 transition-colors ${
                tab === 'following' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'
              }`}
            >
              Mengikuti ({data?.followingCount ?? 0})
            </button>
            <button
              onClick={() => setTab('followers')}
              className={`flex-1 py-2.5 text-xs font-bold text-center border-b-2 transition-colors ${
                tab === 'followers' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground'
              }`}
            >
              Pengikut ({data?.followersCount ?? 0})
            </button>
          </div>
        </div>

        {/* Search */}
        <div className="px-4 pt-3">
          <div className="flex items-center gap-2 bg-muted rounded-xl px-3 py-2">
            <Search className="w-4 h-4 text-muted-foreground flex-shrink-0" />
            <input
              type="text"
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Cari nama atau kota..."
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            />
          </div>
        </div>

        {/* List */}
        <div className="px-4 mt-3 space-y-2">
          {loading ? (
            Array.from({ length: 5 }).map((_, i) => (
              <div key={i} className="flex items-center gap-3 p-3 rounded-xl bg-card border border-border">
                <Skeleton className="w-10 h-10 rounded-full" />
                <div className="flex-1 space-y-1.5">
                  <Skeleton className="h-3.5 w-28 rounded" />
                  <Skeleton className="h-2.5 w-20 rounded" />
                </div>
              </div>
            ))
          ) : filtered.length === 0 ? (
            <div className="py-12 text-center">
              <Users className="w-10 h-10 text-muted-foreground mx-auto mb-3" />
              <p className="text-sm font-medium text-muted-foreground">
                {search ? 'Tidak ditemukan' : tab === 'following' ? 'Belum mengikuti siapapun' : 'Belum ada pengikut'}
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                {tab === 'following' ? 'Ikuti pengguna lain dari halaman profil mereka' : 'Bagikan profil kamu untuk mendapatkan pengikut'}
              </p>
            </div>
          ) : (
            filtered.map(u => (
              <UserCard
                key={u.id}
                user={u}
                showUnfollow={tab === 'following'}
                unfollowing={unfollowingId === u.id}
                onUnfollow={() => handleUnfollow(u.id)}
                onTap={() => navigate(`/user/${u.id}`)}
              />
            ))
          )}
        </div>
      </div>
      <BottomNav />
    </div>
  );
}

function UserCard({ user, showUnfollow, unfollowing, onUnfollow, onTap }: {
  user: FollowUser; showUnfollow: boolean; unfollowing: boolean;
  onUnfollow: () => void; onTap: () => void;
}) {
  const initials = (user.name[0] || 'U').toUpperCase();

  return (
    <div className="flex items-center gap-3 p-3 rounded-xl bg-card border border-border">
      <button onClick={onTap} className="flex-shrink-0">
        {user.image ? (
          <img src={user.image} alt={user.name} className="w-10 h-10 rounded-full object-cover" />
        ) : (
          <div className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center text-sm font-bold">
            {initials}
          </div>
        )}
      </button>
      <button onClick={onTap} className="flex-1 min-w-0 text-left">
        <p className="text-sm font-semibold truncate">{user.name}</p>
        <div className="flex items-center gap-2 mt-0.5">
          {user.city && (
            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
              <MapPin className="w-2.5 h-2.5" /> {user.city}
            </span>
          )}
          <BadgeChip points={user.totalPoints} size="sm" />
        </div>
      </button>
      {showUnfollow && (
        <button
          onClick={e => { e.stopPropagation(); onUnfollow(); }}
          disabled={unfollowing}
          className="flex items-center gap-1 px-3 py-1.5 rounded-full text-[10px] font-bold bg-muted text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-colors"
        >
          {unfollowing ? (
            <span className="w-3 h-3 border-2 border-current border-t-transparent rounded-full animate-spin" />
          ) : (
            <UserMinus className="w-3 h-3" />
          )}
          Hapus
        </button>
      )}
    </div>
  );
}

