import { useState, useMemo, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Search, ChevronDown, ChevronUp, MessageSquare, BookOpen, HelpCircle, Phone, Mail, ExternalLink, Send, Headphones, Loader2 } from 'lucide-react';
import { useAuth } from 'zitejs/auth';
import { getSupportMessages, sendSupportMessage, GetSupportMessagesOutputType } from 'zitejs/api';
import { toast } from 'sonner';

const FAQ_DATA = [
  { q: 'Bagaimana cara upload barang?', a: 'Buka tab Barter di navigasi bawah, lalu ketuk tombol "+ Upload Barang". Isi foto, nama, deskripsi, kategori, kondisi, dan lokasi barang kamu. Pastikan foto jelas agar menarik minat penukar lain.' },
  { q: 'Bagaimana cara melakukan barter?', a: 'Temukan barang yang kamu inginkan, lalu ketuk "Ajukan Barter". Pilih barang milikmu yang ingin ditukar, tambahkan pesan, dan kirim penawaran. Pemilik barang akan menerima notifikasi dan bisa menerima atau menolak.' },
  { q: 'Apa itu sistem poin dan badge?', a: 'Setiap kali kamu berhasil barter, kamu mendapatkan poin. Poin bisa digunakan untuk mendapatkan badge seperti Pendatang Baru, Barterer Aktif, hingga Legenda Barter. Badge menunjukkan reputasi kamu di MUTARI.' },
  { q: 'Bagaimana jika barang tidak sesuai?', a: 'Saat barter diterima, kedua pihak menaruh deposit 50 MP. Jika barang yang diterima tidak sesuai deskripsi, kamu bisa melaporkan melalui fitur "Laporkan Pelanggaran". Pihak yang melanggar akan kehilangan 50 MP yang diberikan sebagai kompensasi ke pihak lain. Tim MUTARI akan meninjau laporan dalam 1-3 hari kerja.' },
  { q: 'Cara menghubungi pengguna lain', a: 'Setelah penawaran barter diterima, kamu bisa menggunakan fitur chat bawaan untuk berkomunikasi langsung dengan pengguna lain. Chat tersedia di tab Chat pada navigasi bawah.' },
  { q: 'Apakah barter aman di MUTARI?', a: 'MUTARI menyediakan sistem verifikasi pengguna, rating & review, serta fitur laporan pelanggaran. Kami sangat menyarankan untuk melakukan COD (Cash on Delivery) di tempat umum yang ramai untuk keamanan.' },
  { q: 'Bagaimana cara mengatur lokasi COD?', a: 'Saat barter disetujui, kamu dan partner barter bisa menyepakati lokasi COD melalui fitur "Atur Lokasi COD" di halaman negosiasi barter. Pilih titik temu yang aman dan nyaman untuk keduanya.' },
  { q: 'Apakah ada biaya menggunakan MUTARI?', a: 'Tidak! MUTARI sepenuhnya gratis. Konsep kami adalah tukar-menukar barang tanpa uang. Kamu hanya perlu mendaftar dan mulai barter.' },
];

const GUIDE_STEPS = [
  { step: 1, title: 'Daftar & Lengkapi Profil', desc: 'Buat akun MUTARI dan lengkapi profil kamu termasuk foto, nama, dan verifikasi nomor HP.' },
  { step: 2, title: 'Upload Barang', desc: 'Foto barang kamu dengan jelas, beri nama, deskripsi detail, dan pilih kategori yang sesuai.' },
  { step: 3, title: 'Temukan & Ajukan Barter', desc: 'Jelajahi barang yang tersedia, temukan yang kamu suka, lalu ajukan penawaran barter.' },
  { step: 4, title: 'Negosiasi & Setujui', desc: 'Diskusikan detail pertukaran melalui chat. Jika cocok, setujui barter.' },
  { step: 5, title: 'COD & Selesai', desc: 'Tentukan lokasi COD yang aman, bertemu, tukar barang, dan konfirmasi penyelesaian barter.' },
];

type View = 'main' | 'faq' | 'guide' | 'contact' | 'chat';

export default function HelpPage() {
  const navigate = useNavigate();
  const [view, setView] = useState<View>('main');
  const [search, setSearch] = useState('');
  const [openFaq, setOpenFaq] = useState<number | null>(null);

  const filtered = useMemo(() => {
    if (!search.trim()) return FAQ_DATA;
    const q = search.toLowerCase();
    return FAQ_DATA.filter(f => f.q.toLowerCase().includes(q) || f.a.toLowerCase().includes(q));
  }, [search]);

  const topikFiltered = useMemo(() => {
    if (!search.trim()) return FAQ_DATA.slice(0, 5);
    return filtered.slice(0, 5);
  }, [search, filtered]);

  if (view === 'faq') return <FaqView search={search} setSearch={setSearch} filtered={filtered} openFaq={openFaq} setOpenFaq={setOpenFaq} onBack={() => setView('main')} />;
  if (view === 'guide') return <GuideView onBack={() => setView('main')} />;
  if (view === 'contact') return <ContactView onBack={() => setView('main')} />;
  if (view === 'chat') return <SupportChatView onBack={() => setView('main')} />;

  return (
    <div className="min-h-screen bg-background mutari-main pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">Pusat Bantuan</h1>
        </div>

        <div className="px-4 mt-4">
          <div className="bg-muted rounded-xl px-4 py-3 flex items-center gap-2">
            <Search className="w-4 h-4 text-muted-foreground" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Cari bantuan..."
              className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
            />
          </div>
        </div>

        {search.trim() ? (
          <div className="px-4 mt-4">
            <p className="text-xs text-muted-foreground mb-2">{filtered.length} hasil ditemukan</p>
            <div className="space-y-2">
              {filtered.length === 0 && (
                <p className="text-sm text-muted-foreground text-center py-6">Tidak ada hasil untuk "{search}"</p>
              )}
              {filtered.map((f, i) => (
                <button key={i} onClick={() => { setOpenFaq(i); setView('faq'); }} className="w-full bg-card rounded-xl border border-border px-4 py-3 text-left hover:bg-muted/50 transition-colors">
                  <p className="text-xs font-medium">{f.q}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5 line-clamp-2">{f.a}</p>
                </button>
              ))}
            </div>
          </div>
        ) : (
          <>
            <div className="px-4 mt-4">
              <div className="bg-card rounded-2xl border border-border overflow-hidden divide-y divide-border shadow-sm">
                {[
                  { icon: Headphones, label: 'Chat Admin', sub: 'Chat langsung dengan tim support MUTARI', target: 'chat' as View },
                  { icon: HelpCircle, label: 'FAQ', sub: 'Pertanyaan yang sering ditanyakan', target: 'faq' as View },
                  { icon: BookOpen, label: 'Panduan Barter', sub: 'Cara menggunakan MUTARI dengan aman', target: 'guide' as View },
                  { icon: MessageSquare, label: 'Hubungi Kami', sub: 'Kirim pesan ke tim support MUTARI', target: 'contact' as View },
                ].map(item => (
                  <button key={item.label} onClick={() => setView(item.target)} className="w-full px-4 py-3.5 flex items-center gap-3 text-left hover:bg-muted/50 transition-colors">
                    <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
                      <item.icon className="w-4 h-4 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold">{item.label}</p>
                      <p className="text-[10px] text-muted-foreground">{item.sub}</p>
                    </div>
                    <ExternalLink className="w-4 h-4 text-muted-foreground flex-shrink-0" />
                  </button>
                ))}
              </div>
            </div>

            <div className="px-4 mt-5">
              <h3 className="font-bold text-sm mb-2">Topik Populer</h3>
              <div className="space-y-2">
                {topikFiltered.map((f, i) => (
                  <button key={i} onClick={() => { setOpenFaq(FAQ_DATA.indexOf(f)); setView('faq'); }} className="w-full bg-card rounded-xl border border-border px-4 py-3 text-left hover:bg-muted/50 transition-colors flex items-center gap-2 shadow-sm">
                    <span className="text-xs text-foreground flex-1">{f.q}</span>
                    <ExternalLink className="w-3.5 h-3.5 text-muted-foreground flex-shrink-0" />
                  </button>
                ))}
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function FaqView({ search, setSearch, filtered, openFaq, setOpenFaq, onBack }: {
  search: string; setSearch: (s: string) => void; filtered: typeof FAQ_DATA; openFaq: number | null; setOpenFaq: (n: number | null) => void; onBack: () => void;
}) {
  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={onBack} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">FAQ</h1>
        </div>

        <div className="px-4 mt-4">
          <div className="bg-muted rounded-xl px-4 py-3 flex items-center gap-2">
            <Search className="w-4 h-4 text-muted-foreground" />
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Cari pertanyaan..." className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground" />
          </div>
        </div>

        <div className="px-4 mt-4 space-y-2">
          {filtered.length === 0 && <p className="text-sm text-muted-foreground text-center py-6">Tidak ada hasil.</p>}
          {filtered.map((f, i) => {
            const idx = FAQ_DATA.indexOf(f);
            const isOpen = openFaq === idx;
            return (
              <div key={idx} className="bg-card rounded-xl border border-border overflow-hidden shadow-sm">
                <button onClick={() => setOpenFaq(isOpen ? null : idx)} className="w-full px-4 py-3 flex items-center gap-2 text-left">
                  <span className="text-xs font-medium flex-1">{f.q}</span>
                  {isOpen ? <ChevronUp className="w-4 h-4 text-muted-foreground" /> : <ChevronDown className="w-4 h-4 text-muted-foreground" />}
                </button>
                {isOpen && (
                  <div className="px-4 pb-3 border-t border-border pt-2">
                    <p className="text-xs text-muted-foreground leading-relaxed">{f.a}</p>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function GuideView({ onBack }: { onBack: () => void }) {
  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={onBack} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">Panduan Barter</h1>
        </div>

        <div className="px-4 mt-4">
          <div className="bg-primary/10 rounded-2xl p-4 mb-4">
            <p className="text-sm font-semibold text-primary">5 Langkah Mudah Barter di MUTARI</p>
            <p className="text-[10px] text-muted-foreground mt-1">Ikuti panduan ini untuk mulai bertukar barang dengan aman.</p>
          </div>

          <div className="space-y-3">
            {GUIDE_STEPS.map(s => (
              <div key={s.step} className="bg-card rounded-xl border border-border p-4 shadow-sm flex gap-3">
                <div className="w-8 h-8 rounded-full bg-primary text-primary-foreground flex items-center justify-center text-xs font-bold flex-shrink-0">{s.step}</div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">{s.title}</p>
                  <p className="text-[10px] text-muted-foreground mt-0.5 leading-relaxed">{s.desc}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-4 bg-card rounded-xl border border-border p-4 shadow-sm">
            <p className="text-xs font-semibold">💡 Tips Keamanan</p>
            <ul className="mt-2 space-y-1.5 text-[10px] text-muted-foreground">
              <li>• Selalu bertemu di tempat umum yang ramai</li>
              <li>• Periksa barang sebelum konfirmasi barter</li>
              <li>• Gunakan fitur chat bawaan MUTARI</li>
              <li>• Laporkan jika ada yang mencurigakan</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
}

function ContactView({ onBack }: { onBack: () => void }) {
  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={onBack} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">Hubungi Kami</h1>
        </div>

        <div className="px-4 mt-4 space-y-3">
          <div className="bg-card rounded-xl border border-border p-4 shadow-sm">
            <p className="text-sm font-semibold mb-3">Butuh bantuan lebih lanjut?</p>
            <p className="text-xs text-muted-foreground leading-relaxed">Tim support MUTARI siap membantu kamu. Hubungi kami melalui salah satu cara berikut:</p>
          </div>

          <a href="mailto:mutari.support@gmail.com" className="block bg-card rounded-xl border border-border p-4 shadow-sm hover:bg-muted/50 transition-colors">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
                <Mail className="w-5 h-5 text-primary" />
              </div>
