type SupportMsg = GetSupportMessagesOutputType['messages'][0];

function SupportChatView({ onBack }: { onBack: () => void }) {
  const { user } = useAuth();
  const [messages, setMessages] = useState<SupportMsg[]>([]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(true);
  const bottomRef = useRef<HTMLDivElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const prevMsgCount = useRef(0);
  const shouldAutoScroll = useRef(true);

  const isNearBottom = () => {
    const el = scrollContainerRef.current;
    if (!el) return true;
    return el.scrollHeight - el.scrollTop - el.clientHeight < 120;
  };

  const loadMessages = async () => {
    try {
      const res = await getSupportMessages({});
      setMessages(res.messages);
    } catch { /* ignore */ }
    setLoading(false);
  };

  useEffect(() => { loadMessages(); }, []);

  useEffect(() => {
    if (shouldAutoScroll.current || isNearBottom()) {
      bottomRef.current?.scrollIntoView({ behavior: prevMsgCount.current === 0 ? 'instant' : 'smooth' });
    }
    prevMsgCount.current = messages.length;
    shouldAutoScroll.current = false;
  }, [messages]);

  // Poll for new messages every 8s
  useEffect(() => {
    const interval = setInterval(async () => {
      try {
        const res = await getSupportMessages({});
        setMessages(res.messages);
      } catch { /* ignore */ }
    }, 8000);
    return () => clearInterval(interval);
  }, []);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || sending) return;
    setSending(true);
    setInput('');
    shouldAutoScroll.current = true;

    // Optimistic
    const optimistic: SupportMsg = {
      id: 'temp-' + Date.now(),
      content: text,
      senderRole: 'user',
      read: false,
      createdAt: new Date().toISOString(),
      subject: 'Chat Support',
    };
    setMessages(prev => [...prev, optimistic]);

    try {
      await sendSupportMessage({ content: text });
      await loadMessages();
    } catch {
      toast.error('Gagal mengirim pesan');
      setMessages(prev => prev.filter(m => m.id !== optimistic.id));
      setInput(text);
    }
    setSending(false);
    inputRef.current?.focus();
  };

  const formatTime = (iso: string) => {
    try {
      const d = new Date(iso);
      return d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    } catch { return ''; }
  };

  const formatDate = (iso: string) => {
    try {
      const d = new Date(iso);
      const today = new Date();
      if (d.toDateString() === today.toDateString()) return 'Hari ini';
      const yesterday = new Date(today);
      yesterday.setDate(today.getDate() - 1);
      if (d.toDateString() === yesterday.toDateString()) return 'Kemarin';
      return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    } catch { return ''; }
  };

  // Group by date
  const grouped: { date: string; msgs: SupportMsg[] }[] = [];
  messages.forEach(m => {
    const dateStr = formatDate(m.createdAt);
    const last = grouped[grouped.length - 1];
    if (last && last.date === dateStr) {
      last.msgs.push(m);
    } else {
      grouped.push({ date: dateStr, msgs: [m] });
    }
  });

  return (
    <div className="h-[100dvh] bg-background flex flex-col">
      <div className="max-w-[420px] mx-auto w-full flex flex-col flex-1 min-h-0">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border">
          <div className="px-4 py-3 flex items-center gap-3">
            <button onClick={onBack} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
              <Headphones className="w-4 h-4 text-primary" />
            </div>
            <div className="flex-1 min-w-0">
              <h1 className="font-bold text-sm text-foreground">Tim Support MUTARI</h1>
              <p className="text-[10px] text-muted-foreground">Biasanya membalas dalam 1-24 jam</p>
            </div>
          </div>
        </div>

        {/* Messages */}
        <div ref={scrollContainerRef} className="flex-1 overflow-y-auto px-4 py-3 space-y-4 overscroll-contain">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-6 h-6 text-primary animate-spin" />
            </div>
          ) : messages.length === 0 ? (
            <div className="text-center py-12 space-y-3">
              <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center mx-auto">
                <Headphones className="w-8 h-8 text-primary" />
              </div>
              <p className="text-sm font-semibold">Halo{user?.firstName ? `, ${user.firstName}` : ''}! 👋</p>
              <p className="text-xs text-muted-foreground leading-relaxed max-w-[260px] mx-auto">
                Sampaikan keluhan, laporan, atau pertanyaan kamu di sini. Tim admin MUTARI akan segera membalas.
              </p>
              <div className="flex flex-wrap justify-center gap-2 mt-3">
                {['Lapor pengguna', 'Masalah barter', 'Akun saya', 'Pertanyaan lain'].map(q => (
                  <button
                    key={q}
                    onClick={() => setInput(q + ': ')}
                    className="px-3 py-1.5 rounded-full bg-muted border border-border text-[10px] font-medium hover:bg-primary/10 transition"
                  >
                    {q}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            grouped.map((group, gi) => (
              <div key={gi}>
                <div className="flex justify-center mb-2">
                  <span className="text-[10px] text-muted-foreground bg-muted px-3 py-0.5 rounded-full">{group.date}</span>
                </div>
                <div className="space-y-2">
                  {group.msgs.map(m => {
                    const isUser = m.senderRole === 'user';
                    return (
                      <div key={m.id} className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
                        {!isUser && (
                          <div className="w-7 h-7 rounded-full bg-primary flex items-center justify-center mr-2 mt-auto mb-1 flex-shrink-0">
                            <Headphones className="w-3.5 h-3.5 text-primary-foreground" />
                          </div>
                        )}
                        <div
                          className={`max-w-[75%] rounded-2xl px-3.5 py-2.5 ${
                            isUser
                              ? 'bg-primary text-primary-foreground rounded-br-md'
                              : 'bg-card border border-border text-foreground rounded-bl-md'
                          }`}
                        >
                          {!isUser && (
                            <p className="text-[10px] font-semibold text-primary mb-0.5">Admin MUTARI</p>
                          )}
                          <p className="text-xs leading-relaxed whitespace-pre-wrap">{m.content}</p>
                          <p className={`text-[9px] mt-1 text-right ${isUser ? 'text-primary-foreground/60' : 'text-muted-foreground'}`}>
                            {formatTime(m.createdAt)}
                          </p>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))
          )}
          <div ref={bottomRef} />
        </div>

        {/* Input */}
        <div className="flex-shrink-0 bg-background border-t border-border px-4 py-3 pb-[max(0.75rem,env(safe-area-inset-bottom))]">
          <div className="flex items-center gap-2">
            <input
              ref={inputRef}
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              onFocus={() => { setTimeout(() => { inputRef.current?.scrollIntoView({ block: 'end', behavior: 'smooth' }); }, 300); }}
              placeholder="Tulis pesan ke admin..."
              className="flex-1 bg-muted rounded-full px-4 py-2.5 text-sm outline-none focus:ring-1 focus:ring-primary placeholder:text-muted-foreground"
              enterKeyHint="send"
              autoComplete="off"
            />
            <button
              onClick={handleSend}
              disabled={!input.trim() || sending}
              className="w-10 h-10 rounded-full bg-primary text-primary-foreground flex items-center justify-center disabled:opacity-40 active:scale-95 transition"
            >
              {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

