import { useState, useEffect } from 'react';
import { loginWithRedirect } from 'zitejs/auth';
import HeroSection from '../components/landing/HeroSection';
import FeaturesSection from '../components/landing/FeaturesSection';
import HowItWorks from '../components/landing/HowItWorks';
import TestimonialsSection from '../components/landing/TestimonialsSection';
import CTASection from '../components/landing/CTASection';
import LandingFooter from '../components/landing/LandingFooter';
import LandingNav from '../components/landing/LandingNav';
import RegisterPage from './RegisterPage';

export default function LandingPage() {
  const [showRegister, setShowRegister] = useState(false);
  const handleLogin = () => loginWithRedirect();
  const handleRegister = () => setShowRegister(true);

  // Auto-open register if referral code in URL
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get('ref') || params.get('referral') || params.get('code')) {
      setShowRegister(true);
    }
  }, []);

  if (showRegister) {
    return <RegisterPage onBack={() => setShowRegister(false)} />;
  }

  return (
    <div className="min-h-screen bg-background overflow-x-hidden">
      <LandingNav onLogin={handleLogin} onRegister={handleRegister} />
