import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowLeft, Zap, ArrowRightLeft, ChevronRight, Sparkles, RefreshCw } from 'lucide-react';
import { getMatchAlerts, GetMatchAlertsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import BottomNav from '../components/BottomNav';

type Alert = GetMatchAlertsOutputType['alerts'][0];

export default function MatchAlertsPage() {
  const navigate = useNavigate();
  const [data, setData] = useState<GetMatchAlertsOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const load = (isRefresh = false) => {
    if (isRefresh) setRefreshing(true); else setLoading(true);
    getMatchAlerts({})
      .then(setData)
      .catch(() => {})
      .finally(() => { setLoading(false); setRefreshing(false); });
  };

  useEffect(() => { load(); }, []);

  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8 mutari-main">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1">
              <ArrowLeft className="w-5 h-5 text-foreground" />
            </button>
            <div className="flex-1">
              <h1 className="text-lg font-bold text-foreground flex items-center gap-2">
                <Zap className="w-5 h-5 text-amber-500" /> Match Alert
              </h1>
              <p className="text-[10px] text-muted-foreground">Kecocokan otomatis berdasarkan barang & keinginan</p>
            </div>
            <button
              onClick={() => load(true)}
              disabled={refreshing}
              className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center"
            >
              <RefreshCw className={`w-4 h-4 text-primary ${refreshing ? 'animate-spin' : ''}`} />
            </button>
          </div>
        </div>

        {/* Info banner */}
        <div className="mx-4 mt-4 rounded-2xl overflow-hidden bg-gradient-to-r from-amber-500 via-orange-500 to-red-500 p-4 text-white">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center">
              <Sparkles className="w-5 h-5" />
            </div>
            <div>
              <h2 className="font-bold text-sm">Match Alert Cerdas</h2>
              <p className="text-[10px] opacity-80">Menemukan kecocokan mutual — kamu punya yang mereka cari & sebaliknya!</p>
            </div>
          </div>
        </div>

        {/* Alerts list */}
        <div className="px-4 mt-4 space-y-3">
          {loading ? (
            Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="h-36 rounded-2xl bg-muted animate-pulse" />
            ))
          ) : !data || data.alerts.length === 0 ? (
            <EmptyState />
          ) : (
            data.alerts.map((alert, i) => (
              <MatchAlertCard key={alert.id} alert={alert} index={i} navigate={navigate} />
            ))
          )}
        </div>

        {/* Tips */}
        <div className="mx-4 mt-6 p-4 rounded-2xl bg-muted/50 border border-border">
          <h3 className="text-sm font-bold text-foreground mb-2">💡 Tips Match Alert</h3>
          <ul className="space-y-1.5 text-xs text-muted-foreground">
            <li className="flex gap-2"><span>📝</span> Isi "Ingin Ditukar Dengan" yang spesifik saat upload barang</li>
            <li className="flex gap-2"><span>📦</span> Semakin banyak barang kamu upload, semakin besar peluang match</li>
            <li className="flex gap-2"><span>🔔</span> Match Alert dikirim otomatis saat ada upload baru yang cocok</li>
            <li className="flex gap-2"><span>⚡</span> Langsung ajukan barter saat melihat match yang bagus!</li>
          </ul>
        </div>
      </div>
      <BottomNav />
    </div>
  );
}

function EmptyState() {
  return (
    <div className="py-16 text-center">
      <div className="w-16 h-16 rounded-full bg-amber-500/10 flex items-center justify-center mx-auto mb-4">
        <Zap className="w-8 h-8 text-amber-500" />
      </div>
      <h3 className="font-bold text-foreground mb-1">Belum Ada Match</h3>
      <p className="text-xs text-muted-foreground max-w-[260px] mx-auto">
        Upload lebih banyak barang dan isi kolom "Ingin Ditukar Dengan" supaya sistem bisa menemukan kecocokan untuk kamu
      </p>
    </div>
  );
}

function MatchAlertCard({ alert, index, navigate }: { alert: Alert; index: number; navigate: ReturnType<typeof useNavigate> }) {
  const scoreColor = alert.matchScore >= 70 ? 'from-emerald-500 to-green-500' : alert.matchScore >= 40 ? 'from-amber-500 to-orange-500' : 'from-blue-500 to-indigo-500';
  const scoreLabel = alert.matchScore >= 70 ? 'Cocok Banget!' : alert.matchScore >= 40 ? 'Potensi Bagus' : 'Mungkin Cocok';

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.08 }}
      className="rounded-2xl border border-border bg-card overflow-hidden"
    >
      {/* Score header */}
      <div className={`bg-gradient-to-r ${scoreColor} px-4 py-2 flex items-center justify-between`}>
        <span className="text-white text-xs font-bold flex items-center gap-1.5">
          <Zap className="w-3.5 h-3.5" /> {scoreLabel}
        </span>
        <span className="text-white/90 text-[10px] font-bold bg-white/20 px-2 py-0.5 rounded-full">
          {alert.matchScore}% match
        </span>
      </div>

      {/* Items comparison */}
      <div className="p-3">
        <div className="flex items-center gap-2">
          {/* My item */}
          <button
            onClick={() => navigate(`/item/${alert.myItemId}`)}
            className="flex-1 flex items-center gap-2 p-2 rounded-xl bg-muted/50 hover:bg-muted transition-colors min-w-0"
          >
            {alert.myItemPhoto ? (
              <img src={alert.myItemPhoto} alt="" className="w-12 h-12 rounded-lg object-cover flex-shrink-0" />
            ) : (
              <div className="w-12 h-12 rounded-lg bg-muted flex-shrink-0" />
            )}
            <div className="min-w-0">
              <p className="text-[9px] text-muted-foreground font-medium">Barang Kamu</p>
              <p className="text-[11px] font-semibold truncate">{alert.myItemTitle}</p>
            </div>
          </button>

          {/* Arrow */}
          <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
            <ArrowRightLeft className="w-3.5 h-3.5 text-primary" />
          </div>

          {/* Their item */}
          <button
            onClick={() => navigate(`/item/${alert.theirItemId}`)}
            className="flex-1 flex items-center gap-2 p-2 rounded-xl bg-muted/50 hover:bg-muted transition-colors min-w-0"
          >
            {alert.theirItemPhoto ? (
              <img src={alert.theirItemPhoto} alt="" className="w-12 h-12 rounded-lg object-cover flex-shrink-0" />
            ) : (
              <div className="w-12 h-12 rounded-lg bg-muted flex-shrink-0" />
            )}
            <div className="min-w-0">
              <p className="text-[9px] text-muted-foreground font-medium">Barang Mereka</p>
              <p className="text-[11px] font-semibold truncate">{alert.theirItemTitle}</p>
            </div>
          </button>
        </div>

        {/* Match reason */}
        <p className="text-[10px] text-muted-foreground mt-2 px-1">{alert.matchReason}</p>

        {/* Owner & CTA */}
        <div className="flex items-center justify-between mt-3 pt-2.5 border-t border-border">
          <button
            onClick={() => navigate(`/user/${alert.theirOwnerId}`)}
            className="flex items-center gap-2 min-w-0"
          >
            {alert.theirOwnerImage ? (
              <img src={alert.theirOwnerImage} alt="" className="w-6 h-6 rounded-full object-cover" />
            ) : (
              <div className="w-6 h-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-[9px] font-bold">
                {alert.theirOwnerName[0]?.toUpperCase()}
              </div>
            )}
            <span className="text-xs font-medium truncate">{alert.theirOwnerName}</span>
          </button>
          <button
            onClick={() => navigate(`/item/${alert.theirItemId}`)}
            className="flex items-center gap-1 px-3 py-1.5 rounded-full bg-primary text-primary-foreground text-[10px] font-bold active:scale-95 transition-transform"
          >
            Lihat & Barter <ChevronRight className="w-3 h-3" />
          </button>
        </div>
      </div>
    </motion.div>
  );
}

