import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft, Target, Gift, Check, Clock,
  ChevronRight, Flame, Trophy, Sparkles,
} from 'lucide-react';
import { getWeeklyMissions, claimMissionReward, GetWeeklyMissionsOutputType } from 'zitejs/api';
import BottomNav from '../components/BottomNav';
import Confetti from '../components/Confetti';

type Mission = GetWeeklyMissionsOutputType['missions'][0];

export default function MissionsPage() {
  const navigate = useNavigate();
  const [data, setData] = useState<GetWeeklyMissionsOutputType | null>(null);
  const [loading, setLoading] = useState(true);
  const [claimingId, setClaimingId] = useState<string | null>(null);
  const [showConfetti, setShowConfetti] = useState(false);
  const [toast, setToast] = useState('');

  const refresh = useCallback(() => {
    setLoading(true);
    getWeeklyMissions({}).then(setData).catch(() => {}).finally(() => setLoading(false));
  }, []);

  useEffect(() => { refresh(); }, [refresh]);

  const handleClaim = async (userMissionId: string) => {
    setClaimingId(userMissionId);
    try {
      const res = await claimMissionReward({ userMissionId });
      setToast(res.message);
      setShowConfetti(true);
      setTimeout(() => { setShowConfetti(false); setToast(''); }, 3500);
      refresh();
    } catch {
      // ignore
    } finally {
      setClaimingId(null);
    }
  };

  const completedCount = data?.missions.filter(m => m.status === 'completed' || m.status === 'claimed').length ?? 0;
  const totalCount = data?.missions.length ?? 0;

  return (
    <div className="min-h-screen bg-background pb-24 lg:pb-8 mutari-main">
      {showConfetti && <Confetti active={showConfetti} />}
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border">
          <div className="flex items-center gap-3 px-4 py-3">
            <button onClick={() => navigate(-1)} className="p-1">
              <ArrowLeft className="w-5 h-5 text-foreground" />
            </button>
            <div className="flex-1">
              <h1 className="text-lg font-bold text-foreground">Misi & Tantangan</h1>
              <p className="text-xs text-muted-foreground">
                {data ? `${data.weekStart} — ${data.weekEnd}` : '...'}
              </p>
            </div>
            <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-primary/10">
              <Trophy className="w-3.5 h-3.5 text-primary" />
              <span className="text-xs font-bold text-primary">{completedCount}/{totalCount}</span>
            </div>
          </div>
        </div>

        {/* Progress banner */}
        {data && (
          <div className="mx-4 mt-4 rounded-2xl overflow-hidden bg-gradient-to-r from-violet-600 via-purple-600 to-indigo-600 p-4 text-white">
            <div className="flex items-center gap-3 mb-3">
              <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center">
                <Target className="w-5 h-5" />
              </div>
              <div>
                <h2 className="font-bold">Misi Mingguan</h2>
                <p className="text-xs opacity-80">Selesaikan misi untuk dapat bonus poin</p>
              </div>
            </div>
            <div className="flex gap-1">
              {data.missions.map((m, i) => (
                <div
                  key={i}
                  className={`flex-1 h-1.5 rounded-full ${
                    m.status === 'claimed'
                      ? 'bg-emerald-400'
                      : m.status === 'completed'
                      ? 'bg-yellow-400'
                      : 'bg-white/20'
                  }`}
                />
              ))}
            </div>
            {completedCount === totalCount && totalCount > 0 && (
              <p className="text-center text-xs font-bold mt-2 flex items-center justify-center gap-1">
                <Sparkles className="w-3 h-3" /> Semua misi selesai! Keren banget! 🎉
              </p>
            )}
          </div>
        )}

        {/* Mission list */}
        <div className="px-4 mt-4 space-y-3">
          {loading ? (
            Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="h-24 rounded-2xl bg-muted animate-pulse" />
            ))
          ) : (
            data?.missions.map((mission) => (
              <MissionCard
                key={mission.id}
                mission={mission}
                claiming={claimingId === mission.userMissionId}
                onClaim={() => mission.userMissionId && handleClaim(mission.userMissionId)}
              />
            ))
          )}
        </div>

        {/* Info */}
        <div className="mx-4 mt-6 p-4 rounded-2xl bg-muted/50 border border-border">
          <h3 className="text-sm font-bold text-foreground flex items-center gap-2 mb-2">
            <Flame className="w-4 h-4 text-orange-500" /> Cara Kerja
          </h3>
          <ul className="space-y-1.5 text-xs text-muted-foreground">
            <li className="flex gap-2"><span>📋</span> Misi direset setiap minggu (Senin)</li>
            <li className="flex gap-2"><span>✅</span> Selesaikan misi dan klaim hadiah poin</li>
            <li className="flex gap-2"><span>🔥</span> Check-in harian juga termasuk misi</li>
            <li className="flex gap-2"><span>🎯</span> Semakin banyak misi, semakin banyak poin!</li>
          </ul>
        </div>
      </div>

      {/* Toast */}
      <AnimatePresence>
        {toast && (
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 px-5 py-3 rounded-2xl bg-gradient-to-r from-violet-600 to-purple-600 text-white shadow-2xl"
          >
            <p className="text-sm font-bold text-center">{toast}</p>
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  );
}

function MissionCard({ mission, claiming, onClaim }: { mission: Mission; claiming: boolean; onClaim: () => void }) {
  const progress = Math.min(mission.currentProgress / mission.targetCount, 1);
  const isDone = mission.status === 'completed';
  const isClaimed = mission.status === 'claimed';

  return (
    <motion.div
      layout
      className={`rounded-2xl border p-3.5 transition-all ${
        isClaimed
          ? 'bg-muted/30 border-border opacity-70'
          : isDone
          ? 'bg-gradient-to-r from-emerald-50 to-green-50 dark:from-emerald-950/20 dark:to-green-950/20 border-emerald-200 dark:border-emerald-800'
          : 'bg-card border-border'
      }`}
    >
      <div className="flex items-start gap-3">
        {/* Icon */}
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg flex-shrink-0 ${
          isClaimed ? 'bg-muted' : isDone ? 'bg-emerald-100 dark:bg-emerald-900/30' : 'bg-primary/10'
        }`}>
          {isClaimed ? <Check className="w-5 h-5 text-muted-foreground" /> : mission.icon}
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between mb-0.5">
            <h4 className={`text-sm font-bold ${isClaimed ? 'text-muted-foreground line-through' : 'text-foreground'}`}>
              {mission.title}
            </h4>
            <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${
              isClaimed
                ? 'bg-muted text-muted-foreground'
                : isDone
                ? 'bg-emerald-500 text-white'
                : 'bg-primary/10 text-primary'
            }`}>
              +{mission.rewardPoints}
            </span>
          </div>
          <p className="text-[11px] text-muted-foreground mb-2">{mission.description}</p>

          {/* Progress bar */}
          <div className="flex items-center gap-2">
            <div className="flex-1 h-2 rounded-full bg-muted overflow-hidden">
              <motion.div
                initial={{ width: 0 }}
                animate={{ width: `${progress * 100}%` }}
                transition={{ duration: 0.6, ease: 'easeOut' }}
                className={`h-full rounded-full ${
                  isClaimed ? 'bg-muted-foreground/30' : isDone ? 'bg-emerald-500' : 'bg-primary'
                }`}
              />
            </div>
            <span className="text-[10px] font-bold text-muted-foreground flex-shrink-0">
              {mission.currentProgress}/{mission.targetCount}
            </span>
          </div>

          {/* Claim button */}
          {isDone && !isClaimed && (
            <motion.button
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              onClick={onClaim}
              disabled={claiming}
              className="mt-2 w-full py-2 rounded-xl bg-gradient-to-r from-emerald-500 to-green-500 text-white text-xs font-bold flex items-center justify-center gap-1.5 active:scale-[0.97] transition-transform"
            >
              {claiming ? (
                <span className="w-3 h-3 border-2 border-white border-t-transparent rounded-full animate-spin" />
              ) : (
                <>
                  <Gift className="w-3.5 h-3.5" />
                  Klaim Hadiah
                </>
              )}
            </motion.button>
          )}

          {isClaimed && (
            <p className="mt-1.5 text-[10px] text-muted-foreground flex items-center gap-1">
              <Check className="w-3 h-3" /> Hadiah sudah diklaim
            </p>
          )}
        </div>
      </div>
    </motion.div>
  );
}

