import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Plus, Eye, Heart, MapPin, Package, MessageCircle } from 'lucide-react';
import { getMyItems, GetMyItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';

type MyItem = GetMyItemsOutputType['items'][0];

const STATUS_COLORS: Record<string, string> = {
  'Tersedia': 'bg-emerald-100 text-emerald-700',
  'Negosiasi': 'bg-amber-100 text-amber-700',
  'Sudah Ditukar': 'bg-muted text-muted-foreground',
};

function fmt(v: number) {
  return 'Rp' + v.toLocaleString('id-ID');
}

function ItemCard({ item }: { item: MyItem }) {
  const navigate = useNavigate();
  const priceText = item.estimatedValueMin && item.estimatedValueMax && item.estimatedValueMin !== item.estimatedValueMax
    ? `${fmt(item.estimatedValueMin)} – ${fmt(item.estimatedValueMax)}`
    : item.estimatedValueMin ? fmt(item.estimatedValueMin)
    : item.estimatedValueMax ? fmt(item.estimatedValueMax) : '-';

  return (
    <button
      onClick={() => navigate(`/item/${item.id}`)}
      className="w-full bg-card rounded-2xl border border-border overflow-hidden text-left hover:shadow-md transition-shadow"
    >
      <div className="flex gap-3 p-3">
        {item.photo ? (
          <img src={item.photo} alt={item.title} className="w-20 h-20 rounded-xl object-cover flex-shrink-0" />
        ) : (
          <div className="w-20 h-20 rounded-xl bg-muted flex items-center justify-center flex-shrink-0">
            <Package className="w-8 h-8 text-muted-foreground" />
          </div>
        )}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2">
            <p className="text-sm font-bold truncate">{item.title}</p>
            <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium flex-shrink-0 ${STATUS_COLORS[item.status] || 'bg-muted text-muted-foreground'}`}>
              {item.status}
            </span>
          </div>
          <p className="text-xs text-primary font-semibold mt-0.5">{priceText}</p>
          {item.location && (
            <p className="text-[10px] text-muted-foreground flex items-center gap-0.5 mt-1">
              <MapPin className="w-3 h-3" /> {item.location}
            </p>
          )}
          <div className="flex items-center gap-3 mt-1.5 text-[10px] text-muted-foreground">
            <span className="flex items-center gap-0.5"><Eye className="w-3 h-3" /> {item.viewsCount}</span>
            <span className="flex items-center gap-0.5"><Heart className="w-3 h-3" /> {item.likesCount}</span>
            <span className="flex items-center gap-0.5"><MessageCircle className="w-3 h-3" /> {item.commentsCount}</span>
            {item.condition && <span className="px-1.5 py-0.5 bg-muted rounded text-[9px]">{item.condition}</span>}
          </div>
        </div>
      </div>
    </button>
  );
}

export default function MyItemsPage() {
  const navigate = useNavigate();
  const [items, setItems] = useState<MyItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getMyItems({}).then(res => {
      setItems(res.items);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

