import BadgeAvatar from '../components/BadgeAvatar';
import { getBadge, getProgressToNext } from '../lib/badges';

type ProfileData = GetPublicProfileOutputType;

function VerifiedBadge({ label }: { label: string }) {
  return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 text-[10px] font-semibold">
      <CheckCircle2 className="w-3 h-3" /> {label}
    </span>
  );
}

function StatCard({ icon: Icon, value, label, color }: { icon: any; value: string | number; label: string; color: string }) {
  return (
    <div className="flex flex-col items-center gap-1 py-3 px-2">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center ${color}`}>
        <Icon className="w-4 h-4" />
      </div>
      <p className="font-bold text-sm leading-none">{value}</p>
      <p className="text-[10px] text-muted-foreground leading-tight text-center">{label}</p>
    </div>
  );
}

function ItemCard({ item, onTap }: { item: ProfileData['items'][0]; onTap: () => void }) {
  const statusColor = item.status === 'Tersedia' ? 'bg-emerald-500' : item.status === 'Negosiasi' ? 'bg-amber-500' : 'bg-muted-foreground';
  return (
    <button onClick={onTap} className="bg-card border border-border rounded-xl overflow-hidden text-left group shadow-sm">
      <div className="relative">
        {item.photo ? (
          <img src={item.photo} alt={item.title} className="w-full aspect-square object-cover group-hover:scale-105 transition-transform" />
