import { MutariInline } from '../components/MutariSpinner';
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Check, Sparkles } from 'lucide-react';
import { toast } from 'sonner';
import { useProfile } from '../hooks/useProfile';
import { getCategories, GetCategoriesOutputType, updateProfile } from 'zitejs/api';
import { useI18n } from '../context/I18nContext';
import { Skeleton } from '@project/components/ui/skeleton';

type Cat = GetCategoriesOutputType['categories'][0];

export default function PreferredCategoriesPage() {
  const navigate = useNavigate();
  const { profile, loading: profileLoading } = useProfile();
  const { lang } = useI18n();
  const [categories, setCategories] = useState<Cat[]>([]);
  const [selected, setSelected] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    getCategories({}).then(r => {
      setCategories(r.categories);
    }).catch(() => {}).finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    if (profile) {
      const saved = (profile as any).preferredCategories;
      if (saved) {
        try {
          setSelected(JSON.parse(saved));
        } catch {
          setSelected(saved.split(',').map((s: string) => s.trim()).filter(Boolean));
        }
      }
    }
  }, [profile]);

  const toggle = (name: string) => {
    setSelected(prev => prev.includes(name) ? prev.filter(s => s !== name) : [...prev, name]);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await updateProfile({ preferredCategories: JSON.stringify(selected) });
      toast.success(lang === 'id' ? 'Preferensi kategori disimpan!' : 'Category preferences saved!');
      navigate(-1);
    } catch {
      toast.error(lang === 'id' ? 'Gagal menyimpan' : 'Failed to save');
    }
    setSaving(false);
  };

  const isLoading = loading || profileLoading;

  return (
    <div className="min-h-screen bg-background mutari-main pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">{lang === 'id' ? 'Preferensi Kategori' : 'Category Preferences'}</h1>
        </div>

        {/* Info */}
        <div className="px-4 mt-4">
          <div className="bg-primary/5 border border-primary/20 rounded-2xl p-4 flex items-start gap-3 shadow-sm">
            <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
              <Sparkles className="w-5 h-5 text-primary" />
            </div>
            <div>
              <p className="text-sm font-bold">{lang === 'id' ? 'Personalisasi Rekomendasi' : 'Personalize Recommendations'}</p>
              <p className="text-[10px] text-muted-foreground mt-0.5">
                {lang === 'id'
                  ? 'Pilih kategori yang kamu minati agar rekomendasi barang barter lebih akurat dan relevan untukmu.'
                  : 'Choose categories you are interested in for more accurate and relevant barter recommendations.'}
              </p>
            </div>
          </div>
        </div>

        {/* Category grid */}
        <div className="px-4 mt-4">
          <div className="flex items-center justify-between mb-3">
            <p className="font-bold text-sm">{lang === 'id' ? 'Pilih Kategori' : 'Select Categories'}</p>
            <span className="text-xs text-muted-foreground">{selected.length} {lang === 'id' ? 'dipilih' : 'selected'}</span>
          </div>

          {isLoading ? (
            <div className="grid grid-cols-3 gap-2">
              {[0, 1, 2, 3, 4, 5].map(i => <Skeleton key={i} className="h-20 rounded-xl" />)}
            </div>
          ) : (
            <div className="grid grid-cols-3 gap-2">
              {categories.map(cat => {
                const isSelected = selected.includes(cat.name);
                return (
                  <button
                    key={cat.id}
                    onClick={() => toggle(cat.name)}
                    className={`relative rounded-xl p-3 flex flex-col items-center gap-1.5 text-center transition-all ${
                      isSelected
                        ? 'bg-primary/10 border-2 border-primary ring-1 ring-primary/20'
                        : 'bg-card border border-border hover:bg-muted/50'
                    }`}
                  >
                    {isSelected && (
                      <div className="absolute top-1.5 right-1.5 w-4 h-4 rounded-full bg-primary flex items-center justify-center">
                        <Check className="w-2.5 h-2.5 text-primary-foreground" />
                      </div>
                    )}
                    <span className="text-xl">{cat.icon || '📦'}</span>
                    <span className={`text-[10px] font-semibold leading-tight ${isSelected ? 'text-primary' : 'text-foreground'}`}>{cat.name}</span>
                  </button>
                );
              })}
            </div>
          )}
        </div>

        {/* Selected chips */}
        {selected.length > 0 && (
          <div className="px-4 mt-4">
            <p className="text-xs text-muted-foreground mb-2">{lang === 'id' ? 'Kategori Terpilih:' : 'Selected:'}</p>
            <div className="flex flex-wrap gap-1.5">
              {selected.map(name => {
                const cat = categories.find(c => c.name === name);
                return (
                  <button
                    key={name}
                    onClick={() => toggle(name)}
                    className="flex items-center gap-1 bg-primary/10 text-primary rounded-full px-2.5 py-1 text-[11px] font-medium"
                  >
                    <span>{cat?.icon || '📦'}</span> {name}
                    <span className="text-primary/50 ml-0.5">✕</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        <div className="px-4 mt-6">
          <button onClick={handleSave} disabled={saving} className="w-full py-3.5 rounded-2xl bg-primary text-primary-foreground font-bold text-sm flex items-center justify-center gap-2 disabled:opacity-50">
            {saving && <MutariInline size={16} />}
            {lang === 'id' ? 'Simpan Preferensi' : 'Save Preferences'}
          </button>
        </div>
      </div>
    </div>
  );
}

