import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Eye, EyeOff, Package, MessageCircle, MapPin, Clock, History, Users, Globe, UserCheck, Loader2 } from 'lucide-react';
import { getPrivacySettings, updatePrivacySettings } from 'zitejs/api';
import { toast } from 'sonner';
import { useI18n } from '../context/I18nContext';

type Visibility = 'public' | 'followers' | 'private';
type MsgPrivacy = 'everyone' | 'followers' | 'nobody';

const VIS_OPTIONS: { value: Visibility; labelId: string; labelEn: string; icon: typeof Globe; color: string }[] = [
  { value: 'public', labelId: 'Publik', labelEn: 'Public', icon: Globe, color: 'text-emerald-500' },
  { value: 'followers', labelId: 'Hanya Pengikut', labelEn: 'Followers Only', icon: Users, color: 'text-sky-500' },
];

const MSG_OPTIONS: { value: MsgPrivacy; labelId: string; labelEn: string; icon: typeof Globe; color: string }[] = [
  { value: 'everyone', labelId: 'Semua Orang', labelEn: 'Everyone', icon: Globe, color: 'text-emerald-500' },
  { value: 'followers', labelId: 'Hanya Pengikut', labelEn: 'Followers Only', icon: UserCheck, color: 'text-sky-500' },

];

function OptionPicker<T extends string>({
  options,
  value,
  onChange,
  lang,
}: {
  options: { value: T; labelId: string; labelEn: string; icon: typeof Globe; color: string }[];
  value: T;
  onChange: (v: T) => void;
  lang: string;
}) {
  return (
    <div className="flex gap-2">
      {options.map((opt) => {
        const active = opt.value === value;
        return (
          <button
            key={opt.value}
            onClick={() => onChange(opt.value)}
            className={`flex-1 flex flex-col items-center gap-1.5 py-3 px-2 rounded-xl border transition-all ${
              active
                ? 'border-primary bg-primary/10 shadow-sm'
                : 'border-border bg-card hover:bg-muted/50'
            }`}
          >
            <opt.icon className={`w-5 h-5 ${active ? 'text-primary' : opt.color}`} strokeWidth={1.75} />
            <span className={`text-[11px] font-medium leading-tight text-center ${active ? 'text-primary' : 'text-muted-foreground'}`}>
              {lang === 'id' ? opt.labelId : opt.labelEn}
            </span>
          </button>
        );
      })}
    </div>
  );
}

function ToggleRow({
  icon: Icon,
  label,
  desc,
  checked,
  onChange,
}: {
  icon: typeof Eye;
  label: string;
  desc: string;
  checked: boolean;
  onChange: (v: boolean) => void;
}) {
  return (
    <button
      onClick={() => onChange(!checked)}
      className="w-full flex items-center gap-3 p-3.5 rounded-xl border border-border bg-card hover:bg-muted/30 transition-colors shadow-sm"
    >
      <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
        <Icon className="w-5 h-5 text-primary" strokeWidth={1.75} />
      </div>
      <div className="flex-1 min-w-0 text-left">
        <p className="text-sm font-semibold">{label}</p>
        <p className="text-[10px] text-muted-foreground leading-snug">{desc}</p>
      </div>
      <div className={`w-11 h-6 rounded-full transition-colors flex-shrink-0 flex items-center px-0.5 ${checked ? 'bg-primary' : 'bg-muted'}`}>
        <div className={`w-5 h-5 rounded-full bg-white shadow transition-transform ${checked ? 'translate-x-5' : 'translate-x-0'}`} />
      </div>
    </button>
  );
}

export default function PrivacySettingsPage() {
  const navigate = useNavigate();
  const { lang } = useI18n();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [profileVisibility, setProfileVisibility] = useState<Visibility>('public');
  const [itemsVisibility, setItemsVisibility] = useState<Visibility>('public');
  const [messagingPrivacy, setMessagingPrivacy] = useState<MsgPrivacy>('everyone');
  const [showOnlineStatus, setShowOnlineStatus] = useState(true);
  const [showLocation, setShowLocation] = useState(true);
  const [showBarterHistory, setShowBarterHistory] = useState(true);

  useEffect(() => {
    getPrivacySettings({})
      .then((r) => {
        setProfileVisibility(r.profileVisibility as Visibility);
        setItemsVisibility(r.itemsVisibility as Visibility);
        setMessagingPrivacy(r.messagingPrivacy as MsgPrivacy);
        setShowOnlineStatus(r.showOnlineStatus);
        setShowLocation(r.showLocation);
        setShowBarterHistory(r.showBarterHistory);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const save = async (updates: Record<string, any>) => {
    setSaving(true);
    try {
      await updatePrivacySettings(updates as any);
      toast.success(lang === 'id' ? 'Pengaturan disimpan' : 'Settings saved');
    } catch {
      toast.error(lang === 'id' ? 'Gagal menyimpan' : 'Failed to save');
    } finally {
      setSaving(false);
    }
  };

  const handleVisibility = (key: string, val: string) => {
    if (key === 'profileVisibility') setProfileVisibility(val as Visibility);
    if (key === 'itemsVisibility') setItemsVisibility(val as Visibility);
    if (key === 'messagingPrivacy') setMessagingPrivacy(val as MsgPrivacy);
    save({ [key]: val });
  };

  const handleToggle = (key: string, val: boolean) => {
    if (key === 'showOnlineStatus') setShowOnlineStatus(val);
    if (key === 'showLocation') setShowLocation(val);
    if (key === 'showBarterHistory') setShowBarterHistory(val);
    save({ [key]: val });
  };

  return (
    <div className="min-h-screen bg-background mutari-main pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0">
              <ArrowLeft className="w-4 h-4 text-foreground" />
            </button>
            <h1 className="font-bold text-base text-foreground flex-1">
              {lang === 'id' ? 'Pengaturan Privasi' : 'Privacy Settings'}
            </h1>
            {saving && <Loader2 className="w-4 h-4 text-muted-foreground animate-spin" />}
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-6 h-6 text-primary animate-spin" />
          </div>
        ) : (
          <div className="px-4 mt-4 space-y-6">
            {/* Info banner */}
            <div className="bg-primary/5 border border-primary/20 rounded-2xl p-4 flex items-start gap-3 shadow-sm">
              <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0 mt-0.5">
                <Eye className="w-4 h-4 text-primary" />
              </div>
              <div>
                <p className="text-sm font-semibold text-foreground">
                  {lang === 'id' ? 'Kontrol siapa yang melihat datamu' : 'Control who sees your data'}
                </p>
                <p className="text-[11px] text-muted-foreground mt-0.5 leading-snug">
                  {lang === 'id'
                    ? 'Atur visibilitas profil, barang, dan siapa yang bisa menghubungimu.'
                    : 'Set visibility for your profile, items, and who can contact you.'}
                </p>
              </div>
            </div>

            {/* Profile Visibility */}
            <section>
              <div className="flex items-center gap-2 mb-2.5">
                <Eye className="w-4 h-4 text-primary" />
                <h2 className="font-bold text-sm">
                  {lang === 'id' ? 'Visibilitas Profil' : 'Profile Visibility'}
                </h2>
              </div>
              <p className="text-[11px] text-muted-foreground mb-3">
                {lang === 'id'
                  ? 'Siapa yang bisa melihat profil, bio, dan statistik kamu.'
                  : 'Who can see your profile, bio, and stats.'}
              </p>
              <OptionPicker
                options={VIS_OPTIONS}
                value={profileVisibility}
                onChange={(v) => handleVisibility('profileVisibility', v)}
                lang={lang}
              />
            </section>

            {/* Items Visibility */}
            <section>
              <div className="flex items-center gap-2 mb-2.5">
                <Package className="w-4 h-4 text-primary" />
                <h2 className="font-bold text-sm">
                  {lang === 'id' ? 'Visibilitas Barang' : 'Items Visibility'}
                </h2>
              </div>
              <p className="text-[11px] text-muted-foreground mb-3">
                {lang === 'id'
                  ? 'Siapa yang bisa melihat barang yang kamu tawarkan.'
                  : 'Who can see items you are offering.'}
              </p>
              <OptionPicker
                options={VIS_OPTIONS}
