                <ToggleRow
                  icon={MapPin}
                  label={lang === 'id' ? 'Tampilkan Lokasi' : 'Show Location'}
                  desc={lang === 'id' ? 'Tampilkan kota/daerah di profil dan barang' : 'Show city/area on profile and items'}
                  checked={showLocation}
                  onChange={(v) => handleToggle('showLocation', v)}
                />
                <ToggleRow
                  icon={History}
                  label={lang === 'id' ? 'Tampilkan Riwayat Barter' : 'Show Barter History'}
                  desc={lang === 'id' ? 'Orang lain bisa melihat riwayat barter kamu' : 'Others can see your barter history'}
                  checked={showBarterHistory}
                  onChange={(v) => handleToggle('showBarterHistory', v)}
                />
              </div>
            </section>



            {/* Privacy note */}
            <div className="bg-muted/50 rounded-2xl p-4">
              <div className="flex items-start gap-2">
                <EyeOff className="w-4 h-4 text-muted-foreground mt-0.5 flex-shrink-0" />
                <p className="text-[11px] text-muted-foreground leading-relaxed">
                  {lang === 'id'
                    ? 'Pengaturan privasi berlaku untuk pengguna lain yang melihat profilmu. Pengguna yang terlibat dalam barter aktif tetap bisa melihat informasi yang diperlukan untuk menyelesaikan transaksi.'
                    : 'Privacy settings apply to other users viewing your profile. Users involved in active barters can still see information needed to complete the transaction.'}
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

