function ProfileHeader({ user, initials, points, loading, navigate, lang }: any) {
  return (
    <div className="px-4 pt-5 pb-4">
      <div className="flex items-center gap-3">
        <BadgeAvatar src={user?.image} initials={initials} points={points} size="lg" />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <p className="text-foreground font-bold text-[15px] truncate">{user?.name || (lang === 'id' ? 'Pengguna' : 'User')}</p>
            <button onClick={() => navigate('/edit-profile')} className="w-7 h-7 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
              <Edit className="w-3.5 h-3.5 text-primary" />
            </button>
          </div>
          <p className="text-muted-foreground text-xs truncate">{user?.email}</p>
        </div>
        <div className="flex-shrink-0">
          {loading ? (
            <Skeleton className="h-5 w-24 rounded-full" />
          ) : (
            <BadgeChip points={points} size="md" />
