}

function StatsRow({ itemsUploaded, bartersCompleted, avgRating, loading, lang }: any) {
  const stats = [
    { label: lang === 'id' ? 'Barang' : 'Items', value: loading ? '…' : String(itemsUploaded), icon: Package, color: 'text-sky-500' },
    { label: 'Barter', value: loading ? '…' : String(bartersCompleted), icon: Star, color: 'text-emerald-500' },
    { label: 'Rating', value: avgRating, icon: Heart, color: 'text-pink-500' },
