            <s.icon className={`w-5 h-5 ${s.color}`} strokeWidth={1.75} />
          </div>
          <p className="font-bold text-lg leading-none">{s.value}</p>
          <p className="text-[10px] text-muted-foreground mt-1">{s.label}</p>
        </div>
      ))}
    </div>
  );
}

function WalletCard({ points, progress, next, loading, navigate }: any) {
  return (
    <div className="px-4 py-1">
      <button
        onClick={() => navigate('/wallet')}
        className="w-full bg-card border border-border rounded-2xl p-4 text-left flex items-center gap-3 shadow-sm hover:shadow-md transition-shadow"
      >
        <div className="w-11 h-11 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
          <Wallet className="w-5 h-5 text-primary" strokeWidth={1.75} />
        </div>
        <div className="flex-1 min-w-0">
          <p className="font-bold text-sm text-foreground">Wallet MUTARI</p>
          {loading ? (
            <Skeleton className="h-2.5 w-24 mt-1" />
          ) : (
            <div className="flex items-center gap-2 mt-1">
              <span className="text-xs font-bold text-primary">{points} MP</span>
              <div className="flex-1 bg-primary/10 rounded-full h-1.5 max-w-[80px]">
                <div className="bg-primary rounded-full h-1.5 transition-all duration-500" style={{ width: `${progress.percent}%` }} />
              </div>
              {next && <span className="text-[9px] text-muted-foreground">{next.emoji} {progress.remaining} MP</span>}
