}

function MenuItem({ icon: Icon, label, sub, path, navigate }: any) {
  return (
    <button onClick={() => navigate(path)} className="w-full bg-card border border-border rounded-2xl p-3.5 flex items-center gap-3 text-left shadow-sm hover:shadow-md transition-shadow">
      <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
        <Icon className="w-5 h-5 text-primary" strokeWidth={1.75} />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold">{label}</p>
        <p className="text-[10px] text-muted-foreground">{sub}</p>
      </div>
      <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0" />
    </button>
  );
}

export default function ProfilePage() {
