        { icon: UserPlus, label: lang === 'id' ? 'Program Affiliate' : 'Affiliate Program', sub: lang === 'id' ? 'Ajak teman, naik tier, dapat boost gratis' : 'Invite friends, level up, earn free boosts', path: '/affiliate' },
      ],
    },
    {
      title: lang === 'id' ? 'Aktivitas' : 'Activity',
      items: [
        { icon: Trophy, label: t('profile.achievements'), sub: lang === 'id' ? 'Badge, poin, dan level kamu' : 'Badges, points, and your level', path: '/achievements' },
        { icon: Package, label: t('profile.myItems'), sub: lang === 'id' ? 'Kelola barang yang kamu tawarkan' : 'Manage your listed items', path: '/my-items' },
