import { MutariInline } from '../components/MutariSpinner';
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Copy, Share2, Gift, Users, Coins, CheckCircle2, Clock  } from 'lucide-react';
import { toast } from 'sonner';
import { getReferral, GetReferralOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import { useI18n } from '../context/I18nContext';

type Referral = GetReferralOutputType['referrals'][0];

function StatCard({ icon: Icon, label, value, color }: { icon: typeof Gift; label: string; value: string; color: string }) {
  return (
    <div className="bg-card border border-border rounded-xl p-3 text-center shadow-sm">
      <div className={`w-9 h-9 rounded-full ${color} flex items-center justify-center mx-auto mb-1.5`}>
        <Icon className="w-4 h-4 text-white" />
      </div>
      <p className="font-bold text-lg leading-none">{value}</p>
      <p className="text-[10px] text-muted-foreground mt-0.5">{label}</p>
    </div>
  );
}

function ReferralItem({ r }: { r: Referral }) {
  const initials = (r.referredName?.[0] || 'U').toUpperCase();
  const isCompleted = r.status === 'completed';
  return (
    <div className="flex items-center gap-3 py-3">
      {r.referredImage ? (
        <img src={r.referredImage} alt="" className="w-9 h-9 rounded-full object-cover" />
      ) : (
        <div className="w-9 h-9 rounded-full bg-muted flex items-center justify-center text-xs font-bold">{initials}</div>
      )}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold truncate">{r.referredName}</p>
        <p className="text-[10px] text-muted-foreground">
          {new Date(r.createdAt).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
        </p>
      </div>
      <div className="flex items-center gap-1.5">
        {isCompleted ? (
          <>
            <span className="text-xs font-bold text-emerald-600">+{r.bonusPoints} MP</span>
            <CheckCircle2 className="w-4 h-4 text-emerald-500" />
          </>
        ) : (
          <>
            <span className="text-xs text-muted-foreground">Pending</span>
            <Clock className="w-4 h-4 text-amber-500" />
          </>
        )}
      </div>
    </div>
  );
}

export default function ReferralPage() {
  const navigate = useNavigate();
  const { lang } = useI18n();
  const [data, setData] = useState<GetReferralOutputType | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getReferral({}).then(setData).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const copyCode = () => {
    if (!data) return;
    navigator.clipboard.writeText(data.referralCode);
    toast.success(lang === 'id' ? 'Kode referral disalin!' : 'Referral code copied!');
  };

  const shareLink = () => {
    if (!data) return;
    const referralUrl = `${window.location.origin}?ref=${data.referralCode}`;
    const text = lang === 'id'
      ? `Yuk gabung MUTARI! Tukar barang bekas tanpa uang 🔄♻️\nPakai kode referral saya: ${data.referralCode}\n${referralUrl}`
      : `Join MUTARI! Swap used items without money 🔄♻️\nUse my referral code: ${data.referralCode}\n${referralUrl}`;
    if (navigator.share) {
      navigator.share({ title: 'MUTARI Referral', text, url: referralUrl }).catch(() => {});
    } else {
      navigator.clipboard.writeText(text);
      toast.success(lang === 'id' ? 'Link disalin!' : 'Link copied!');
    }
  };

  return (
    <div className="min-h-screen bg-background mutari-main pb-24 lg:pb-8">
      <div className="max-w-[420px] mx-auto">
        {/* Header */}
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">{lang === 'id' ? 'Ajak Teman' : 'Invite Friends'}</h1>
        </div>

        {loading ? (
          <div className="px-4 mt-4 space-y-4">
            <Skeleton className="h-40 w-full rounded-2xl" />
            <div className="grid grid-cols-3 gap-2">
              {[0, 1, 2].map(i => <Skeleton key={i} className="h-24 rounded-xl" />)}
            </div>
            <Skeleton className="h-32 w-full rounded-2xl" />
          </div>
        ) : data ? (
          <>
            {/* Hero Card */}
            <div className="px-4 mt-4">
              <div className="bg-gradient-to-br from-primary to-primary/80 rounded-2xl p-5 text-center relative overflow-hidden">
                <div className="absolute -right-6 -top-6 w-24 h-24 rounded-full bg-white/5" />
                <div className="absolute -left-4 -bottom-4 w-16 h-16 rounded-full bg-white/5" />
                <div className="relative z-10">
                  <div className="w-14 h-14 rounded-full bg-white/15 flex items-center justify-center mx-auto mb-3">
                    <Gift className="w-7 h-7 text-white" />
                  </div>
                  <h2 className="text-white font-bold text-lg">
                    {lang === 'id' ? 'Ajak Teman, Dapat Poin!' : 'Invite Friends, Get Points!'}
                  </h2>
                  <p className="text-white/70 text-xs mt-1 max-w-[260px] mx-auto">
                    {lang === 'id'
                      ? 'Bagikan kode referral kamu dan dapatkan 50 MUTARI Points setiap teman menyelesaikan barter pertama!'
                      : 'Share your referral code and earn 50 MUTARI Points for each friend who completes their first barter!'}
                  </p>
                </div>
              </div>
            </div>

            {/* Referral Code */}
            <div className="px-4 mt-4">
              <div className="bg-card border-2 border-dashed border-primary/30 rounded-2xl p-4 shadow-sm">
                <p className="text-[10px] text-muted-foreground text-center mb-1.5 font-medium uppercase tracking-wider">
                  {lang === 'id' ? 'Kode Referral Kamu' : 'Your Referral Code'}
                </p>
                <p className="text-center font-bold text-xl tracking-widest text-primary">{data.referralCode}</p>
                <div className="flex gap-2 mt-3">
                  <button onClick={copyCode} className="flex-1 py-2.5 rounded-xl bg-muted text-sm font-semibold flex items-center justify-center gap-2 hover:bg-muted/80 transition-colors">
                    <Copy className="w-4 h-4" /> {lang === 'id' ? 'Salin' : 'Copy'}
                  </button>
                  <button onClick={shareLink} className="flex-1 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold flex items-center justify-center gap-2">
                    <Share2 className="w-4 h-4" /> {lang === 'id' ? 'Bagikan' : 'Share'}
                  </button>
                </div>
              </div>
            </div>

            {/* Stats */}
            <div className="px-4 mt-4 grid grid-cols-3 gap-2">
              <StatCard icon={Users} label={lang === 'id' ? 'Teman Diajak' : 'Invited'} value={String(data.totalReferred)} color="bg-blue-500" />
              <StatCard icon={CheckCircle2} label={lang === 'id' ? 'Selesai' : 'Completed'} value={String(data.completedReferrals)} color="bg-emerald-500" />
              <StatCard icon={Coins} label={lang === 'id' ? 'Bonus Poin' : 'Bonus Points'} value={String(data.totalBonusPoints)} color="bg-amber-500" />
            </div>

            {/* How it works */}
            <div className="px-4 mt-4">
              <h3 className="font-bold text-sm mb-2">{lang === 'id' ? 'Cara Kerja' : 'How It Works'}</h3>
              <div className="bg-card border border-border rounded-2xl p-4 space-y-3 shadow-sm">
                {[
                  { step: '1', text: lang === 'id' ? 'Bagikan kode referral kamu ke teman' : 'Share your referral code with friends' },
                  { step: '2', text: lang === 'id' ? 'Teman mendaftar di MUTARI menggunakan kode kamu' : 'Friend signs up on MUTARI using your code' },
                  { step: '3', text: lang === 'id' ? 'Teman menyelesaikan barter pertamanya' : 'Friend completes their first barter' },
                  { step: '4', text: lang === 'id' ? 'Kamu & teman masing-masing dapat 50 MP!' : 'You & your friend each get 50 MP!' },
                ].map(({ step, text }) => (
                  <div key={step} className="flex items-start gap-3">
                    <div className="w-6 h-6 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xs font-bold flex-shrink-0 mt-0.5">
                      {step}
                    </div>
                    <p className="text-xs text-muted-foreground">{text}</p>
                  </div>
                ))}
              </div>
            </div>

            {/* Referral List */}
            <div className="px-4 mt-4">
