import { useState, useEffect } from 'react';
import { loginWithRedirect } from 'zitejs/auth';
import { ArrowLeft, Mail, ShieldCheck, Recycle, Users, Sparkles, Gift } from 'lucide-react';
import { MutariInline } from '../components/MutariSpinner';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';

const benefits = [
  { icon: Recycle, text: 'Tukar barang tanpa uang' },
  { icon: Users, text: 'Komunitas barter terpercaya' },
  { icon: ShieldCheck, text: 'Verifikasi & keamanan terjamin' },
  { icon: Sparkles, text: 'AI Smart Match otomatis' },
];

export default function RegisterPage({ onBack }: { onBack: () => void }) {
  const [email, setEmail] = useState('');
  const [referralCode, setReferralCode] = useState('');
  const [referralLocked, setReferralLocked] = useState(false);
  const [status, setStatus] = useState<'idle' | 'sending'>('idle');

  // Auto-detect referral code from URL params (?ref=MUTARI-XXXX)
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const ref = params.get('ref') || params.get('referral') || params.get('code') || '';
    if (ref) {
      setReferralCode(ref.toUpperCase());
      setReferralLocked(true);
    } else {
      const stored = localStorage.getItem('mutari-referral-code');
      if (stored) {
        setReferralCode(stored);
        setReferralLocked(true);
      }
    }
  }, []);

  const saveAndRedirect = () => {
    // Save referral code to localStorage so we can use it after auth completes
    if (referralCode.trim()) {
      localStorage.setItem('mutari-referral-code', referralCode.trim().toUpperCase());
    }
    loginWithRedirect();
  };

  const handleGoogleSignup = () => {
    saveAndRedirect();
  };

  const handleEmailSignup = () => {
    if (!email.trim()) return;
    setStatus('sending');
    saveAndRedirect();
  };

  return (
    <div className="min-h-screen bg-background flex flex-col">
      {/* Header */}
      <div className="sticky top-0 z-10 bg-background/80 backdrop-blur-md border-b border-border px-4 py-3 flex items-center gap-3">
