        {/* Logo & Welcome */}
        <div className="flex flex-col items-center mb-8">
          <div className="w-16 h-16 rounded-2xl bg-primary flex items-center justify-center mb-3 shadow-lg">
            <span className="text-primary-foreground font-extrabold text-2xl">M</span>
          </div>
          <h2 className="text-2xl font-bold text-foreground">Bergabung di MUTARI</h2>
          <p className="text-sm text-muted-foreground mt-1 text-center">
            Barang Berputar, Manfaat Berlanjut
          </p>
        </div>

        {/* Referral Code Input */}
        <div className="w-full mb-5">
          <label className="text-sm font-semibold text-foreground mb-1.5 block flex items-center gap-1.5">
            <Gift className="w-4 h-4 text-primary" />
            Punya Kode Affiliate?
            <span className="text-xs font-normal text-muted-foreground">(opsional)</span>
          </label>
          <div className="relative">
            <Input
              type="text"
              placeholder="Contoh: MUTARI-AB12CD34"
              value={referralCode}
              onChange={(e) => { if (!referralLocked) setReferralCode(e.target.value.toUpperCase()); }}
              readOnly={referralLocked}
              className={`h-11 text-sm font-mono tracking-wider uppercase ${referralLocked ? 'bg-muted/50 cursor-not-allowed opacity-75' : ''}`}
            />
            {referralCode && (
              <div className="absolute right-3 top-1/2 -translate-y-1/2">
                {referralLocked
                  ? <span className="text-[10px] bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded font-medium">🔒 Terkunci</span>
