        {/* Info */}
        <p className="text-xs text-muted-foreground text-center mt-4 leading-relaxed">
          Kami akan mengirim <span className="font-medium text-foreground">magic link</span> ke email kamu.
          Klik link tersebut untuk masuk — tanpa perlu password!
        </p>

        {/* Benefits */}
        <div className="w-full mt-8 p-4 rounded-2xl bg-muted/50 border border-border">
          <h3 className="text-sm font-bold text-foreground mb-3">Kenapa MUTARI?</h3>
          <div className="space-y-2.5">
            {benefits.map((b, i) => (
              <div key={i} className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
