import { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Upload, CheckCircle, Clock, AlertTriangle, XCircle, Camera, Flag, Loader2, ShieldAlert, MinusCircle } from 'lucide-react';
import { getServiceBarterDetail, respondServiceBarter, reportViolation } from 'zitejs/api';
import { useUpload } from 'zitejs/upload';
import { useAuth } from 'zitejs/auth';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';
import { id as localeId } from 'date-fns/locale';
import BottomNav from '../components/BottomNav';

const STATUS_CONFIG: Record<string, { color: string; icon: any; label: string }> = {
  Menunggu: { color: 'bg-yellow-100 text-yellow-700 border-yellow-200', icon: Clock, label: 'Menunggu Respon' },
  Diterima: { color: 'bg-blue-100 text-blue-700 border-blue-200', icon: CheckCircle, label: 'Diterima' },
  'Dalam Pengerjaan': { color: 'bg-orange-100 text-orange-700 border-orange-200', icon: Clock, label: 'Dalam Pengerjaan' },
  'Menunggu Bukti': { color: 'bg-purple-100 text-purple-700 border-purple-200', icon: Upload, label: 'Bukti Diupload' },
  Selesai: { color: 'bg-green-100 text-green-700 border-green-200', icon: CheckCircle, label: 'Selesai' },
  Dibatalkan: { color: 'bg-red-100 text-red-700 border-red-200', icon: XCircle, label: 'Dibatalkan' },
  Expired: { color: 'bg-gray-100 text-gray-700 border-gray-200', icon: AlertTriangle, label: 'Expired' },
};

export default function ServiceBarterDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { upload, isUploading } = useUpload();
  const [barter, setBarter] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [acting, setActing] = useState(false);
  const [proofUrls, setProofUrls] = useState<string[]>([]);
  const [showReport, setShowReport] = useState(false);
  const [reportReason, setReportReason] = useState('');
  const [reportDetail, setReportDetail] = useState('');
  const [reportSubmitting, setReportSubmitting] = useState(false);

  const loadBarter = useCallback(async (silent = false) => {
    if (!id) return;
    if (!silent) setLoading(true);
    try {
      const r = await getServiceBarterDetail({ id });
      setBarter(r.barter);
    } catch {
      if (!silent) navigate('/services');
    } finally {
      if (!silent) setLoading(false);
    }
  }, [id, navigate]);

  useEffect(() => { loadBarter(); }, [loadBarter]);

  // Auto-poll every 5s for status changes (e.g. other party uploads proof)
  useEffect(() => {
    if (!id) return;
    const interval = setInterval(() => loadBarter(true), 5000);
    return () => clearInterval(interval);
  }, [id, loadBarter]);

  const handleAction = async (action: 'accept' | 'reject' | 'upload_proof' | 'confirm_complete') => {
    if (!id) return;
    setActing(true);
    try {
      const result = await respondServiceBarter({
        barterId: id,
        action,
        proofUrls: action === 'upload_proof' ? proofUrls : undefined,
      });
      toast.success(result.message);
      await loadBarter(false);
    } catch (err: any) {
      const raw = err?.message || '';
      let msg = 'Gagal memproses';
      try {
        const match = raw.match(/:\s*(\{.*\})\s*$/);
        if (match) {
          const parsed = JSON.parse(match[1]);
          if (parsed?.message) msg = parsed.message;
        }
      } catch { /* ignore */ }
      toast.error(msg);
    } finally {
      setActing(false);
    }
  };

  const handleProofUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    for (const file of Array.from(files).slice(0, 5 - proofUrls.length)) {
      try {
        const { url } = await upload(file);
        setProofUrls(prev => [...prev, url]);
      } catch {
        toast.error('Gagal upload bukti');
      }
    }
  };

  const handleReport = async () => {
    if (!reportReason) return toast.error('Pilih alasan pelaporan');
    setReportSubmitting(true);
    try {
      // Report the other party — if I'm item owner, report provider; vice versa
      const reportedUserId = barter?.isItemOwner ? barter?.providerId : barter?.itemOwnerId;
      await reportViolation({
        userId: reportedUserId || '',
        violationType: reportReason,
        barterId: id,
        notes: reportDetail.trim() || undefined,
      });
      toast.success('Laporan berhasil dikirim. Tim kami akan meninjau.');
      setShowReport(false);
      setReportReason('');
      setReportDetail('');
    } catch (err: any) {
      const raw = err?.message || '';
      let msg = 'Gagal mengirim laporan';
      try {
        const match = raw.match(/:\s*(\{.*\})\s*$/);
        if (match) {
          const parsed = JSON.parse(match[1]);
          if (parsed?.message) msg = parsed.message;
        }
      } catch { /* ignore */ }
      toast.error(msg);
    } finally {
      setReportSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!barter) return null;

  const sc = STATUS_CONFIG[barter.status] || STATUS_CONFIG.Menunggu;
  const StatusIcon = sc.icon;
  const deadlineDate = barter.deadlineAt ? new Date(barter.deadlineAt) : null;
  const isOverdue = deadlineDate && deadlineDate < new Date();

  return (
    <div className="min-h-screen bg-background pb-28 lg:pl-[220px] xl:lg:pl-[240px]">
      <div className="sticky top-0 z-40 bg-primary text-primary-foreground">
        <div className="max-w-[420px] lg:max-w-3xl mx-auto flex items-center gap-3 px-4 py-3">
          <button onClick={() => navigate(-1)} className="p-1 -ml-1"><ArrowLeft className="w-5 h-5" /></button>
          <h1 className="text-lg font-bold flex-1">Detail Barter Jasa</h1>
          {/* Report Flag */}
          <button
            onClick={() => setShowReport(true)}
            className="p-1.5 rounded-full hover:bg-white/15 transition"
            title="Laporkan pelanggaran"
          >
            <Flag className="w-4.5 h-4.5" />
          </button>
        </div>
      </div>

      <div className="max-w-[420px] lg:max-w-3xl mx-auto px-4 mt-4 space-y-4">
        {/* Status Badge */}
        <div className={`flex items-center gap-2 px-4 py-3 rounded-xl border ${sc.color}`}>
          <StatusIcon className="w-5 h-5" />
          <div>
            <p className="text-sm font-bold">{sc.label}</p>
            {deadlineDate && barter.status === 'Dalam Pengerjaan' && (
              <p className="text-xs mt-0.5">
                {isOverdue ? '⚠️ Sudah melewati deadline!' : `Deadline: ${formatDistanceToNow(deadlineDate, { addSuffix: true, locale: localeId })}`}
              </p>
            )}
          </div>
        </div>

        {/* Violation / Rules Info */}
        <div className="p-3 bg-red-50 dark:bg-red-950/20 border border-red-200 dark:border-red-800 rounded-xl">
          <div className="flex items-start gap-2">
            <ShieldAlert className="w-4 h-4 text-red-600 dark:text-red-400 mt-0.5 flex-shrink-0" />
            <div className="text-xs text-red-700 dark:text-red-300 space-y-1">
              <p className="font-semibold">⚠️ Aturan & Sanksi Barter Jasa</p>
              <ul className="space-y-0.5">
                <li>• Jasa <strong>tidak selesai tepat waktu</strong> → deposit <strong>40 MP hangus</strong></li>
                <li>• <strong>Hasil tidak sesuai</strong> perjanjian → <strong>-20 MP</strong> & peringatan</li>
                <li>• <strong>Pembatalan sepihak</strong> setelah diterima → <strong>-30 MP</strong></li>
                <li>• <strong>Bukti palsu / penipuan</strong> → <strong>-50 MP</strong> & potensi <span className="font-bold text-red-600">BAN</span></li>
                <li>• 3x pelanggaran dalam 30 hari → <strong>akun ditangguhkan</strong></li>
              </ul>
              <p className="mt-1 text-red-600 dark:text-red-400 font-medium flex items-center gap-1">
                <Flag className="w-3 h-3" /> Tekan ikon bendera di atas untuk melaporkan pelanggaran
              </p>
            </div>
          </div>
        </div>

        {/* Items */}
        <div className="bg-card rounded-xl border border-border p-4">
          <div className="flex items-center gap-3">
            {/* Item */}
            <div className="flex-1 text-center">
              {barter.item.photo ? (
                <img src={barter.item.photo} alt="" className="w-16 h-16 rounded-lg object-cover mx-auto" />
              ) : (
                <div className="w-16 h-16 rounded-lg bg-muted flex items-center justify-center mx-auto text-2xl">📦</div>
              )}
              <p className="text-xs font-medium text-foreground mt-1 truncate">{barter.item.title}</p>
              <p className="text-[10px] text-muted-foreground">{barter.itemOwnerName}</p>
            </div>

            <div className="text-xl">↔</div>

            {/* Service */}
            <div className="flex-1 text-center">
              {barter.service.photo ? (
                <img src={barter.service.photo} alt="" className="w-16 h-16 rounded-lg object-cover mx-auto" />
              ) : (
                <div className="w-16 h-16 rounded-lg bg-primary/10 flex items-center justify-center mx-auto text-2xl">🛠️</div>
              )}
              <p className="text-xs font-medium text-foreground mt-1 truncate">{barter.service.title}</p>
              <p className="text-[10px] text-muted-foreground">{barter.providerName}</p>
            </div>
          </div>
        </div>

        {/* Deposit Info */}
        <div className="flex items-center gap-2 px-3 py-2 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-xl">
          <MinusCircle className="w-4 h-4 text-amber-600 flex-shrink-0" />
          <span className="text-xs text-amber-700 dark:text-amber-300 font-medium">
            Deposit <strong>40 MP</strong> ditahan — dikembalikan setelah jasa selesai, hangus jika gagal/expired
          </span>
        </div>

        {/* Notes */}
        {barter.notes && (
          <div className="p-3 bg-muted rounded-xl">
            <p className="text-xs font-medium text-muted-foreground mb-1">Catatan:</p>
            <p className="text-sm text-foreground">{barter.notes}</p>
          </div>
        )}

        {/* Proof Photos */}
        {barter.proofPhotos.length > 0 && (
          <div className="bg-card rounded-xl border border-border p-4">
            <p className="text-sm font-semibold text-foreground mb-2">📸 Bukti Penyelesaian</p>
            <div className="flex gap-2 overflow-x-auto">
              {barter.proofPhotos.map((p: any, i: number) => (
                <img key={i} src={p.url} alt="" className="w-24 h-24 rounded-lg object-cover flex-shrink-0" />
              ))}
            </div>
          </div>
        )}

        {/* Provider Actions */}
        {barter.isProvider && barter.status === 'Menunggu' && (
          <div className="space-y-2">
            <button onClick={() => handleAction('accept')} disabled={acting} className="w-full py-3 bg-green-600 text-white rounded-xl font-bold text-sm hover:bg-green-700 transition disabled:opacity-50 flex items-center justify-center gap-2">
              {acting ? <Loader2 className="w-4 h-4 animate-spin" /> : '✅'} Terima Penawaran
            </button>
            <button onClick={() => handleAction('reject')} disabled={acting} className="w-full py-3 bg-red-100 text-red-700 rounded-xl font-bold text-sm hover:bg-red-200 transition disabled:opacity-50 flex items-center justify-center gap-2">
              {acting ? <Loader2 className="w-4 h-4 animate-spin" /> : '❌'} Tolak Penawaran
            </button>
          </div>
        )}

        {/* Provider Upload Proof */}
        {barter.isProvider && barter.status === 'Dalam Pengerjaan' && (
          <div className="bg-card rounded-xl border border-border p-4 space-y-3">
            <p className="text-sm font-semibold text-foreground">📸 Upload Bukti Penyelesaian Jasa</p>
            <p className="text-xs text-muted-foreground">Wajib upload bukti foto/video sebelum bisa menyelesaikan barter.</p>
            <div className="flex gap-2 flex-wrap">
              {proofUrls.map((url, i) => (
                <div key={i} className="relative w-20 h-20 rounded-lg overflow-hidden border border-border">
                  <img src={url} alt="" className="w-full h-full object-cover" />
                  <button onClick={() => setProofUrls(p => p.filter((_, j) => j !== i))} className="absolute top-0.5 right-0.5 w-5 h-5 bg-black/60 rounded-full text-white text-xs flex items-center justify-center">✕</button>
                </div>
              ))}
              {proofUrls.length < 5 && (
                <label className="w-20 h-20 rounded-lg border-2 border-dashed border-border flex flex-col items-center justify-center text-muted-foreground cursor-pointer hover:border-primary/30">
                  <Camera className="w-5 h-5" />
                  <span className="text-[8px] mt-0.5">Bukti</span>
                  <input type="file" accept="image/*,video/*" multiple onChange={handleProofUpload} className="hidden" disabled={isUploading} />
                </label>
              )}
            </div>
            <button
              onClick={() => handleAction('upload_proof')}
              disabled={acting || proofUrls.length === 0}
              className="w-full py-3 bg-primary text-primary-foreground rounded-xl font-bold text-sm disabled:opacity-50 hover:opacity-90 transition flex items-center justify-center gap-2"
            >
              {acting ? <Loader2 className="w-4 h-4 animate-spin" /> : isUploading ? 'Mengupload...' : '📤 Kirim Bukti'}
            </button>
          </div>
        )}

        {/* Item Owner Confirm */}
        {barter.isItemOwner && barter.status === 'Menunggu Bukti' && (
          <div className="space-y-3">
            <div className="p-3 bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800 rounded-xl">
              <p className="text-sm font-semibold text-blue-800 dark:text-blue-200">Penyedia jasa telah upload bukti.</p>
              <p className="text-xs text-blue-700 dark:text-blue-300 mt-1">
                Periksa bukti di atas. Jika jasa sudah selesai sesuai perjanjian, konfirmasi di bawah.
                Jika <strong>tidak sesuai</strong>, tekan ikon 🚩 bendera di atas untuk melaporkan.
              </p>
            </div>
            <button onClick={() => handleAction('confirm_complete')} disabled={acting} className="w-full py-3 bg-green-600 text-white rounded-xl font-bold text-sm hover:bg-green-700 transition disabled:opacity-50 flex items-center justify-center gap-2">
              {acting ? <Loader2 className="w-4 h-4 animate-spin" /> : '✅'} Konfirmasi Selesai (+50 MP & Refund Deposit)
            </button>
            <button onClick={() => setShowReport(true)} className="w-full py-2.5 bg-red-100 text-red-700 rounded-xl font-semibold text-sm hover:bg-red-200 transition flex items-center justify-center gap-2">
              <Flag className="w-4 h-4" /> Laporkan — Jasa Tidak Sesuai
            </button>
          </div>
        )}

        {/* Timeline */}
        <div className="bg-card rounded-xl border border-border p-4">
          <p className="text-sm font-semibold text-foreground mb-3">📅 Timeline</p>
          <div className="space-y-2 text-xs text-muted-foreground">
            <div className="flex justify-between"><span>Dibuat:</span><span>{barter.createdAt ? new Date(barter.createdAt).toLocaleDateString('id-ID') : '-'}</span></div>
            {barter.startedAt && <div className="flex justify-between"><span>Mulai dikerjakan:</span><span>{new Date(barter.startedAt).toLocaleDateString('id-ID')}</span></div>}
            {barter.deadlineAt && <div className="flex justify-between"><span>Deadline:</span><span className={isOverdue ? 'text-red-600 font-bold' : ''}>{new Date(barter.deadlineAt).toLocaleDateString('id-ID')}</span></div>}
            {barter.completedAt && <div className="flex justify-between"><span>Selesai:</span><span className="text-green-600 font-bold">{new Date(barter.completedAt).toLocaleDateString('id-ID')}</span></div>}
          </div>
        </div>
      </div>

      {/* Report Modal — z-[60] to sit above BottomNav */}
      {showReport && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4" onClick={() => setShowReport(false)}>
          <div className="bg-card w-full max-w-[400px] rounded-2xl p-4 space-y-3 max-h-[80vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-2">
              <Flag className="w-4 h-4 text-red-600" />
              <h2 className="text-sm font-bold text-foreground">Laporkan Pelanggaran</h2>
            </div>
            <p className="text-[11px] text-muted-foreground leading-relaxed">
              Laporkan jika pihak lawan melanggar ketentuan barter jasa. Tim MUTARI akan meninjau.
            </p>

            <div className="space-y-1.5">
              <p className="text-sm font-semibold text-foreground">Alasan Pelaporan</p>
              {[
                { val: 'not_delivered', label: '🚫 Jasa tidak dikerjakan', penalty: '-30' },
                { val: 'bad_quality', label: '⚠️ Hasil tidak sesuai', penalty: '-20' },
                { val: 'fake_proof', label: '🚨 Bukti palsu / penipuan', penalty: '-50+BAN' },
                { val: 'late_delivery', label: '⏰ Lewat deadline', penalty: '-20' },
                { val: 'abusive', label: '💬 Komunikasi kasar', penalty: '-10' },
                { val: 'other', label: '📝 Lainnya', penalty: 'Review' },
              ].map(opt => (
                <button
                  key={opt.val}
                  onClick={() => setReportReason(opt.val)}
                  className={`w-full text-left px-3 py-2 rounded-lg border text-xs transition flex items-center gap-2 ${
                    reportReason === opt.val
                      ? 'border-red-400 bg-red-50 dark:bg-red-950/30 text-red-700 dark:text-red-300 ring-1 ring-red-300'
                      : 'border-border bg-card text-foreground hover:border-red-200'
                  }`}
                >
                  <span className="flex-1 leading-snug">{opt.label}</span>
                  <span className="text-[9px] font-bold text-red-600 bg-red-100 dark:bg-red-900/50 px-1.5 py-0.5 rounded-full whitespace-nowrap">{opt.penalty}</span>
                </button>
              ))}
            </div>

            <div>
              <label className="text-xs font-semibold text-foreground">Detail (opsional)</label>
              <textarea
                value={reportDetail}
                onChange={e => setReportDetail(e.target.value)}
                placeholder="Jelaskan kronologi kejadian..."
                rows={2}
                className="mt-1 w-full px-3 py-2 bg-muted rounded-lg text-xs border-none outline-none focus:ring-2 focus:ring-red-300 resize-none"
              />
            </div>

            <div className="flex gap-2">
              <button onClick={() => setShowReport(false)} className="flex-1 py-2 bg-muted text-foreground rounded-lg text-xs font-medium hover:bg-accent transition">
                Batal
              </button>
              <button
                onClick={handleReport}
                disabled={!reportReason || reportSubmitting}
                className="flex-1 py-2 bg-red-600 text-white rounded-lg text-xs font-bold hover:bg-red-700 transition disabled:opacity-50 flex items-center justify-center gap-1.5"
              >
                {reportSubmitting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Flag className="w-3.5 h-3.5" />}
                Kirim Laporan
              </button>
            </div>
          </div>
        </div>
      )}

      <BottomNav />
    </div>
  );
}

