import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, MapPin, Clock, Eye, Heart, Share2, User, Repeat } from 'lucide-react';
import { getServiceDetail } from 'zitejs/api';
import { getBadge } from '../lib/badges';
import BottomNav from '../components/BottomNav';

export default function ServiceDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [service, setService] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activePhoto, setActivePhoto] = useState(0);

  useEffect(() => {
    if (!id) return;
    getServiceDetail({ id }).then(r => setService(r.service)).catch(() => navigate('/services')).finally(() => setLoading(false));
  }, [id]);

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!service) return null;

  const badge = getBadge(service.providerPoints);
  const photos = service.portfolio.length > 0 ? service.portfolio : [{ url: '', name: '' }];
  const hasPhotos = photos[0]?.url;

  return (
    <div className="min-h-screen bg-background pb-24 lg:pl-[220px] xl:lg:pl-[240px]">
      {/* Photo Gallery */}
      <div className="relative">
        {hasPhotos ? (
          <div className="relative aspect-[4/3] max-h-[320px] bg-muted overflow-hidden">
            <img src={photos[activePhoto]?.url} alt="" className="w-full h-full object-cover" />
            {photos.length > 1 && (
              <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1.5">
                {photos.map((_: any, i: number) => (
                  <button key={i} onClick={() => setActivePhoto(i)} className={`w-2 h-2 rounded-full transition ${i === activePhoto ? 'bg-white shadow' : 'bg-white/50'}`} />
                ))}
              </div>
            )}
          </div>
        ) : (
          <div className="aspect-[4/3] max-h-[320px] bg-primary/10 flex items-center justify-center">
            <span className="text-6xl">{service.categoryIcon}</span>
          </div>
        )}
        <button onClick={() => navigate(-1)} className="absolute top-4 left-4 w-9 h-9 bg-black/40 backdrop-blur rounded-full flex items-center justify-center text-white">
          <ArrowLeft className="w-5 h-5" />
        </button>
      </div>

      <div className="max-w-[420px] lg:max-w-3xl mx-auto px-4">
        {/* Category & Title */}
        <div className="mt-4">
          <span className="text-xs px-2 py-1 bg-primary/10 text-primary rounded-full font-medium">
            {service.categoryIcon} {service.categoryName}
          </span>
          <h1 className="text-xl font-bold text-foreground mt-2">{service.title}</h1>
        </div>

        {/* Stats */}
        <div className="flex items-center gap-4 mt-3 text-xs text-muted-foreground">
          {service.completionDays && (
            <span className="flex items-center gap-1"><Clock className="w-3.5 h-3.5" /> {service.completionDays} hari</span>
          )}
          {service.estimatedHours && (
            <span className="flex items-center gap-1"><Clock className="w-3.5 h-3.5" /> ~{service.estimatedHours} jam</span>
          )}
          <span className="flex items-center gap-1"><Eye className="w-3.5 h-3.5" /> {service.viewsCount} views</span>
          {service.location && (
            <span className="flex items-center gap-1"><MapPin className="w-3.5 h-3.5" /> {service.location}</span>
          )}
        </div>

        {/* Description */}
        <div className="mt-4 p-4 bg-card rounded-xl border border-border">
          <h3 className="text-sm font-semibold text-foreground mb-2">Deskripsi Jasa</h3>
          <p className="text-sm text-muted-foreground whitespace-pre-wrap">{service.description}</p>
        </div>

        {/* Desired Items */}
        {service.desiredItems && (
          <div className="mt-3 p-4 bg-card rounded-xl border border-border">
            <h3 className="text-sm font-semibold text-foreground mb-2">🎯 Ingin Ditukar Dengan</h3>
            <p className="text-sm text-muted-foreground">{service.desiredItems}</p>
          </div>
        )}

        {/* Service Rules */}
        <div className="mt-3 p-4 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-xl">
          <h3 className="text-sm font-semibold text-amber-800 dark:text-amber-200 mb-2">📋 Aturan Barter Jasa</h3>
          <ul className="text-xs text-amber-700 dark:text-amber-300 space-y-1.5">
            <li>• Deposit <strong>40 MP</strong> (dikembalikan setelah selesai)</li>
            <li>• Hanya <strong>Barang → Jasa</strong> (tukar barangmu dengan jasa ini)</li>
            <li>• Penyedia jasa wajib upload <strong>bukti foto/video</strong> sebelum selesai</li>
            <li>• Deadline: <strong>{service.completionDays || 7} hari</strong> setelah diterima</li>
            <li>• Deposit hangus jika jasa tidak selesai tepat waktu</li>
          </ul>
        </div>

        {/* Provider Card */}
        <div className="mt-3 p-4 bg-card rounded-xl border border-border">
          <div className="flex items-center gap-3">
            {service.providerImage ? (
              <img src={service.providerImage} alt="" className="w-12 h-12 rounded-full object-cover" />
            ) : (
              <div className="w-12 h-12 rounded-full bg-primary/15 flex items-center justify-center text-lg font-bold text-primary">
                {service.providerName[0]?.toUpperCase()}
              </div>
            )}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold text-foreground">{service.providerName}</p>
              <p className="text-xs text-muted-foreground">{badge.emoji} {badge.name} • {service.providerBarterCount} barter</p>
            </div>
            <button onClick={() => navigate(`/user/${service.providerId}`)} className="text-xs text-primary font-medium">
              Lihat Profil
            </button>
          </div>
        </div>

        {/* Bottom Action Bar — compact so it doesn't cover provider card */}
        <div className="fixed bottom-16 lg:bottom-0 left-0 lg:left-[220px] xl:lg:left-[240px] right-0 bg-card/95 backdrop-blur-md border-t border-border z-40 px-3 py-2">
          <div className="max-w-[420px] lg:max-w-3xl mx-auto">
            <button onClick={() => navigate(`/barter-jasa/${service.id}`)} className="w-full py-2.5 bg-primary text-primary-foreground rounded-lg font-bold text-xs flex items-center justify-center gap-1.5 shadow-sm shadow-primary/20 hover:opacity-90 transition">
              <Repeat className="w-3.5 h-3.5" /> Tukar dengan Jasa Ini
            </button>
          </div>
        </div>
      </div>

      <BottomNav />
    </div>
  );
}

