import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Search, MapPin, Clock, Eye, Star, ChevronRight, Wrench } from 'lucide-react';
import { getServices, getServiceCategories } from 'zitejs/api';
import BottomNav from '../components/BottomNav';

type ServiceItem = {
  id: string;
  title: string;
  description: string;
  portfolio: { url: string }[];
  categoryId: string;
  categoryName: string;
  categoryIcon: string;
  desiredItems: string;
  location: string;
  estimatedHours: number | null;
  completionDays: number | null;
  likesCount: number;
  viewsCount: number;
  providerId: string;
  providerName: string;
  providerImage: string | null;
  createdAt: string | null;
};

type Category = { id: string; name: string; icon: string };

export default function ServicesPage() {
  const navigate = useNavigate();
  const [services, setServices] = useState<ServiceItem[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [activeCat, setActiveCat] = useState<string>('');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getServiceCategories({}).then(r => setCategories(r.categories)).catch(() => {});
  }, []);

  useEffect(() => {
    setLoading(true);
    getServices({ categoryId: activeCat || undefined, search: search || undefined, limit: 50 })
      .then(r => setServices(r.services))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [activeCat, search]);

  return (
    <div className="min-h-screen bg-background pb-24 lg:pl-[220px] xl:lg:pl-[240px]">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-primary text-primary-foreground">
        <div className="max-w-[420px] lg:max-w-3xl mx-auto flex items-center gap-3 px-4 py-3">
          <button onClick={() => navigate(-1)} className="p-1 -ml-1 rounded-full hover:bg-white/10">
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div className="flex-1">
            <h1 className="text-lg font-bold flex items-center gap-2">
              <Wrench className="w-5 h-5" /> Jasa MUTARI
            </h1>
            <p className="text-xs opacity-80">Tukar barangmu dengan jasa</p>
          </div>
          <button
            onClick={() => navigate('/upload-service')}
            className="px-3 py-1.5 bg-white/20 rounded-lg text-xs font-semibold hover:bg-white/30 transition"
          >
            + Tawarkan Jasa
          </button>
        </div>
      </div>

      <div className="max-w-[420px] lg:max-w-3xl mx-auto px-4">
        {/* Info Banner */}
        <div className="mt-4 p-3 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-xl">
          <p className="text-xs text-amber-800 dark:text-amber-200 font-medium">
            🛠️ <strong>Barter Barang → Jasa</strong> — Tukar barangmu dengan jasa dari pengguna lain. Deposit 40 MP (lebih tinggi dari barter barang karena risiko lebih besar). Jasa wajib diselesaikan dalam batas waktu & upload bukti.
          </p>
        </div>

        {/* Search */}
        <div className="mt-4 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            type="text"
            placeholder="Cari jasa..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-muted rounded-xl text-sm border-none outline-none focus:ring-2 focus:ring-primary/30"
          />
        </div>

        {/* Categories */}
        <div className="mt-4 flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
          <button
            onClick={() => setActiveCat('')}
            className={`flex-shrink-0 px-3 py-1.5 rounded-full text-xs font-medium transition ${
              !activeCat ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-accent'
            }`}
          >
            Semua
          </button>
          {categories.map(c => (
            <button
              key={c.id}
              onClick={() => setActiveCat(c.id === activeCat ? '' : c.id)}
              className={`flex-shrink-0 px-3 py-1.5 rounded-full text-xs font-medium transition ${
                activeCat === c.id ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground hover:bg-accent'
              }`}
            >
              {c.icon} {c.name}
            </button>
          ))}
        </div>

        {/* Services List */}
        <div className="mt-4 space-y-3">
          {loading ? (
            Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="bg-card rounded-xl border border-border p-4 animate-pulse">
                <div className="flex gap-3">
                  <div className="w-20 h-20 bg-muted rounded-lg" />
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-muted rounded w-3/4" />
                    <div className="h-3 bg-muted rounded w-1/2" />
                    <div className="h-3 bg-muted rounded w-1/3" />
                  </div>
                </div>
              </div>
            ))
          ) : services.length === 0 ? (
            <div className="text-center py-12">
              <Wrench className="w-12 h-12 text-muted-foreground/30 mx-auto mb-3" />
              <p className="text-sm text-muted-foreground font-medium">Belum ada jasa tersedia</p>
              <p className="text-xs text-muted-foreground mt-1">Jadilah yang pertama menawarkan jasa!</p>
              <button onClick={() => navigate('/upload-service')} className="mt-3 px-4 py-2 bg-primary text-primary-foreground rounded-lg text-sm font-semibold">
                Tawarkan Jasa
              </button>
            </div>
          ) : (
            services.map(s => (
              <ServiceCard key={s.id} service={s} onClick={() => navigate(`/service/${s.id}`)} />
            ))
          )}
        </div>
      </div>

      <BottomNav />
    </div>
  );
}

function ServiceCard({ service: s, onClick }: { service: ServiceItem; onClick: () => void }) {
  const thumb = s.portfolio[0]?.url;
  return (
    <button onClick={onClick} className="w-full bg-card rounded-xl border border-border p-3 flex gap-3 text-left hover:border-primary/30 transition group">
      {thumb ? (
        <img src={thumb} alt="" className="w-20 h-20 rounded-lg object-cover flex-shrink-0" />
      ) : (
        <div className="w-20 h-20 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
          <span className="text-2xl">{s.categoryIcon}</span>
        </div>
      )}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold text-foreground truncate group-hover:text-primary transition">{s.title}</p>
        <p className="text-xs text-muted-foreground mt-0.5 truncate">{s.description}</p>
        <div className="flex items-center gap-2 mt-1.5 flex-wrap">
          <span className="text-[10px] px-1.5 py-0.5 bg-primary/10 text-primary rounded-full font-medium">
            {s.categoryIcon} {s.categoryName}
          </span>
          {s.location && (
            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
              <MapPin className="w-3 h-3" /> {s.location}
            </span>
          )}
        </div>
        <div className="flex items-center gap-3 mt-1.5">
          {s.completionDays && (
            <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
              <Clock className="w-3 h-3" /> {s.completionDays} hari
            </span>
          )}
          <span className="text-[10px] text-muted-foreground flex items-center gap-0.5">
            <Eye className="w-3 h-3" /> {s.viewsCount}
          </span>
        </div>
        <div className="flex items-center gap-2 mt-1.5">
          {s.providerImage ? (
            <img src={s.providerImage} alt="" className="w-4 h-4 rounded-full object-cover" />
          ) : (
            <div className="w-4 h-4 rounded-full bg-primary/20 flex items-center justify-center text-[8px] font-bold text-primary">
              {s.providerName[0]?.toUpperCase()}
            </div>
          )}
          <span className="text-[10px] text-muted-foreground">{s.providerName}</span>
        </div>
      </div>
      <ChevronRight className="w-4 h-4 text-muted-foreground/50 self-center flex-shrink-0" />
    </button>
  );
}

