import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Sparkles, MapPin, CheckCircle, Star, TrendingUp, ChevronRight, Package, Search } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { getSmartMatch, GetSmartMatchOutputType, getMyItems, GetMyItemsOutputType } from 'zitejs/api';
import { Skeleton } from '@project/components/ui/skeleton';
import BottomNav from '../components/BottomNav';
import { useI18n } from '../context/I18nContext';

type MatchType = GetSmartMatchOutputType['matches'][0];
type ItemInfo = NonNullable<GetSmartMatchOutputType['item']>;
type MyItem = GetMyItemsOutputType['items'][0];

const PLACEHOLDER_IMG = 'https://images.fillout.com/793308/exc3bfzedf/generated-images/hsZAVjkb8K1hUmEFnyGrB3/img_6cS1c7v6SyiROUHZ.jpg';

const LOADING_STEPS = [
  'Menganalisis kategori barang...',
  'Menganalisis kondisi barang...',
  'Mengestimasi nilai pasar...',
  'Menganalisis lokasi terdekat...',
  'Memeriksa riwayat transaksi...',
  'Mencari pasangan barter terbaik...',
  'Membandingkan lokasi...',
  'Menyusun rekomendasi...',
];

function ItemPicker({ onSelect }: { onSelect: (id: string) => void }) {
  const navigate = useNavigate();
  const { lang } = useI18n();
  const [items, setItems] = useState<MyItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getMyItems({}).then(res => {
      setItems(res.items.filter(i => i.status === 'Tersedia'));
    }).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const fmt = (v: number | null) => v ? 'Rp' + v.toLocaleString('id-ID') : '';
  const priceRange = (item: MyItem) => {
    const min = fmt(item.estimatedValueMin);
    const max = fmt(item.estimatedValueMax);
    if (min && max && min !== max) return `${min} – ${max}`;
    return min || max || '-';
  };

  return (
    <div className="px-4 py-4">
      {/* Hero info */}
      <div className="text-center mb-6">
        <div className="w-16 h-16 rounded-2xl bg-primary/10 flex items-center justify-center mx-auto mb-3">
          <Search className="w-8 h-8 text-primary" />
        </div>
        <h2 className="font-bold text-lg text-foreground">
          {lang === 'id' ? 'Pilih Barang untuk Smart Match' : 'Pick an Item for Smart Match'}
        </h2>
        <p className="text-sm text-muted-foreground mt-1 max-w-[300px] mx-auto">
          {lang === 'id'
            ? 'AI akan mencarikan pasangan barter terbaik berdasarkan nilai, kondisi, dan lokasi.'
            : 'AI will find the best barter matches based on value, condition, and location.'}
        </p>
      </div>

      {loading ? (
        <div className="space-y-3">
          {[0, 1, 2].map(i => (
            <Skeleton key={i} className="h-20 w-full rounded-2xl" />
          ))}
        </div>
      ) : items.length === 0 ? (
        <div className="text-center py-8">
          <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto mb-3">
            <Package className="w-7 h-7 text-muted-foreground" />
          </div>
          <p className="font-semibold text-sm mb-1">
            {lang === 'id' ? 'Belum ada barang' : 'No items yet'}
          </p>
          <p className="text-xs text-muted-foreground mb-4">
            {lang === 'id'
              ? 'Upload barang dulu untuk mulai Smart Match'
              : 'Upload an item first to start Smart Match'}
          </p>
          <button
            onClick={() => navigate('/upload')}
            className="px-5 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold"
          >
            {lang === 'id' ? 'Upload Barang' : 'Upload Item'}
          </button>
        </div>
      ) : (
        <div className="space-y-2.5">
          {items.map(item => (
            <button
              key={item.id}
              onClick={() => onSelect(item.id)}
              className="w-full bg-card border border-border rounded-2xl p-3 flex items-center gap-3 hover:border-primary/40 hover:shadow-sm transition-all text-left"
            >
              <img
                src={item.photo || PLACEHOLDER_IMG}
                alt={item.title}
                className="w-14 h-14 rounded-xl object-cover flex-shrink-0"
              />
              <div className="flex-1 min-w-0">
                <p className="font-semibold text-sm truncate">{item.title}</p>
                <p className="text-xs text-muted-foreground">{priceRange(item)}</p>
                <div className="flex items-center gap-2 mt-1 text-[10px] text-muted-foreground">
                  <span className="flex items-center gap-0.5">
                    <Star className="w-3 h-3 text-amber-400" /> {item.condition}
                  </span>
                  {item.location && (
                    <span className="flex items-center gap-0.5">
                      <MapPin className="w-3 h-3" /> {item.location}
                    </span>
                  )}
                </div>
              </div>
              <div className="flex-shrink-0 w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                <Sparkles className="w-4 h-4 text-primary" />
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function MatchResults({ itemId }: { itemId: string }) {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [step, setStep] = useState(0);
  const [item, setItem] = useState<ItemInfo | null>(null);
  const [matches, setMatches] = useState<MatchType[]>([]);
  const [dataReady, setDataReady] = useState(false);

  useEffect(() => {
    getSmartMatch({ itemId }).then(res => {
      setItem(res.item);
      setMatches(res.matches);
      setDataReady(true);
    }).catch(() => setDataReady(true));
  }, [itemId]);

  useEffect(() => {
    const interval = setInterval(() => {
      setStep(s => {
        if (s >= LOADING_STEPS.length - 1) { clearInterval(interval); return s; }
        return s + 1;
      });
    }, 500);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (step >= LOADING_STEPS.length - 1 && dataReady) {
      const t = setTimeout(() => setLoading(false), 600);
      return () => clearTimeout(t);
    }
  }, [step, dataReady]);

  return (
    <>
      {/* Item summary */}
      <div className="px-4 pt-4">
        <div className="bg-primary/5 border border-primary/20 rounded-2xl p-3 flex gap-3">
          <img src={item?.img || PLACEHOLDER_IMG} alt={item?.title || ''} className="w-14 h-14 rounded-xl object-cover flex-shrink-0" />
          <div className="flex-1 min-w-0">
            <p className="font-bold text-sm truncate">{item?.title || 'Memuat...'}</p>
            <p className="text-xs text-muted-foreground">{item?.priceRange || '-'}</p>
            <p className="text-[10px] text-primary font-medium mt-0.5">Barang Anda</p>
          </div>
        </div>
      </div>

      <AnimatePresence mode="wait">
        {loading ? (
          <motion.div key="loading" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="px-4 py-10 flex flex-col items-center">
            <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center mb-6">
              <motion.div animate={{ rotate: [0, 10, -10, 0] }} transition={{ repeat: Infinity, duration: 2 }}>
                <Sparkles className="w-10 h-10 text-primary" />
              </motion.div>
            </div>
            <div className="w-full space-y-2">
              {LOADING_STEPS.map((text, i) => (
                <motion.div key={i} initial={{ opacity: 0, x: -20 }} animate={{ opacity: i <= step ? 1 : 0.3, x: 0 }} transition={{ delay: i * 0.1 }} className="flex items-center gap-2">
                  {i < step ? (
                    <CheckCircle className="w-4 h-4 text-primary flex-shrink-0" />
                  ) : i === step ? (
                    <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}>
                      <Sparkles className="w-4 h-4 text-primary flex-shrink-0" />
                    </motion.div>
                  ) : (
                    <div className="w-4 h-4 rounded-full border border-border flex-shrink-0" />
                  )}
                  <span className={`text-xs ${i <= step ? 'text-foreground' : 'text-muted-foreground'}`}>{text}</span>
                </motion.div>
              ))}
            </div>
            <div className="w-full h-1.5 bg-muted rounded-full mt-6 overflow-hidden">
              <motion.div className="h-full bg-primary rounded-full" animate={{ width: `${((step + 1) / LOADING_STEPS.length) * 100}%` }} transition={{ duration: 0.3 }} />
            </div>
          </motion.div>
        ) : (
          <motion.div key="results" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="px-4 py-4">
            {matches.length === 0 ? (
              <div className="text-center py-10">
                <div className="w-16 h-16 rounded-full bg-muted flex items-center justify-center mx-auto mb-4">
                  <Sparkles className="w-8 h-8 text-muted-foreground" />
                </div>
                <p className="font-bold text-base mb-1">Belum Ada Pasangan</p>
                <p className="text-sm text-muted-foreground">AI belum menemukan pasangan barter yang cocok. Coba lagi nanti!</p>
                <button onClick={() => navigate('/smart-match')} className="mt-4 px-5 py-2.5 rounded-xl bg-primary text-primary-foreground text-sm font-semibold">
                  Coba Barang Lain
                </button>
              </div>
            ) : (
              <>
                <div className="flex items-center justify-between mb-3">
                  <p className="font-bold text-base">Pasangan Barter Terbaik</p>
                  <span className="text-xs text-muted-foreground">{matches.length} ditemukan</span>
                </div>
                <div className="space-y-3">
                  {matches.map((match, i) => (
                    <MatchCard key={match.id} rank={i + 1} item={item!} match={match} myItemId={itemId} />
                  ))}
                </div>
                <button onClick={() => navigate('/smart-match')} className="w-full mt-4 py-2.5 rounded-xl border border-border text-sm font-semibold text-muted-foreground hover:bg-muted transition-colors">
                  Coba Barang Lain
                </button>
                <p className="text-center text-[10px] text-muted-foreground mt-4 italic">
                  "Biarkan AI bekerja. Anda tinggal memilih peluang terbaik."
                </p>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

function MatchCard({ rank, item, match, myItemId }: { rank: number; item: ItemInfo; match: MatchType; myItemId: string }) {
  const navigate = useNavigate();
  const [expanded, setExpanded] = useState(rank === 1);

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: rank * 0.1 }} className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
      <div className="p-4">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center">#{rank}</div>
            <span className="text-xs text-muted-foreground">Peringkat {rank}</span>
          </div>
          <div className={`px-3 py-1 rounded-full text-xs font-bold ${match.matchScore >= 80 ? 'bg-primary text-primary-foreground' : 'bg-primary/10 text-primary'}`}>
            {match.matchScore}% Match
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex-1 text-center">
            <img src={item.img || PLACEHOLDER_IMG} alt={item.title} className="w-14 h-14 rounded-xl object-cover mx-auto" />
            <p className="text-[11px] font-semibold mt-1 truncate">{item.title}</p>
            <p className="text-[10px] text-muted-foreground">Barang Anda</p>
          </div>
          <div className="flex flex-col items-center">
            <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
              <TrendingUp className="w-4 h-4 text-primary" />
            </div>
            <div className="w-px h-3 bg-border" />
          </div>
          <div className="flex-1 text-center">
            <img src={match.img || PLACEHOLDER_IMG} alt={match.title} className="w-14 h-14 rounded-xl object-cover mx-auto" />
            <p className="text-[11px] font-semibold mt-1 truncate">{match.title}</p>
            <p className="text-[10px] text-muted-foreground">{match.ownerName}</p>
          </div>
        </div>

        <div className="flex items-center justify-between mt-3 pt-3 border-t border-border text-[10px] text-muted-foreground">
          <span className="flex items-center gap-1"><Star className="w-3 h-3 text-amber-400" /> {match.condition}</span>
          <span className="flex items-center gap-1"><TrendingUp className="w-3 h-3 text-primary" /> {match.priceRange}</span>
          <span className="flex items-center gap-1"><MapPin className="w-3 h-3 text-primary" /> {match.location}</span>
        </div>

        <button onClick={() => setExpanded(!expanded)} className="w-full mt-2 text-xs text-primary font-semibold flex items-center justify-center gap-1">
          {expanded ? 'Sembunyikan' : 'Lihat Alasan AI'}
          <ChevronRight className={`w-3 h-3 transition-transform ${expanded ? 'rotate-90' : ''}`} />
        </button>
