const MONTH_NAMES: Record<string, string> = {
  '01': 'Jan', '02': 'Feb', '03': 'Mar', '04': 'Apr', '05': 'Mei', '06': 'Jun',
  '07': 'Jul', '08': 'Ags', '09': 'Sep', '10': 'Okt', '11': 'Nov', '12': 'Des',
};

export default function StatsPage() {
  const navigate = useNavigate();
  const { lang } = useI18n();
  const [data, setData] = useState<GetUserStatsOutputType | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getUserStats({}).then(setData).catch(() => {}).finally(() => setLoading(false));
  }, []);

  const chartData = (data?.bartersByMonth || []).map(d => ({
    name: MONTH_NAMES[d.month.split('-')[1]] || d.month,
    value: d.count,
  }));

  // Fill in missing months for last 6
  const now = new Date();
  const filledChart: { name: string; value: number }[] = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    const monthLabel = MONTH_NAMES[String(d.getMonth() + 1).padStart(2, '0')] || key;
    const found = data?.bartersByMonth.find(b => b.month === key);
    filledChart.push({ name: monthLabel, value: found?.count || 0 });
  }

  const maxCatCount = data?.topCategories?.[0]?.count || 1;

  return (
    <div className="min-h-screen bg-background mutari-main pb-10">
      <div className="max-w-[420px] mx-auto">
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
            <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0"><ArrowLeft className="w-4 h-4 text-foreground" /></button>
            <h1 className="font-bold text-base text-foreground flex-1">{lang === 'id' ? 'Statistik Lengkap' : 'Detailed Stats'}</h1>
        </div>

        {loading ? (
          <div className="px-4 mt-4 space-y-4">
            <div className="grid grid-cols-2 gap-2">
              {[0, 1, 2, 3].map(i => <Skeleton key={i} className="h-24 rounded-xl" />)}
            </div>
            <Skeleton className="h-48 rounded-2xl" />
            <Skeleton className="h-32 rounded-2xl" />
          </div>
        ) : data ? (
          <>
            {/* Quick stats grid */}
            <div className="px-4 mt-4 grid grid-cols-2 gap-2">
              <StatBox icon={Package} label={lang === 'id' ? 'Total Barang' : 'Total Items'} value={String(data.totalItems)} color="bg-sky-500" />
              <StatBox icon={TrendingUp} label={lang === 'id' ? 'Total Barter' : 'Total Barters'} value={String(data.totalBarters)} color="bg-emerald-500" />
              <StatBox icon={Eye} label={lang === 'id' ? 'Total Dilihat' : 'Total Views'} value={data.totalViews.toLocaleString('id-ID')} color="bg-violet-500" />
              <StatBox icon={Heart} label={lang === 'id' ? 'Total Like' : 'Total Likes'} value={data.totalLikes.toLocaleString('id-ID')} color="bg-pink-500" />
            </div>

            {/* Performance metrics */}
            <div className="px-4 mt-3 grid grid-cols-3 gap-2">
              <div className="bg-card border border-border rounded-xl p-3 text-center shadow-sm">
                <div className="relative w-12 h-12 mx-auto mb-1">
                  <svg className="w-12 h-12 -rotate-90" viewBox="0 0 36 36">
                    <circle cx="18" cy="18" r="14" fill="none" stroke="currentColor" strokeWidth="3" className="text-muted" />
                    <circle cx="18" cy="18" r="14" fill="none" stroke="currentColor" strokeWidth="3" className="text-emerald-500" strokeDasharray={`${data.completionRate * 0.88} 88`} strokeLinecap="round" />
                  </svg>
                  <span className="absolute inset-0 flex items-center justify-center text-[10px] font-bold">{data.completionRate}%</span>
                </div>
                <p className="text-[9px] text-muted-foreground">{lang === 'id' ? 'Selesai' : 'Completion'}</p>
              </div>
              <div className="bg-card border border-border rounded-xl p-3 text-center shadow-sm">
                <div className="relative w-12 h-12 mx-auto mb-1">
                  <svg className="w-12 h-12 -rotate-90" viewBox="0 0 36 36">
                    <circle cx="18" cy="18" r="14" fill="none" stroke="currentColor" strokeWidth="3" className="text-muted" />
                    <circle cx="18" cy="18" r="14" fill="none" stroke="currentColor" strokeWidth="3" className="text-blue-500" strokeDasharray={`${data.responseRate * 0.88} 88`} strokeLinecap="round" />
                  </svg>
                  <span className="absolute inset-0 flex items-center justify-center text-[10px] font-bold">{data.responseRate}%</span>
                </div>
                <p className="text-[9px] text-muted-foreground">{lang === 'id' ? 'Response' : 'Response'}</p>
              </div>
              <div className="bg-card border border-border rounded-xl p-3 text-center shadow-sm">
                <div className="flex items-center justify-center h-12 mb-1">
