                      <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                        {filledChart.map((_, i) => (
                          <Cell key={i} fill={i === filledChart.length - 1 ? 'hsl(var(--primary))' : 'hsl(var(--primary) / 0.3)'} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                )}
              </div>
            </div>

            {/* Top categories */}
            <div className="px-4 mt-4">
              <div className="bg-card border border-border rounded-2xl p-4 shadow-sm">
                <div className="flex items-center gap-2 mb-3">
                  <Package className="w-4 h-4 text-primary" />
                  <p className="font-bold text-sm">{lang === 'id' ? 'Kategori Paling Sering' : 'Top Categories'}</p>
                </div>
                {data.topCategories.length === 0 ? (
                  <p className="text-xs text-muted-foreground text-center py-4">{lang === 'id' ? 'Belum ada data' : 'No data yet'}</p>
                ) : (
                  <div className="space-y-2.5">
                    {data.topCategories.map((cat, i) => (
                      <div key={cat.category}>
                        <div className="flex items-center justify-between mb-1">
