                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="px-4 mt-8 text-center">
            <p className="text-muted-foreground text-sm">{lang === 'id' ? 'Gagal memuat statistik' : 'Failed to load stats'}</p>
          </div>
        )}
      </div>
    </div>
  );
}

