import { useState, useEffect, useCallback } from 'react';
import { useNavigate, useParams, useLocation } from 'react-router-dom';
import { X, Eye, Repeat2 } from 'lucide-react';
import { viewStory } from 'zitejs/api';
import { formatDistanceToNow } from 'date-fns';
import { id as idLocale } from 'date-fns/locale';

interface StoryData {
  id: string;
  caption: string;
  mediaUrl: string | null;
  authorId: string;
  authorName: string;
  authorImage: string | null;
  type: string;
  location: string | null;
  viewsCount: number;
  createdAt: string;
}

const TYPE_LABELS: Record<string, string> = {
  barter_baru: '🆕 Barter Baru',
  dicari: '🔍 Dicari',
  promo: '🏷️ Promo',
  showcase: '✨ Showcase',
};

export default function StoryViewerPage() {
  const navigate = useNavigate();
  const { authorId } = useParams<{ authorId: string }>();
  const location = useLocation();
  const passedStories = (location.state as any)?.stories as StoryData[] | undefined;

  const [stories, setStories] = useState<StoryData[]>(passedStories || []);
  const [current, setCurrent] = useState(0);
  const [progress, setProgress] = useState(0);
  const [paused, setPaused] = useState(false);

  const story = stories[current];
  const DURATION = 5000; // 5 seconds per story

  // Track view
  useEffect(() => {
    if (story?.id) {
      viewStory({ storyId: story.id }).catch(() => {});
    }
  }, [story?.id]);

  // Auto-advance timer
  useEffect(() => {
    if (paused || !story) return;
    const interval = 50;
    let elapsed = 0;
    const timer = setInterval(() => {
      elapsed += interval;
      setProgress((elapsed / DURATION) * 100);
      if (elapsed >= DURATION) {
        clearInterval(timer);
        goNext();
      }
    }, interval);
    return () => clearInterval(timer);
  }, [current, paused, story]);

  const goNext = useCallback(() => {
    if (current < stories.length - 1) {
      setCurrent(c => c + 1);
      setProgress(0);
    } else {
      navigate(-1);
    }
  }, [current, stories.length, navigate]);

  const goPrev = useCallback(() => {
    if (current > 0) {
      setCurrent(c => c - 1);
      setProgress(0);
    }
  }, [current]);

  // Tap zones: left = prev, right = next
  const handleTap = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    if (x < rect.width / 3) goPrev();
    else goNext();
  };

  if (!story) {
    return (
      <div className="min-h-screen bg-black mutari-main flex items-center justify-center text-white">
        <p>Tidak ada story</p>
      </div>
    );
  }

  const timeAgo = formatDistanceToNow(new Date(story.createdAt), { addSuffix: true, locale: idLocale });

  return (
    <div className="fixed inset-0 bg-black z-50 flex items-center justify-center">
      <div className="max-w-[420px] w-full h-full relative flex flex-col">
        {/* Progress bars */}
        <div className="absolute top-0 inset-x-0 z-30 bg-gradient-to-b from-black/60 to-transparent pb-16 pt-2 px-3">
          <div className="flex gap-1">
            {stories.map((_, i) => (
              <div key={i} className="flex-1 h-[2px] rounded-full bg-white/30 overflow-hidden">
                <div
                  className="h-full bg-white rounded-full transition-all duration-75"
                  style={{
                    width: i < current ? '100%' : i === current ? `${progress}%` : '0%',
                  }}
                />
              </div>
            ))}
          </div>

          {/* Header — Instagram style */}
          <div className="mt-3 flex items-center gap-3">
            <div className="flex items-center gap-2.5 flex-1 min-w-0">
              <div className="w-8 h-8 rounded-full overflow-hidden ring-2 ring-white/50 flex-shrink-0 bg-muted">
                {story.authorImage ? (
                  <img src={story.authorImage} alt="" className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full bg-gradient-to-br from-emerald-500 to-emerald-700 flex items-center justify-center text-white font-bold text-xs">
                    {story.authorName[0]?.toUpperCase()}
                  </div>
                )}
              </div>
              <div className="min-w-0 flex items-center gap-2">
                <p className="text-white text-[13px] font-semibold truncate">{story.authorName}</p>
                <span className="text-white/60 text-[11px] flex-shrink-0">{timeAgo}</span>
              </div>
            </div>
            <button onClick={() => navigate(-1)} className="p-1">
              <X className="w-6 h-6 text-white" />
            </button>
          </div>
        </div>

        {/* Media */}
        <div className="flex-1 relative" onClick={handleTap} onMouseDown={() => setPaused(true)} onMouseUp={() => setPaused(false)} onTouchStart={() => setPaused(true)} onTouchEnd={() => setPaused(false)}>
          {story.mediaUrl ? (
            <img src={story.mediaUrl} alt="" className="w-full h-full object-cover" />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-primary/40 to-primary/10 flex items-center justify-center">
              <p className="text-white/60 text-lg">📸</p>
            </div>
          )}

          {/* Caption overlay */}
          <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black/80 via-black/30 to-transparent px-5 pb-8 pt-20">
            <div className="flex items-center gap-2 mb-2">
              <span className="inline-block px-2.5 py-1 rounded-full bg-white/15 backdrop-blur text-[10px] font-semibold text-white">
                {TYPE_LABELS[story.type] || story.type}
              </span>
              {story.location && (
                <span className="text-white/60 text-[10px] truncate">📍 {story.location}</span>
              )}
              <span className="flex items-center gap-1 text-white/40 text-[10px] ml-auto">
                <Eye className="w-3 h-3" /> {story.viewsCount}
              </span>
            </div>
            {story.caption && (
              <p className="text-white text-sm font-medium leading-relaxed">{story.caption}</p>
            )}
            {/* Ajak Barter button */}
            <button
              onClick={(e) => {
                e.stopPropagation();
                navigate(`/user/${story.authorId}`);
              }}
              className="mt-3 flex items-center gap-1.5 px-4 py-2 rounded-full bg-white/20 backdrop-blur-sm border border-white/20 text-white text-xs font-semibold active:scale-95 transition-transform"
            >
              <Repeat2 className="w-3.5 h-3.5" />
              Ajak Barter
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

