    }
    setAiLoading(false);
  };

  const handlePhotoAdd = async (files: File[]) => {
    let firstNewUrl = '';
    const currentCount = photos.length;
    for (const file of files.slice(0, 10 - currentCount)) {
      try {
        const { url } = await upload(file);
        setPhotos(p => [...p, { url }]);
        if (!firstNewUrl) firstNewUrl = url;
      } catch {
        toast.error(lang === 'id' ? 'Gagal upload foto' : 'Failed to upload photo');
      }
    }
    // Auto-trigger AI analysis on first photo upload (or if no result yet)
    if (firstNewUrl && !aiResult) {
      runAiCheck(firstNewUrl);
    }
  };

  const handleSubmit = async (asDraft: boolean) => {
    if (!valid && !asDraft) return;
    setSubmitting(true);
    try {
      const specStr = specs.filter(s => s.label && s.value).map(s => `${s.label}: ${s.value}`).join('\n');
      const result = await uploadItem({
        title: nama,
        kategori,
        kondisi,
        kelengkapan: kelengkapan.join(', '),
        spesifikasi: specStr,
        kekurangan,
        inginDitukar,
        tambahan,
        deskripsi,
        lokasi,
        photos: photos.map(p => p.url),
