        <button
          type="button"
          onClick={handleAiCheck}
          disabled={aiLoading || photos.length === 0}
          className="w-full flex items-center justify-center gap-2 py-3 rounded-xl font-semibold text-sm border-2 border-primary text-primary bg-primary/5 hover:bg-primary/10 disabled:opacity-50 transition-colors"
        >
          {aiLoading ? (
            <>
              <MutariInline size={16} />
