          ) : (
            <>
              <ScanSearch className="w-4 h-4" />
              Cek dengan AI Mikro
            </>
          )}
        </button>

        {/* Hasil Cek AI */}
        {aiResult && (
          <div className="space-y-4">
            {/* Analisis */}
            <div className="bg-primary/5 border border-primary/30 rounded-xl p-4">
              <div className="flex items-center gap-2 mb-2">
                <Sparkles className="w-4 h-4 text-primary" />
                <p className="text-sm font-bold text-primary">Hasil Cek AI</p>
              </div>
              <p className="text-sm text-foreground whitespace-pre-wrap leading-relaxed">{aiResult.analysis}</p>
            </div>

            {/* Kisaran Harga */}
            {aiResult.estimatedMinPrice > 0 && (
              <div className="bg-accent/60 border border-border rounded-xl p-4">
                <p className="text-xs font-semibold text-muted-foreground mb-1">Kisaran Harga AI</p>
                <p className="text-lg font-bold text-foreground">
                  Rp {aiResult.estimatedMinPrice.toLocaleString('id-ID')} — Rp {aiResult.estimatedMaxPrice.toLocaleString('id-ID')}
