                          </p>
                        </div>
                        <span className="text-[10px] bg-green-500/10 text-green-600 px-2 py-1 rounded-full font-semibold flex-shrink-0">
                          Match
                        </span>
                      </div>
                      <div className="px-3 pb-3">
                        <button
                          type="button"
                          onClick={() => navigate(`/item/${m.id}`)}
                          className="w-full flex items-center justify-center gap-2 py-2.5 rounded-lg bg-primary text-primary-foreground font-semibold text-sm active:scale-[0.98] transition-transform"
                        >
                          <ArrowRightLeft className="w-4 h-4" />
