                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ) : aiResult.estimatedMinPrice > 0 ? (
              <div className="text-center py-5 bg-amber-50 dark:bg-amber-900/10 rounded-xl border border-amber-200 dark:border-amber-800/30">
                <div className="w-12 h-12 mx-auto rounded-full bg-amber-100 dark:bg-amber-900/30 flex items-center justify-center mb-2">
                  <ArrowRightLeft className="w-6 h-6 text-amber-500" />
                </div>
                <p className="text-sm font-bold text-foreground mb-1">Tidak Ada Pasangan yang Sepadan</p>
                <p className="text-xs text-muted-foreground max-w-[260px] mx-auto leading-relaxed">
                  Belum ada barang lain yang setara nilainya untuk ditukar. Pasangan barter akan muncul ketika ada barang lain dengan nilai yang cocok.
                </p>
              </div>
            ) : null}
          </div>
        )}

        {/* Nama Barang */}
        <Field label="Nama Barang" required>
          <input
            value={nama}
            onChange={e => setNama(e.target.value)}
            placeholder="Contoh: iPhone 13 Pro Max"
            className="form-input"
          />
        </Field>

        {/* Kategori */}
        <Field label="Kategori" required>
          <div className="relative">
            <select value={kategori} onChange={e => setKategori(e.target.value)} className="form-input appearance-none pr-10">
              <option value="">Pilih kategori</option>
              {KATEGORI.map(k => <option key={k} value={k}>{k}</option>)}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-muted-foreground"><path d="M6 9l6 6 6-6"/></svg>
