                <p className="font-bold text-foreground text-lg">
                  Rp {aiResult.estimatedMinPrice.toLocaleString('id-ID')} — Rp {aiResult.estimatedMaxPrice.toLocaleString('id-ID')}
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  Dihitung otomatis oleh Mutari AI dari foto barang kamu.
                </p>
              </>
            ) : aiResult ? (
              <>
                <p className="font-bold text-foreground">Tidak terdeteksi</p>
                <p className="text-xs text-muted-foreground mt-1">
                  AI tidak dapat memperkirakan harga. Coba upload foto yang lebih jelas.
                </p>
              </>
            ) : (
              <>
                <p className="font-bold text-foreground">Upload foto untuk memulai</p>
                <p className="text-xs text-muted-foreground mt-1">
                  Dihitung otomatis oleh Mutari AI setelah kamu upload foto barang.
                </p>
              </>
            )}
          </div>
        </div>

        {/* Match Alert Tips */}
        <div className="rounded-xl bg-amber-500/10 border border-amber-500/20 p-3">
          <p className="text-xs font-bold text-amber-700 dark:text-amber-400 flex items-center gap-1.5 mb-1.5">
            🎯 Tips Match Alert Cerdas
          </p>
          <p className="text-[11px] text-amber-700/80 dark:text-amber-400/80 leading-relaxed">
            Sistem kami otomatis mencocokkan barang kamu dengan pengguna lain. Kalau ada yang <strong>punya barang yang kamu cari</strong> dan mereka juga <strong>butuh barang yang kamu punya</strong>, kalian berdua langsung dapat notifikasi!
          </p>
          <p className="text-[11px] text-amber-700/80 dark:text-amber-400/80 leading-relaxed mt-1">
            ✍️ Isi kolom <strong>"Ingin Ditukar Dengan"</strong> di bawah dengan spesifik (contoh: "iPhone 13, Samsung S22") supaya match lebih akurat.
          </p>
        </div>

        {/* Ingin Ditukar Dengan */}
        <Field label="Ingin Ditukar Dengan">
          <input
            value={inginDitukar}
            onChange={e => setInginDitukar(e.target.value)}
            placeholder="Pisahkan dengan koma, mis: Laptop, Kamera"
            className="form-input"
          />
        </Field>

        {/* Tambahan yang Diinginkan */}
        <Field label="Tambahan yang Diinginkan">
          <input
            value={tambahan}
            onChange={e => setTambahan(e.target.value)}
            placeholder="Contoh: tambah uang Rp500.000 / aksesori"
            className="form-input"
          />
        </Field>

        {/* Deskripsi Lengkap */}
        <Field label="Deskripsi Lengkap" required>
          <textarea
            value={deskripsi}
            onChange={e => setDeskripsi(e.target.value)}
            placeholder="Jelaskan detail barang Anda..."
            rows={5}
            className="form-input resize-none"
          />
          <p className={`text-xs mt-1 ${deskripsi.length < 10 ? 'text-destructive' : 'text-muted-foreground'}`}>
            Wajib diisi, minimal 10 karakter ({deskripsi.length}/10)
          </p>
          <div className="flex items-start gap-2 mt-2 bg-blue-50 border border-blue-200 rounded-lg px-3 py-2">
            <span className="text-blue-500 mt-0.5 text-sm">🛡️</span>
            <p className="text-[11px] text-blue-700 leading-snug">
              <strong>Asuransi Barter:</strong> Kedua pihak akan menaruh deposit 50 MP saat barter diterima. Jika salah satu pihak melanggar perjanjian (barang tidak sesuai deskripsi), 50 MP mereka akan dikurangi dan diberikan sebagai kompensasi ke pihak lain.
            </p>
          </div>
        </Field>

        {/* Lokasi (auto GPS) */}
        <LocationAuto value={lokasi} onChange={setLokasi} loading={lokasiLoading} onLoadingChange={setLokasiLoading} />
      </div>

      {/* Bottom bar */}
      <div className="fixed bottom-0 left-0 right-0 bg-card border-t border-border p-4 flex gap-3 z-30 max-w-[500px] mx-auto">
        <button
          onClick={() => handleSubmit(true)}
          disabled={submitting}
          className="flex-1 py-3.5 rounded-xl border border-border font-semibold text-foreground bg-card"
        >
          Simpan Draft
        </button>
        <button
          onClick={() => handleSubmit(false)}
          disabled={!valid || submitting}
          className="flex-1 py-3.5 rounded-xl font-semibold text-primary-foreground bg-primary disabled:opacity-50"
        >
          {submitting ? 'Menyimpan...' : 'Publish'}
        </button>
      </div>
    </div>
  );
}

function Field({ label, required, children }: { label: string; required?: boolean; children: React.ReactNode }) {
  return (
    <div>
      <p className="text-sm font-semibold text-foreground mb-2">
        {label} {required && <span className="text-destructive">*</span>}
      </p>
      {children}
    </div>
  );
}

