import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Camera, MapPin, Clock, Info, Sparkles, X, Loader2 } from 'lucide-react';
import { uploadService, getServiceCategories, getProfile } from 'zitejs/api';
import { useUpload } from 'zitejs/upload';
import { useLocation as useMutariLocation } from '../context/LocationContext';
import { toast } from 'sonner';
import BottomNav from '../components/BottomNav';

type Category = { id: string; name: string; icon: string };

const COMPLETION_OPTIONS = [
  { value: 1, label: '1 hari' },
  { value: 2, label: '2 hari' },
  { value: 3, label: '3 hari' },
  { value: 5, label: '5 hari' },
  { value: 7, label: '7 hari' },
  { value: 10, label: '10 hari' },
  { value: 14, label: '14 hari' },
  { value: 21, label: '21 hari' },
  { value: 30, label: '30 hari' },
];

const HOURS_OPTIONS = [
  { value: 1, label: '~1 jam' },
  { value: 2, label: '~2 jam' },
  { value: 3, label: '~3 jam' },
  { value: 5, label: '~5 jam' },
  { value: 8, label: '~8 jam' },
  { value: 10, label: '~10 jam' },
  { value: 16, label: '~16 jam' },
  { value: 24, label: '~24 jam' },
  { value: 40, label: '~40 jam' },
];

export default function UploadServicePage() {
  const navigate = useNavigate();
  const { upload, isUploading } = useUpload();
  const loc = useMutariLocation();
  const [categories, setCategories] = useState<Category[]>([]);
  const [catLoading, setCatLoading] = useState(true);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [categoryId, setCategoryId] = useState('');
  const [desiredItems, setDesiredItems] = useState('');
  const [completionDays, setCompletionDays] = useState(7);
  const [estimatedHours, setEstimatedHours] = useState<number | null>(null);
  const [photos, setPhotos] = useState<string[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [profileCity, setProfileCity] = useState('');

  useEffect(() => {
    setCatLoading(true);
    getServiceCategories({}).then(r => setCategories(r.categories)).catch(() => {}).finally(() => setCatLoading(false));
    // Fetch profile location from account
    getProfile({}).then(p => {
      const city = [p.city, p.province].filter(Boolean).join(', ');
      if (city) setProfileCity(city);
    }).catch(() => {});
  }, []);

  // Derived location: prefer profile city, fallback to GPS
  const displayLocation = profileCity || loc.location?.kabupaten || '';
  const locationForSubmit = profileCity || loc.location?.kabupaten || undefined;

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    for (const file of Array.from(files).slice(0, 5 - photos.length)) {
      try {
        const { url } = await upload(file);
        setPhotos(prev => [...prev, url]);
      } catch {
        toast.error('Gagal upload foto');
      }
    }
  };

  const canSubmit = title.trim().length >= 3 && description.trim().length >= 10 && !!categoryId;

  const handleSubmit = async () => {
    if (!title.trim() || title.trim().length < 3) {
      toast.error('Judul jasa minimal 3 karakter');
      return;
    }
    if (!description.trim() || description.trim().length < 10) {
      toast.error('Deskripsi minimal 10 karakter');
      return;
    }
    if (!categoryId) {
      toast.error('Pilih kategori jasa');
      return;
    }

    setSubmitting(true);
    try {
      await uploadService({
        title: title.trim(),
        description: description.trim(),
        categoryId,
        desiredItems: desiredItems.trim() || undefined,
        completionDays: completionDays || 7,
        estimatedHours: estimatedHours ?? undefined,
        location: locationForSubmit,
        latitude: loc.location?.lat || undefined,
        longitude: loc.location?.lng || undefined,
        portfolio: photos.length > 0 ? photos : undefined,
      });
      toast.success('Jasa berhasil ditawarkan! 🛠️');
      navigate('/services');
    } catch (err: any) {
      const raw = err?.message || '';
      let msg = 'Gagal upload jasa';
      try {
        const match = raw.match(/:\s*(\{.*\})\s*$/);
        if (match) {
          const parsed = JSON.parse(match[1]);
          if (parsed?.message) msg = parsed.message;
        }
      } catch { /* ignore */ }
      toast.error(msg);
    } finally {
      setSubmitting(false);
    }
  };

  const descLen = description.length;

  return (
    <div className="min-h-screen bg-background pb-24 lg:pl-[220px] xl:lg:pl-[240px]">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-primary text-primary-foreground">
        <div className="max-w-[420px] lg:max-w-3xl mx-auto flex items-center gap-3 px-4 py-3">
          <button onClick={() => navigate(-1)} className="p-1 -ml-1"><ArrowLeft className="w-5 h-5" /></button>
          <h1 className="text-lg font-bold">Tawarkan Jasa</h1>
        </div>
      </div>

      <div className="max-w-[420px] lg:max-w-3xl mx-auto px-4 mt-4 space-y-5">
        {/* Info */}
        <div className="p-3 bg-blue-50 dark:bg-blue-950/30 border border-blue-200 dark:border-blue-800 rounded-xl flex gap-2">
          <Info className="w-4 h-4 text-blue-600 dark:text-blue-400 mt-0.5 flex-shrink-0" />
          <p className="text-xs text-blue-700 dark:text-blue-300">
            Tawarkan jasamu dan dapatkan barang dari pengguna lain. Orang lain akan menukarkan barang mereka untuk jasamu.
          </p>
        </div>

        {/* Portfolio Photos */}
        <div>
          <label className="text-sm font-semibold text-foreground">Portofolio / Contoh Hasil <span className="text-muted-foreground font-normal">(opsional, maks 5)</span></label>
          <div className="flex gap-2 mt-2 flex-wrap">
            {photos.map((url, i) => (
              <div key={i} className="relative w-20 h-20 rounded-lg overflow-hidden border border-border group">
                <img src={url} alt="" className="w-full h-full object-cover" />
                <button onClick={() => setPhotos(p => p.filter((_, j) => j !== i))} className="absolute top-0.5 right-0.5 w-5 h-5 bg-black/60 rounded-full text-white flex items-center justify-center opacity-80 group-hover:opacity-100 transition">
                  <X className="w-3 h-3" />
                </button>
              </div>
            ))}
            {photos.length < 5 && (
              <label className="w-20 h-20 rounded-lg border-2 border-dashed border-border flex flex-col items-center justify-center text-muted-foreground cursor-pointer hover:border-primary/40 hover:bg-primary/5 transition">
                <Camera className="w-5 h-5" />
                <span className="text-[9px] mt-0.5">Tambah</span>
                <input type="file" accept="image/*" multiple onChange={handlePhotoUpload} className="hidden" disabled={isUploading} />
              </label>
            )}
          </div>
          {isUploading && <p className="text-xs text-primary mt-1 animate-pulse">Mengupload foto...</p>}
        </div>

        {/* Title */}
        <div>
          <label className="text-sm font-semibold text-foreground">Judul Jasa <span className="text-destructive">*</span></label>
          <input
            type="text"
            value={title}
            onChange={e => setTitle(e.target.value)}
            placeholder="contoh: Jasa Desain Logo Profesional"
            maxLength={100}
            className="mt-1 w-full px-3 py-2.5 bg-muted rounded-xl text-sm border-none outline-none focus:ring-2 focus:ring-primary/30"
          />
          <p className="text-[10px] text-muted-foreground mt-1 text-right">{title.length}/100</p>
        </div>

        {/* Description */}
        <div>
          <label className="text-sm font-semibold text-foreground">Deskripsi Jasa <span className="text-destructive">*</span></label>
          <textarea
            value={description}
            onChange={e => setDescription(e.target.value)}
            placeholder={"Jelaskan detail jasa yang kamu tawarkan:\n• Apa yang akan kamu kerjakan?\n• Tools/software yang digunakan\n• Pengalaman / keahlian\n• Berapa revisi yang diberikan?"}
            rows={5}
            maxLength={1000}
            className="mt-1 w-full px-3 py-2.5 bg-muted rounded-xl text-sm border-none outline-none focus:ring-2 focus:ring-primary/30 resize-none"
          />
          <p className={`text-[10px] mt-1 text-right ${descLen < 10 && descLen > 0 ? 'text-destructive' : 'text-muted-foreground'}`}>
            {descLen}/1000 {descLen > 0 && descLen < 10 && '• minimal 10 karakter'}
          </p>
        </div>

        {/* Category */}
        <div>
          <label className="text-sm font-semibold text-foreground">Kategori Jasa <span className="text-destructive">*</span></label>
          {catLoading ? (
            <div className="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
              <Loader2 className="w-4 h-4 animate-spin" /> Memuat kategori...
            </div>
          ) : categories.length === 0 ? (
            <div className="mt-2 p-3 bg-amber-50 dark:bg-amber-950/30 border border-amber-200 dark:border-amber-800 rounded-xl text-xs text-amber-700 dark:text-amber-300">
              Kategori jasa belum tersedia. Coba muat ulang halaman.
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-2 mt-2">
              {categories.map(c => (
                <button
                  key={c.id}
                  onClick={() => setCategoryId(c.id)}
                  className={`flex items-center gap-2 p-3 rounded-xl border text-sm font-medium transition ${
                    categoryId === c.id
                      ? 'border-primary bg-primary/10 text-primary ring-1 ring-primary/30'
                      : 'border-border bg-card text-foreground hover:border-primary/30'
                  }`}
                >
                  <span className="text-lg">{c.icon}</span> {c.name}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Desired Items */}
        <div>
          <label className="text-sm font-semibold text-foreground flex items-center gap-1">
            <Sparkles className="w-3.5 h-3.5 text-primary" /> Ingin Ditukar Dengan
          </label>
          <input
            type="text"
            value={desiredItems}
            onChange={e => setDesiredItems(e.target.value)}
            placeholder="contoh: Laptop, Tablet, Kamera, atau barang apapun"
            className="mt-1 w-full px-3 py-2.5 bg-muted rounded-xl text-sm border-none outline-none focus:ring-2 focus:ring-primary/30"
          />
          <p className="text-[10px] text-muted-foreground mt-1">Kosongkan jika terbuka untuk semua barang</p>
        </div>

        {/* Time Options */}
        <div className="space-y-4">
          {/* Completion Days */}
          <div>
            <label className="text-sm font-semibold text-foreground flex items-center gap-1">
              <Clock className="w-3.5 h-3.5" /> Waktu Pengerjaan <span className="text-destructive">*</span>
            </label>
            <div className="flex flex-wrap gap-2 mt-2">
              {COMPLETION_OPTIONS.map(opt => (
                <button
                  key={opt.value}
                  onClick={() => setCompletionDays(opt.value)}
                  className={`px-3 py-2 rounded-lg text-xs font-medium border transition ${
                    completionDays === opt.value
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                      : 'bg-card text-foreground border-border hover:border-primary/30'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>

          {/* Estimated Hours */}
          <div>
            <label className="text-sm font-semibold text-foreground">Estimasi Jam Kerja <span className="text-muted-foreground font-normal">(opsional)</span></label>
            <div className="flex flex-wrap gap-2 mt-2">
              {HOURS_OPTIONS.map(opt => (
                <button
                  key={opt.value}
                  onClick={() => setEstimatedHours(prev => prev === opt.value ? null : opt.value)}
                  className={`px-3 py-2 rounded-lg text-xs font-medium border transition ${
                    estimatedHours === opt.value
                      ? 'bg-primary text-primary-foreground border-primary shadow-sm'
                      : 'bg-card text-foreground border-border hover:border-primary/30'
                  }`}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Location — auto from profile */}
        <div>
          <label className="text-sm font-semibold text-foreground flex items-center gap-1">
            <MapPin className="w-3.5 h-3.5" /> Lokasi
          </label>
          <div className="mt-1 flex items-center gap-2 bg-muted rounded-xl px-3 py-2.5">
            <MapPin className="w-4 h-4 text-primary flex-shrink-0" />
            <p className="text-sm text-foreground">
              {displayLocation || <span className="text-muted-foreground">Mendeteksi lokasi...</span>}
            </p>
          </div>
          <p className="text-[10px] text-muted-foreground mt-1">Lokasi otomatis dari akunmu</p>
        </div>

        {/* Submit */}
        <button
          onClick={handleSubmit}
          disabled={submitting || !canSubmit}
          className="w-full py-3.5 bg-primary text-primary-foreground rounded-xl font-bold text-sm shadow-md shadow-primary/20 disabled:opacity-50 disabled:shadow-none hover:opacity-90 transition flex items-center justify-center gap-2"
        >
          {submitting ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Memproses...
            </>
          ) : (
            '🛠️ Tawarkan Jasa'
          )}
        </button>

        {/* Validation hints */}
        {!canSubmit && (title.length > 0 || description.length > 0) && (
          <div className="text-xs text-muted-foreground space-y-0.5 -mt-2">
            {title.trim().length < 3 && <p>• Judul minimal 3 karakter</p>}
            {description.trim().length < 10 && <p>• Deskripsi minimal 10 karakter</p>}
            {!categoryId && <p>• Pilih kategori jasa</p>}
          </div>
        )}

        <div className="h-2" />
      </div>

      <BottomNav />
    </div>
  );
}

