import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Star, Package, ShieldCheck, MapPin, Phone, CheckCircle2, ArrowRightLeft, Heart, Award, MessageCircle, Trophy, UserPlus, UserCheck, Users, ChevronRight } from 'lucide-react';
import { useAuth } from 'zitejs/auth';
import { getPublicProfile, getFollowStatus, toggleFollow, GetPublicProfileOutputType } from 'zitejs/api';
import BadgeAvatar from '../components/BadgeAvatar';
import { Skeleton } from '@project/components/ui/skeleton';
import BadgeChip from '../components/BadgeChip';
import { getBadge, getProgressToNext } from '../lib/badges';
import AwardsShowcase from '../components/AwardsShowcase';
import { AwardsCompactRow } from '../components/AwardPins';

type ProfileData = GetPublicProfileOutputType;

function VerifiedBadge({ label }: { label: string }) {
  return (
    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 text-[10px] font-semibold">
      <CheckCircle2 className="w-3 h-3" /> {label}
    </span>
  );
}

function StatCard({ icon: Icon, value, label, color }: { icon: any; value: string | number; label: string; color: string }) {
  return (
    <div className="flex flex-col items-center gap-1 py-3 px-2">
      <div className={`w-8 h-8 rounded-full flex items-center justify-center ${color}`}>
        <Icon className="w-4 h-4" />
      </div>
      <p className="font-bold text-sm leading-none">{value}</p>
      <p className="text-[10px] text-muted-foreground leading-tight text-center">{label}</p>
    </div>
  );
}

function ItemCard({ item, onTap }: { item: ProfileData['items'][0]; onTap: () => void }) {
  const statusColor = item.status === 'Tersedia' ? 'bg-emerald-500' : item.status === 'Negosiasi' ? 'bg-amber-500' : 'bg-muted-foreground';
  return (
    <button onClick={onTap} className="bg-card border border-border rounded-xl overflow-hidden text-left group shadow-sm">
      <div className="relative">
        {item.photo ? (
          <img src={item.photo} alt={item.title} className="w-full aspect-square object-cover group-hover:scale-105 transition-transform" />
        ) : (
          <div className="w-full aspect-square bg-muted flex items-center justify-center">
            <Package className="w-8 h-8 text-muted-foreground" />
          </div>
        )}
        <span className={`absolute top-1.5 left-1.5 px-1.5 py-0.5 rounded-full text-[8px] font-bold text-white ${statusColor}`}>
          {item.status}
        </span>
      </div>
      <div className="p-2">
        <p className="text-xs font-semibold truncate">{item.title}</p>
        <p className="text-[10px] text-muted-foreground">{item.condition}</p>
      </div>
    </button>
  );
}

function ReviewCard({ review }: { review: ProfileData['reviews'][0] }) {
  return (
    <div className="bg-card border border-border rounded-xl p-3 shadow-sm">
      <div className="flex items-center gap-2">
        {review.reviewerImage ? (
          <img src={review.reviewerImage} alt="" className="w-7 h-7 rounded-full object-cover" />
        ) : (
          <div className="w-7 h-7 rounded-full bg-muted flex items-center justify-center text-[10px] font-bold">
            {review.reviewerName[0]?.toUpperCase()}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <p className="text-xs font-semibold truncate">{review.reviewerName}</p>
          {review.createdAt && (
            <p className="text-[9px] text-muted-foreground">{new Date(review.createdAt).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}</p>
          )}
        </div>
        <div className="flex items-center gap-0.5">
          {Array.from({ length: 5 }).map((_, i) => (
            <Star key={i} className={`w-3 h-3 ${i < review.rating ? 'text-amber-400 fill-amber-400' : 'text-muted-foreground/30'}`} />
          ))}
        </div>
      </div>
      {review.comment && <p className="text-xs text-muted-foreground mt-2 leading-relaxed">{review.comment}</p>}
    </div>
  );
}

function ReviewsSection({ data }: { data: ProfileData }) {
  const [showAll, setShowAll] = useState(false);
  const sorted = [...data.reviews].sort((a, b) =>
    new Date(b.createdAt || '').getTime() - new Date(a.createdAt || '').getTime()
  );
  const latestReview = sorted[0];

  return (
    <div className="px-4 mt-5">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <h3 className="font-bold text-sm">Ulasan ({data.totalReviews})</h3>
          {data.totalReviews > 0 && (
            <div className="flex items-center gap-1 bg-amber-500/10 px-2 py-0.5 rounded-full">
              <Star className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
              <span className="font-bold text-xs text-amber-700">{data.averageRating}</span>
              <span className="text-[9px] text-muted-foreground">/ 5</span>
            </div>
          )}
        </div>
        {data.reviews.length > 1 && (
          <button
            onClick={() => setShowAll(v => !v)}
            className="flex items-center gap-0.5 text-[11px] text-primary font-semibold"
          >
            {showAll ? 'Sembunyikan' : 'Semua'}
            <ChevronRight className={`w-3.5 h-3.5 transition-transform ${showAll ? 'rotate-90' : ''}`} />
          </button>
        )}
      </div>

      {data.reviews.length > 0 ? (
        <>
          {/* Rating breakdown — only when expanded */}
          {showAll && (
            <div className="bg-card border border-border rounded-xl p-3 shadow-sm mb-3">
              {[5, 4, 3, 2, 1].map(star => {
                const count = data.reviews.filter(r => r.rating === star).length;
                const pct = data.totalReviews > 0 ? (count / data.totalReviews) * 100 : 0;
                return (
                  <div key={star} className="flex items-center gap-2 py-0.5">
                    <span className="text-[10px] text-muted-foreground w-3 text-right">{star}</span>
                    <Star className="w-2.5 h-2.5 text-amber-400 fill-amber-400" />
                    <div className="flex-1 h-1.5 rounded-full bg-muted overflow-hidden">
                      <div className="h-full rounded-full bg-amber-400 transition-all" style={{ width: `${pct}%` }} />
                    </div>
                    <span className="text-[10px] text-muted-foreground w-4">{count}</span>
                  </div>
                );
              })}
            </div>
          )}

          {/* Show only latest or all */}
          <div className="space-y-2">
            {showAll
              ? sorted.map(r => <ReviewCard key={r.id} review={r} />)
              : latestReview && <ReviewCard review={latestReview} />
            }
          </div>
        </>
      ) : (
        <div className="bg-card border border-border rounded-xl p-6 text-center shadow-sm">
          <Star className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
          <p className="text-xs text-muted-foreground">Belum ada ulasan</p>
        </div>
      )}
    </div>
  );
}

function ProfileSkeleton({ onBack }: { onBack: () => void }) {
  return (
    <div className="min-h-screen bg-background mutari-main max-w-[420px] mx-auto">
      <div className="bg-primary px-4 pt-4 pb-6 rounded-b-2xl">
        <button onClick={onBack} className="w-8 h-8 rounded-full bg-white/15 flex items-center justify-center mb-4">
          <ArrowLeft className="w-4 h-4 text-white" />
        </button>
        <div className="flex items-center gap-3">
          <Skeleton className="w-16 h-16 rounded-full bg-white/20" />
          <div className="space-y-2">
            <Skeleton className="h-4 w-32 bg-white/20 rounded" />
            <Skeleton className="h-3 w-20 bg-white/20 rounded" />
          </div>
        </div>
      </div>
      <div className="px-4 mt-4 space-y-3">
        <Skeleton className="h-20 w-full rounded-xl" />
        <Skeleton className="h-32 w-full rounded-xl" />
      </div>
    </div>
  );
}

function ProfileContent({ data, navigate, showPreviewBanner = false, targetUserId, isOwnProfile }: { data: ProfileData; navigate: ReturnType<typeof useNavigate>; showPreviewBanner?: boolean; targetUserId?: string; isOwnProfile?: boolean }) {
  const [itemFilter, setItemFilter] = useState<'all' | 'Tersedia' | 'Negosiasi' | 'Sudah Ditukar'>('all');
  const [isFollowing, setIsFollowing] = useState(false);
  const [followersCount, setFollowersCount] = useState(0);
  const [followingCount, setFollowingCount] = useState(0);
  const [followLoading, setFollowLoading] = useState(false);
  const [followChecked, setFollowChecked] = useState(false);
  const initials = (data.name?.[0] || 'U').toUpperCase();
  const badge = getBadge(data.totalPoints);
  const progress = getProgressToNext(data.totalPoints);

  useEffect(() => {
    if (!targetUserId || isOwnProfile) return;
    getFollowStatus({ targetUserId })
      .then(res => {
        setIsFollowing(res.isFollowing);
        setFollowersCount(res.followersCount);
        setFollowingCount(res.followingCount);
        setFollowChecked(true);
      })
      .catch(() => setFollowChecked(true));
  }, [targetUserId, isOwnProfile]);

  const handleFollow = async () => {
    if (!targetUserId || followLoading) return;
    setFollowLoading(true);
    try {
      const res = await toggleFollow({ targetUserId });
      setIsFollowing(res.following);
      setFollowersCount(prev => res.following ? prev + 1 : Math.max(0, prev - 1));
    } catch {
      // ignore
    } finally {
      setFollowLoading(false);
    }
  };

  const filteredItems = itemFilter === 'all' ? data.items : data.items.filter(i => i.status === itemFilter);
  const statusCounts = {
    all: data.items.length,
    Tersedia: data.items.filter(i => i.status === 'Tersedia').length,
    Negosiasi: data.items.filter(i => i.status === 'Negosiasi').length,
    'Sudah Ditukar': data.items.filter(i => i.status === 'Sudah Ditukar').length,
  };

  return (
    <div className="min-h-screen bg-background pb-8">
      <div className="max-w-[420px] mx-auto">
        {/* Preview Banner for own profile */}
        {showPreviewBanner && (
          <div className="bg-amber-500/10 border-b border-amber-500/20 px-4 py-2 flex items-center gap-2 sticky top-0 z-50 backdrop-blur-sm">
            <Award className="w-4 h-4 text-amber-600" />
            <p className="text-xs text-amber-700 font-medium flex-1">
              Ini adalah tampilan profil publik kamu
            </p>
            <button onClick={() => navigate('/edit-profile')} className="text-xs font-semibold text-primary">Edit</button>
          </div>
        )}

        {/* Header */}
        <div className="bg-primary px-4 pt-4 pb-5 rounded-b-2xl relative overflow-hidden">
          <div className="absolute -right-10 -top-10 w-32 h-32 rounded-full bg-white/5" />
          <div className="absolute right-10 -bottom-6 w-20 h-20 rounded-full bg-white/3" />
          <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-white/15 flex items-center justify-center mb-4 relative z-10">
            <ArrowLeft className="w-4 h-4 text-white" />
          </button>
          <div className="flex items-center gap-4 relative z-10">
            <BadgeAvatar src={data.image} initials={initials} points={data.totalPoints ?? 0} size="xl" />
            <div className="flex-1 min-w-0">
              <p className="text-white font-bold text-lg truncate">{data.name}</p>
              <div className="flex items-center gap-2 mt-1 flex-wrap">
                <BadgeChip points={data.totalPoints} size="sm" />
              </div>
              {/* Award emojis in header — separate from reputation badge */}
              {data.awardCount > 0 && (
                <div className="flex items-center gap-1 mt-1">
                  {data.awardEmojis.map((e: string, i: number) => (
                    <span key={i} className="text-xs">{e}</span>
                  ))}
                  <span className="text-[10px] text-white/60 font-medium">{data.awardCount} penghargaan</span>
                </div>
              )}
              {(data.city || data.memberSince !== '-') && (
                <div className="flex items-center gap-3 mt-1.5 flex-wrap">
                  {data.city && (
                    <span className="text-white/60 text-xs flex items-center gap-1">
                      <MapPin className="w-3 h-3" /> {data.city}{data.province ? `, ${data.province}` : ''}
                    </span>
                  )}
                  <span className="text-white/60 text-xs flex items-center gap-1">
                    <ShieldCheck className="w-3 h-3" /> Sejak {data.memberSince}
                  </span>
                </div>
              )}
            </div>
          </div>

          {/* Follow button & counts */}
          {!isOwnProfile && targetUserId && followChecked && (
            <div className="flex items-center gap-3 mt-3 relative z-10">
              <button
                onClick={handleFollow}
                disabled={followLoading}
                className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-xs font-bold transition-all active:scale-95 ${
                  isFollowing
                    ? 'bg-white/20 text-white border border-white/30'
                    : 'bg-white text-primary shadow-md'
                }`}
              >
                {followLoading ? (
                  <span className="w-3.5 h-3.5 border-2 border-current border-t-transparent rounded-full animate-spin" />
                ) : isFollowing ? (
                  <UserCheck className="w-3.5 h-3.5" />
                ) : (
                  <UserPlus className="w-3.5 h-3.5" />
                )}
                {isFollowing ? 'Mengikuti' : 'Ikuti'}
              </button>
              <div className="flex items-center gap-3 text-white/70">
                <span className="text-xs"><span className="font-bold text-white">{followersCount}</span> Pengikut</span>
                <span className="text-xs"><span className="font-bold text-white">{followingCount}</span> Mengikuti</span>
              </div>
            </div>
          )}
        </div>

        {/* Stats Grid */}
        <div className="px-4 -mt-3 relative z-10">
          <div className="bg-card border border-border rounded-xl grid grid-cols-4 divide-x divide-border shadow-sm">
            <StatCard icon={Package} value={data.itemsUploaded} label="Barang" color="bg-blue-500/10 text-blue-600" />
            <StatCard icon={ArrowRightLeft} value={data.bartersCompleted} label="Barter" color="bg-emerald-500/10 text-emerald-600" />
            <StatCard icon={Heart} value={data.likesReceived} label="Suka" color="bg-pink-500/10 text-pink-600" />
            <StatCard icon={Star} value={data.totalReviews > 0 ? String(data.averageRating) : '-'} label="Rating" color="bg-amber-500/10 text-amber-600" />
          </div>
        </div>

        {/* Verification & Trust */}
        <div className="px-4 mt-4">
          <div className="flex flex-wrap gap-1.5">
            {data.phoneVerified && <VerifiedBadge label="Telepon Terverifikasi" />}
            {data.addressVerified && <VerifiedBadge label="Alamat Terverifikasi" />}
            {data.bartersCompleted >= 5 && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-600 text-[10px] font-semibold">
                <Trophy className="w-3 h-3" /> Barter Berpengalaman
              </span>
            )}
