                </div>
              </div>
            )}
          </div>
        </div>

        {/* Penghargaan Program — terpisah dari badge reputasi di atas */}
        {targetUserId && <AwardsShowcase userId={targetUserId} />}

        {/* Bio */}
        {data.bio && (
          <div className="px-4 mt-4">
            <h3 className="font-bold text-sm mb-1.5">Tentang</h3>
            <p className="text-sm text-muted-foreground leading-relaxed">{data.bio}</p>
          </div>
