        {/* Items with filter tabs */}
        <div className="px-4 mt-5">
          <h3 className="font-bold text-sm mb-3">Semua Barang ({data.items.length})</h3>
          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {([['all', 'Semua'], ['Tersedia', 'Tersedia'], ['Negosiasi', 'Negosiasi'], ['Sudah Ditukar', 'Ditukar']] as const).map(([key, label]) => (
              <button
                key={key}
                onClick={() => setItemFilter(key as any)}
                className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-semibold transition-colors ${
                  itemFilter === key
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-muted-foreground'
                }`}
              >
                {label} ({statusCounts[key]})
              </button>
