          {filteredItems.length > 0 ? (
            <div className="grid grid-cols-2 gap-2 mt-2 mutari-item-grid">
              {filteredItems.map(item => (
                <ItemCard key={item.id} item={item} onTap={() => navigate(`/item/${item.id}`)} />
              ))}
            </div>
          ) : (
            <div className="bg-card border border-border rounded-xl p-6 text-center shadow-sm mt-2">
              <Package className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
              <p className="text-xs text-muted-foreground">Belum ada barang</p>
            </div>
          )}
        </div>

        {/* Reviews */}
        <ReviewsSection data={data} />

        {/* Akun Sosial Media */}
        {(data.instagram || data.twitter) && (
          <div className="px-4 mt-5">
            <h3 className="font-bold text-sm mb-2">Sosial Media</h3>
            <div className="flex gap-2 flex-wrap">
              {data.instagram && (
                <a href={`https://instagram.com/${data.instagram}`} target="_blank" rel="noreferrer" className="flex items-center gap-1.5 px-3 py-2 bg-card border border-border rounded-xl text-xs font-medium hover:bg-accent/50 transition-colors">
                  📸 @{data.instagram}
                </a>
              )}
              {data.twitter && (
                <a href={`https://x.com/${data.twitter}`} target="_blank" rel="noreferrer" className="flex items-center gap-1.5 px-3 py-2 bg-card border border-border rounded-xl text-xs font-medium hover:bg-accent/50 transition-colors">
                  𝕏 @{data.twitter}
                </a>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default function UserProfilePage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [data, setData] = useState<ProfileData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!id) return;
    if (user && id === user.id) {
      navigate('/profile', { replace: true });
      return;
    }
    setLoading(true);
    getPublicProfile({ userId: id })
      .then(setData)
      .catch(() => setData(null))
      .finally(() => setLoading(false));
  }, [id, user, navigate]);

  if (loading) return <ProfileSkeleton onBack={() => navigate(-1)} />;

  if (!data) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <p className="text-muted-foreground">Pengguna tidak ditemukan</p>
      </div>
    );
  }

  return <ProfileContent data={data} navigate={navigate} targetUserId={id} isOwnProfile={false} />;
}

