export default function WalletPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const { totalPoints, itemsUploaded, bartersCompleted, likesReceived, totalMinusPoints, activeViolations, history, loading } = useUserPoints();
  const badge = getBadge(totalPoints);
  const next = getNextBadge(totalPoints);
  const progress = getProgressToNext(totalPoints);

  type NotifType = GetNotificationsOutputType['notifications'][0];
  const [badgeNotif, setBadgeNotif] = useState<NotifType | null>(null);
  type ViolationType = GetViolationsOutputType['violations'][0];
  const [violations, setViolations] = useState<ViolationType[]>([]);
  const [violationsLoading, setViolationsLoading] = useState(true);

  useEffect(() => {
    getNotifications({ limit: 5, unreadOnly: true })
      .then(res => {
        const bn = res.notifications.find(n => n.type === 'badge' && !n.read);
        if (bn) setBadgeNotif(bn);
      })
      .catch(() => {});
    getViolations({})
      .then(res => setViolations(res.violations))
      .catch(() => {})
      .finally(() => setViolationsLoading(false));
  }, []);

  const dismissBadgeNotif = () => {
    if (badgeNotif) {
      markNotificationRead({ notificationId: badgeNotif.id }).catch(() => {});
      setBadgeNotif(null);
    }
  };

  const [showConfetti, setShowConfetti] = useState(false);
  const [sparkleBalance, setSparkleBalance] = useState(false);

  useEffect(() => {
    if (!loading && totalPoints > 0) {
      const timer = setTimeout(() => setSparkleBalance(true), 600);
      return () => clearTimeout(timer);
    }
  }, [loading, totalPoints]);

  useEffect(() => {
    if (badgeNotif) setShowConfetti(true);
  }, [badgeNotif]);

  const [openGuide, setOpenGuide] = useState<string | null>(null);
  const toggleGuide = (key: string) => setOpenGuide(prev => prev === key ? null : key);
  const [openSection, setOpenSection] = useState<string | null>(null);
  const toggleSection = (key: string) => setOpenSection(prev => prev === key ? null : key);

  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthlyPoints = history
    .filter(h => new Date(h.earnedAt) >= monthStart)
    .reduce((sum, h) => sum + h.points, 0);

  const grouped: Record<string, typeof history> = {};
  history.forEach(h => {
    const key = formatDate(h.earnedAt);
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(h);
  });
  const dateKeys = Object.keys(grouped);

  return (
    <div className="min-h-screen bg-background mutari-main pb-10">
      <Confetti active={showConfetti} count={60} duration={3500} />
      <div className="max-w-[420px] mx-auto">
        {/* Header — matches Beranda top bar style */}
        <div className="sticky top-0 z-40 bg-background border-b border-border px-4 py-3 flex items-center gap-3">
          <button onClick={() => navigate(-1)} className="w-8 h-8 rounded-full bg-muted flex items-center justify-center flex-shrink-0">
            <ArrowLeft className="w-4 h-4 text-foreground" />
          </button>
          <div className="flex-1">
            <h1 className="text-foreground font-bold text-base">Wallet MUTARI</h1>
            <p className="text-muted-foreground text-[10px]">Kelola poin & reputasimu</p>
          </div>
          <BadgeAvatar src={user?.image} initials={((user?.firstName?.[0] || '') + (user?.lastName?.[0] || '') || user?.email?.[0] || 'U').toUpperCase()} points={totalPoints} size="sm" />
        </div>

        {/* Badge achievement banner */}
        <AnimatePresence>
          {badgeNotif && (
            <motion.div
              initial={{ opacity: 0, y: -10, height: 0 }}
              animate={{ opacity: 1, y: 0, height: 'auto' }}
              exit={{ opacity: 0, y: -10, height: 0 }}
              className="px-4 pt-3"
            >
              <div className="bg-card border border-border rounded-2xl p-4 shadow-sm relative overflow-hidden">
                <button onClick={dismissBadgeNotif} className="absolute top-2 right-2 w-6 h-6 rounded-full bg-muted flex items-center justify-center">
                  <X className="w-3 h-3 text-muted-foreground" />
                </button>
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-xl bg-amber-100 flex items-center justify-center flex-shrink-0">
                    <Trophy className="w-6 h-6 text-amber-600" strokeWidth={1.75} />
                  </div>
                  <div className="flex-1">
                    <p className="font-bold text-sm">{badgeNotif.title}</p>
                    <p className="text-muted-foreground text-[11px] mt-0.5 leading-relaxed">{badgeNotif.body}</p>
                  </div>
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <BalanceCard totalPoints={totalPoints} loading={loading} sparkleBalance={sparkleBalance} monthlyPoints={monthlyPoints} badge={badge} />
        <BadgeProgressCard badge={badge} next={next} progress={progress} totalPoints={totalPoints} loading={loading} />

        {/* Divider */}
        <div className="mx-4 my-2 h-px bg-border" />

        {/* Point Shop & Top Up — side by side */}
        <div className="px-4 pb-1 grid grid-cols-2 gap-2">
          <motion.button
