          >
            <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
              <CreditCard className="w-5 h-5 text-muted-foreground" strokeWidth={1.75} />
            </div>
            <div>
              <p className="font-bold text-sm text-muted-foreground leading-tight flex items-center justify-center gap-1">Poin Plus <Lock className="w-3 h-3" /></p>
              <p className="text-[10px] text-muted-foreground/70 mt-0.5">Segera hadir</p>
            </div>
            <span className="absolute top-2 right-2 text-[8px] font-semibold bg-primary/10 text-primary px-1.5 py-0.5 rounded-full">SOON</span>
          </div>
        </div>

        <QuickStatsRow itemsUploaded={itemsUploaded} bartersCompleted={bartersCompleted} likesReceived={likesReceived} loading={loading} />

        {/* Minus Points */}
        {!loading && (totalMinusPoints < 0 || activeViolations > 0) && (
          <>
            <div className="mx-4 my-2 h-px bg-border" />
            <MinusPointsBanner totalMinusPoints={totalMinusPoints} activeViolations={activeViolations} />
          </>
        )}

        {/* Net points */}
        {!loading && totalMinusPoints < 0 && (
          <div className="px-4 mt-2">
            <div className="bg-card border border-border rounded-2xl p-3 flex items-center justify-between shadow-sm">
              <span className="text-xs text-muted-foreground">Poin Bersih</span>
              <span className="text-sm font-bold">{totalPoints.toLocaleString('id-ID')} MP + ({totalMinusPoints}) = <span className="text-primary">{Math.max(0, totalPoints + totalMinusPoints).toLocaleString('id-ID')} MP</span></span>
            </div>
          </div>
        )}

        {/* Divider */}
        <div className="mx-4 my-2 h-px bg-border" />

        {/* Reputation — collapsible */}
        <CollapsibleSection
          title="Detail Reputasi"
          subtitle={`Level badge · ${badge.emoji} ${badge.name} · ${totalPoints} MP`}
          icon={Shield}
          iconBg="bg-primary/10"
          iconColor="text-primary"
          open={openSection === 'reputasi'}
          onToggle={() => toggleSection('reputasi')}
        >
          <div className="space-y-2">
            {BADGES.map((b) => {
              const unlocked = totalPoints >= b.minPoints;
              const isCurrent = b.id === badge.id;
              const rangeText = b.maxPoints ? `${b.minPoints.toLocaleString('id-ID')} – ${b.maxPoints.toLocaleString('id-ID')} MP` : `${b.minPoints.toLocaleString('id-ID')}+ MP`;
              return (
                <div key={b.id} className={`rounded-2xl p-3 flex items-center gap-3 transition-colors ${isCurrent ? 'bg-primary/10 border-2 border-primary/30' : unlocked ? 'bg-muted/50 border border-border' : 'bg-muted/20 border border-border/50 opacity-60'}`}>
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg flex-shrink-0 ${isCurrent ? 'bg-primary/20' : unlocked ? 'bg-muted' : 'bg-muted/50'}`}>{b.emoji}</div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-1.5">
                      <p className={`text-sm font-bold truncate ${isCurrent ? 'text-primary' : ''}`}>{b.name}</p>
                      {isCurrent && <span className="text-[8px] font-bold bg-primary text-primary-foreground px-1.5 py-0.5 rounded-full flex-shrink-0">LEVEL KAMU</span>}
                    </div>
                    <p className="text-[10px] text-muted-foreground mt-0.5">{b.description}</p>
                  </div>
                  <div className="text-right flex-shrink-0">
                    <p className={`text-[11px] font-bold ${isCurrent ? 'text-primary' : 'text-foreground'}`}>{rangeText}</p>
                    {isCurrent && <p className="text-[9px] text-primary font-medium">{totalPoints.toLocaleString('id-ID')} MP</p>}
                  </div>
                </div>
              );
            })}
          </div>
          {!loading && (
            <div className="mt-4 pt-3 border-t border-border">
              <div className="flex items-center justify-between mb-1.5">
                <span className="text-[10px] text-muted-foreground">Progress keseluruhan</span>
                <span className="text-[10px] font-bold text-primary">{totalPoints.toLocaleString('id-ID')} MP</span>
              </div>
              <div className="flex gap-0.5">
                {BADGES.map((b) => {
                  const segmentMax = b.maxPoints ?? (b.minPoints + 500);
                  const segmentRange = segmentMax - b.minPoints;
                  let fillPercent = 0;
                  if (totalPoints >= segmentMax) fillPercent = 100;
                  else if (totalPoints > b.minPoints) fillPercent = ((totalPoints - b.minPoints) / segmentRange) * 100;
                  const isCurrent = b.id === badge.id;
                  return (
                    <div key={b.id} className="flex-1">
                      <div className={`h-2.5 rounded-full overflow-hidden ${isCurrent ? 'ring-1 ring-primary ring-offset-1' : 'bg-muted'}`}>
                        <motion.div className="h-full rounded-full bg-primary" initial={{ width: 0 }} animate={{ width: `${fillPercent}%` }} transition={{ duration: 0.6, delay: 0.2 }} />
                      </div>
                    </div>
                  );
                })}
              </div>
              <div className="flex justify-between mt-1">
                {BADGES.map(b => <span key={b.id} className="text-[8px] text-muted-foreground text-center flex-1">{b.emoji}</span>)}
              </div>
            </div>
          )}
        </CollapsibleSection>

        {/* Earn points */}
        <div className="mt-2" />
        <CollapsibleSection
          title="Cara Mendapatkan Poin"
          subtitle={`${EARN_OPTIONS.length} cara cepat`}
          icon={TrendingUp}
          iconBg="bg-emerald-100"
          iconColor="text-emerald-600"
          open={openSection === 'earn'}
          onToggle={() => toggleSection('earn')}
        >
