                <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center flex-shrink-0">
                  <opt.icon className="w-5 h-5 text-primary" strokeWidth={1.75} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold">{opt.label}</p>
                  <p className="text-[10px] text-muted-foreground">{opt.desc}</p>
                </div>
                <span className="text-xs font-bold text-primary flex-shrink-0">{opt.points}</span>
                <ChevronRight className="w-4 h-4 text-muted-foreground flex-shrink-0" />
              </button>
            ))}
          </div>
        </CollapsibleSection>

        {/* Panduan Poin */}
        <div className="mt-2" />
        <CollapsibleSection
          title="Panduan Poin MUTARI (MP)"
          subtitle="Plus poin, minus poin & sanksi"
          icon={BookOpen}
          iconBg="bg-amber-100"
          iconColor="text-amber-600"
          open={openSection === 'panduan'}
          onToggle={() => toggleSection('panduan')}
        >
          <div className="space-y-1.5">
