            <button onClick={() => toggleGuide('plus')} className="w-full flex items-center gap-2 bg-emerald-50 rounded-xl px-3 py-2.5 text-left">
              <div className="w-7 h-7 rounded-full bg-emerald-100 flex items-center justify-center flex-shrink-0">
                <Plus className="w-3.5 h-3.5 text-emerald-600" />
              </div>
              <div className="flex-1">
                <p className="text-[11px] font-bold text-emerald-700">Plus Poin — Cara Mendapatkan MP</p>
