              const config: Record<string, { bg: string; dotBg: string; text: string; textSub: string; label: string }> = {
                paling_berat: { bg: 'bg-red-100', dotBg: 'bg-red-700', text: 'text-red-900', textSub: 'text-red-600', label: 'Paling Berat — Mementingkan Diri Sendiri' },
