        {/* Divider */}
        <div className="mx-4 my-2 h-px bg-border" />

        {/* Transaction history */}
        <CollapsibleSection
          title="Riwayat Transaksi"
          subtitle={`${history.length} transaksi${violations.length > 0 ? ` · ${violations.length} pelanggaran` : ''}`}
          icon={Wallet}
          iconBg="bg-sky-100"
          iconColor="text-sky-600"
          open={openSection === 'riwayat'}
