                <span className="text-[10px] text-muted-foreground px-2 py-0.5 bg-red-100 text-red-700 rounded-full font-medium">{violations.length} total</span>
              </div>
              <div className="rounded-2xl border border-border divide-y divide-border overflow-hidden">
                {violations.slice(0, 5).map((v) => {
                  const sc = severityColor(v.severity);
                  return (
                    <div key={v.id} className="px-3 py-2.5 flex items-center gap-3">
                      <div className={`w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 ${sc.bg} ${sc.text}`}>
