              <p className="text-sm font-semibold">Belum Ada Transaksi</p>
              <p className="text-xs text-muted-foreground mt-1">Upload barang untuk mulai mendapatkan poin.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {dateKeys.slice(0, 5).map(dateKey => (
                <div key={dateKey}>
                  <p className="text-[10px] text-muted-foreground font-medium mb-1.5">{dateKey}</p>
                  <div className="rounded-2xl border border-border divide-y divide-border overflow-hidden">
                    {grouped[dateKey].map((h, i) => (
                      <div key={i} className="px-3 py-2.5 flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 ${activityColor(h.activityType)}`}>
                          {activityIcon(h.activityType)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-xs font-semibold truncate">{h.activity}</p>
                          <p className="text-[10px] text-muted-foreground">{formatTime(h.earnedAt)}</p>
                        </div>
                        <span className={`text-xs font-bold flex items-center gap-0.5 flex-shrink-0 ${h.points >= 0 ? 'text-emerald-600' : 'text-destructive'}`}>
                          {h.points >= 0 ? <motion.span initial={{ scale: 1 }} animate={{ scale: [1, 1.3, 1] }} transition={{ duration: 0.5, delay: 0.1 * i }}><ArrowDownLeft className="w-3 h-3" /></motion.span> : <ArrowUpRight className="w-3 h-3" />}
