                    ))}
                  </div>
                </div>
              ))}
              <button onClick={() => navigate('/achievements')} className="w-full text-center text-xs text-primary font-semibold py-2">Lihat Semua →</button>
            </div>
          )}
        </CollapsibleSection>

        <div className="h-6" />
      </div>
    </div>
  );
}

