var analyzeWithGemini_default = createEndpoint({
  description: "Analisis gambar barang dengan Gemini + cari match barter seimbang",
  authenticated: true,
  inputSchema: z.object({
    imageUrl: z.string().url()
  }),
  outputSchema: z.object({
    analysis: z.string(),
    estimatedMinPrice: z.number(),
    estimatedMaxPrice: z.number(),
    matches: z.array(z.object({
      id: z.string(),
      title: z.string(),
      photo: z.string(),
      condition: z.string(),
      location: z.string(),
      estimatedMin: z.number(),
      estimatedMax: z.number(),
      ownerName: z.string()
    }))
  }),
  execute: async ({ input, context }) => {
    const apiKey = process.env.ZITE_GEMINI_API_KEY;
    const imgRes = await fetch(input.imageUrl);
    const imgBuf = await imgRes.arrayBuffer();
    const base64 = Buffer.from(imgBuf).toString("base64");
    const mimeType = imgRes.headers.get("content-type") || "image/jpeg";
    const prompt = `Analisis gambar barang ini. Jawab dalam format berikut (teks biasa, TANPA markdown):

Kategori: (tebak kategori barang)
Merek: (tebak merek/brand)
Kondisi Fisik: (deskripsikan kondisi)
Estimasi Harga: Rp XXX.XXX - Rp XXX.XXX

Berikan kisaran harga pasar bekas di Indonesia dalam Rupiah. Jawab singkat dan langsung.`;
    const body = {
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: mimeType, data: base64 } }
        ]
      }]
    };
    const callGemini = async () => {
      const models = ["gemini-3.6-flash"];
      let lastRes = null;
      for (const model of models) {
        lastRes = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
          { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }
        );
        if (lastRes.ok) return lastRes;
        if (lastRes.status !== 429 && lastRes.status !== 503) return lastRes;
      }
      return lastRes;
    };
    const geminiRes = await callGemini();
    if (!geminiRes.ok) {
      const errText = await geminiRes.text();
      if (geminiRes.status === 429) {
        throw new Error("Kuota AI harian habis. Coba lagi besok atau upgrade ke paket berbayar di Google AI Studio.");
      }
      throw new Error(`Gemini API error: ${geminiRes.status} - ${errText}`);
    }
    const data = await geminiRes.json();
    const text = data?.candidates?.[0]?.content?.parts?.[0]?.text || "";
    let estimatedMinPrice = 0;
    let estimatedMaxPrice = 0;
    const priceMatch = text.match(/Rp\s*[\d.,]+\s*-\s*Rp\s*[\d.,]+/i);
    if (priceMatch) {
      const nums = priceMatch[0].match(/[\d.]+/g);
