  outputSchema: z.object({
    success: z.boolean(),
    winnersCount: z.number(),
    totalPointsDistributed: z.number()
  }),
  execute: async ({ input }) => {
    const challenge = await zite.challenges.findOne({ id: input.challengeId });
    if (!challenge) throw new ZiteError("Challenge not found", "NOT_FOUND");
    if (challenge.status !== "Aktif" && challenge.status !== "Selesai") {
