      query: `SELECT bh."id", bh."title", bh."status", bh."initiator", bh."partner",
                     bh."offeredItem", bh."requestedItem", bh."createdAt"
              FROM "BarterHistory" bh
              ORDER BY bh."createdAt" DESC
