        chatType: "barter",
        title: r.title || "Barter",
        status: r.status || "Menunggu",
        otherUserName: otherUser?.name || "Pengguna",
        otherUserImage: otherUser?.image ?? null,
        otherUserId,
        lastMessage: msgRows[0]?.content || "Penawaran barter dikirim",
        lastMessageAt: msgRows[0]?.sentAt || r.createdAt || null,
        itemId: null,
        itemTitle: null,
        itemPhoto: null,
        offeredItemPhoto: offeredItem?.photos?.[0]?.url || null,
        requestedItemPhoto: requestedItem?.photos?.[0]?.url || null,
        unread: barterUnreadRows[0]?.cnt || 0
