      if (!lastMsg) continue;
      const otherUserId = lastMsg.senderId === userId ? lastMsg.receiverId : lastMsg.senderId;
      const otherUser = otherUserId ? userMap.get(otherUserId) : null;
      const itemId = lastMsg.itemId || "";
      const linkPrefix = `/direct-chat?userId=${otherUserId}&itemId=${itemId}`;
      const { rows: unreadRows } = await zite.sql({
        query: `SELECT COUNT(*)::int AS cnt FROM "Notifications"
                WHERE "type" = 'Chat' AND "read" = false
                AND "recipient" @> to_jsonb(ARRAY[$1])
                AND "linkPath" LIKE $2`,
        params: [userId, `${linkPrefix}%`]
      });
      let itemTitle = "";
      let itemPhoto = null;
      if (itemId) {
        const item = await zite.items.findOne({ id: itemId, fields: ["title", "photos"] });
        if (item) {
          itemTitle = item.title || "";
          itemPhoto = item.photos?.[0]?.url || null;
        }
      }
      const msgContent = lastMsg.type === "Photo" ? "\u{1F4F7} Foto" : lastMsg.content || "";
      allChats.push({
        id: convId,
        chatType: "direct",
        title: itemTitle || "Chat",
        status: "Aktif",
        otherUserName: otherUser?.name || "Pengguna",
        otherUserImage: otherUser?.image ?? null,
        otherUserId,
        lastMessage: msgContent,
        lastMessageAt: lastMsg.sentAt ?? null,
        itemId,
        itemTitle,
        itemPhoto,
        offeredItemPhoto: null,
        requestedItemPhoto: null,
        unread: unreadRows[0]?.cnt || 0
      });
    }
    allChats.sort((a, b) => {
      const aTime = a.lastMessageAt ? new Date(a.lastMessageAt).getTime() : 0;
      const bTime = b.lastMessageAt ? new Date(b.lastMessageAt).getTime() : 0;
      return bTime - aTime;
    });
    return { chats: allChats };
  }
});

