var MIN_GIFT = 10;
var giftPoints_default = createEndpoint({
  description: "Transfer points to another user",
  authenticated: true,
  inputSchema: z.object({
    recipientUserId: z.string().describe("Email or user ID of the recipient"),
    amount: z.number().min(MIN_GIFT)
  }),
  outputSchema: z.object({
    success: z.boolean(),
    remainingPoints: z.number()
  }),
  execute: async ({ input, context }) => {
    const userId = context.user.id;
    let recipientId = input.recipientUserId;
    if (input.recipientUserId.includes("@")) {
      const { records } = await zite.auth.findAllUsers({
        filters: { email: input.recipientUserId },
        limit: 1
      });
      if (!records[0]) throw new Error("Pengguna dengan email tersebut tidak ditemukan");
      recipientId = records[0].id;
    }
    if (recipientId === userId) throw new Error("Tidak bisa transfer poin ke diri sendiri");
    const up = await zite.userPoints.findOne({ filters: { user: userId } });
    if (!up || (up.totalPoints ?? 0) < input.amount) throw new Error("Poin tidak cukup");
    let recipientPoints = await zite.userPoints.findOne({ filters: { user: recipientId } });
    if (!recipientPoints) {
      recipientPoints = await zite.userPoints.create({
        record: {
          label: "User",
          user: recipientId,
          totalPoints: 0,
          itemsUploaded: 0,
          bartersCompleted: 0,
          likesReceived: 0,
          currentBadge: "pemula"
        }
      });
    }
    const newSenderPoints = (up.totalPoints ?? 0) - input.amount;
    await zite.userPoints.update({ id: up.id, record: { totalPoints: newSenderPoints } });
    const newRecipientPoints = (recipientPoints.totalPoints ?? 0) + input.amount;
    await zite.userPoints.update({ id: recipientPoints.id, record: { totalPoints: newRecipientPoints } });
    await zite.pointHistory.create({
      record: {
        activity: `Gift Points ke pengguna lain`,
        user: userId,
        points: -input.amount,
        activityType: "gift_sent"
      }
    });
    await zite.pointHistory.create({
      record: {
        activity: `Menerima Gift Points`,
        user: recipientId,
        points: input.amount,
        activityType: "gift_received"
      }
    });
    await zite.pointRedemptions.create({
      record: {
        label: `Gift ${input.amount} MP`,
        user: userId,
        type: "gift",
        pointsSpent: input.amount,
        recipientUserId: input.recipientUserId,
        status: "used",
        item: null,
        raffleTickets: null,
        expiresAt: null
      }
    });
    await zite.notifications.create({
      record: {
        title: "\u{1F381} Kamu Menerima Gift Points!",
        body: `${context.user.firstName || context.user.email} mengirimkan ${input.amount} MP untukmu!`,
        type: "System",
        recipient: recipientId,
        read: false,
        linkPath: "/wallet"
      }
    });
    return { success: true, remainingPoints: newSenderPoints };
  }
});

