    const callerRole = callerMembership[0].role;
    const isKetua = callerRole === "Ketua";
    const isMod = callerRole === "Moderator";
    if (!isKetua && !isMod) throw new Error("Hanya Ketua atau Moderator yang bisa mengelola post");
    const post = await zite.communityPosts.findOne({ id: input.postId });
    if (!post) throw new Error("Post tidak ditemukan");
    switch (input.action) {
