        if (!isKetua) throw new Error("Hanya Ketua yang bisa menyematkan post");
        await zite.communityPosts.update({ id: input.postId, record: { pinned: true } });
        return { success: true, message: "Post berhasil disematkan" };
      }
      case "unpin": {
        if (!isKetua) throw new Error("Hanya Ketua yang bisa melepas sematan");
        await zite.communityPosts.update({ id: input.postId, record: { pinned: false } });
        return { success: true, message: "Sematan post dilepas" };
      }
      case "delete": {
        const authorId = Array.isArray(post.author) ? post.author[0] : post.author || "";
        if (isMod && !isKetua) {
          const { records: authorMembership } = await zite.communityMembers.findAll({
            filters: { community: input.communityId, user: authorId, status: "active" },
            limit: 1
          });
          if (authorMembership.length > 0 && authorMembership[0].role === "Ketua") {
            throw new Error("Moderator tidak bisa menghapus post Ketua");
          }
        }
        await zite.communityPosts.delete({ id: input.postId });
        return { success: true, message: "Post berhasil dihapus" };
      }
