var toggleWishlist_default = createEndpoint({
  description: "Toggle an item in the user wishlist (add or remove)",
  authenticated: true,
  inputSchema: z.object({
    itemId: z.string()
  }),
  outputSchema: z.object({
    saved: z.boolean()
  }),
  execute: async ({ input, context }) => {
    await enforceBan(context.user.id);
    const userId = context.user.id;
    const { records } = await zite.wishlist.findAll({
      filters: { user: userId, item: input.itemId },
      limit: 1
    });
    if (records.length > 0) {
      await zite.wishlist.delete({ id: records[0].id });
      return { saved: false };
    }
    const item = await zite.items.findOne({ id: input.itemId });
    const label = item?.title || "Item";
    await zite.wishlist.create({
      record: {
        label,
        user: userId,
        item: input.itemId
      }
    });
    return { saved: true };
  }
});

