      const batchSize = Math.min(100, totalToAdd - added);
      const records = [];
      for (let i = 0; i < batchSize; i++) {
        records.push({ follower: null, followingUserId: input.userId });
      }
      await zite.follows.bulkCreate({ records });
      added += batchSize;
    }
    return {
      success: true,
      followersAdded: input.count,
      totalFollowers: currentCount + input.count
    };
  }
});

