    const notification = await zite.notifications.create({
      record: {
        title: `\u26A0\uFE0F ${input.title}`,
        body: `${input.message}${pointsToDeduct > 0 ? ` (-${pointsToDeduct} poin)` : ""}`,
        type: "System",
        recipient: input.userId,
        read: false,
        linkPath: "/wallet"
      }
    });
    if (pointsToDeduct > 0) {
      const pointsRes = await zite.userPoints.findAll({
        filters: { user: input.userId },
        limit: 1
      });
      if (pointsRes.records.length > 0) {
        const current = pointsRes.records[0];
        await zite.userPoints.update({
          id: current.id,
          record: {
            totalPoints: Math.max(0, (current.totalPoints ?? 0) - pointsToDeduct)
