      record: {
        action: "Send Direct Warning",
        adminEmail: context.user.email,
        adminName,
        targetType: "user",
        targetId: input.userId,
        targetName: null,
        details: `Peringatan: "${input.title}" \u2014 ${input.message}. Poin dikurangi: ${pointsToDeduct}. Aksi: ${actionTaken}`
      }
    });
    return {
      success: true,
      notificationId: notification.id,
      pointsDeducted: pointsToDeduct,
      actionTaken
    };
  }
