    const logAudit = (act, details) => zite.adminAuditLog.create({
      record: { action: act, adminEmail: context.user.email, adminName, targetType: "user", targetId: userId, targetName: null, details }
    });
    const profileRes = await zite.userProfiles.findAll({ filters: { user: userId }, limit: 1 });
    const profile = profileRes.records[0];
    if (!profile) throw new Error("Profile tidak ditemukan");
    const pointsRes = await zite.userPoints.findAll({ filters: { user: userId }, limit: 1 });
    const pointsRecord = pointsRes.records[0];
    switch (action) {
      case "verifyAddress": {
        await zite.userProfiles.update({ id: profile.id, record: { addressVerified: true } });
        await zite.notifications.create({
          record: {
            title: "\u2705 Alamat Terverifikasi",
            body: "Alamat kamu telah diverifikasi oleh admin MUTARI.",
            type: "System",
            recipient: userId,
            read: false,
            linkPath: "/profile"
          }
        });
        await logAudit("Verifikasi Alamat", "Alamat user diverifikasi");
        return { success: true, message: "Alamat berhasil diverifikasi" };
      }
      case "unverifyAddress": {
        await zite.userProfiles.update({ id: profile.id, record: { addressVerified: false } });
        await logAudit("Cabut Verifikasi Alamat", "Verifikasi alamat dicabut");
        return { success: true, message: "Verifikasi alamat dicabut" };
      }
      case "verifyPhone": {
        await zite.userProfiles.update({ id: profile.id, record: { phoneVerified: true } });
        await zite.notifications.create({
          record: {
            title: "\u2705 Nomor HP Terverifikasi",
            body: "Nomor HP kamu telah diverifikasi oleh admin MUTARI.",
            type: "System",
            recipient: userId,
            read: false,
            linkPath: "/profile"
          }
        });
        await logAudit("Verifikasi HP", "Nomor HP user diverifikasi");
        return { success: true, message: "Nomor HP berhasil diverifikasi" };
      }
      case "unverifyPhone": {
        await zite.userProfiles.update({ id: profile.id, record: { phoneVerified: false } });
        await logAudit("Cabut Verifikasi HP", "Verifikasi HP dicabut");
        return { success: true, message: "Verifikasi nomor HP dicabut" };
      }
      case "adjustPoints": {
        const amount = input.pointsAmount ?? 0;
        if (amount === 0) throw new Error("Jumlah poin tidak boleh 0");
        const reason = input.pointsReason || (amount > 0 ? "Bonus admin" : "Pengurangan admin");
        if (!pointsRecord) {
          await zite.userPoints.create({
            record: {
              label: `Points-${userId.slice(0, 8)}`,
              user: userId,
              totalPoints: Math.max(0, amount),
              itemsUploaded: 0,
              bartersCompleted: 0,
              likesReceived: 0,
              currentBadge: "pemula"
            }
          });
        } else {
          const newTotal = Math.max(0, (pointsRecord.totalPoints ?? 0) + amount);
          const badge = getBadge(newTotal);
          await zite.userPoints.update({
            id: pointsRecord.id,
            record: { totalPoints: newTotal, currentBadge: badge }
          });
        }
        await zite.pointHistory.create({
          record: {
            activity: reason,
            user: userId,
            points: amount,
            activityType: "admin_adjust"
          }
        });
        await zite.notifications.create({
          record: {
            title: amount > 0 ? "\u{1F381} Bonus Poin!" : "\u26A0\uFE0F Pengurangan Poin",
            body: `${amount > 0 ? "+" : ""}${amount} poin: ${reason}`,
            type: "System",
            recipient: userId,
            read: false,
            linkPath: "/wallet"
          }
        });
        await logAudit("Adjust Poin", `${amount > 0 ? "+" : ""}${amount} poin: ${reason}`);
        return { success: true, message: `Poin berhasil ${amount > 0 ? "ditambah" : "dikurangi"} ${Math.abs(amount)}` };
      }
      case "resetBadge": {
        const targetBadge = input.badgeValue || "Pemula";
        if (!pointsRecord) throw new Error("Data poin user tidak ditemukan");
        await zite.userPoints.update({
          id: pointsRecord.id,
          record: { currentBadge: targetBadge }
        });
        await logAudit("Reset Badge", `Badge direset ke "${targetBadge}"`);
        return { success: true, message: `Badge direset ke "${targetBadge}"` };
      }
      default:
        throw new Error("Action tidak valid");
    }
  }
});
function getBadge(points) {
  if (points >= 1e4) return "elite";
  if (points >= 5e3) return "mentor";
  if (points >= 2500) return "legenda";
  if (points >= 1e3) return "profesional";
  if (points >= 500) return "terpercaya";
  if (points >= 200) return "aktif";
  return "pemula";
}

