var broadcastNotification_default = createEndpoint({
  description: "Mengirim broadcast notifikasi ke semua atau sebagian user",
  inputSchema: z.object({
    title: z.string().min(1),
    body: z.string().min(1),
    targetType: z.enum(["all", "specific"]),
    targetEmails: z.array(z.string()).optional()
  }),
  outputSchema: z.object({
    sent: z.number()
  }),
  execute: async ({ input, context }) => {
    const { title, body, targetType, targetEmails } = input;
    let userIds = [];
    if (targetType === "all") {
      const res = await zite.sql({ query: 'SELECT id FROM "ziteUsers"' });
      userIds = res.rows.map((r) => String(r.id));
    } else if (targetEmails && targetEmails.length > 0) {
      const placeholders = targetEmails.map((_, i) => `$${i + 1}`).join(", ");
      const res = await zite.sql({
        query: `SELECT id FROM "ziteUsers" WHERE "email" IN (${placeholders})`,
        params: targetEmails
      });
      userIds = res.rows.map((r) => String(r.id));
    }
    if (userIds.length === 0) return { sent: 0 };
    const records = userIds.map((uid) => ({
      title,
      body,
      type: "System",
      recipient: uid,
      read: false
    }));
    let sent = 0;
    for (let i = 0; i < records.length; i += 100) {
      const batch = records.slice(i, i + 100);
      await zite.notifications.bulkCreate({ records: batch });
      sent += batch.length;
    }
    const adminName = context.user.firstName ? `${context.user.firstName} ${context.user.lastName || ""}`.trim() : context.user.email;
    await zite.adminAuditLog.create({
      record: {
        action: "Broadcast Notifikasi",
        adminEmail: context.user.email,
        adminName,
        targetType: targetType === "all" ? "all_users" : "specific_users",
        targetId: null,
        targetName: null,
        details: `Judul: "${title}", Terkirim ke ${sent} pengguna`
      }
    });
    return { sent };
  }
});

