    reward3rd: z.number().optional(),
    participationReward: z.number().optional(),
    badge1st: z.string().optional(),
    badgeParticipant: z.string().optional(),
    inviteBonusPoints: z.number().optional(),
    maxInvites: z.number().optional(),
    visibility: z.string().optional(),
    icon: z.string().optional()
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string() }),
  async execute({ input, context }) {
    const record = {
      title: input.title,
      description: input.description ?? null,
      type: input.type,
      categoryFilter: input.categoryFilter ?? null,
      startDate: input.startDate,
      endDate: input.endDate,
      status: input.status ?? "Draft",
      minTarget: input.minTarget ?? null,
      reward1st: input.reward1st ?? null,
      reward2nd: input.reward2nd ?? null,
      reward3rd: input.reward3rd ?? null,
      participationReward: input.participationReward ?? null,
      badge1st: input.badge1st ?? null,
      badgeParticipant: input.badgeParticipant ?? null,
      inviteBonusPoints: input.inviteBonusPoints ?? null,
      maxInvites: input.maxInvites ?? null,
      visibility: input.visibility ?? "Publik",
      icon: input.icon ?? null
    };
    if (input.id) {
      await zite.challenges.update({ id: input.id, record });
      await zite.adminAuditLog.create({
        record: {
          action: "Update Challenge",
          adminEmail: context.user.email,
          adminName: context.user.firstName ?? context.user.email,
