    violationId: z.string(),
    status: z.enum(["Aktif", "Sudah Diperingatkan", "Banding", "Kedaluwarsa", "Dicabut", "Ditolak", "Menunggu Review"]),
    adminNotes: z.string().optional(),
    sanctionReporter: z.boolean().optional()
