    if (input.status !== "Aktif" && input.status !== "Ditolak" && reportedUserId) {
      const statusEmoji = input.status === "Dicabut" ? "\u2705" : input.status === "Sudah Diperingatkan" ? "\u26A0\uFE0F" : "\u{1F4CB}";
